window.SOUYUN_ALLUSIONS={"fetchedAt":"2026-09-25 13:57:29","source":"https://sou-yun.cn/AllusionsIndex.aspx?sort=People","allusions":{"0":[{"n":"吾道穷","d":"悲麟：指感叹生不逢时。唐李商隐《失题》：“斯文虚梦鸟，吾道欲悲麟。”；麟笔：指著作。宋陆游《小轩》：“麟笔残功成水品，蛇图余思入棋枰。”","s":"《春秋公羊传注疏》卷二十八〈哀公十四年〉～355～","w":"十有四年。春。西狩获麟。何以书。记异也。何异尔。非中国之兽也。然则孰狩之。薪采者也。薪采者则微者也。曷为以狩言之。大之也。曷为大之。为获麟大之也。曷为为获麟大之。麟者。仁兽也。有王者则至。无王者则不至。有以告者曰。有而角者。孔子曰。孰为来…","q":[["获麟书诸册，豢龙醢为臡。","元稹 青云驿"],["别号行鸣雁，遗编感获麟。","唐彦谦 吊方于处士二首"]]},{"n":"卑宫","d":"","s":"《论语注疏·泰伯》～73～","w":"子曰：「禹，吾无间然矣。菲饮食而致孝乎鬼神，恶衣服而致美乎黻冕，卑宫室而尽力乎沟洫。禹吾无间然矣。」","q":[["卑宫昭夏德，尊老睦尧亲。","陈子昂 奉和皇帝上礼抚事述怀应制"]]},{"n":"壁经","d":"","s":"《汉书》卷三十〈艺文志〉～706～","w":"《古文尚书》者，出孔子壁中。武帝末，鲁共王坏孔子宅，欲以广其宫，而得古文尚书及礼记、论语、孝经凡数十篇，皆古字也。唐·颜师古：「《家语》云孔腾字子襄，畏秦法峻急，藏《尚书》、《孝经》、《论语注疏》于夫子旧堂壁中，而《汉记》〈尹敏传〉云孔鲋所…","q":[["箫奏秦台里，书开鲁壁中。","宋之问 宴安乐公主宅得空字"],["孔壁采遗篆，周韦考绝编。","崔日知 冬日述怀奉呈韦祭酒张左丞兰台名贤"]]},{"n":"伯牛灾","d":"伯牛灾：指不治之症。唐王维《哭褚司马》：“谁言老龙吉，未免伯牛灾。”","s":"《论语》卷三《雍也》","w":"伯牛有疾，子问之，自牖执其手，曰：「亡之，命矣夫！斯人也而有斯疾也！斯人也而有斯疾也！」","q":[["谁言老龙吉，未免伯牛灾。","王维 哭褚司马"]]},{"n":"伯鱼","d":"","s":"《孔子家语》卷九《本姓》","w":"孔子三岁而叔梁纥卒，葬于防。至十九，娶于宋之并官氏，一岁而生伯鱼，鱼之生也，鲁昭公以鲤鱼赐孔子，荣君之贶，故因以名曰鲤，而字伯鱼，鱼年五十，先孔子卒。","q":[["露幕拥簪裾，台庭饯伯鱼。","卢纶 送浑炼归觐却赴阙庭"]]},{"n":"不火食","d":"","s":"《论语注疏·卫灵公》～37～","w":"卫灵公问陈于孔子。孔子对曰：「俎豆之事，则尝闻之矣；军旅之事，未之学也。」明日遂行。在陈绝粮，从者病，莫能兴。子路愠见曰：「君子亦有穷乎？」子曰：「君子固穷，小人穷斯滥矣。」","q":[]},{"n":"黔突","d":"","s":"《昭明文选》卷四十五〈对问设论辞序上·设论·答宾戏〉～206～","w":"「是以圣哲之治，栖栖遑遑，孔席不暖，墨突不黔。」唐·李善注：「韦昭曰：暖，温也，言坐不席也。《文子》曰：墨子无黔突，孔子无煖席，非以贪禄慕位，欲起天下之利，除万民之害也。」","q":[["早须归天阶，不得安孔席。","岑参 西蜀旅舍春叹寄朝中故人呈狄评事"],["贤有不黔突，圣有不暖席。","杜甫 发同谷县"]]},{"n":"富贵浮云","d":"","s":"《论语注疏·述而》～62～","w":"子曰：「饭疏食，饮水，曲肱而枕之，乐亦在其中矣。不义而富且贵，于我如浮云。」宋·邢炳疏：「疏食，菜食也。肱，臂也。言已饭菜食、饮水、寝则曲肱而枕之，以此为乐。不义而富且贵，于我如浮云者，富与贵虽人之所欲，若富贵而以不义者，于我如浮云，言非已…","q":[["何事退耕沧海畔，闲看富贵白云飞。","刘商 题刘偃庄"],["背恩惭皎日，不义若浮云。","崔峒 刘展下判官相招以诗答之"]]},{"n":"不踰矩","d":"","s":"《论语·为政》","w":"「子曰：『吾十有五而志于学，三十而立，四十而不惑，五十而知天命。』」三国魏·何晏《集解》：「有所立也。」","q":[["三十既成立，嗟吁命不通。","孟浩然 书怀贻京邑同好"],["三十名未立，君还惜寸阴。","綦毋潜 送章彝下第"]]},{"n":"老之将至","d":"","s":"《论语·述而》","w":"叶公问孔子于子路，子路不对。子曰：「女奚不曰，其为人也，发愤忘食，乐以忘忧，不知老之将至云尔。」","q":[["不知老将至，犹自放诗狂。","白居易 洛中偶作"]]},{"n":"偃草","d":"","s":"《论语·颜渊》","w":"季康子问政于孔子，曰：「如杀无道，以就有道，何如？」孔子对曰：「子为政，焉用杀？」子欲善而民善矣。君子之德风，小人之德草。草上之风，必偃。","q":[["风变市儿惊偃草，雨晴郊薮谬随车。","李绅 拜三川守"],["草木承风偃，云雷施泽均。","卢纶 寄赠库部王郎中"]]},{"n":"长沮桀溺","d":"","s":"《论语注疏·微子》～65～","w":"长沮、桀溺耦而耕，孔子过之，使子路问津焉。长沮曰：「夫执舆者为谁？」子路曰：「为孔丘。」曰：「是鲁孔丘与？」曰：「是也。」曰：「是知津矣。」问于桀溺，桀溺曰：「子为谁？」曰：「为仲由。」曰：「是鲁孔丘之徒与？」对曰：「然。」曰：「滔滔者天下…","q":[["从他烟棹更南去，休向津头问去程。","司空图 淅上（作江淅上是今郧阳府地在秦楚之交故有秦云楚两之句）"],["苦作南行约，劳生始问津。","周贺 赠皎然上人（一本无皎字）"]]},{"n":"捧心颦","d":"丑女效颦：指丑陋而强学美好之人。唐李白《古风五十九首》之三十五：“丑女来效颦，还家惊四邻。”；捧心：喻指仿效弄巧成拙，或喻美女病态。唐”柳宗元《重赠二首》之二：“世世悠悠不识真，姜芽尽是捧心人。’”","s":"《庄子集释》卷五下〈外篇·天运〉～5～","w":"孔子西游于卫。颜渊问师金曰：「以夫子之行为奚如？」师金曰：「惜乎，而夫子其穷哉！」颜渊曰：「何也？」师金曰：「夫刍狗之未陈也，盛以箧衍，巾以文绣，尸祝齐戒以将之。及其已陈也，行者践其首脊，苏者取而爨之而已；将复取而盛以箧衍，巾以文绣，游居寝…","q":[["翻惭效颦者，却笑从人迟。","于濆 拟古意"],["丑女来效颦，还家惊四邻。","李白 古风之三十五"]]},{"n":"嘲宰予","d":"","s":"《论语·公冶长》","w":"宰予昼寝，子曰：「朽木不可雕也，粪土之墙不可圬也；于予与何诛？」","q":[["筠桂晚萧疏，任人嘲宰予。","李群玉 昼寝"]]},{"n":"乘桴浮于海","d":"","s":"《论语注疏·公冶长》～42～","w":"子曰：「道不行，乘桴浮于海，从我者，其由与？」子路闻之喜。子曰：「由也，好勇过我，无所取材。」","q":[["绝迹思浮海，修书懒寄秦。","吴融 荆州寓居书怀"],["吾当海上去，且学乘桴翁。","岑参 东归发犍为至泥溪舟中作"]]},{"n":"咏而归","d":"","s":"《论语注疏·先进》～00～","w":"子路、曾皙、冉有、公西华侍坐。子曰：「以吾一日长乎尔，毋吾以也。居则曰：『不吾知也！』如或知尔，则何以哉？」子路率尔而对曰：「千乘之国，摄乎大国之间，加之以师旅，因之以饥馑；由也为之，比及三年，可使有勇，且知方也。」夫子哂之。「求！尔何如？…","q":[["白雪调歌响，清风乐舞雩。","温庭筠 病中书怀呈友人"]]},{"n":"衰凤","d":"接舆狂：咏隐士或狂者。五代前蜀韦庄《和郑拾遗秋日感事一百韵》：“世随渔父醉，身效接舆狂。”","s":"《论语注疏·微子》～65～","w":"楚狂接舆歌而过孔子，曰：「凤兮凤兮，何德之衰。往者不可谏，来者犹可追。已而已而，今之从政者殆而！」孔子下，欲与之言，趋而辟之，不得与之言。","q":[["狂歌问夫子，夫子莫能陈。","储光羲 同王十三维偶然作十首"],["莫学楚狂隳姓字，知音还有子期听。","元孚 送李四校书"]]},{"n":"逝者如斯","d":"","s":"《论语注疏·子罕》～80～","w":"子在川上曰：「逝者如斯夫，不舍昼夜。」","q":[["西沉浮世日，东注逝川波。","于武陵 感情"],["昔为昼锦游，今成逝川路。","储光羲 陆著作挽歌"]]},{"n":"三缄","d":"","s":"《说苑》卷十〈敬慎〉～337～","w":"孔子之周，观于太庙右陛之前，有金人焉，三缄其口而铭其背曰：「古之慎言人也，戒之哉！戒之哉！无多言，多口多败；无多事，多事多患。安乐必戒，无行所悔。勿谓何伤，其祸将长；勿谓何害，其祸将大；勿谓何残，其祸将然；勿谓莫闻，天妖伺人；荧荧不灭，炎炎…","q":[["馀生愿依止，文字欲三缄。","严维 送桃岩成上人归本寺"],["因思周庙当时诫，金口三缄示后昆。","徐夤 上卢三拾遗以言见黜"]]},{"n":"数仞墙","d":"夫子墙：指道德学问高深莫测。唐钱起《寻司助李郎中不遇》：“重花不隔陈善榻，修竹能深夫子墙。”","s":"《论语注疏·子张》～73～","w":"叔孙武叔语大夫于朝，曰：「子贡贤于仲尼。」子服景伯以告子贡。子贡曰：「譬之宫墙，赐之墙也及肩，窥见室家之好。夫子之墙数仞，不得其门而入，不见宗庙之美，百官之富。得其门者或寡矣，夫子之云，不亦宜乎。」","q":[["夫子墙还峻，酂侯宅过谦。","姚合 和座主相公西亭秋日即事"],["丘墙高莫比，萧宅僻还清。","姚合 和裴令公新成绿野堂即事"]]},{"n":"荣期乐","d":"","s":"《列子集释》卷一〈天瑞篇〉～22～","w":"孔子游于太山，见荣启期行乎郕之野，鹿裘带索，鼓琴而歌。孔子问曰：「先生所以乐，何也？」对曰：「吾乐甚多：天生万物，唯人为贵。而吾得为人，是一乐也。男女之别，男尊女卑，故以男为贵；吾既得为男矣，是二乐也。人生有不见日月、不免襁褓者，吾既己行年…","q":[]},{"n":"聃丘","d":"","s":"《史记》卷四十七〈孔子世家〉～905～","w":"孔子生鲁昌平乡陬邑。其先宋人也，曰孔防叔。防叔生伯夏，伯夏生叔梁纥。纥与颜氏女野合而生孔子，祷于尼丘得孔子。鲁襄公二十二年而孔子生。生而首上圩顶，故因名曰丘云。字仲尼，姓孔氏。","q":[]},{"n":"颜巷","d":"颜回：指有修养、能安于贫困生活的贤才。唐王绩《被召谢病》：“颜回唯乐道，原宪岂伤贫。”","s":"《史记》卷六十七〈仲尼弟子列传〉～288～","w":"颜回者，鲁人也，字子渊。少孔子三十岁。颜渊问仁，孔子曰：「克己复礼，天下归仁焉。」 孔子曰：「贤哉回也！一箪食，一瓢饮，在陋巷，人不堪其忧，回也不改其乐。」「回也如愚；退而省其私，亦足以发，回也不愚。」「用之则行，舍之则藏，唯我与尔有是夫！…","q":[["陋巷满蓬蒿，谁知有颜子。","于濆 秦富人"],["春草秋风老此身，一瓢长醉任家贫。","刘商 醉后"]]},{"n":"盗泉","d":"盗泉：喻恶势力，或表示不义之物。唐李白《赠宣城宇文太守兼呈崔诗御》：“回车避朝歌，掩口去盗泉。”","s":"《水经注》卷二十五《洙水》","w":"洙水西南流，盗泉水注之，泉出卞城东北，卞山之阴。《尸子》曰：「孔子至于胜母，暮矣而不宿；过于盗泉，渴矣而不饮；恶其名也。」故《论语撰考谶》曰：「水名盗泉，仲尼不漱，即斯泉矣。」","q":[["莫饮盗泉水，无为天下先。","李咸用 遣怀"],["回车避朝歌，掩口去盗泉。","李白 赠宣城宇文太守兼呈崔侍御"]]},{"n":"德邻","d":"","s":"《论语·里仁》","w":"子曰：「德不孤，必有邻。」","q":[["独步才超古，馀波德照邻。","杜甫 上韦左相二十韵"],["扫洒潭中月，他时望德邻。","独孤及 答李滁州忆玉潭新居见寄"]]},{"n":"奠楹","d":"","s":"《礼记注疏》卷七〈檀弓〉～30～","w":"孔子蚤作。负手曳杖。消摇于门。歌曰。泰山其颓乎。梁木其坏乎。哲人其萎乎。既歌而入。当户而坐。子贡闻之。曰。泰山其颓。则吾将安仰梁木其坏。哲人其萎则吾将安放。夫子殆将病也。遂趋而入。夫子曰。赐。尔来何迟也。夏后氏殡于东阶之上。则犹在阼也。殷人…","q":[["今看两楹奠，当与梦时同。","李隆基 经邹鲁祭孔子而叹之"],["两楹凄已合，九仞杳难分。","王起 贡举人谒先师闻雅乐"]]},{"n":"东家邱","d":"东家丘：喻指圣贤未被世人认识。唐李白《送薛九被谗去鲁》：“宋人不辨玉，鲁贱东家丘。”","s":"《昭明文选》卷四十一〈书上·为曹洪与魏文帝书〉","w":"「盖闻过高唐者，效王豹之讴；游睢涣者，学藻缋之䌽。间自入益部，仰司马杨王遗风，有子胜斐然之志，故颇奋文辞，异于他日。怪乃轻其家丘，谓为倩人，是何言欤？ 」唐·张诜注：「鲁人不识孔子圣人，乃云：『我东家丘者，吾知之矣。』言轻孔丘也。」","q":[["知己欲依何水部，乡人今正贱东丘。","严维 余姚祗役奉简鲍参军"],["宋人不辨玉，鲁贱东家丘。","李白 送薛九被谗去鲁"]]},{"n":"畏后生","d":"","s":"《论语注疏·子罕》～80～","w":"子曰：「后生可畏，焉知来者之不如今也？四十、五十而无闻焉，斯亦不足畏也已。」","q":[["宣父犹能畏后生，丈夫未可轻年少。","李白 上李邕"]]},{"n":"东西南北人","d":"","s":"《礼记注疏》卷六〈檀弓上〉～2～","w":"孔子既得合葬于防，曰：「吾闻之，古也墓而不坟。今丘也，东西南北之人也，不可以弗识也。」于是封之，崇四尺。孔子先反，门人后。雨甚至，孔子问焉，曰：「尔来何迟也。」曰：「防墓崩。」孔子不应。三，孔子泫然流涕曰：「吾闻之，古不脩墓。」","q":[["东西南北人，高迹自相亲。","李频 过四皓庙"],["甫也南北人，芜蔓少耘锄。","杜甫 谒文公上方"]]},{"n":"吾衰矣","d":"","s":"《论语·述而》～60～","w":"子曰：「甚矣，吾衰也！久矣，吾不复梦见周公！」","q":[["凄其望吕葛，不复梦周孔。","杜甫 晚登瀼上堂"]]},{"n":"斗筲","d":"","s":"《论语·子路》","w":"曰：「今之从政者何如？」子曰：「噫！斗筲之人，何足算也。」","q":[["薄躯信无庸，琐屑剧斗筲。","柳宗元 游朝阳岩遂登西亭二十韵"],["从此居方丈，终非竞斗筲。","皮日休 新秋言怀寄鲁望三十韵"]]},{"n":"对山林哀乐未忘怀","d":"","s":"《庄子集释》卷七下〈外篇·知北游〉～765～","w":"仲尼曰：「古之人，外化而内不化，今之人，内化而外不化。与物化者，一不化者也。安化安不化，安与之相靡，必与之莫多。狶韦氏之囿，黄帝之圃，有虞氏之宫，汤武之室。君子之人，若儒墨者师，故以是非相●也，而况今之人乎！圣人处物不伤物。不伤物者，物亦不…","q":[]},{"n":"对欹器","d":"","s":"《荀子·宥坐》","w":"「孔子观于鲁桓公之庙，有欹器焉。弟子挹水而注之，中而正，满而覆，虚而欹。孔子喟然而叹曰：『吁！恶有满而不覆者哉！』」唐·杨倞注：「宥与右同，言人君可置于坐右以为戒也。」","q":[["器满自当敧，物盈终有缺。","李德裕 怀山居邀松阳子同作"],["就学缉韦编，铭心对欹器。","权德舆 郊居岁暮因书所怀"]]},{"n":"耳顺","d":"","s":"《论语·为政》","w":"子曰：「吾十有五而志于学，此孔子立志之关键也。故三十而立，则其理凝。四十而不惑，则其理通。五十而知天命，则其理贯。六十而耳顺，则其理彻。七十而从心所欲，不踰矩。」宋。邢炳疏：「顺。不逆也。耳闻其言则知其微旨而不逆也。」","q":[["吟君新什慰蹉跎，屈指同登耳顺科。","刘禹锡 和乐天耳顺吟兼寄敦诗"],["耳顺何为土木勤，叔孙墙屋有前闻。","徐夤 新屋"]]},{"n":"伐树","d":"","s":"《史记》卷四十七《孔子世家》","w":"孔子去曹适宋，与弟子习礼大树下。宋司马桓魋欲杀孔子，拔其树。孔子去。弟子曰：「可以速矣。」孔子曰：「天生德于予，桓魋其如予何！」","q":[["忆昔鲁仲尼，凄凄此经过。众人不可向，伐树将如何。","高适 宋中十首"]]},{"n":"学樊迟","d":"","s":"《论语注疏·子路》～6～","w":"樊迟请学稼，子曰：「吾不如老农。」请学为圃。曰：「吾不如老圃。」樊迟出。子曰：「小人哉，樊须也！上好礼，则民莫敢不敬；上好义，则民莫敢不服；上好信，则民莫敢不用情。夫如是，则四方之民襁负其子而至矣，焉用稼？」","q":[["灌园输井税，学稼奉晨昏。","权德舆 暮春闲居示同志"],["学稼功还弃，论边事亦沉。","卢纶 酬李端长安寓居偶咏见寄"]]},{"n":"缝掖","d":"","s":"《礼记·儒行》","w":"「丘少居鲁。衣逢掖之衣。」东汉·郑玄注：「逢犹大也，大掖之衣，大袂襌衣也，此君子有道艺者所衣也。」","q":[["腐儒著缝掖，何处议邹鲁。","独孤及 季冬自嵩山赴洛道中作"],["往年脱缝掖，接武仕关西。","独孤及 江宁酬郑县刘少府兄赠别作"]]},{"n":"仲尼执鞭","d":"","s":"《论语·述而》","w":"「子曰：『富而可求也，虽执鞭之士，吾亦为之。如不可求，从吾所好。』」","q":[["执鞭慕夫子，捧檄怀毛公。","孟浩然 书怀贻京邑同好"],["化佛示持帚，仲尼称执鞭。","顾况 归阳萧寺有丁行者能修无生忍担水施僧况归命稽首作诗"]]},{"n":"附骥尾","d":"","s":"《史记》卷六十一《伯夷列传》","w":"「颜渊虽笃学，附骥尾而行益显。」唐·司马贞《史记索隐》：「苍蝇附骥尾而致千里，以譬颜回因孔子而名彰也。」","q":[["千里江山陪骥尾，五更风水失龙鳞。","张曙 下第戏状元崔昭纬"],["若向云衢陪骥尾，直须天畔落旄头。","李咸用 和彭进士感怀"]]},{"n":"负米归","d":"负米：喻奉养父母，或喻为奉养父母而在外谋求禄米。唐杜甫《八哀诗·故秘书少监武功苏公源明》：“负米晚为身，每食脸必泫。”","s":"《孔子家语》卷二《致思》","w":"「子路见于孔子曰：『负重涉远，不择地而休，家贫亲老，不择禄而仕。昔者由也，事二亲之时，常食藜藿之实，为亲负米百里之外。亲殁之后，南游于楚，从车百乘，积粟万钟，累茵而坐，列鼎而食，愿欲食藜藿，为亲负米，不可复得也。枯鱼衔索，几何不蠹，二亲之寿…","q":[["负米晚为身，每食脸必泫。","杜甫 八哀诗（并序）故秘书少监武功苏公源明"],["负米力葵外，读书秋树根。","杜甫 孟氏（集有过孟十二仓曹十四主簿兄弟诗）"]]},{"n":"赋归欤","d":"","s":"《论语注疏·公冶长》～45～","w":"子在陈曰：「归与！归与！吾党之小子狂简，斐然成章，不知所以裁之。」","q":[]},{"n":"肝胆成楚越","d":"","s":"《庄子集释》卷二下〈内篇·德充符〉～87～","w":"鲁有兀者王骀，从之游者与仲尼相若。常季问于仲尼曰：「王骀，兀者也，从之游者与夫子中分鲁。立不教，坐不议，虚而往，实而归。固有不言之教，无形而心成者邪？是何人也？」仲尼曰：「夫子，圣人也，丘也直后而未往耳。丘将以为师，而况不若丘者乎！奚假鲁国…","q":[]},{"n":"蓍簪","d":"蓍簪：喻不忘故人、旧物。五代前蜀韦庄《同旧韵》：“既闻留缟带，讵肯掷蓍簪？”","s":"《韩诗外传》卷九","w":"孔子出游少源之野。有妇人中泽而哭，其音甚哀。孔子使弟子问焉，曰：「夫人何哭之哀？」妇人曰：「乡者、刈蓍薪，亡吾蓍簪，吾是以哀也。」弟子曰：「刈蓍薪而亡蓍簪，有何悲焉！」妇人曰：「非伤亡簪也，盖不忘故也。」","q":[["人生感故物，慷慨有馀悲。","杜甫 水槛"],["折简能荣瘁，遗簪莫弃捐。","温庭筠 感旧陈情五十韵献淮南李仆射"]]},{"n":"试牛刀","d":"弦歌：喻出任邑令。唐秦韬玉《送友人罢举除南陵令》：“共言愁是酌离杯，况值弦歌枉大才。”；武城弦：咏重视礼乐教化。唐卢照邻《于时春也慨然有江湖之思寄赠柳九陇卜“遥闻彭泽宰，高弄武城弦。”","s":"《论语注疏·阳货》～54～","w":"子之武城，闻弦歌之声。夫子莞尔而笑，曰：「割鸡焉用牛刀？」子游对曰：「昔者偃也闻诸夫子曰：『君子学道则爱人，小人学道则易使也。』」子曰：「二三子！偃之言是也。前言戏之耳。」","q":[["朝来仙阁听弦歌，暝入花亭见绮罗。","储光羲 同武平一员外游湖五首时武贬金坛令"],["闲逐维私向武城，北风青雀片时行。","刘言史 送人随姊夫任云安令"]]},{"n":"拱北辰","d":"","s":"《论语注疏·为政》～6～","w":"子曰：「为政以德，譬如北辰，居其所而众星共之。」","q":[["相印昔辞东阁去，将星还拱北辰来。","刘禹锡 和令狐相公初归京国赋诗言怀"],["护塞无南牧，驰心拱北辰。","刘禹锡 许给事见示哭工部刘尚书诗因命同作"]]},{"n":"孤凤","d":"","s":"《论语注疏·微子》～65～","w":"楚狂接舆歌而过孔子曰：「凤兮！凤兮！何德之衰？往者不可谏，来者犹可追。已而，已而！今之从政者殆而！」孔子下，欲与之言。趋而辟之，不得与之言。","q":[["溟海皆震荡，孤凤其如何。","陈子昂 感遇诗三十八首"]]},{"n":"固穷","d":"","s":"《论语注疏·卫灵公》～37～","w":"明日遂行，在陈绝粮，从者病，莫能兴。子路愠见曰：「君子亦有穷乎？」子曰：「君子固穷，小人穷斯滥矣。」","q":[["自乐固穷心，天意在何处。","于濆 富农诗"],["道家贵至柔，儒生何固穷。","张九龄 杂诗五首"]]},{"n":"龟山蔽鲁","d":"","s":"《乐府诗集》卷五十八《龟山操》","w":"题解引东汉·蔡邕《琴操》云，《龟山操》孔子作。季桓子受齐女乐，孔子欲谏不得，退而望鲁龟山，作此曲，喻季氏若龟山之蔽鲁。","q":[["龟山蔽鲁国，有斧且无柯。","李白 纪南陵题五松山"]]},{"n":"鲤庭","d":"鲤庭：喻指晚辈受师长教育。唐刘禹锡《酬郑州权舍人见寄》：“鲤庭传事业，鸡树遂翱翔。”","s":"《论语注疏·季氏》～50～","w":"陈亢问于伯鱼曰：「子亦有异闻乎？」对曰：「未也。尝独立，鲤趋而过庭。曰：『学诗乎？』对曰：『未也。』『不学诗，无以言。』鲤退而学诗。他日又独立，鲤趋而过庭。曰：『学礼乎？』对曰：『未也。』『不学礼，无以立。』鲤退而学礼。闻斯二者。」陈亢退而…","q":[["鲤庭传事业，鸡树遂翱翔。","刘禹锡 酬郑州权舍人见寄十二韵"],["谁比趋庭恋，骊珠耀䌽衣。","姚鹄 送李潜归绵州觐省"]]},{"n":"岁寒心","d":"","s":"《论语·子罕》","w":"子曰：「岁寒，然后知松柏之后彫也。」三国魏·何晏集解：「大寒之岁，众木皆死，然后知松柏小彫伤，平岁则众木亦有不死者，故须岁寒而后别之。喻凡人处治世亦能自脩整，与君子同在浊世，然后知君子之正不苟容。」","q":[["多为势利朋，少有岁寒操。","李咸用 古意论交"],["少见岁寒后，免为霜雪尘。","李咸用 论交"]]},{"n":"罕言命","d":"","s":"《论语·子罕》","w":"子罕言利，与命与仁。","q":[["吾师罕言命，感激潜伤思。","鲍溶 秋思"]]},{"n":"号三匝","d":"","s":"《礼记·檀弓下》","w":"「延陵季子适齐。于其反也，其长子死。葬于赢博之间。孔子曰：『延陵季子，吴之习于礼者也。往而观其葬焉，其坎深不至于泉，其敛以时服，既葬而封，广轮掩坎，其高可隐也。既封，左袒，右还其封，且号者三，曰：『骨肉归复于土，命也，若魂气则无不之也，无不…","q":[["绕坟不暇号三匝，设祭惟闻饭一盘。","韩愈 去岁自刑部侍郎以罪贬潮州刺史乘驿赴任（一作之官）其后家亦遣逐小女道死殡之层峰驿旁（一作之）山下蒙恩还朝（一作今）过其墓留题驿梁"]]},{"n":"何为是栖栖者","d":"","s":"《论语注疏·宪问》～29～","w":"微生亩谓孔子曰：「丘何为是栖栖者与？无乃为佞乎？」孔子曰：「非敢为佞也，疾固也。」","q":[]},{"n":"瑚琏才","d":"","s":"《论语·公冶长》","w":"「子贡问曰：『赐也何如？』子曰：『女，器也。』曰：『何器也。』曰：『瑚琏也。』《集解》引包咸曰：「瑚琏，黍稷之器，夏曰瑚，殷曰琏，周曰簠簋。宗庙之器贵者。」","q":[["郑公瑚琏器，华岳金天晶。","杜甫 八哀诗赠左仆射郑国公严公武"],["嶷嶷瑚琏器，阴阴桃李蹊。","杜甫 水宿遣兴奉呈群公"]]},{"n":"瓠瓜不食","d":"","s":"《论语·阳货》","w":"佛肸召，子欲往。子路曰：「昔者由也闻诸夫子曰：亲于其身为不善者，君子不入也。佛肸以中牟畔，子之往也，如之何？」子曰：「然有是言也，不曰坚乎磨而不磷，不曰白乎涅而不缁。吾岂匏瓜也哉？焉能系而不食？」","q":[["虽异匏瓜难不食，大都食足早宜休。","白居易 感兴二首之一"],["坚辞羽葆与吹铙，翻向天涯困系匏。","韩偓 有感"]]},{"n":"黄口为人罗","d":"","s":"《孔子家语》卷四《六本》","w":"孔子见罗雀者所得，皆黄口小雀。夫子问之曰：「大雀独不得，何也？」罗者曰：「大雀善惊而难得，黄口贪食而易得。黄口从大雀则不得，大雀从黄口亦不得。」孔子顾谓弟子曰：「善惊以远害，利食而忘患，自其心矣，而以所从为祸福。故君子慎其所从，以长者之虑，…","q":[["黄口为人罗，白龙乃鱼服。得罪岂怨天，以愚陷网目。","李白 流夜郎半道承恩放还兼欣剋复之美书怀示息秀才"]]},{"n":"潢潦无源","d":"","s":"《孟子》卷八上《离娄下》","w":"徐子曰：「仲尼亟称于水，曰：『水哉水哉！』何取于水也？」孟子曰：「源泉混混，不舍昼夜，盈科而后进，放乎四海，有本者如是，是之取尔，苟为无本，七八月之间雨集，沟浍皆盈，其涸也，可立而待也，故声闻过情，君子耻之。」","q":[["潢潦无根源，朝满夕已除。","韩愈 符读书城南"]]},{"n":"回夭折","d":"","s":"《史记》卷六十七《仲尼弟子列传》","w":"回年二十九，发尽白，蚤死。孔子哭之恸，曰：「自吾有回，门人益亲。」鲁哀公问：「弟子孰为好学？」孔子对曰：「有颜回者好学，不迁怒，不贰过。不幸短命死矣，今也则亡。」","q":[["回也实夭折，贾生亦脆促。","徐彦伯 题东山子李适碑阴二首"]]},{"n":"回愚","d":"","s":"《论语·为政》","w":"「子曰：『吾与回言终日，不违，如愚。退而省其私，亦足以发，回也不愚。』」","q":[["礼数全优知隗始，讨论常见念回愚。","杜牧 送王侍御赴夏口座主幕"]]},{"n":"毁仲尼","d":"","s":"《论语》卷十《子张》","w":"叔孙武叔毁仲尼。子贡曰：「无以为也，仲尼不可毁也。」","q":[["无国要孟子，有人毁仲尼。","杜牧 杜秋娘诗"]]},{"n":"讳穷","d":"","s":"《庄子集释》卷六下〈外篇·秋水〉～595～","w":"孔子游于匡，宋人围之数匝，而弦歌不惙。子路入见，曰：「何夫子之娱也？」孔子曰：「来！吾语女。我讳穷久矣，而不免，命也；求通久矣，而不得，时也。当尧、舜而天下无穷人，非知得也，桀，纣而天下无通人，非知失也，时势适然。夫水行不避蛟龙者，渔父之勇…","q":[]},{"n":"祸起萧墙","d":"","s":"《论语·季氏》","w":"「季氏将伐颛臾，冉有季路见于孔子，曰：『季氏将有事于颛臾。』孔子曰：『求，无乃尔是过与，夫颛臾，昔者先王以为东蒙主，且在邦域之中矣，是社稷之臣也。何以伐为？』冉有曰：『夫子欲之，吾二臣者皆不欲也。』孔子曰：『求，周任有言曰：「陈力就列，不能…","q":[["祸稔萧墙终不知，生人力屈尽边陲。","储嗣宗 长安怀古"],["一朝祸起萧墙内，渭水咸阳不复都。","王翰 饮马长城窟行"]]},{"n":"绝编","d":"韦编：指书籍或发奋读书。唐权德舆《郊居岁暮因书所怀》：“就学缉韦编，铭心对欹器。”","s":"《史记》卷四十七〈孔子世家〉～937～","w":"孔子晚而喜《易》，〈序彖〉、〈系〉、〈象〉、〈说卦〉、〈文言〉。读《易》，韦编三绝。曰：「假我数年，若是，我于易则彬彬矣。」","q":[["还伤知候客，花景对韦编。","周弘亮 除夜书情"],["孔壁采遗篆，周韦考绝编。","崔日知 冬日述怀奉呈韦祭酒张左丞兰台名贤"]]},{"n":"君子墓","d":"","s":"《礼记·檀弓下》","w":"「延陵季子适齐。于其反也，其长子死。葬于赢博之间。孔子曰：『延陵季子，吴之习于礼者也。往而观其葬焉，其坎深不至于泉，其敛以时服，既葬而封，广轮掩坎，其高可隐也。既封，左袒，右还其封，且号者三，曰：『骨肉归复于土，命也，若魂气则无不之也，无不…","q":[["延陵今葬子，空使鲁人观。","司空曙 哭王注"],["有吴君子墓，返葬故山遥。","窦牟 故秘监丹阳郡公延陵包公挽歌"]]},{"n":"孔父伤时","d":"","s":"《论语·子罕》","w":"子曰：「凤鸟不至，河不出图，吾已矣夫！」","q":[["伤时愧孔父，去国同王粲。","杜甫 通泉驿南去通泉县十五里山水作"]]},{"n":"孔墨","d":"","s":"《韩非子》卷十九〈显学〉～080～","w":"世之显学，儒、墨也。儒之所至，孔丘也。墨之所至，墨翟也。自孔子之死也，有子张之儒，有子思之儒，有颜氏之儒，有孟氏之儒，有漆雕氏之儒，有仲良氏之儒，有孙氏之儒，有乐正氏之儒。自墨子之死也，有相里氏之墨，有相夫氏之墨，有邓陵氏之墨。故孔、墨之后…","q":[["不能师孔墨，何事问长沮。","王维 赠东岳焦鍊师"]]},{"n":"孔丘","d":"","s":"《史记》卷四十七《孔子世家》","w":"鲁襄公二十二年而孔子生。生而首上圩顶，故因名曰丘云。字仲尼，姓孔氏。……孔子贫且贱。及长，尝为季氏史，料量平；尝为司职吏而畜蕃息。由是为司空。已而去鲁，斥乎齐，逐乎宋、卫，困于陈蔡之閒，于是反鲁。孔子长九尺有六寸，人皆谓之「长人」而异之。鲁…","q":[["孔丘贵仁义，老氏好无为。","储光羲 同王十三维偶然作十首"],["卒卒周姬旦，栖栖鲁孔丘。","刘希夷 故园置酒"]]},{"n":"孔颜","d":"","s":"《昭明文选》卷二十八〈诗戊·乐府下·乐府十七首·日出东南隅行〉～32～","w":"天道夷且简，人道崄而难。休咎相乘蹑，翻覆若波澜。去疾苦不远，疑似实生患。近火固宜热，履冰岂恶寒。掇蜂灭天道，拾尘惑孔颜。逐臣尚何有，弃友焉足叹。福钟恒有兆，祸集非无端。天损未易辞，人益犹可欢。朗鉴岂远假，取之在倾冠。近情苦自信，君子防未然。","q":[]},{"n":"孔颜遗旨","d":"","s":"《论语注疏·季氏》～49～","w":"孔子曰：「见善如不及，见不善如探汤。吾见其人矣，吾闻其语矣。隐居以求其志，行义以达其道。吾闻其语矣，未见其人也。」","q":[]},{"n":"孔子厄陈","d":"","s":"《史记》卷四十七〈孔子世家〉～930～","w":"孔子迁于蔡三岁，吴伐陈。楚救陈，军于城父。闻孔子在陈蔡之閒，楚使人聘孔子。孔子将往拜礼，陈蔡大夫谋曰：「孔子贤者，所刺讥皆中诸侯之疾。今者久留陈蔡之閒，诸大夫所设行皆非仲尼之意。今楚，大国也，来聘孔子。孔子用于楚，则陈蔡用事大夫危矣。」于是…","q":[]},{"n":"孔子思周","d":"","s":"《论语注疏·八佾》～28～","w":"子曰：「周监于二代，郁郁乎文哉！吾从周。」","q":[]},{"n":"哭寝门","d":"","s":"《礼记·檀弓上》","w":"伯高死于卫，赴于孔子。孔子曰：「吾恶乎哭诸？兄弟，吾哭诸庙；父之友，吾哭诸庙门之外；师，吾哭诸寝；朋友，吾哭诸寝门之外。」","q":[["十年同在平原客，更遣何人哭寝门。","孟郊 哭李丹员外并寄杜中丞"],["平生风义兼师友，不敢同君哭寝门。","李商隐 哭刘蕡"]]},{"n":"狂狷","d":"","s":"《论语·子路》","w":"「子曰：『不得中行而与之，必也狂狷乎！狂者进取，狷者有所不为也。』」三国魏·何晏《集解》引包咸曰：「狂者进取于善道，狷者守节无为。」宋·邢炳注：「狂者进取于善道，知进而不知退；狷者守节无为，应进而退也。」","q":[["小生奏狂狷，感惕增万状。","孟郊 吊元鲁山"],["徒言奏狂狷，讵敢忘筌蹄。","孟郊 与王二十一员外涯游枋口柳溪"]]},{"n":"斯文未丧","d":"","s":"《论语注疏·子罕》～77～","w":"子畏于匡，曰：「文王既没，文不在兹乎？天之将丧斯文也，后死者，不得与于斯文也；天之未丧斯文也，匡人其如予何？」","q":[["寻疑天意丧斯文，故选茅峰寄白云。","张贲 酬袭美先见寄倒来韵"],["天畏斯文坠，凭君助素风。","李咸用 九江和人赠陈生"]]},{"n":"彭寿","d":"","s":"《论语·述而》","w":"述而不作，信而好古，窃比我于老彭。","q":[["自言混沌凿不死，大笑老彭非久视。","李咸用 临川逢陈百年"],["自是依刘表，安能比老彭。","李商隐 五言述德抒情诗一首四十韵献上杜七兄仆射相公"]]},{"n":"老子犹龙","d":"","s":"《史记》卷六十三〈老子韩非列传·老子〉～239～","w":"老子者，楚苦县厉乡曲仁里人也，姓李氏，名耳，字聃，周守藏室之史也。孔子适周，将问礼于老子。老子曰：「子所言者，其人与骨皆已朽矣，独其言在耳。且君子得其时则驾，不得其时则蓬累而行。吾闻之，良贾深藏若虚，君子盛德容貌若愚。去子之骄气与多欲，态色…","q":[]},{"n":"乐极悲来","d":"","s":"《淮南子》卷十二《道应训》","w":"（子贡）曰：「何谓益而损之？」（孔子）曰：「夫物盛而衰，乐极则悲，日中而移，月盈而亏。是故聪明睿智，守之以愚。」","q":[["君不见西施绿珠颜色可倾国，乐极悲来留不得。","贯休 偶作五首之五"]]},{"n":"藜不糁","d":"","s":"《庄子》杂篇·卷九下《让王》","w":"孔子穷于陈蔡之间，七日不火食，藜羹不糁，颜色甚惫，而弦歌于室。","q":[["童稚频书札，盘餐讵糁藜。","杜甫 水宿遣兴奉呈群公"],["吾安藜不糁，汝贵玉为琛。","杜甫 风疾舟中优枕书怀三十六韵奉呈湖南亲友"]]},{"n":"练光乱马","d":"","s":"东汉·王充《论衡》卷四《书虚》","w":"传书或言：颜渊与孔子俱上鲁太山，孔子东南望，吴阊门外有系白马，引颜渊指以示之，曰：「若见吴昌门乎？」颜渊曰：「见之。」孔子曰：「门外何有？」曰：「有如系练之状。」","q":[["练光摇乱马，剑气上连牛。","骆宾王 久客临海有怀"]]},{"n":"磷缁","d":"","s":"《论语》卷九《阳货》","w":"不曰坚乎，磨而不磷；不曰白乎，涅而不缁。","q":[["如何久磨砺，但取不磷缁。","杜甫 别崔潩因寄薛据孟云卿"],["岁阳初盛动，王化久磷缁。","杜甫 暮冬送苏四郎徯兵曹适桂州"]]},{"n":"灵府","d":"","s":"《庄子》内篇·卷二下《德充符》","w":"「仲尼曰：『死生存亡，穷达贫富，贤与不肖毁誉，饥渴寒暑，是事之变，命之行也；日夜相代乎前，而知不能规乎其始者也。故不足以滑和，不可入于灵府。使之和豫，通而不失于兑；使日夜无郤而与物为春，是接而生时于心者也。是之谓才全。』」唐·成玄英疏：「灵…","q":[["愔愔闻玉磬，寤寐在灵府。","皎然 读张曲江集"]]},{"n":"鲁司寇","d":"","s":"《史记》卷四十七《孔子世家》","w":"其后定公以孔子为中都宰，一年，四方皆则之。由中都宰为司空，由司空为大司寇。","q":[["司寇亦曾遭鲁黜，步兵何事哭途穷。","李山甫 早秋山中作"]]},{"n":"鲁衣冠","d":"","s":"《礼记·儒行》","w":"鲁哀公问于孔子曰：「夫子之服，其儒服与？」孔子对曰：「丘少居鲁，衣逢掖之衣，长居宋，冠章甫之冠。丘闻之也，君子之学也博，其服也乡。丘不知儒服。」","q":[["工为楚辞赋，更著鲁衣冠。","权德舆 送山人归旧隐"]]},{"n":"鲁中都","d":"","s":"《史记》卷四十七《孔子世家》","w":"孔子年四十二，鲁昭公卒于乾侯，定公立。……其后定公以孔子为中都宰，一年，四方皆则之。由中都宰为司空，由司空为大司寇。","q":[["地雄韩上党，秩比鲁中都。","权德舆 送从翁赴任长子县令"]]},{"n":"陆沉","d":"","s":"《庄子》杂篇·卷八下《则阳》","w":"「仲尼曰：『是圣人仆也。是自埋于民，自藏于畔。其声销，其志无穷，其口虽言，其心未尝言，方且与世违而心不屑与之俱。是陆沈者也，是其市南宜僚邪？』」晋·郭象注：「人中隐者，譬无水而沈也。」","q":[["僻地好泉石，何人曾陆沉。","于武陵 游中梁山"],["僻地好泉石，何人曾陆沉。","于邺 游中梁山"]]},{"n":"屡空","d":"","s":"《论语·先进》","w":"「子曰：『回也其庶乎，屡空。』」三国魏·何晏集解：「言回庶几圣道，虽数空匮而乐在其中。」","q":[["旅兹殊俗远，竟以屡空迫。","杜甫 郑典设自施州归"]]},{"n":"蛮貊可行","d":"","s":"《论语·卫灵公》","w":"子张问行。子曰：「言忠信，行笃敬，虽蛮貊之邦，行矣。言不忠信，行不笃敬，虽州里，行乎哉」","q":[["常闻仗患信，蛮貊可行矣。自古漂沉人，岂尽非君子。","白居易 初入峡有感"]]},{"n":"媚灶","d":"","s":"《论语·八佾》","w":"「王孙贾问曰：『与其媚于奥，宁媚于灶，何谓也？』子曰：『不然，获罪于天，无所祷也。』」唐·孔颖达疏：「奥，内也，谓室内西南隅也，以其隐奥，故尊者居之，其处虽尊，而间静无事，以喻近臣虽尊不执政柄，无益于人也。灶者，饮食之所由，虽处卑亵，为家之…","q":[["行身践规矩，甘辱耻媚灶。","韩愈 荐士"]]},{"n":"民受其赐","d":"","s":"《论语·先宪》","w":"子贡曰：「管仲非仁者与？桓公杀公子纠，不能死，又相之。」子曰：「管仲相桓公，霸诸侯，一匡天下，民到于今受其赐；微管仲，吾其被发左衽矣！岂若匹夫匹妇之为谅也，自经于沟渎而莫之知也！」","q":[["道州民，民到于今受其赐。","白居易 新乐府（并序）之道州民之美（一有贤字）臣遇明主也"]]},{"n":"鸣攻","d":"","s":"《论语·先进》","w":"季氏富于周公，而求也为之聚敛而附益之。子曰：『非吾徒也。小子鸣鼓而攻之，可也。』」东汉·郑玄注：「鸣鼓，声其罪以责之。」","q":[["仗义悬无敌，鸣攻故有词。","杜牧 和野人殷潜之题筹笔驿十四韵"]]},{"n":"尼甫縻匡","d":"","s":"《史记》卷四十七《孔子世家》","w":"匡人闻之，以为鲁之阳虎。阳虎尝暴匡人，匡人于是遂止孔子。孔子状类阳虎，拘焉五日，颜渊后，子曰：「吾以汝为死矣。」颜渊曰：「子在，回何敢死！」匡人拘孔子益急，弟子惧。孔子曰：「文王既没，文不在兹乎？天之将丧斯文也，后死者不得与于斯文也。天之未…","q":[["尼甫至圣贤，犹为匡所縻。","李咸用 君子行"]]},{"n":"宁武愚","d":"","s":"《论语·公冶长》","w":"子曰：「宁武子，邦有道，则知；邦无道，则愚。其知可及也，其愚不可及也。」","q":[["直似王陵戆，非如宁武愚。","张九龄 登荆州城楼"],["醺醺若借嵇康懒，兀兀仍添宁武愚。","杜牧 歙州卢中丞见惠名酝"]]},{"n":"七人","d":"","s":"《论语·宪问》","w":"子曰：「贤者辟世，其次辟地，其次辟色，其次辟言。」子曰：「作者七人矣。」","q":[["疲羸只欲思三径，戆直那堪备七人。","权德舆 省中春晚忽忆江南旧居戏书所怀因寄两浙亲故杂言"]]},{"n":"七十人","d":"","s":"《孟子注疏》卷三下〈公孙丑章句上〉～63～","w":"以德服人者，中心悦而诚服也，如七十子之服孔子也。","q":[["从军暮下三千客，闻礼庭中七十人。","许浑 和人贺杨仆射致政"]]},{"n":"七十说","d":"","s":"《淮南子》卷二十〈泰族训〉～683～","w":"孔子欲行王道，东西南北，七十说而无所偶。故因卫卫夫人、弥子瑕而欲通其道。此皆欲平险除秽，由冥冥至炤炤，动于权而统于善者也。夫观逐者于其反也，而观行者于其终也。故舜放弟，周公杀兄，犹之为仁也；文公树米，曾子架羊，犹之为知也。","q":[["仲尼七十说，历聘莫见收。","李白 赠崔郎中宗之"]]},{"n":"期月","d":"","s":"《论语·子路》","w":"「子曰：『苟有用我者，期月而已可也，三年有成。』」宋·邢炳疏：「期月，周月也，谓周一年之十二月也。」","q":[["期月终迷化，三年讵有成。","李绅 到宜武三十韵"],["海隅布政惭期月，江上沾巾愧万人。","李绅 宿越州天主寺"]]},{"n":"起予","d":"","s":"《史记》卷六十七〈仲尼弟子列传〉～2202～","w":"子夏问：「『巧笑倩兮，美目盼兮，素以为绚兮』，何谓也？」子曰：「绘事后素。」曰：「礼后乎？」孔子曰：「商始可与言诗已矣。」","q":[["努力输肝胆，休烦独起予。","杜甫 秋日荆南送石首薛明府辞满告别奉寄薛尚书颂德叙怀斐然之作三十韵"],["起予幸斑白，因是托子孙。","杜甫 贻华阳柳少府"]]},{"n":"千钟","d":"","s":"《孔子家语》卷二〈致思〉～5～","w":"孔子曰：「季孙之赐我粟千钟也，而交益亲，自南宫敬叔之乘我车也，而道加行。故道虽贵，必有时而后重，有势而后行，微夫二子之贶财，则丘之道，殆将废矣。」","q":[["争得千钟季孙粟，沧洲归与故人分。","徐夤 温陵即事"],["南昌一榻延徐孺，楚国千钟逼老莱。","杜荀鹤 和友人见题山居水阁八韵"]]},{"n":"丘祷","d":"","s":"《论语·述而》","w":"「子疾病，子路请祷。子曰：『有诸？』子路对日：『有之；《诔》曰：祷尔于上下神祗。』子曰：『丘之祷久矣。』」三国魏·何晏《集解》：「孔安国曰：『孔子素行合于神明，故曰丘之祷久矣。』」","q":[["丘祷虽已久，氓心难重违。","张九龄 洪州西山祈雨是日辄应因赋诗言事"],["我家柱石衰，忧来学丘祷。","文宗皇帝 上巳日赐裴度"]]},{"n":"丘轲自厄穷","d":"","s":"《史记》卷四十七〈孔子世家〉～905～","w":"孔子生鲁昌平乡陬邑。其先宋人也，曰孔防叔。防叔生伯夏，伯夏生叔梁纥。纥与颜氏女野合而生孔子，祷于尼丘得孔子。鲁襄公二十二年而孔子生。生而首上圩顶，故因名曰丘云。字仲尼，姓孔氏。……孔子贫且贱。及长，尝为季氏史，料量平；尝为司职吏而畜蕃息。由…","q":[]},{"n":"丘也同耻","d":"","s":"《论语·公冶长》","w":"子曰：「巧言、令色、足恭，左丘明耻之。丘亦耻之。匿怨而友其人，左丘明耻之，丘亦耻之。」","q":[["湛生久已没，丘也亦同耻。","于頔 和丘员外题湛长史旧居"]]},{"n":"丘也幸","d":"","s":"《论语注疏·述而》～64～","w":"陈司败问昭公知礼乎？孔子曰：「知礼。」孔子退，揖巫马期而进之，曰：「吾闻君子不党，君子亦党乎？君取于吴为同姓，谓之吴孟子。君而知礼，孰不知礼？」巫马期以告。子曰：「丘也幸，苟有过，人必知之。」","q":[]},{"n":"犬马有盖帷","d":"","s":"《礼记注疏》卷十〈檀弓〉～97～","w":"仲尼之畜狗死，使子贡埋之。曰：「吾闻之也，敝帷不弃，为埋马也；敝盖不弃，为埋狗也。」丘也贫，无盖，于其封也，亦予之席，毋使其首陷焉。路马死，埋之以帷。","q":[["猫虎获迎祭，犬马有盖帷。","柳宗元 掩役夫张进骸"]]},{"n":"阙里","d":"","s":"《汉书》卷六十七《梅福传》","w":"「今仲尼之庙不出阙里。」唐·颜师古注：「阙里，孔子旧里也。」","q":[["家法遥传阙里训，心源早逐嵩丘侣。","权德舆 奉送孔十兄宾客承致政归东都旧居"]]},{"n":"仁者依山","d":"","s":"《论语·雍也》","w":"子曰：「知者乐水，仁者乐山；知者动，仁者静；知者乐，仁者寿。」","q":[["愚公方住谷，仁者本依山。","李商隐 灵仙阁晚眺寄郓州韦评事"]]},{"n":"入寥天一","d":"","s":"《庄子集释》卷三上〈内篇·大宗师〉～274～","w":"颜回问仲尼曰：「孟孙才，其母死，哭泣无涕，中心不戚，居丧不哀。无是三者，以善处丧盖鲁国。固有无其实而得其名者乎？回壹怪之。」仲尼曰：「夫孟孙氏尽之矣，进于知矣。唯简之而不得，夫已有所简矣。孟孙氏不知所以生，不知所以死；不知就先，不知就后；若…","q":[]},{"n":"若堂封","d":"","s":"《礼记注疏》卷八〈檀弓上〉～49～","w":"孔子之丧，有自燕来观者。舍于子夏氏，子夏曰：「圣人之葬人，与人之葬圣人也，子何观焉？昔者夫子言之曰：『吾见封之若堂者矣。』见若坊者矣，见若覆夏屋者矣，见若斧者矣，从若斧者焉，马鬣封之谓也，今一日而三斩板，而已封，尚行夫子之志乎哉！」东汉·郑…","q":[["三亩空留悬磬室，九原犹寄若堂封。","柳宗元 同刘二十八哭吕衡州兼寄江陵李元二侍御"]]},{"n":"三百篇","d":"","s":"《论语注疏·为政》～6～","w":"子曰：「《诗》三百，一言以蔽之，曰『思无邪』。」","q":[["君看三百篇章首，何处分明著姓名。","齐己 偶题"]]},{"n":"三千弟子","d":"","s":"《史记》卷四十七〈孔子世家〉～938～","w":"孔子以诗书礼乐教，弟子盖三千焉，身通六艺者七十有二人。如颜浊邹之徒，颇受业者甚众众。","q":[["三千弟子标青史，万代先生号素王。","刘沧 经曲阜城"],["十五男儿志，三千弟子行。","杜甫 又示宗武"]]},{"n":"无喜愠","d":"","s":"《论语注疏·公冶长》～44～","w":"子张问曰：「令尹子文三仕为令尹，无喜色；三已之，无愠色。旧令尹之政，必以告新令尹。何如？」子曰：「忠矣。」曰：「仁矣乎？」曰：「未知，焉得仁？」「崔子弑齐君，陈文子有马十乘，弃而违之。至于他邦，则曰：『犹吾大夫崔子也。』违之。之一邦，则又曰…","q":[]},{"n":"三益","d":"","s":"《后汉书》卷二十八下〈冯衍列传下·冯衍〉～984～","w":"臣自惟无三益之才，不敢处三损之地，固让而不受之。唐·李贤注：「《论语注疏》载孔子言曰：『益者三友，损者三友』，故衍引以为言也。」","q":[["琢磨三益重，唱和五音调。","刘禹锡 酬杨八庶子喜韩吴兴与余同迁见赠"],["懿君敦三益，颓俗期一变。","杨巨源 题赵孟庄"]]},{"n":"忘肉味","d":"忘味：指许久未吃过味美食物。宋陆游《病思》之四：“本自人山缘服玉，不应忘味待闻韶。”；闻韶：喻听到或看到极美妙、极向往的音乐或事物。南朝梁张率《楚王吟》：“不惜同从理，但使一闻韶。”","s":"《论语注疏·述而》～6～","w":"子在齐，闻韶，三月，不知肉味，曰：「不图为乐之至于斯也。」三国魏·何晏集解：「周曰，孔子在齐，闻习韶乐之盛美，故忽忘于肉味。」","q":[["虽无先圣耳，异代得闻昭。","李咸用 览文僧卷"],["欲知忘味处，共仰在齐人。","窦庠 奉和王侍郎春日喜李侍郎崔给谏张舍人韦谏议见访因命觞观乐之什"]]},{"n":"丧家狗","d":"丧家狗：喻失意落魄的窘境。唐杜甫《奉赠李八丈判官》：“真成穷辙鲋，或似丧家狗。”","s":"《史记》卷四十七〈孔子世家〉～92～","w":"孔子适郑，与弟子相失，孔子独立郭东门。郑人或谓子贡曰：「东门有人，其颡似尧，其项类皋陶，其肩类子产，然自要以下不及禹三寸。累累若丧家之狗。」子贡以实告孔子。孔子欣然笑曰：「形状，末也。而谓似丧家之狗，然哉！然哉！」","q":[["真成穷辙鲋，或似丧家狗。","杜甫 奉赠李八丈判官"],["昔如纵壑鱼，今如丧家狗。","杜甫 将适吴楚留别章使君留后兼幕府诸公得柳字"]]},{"n":"杀伐仿佛","d":"","s":"《孔子家语》卷八《辨乐》","w":"「子路鼓琴，孔子闻之，谓冉有曰：『甚矣由之不才也。夫先王之制音也，奏中声以为节，流入于南，不归于北。夫南者，生育之乡，北者，杀伐之城。故君子之音温柔居中以养生育之气，忧愁之感不加于心也，暴厉之动，不在于体也。夫然者，乃所谓治安之风也。小人之…","q":[["耳闻读书声，杀伐灾髣髴。","杜甫 题衡山县文宣王庙新学堂呈陆宰"]]},{"n":"少施","d":"","s":"《礼记注疏》卷四十三〈杂记〉～755～","w":"孔子曰：「吾食于少施氏而饱，少施氏食我以礼。」东汉·郑玄注：「贵其以礼待已，而为之饱也。时人倨慢若季氏，则不以礼矣，少施氏，鲁惠公子施父之后。」","q":[["法味已同香积会，礼容疑在少施家。","权德舆 惠上人房宴别"]]},{"n":"圣相","d":"","s":"《晏子春秋》卷八《外篇》","w":"仲尼相鲁，景公患之，谓晏子曰：「邻国有圣人，敌国之忧也。今孔子相鲁若何？」晏子对曰：「君其勿忧。彼鲁君，弱主也；孔子，圣相也。」","q":[["帝得圣相相曰度，贼斫不死神扶持。","李商隐 韩碑"]]},{"n":"十哲","d":"","s":"《旧唐书》卷二十四〈礼仪志四〉～99～","w":"初，开元八年，国子司业李元瓘奏称：「先圣孔宣父庙，先师颜子配座，今其像立侍，配享合坐。十哲弟子，虽复列像庙堂，不预享祀。谨检祠令：何休、范宁等二十二贤，犹沾从祀，望请春秋释奠，列享在二十二贤之上。七十子，请准旧都监堂图形于壁，兼为立赞，庶敦…","q":[]},{"n":"拾尘","d":"","s":"《吕氏春秋·览部》卷十七〈审分览·任数〉～066～","w":"孔子穷乎陈、蔡之间，藜羹不斟，七日不尝粒，昼寝。颜回索米，得而爨之，几熟。孔子望见颜回攫其甑中而食之。选间，食熟，谒孔子而进食。孔子佯为不见之。孔子起曰：「今者梦见先君，食洁而后馈。」颜回对曰：「不可。向者煤室入甑中，弃食不祥，回攫而饭之。…","q":[["拾尘掇蜂，疑圣猜贤。","李白 雪谗诗赠友人"],["机事齐飘瓦，嫌猜比拾尘。","柳宗元 酬娄秀才将之淮南所赠之升"]]},{"n":"叔孙毁仲尼","d":"","s":"《论语·子张》","w":"叔孙武叔毁仲尼，子贡曰：「无以为也！仲尼不可毁也。」","q":[["叔孙毁仲尼，臧仓掩孟轲。","孟郊 君子勿郁郁士有谤毁者作诗以赠之"]]},{"n":"庶几","d":"","s":"《周易》卷八《系辞下》","w":"「子曰：『颜氏之子，其殆庶几乎！有不善未尝不知，知之未尝复行也。』」唐·孔颖达疏：「此节论贤人唯庶于几，虽未能知几。故引颜氏之子以明之也，其殆庶几乎者，言圣人知几，颜子亚圣，未能知几，但殆近庶慕而已。」","q":[["钱神任尔知无敌，酒圣于吾亦庶几。","杜牧 题桐叶"]]},{"n":"丝纶","d":"","s":"《礼记·缁衣》","w":"「王言如丝，其出如纶。王言如纶，其出如綍。故大人不倡游言。」汉。郑玄注：「言言出弥大也。纶，今有秩，啬夫所佩也。綍，引棺素也。」唐·孔颖达疏：「王言初出微细如丝，及其出行于外，言更渐大如似纶也。言纶粗于丝。王言如纶，其出如綍者，亦言渐大，出…","q":[["从辞凤阁掌丝纶，便向青云领贡宾。","广宣 贺王起（一作贺王侍郎典供放榜）"],["走笔往来盈卷轴，除官递互掌丝纶。","白居易 余思未尽加为六韵重寄微之（一作微之整集旧诗及文笔为百轴。以七言长句寄乐天。乐天次韵酬之。馀思未尽。加为六韵。）"]]},{"n":"孙敖秉羽","d":"","s":"《庄子》杂篇·卷八中《徐无鬼》","w":"「仲尼之楚，楚王觞之，孙叔敖执爵而立，市南宜僚受酒而祭曰：『古之人乎！于此言已。』曰：『丘也闻不言之言矣，未之尝言，于此乎言之。前此未尝言不言之言，乃今言之。市南宜僚弄丸而两家之难解，孙叔敖甘寝秉羽而郢人投兵。丘愿有喙三尺。』」唐·成玄英疏…","q":[["寝谋惭汲黯，秉羽贵孙敖。","李德裕 寒食日三殿侍宴奉进诗一首"]]},{"n":"探汤","d":"","s":"《论语·季氏》","w":"「孔子曰：『见善如不及，见不善如探汤。吾见其人矣，吾闻其语矣。』」宋·邢炳疏：「人之探试热汤，其去之必速，以喻见恶事去之疾也。」","q":[["探汤汲阴井，炀灶开重扉。","柳宗元 夏夜苦热登西楼"],["中原初纵燎，下国竟探汤。","韦庄 和郑拾遗秋日感事一百韵"]]},{"n":"滔滔天下","d":"","s":"《论语》卷九《微子》","w":"长沮、桀溺耦而耕，孔子过之，使子路问津焉。长沮曰：「夫执舆者为谁？」子路曰：「为孔丘。」曰：「是鲁孔丘与？」曰：「是也。」曰：「是知津矣。」问于桀溺，桀溺曰：「子为谁？」曰：「为仲由。」曰：「是鲁孔丘之徒与？」对曰：「然。」曰：「滔滔者天下…","q":[["衰世难修道，花时不称贫。滔滔天下者，何处问通津。","李咸用 春日忆李白"]]},{"n":"微尔","d":"","s":"《论语》卷七《宪问》","w":"子曰：「管仲相桓公，霸诸侯，一匡天下，民到于今受其赐。微管仲，吾其被发左衽矣。」","q":[["微尔人尽非，于今国犹活。","杜甫 北征"]]},{"n":"吾其衽发","d":"","s":"《论语注疏·宪问》～27～","w":"子贡曰：「管仲非仁者与？桓公杀公子纠，不能死，又相之。」子曰：「管仲相桓公，霸诸侯，一匡天下，民到于今受其赐。微管仲，吾其被发左衽矣。岂若匹夫匹妇之为谅也，自经于沟渎而莫之知也。」宋·邢炳疏：「微，无也。衽谓衣衿。衣衿向左谓之左衽，夷狄之人…","q":[]},{"n":"卫谤","d":"","s":"《史记》卷四十七《孔子世家》","w":"孔子遂适卫，主于子路妻兄颜浊邹家。卫灵公问孔子：「居鲁得禄几何？」对曰：「奉粟六万。」卫人亦致粟六万。居顷之，或谮孔子于卫灵公。灵公使公孙余假一出一入。孔子恐获罪焉，居十月，去卫。","q":[["终当灭卫谤，不受鲁人讥。","李白 书怀赠南陵常赞府"]]},{"n":"吴练","d":"","s":"《论衡》卷四《书虚》","w":"孔子东南望，吴阊门外有系白马，引颜渊指以示之，曰：「若见吴昌门乎？」颜渊曰：「见之。」孔子曰：「门外何有？」曰：「有如系练之状。」","q":[["吴练已知随影没，朔风犹想带嘶闻。","刘威 伤曾秀才马"]]},{"n":"吾安放","d":"","s":"《礼记·檀弓上》","w":"「孔子早作，负手曳杖，逍遥于门，歌曰：『泰山其颓乎！梁木其坏乎！哲人其萎乎。』既歌而入，当户而坐。子贡闻之，曰：『泰山其颓，则吾将安仰；梁木其坏，哲人其萎，则吾将安放？夫子殆将病也！』遂趋而入。夫子曰：『赐，尔来何迟也，夏后氏殡于东阶之上，…","q":[["百年见存殁，牢落吾安放。","杜甫 八哀诗故著作郎贬台州司户荥阳郑公虔"]]},{"n":"吾党二三子","d":"","s":"《论语·公冶长》","w":"「子在陈，孔子曰：『归乎，归乎！吾党之小子狂简，斐然成章，吾不知所以裁之。』」《论语·述而》「子曰：『二三子以我为隐乎？吾无隐乎尔。吾无行而不与二三子者，是丘也。』」","q":[["嗟哉吾党二三子，安得至老不更归。","韩愈 山石"]]},{"n":"吾语汝","d":"","s":"《论语注疏·阳货》～55～","w":"子曰：「由也，女闻六言六蔽矣乎？」对曰：「未也。」「居！吾语女。好仁不好学，其蔽也愚；好知不好学，其蔽也荡；好信不好学，其蔽也贼；好直不好学，其蔽也绞；好勇不好学，其蔽也乱；好刚不好学，其蔽也狂。」","q":[]},{"n":"无力犹能肆汝杯","d":"","s":"《论语注疏·宪问》～29～","w":"公伯寮愬子路于季孙。子服景伯以告，曰：「夫子固有惑志于公伯寮，吾力犹能肆诸市朝。子曰：「道之将行也，与命也，道之将废也，与命也，公伯寮其如命何。」","q":[]},{"n":"五十知天命","d":"","s":"《论语注疏·为政》～6～","w":"子曰：「吾十有五而志于学，三十而立，四十而不惑，五十而知天命，六十而耳顺，七十而从心所欲，不踰矩。」","q":[["五十知天命，吾其达此生。","张说 岳州夜坐"],["笑向春风初五十，敢言知命且知非。","杜牧 岁旦朝回口号"]]},{"n":"席上珍","d":"","s":"《礼记·儒行》","w":"哀公命席，孔子侍曰：「儒有席上之珍以待聘，夙夜强学以待问，怀忠信以待举，力行以待取，其自立有如此者。」","q":[["昔作园中实，今来席上珍。","李世民 赋得樱桃"],["我有握中璧，双飞席上珍。","李隆基 左丞相说右丞相璟太子乾耀同日上官命宴东堂赐诗"]]},{"n":"萧墙","d":"","s":"《论语注疏·季氏》～46～","w":"季氏将伐颛臾。冉有、季路见于孔子曰：「季氏将有事于颛臾。」孔子曰：「求！无乃尔是过与？夫颛臾，昔者先王以为东蒙主，且在邦域之中矣，是社稷之臣也。何以伐为？」冉有曰：「夫子欲之，吾二臣者皆不欲也。」孔子曰：「求！周任有言曰：『陈力就列，不能者…","q":[]},{"n":"小人儒","d":"","s":"《论语·雍也》","w":"子谓子夏曰：「汝为君子儒，无为小人儒。」","q":[["名参君子场，行为小人儒。","孟郊 旅次湘沅有怀灵均"]]},{"n":"朽木不可雕","d":"","s":"《论语·公冶长》","w":"「宰予昼寝，子曰：『朽木不可雕也，粪土之墙不可圬也。于予与何诛？』」","q":[["数子皆奇货，唯予独朽株。","元稹 酬乐天东南行诗一百韵（并序）"],["朽木不可雕，短翮将焉摅。","王绩 薛记室收过庄见寻率题古意以赠"]]},{"n":"宣尼念鲁","d":"","s":"《论语注疏·公冶长》～45～","w":"子在陈曰：「归与！归与！吾党之小子狂简，斐然成章，不知所以裁之。」","q":[["谁言圣与哲，曾是不怀土。公旦既思周，宣尼亦念鲁。","李德裕 夏晚有归平泉林居"]]},{"n":"一夔足","d":"","s":"《韩非子》卷十二〈外储说左下·说二〉～686～","w":"鲁哀公问于孔子曰：『吾闻古者有夔一足，其果信有一足乎？孔子对曰：『不也，夔非一足也。夔者忿戾恶心，人多不说喜也。虽然，其所以得免于人害者，以其信也，人皆曰独此一足矣，夔非一足也，一而足也。』哀公曰：『审而是固足矣。』","q":[]},{"n":"用行舍藏","d":"","s":"《论语注疏·述而》～6～","w":"子谓颜渊曰：「用之则行，舍之则藏，唯我与尔有是夫！」子路曰：「子行三军，则谁与？」子曰：「暴虎冯河，死而无悔者，吾不与也。必也临事而惧，好谋而成者也。」","q":[]},{"n":"由之瑟","d":"升堂：喻学识造诣精深。唐杜甫《戏题寄上汉中王三首》之三：“空余枚叟在，应念早升堂。”；由也瑟：指自谦学识不够精深。唐窦庠《酬韩愈侍郎登岳阳楼见赠》：“自悲由也瑟，敢坠孔悝铭。”","s":"《论语注疏·先进》～98～","w":"子曰：「由之瑟奚为于丘之门？」门人不敬子路。子曰：「由也升堂矣，未入于室也。」","q":[["空余枚叟在，应念早升堂。","杜甫 戏题寄上汉中王三首之三"],["敢衒由之瑟，甘循赐也墙。","杨巨源 上刘侍中"]]},{"n":"玉振","d":"","s":"《孟子》卷十上《万章下》","w":"孔子，圣之时者也，孔子之谓集大成。集大成也者，金声而玉振之也，金声也者，始条理也，玉振之也者，终条理也，始条理者，智之事也，终条理者，圣之事也。","q":[["士林推玉振，公府荐冰清。","皎然 送乌程李明府得陟状赴京"]]},{"n":"韫椟藏玉","d":"","s":"《论语注疏·子罕》～79～","w":"子贡曰：「有美玉于斯，韫而藏诸，求善贾而沽诸。」子曰：「沽之哉，沽之哉，我待贾者也。」宋·朱熹《论语集注》：「韫，藏也。椟，匮也。沽，卖也。子贡以孔子有道不仕，故设此二端以问也。孔子言固当卖之，但当待贾，而不当求之耳。」","q":[]},{"n":"章甫西东","d":"","s":"《礼记·儒行》","w":"孔子对曰：「丘少居鲁，衣逢掖之衣；长居宋，冠章甫之冠。」","q":[["青囊仍隐逸，章甫尚西东。","杜甫 奉寄河南韦尹丈人"]]},{"n":"芝兰室","d":"","s":"《孔子家语》卷四《六本》","w":"与善人居，如入芝兰之室，久而不闻其香，即与之化矣。","q":[["宿昔芝兰室，今兹鸳鹭行。","权德舆 户部王曹长杨考功崔刑部二院长并同钟陵使府之旧因以寄赠又陪郎署喜甚常僚因书所怀且叙所知（一作前好）"],["芳室芝兰茂，春蹊桃李开。","卢纶 书情上大尹十兄"]]},{"n":"知丘","d":"知丘：喻对作者及其作品深为理解、唐徐弦《张先辈见寄二首》之二：“两首新诗千里道，感君情分独知丘。”","s":"《孟子注疏》卷六〈滕文公章句下〉～7～","w":"世衰道微，邪说暴行有作，臣弑其君者有之，子弑其父者有之。孔子惧，作《春秋》。《春秋》，天子之事也；是故孔子曰：「知我者其惟《春秋》乎！罪我者其惟《春秋》乎！」","q":[["两首新诗千里道，感君情分独知丘。","徐弦 张先辈见寄二首"],["杯酒英雄君与操，文章微婉我知丘。","白居易 哭刘尚书梦得二首"]]},{"n":"蹠行仁义孔丘非","d":"","s":"《庄子集释》卷四中〈外篇·胠箧〉～346～","w":"故蹠之徒问于蹠曰：「盗亦有道乎？」蹠曰：「何适而无有道邪！」夫妄意室中之藏，圣也；入先，勇也；出后，义也；知可否，知也；分均，仁也。五者不备而能成大盗者，天下未之有也。","q":[]},{"n":"仲尼去卫之陈","d":"","s":"《史记》卷四十七〈孔子世家〉～920～","w":"去即过蒲。月馀，反乎卫，主蘧伯玉家。灵公夫人有南子者，使人谓孔子曰：「四方之君子不辱欲与寡君为兄弟者，必见寡小君。寡小君愿见。」孔子辞谢，不得已而见之。夫人在絺帷中。孔子入门，北面稽首。夫人自帷中再拜，环佩玉声璆然。孔子曰：「吾乡为弗见，见…","q":[]},{"n":"仲尼为土","d":"","s":"《史记》卷四十七《孔子世家》","w":"孔子贫且贱。及长，尝为季氏史，料量平；尝为司职吏而畜蕃息。由是为司空。","q":[["仲尼亦为土，鲁人焉敢耕。","刘驾 励志（一作续励志）"]]},{"n":"周孔","d":"","s":"《昭明文选》卷十五东汉·张平子（衡）《归田赋》","w":"「弹五弦之妙指，咏周孔之图书。」唐·李善注：「周，周公；孔，孔子也。」","q":[["轩皇竟磨灭，周孔亦衰老。","孟云卿 放歌行"],["周孔传文教，萧曹授武经。","杜牧 分司东都寓居履道叨承川尹刘侍郎大夫恩知上四十韵"]]},{"n":"洙泗","d":"","s":"《礼记注疏》卷七〈檀弓〉～28～","w":"「曾子怒曰：『商，女何无罪也？吾与女事夫子于洙泗之间。』」东汉·郑玄注：「洙、泗，鲁水名。」","q":[["业成洙泗客，皓发著儒衣。","司空曙 送菊潭王明府"],["人归洙泗学，歌盛舞雩风。","卢象 赠广川马先生"]]},{"n":"铸颜","d":"","s":"《法言·学行》","w":"或曰：「人可铸与？」曰：「孔子铸颜渊矣。」","q":[["宁同鲁司寇，惟铸一颜回。","李商隐 喜舍弟羲叟及第上礼部魏公"],["斗间紫气龙埋狱，天上洪炉帝铸颜。","杜牧 道一大尹存之庭美二学士简于圣明自致霄汉皆与舍弟昔年还往牧支离穷悴窃于一麾书美歌诗兼自言志因成长句四韵呈上三君子"]]},{"n":"子曰","d":"","s":"《论语·学而》","w":"「子曰：『学而时习之，不亦说乎？有朋自远方来，不亦乐乎？人不知而不愠，不亦君子乎？』」三国魏·何晏《集解》：「马曰：子者，男子之通称，谓孔子也。」","q":[["率赋赠远言，言惭非子曰。","贾岛 赠智朗禅师"]]},{"n":"孔孟","d":"","s":"《史记》卷四十七《孔子世家》","w":"「孔子生鲁昌平乡陬邑。」唐·司马贞《史记索隐》：「孔子居鲁之邹邑昌平乡之阙里也。」","q":[["末学惭邹鲁，深仁录弟兄。","皇甫冉 上礼部杨侍郎"],["邹鲁诗书国，应无鼙鼓喧。","郎士元 送裴补阙入河南"]]},{"n":"鄹人子","d":"","s":"《论语注疏·八佾》～28～","w":"子入太庙，每事问。或曰。孰谓鄹人之子知礼乎。入太庙。每事问。子闻之曰。是礼也。三国魏·何晏集解引孔(安国)曰：「鄹，孔子父叔梁纥所治邑。时人多言孔子知礼。」宋·邢炳疏：「鄹人，鲁鄹邑大夫孔子父叔梁纥也。」","q":[]},{"n":"俎豆","d":"","s":"《论语·卫灵公》","w":"卫灵公问陈于孔子。孔子对曰：「俎豆之事，则尝闻之矣；军旅之事，未之学也。」明日遂行。在陈绝粮，从者病，莫能兴。子路愠见曰：「君子亦有穷乎？」子曰：「君子固穷，小人穷斯滥矣。」三国魏·何晏《史记集解》引汉孔安国注：「俎豆，礼器。」","q":[["宗儒俎豆事，故吏去思计。","杜甫 八哀诗赠秘书监江夏李公邕"],["旄头彗紫微，无复俎豆事。","杜甫 题衡山县文宣王庙新学堂呈陆宰"]]}],"1":[{"n":"阿娇","d":"","s":"《史记》卷四十九《外戚世家》","w":"「初，上为太子时，娶长公主女为妃。立为帝，妃立为皇后，姓陈氏。」唐·司马贞《史记索隐》：「《汉武故事》云：『后名阿娇』即长公主嫖女也。」","q":[["母兄怜爱无俦侣，五岁名为阿娇女。","崔显 邯郸宫人怨"],["阿娇生汉宫，西施住南国。","曹邺 四怨三愁五情诗十二首其二情"]]},{"n":"哀痛诏","d":"","s":"《汉书》卷九十六下〈西域列传下〉～392～","w":"上乃下诏，深陈既往之悔，曰：「前有司奏，欲益民赋三十助边用，是重困老弱孤独也。而今又请遣卒田轮台。……乃者贰师败，军士死略离散，悲痛常在朕心。」……赞曰：孝武之世，图制匈奴，患其兼从西国，结党南羌，乃表河西，列四郡，开玉门，通西域，以断匈奴…","q":[["忽闻哀痛诏，又下圣明朝。","杜甫 收京三首"]]},{"n":"安世三箧","d":"","s":"《汉书》卷五十九《张汤传》附《张安世传》","w":"「安世字子孺，少以父任为郎。用善书给事尚书，精力于职，休沐未尝出。上行幸河东，尝亡书三箧，诏问莫能知，唯安世识之，具作其事。后购求得书，以相校无所遗失。上奇其材，擢为尚书令，迁光禄大夫。」","q":[["应奉五行，安世三箧。","李瀚 蒙求"],["汉使收三箧，周诗采百篇。","李端 送耿拾遗湋使江南括图书"]]},{"n":"苏武节","d":"羝乳：指无法办到之事。元袁桷《题郝伯常雁足》：“不须羝乳终回汉，肯学鸡鸣诈度关。”；苏武节：喻忠臣出使，宁死不屈。唐戎昱《闻颜尚书陷贼中》：“能持苏武节，不受马超勋。”","s":"《汉书》卷五十四〈李广苏建列传·苏建·（子）苏武〉～2459～","w":"武字子卿，少以父任，兄弟并为郎，稍迁至栘中厩监。时汉连伐胡，数通使相窥观，匈奴留汉使郭吉、路充国等，前后十馀辈。匈奴使来，汉亦留之以相当。天汉元年，且鞮侯单于初立，恐汉袭之，乃曰：「汉天子我丈人行也。」尽归汉使路充国等。武帝嘉其义，乃遣武以…","q":[["握雪海上餐，拂沙陇头寝。","李白 塞下曲六首之二"],["就烹感汉使，握节悲阳秋。","李德裕 东郡怀古二首之阳给事"]]},{"n":"白麟","d":"","s":"《汉书》卷六《武帝纪》","w":"「汉元狩元年冬十月，所幸雍，祠五时。获白麟，作《白麟之歌》。」唐·颜师古注：「麟，麋身，牛尾，马足，黄色，圜蹄，一角，角端有肉。」","q":[["池籞呈朱雁，坛场得白麟。","元稹 代曲江老人百韵（年十六时作）"]]},{"n":"燕钗","d":"","s":"旧题南朝梁·任昉《述异记》卷下","w":"汉武帝元鼎元年，起招灵阁，有一神女，留一玉钗与帝，帝以赐赵婕妤。至昭帝元凤中，宫人见此钗，光莹甚异，共谋欲碎之。明视钗匣，唯见白燕，直升天去。后宫人常作玉钗，因名玉燕钗。","q":[["当时白燕无寻处，今日云鬟见玉钗。","刘言史 赠成炼师四首"],["泉下双龙无再期，金蚕玉燕空销化。","孟郊 悼亡"]]},{"n":"长门赋","d":"千金赋：喻作品极有价值。金元好问《白屋》：“长门谁买千金赋，祖道虚传五鬼文。”；长门泣：喻失宠后的凄怨心情。南朝梁何逊《扬州法曹梅花盛开》：“朝洒长门泣，夕驻临邛杯。”","s":"《昭明文选》卷十六汉·司马长卿（相如）《长门赋·序》","w":"「孝武皇帝陈皇后时得幸，颇妒。别在长门宫，愁闷悲思。闻蜀郡成都司马相如天下工为文，奉黄金百斤为相如文君取酒，因于解悲愁之辞。而相如为文以悟主上，陈皇后复得亲幸。」","q":[["长门谁买千金赋，祖道虚传五鬼文。","元好问 白屋"],["虽然不似王孙女，解爱临邛卖赋郎。","崔珏 有赠"]]},{"n":"宝屏","d":"","s":"晋·葛洪《西京杂记》卷二","w":"武帝为七宝床、杂宝按宝屏风、列宝帐、设于桂宫。时人谓之四宝宫。","q":[["巫峡曾经宝屏见，楚宫犹对碧峰疑。","杜甫 夔州歌十绝句"]]},{"n":"璧门","d":"","s":"《三辅黄图》卷二《汉宫》","w":"帝于未央宫营造日广，以城中为小，乃于宫西跨城池作飞阁，通建章宫……宫之正门曰阊阖，高二十五丈。亦曰璧门。」","q":[["月上白璧门，桂影凉参差。","杜牧 杜秋娘诗"]]},{"n":"传雁","d":"雁书：喻书信。唐杜甫《秋日荆南送石首薛明诗》：“岁满归凫舄，秋来把雁书。”","s":"《汉书》卷五十四〈李广苏建列传·苏武〉","w":"初，武与李陵俱为侍中，武使匈奴明年，陵降，不敢求武。……陵恶自赐武，使其妻赐武牛羊数十头。后陵复至北海上，语武：「区脱捕得云中生口，言太守以下吏民皆白服，曰上崩。」武闻之，南乡号哭，欧血，旦夕临。数月，昭帝即位。数年，匈奴与汉和亲。汉求武等…","q":[["当日苏武单于问，道是宾鸿解传信。","刘商 胡笳十八拍"],["家书欲寄雁飞远，客恨正深秋又来。","刘威 早秋归"]]},{"n":"博望宾","d":"","s":"《三辅黄图》卷四《苑囿》","w":"武帝立子据为太子，为太子开博望苑以通宾客。《汉书》曰：「武帝年二十九乃得太子，甚喜。太子冠，为立博望苑，使之通宾客从其所好。」又云：「博望苑在长安城南，杜门外五里有遗址。」","q":[["昔曾对作承华相，今复连为博望宾。","白居易 赠皇甫宾客"]]},{"n":"苍鴚","d":"","s":"《汉书》卷五十四〈李广苏建列·苏建·（子）苏武〉～2466～","w":"数月，昭帝即位。数年，匈奴与汉和亲。汉求武等，匈奴诡言武死。后汉使复至匈奴，常惠请其守者与俱，得夜见汉使，具自陈道。教使者谓单于，言天子射上林中，得雁，足有系帛书，言武等在某泽中。使者大喜，如惠语以让单于。单于视左右而惊，谢汉使曰：「武等实…","q":[]},{"n":"长门","d":"","s":"《昭明文选》卷十六〈赋辛·哀伤·长门赋〉～72～","w":"孝武皇帝陈皇后时得幸，颇妒。别在长门宫，愁闷悲思。闻蜀郡成都司马相如天下工为文，奉黄金百斤为相如文君取酒，因于解悲愁之辞。而相如为文以悟主上，陈皇后复得亲幸。","q":[["今日在长门，从来不如丑。","于濆 宫怨"],["谁能赋得长门事，不惜千金奉酒杯。","吴融 上阳宫词"]]},{"n":"绣斧","d":"","s":"《汉书》卷六十六〈公孙刘田王杨蔡陈郑列传·王䜣〉～2887～","w":"王䜣，济南人也。以郡县吏积功，稍迁为被阳令。武帝末，军旅数发，郡国盗贼群起，绣衣御史暴胜之使持斧逐捕盗贼，以军兴从事，诛二千石以下。胜之过被阳，欲斩䜣，䜣已解衣伏质，仰言曰：「使君颛杀生之柄，威震郡国，今复斩一䜣，不足以增威，不如时有所宽，…","q":[["云客方持斧，与人正相临。","元结 酬裴云客"],["予时与和鼎，官班各持斧。","杜牧 李甘诗"]]},{"n":"斩楼兰","d":"斩楼兰：喻杀敌建功立业。唐李白《塞下曲六首》之一：“愿将腰下剑。直为斩楼兰。”","s":"《汉书》卷七十〈傅常郑甘陈段列传·傅介子〉～3002～","w":"介子与士卒俱赍金币，扬言以赐外国为名。至楼兰，楼兰王意不亲介子，介子阳引去，至其西界，使译谓曰：「汉使者持黄金锦绣行赐诸国，王不来受，我去之西国矣。」即出金币以示译。译还报王，王贪汉物，来见使者。介子与坐饮，陈物示之。饮酒皆醉，介子谓王曰：…","q":[["犹道楼兰十万师，书生匹马去何之。","严维 送房元直赴北京"],["拟脍楼兰肉，蓄怒时未扬。","孟郊 猛将吟"]]},{"n":"天马","d":"","s":"《史记》卷一百二十三〈大宛列传〉～370～","w":"初，天子发书《易》，云「神马当从西北来」。得乌孙马好，名曰「天马」。及得大宛汗血马，益壮，更名乌孙马曰「西极」，名大宛马曰「天马」云。而汉始筑令居以西，初置酒泉郡以通西北国。因益发使抵安息、奄蔡、黎轩、条枝、身毒国。而天子好宛马，使者相望于…","q":[["天马来东道，佳人倾北方。","吴少微 过汉故城"],["天马从东道，皇威被远戎。","周存 西戎献马"]]},{"n":"从官负薪","d":"","s":"《史记》卷二十九〈河渠书〉～42～","w":"自河决瓠子后二十馀岁，岁因以数不登，而梁楚之地尤甚。天子既封禅巡祭山川，其明年，旱，乾封少雨。天子乃使汲仁、郭昌发卒数万人塞瓠子决。于是天子已用事万里沙，则还自临决河，沈白马玉璧于河，令群臣从官自将军已下皆负薪窴决河。是时东郡烧草，以故薪柴…","q":[["天子忽惊悼，从官皆负薪。","高适 自淇涉黄河途中作十三首"]]},{"n":"大臣书","d":"","s":"《汉书》卷六十五《东方朔传》","w":"武帝初即位，徵天下举方正贤良文学材力之士，待以不次之位，四方士多上书言得失，……臣朔年二十二，长九尺三寸，目若悬珠，齿若编贝，勇若孟贲，捷若庆忌，廉若鲍叔，信若尾生。若此，可以为天子大臣矣。」","q":[["怀君欲何赠，愿上大臣书。","陈子昂 春夜别友人二首"]]},{"n":"斗蛙蟆","d":"","s":"《汉书》卷二十七中之下〈五行志中之下〉～430～","w":"武帝元鼎五年秋，蛙与虾虾蟆斗。是岁，四将军众十万征南越，开九郡。","q":[["谁识大君谦让德，一毫名利斗蛙蟆。","杜牧 长安杂题长句六首"],["大战元鼎年，孰强孰败桡。","韩愈 答柳柳州食虾蟆"]]},{"n":"李少卿","d":"","s":"《史记》卷一○九《李将军列传》附《李陵传》","w":"李陵既壮，选为建章监，监诸骑。善射，爱士卒。天子以为李氏世将，而使将八百骑。尝深入匈奴二千馀里，过居延视地形，无所见虏而还。拜为骑都尉，将丹阳楚人五千人，教射酒泉、张掖以屯卫胡。数岁，天汉二年秋，贰师将军李广利将三万骑击匈奴右贤王于祁连天山…","q":[["不是史迁书与说，谁知孤负李陵心。","司空图 狂题十八首之三"],["亭伯去安在，李陵降未归。","李白 奔亡道中五首之二"]]},{"n":"辕下驹","d":"","s":"《史记》卷一百七〈魏其武安侯列传〉～285～","w":"魏其之东朝，盛推灌夫之善，言其醉饱得过，乃丞相以他事诬罪之。武安又盛毁灌夫所为横恣，罪逆不道。魏其度不可柰何，因言丞相短。武安曰：「天下幸而安乐无事，鼢得为肺腑，所好音乐狗马田宅。鼢所爱倡优巧匠之属，不如魏其、灌夫日夜招聚天下豪桀壮士与论议…","q":[["赠尔秦人策，莫鞭辕下驹。","杜甫 别苏傒"],["出尘皆野鹤，历块匪辕驹。","杜甫 大历三年春白帝城放船出瞿塘峡久居夔府将适江陵漂泊有诗凡四十韵"]]},{"n":"访蓬瀛","d":"","s":"《史记》卷二十八《封禅书》","w":"「自威、宣、燕昭使人入海求蓬莱、方丈、瀛洲。此三神山者，其傅在勃海中，去人不远；患且至，则船风引而去。盖尝有至者，诸仙人及不死之药皆在焉。其物禽兽尽白，而黄金银为宫阙。未至，望之如云；及到，三神山反居水下。临之，风辄引去，终莫能至云。世主莫…","q":[["仍闻遣方士，东海访蓬瀛。","王维 早朝"]]},{"n":"相如赋","d":"","s":"《史记》卷一一七《司马相如列传》","w":"司马相如者，蜀郡成都人也，字长卿。少时好读书，学击剑，故其亲名之曰犬子。相如既学，慕蔺相如之为人，更名相如。以赀为郎，事孝景帝，为武骑常侍，非其好也。会景帝不好辞赋，是时梁孝王来朝，从游说之士齐人邹阳、淮阴枚乘、吴庄忌夫子之徒，相如见而说之…","q":[["献纳开东观，君王问长卿。","杜甫 赠陈二补阙"],["孟阳题剑阁，子云献甘泉。","储光羲 酬李处士山中见赠"]]},{"n":"赋罢为郎","d":"","s":"《史记》卷一一七《司马相如列传》","w":"上读子虚赋而善之，曰：「朕独不得与此人同时哉！」得意曰：「臣邑人司马相如自言为此赋。」上惊，乃召问相如。相如曰：「有是。然此乃诸侯之事，未足观也。请为天子游猎赋，赋成奏之。」上许，令尚书给笔札。相如以「子虚」，虚言也，为楚称；「乌有先生」者…","q":[["书成休逐客，赋罢遂为郎。","张继 洛阳作"]]},{"n":"赋上林","d":"","s":"《史记》卷一一七《司马相如列传》","w":"上读《子虚赋》而善之，曰：「朕独不得与此人同时哉！」得意曰：「臣邑人司马相如自言为此赋。」上惊，乃召问相如。相如曰：「有是。然此乃诸侯之事，未足观也。请为天子游猎赋，赋成奏之。」上许，令尚书给笔札。相如以「子虚」，虚言也，为楚称；「乌有先生…","q":[["本为成王业，初由赋上林。","张说 对酒行巴陵作"]]},{"n":"秋风客","d":"","s":"《汉武帝故事》","w":"上幸河东，欣言中流，与群臣饮宴。顾视帝京，乃自作《秋风辞》曰：「汎楼舡兮汾河，横中流兮扬素波。箫鼓吹，发棹歌，极欢乐兮哀情多。」","q":[["酆镐谁将敌，横汾未可方。","宋若宪 奉和御制麟德殿宴百官"],["岂如横汾唱，其事徒骄逸。","崔元翰 奉和圣制重阳旦日百寮曲江宴示怀"]]},{"n":"汉武眼穿","d":"","s":"《汉书》卷九十七上《外戚传·孝武李夫人传》","w":"上思念李夫人不已，方士齐人少翁言能致其神。乃夜张灯烛，设帷帐，陈酒肉，而令上居他帐，遥望好女如李夫人之貌，还幄坐而步。又不得就视，上愈益相思悲感，为作诗曰：「是邪，非邪？立而望之，偏何姗姗其来迟！」令乐府诸音家弦歌之。","q":[["亚水依岩半倾侧，笼云隐雾多愁绝。绿珠语尽身欲投，汉武眼穿神渐灭。","元稹 山枇杷"],["纵有迎仙术，终悲隔绛纱。","窦叔向 贞懿皇后挽歌三首之二"]]},{"n":"卫娘","d":"","s":"《史记》卷四十九《外戚世家》","w":"卫皇后字子夫，生微矣。盖其家号曰卫氏出平阳侯邑。子夫为平阳主讴者。武帝初即位，数岁无子。平阳主求诸良家子女十馀人，饰置家。武帝祓霸上还，因过平阳主。主见所侍美人。上弗说。既饮，讴者进，上望见，独说卫子夫。是日，武帝起更衣，子夫侍尚衣轩中，得…","q":[["瑶房侍寝世莫知，金屋更衣人不见。","崔颢 郸邯宫人怨"],["子夫前入侍，飞燕复当时。","武平一 妾薄命"]]},{"n":"杨仆移关","d":"","s":"《汉书》卷六《武帝纪》","w":"「三年冬，徙函谷关于新安。以故关为弘农县。」东汉·应劭注：「时楼船将军杨仆数有大功，耻为关外民，上书乞徙东关，以家财给其用度。武帝意亦好广阔，于是徙关于新安，去弘农三百里。」","q":[["阮郎无复里中旧，杨仆却为关外人。","刘禹锡 寄杨虢州与之旧姻"],["杨仆移关三百里，可能全是为荆山。","李商隐 荆山"]]},{"n":"桂馆求仙","d":"","s":"《汉书》卷二十五下《郊祀志下》","w":"公孙卿曰：「仙人可见，上往常遽，以故不见。今陛下可为馆如缑氏城，置脯枣，神人宜可致。且仙人好楼居。」于是上令长安则作飞廉、桂馆，甘泉则作益寿、延寿馆，使卿持节设具而候神人。","q":[["竹宫时望拜，桂馆或求仙。","杜甫 覆舟二首"]]},{"n":"倾城色","d":"","s":"《汉书》卷九十七上〈外戚列传上·孝武李夫人〉～395～","w":"孝武李夫人，本以倡进。初，夫人兄延年性知音，善歌舞，武帝爱之。每为新声变曲，闻者莫不感动。延年侍上起舞，歌曰：「北方有佳人，绝世而独立，一顾倾人城，再顾倾人国。宁不知倾城与倾国，佳人难再得！」上叹息曰：「善！世岂有此人乎？」平阳主因言延年有…","q":[["一从屠贵妃，生女愁倾国。","于濆 马嵬驿"],["倾国倾城汉武帝，为云为雨楚襄王。古来容光人所羡，况复今日遥相见。","刘希夷 公子行"]]},{"n":"汉后藏钩","d":"","s":"旧题汉·刘向《列仙传》卷下《钩翼夫人》","w":"钩翼夫人，齐人也。姓赵。少好清净，病卧六年，右手捲，饮食少。汉武帝时，望气者云东北有贵人气。推而得之，召到。姿色甚伟，武帝发其手，而得玉钩。手得展，幸之，生昭帝。","q":[["楚妃交荐枕，汉后共藏阄。","李商隐 拟意"]]},{"n":"茂陵金碗","d":"","s":"《太平御览》七五九卷","w":"旧题东汉·班固《汉武帝故事》：上崩后，鄠县有一人于市货玉杯，吏欲捕之，因忽不见。县送其器，推问，茂陵中物。霍光呼问，说市人形貌如先帝。（据《太平御览》七五九卷引）","q":[["昨日玉鱼蒙葬地，早时金碗出人间。","杜甫 诸将五首"],["汉陵帝子黄金碗，晋代神仙白玉棺。","戴叔伦 赠徐山人"]]},{"n":"汉失中策","d":"","s":"《汉书》卷九十四下《匈奴传下》","w":"王莽伐匈奴，「莽将严尤谏曰：『臣闻匈奴为害，所从来久矣，未闻上世有必征之者也。后世三家周、秦、汉征之，然皆未有得上策者也。周得中策，汉得下策，秦无策焉。当周宣王时，猃狁内侵，至于泾阳，命将征之，尽境而还。其视戎狄之侵，譬犹蚊虻之螫，驱之而已…","q":[["汉家失中策，胡马屡南驱。","陈子昂 答韩使同在边"]]},{"n":"汉武爱祈祷","d":"","s":"《汉书》卷十二《孝武本纪》","w":"「孝武皇帝者，孝景中子也。母曰王太后。孝景四年，以皇子为胶东王。孝景七年，栗太子废为临江王，以胶东王为太子。孝景十六年崩，太子即位，为孝武皇帝。孝武皇帝初即位，尤敬鬼神之祀。」「是时，上求神君，舍之上林中蹄氏观。」「是时而李少君亦以祠灶、谷…","q":[["轩皇重斋拜，汉武爱祈祷。","沈佺期 同工部李侍郎适访司马（一本此下有先生二字）子微"]]},{"n":"汉武射蛟","d":"","s":"《汉书》卷六《武帝纪》","w":"五年冬，行南巡狩，至于盛唐，望祀虞舜于九嶷。登潜天柱山，自寻阳浮江，亲射蛟江中，获之。","q":[["祖龙浮海不成桥，汉武寻阳空射蛟。","李白 永王东巡歌十一首之九"]]},{"n":"汉武巡","d":"","s":"《汉书》卷十二《孝武本纪》","w":"其明年冬（元封五年），上巡南郡至江陵而东。","q":[["未枉周王驾，终期汉武巡。","杜甫 江陵望幸（肃宗上元元年。置南都于荆州。号江陵府。以吕諲为尹。寻罢。广德元年。复以卫伯玉尹江陵。）"],["周成会西土，汉武幸南都。","张说 奉和圣制爱因巡省途次旧居应制"]]},{"n":"鸿鳞","d":"","s":"《汉书》卷五十四〈李广苏建列·苏建·（子）苏武〉～2466～","w":"数月，昭帝即位。数年，匈奴与汉和亲。汉求武等，匈奴诡言武死。后汉使复至匈奴，常惠请其守者与俱，得夜见汉使，具自陈道。教使者谓单于，言天子射上林中，得雁，足有系帛书，言武等在某泽中。使者大喜，如惠语以让单于。单于视左右而惊，谢汉使曰：「武等实…","q":[]},{"n":"淮南食时","d":"","s":"《汉书》卷四十四《淮南王传》","w":"淮南王安为人好读书鼓琴，不喜弋猎狗马驰骋，亦欲以行阴德拊循百姓，流誉天下。……时武帝方好艺文，以安属为诸父，辩博善为文辞，甚尊重之。每为报书及赐，常召司马相如等视草乃遣。初，安入朝，献所作内篇，新出，上爱秘之。使为《离骚传》，旦受诏，日食时…","q":[["淮南食时，左思十稔。","李瀚 蒙求"]]},{"n":"黄金屋","d":"黄金屋：喻女子所居之华丽宫室。唐李白《怨情》：“请看陈后黄金屋，寂寂珠帘生网丝。”","s":"《太平御览》卷八十八〈皇王部十三·汉·孝武皇帝〉～549～2～","w":"旧题汉·班固《汉武帝故事》：「数岁，长公主嫖抱置膝上，问曰：『儿欲得妇不？』胶东王曰：『欲得妇。』长主指左右长御百馀人，皆云不用。末指其女问曰：『阿娇好不？』于是乃笑对曰：『好！若得阿娇作妇，当作金屋贮之也。』长主大悦；乃苦要上，遂成婚焉。…","q":[["自伤白发辞金屋，许著黄衣向玉峰。","于鹄 送宫人入道归山"],["谁家更有黄金屋，深锁东风贮阿娇。","何希尧 海棠"]]},{"n":"蛟龙匣","d":"","s":"《西京杂记》卷一","w":"汉帝送死皆珠襦玉匣、匣形如铠甲，连以金镂，武帝匣上皆镂为蛟龙鸾凤龟龙之象，世谓为蛟龙玉匣。","q":[["平生白羽扇，零落蛟龙匣。","杜甫 八哀诗故司徒李公光弼"],["风送蛟龙雨，天长骠骑营。","杜甫 哭严仆射归榇"]]},{"n":"劫火烧","d":"劫灰：喻灾难后的遗迹。唐韩偓《寄禅师》：“劫灰聚散铁辎墨，日御奔驰茧栗红。”","s":"南朝梁·释慧皎《高僧传》卷一《汉洛阳白马寺竺法兰》","w":"「昔汉武穿昆明池底得黑灰。以问东方朔，朔云不委，可问西域人。后法兰既至，众人追以问之，兰云：『世界终尽劫火洞烧，此灰是也。』」","q":[["下辇登三袭，褰旒望九垓。林披馆陶榜，水浸昆明灰。","刘宪 奉和幸三会寺应制"],["劫灰难问理，岛树偶知名。","朱庆馀 省试晦日与同志昆明池泛舟"]]},{"n":"芝房雅奏","d":"","s":"《汉书》卷六〈武帝纪〉～93～","w":"（元封二年）六月，诏曰：「甘泉宫内中产芝，九茎连叶。上帝博临，不异下房，赐朕弘休。其赦天下，赐云阳都百户牛酒。」作〈芝房之歌〉。唐·颜师古注：「应劭曰：『芝，芝草也，其叶相连。』如淳曰：『〈瑞应图〉王者敬事耆老，不失旧故，则芝草生。』师古曰…","q":[]},{"n":"昆明习战","d":"","s":"《汉书》卷六〈武帝纪〉～77～","w":"发谪吏穿昆明池。晋·臣瓒注：「《西南夷传》有越巂、昆明国，有滇池，方三百里。汉使求身毒国，而为昆明所闭。今欲伐之，故作昆明池象之，以习水战，在长安西南，周回四十里。」","q":[["武帝伐昆明，穿池习五兵。","沈佺期 昆明池侍宴应制"],["炎历事边陲，昆明始凿池。","苏颋 奉和晦日幸昆明池应制"]]},{"n":"李夫人","d":"","s":"《汉书》卷九十七上《外戚传上·孝武李夫人传》","w":"「孝武李夫人，本以倡进。初，夫人兄延年性知音，善歌舞，武帝爱之。每为新声变曲，闻者莫不感动。延年侍上起舞，歌曰：『北方有佳人，绝世而独立，一顾倾人城，再顾倾人国。宁不知倾城与倾国，佳人难再得！』上叹息曰：『善！世岂有此人乎？』平阳主因言延年…","q":[["秾艳三千临粉镜，独悲掩面李夫人。","司空图 力疾山下吴村看杏花十九首之十"],["屏上楼台陈后主，镜中金翠李夫人。","温庭筠 和道溪君别业"]]},{"n":"李延年","d":"","s":"《汉书》卷九十三《佞幸传·李延年传》","w":"「李延年，中山人，身及父母兄弟皆故倡也。延年坐法腐刑，给事狗监中。女弟得幸于上，号李夫人，列外戚传。延年善歌，为新变声。是时上方兴天地诸祠，欲造乐，令司马相如等作诗颂。延年辄承意弦歌所造诗，为之新声曲。而李夫人产昌邑王，延年繇是贵为协律都尉…","q":[["若逢汉武帝，还是李延年。","梁锽 戏赠歌者"],["延年女弟双凤入，罗敷使君千骑归。","骆宾王 帝京篇"]]},{"n":"梁王驷马","d":"","s":"《艺文类聚》卷五十六","w":"《古文苑》卷八《柏梁诗并序》：汉武帝元封三年作柏梁台，诏群臣二千石，有新为七言诗乃得上座：「日月星辰和四时（皇帝），骖驾驷马从梁（梁王）来。」","q":[["都尉仙凫远，梁王驷马来。","李峤 诗"],["叶令双凫至，梁王驷马来。","李元操 和从叔禄愔元日早朝"]]},{"n":"龙媒","d":"","s":"《汉书》卷二十二《礼乐志》","w":"《天马歌》：「天马徕，龙之媒。」东汉·应劭注：「言天马者乃神龙之类，今天马已来，此龙必至之效也。」","q":[["买得龙媒越水濆，轻桃细杏色初分。","刘威 伤曾秀才马"],["紫云团影电飞瞳，骏骨龙媒自不同。","唐彦谦 咏马二首"]]},{"n":"楼居","d":"","s":"《汉书》卷二十五下《郊祀志下》","w":"「公孙卿曰：『仙人可见，而上往常遽，以故不见。今陛下可为观，如缑城，置脯枣，神人宜可致也。且仙人好楼居。』于是上令长安则作蜚廉桂观，甘泉则作益延寿观，使卿持节设具而候神人。」","q":[["须为下殿走，不可好楼居。","杜甫 收京三首之一"],["楼居五云里，几与武皇登。","卢纶 送道士郤彝素归内道场"]]},{"n":"曼倩风流","d":"","s":"《太平御览》卷一百八十八〈居处部十六·〉～039～2～","w":"《汉武故事》：「西王母降，东方朔于朱雀牖中窥母，母谓帝曰：『此儿无赖，久被斥逐，原心无恶，寻当得还。』」","q":[]},{"n":"茂陵滞骨","d":"","s":"《汉武帝内传》","w":"王母乃遣侍女郭密香与上元夫人相问云：「……刘彻好道，适来视之，见彻了了，似可成进，然形慢神秽，脑血淫漏不淳，关胄彭孛，骨无津液，脉浮反升，肉多精少，瞳子不夷，三尸狡乱，玄白失时，虽当与之以至道，始恐非仙才也。","q":[["每怀仙驾远，更望茂陵号。","李德裕 述梦四十韵"],["刘彻茂陵多滞骨，嬴政梓棺费鲍鱼。","李贺 苦昼短"]]},{"n":"千里驹","d":"","s":"《楚辞补注》卷六〈卜居〉～76～","w":"屈原既放三年，不得复见，竭智尽忠，蔽鄣于谗。心烦意乱，不知所从乃往见太卜郑詹尹，曰：「余有所疑，愿因先生决之。」詹尹乃端策拂龟，曰：「君将何以教之？」屈原曰：吾宁悃悃款款，朴以忠乎？将送往劳来，斯无穷乎？宁诛锄草茅，以力耕乎？将游大人，以成…","q":[]},{"n":"平阳","d":"","s":"《史记》卷一一一《卫将军骠骑列传》","w":"「大将军卫青者，平阳人也。……而姊卫子夫自平阳公主家得幸天子。」南朝宋·裴骃《史记集解》：「徐广曰：『曹参曾孙平阳夷侯，时尚武帝姊平阳公主，生子襄。』唐·司马贞《史记索隐》：『案：如淳云「本阳信长公主，为平阳侯所尚，故称平阳公主」。按徐广云…","q":[["虚然异风出，髣髴宿平阳。","丁仙芝 剡溪西馆闻笛"],["平阳旧池馆，寂寞使人愁。","丁仙芝 长宁公主旧山池"]]},{"n":"平阳拊背","d":"","s":"《史记》卷四十九《外戚世家》","w":"（武帝）既饮，讴者进，上望见，独说卫子夫。是日，武帝起更衣，子夫侍尚衣轩中，得幸。上还坐，驩甚。赐平阳主金千斤。主因奏子夫奉送入宫。子夫上车，平阳主拊其背曰：「行矣，彊饭，勉之！即贵，无相忘。」","q":[["平阳拊背穿驰道，铜雀分香下璧门。","杜牧 出宫人二首"]]},{"n":"蒲车","d":"","s":"《汉书》卷五十一《枚乘传》","w":"武帝自为太子闻乘名，及即位，乘年老，乃以安车蒲轮徵乘，道死。","q":[["回看药灶封题密，强入蒲轮引步迟。","戎昱 赠韦况徵君"],["一朝下蒲轮，清辉照岩廊。","李群玉 自澧浦东游江表途出巴丘投员外从公虞"]]},{"n":"千金价","d":"","s":"《史记》卷一百二十三〈大宛列传〉～374～","w":"而汉使者往既多，其少从率多进熟于天子，言曰：「宛有善马在贰师城，匿不肯与汉使。」天子既好宛马，闻之甘心，使壮士车令等持千金及金马以请宛王贰师城善马。","q":[]},{"n":"青鸟独来","d":"","s":"《太平御览》卷一百三十六〈皇亲部二·汉·孝昭赵太后〉～790～2～","w":"旧题东汉·班固《汉武帝故事》：上巡狩过河间，见有青紫气自地属天。望气者以为其下有奇女，必天子之祥。求之，见一女子在空馆中，姿貌殊绝，两手一拳。上令开其手，数百人擘莫能开，上自披，手即申。由是得幸，为拳夫人。进为婕妤，居钩弋宫。解皇帝素女之术…","q":[["通灵深眷想，青鸟独飞来。","钱起 贞懿皇后挽词"]]},{"n":"如刻画","d":"","s":"《汉书》卷六十九《赵充国传》","w":"「赵充国字翁孙，陇西上邽人也。」「武帝时，以假司马从贰师将军击匈奴，大为虏所围。汉军乏食数日，死伤者多，充国乃与壮士百馀人溃围陷陈，贰师引兵随之，遂得解。身被二十馀创，贰师奏状，诏徵充国诣行在所。武帝亲见视其创，嗟叹之，拜为中郎，迁车骑将军…","q":[["唯有老身如刻画，犹期圣主解衣看。","李端 题故将军庄"]]},{"n":"青鸟使","d":"青鸟：指神仙，或爱情的使者。唐李侨《拟古东飞伯劳西飞燕》：“传书青鸟迎萧凤，巫岭荆台一通梦。”","s":"《山海经·山经》卷二〈西山经〉～54～","w":"又西二百二十里，曰三危之山，三青鸟居之。郭璞云：「三青鸟主为西王母取食者，别自栖息于此山也。」","q":[["寄音青鸟翼，谢尔碧海流。","刘复 游仙"],["得意紫鸾休舞镜，断踪青鸟罢衔笺。","刘损 愤惋诗三首"]]},{"n":"上林","d":"","s":"《三辅黄图》","w":"汉上林苑，即秦之旧苑也。汉书云武帝建元三年开上林苑。","q":[]},{"n":"少壮几时奈老何","d":"","s":"《昭明文选》卷四十五汉武帝（刘彻）《秋风辞》","w":"秋风起兮白云飞。草木黄落兮雁南归。兰有秀兮菊有芳。携佳人兮不能忘。泛楼舡兮济汾河。横中流兮扬素波。箫鼓鸣兮发棹歌。欢乐极兮哀情多。少壮几时兮奈老何。","q":[["少壮几时奈老何，向来哀乐何其多。","杜甫 渼陂行"]]},{"n":"射蛟","d":"","s":"《汉书》卷六《武帝纪》","w":"（元封）五年冬，行南巡狩，至于盛唐，望祀虞舜于九嶷。登天柱山，自寻阳浮江，亲射蛟江中，获之。","q":[["自从献宝朝河宗，无复射蛟江水中。","杜甫 韦讽录事宅观曹将军画马图"]]},{"n":"神光烛","d":"","s":"《汉书》卷六〈武帝纪〉～95～","w":"四年冬十月，行幸雍，祠五畤。通回中道，遂北出萧关，历独鹿、鸣泽，自代而还，幸河东。春三月，祠后土。诏曰：「朕躬祭后土地祇，见光集于灵坛，一夜三烛。幸中都宫，殿上见光。其赦汾阴、夏阳、中都死罪以下，赐三县及杨氏皆无出今年租赋。」","q":[["姹女临波日，神光照夜年。","杜甫 覆舟三首"]]},{"n":"十洲","d":"","s":"《海内十洲记》","w":"汉武帝既闻王母说：八方巨海之中，有祖洲、瀛洲、玄洲、炎洲、长洲、元洲、流洲、生洲、凤麟洲、聚窟洲。有此十洲，乃人迹所稀绝处。祖洲，近在东海之中，地方五百里，去西岸七百里，上有不死之草。……玄洲在北海之中，戌亥之地，方七千二百里，去南岸三十六…","q":[["百越酋豪称故吏，十洲风景助新诗。","刘禹锡 马大夫见示浙西王侍御赠答诗因命同作并序"],["鸾凤戏三岛，神仙居十洲。","李商隐 牡丹"]]},{"n":"受降城","d":"","s":"《史记》卷一百十〈匈奴列传〉～295～","w":"是岁，汉使贰师将军广利西伐大宛，而令因杅将军敖筑受降城。其冬，匈奴大雨雪，畜多饥寒死。儿单于年少，好杀伐，国人多不安。左大都尉欲杀单于，使人閒告汉曰：「我欲杀单于降汉，汉远，即兵来迎我，我即发。」初，汉闻此言，故筑受降城，犹以为远。","q":[["斩虏还遮塞，绥降更筑城。","裴漼 奉和御制旋师喜捷"],["受降追汉策，筑馆许戎和。","赵彦昭 奉和送金城公主适西蕃应制"]]},{"n":"嵩山万岁","d":"","s":"《汉书》卷六《武帝纪》","w":"「元封元年冬十月，诏曰：『南越、东瓯咸伏其辜，西蛮北夷颇未辑睦，朕将巡边垂，择兵振旅，躬秉武节，置十二部将军，亲帅师焉。』行自云阳，北历上郡、西河、五原，出长城，北登单于台，至朔方，临北河。勒兵十八万骑，旌旗径千馀里，威震匈奴。遣使者告单于…","q":[["但听嵩山万岁声，将军旗鼓何时偃。","李咸用 煌煌京洛行"]]},{"n":"脱屣","d":"","s":"《史记》卷十二《孝武本纪》","w":"卿曰：「申功，齐人也。与安期生通，受黄帝言，无书，独有此鼎书。曰『汉兴复当黄帝之时。汉之圣者在高祖之孙且曾孙也。宝鼎出而与神通，封禅。封禅七十二王，唯黄帝得上泰山封』。申功曰：『汉主亦当上封，上封则能仙登天矣。黄帝时万诸侯，而神灵之封居七千…","q":[["仙成脱屣去，臣恋捧弓号。","刘禹锡 浙西李大夫述梦四十韵并浙东元相公酬和斐然继声"],["忘缘祛天机，脱屐恨不早。","独孤及 早发若岘驿望庐山"]]},{"n":"望仙台","d":"","s":"《三辅黄图》卷三《甘泉宫》","w":"集灵宫、集仙宫、存仙殿、存神殿、望仙台、望仙观，俱在华阴县界，皆武帝宫观名也。","q":[["天寒邵伯树，地阔望仙台。","杜甫 巴山"],["一宅柳花今似雪，乡人拟筑望仙台。","窦常 过宋氏五女旧居"]]},{"n":"卫幕","d":"","s":"《汉书》卷五十四〈李广苏建列传·李广〉～244～","w":"武帝即位，左右言广名将也，由是入为未央卫尉，而程不识时亦为长乐卫尉。程不识故与广俱以边太守将屯。及出击胡，而广行无部曲行陈，就善水草顿舍，人人自便，不击刁斗自莫府省文书，然亦远斥候，未尝遇害。」晋·晋灼注：「将军职在征行，无常处，所在为治，…","q":[["卫幕衔恩重，潘舆送喜频。","杜甫 奉贺阳城郡王太夫人恩命加邓国太夫人"],["卫青开幕府，杨仆将楼船。","杜甫 广州段功曹到得杨五长史谭书功曹却归聊寄此诗"]]},{"n":"武库","d":"","s":"《史记》卷六十〈三王世家〉～24～","w":"褚先生曰：夫人者，赵人也，与卫夫人并幸武帝，而生子闳。闳且立为王时，其母病，武帝自临问之。曰：「子当为王，欲安所置之？」王夫人曰：「陛下在，妾又何等可言者。」帝曰：「虽然，意所欲，欲于何所王之？」王夫人曰：「愿置之雒阳。」武帝曰：「雒阳有武…","q":[["教用儒门俭，兵依武库雄。","耿湋 奉送蒋尚书兼御史大夫东都留守"]]},{"n":"萧关北上","d":"","s":"《汉书》卷六《武帝纪》","w":"（元封）四年冬十月，行幸雍，祠五畤。通回中道，遂北出萧关，历独鹿、鸣泽，自代而还，幸河东。","q":[["萧关迷北上，沧海欲东巡。","杜甫 伤春五首之四"]]},{"n":"一言悟主","d":"","s":"《汉书》卷六十六《车千秋传》","w":"会卫太子为江充所谮败，久之，千秋上急变讼太子冤，曰：「子弄父兵，罪当笞；天子之子过误杀人，当何罪哉！臣尝梦见一白头翁教臣言。」是时，上颇知太子惶恐无他意，乃大感寤，召见千秋。至前，千秋长八尺馀，体貌甚丽，武帝见而说之，谓曰：「父子之间，人所…","q":[["悟主一言那可学，从军五首竟徒为。","窦牟 秋夕闲居对雨赠别卢七侍御坦"]]},{"n":"影娥池","d":"","s":"《三辅黄图》卷四《池沼》","w":"武帝凿池以玩月，其旁起望鹄台以眺月，影入池中，使宫人乘舟弄月影。名影娥池，亦曰眺蟾台。","q":[["花明栖凤阁，珠散影娥池。","上官仪 咏雪应诏"]]},{"n":"之罘","d":"","s":"《汉书》卷六〈武帝纪〉～206～","w":"幸琅邪，礼日成山。登之罘，浮大海。山称万岁。冬，赐行所过户五千钱，寡孤独帛人一匹。」晋·晋灼注：「《地理志》：东莱腄县有之罘山祠。」","q":[["之罘称万岁，今此复同声。","张九龄 奉和圣制早登太行山率尔言志"],["之罘思汉帝，碣石想秦皇。","李世民 春日望海"]]},{"n":"朱雁","d":"","s":"《汉书》卷六《武帝纪》","w":"太始三年，「行幸东海，获赤雁，作朱雁之歌。」","q":[["池籞呈朱雁，坛场得白麟。","元稹 代曲江老人百韵（年十六时作）"]]},{"n":"侏儒饱","d":"侏儒饱：喻小人得志而贤才受屈。元朱旭《杂诗》之二：“长身素米侏儒饱，飞将无功妄尉侯。”；曼倩饥：咏人生活清贫。唐许浑《早秋三首》之二：“老信相如渴，贫忧曼倩饥。”","s":"《汉书》卷六十五〈东方朔列传〉","w":"「朔文辞不逊，高自称誉，上伟之，令待诏公车，奉禄薄，未得省见。久之，朔绐驺朱儒，曰：「上以若曹无益于县官，耕田力作固不及人，临众处官不能治民，从军击虏不任兵事，无益于国用，徒索衣食，今欲尽杀若曹。」朱儒大恐，啼泣。朔教曰：「上即过，叩头请罪…","q":[["奸声入耳佞入心，侏儒饱饭夷齐饿。","元稹 立部伎"],["只取侏儒饱，不怜方朔饿。","寒山 诗三百三首"]]},{"n":"竹宫望拜","d":"","s":"《汉书》卷二十二《礼乐志》","w":"「以正月上辛用事甘泉圜丘，使童男女七十人俱歌，昏祠至明。夜常有神光如流星止集于祠坛，天子自竹宫而望拜，百官侍祠者数百人皆肃然动心焉。」三国吴·韦昭注：「以竹为宫，天子居中。」唐·颜师古注：「《汉旧仪》云竹宫去坛三里。」","q":[["竹宫时望拜，桂馆或求仙。","杜甫 覆舟二首"]]}],"2":[{"n":"黄绮","d":"四老：称美年高德劭者。唐张说《赠崔公》：“我闻西汉日，四老南山幽。”","s":"《汉书》卷七十二〈王贡两龚鲍传〉～3056～","w":"汉兴有园公、绮里季、夏黄公、甪里先生，此四人者，当秦之世，避而入商雒深山，以待天下之定也。自高祖闻而召之，不至。其后吕后用留侯计，使皇太子卑辞束帛致礼，安车迎而致之。四人既至，从太子见，高祖客而敬焉，太子得以为重，遂用自安。语在留侯传。","q":[["独忆紫芝叟，临风歌旧歌。","于邺 斜谷道"],["得道南山久，曾教四皓棋。","于鹄 题南峰（一作终南）褚道士（一作尊师）"]]},{"n":"安刘","d":"","s":"《史记》卷八《高祖本纪》","w":"「高祖击布时，为流矢所中，行道病。病甚，吕后迎良医，医入见，高祖问医，医曰：『病可治。』于是高祖嫚骂之曰：『吾以布衣提三尺剑取天下，此非天命乎？命乃在天，虽扁鹊何益！』遂不使治病，赐金五十斤罢之。已而吕后问：『陛下百岁后，萧相国即死，令谁代…","q":[["诛吕鬼神动，安刘天地开。","高适 酬裴员外以诗代书"]]},{"n":"白马子婴","d":"","s":"《史记》卷八《高祖本纪》","w":"汉元年十月，沛公兵遂先诸侯至霸上。秦王子婴素车白马，系颈以组，封皇帝玺符节，降轵道旁。","q":[["素灵感刘季，白马从子婴。","张良璞 览史"]]},{"n":"柏人诫","d":"","s":"《史记》卷八十九〈张耳陈馀列传〉～2583～","w":"汉七年，高祖从平城过赵，赵王朝夕袒鞲蔽，自上食，礼甚卑，有子婿礼。高祖箕踞詈，甚慢易之。赵相贯高、赵午等年六十馀，故张耳客也。生平为气，乃怒曰：「吾王孱王也！」说王曰：「夫天下豪桀并起，能者先立。今王事高祖甚恭，而高祖无礼，请为王杀之！」张…","q":[["万乘慎出入，柏人以为诫。","李白 枯鱼过河泣"]]},{"n":"追亡","d":"","s":"《史记》卷九十二〈淮阴侯列传〉～26～","w":"信数与萧何语，何奇之。至南郑，诸将行道亡者数十人，信度何等已数言上，上不我用，即亡。何闻信亡，不及以闻，自追之。人有言上曰：「丞相何亡。」上大怒，如失左右手。居一二日，何来谒上，上且怒且喜，骂何曰：「若亡，何也？」何曰：「臣不敢亡也，臣追亡…","q":[["公议今如此，登坛到即行。","姚合 赠卢大夫将军"],["儒有登坛贵，何人得此功。","姚合 送郑尚书赴兴元"]]},{"n":"汉主冠","d":"","s":"《汉书》卷一上《高帝纪上》","w":"「高祖为亭长，乃以竹皮为冠，令求盗之薛治之，时时冠之，及贵常冠，所谓『刘氏冠』乃是也。」东汉·应劭注：「以竹始生皮作冠，今鹊尾冠是也。求盗者，旧时亭有两卒，其一为亭父，掌开闭埽除，一为求盗，掌逐捕盗贼。薛，鲁国县也。有作冠师，故往治之。」","q":[["可惜班皮空满地，无人解取作头冠。","李涉 头陀寺看竹"],["翠筠不乐湘娥泪，斑箨堪裁汉主冠。","王睿 竹"]]},{"n":"成羽翼","d":"","s":"《史记》卷五十五〈留侯世家〉～2046～","w":"汉十二年，上从击破布军归，疾益甚，愈欲易太子。留侯谏，不听，因疾不视事。叔孙太傅称说引古今，以死争太子。上详许之，犹欲易之。及燕，置酒，太子侍。四人从太子，年皆八十有馀，须眉皓白，衣冠甚伟。上怪之，问曰：「彼何为者？」四人前对，各言名姓，曰…","q":[]},{"n":"赤精","d":"","s":"《汉书》卷十一《哀帝纪》","w":"「侍诏夏贺良等言赤精子之谶，汉家历运中衰，当再受命，宜改元易号。诏曰：『汉兴二百载，历数开元。皇天降非材之佑，汉国再获受命之符，朕之不德，曷敢不通！夫基事之元命，必与天下自新，其大赦天下。以建平二年为太初元将元年。号曰陈圣刘太平皇帝。漏刻以…","q":[["赤精既迷汉，子年何救秦。","陈子昂 感遇诗三十八首之九"],["复闻赤精子，提剑入咸京。","陈子昂 感遇诗三十八首之十七"]]},{"n":"赤龙子","d":"赤龙子：喻指帝王。唐李贺《公莫舞歌》：“材官小臣公莫舞，座上真人赤龙子。”","s":"《史记》卷八〈高祖本纪〉～347～","w":"高祖以亭长为县送徒郦山，徒多道亡。自度比至皆亡之，到丰西泽中，止饮，夜乃解纵所送徒。曰：「公等皆去，吾亦从此逝矣！」徒中壮士愿从者十馀人。高祖被酒，夜径泽中，令一人行前。行前者还报曰：「前有大蛇当径，愿还。」高祖醉，曰：「壮士行，何畏！」乃…","q":[["火德道将亨，夜逢蛇母哭。","于濆 秦原览古"],["赤龙已赴东方暗，黄犬徒怀上蔡悲。","储嗣宗 长安怀古"]]},{"n":"松乔","d":"","s":"《搜神记》卷一～","w":"赤松子者，神农时雨师也，服冰玉散，以教神农，能入火不烧。至昆崙山，常入西王母石室中，随风雨上下。炎帝少女追之，亦得仙，俱去。至高辛时，复为雨师，游人间。今之雨师本是焉。","q":[["自有园公紫芝侣，仍追少傅赤松游。","刘禹锡 自左冯归洛下酬乐天兼呈裴令公"],["向夕便思青琐拜，近年寻伴赤松游。","姚合 使两浙赠罗隐"]]},{"n":"赤帜雄张军缟素","d":"","s":"《史记》卷九十二〈淮阴侯列传〉～266～","w":"信所出奇兵二千骑，共候赵空壁逐利，则驰入赵壁，皆拔赵旗，立汉赤帜二千。赵军已不胜，不能得信等，欲还归壁，壁皆汉赤帜，而大惊，以为汉皆已得赵王将矣，兵遂乱，遁走，赵将虽斩之，不能禁也。于是汉兵夹击，大破虏赵军，斩成安君泜水上，禽赵王歇。","q":[]},{"n":"舂市徒","d":"","s":"《汉书》卷九十七上《外戚传上·高祖吕皇后传》","w":"后汉王得定陶戚姬，爱幸，生赵隐王如意。太子为人仁弱，高祖以为不类己，常欲废之而立如意，「如意类我」。戚姬常从上之关东，日夜啼泣，欲立其子。吕后年长，常留守，希见，益疏。如意且立为赵王，留长安，几代太子者数。赖公卿大臣争之，及叔孙通谏，用留侯…","q":[["戚姬髡剪入舂市，万古共悲辛。","李白 中山孺子妾歌"],["昔称夭桃子，今为舂市徒。","陈子昂 感遇诗三十八首之十五"]]},{"n":"出平城","d":"","s":"《史记》卷九十三《韩信列传》","w":"「信亡走匈奴。」「高皇帝居晋阳，使人视冒顿，还报曰『可击』。上遂至平城。上出白登，匈奴骑围上，上乃使人厚遗阏氏。阏氏乃说冒顿曰：『……』居七日，胡骑稍引去。时天大雾，汉使人往来，胡不觉。护军中尉陈平言上曰：『胡者全兵，请令彊弩傅两矢外向，徐…","q":[["曹公迷楚泽，汉帝出平城。","李峤 雾"]]},{"n":"大风歌","d":"大风歌：咏帝王，或指慷慨悲歌及治国安邦之志。唐杜甫《伤春五首》之五：“得无中夜舞，谁忆大风歌？”；歌大风：喻治国安邦之情怀。唐李世民《过旧宅二首》之二：“八表文同轨，无劳歌大风。”","s":"《史记》卷八〈高祖本纪〉～389～","w":"高祖还归，过沛，留。置酒沛宫，悉召故人父老子弟纵酒，发沛中儿得百二十人，教之歌。酒酣，高祖击筑，自为歌诗曰：「大风起兮云飞扬，威加海内兮归故乡，安得猛士兮守四方！」令儿皆和习之。高祖乃起舞，慷慨伤怀，泣数行下。谓沛父兄曰：「游子悲故乡。吾虽…","q":[["大风迎汉筑，丛烟入舜球。","上官仪 奉和过旧宅应制"],["延襟小山路，还起大风歌。","刘祎之 奉和别越王"]]},{"n":"带砺山河","d":"","s":"《史记》卷十八〈高祖功臣侯者年表〉～877～","w":"太史公曰：古者人臣功有五品，以德立宗庙定社稷曰勋，以言曰劳，用力曰功，明其等曰伐，积日曰阅。封爵之誓曰：「使河如带，泰山若厉。国以永宁，爰及苗裔。」始未尝不欲固其根本，而枝叶稍陵夷衰微也。","q":[["回看带砺山河者，济得危时没旧勋。","吴融 闲书"],["岂要黄河誓，须勒燕然石。","崔湜 塞垣行"]]},{"n":"砀瑞","d":"","s":"《史记》卷八《高祖本纪》","w":"秦始皇帝常曰「东南有天子气」，于是因东游以厌之。高祖即自疑，亡匿，隐于芒、砀山泽岩石之閒。吕后与人俱求，常得之。高祖怪问之。吕后曰：「季所居上常有云气，故从往常得季。」高祖心喜。沛中子弟或闻之，多欲附者矣。","q":[["色泛临砀瑞，香流赴蜀仙。","骆宾王 咏云酒"],["云浮非隐帝，日举类游童。","骆宾王 过故宋"]]},{"n":"两贤岂相厄","d":"","s":"《史记》卷一○○《季布列传》","w":"季布母弟丁公，为楚将。丁公为项羽逐窘高祖彭城西，短兵接，高祖急，顾丁公曰：「两贤岂相厄哉！」于是丁公引兵而还，汉王遂解去。及项王灭，丁公谒见高祖。高祖以丁公徇军中，曰：「丁公为项王臣不忠，使项王失天下者，乃丁公也。」遂斩丁公，曰：「使后世为…","q":[["丁公遽戮，雍齿先侯。","李瀚 蒙求"]]},{"n":"功狗","d":"功人：喻谋臣。清王昙《留候词》：“功人功狗两无益，徒受亭公谩骂名。”；功臣狗：喻武将。清赵翼《悯忠寺石一坛相传唐太宗葬战骨处》：“岂乏功臣狗，兼多君子猿。”","s":"《史记》卷五十三〈萧相国世家〉～205～","w":"汉五年，既杀项羽，定天下，论功行封。群臣争功，岁馀功不决。高祖以萧何功最盛，封为酂侯，所食邑多。功臣皆曰：「臣等身被坚执锐，多者百馀战，少者数十合，攻城略地，大小各有差。今萧何未尝有汗马之劳，徒持文墨议论，不战，顾反居臣等上，何也？」高帝曰…","q":[["功人功狗两无益，徒受亭公谩骂名。","王昙 留候词"],["信越功名高似狗，裴王气力大于牛。未知至竟将何用，渭水泾川一向流。","罗隐 关亭春望"]]},{"n":"樊哙排闼","d":"","s":"《史记》卷九十五《樊哙列传》","w":"先黥布反时，高祖尝病甚，恶见人，卧禁中，诏户者无得入群臣。群臣绛、灌等莫敢入。十馀日，哙乃排闼直入，大臣随之。上独枕一宦者卧。哙等见上流涕曰：「始陛下与臣等起丰沛，定天下，何其壮也！今天下已定，又何惫也！且陛下病甚，大臣震恐，不见臣等计事，…","q":[["樊哙排闼，辛毗引裾。","李瀚 蒙求"]]},{"n":"樊哙市井","d":"","s":"《史记》卷九十五《樊哙列传》","w":"舞阳侯樊哙者，沛人也。以屠狗为事，与高祖俱隐。初从高祖起丰，攻下沛。高祖为沛公，以哙为舍人。从攻胡陵、方与，还守丰，击泗水监丰下，破之。……项羽入屠咸阳，立沛公为汉王。汉王赐哙爵为列侯，号临武侯。迁为郎中，从入汉中。还定三秦，别击西丞白水北…","q":[["屠狗兴贩缯，突起定倾危。","李商隐 井泥四十韵"],["樊哙市井徒，萧何刀笔吏。一朝时运会，千古传名谥。","李密 淮阳感怀"]]},{"n":"枌榆","d":"","s":"《史记》卷二十八《封禅书》","w":"「高祖初起，祷丰枌榆社。徇沛，为沛公，则祠蚩尤，衅鼓旗。遂以十月至灞上，与诸侯平咸阳，立为汉王。因以十月为年首，而色上赤。」南朝宋·裴骃《史记集解》：「张晏曰：枌，白榆也。社在丰东北十五里。或曰枌榆，乡名，高祖里社也。」","q":[["户蒙枌榆复，邑争牛酒欢。","张九龄 奉和圣制幸晋阳宫"],["枌榆恩赏洽，桑梓旧情恭。","张说 奉和圣制过晋阳宫应制"]]},{"n":"娄敬策","d":"","s":"《史记》卷九十九〈刘敬叔孙通列传·刘敬列传〉～277～","w":"于是上曰：「本言都秦地者娄敬，『娄』者乃『刘』也。」赐姓刘氏，拜为郎中，号为奉春君。汉七年，韩王信反，高帝自往击之。至晋阳，闻信与匈奴欲共击汉，上大怒，使人使匈奴。匈奴匿其壮士肥牛马，但见老弱及羸畜。使者十辈来，皆言匈奴可击。上使刘敬复往使…","q":[["汉祖谩誇娄敬策，却将公主嫁单于。","戴叔伦 塞上曲二首"],["当时已有吹毛剑，何事无人杀奉春。","胡曾 平城"]]},{"n":"缚楚王","d":"","s":"《史记》卷九十二《淮阴侯列传》","w":"人有上书告楚王信反。高帝以陈平计，天子巡狩会诸侯，南方有云梦，发使告诸侯会陈：「吾将游云梦。」实欲袭信，信弗知。高祖且至楚，信欲发兵反，自度无罪，欲谒上，恐见禽。人或说信曰：「斩眛谒上，上必喜，无患。」信见眛计事。眛曰：「汉所以不击取楚，以…","q":[["日旗龙旆想飘扬，一索功高缚楚王。","杜牧 云梦泽"]]},{"n":"割鸿沟","d":"","s":"《史记》卷七《项羽本纪》","w":"「项王乃与汉约，中分天下，割鸿沟以西者为汉，鸿沟而东者为楚。」南朝宋·裴骃《史记集解》：「文颖曰：『于荥阳下引河东南为鸿沟。』」唐·张守节《史记正义》：「张华云：『大梁城在浚仪县北，县西北渠水东经此城南，又北屈分为二渠。其一渠东南流，始皇凿…","q":[["搀抢扫河洛，直割鸿沟半。","李白 南奔书怀"],["大盗割鸿沟，如风扫秋叶。","李白 赠王判官时馀归隐居庐山屏风叠"]]},{"n":"关中事","d":"","s":"《史记》卷五十三《萧相国世家》","w":"「汉二年，汉王与诸侯击楚，何守关中，侍太子，治栎阳。为法令约束，立宗庙社稷宫室县邑，辄奏上，可，许以从事；即不及奏上，辄以便宜施行，上来以闻。关中事计户口转漕给军，汉王数失军遁去，何常兴关中卒，辄补缺。上以此专属任何关中事。」「后功臣争功，…","q":[["今日关中事，萧何共尔忧。","刘长卿 重阳日鄂城楼送屈突司直"]]},{"n":"韩信羞比灌","d":"","s":"《史记》卷九十二《淮阴侯列传》","w":"遂械系信。至雒阳，赦信罪，以为淮阴侯。信知汉王畏恶其能，常称病不朝从。信由此日夜怨望，居常鞅鞅，羞与绛、灌等列。","q":[["韩信羞将绛灌比，祢衡耻逐屠沽儿。","李白 答王十二寒夜独酌有怀"]]},{"n":"汉宫巫","d":"","s":"《汉书》卷二十五上《郊祀志上》","w":"长安置祠祀官、女巫。其梁巫祠天、地、天社、天水、房中、堂上之属；晋巫祠五帝、东君、云中君、巫社、巫祠、族人炊之属；秦巫祠杜主、巫保、族累之属；荆巫祠堂下、巫先、司命、施糜之属；九天巫祠九天：皆以岁时祠宫中。其河巫祠河于临晋，而南山巫祠南山、…","q":[["肠回楚国梦，心断汉宫巫。","李商隐 圣女祠"]]},{"n":"武库火","d":"","s":"南朝宋·刘敬叔《异苑》卷二","w":"晋惠帝元康五年，武库火，烧汉高祖斩白蛇剑、孔子履、王莽头等三物。中书监张茂先惧难作，列兵陈卫，咸见此剑穿屋飞去，莫知所向。","q":[["汉帝斩蛇剑，晋时烧上天。自兹繁巨蟒，往往寿千年。","元稹 巴蛇"],["晋末武库烧，脱然排户牖。为欲扫群胡，散作弥天帚。自兹失所往，豪英共为诟。今复谁人铸，挺然千载后。","元稹 说剑"]]},{"n":"汉求季布","d":"","s":"《史记》卷一○○《季布列传》","w":"季布者，楚人也。为气任侠，有名于楚。项籍使将兵，数窘汉王。及项羽灭，高祖购求布千金，敢有舍匿，罪及三族。季布匿濮阳周氏。周氏曰：「汉购将军急，且至臣家，将军能听臣，臣敢献计；即不能，愿先自刭。」季布许之。乃髡钳季布，衣褐衣，置广柳车中，并…","q":[["汉求季布鲁朱家，楚逐伍胥去章华。","李白 江上赠窦长史"]]},{"n":"汉主新丰","d":"","s":"《史记》卷八《高祖本纪》","w":"「更命郦邑曰新丰。」唐·张守节《史记正义》：「《括地志》云：『新丰故城在雍州新丰县西南四里，汉新丰宫也。太上皇时悽怆不乐，高祖窃因左右问故，答以平生所好皆屠贩少年，酤酒卖饼，斗鸡蹴鞠，以此为欢，今皆无此，故不乐。高祖乃作新丰，徙诸故人实之，…","q":[["汉主新丰邑，周王尚父师。","苏绾 奉和姚令公驾幸温汤喜雪应制"]]},{"n":"汉筑","d":"","s":"《史记》卷八《高祖本纪》","w":"高祖还归，过沛，留。置酒沛宫，悉召故人父老子弟纵酒，发沛中儿得百二十人，教之歌。酒酣，高祖击筑，自为歌诗曰：「大风起兮云飞扬，威加海内兮归故乡，安得猛士兮守四方！」令儿皆和习之。高祖乃起舞，慷慨伤怀，泣数行下。","q":[["凄风移汉筑，流水入虞琴。","上官仪 奉和山夜临秋"],["大风迎汉筑，丛烟入舜球。","上官仪 奉和过旧宅应制"]]},{"n":"鸿门","d":"","s":"《史记》卷七《项羽本纪》","w":"沛公旦日从百馀骑来见项王，至鸿门，谢曰：「臣与将军戮力而攻秦，将军战河北，臣战河南，然不自意能先入关破秦，得复见将军于此。今者有小人之言，令将军与臣有却。」项王曰：「此沛公左司马曹无伤言之；不然，籍何以至此。」项王即日因留沛公与饮。项王、项…","q":[["佐汉解鸿门，生唐为后身。","李白 赠张相镐二首之一"]]},{"n":"护汉储","d":"","s":"《汉书》卷四十《张良传》","w":"「汉十二年，上从破布归，疾益甚，愈欲易太子。良谏不听，因疾不视事。叔孙太傅称说引古，以死争太子。上阳许之，犹欲易之。及宴，置酒，太子侍。四人者从太子，年皆八十有馀，须眉皓白，衣冠甚伟。上怪，问曰：『何为者？』四人前对，各言其姓名。上乃惊曰：…","q":[["汉宫成羽翼，伊水弄参差。","储光羲 河中望鸟滩作贻吕四郎中"],["卒能匡惠帝，岂不赖留侯。","张说 赠崔公"]]},{"n":"张良烧栈","d":"","s":"《史记》卷五十五《留侯世家》","w":"汉元年正月，沛公为汉王，王巴蜀。汉王赐良金百溢，珠二斗，良具以献项伯。汉王亦因令良厚遗项伯，使请汉中地。项王乃许之，遂得汉中地。汉王之国，良送至褒中，遣良归韩。良因说汉王曰：「王何不烧绝所过栈道，示天下无还心，以固项王意。」乃使良还。行，烧…","q":[["黥布开关，张良烧栈。","李瀚 蒙求"]]},{"n":"纪信诈帝","d":"","s":"《汉书》卷一上《高帝纪上》","w":"「夏四月，项羽围汉荥阳，汉王请和，割荥阳以西者为汉。亚父劝项羽急攻荥阳，汉王患之。陈平反间既行，羽果疑亚父。亚父大怒而去，发病死。」「五月，将军纪信曰：『事急矣！臣请诳楚，可以间出。』于是陈平夜出女子东门二千馀人，楚因四面击之。纪信乃乘王车…","q":[["郦寄卖友，纪信诈帝。","李瀚 蒙求"]]},{"n":"假王徼福","d":"","s":"《史记》卷九十二《淮阴侯列传》","w":"汉四年，遂皆降平齐。使人言汉王曰：「齐伪诈多变，反覆之国也，南边楚，不为假王以镇之，其势不定。愿为假王便。」当是时，楚方急围汉王于荥阳，韩信使者至，发书，汉王大怒，骂曰：「吾困于此，旦暮望若来佐我，乃欲自立为王！」","q":[["英主任贤增虎翼，假王徼福犯龙鳞。","李绅 却过淮阴吊韩信庙"]]},{"n":"随何","d":"","s":"《史记》卷九十一〈黥布列传〉～2603～","w":"项籍死，天下定，上置酒。上折随何之功，谓何为腐儒，为天下安用腐儒。随何跪曰：「夫陛下引兵攻彭城，楚王未去齐也，陛下发步卒五万人，骑五千，能以取淮南乎？」上曰：「不能。」随何曰：「陛下使何与二十人使淮南，至，如陛下之意，是何之功贤于步卒五万人…","q":[["天下尚未宁，健儿胜腐儒。","杜甫 草堂"]]},{"n":"解衣","d":"","s":"《史记》卷九十二《淮阴侯列传》","w":"汉四年，遂皆降平齐。使人言汉王曰：「齐伪诈多变，反覆之国也，南边楚，不为假王以镇之，其势不定。愿为假王便。」当是时，楚方急围汉王于荥阳，韩信使者至，发书，汉王大怒，骂曰：「吾困于此，旦暮望若来佐我，乃欲自立为王！」张良、陈平蹑汉王足，因附耳…","q":[["解衣延宠命，横剑总威名。","李适 奉和幸望春宫送朔方军大总管张仁亶"],["推食天厨至，投醪御酒传。","萧至忠 送张亶赴朔方应制"]]},{"n":"决策欺陈","d":"","s":"《史记》卷五十六《陈丞相世家》","w":"「陈平既多以金纵反閒于楚军，宣言诸将钟离眛等为项王将，功多矣，然而终不得裂地而王，欲与汉为一，以灭项氏而分王其地。项羽果意不信钟离眛等。项王既疑之，使使至汉。汉王为太牢具，举进。见楚使，即详惊曰：『吾以为亚父使，乃项王使！』复持去，更以恶草…","q":[["勒功思比宪，决略暗欺陈。","骆宾王 咏怀古意上裴侍郎"]]},{"n":"君臣际会","d":"","s":"《论衡校释》卷三〈偶会第十〉～07～","w":"因此论圣贤迭起，犹此类也。圣主龙兴于仓卒，良辅超拔于际会。世谓韩信、张良辅助汉王，故秦灭汉兴，高祖得王。","q":[]},{"n":"田横客","d":"","s":"《史记》卷九十四《田儋列传》","w":"「（横）遂自刭，令客奉其头，从使者驰奏之高帝。高帝曰：『嗟乎，有以也夫！起自布衣，兄弟三人更王，岂不贤乎哉！』为之流涕，而拜其二客为都尉，发卒二千人，以王者礼葬田横。」唐·张守节《史记正义》引晋·崔豹《古今注》：「薤露、蒿里，送哀歌也，出田…","q":[["纵使将军能伏剑，何人岛上哭田横。","李涉 哭田布"],["李陵初诗，田横感歌。","李瀚 蒙求"]]},{"n":"哙伍","d":"","s":"《史记》卷九十二〈淮阴侯列传〉～2628～","w":"信知汉王畏恶其能，常称病不朝从。信由此日夜怨望，居常鞅鞅，羞与绛、灌等列。信尝过樊将军哙，哙跪拜送迎，言称臣，曰：「大王乃肯临臣！」信出门，笑曰：「生乃与哙等为伍！」上常从容与信言诸将能不，各有差。上问曰：「如我能将几何？」信曰：「陛下不过…","q":[]},{"n":"郦生长揖","d":"","s":"《史记》卷九十七〈郦生陆贾列传·郦生〉～2692～","w":"沛公至高阳传舍，使人召郦生。郦生至，入谒，沛公方倨使两女子洗足，而见郦生。郦生入，则长揖不拜，曰：「足下欲助秦攻诸侯乎？且欲率诸侯破秦也？」沛公骂曰：「竖儒！夫天下同苦秦久矣，故诸侯相率而攻秦，何谓助秦攻诸侯乎？」郦生曰：「必聚徒合义兵诛…","q":[["伊籍一拜，郦生长揖。","李瀚 蒙求"]]},{"n":"隆准","d":"","s":"《史记》卷八《高祖本纪》","w":"「高祖为人，隆准而龙颜，美须髯，左股有七十二黑子。」南朝宋·裴骃《史记集解》引文颖曰：「高祖感龙而生，故其颜貌似龙，长颈而高鼻。」","q":[["我来不见隆准人，沥酒空馀庙中客。","李商隐 偶成转韵七十二句赠四同舍"],["高帝子孙尽隆准，龙种自与常人殊。","杜甫 哀王孙"]]},{"n":"龙颜","d":"","s":"《史记》卷八《高祖本纪》","w":"「高祖为人，隆准而龙颜，美须髯。」南朝宋·裴骃《史记集解》：「应劭曰：『隆，高也。准，颊权准也。颜，额颡也，齐人谓之颡，汝南、淮、泗之间曰颜。』」","q":[["秦皇曾虎视，汉祖亦龙颜。","张祜 入潼关"]]},{"n":"龙种","d":"","s":"《史记》卷四十九《外戚世家》","w":"汉王入织室，见薄姬有色，诏内后宫，岁馀不得幸。始姬少时，与管夫人、赵子儿相爱，约曰：「先贵无相忘。」已而管夫人、赵子儿先幸汉王。汉王坐河南宫成皋台，此两美人相与笑薄姬初时约。汉王闻之，问其故，两人具以实告汉王。汉王心惨然，怜薄姬，是日召而幸…","q":[["寄人龙种瘦，失母凤雏痴。","李商隐 杨本胜说于长安见小男阿衮"],["世上苍龙种，人间武帝孙。","李商隐 鄠杜马上念汉书一云五陵怀古"]]},{"n":"卢绾须征","d":"","s":"《汉书》卷三十四《卢绾传》","w":"汉既斩豨，其裨将降，言燕王绾使范齐通计谋豨所。上使使召绾，绾称病。又使辟阳侯审食其、御史大夫赵尧往迎绾，因验问其左右。绾愈恐，閟匿，谓其幸臣曰：「非刘氏而王者，独我与长沙耳。往年汉族淮阴，诛彭越，皆吕后计。今上病，属任吕后。吕后妇人，专欲以…","q":[["卢绾须征日，楼兰要斩时。","杜甫 暮冬送苏四郎徯兵曹适桂州"]]},{"n":"马上得天下","d":"","s":"《史记》卷九十七〈郦生陆贾列传·陆贾〉～2699～","w":"陆生时时前说称诗书。高帝骂之曰：「乃公居马上而得之，安事诗书！」陆生曰；「居马上得之，宁可以马上治之乎？且汤武逆取而以顺守之，文武并用，长久之术也。昔者吴王夫差、智伯极武而亡；秦任刑法不变，卒灭赵氏。乡使秦已并天下，行仁义，法先圣，陛下安得…","q":[["莫言马上得天下，自古英雄尽解诗。","林宽 歌风台"]]},{"n":"七国三边","d":"","s":"《史记》卷十一〈孝景本纪〉～449～","w":"太史公曰：汉兴，孝文施大德，天下怀安，至孝景，不复忧异姓，晁错刻削诸侯，遂使七国俱起，合从而西乡，以诸侯太盛，而错为之不以渐也。及主父偃言之，而诸侯以弱，卒以安。安危之机，岂不以谋哉？","q":[["七国三边未到忧，十三身袭富平侯。","李商隐 富平少侯"]]},{"n":"三尺水","d":"王陵戆：喻人耿直不阿。唐许浑《维舟秦淮过温州李给事宅》：“代有王陵戆，时无勒尚谗。”","s":"《史记》卷八〈高祖本纪〉～39～","w":"高祖击布时，为流矢所中，行道病。病甚，吕后迎良医，医入见，高祖问医，医曰：「病可治。」于是高祖嫚骂之曰：「吾以布衣提三尺剑取天下，此非天命乎？命乃在天，虽扁鹊何益！」遂不使治病，赐金五十斤罢之。已而吕后问：「陛下百岁后，萧相国即死，令谁代之…","q":[["直似王陵戆，非如宁武愚。","张九龄 豋荆州城楼"],["王陵固似戆，郭最遂非雄。","李端 长安感事呈卢纶"]]},{"n":"三章","d":"","s":"《史记》卷八〈高祖本纪〉～362～","w":"与父老约，法三章耳：杀人者死，伤人及盗抵罪。馀悉除去秦法。诸吏人皆案堵如故。凡吾所以来，为父老除害，非有所侵暴，无恐！且吾所以还军霸上，待诸侯至而定约束耳。」乃使人与秦吏行县乡邑，告谕之。秦人大喜，争持牛羊酒食献飨军士。沛公又让不受，曰：「…","q":[["汉后三章令，周王五伐兵。","杨炯 奉和上元酺宴应诏"]]},{"n":"素灵感刘季","d":"","s":"《昭明文选》卷四十七东汉·史孝山（岑）《出师颂》","w":"「五曜霄映，素灵夜叹。皇运来授，万宝增焕。」唐·李善注：《汉书》曰：「元年冬十月，五星聚于东井，沛公至霸上。应劭曰：五星所在，其下以义取天下也。又曰：高祖夜经泽中，有大蛇当径，拔剑斩蛇，蛇分为两。后人至蛇所，有一妪夜哭，人问妪，妪曰：吾子白…","q":[["素灵感刘季，白马从子婴。","张良璞 览史"]]},{"n":"碎玉斗","d":"","s":"《史记》卷七《项羽本纪》","w":"张良入谢，曰：「沛公不胜杯杓，不能辞。谨使臣良奉白璧一双，再拜献大王足下；玉斗一双，再拜奉大将军足下。」项王曰：「沛公安在？」良曰︰「闻大王有意督过之，脱身独去，已至军矣。」项王则受璧，置之坐上。亚父受玉斗，置之地，拔剑撞而破之，曰：「唉！…","q":[["忆昔范增碎玉斗，未使吴兵著白袍。","杜甫 久雨期王将军不至"]]},{"n":"提剑","d":"","s":"《史记》卷八《高祖本纪》","w":"高祖击布时，为流矢所中，行道病。病甚，吕后迎良医，医入见，高祖问医，医曰：「病可治。」于是高祖嫚骂之曰：「吾以布衣提三尺剑取天下，此非天命乎？命乃在天，虽扁鹊何益！」","q":[["高文会隋季，提剑徇天意。","杜牧 感怀诗一首"],["提剑云雷动，垂衣日月明。","卢纶 皇帝感词"]]},{"n":"天寒堕指白登围","d":"","s":"《史记》卷一百十〈匈奴列传〉～2894～","w":"是时汉初定中国，徙韩王信于代，都马邑。匈奴大攻围马邑，韩王信降匈奴。匈奴得信，因引兵南踰句注，攻太原，至晋阳下。高帝自将兵往击之。会冬大寒雨雪，卒之堕指者十二三，于是冒顿详败走，诱汉兵。汉兵逐击冒顿，冒顿匿其精兵，见其羸弱，于是汉悉兵，多步…","q":[]},{"n":"为我楚舞","d":"","s":"《史记》卷五十五〈留侯世家〉～2047～","w":"四人为寿已毕，趋去。上目送之，召戚夫人指示四人者曰：「我欲易之，彼四人辅之，羽翼已成，难动矣。吕后真而主矣。」戚夫人泣，上曰：「为我楚舞，吾为若楚歌。」歌曰：「鸿鹄高飞，一举千里。羽翮已就，横绝四海。横绝四海，当可柰何！虽有矰缴，尚安所施！…","q":[]},{"n":"萧曹","d":"","s":"《汉书》卷三十九《萧何曹参传》","w":"赞曰：萧何、曹参皆起秦刀笔吏，当时录录未有奇节。汉兴，依日月之末光，何以信谨守管籥，参与韩信俱征伐。天下既定，因民之疾秦法，顺流与之更始，二人同心，遂安海内。淮阴、黥布等已灭，唯何、参擅功名，位冠群臣，声施后世，为一代之宗臣，庆流曲裔，盛矣…","q":[["宠荣连雨露，先后比萧曹。","姚合 和郑相演杨尚书蜀中唱和诗"],["萧曹曾作沛中吏，攀龙附凤当有时。","李白 猛虎行"]]},{"n":"萧相国","d":"","s":"《史记》卷五十三《萧相国世家》","w":"萧相国何者，沛丰人也。以文无害为沛主吏掾。高祖为布衣时，何数以吏事护高祖。高祖为亭长，常左右之。高祖以吏繇咸阳，吏皆送奉钱三，何独以五。……及高祖起为沛公，何常为丞督事。沛公至咸阳，诸将皆争走金帛财物之府分之，何独先入收秦丞相御史律令图书藏…","q":[["知己酂侯在，应怜脱粟人。","刘长卿 送裴郎中贬吉州"],["夫子墙还峻，酂侯宅过谦。","姚合 和座主相公西亭秋日即事"]]},{"n":"萧何识故侯","d":"","s":"《史记》卷五十三《萧相国世家》","w":"淮阴侯谋反关中，吕后用萧何计，诛淮阴侯，语在淮阴事中。上已闻淮阴侯诛，使使拜丞相何为相国，益封五千户，令卒五百人一都尉为相国卫。诸君皆贺，召平独吊。召平者，故秦东陵侯。秦破，为布衣，贫，种瓜于长安城东，瓜美，故世俗谓之「东陵瓜」，从召平以为…","q":[["贾谊辞明主，萧何识故侯。","刘长卿 送李使君贬连州"]]},{"n":"星辰合围","d":"","s":"《汉书》卷二十六《天文志》","w":"七年，月晕，围参、毕七重。占曰：「毕、昴间，天街也；街北，胡也；街南，中国也。昴为匈奴，参为赵，毕为边兵。」是岁高皇帝自将兵击匈奴，至平城，为冒顿单于所围，七日乃解。","q":[["日月还相斗，星辰屡合围。","杜甫 伤春五首"]]},{"n":"雄都壮丽","d":"","s":"《史记》卷八《高祖本纪》","w":"萧丞相营作未央宫，立东阙、北阙、前殿、武库、太仓。高祖还，见宫阙壮甚，怒，谓萧何曰：「天下匈匈苦战数岁，成败未可知，是何治宫室过度也？」萧何曰：「天下方未定，故可因遂就宫室。且夫天子四海为家，非壮丽无以重威，且无令后世有以加也。」高祖乃说。","q":[["雄都元壮丽，望幸歘威神。","杜甫 江陵望幸"]]},{"n":"白登围","d":"","s":"《汉书》卷九十四上〈匈奴传〉～3753～","w":"是时，汉初定，徙韩王信于代，都马邑。匈奴大攻围马邑，韩信降匈奴。匈奴得信，因引兵南踰句注，攻太原，至晋阳下。高帝自将兵往击之。会冬大寒雨雪，卒之堕指者十二三，于是冒顿阳败走，诱汉兵。汉兵逐击冒顿，冒顿匿其精兵，见其羸弱，于是汉悉兵，多步兵，…","q":[["汉下白登道，胡窥青海湾。","李白 关山月"],["动询黄阁老，肯虑白登围。","杜甫 送卢十四弟侍御报韦尚书（之晋）灵榇归上都二十韵"]]},{"n":"雍齿先封","d":"","s":"《史记》卷五十五《留侯世家》","w":"上已封大功臣二十馀人，其馀日夜争功不决，未得行封。上在雒阳南宫，从复道望见诸将往往相与坐沙中语。上曰：「此何语？」留侯曰：「陛下不知乎？此谋反耳。」上曰：「天下属安定，何故反乎？」留侯曰：「陛下起布衣，以此属取天下，今陛下为天子，而所封皆萧…","q":[["丁公遽戮，雍齿先封。","李瀚 蒙求"]]},{"n":"玉衣自举","d":"","s":"旧题东汉·班固《汉武帝故事》","w":"高皇庙中御衣自箧中出，舞于殿上。冬衣自下在席上。平帝时，哀帝庙衣自在押外。","q":[["玉衣晨自举，铁马汗常趋。","杜甫 行次昭陵（唐太宗昭陵在醴泉县九嵏山西北。时甫诏许之鄜州视家。道里所经。）"]]}],"3":[{"n":"鹴裘解尽","d":"","s":"《西京杂记》卷二～076～","w":"司马相如，初与卓文君还成都。居贫愁懑，以所著鹔鹴裘，就市人阳昌贳酒，与文君为欢。","q":[]},{"n":"茂陵女","d":"白头吟：喻心境哀伤幽怨。唐骆宾王《在狱咏蝉》；“那堪玄鬓影，来对白头吟。”","s":"旧题晋·葛洪《西京杂记》卷三","w":"司马相如将聘茂陵人女为妾。卓文君作《白头吟》以自绝。相如乃止。","q":[["一朝将聘茂陵女，文君因赠白头吟。","李白 白头吟"],["分明似写文君恨，万怨千愁弦上声。","李益 奉和武相公春晓闻莺"]]},{"n":"长门赋","d":"千金赋：喻作品极有价值。金元好问《白屋》：“长门谁买千金赋，祖道虚传五鬼文。”；长门泣：喻失宠后的凄怨心情。南朝梁何逊《扬州法曹梅花盛开》：“朝洒长门泣，夕驻临邛杯。”","s":"《昭明文选》卷十六汉·司马长卿（相如）《长门赋·序》","w":"「孝武皇帝陈皇后时得幸，颇妒。别在长门宫，愁闷悲思。闻蜀郡成都司马相如天下工为文，奉黄金百斤为相如文君取酒，因于解悲愁之辞。而相如为文以悟主上，陈皇后复得亲幸。」","q":[["长门谁买千金赋，祖道虚传五鬼文。","元好问 白屋"],["虽然不似王孙女，解爱临邛卖赋郎。","崔珏 有赠"]]},{"n":"避事","d":"","s":"《汉书》卷六十四上《严助传》","w":"其尤亲幸者，东方朔、枚皋、严助、吾丘寿王、司马相如。相如常称疾避事。","q":[["有园同庾信，避事学相如。","杜牧 许七侍御弃官东归潇洒江南颇闻自适高秋企望题诗寄赠十韵"]]},{"n":"交颈鸳鸯","d":"","s":"《太平御览》卷五百七十三〈乐部十一·歌四〉～277～","w":"《琴歌二首》其一：「凤兮凤兮归故乡，遨游四海索我皇。时来通遇无所将，何悟今夕升斯堂。有艳淑女在此房，室迩人遐毒我肠，何缘交接为鸳鸯。」","q":[]},{"n":"相如渴","d":"相如渴病：指渴饮或有疾病。唐唐彦谦《奏捷西蜀题沱江驿》：“锦江不识临邛酒，且免相如渴病归。”","s":"《史记》卷一百一十七〈司马相如列传〉～2999～","w":"司马相如者，蜀郡成都人也，字长卿。少时好读书，学击剑，故其亲名之曰犬子。相如既学，慕蔺相如之为人，更名相如。以赀为郎，事孝景帝，为武骑常侍，非其好也。……相如口吃而善著书。常有消渴疾。与卓氏婚，饶于财。其进仕宦，未尝肯与公卿国家之事，称病閒…","q":[["茂陵久病书千卷，彭泽初归酒一瓢。","许浑 送前东阳于明府由鄂渚归故林"],["茂陵虽有病，犹得伴君行。","祖咏 赠苗员外发"]]},{"n":"邹枚","d":"","s":"《史记》卷一百一十七〈司马相如列传〉～2999～","w":"司马相如者，蜀郡成都人也，字长卿。少时好读书，学击剑，故其亲名之曰犬子。相如既学，慕蔺相如之为人，更名相如。以赀为郎，事孝景帝，为武骑常侍，非其好也。会景帝不好辞赋，是时梁孝王来朝，从游说之士齐人邹阳、淮阴枚乘、吴庄忌夫子之徒，相如见而说之…","q":[["邹枚入梁苑，逸少在山阴。","刘长卿 寄会稽公徐侍郎"],["文学引邹枚，歌钟陈卫霍。","张说 药园宴武辂沙将军赋得洛字"]]},{"n":"长门","d":"","s":"《昭明文选》卷十六〈赋辛·哀伤·长门赋〉～72～","w":"孝武皇帝陈皇后时得幸，颇妒。别在长门宫，愁闷悲思。闻蜀郡成都司马相如天下工为文，奉黄金百斤为相如文君取酒，因于解悲愁之辞。而相如为文以悟主上，陈皇后复得亲幸。","q":[["今日在长门，从来不如丑。","于濆 宫怨"],["谁能赋得长门事，不惜千金奉酒杯。","吴融 上阳宫词"]]},{"n":"驷马车","d":"题柱：喻指立志求取功名。唐杜甫《投赠哥舒开府翰二十韵》：“壮节初题柱，生涯独转蓬。”","s":"《艺文类聚》第六十三卷〈居处部三·门〉～29～","w":"《华阳国志》曰：蜀城十里，有升迁桥，送客观。司马相如初入长安，题其门曰：「不乘赤车驷马，不过汝下。」","q":[["徒闻子敬遗琴在，不见相如驷马归。","戴叔伦 吊畅当"],["汉家天子驰驷马，赤军蜀道迎相如。","李白 赠从弟南平太守之遥二首之一"]]},{"n":"马相如","d":"","s":"《史记》卷一一七《司马相如列传》","w":"司马相如者，蜀郡成都人也，字长卿。少时好读书，学击剑，故其亲名之曰犬子。相如既学，慕蔺相如之为人，更名相如。以赀为郎，事孝景帝，为武骑常侍，非其好也。会景帝不好辞赋，是时梁孝王来朝，从游说之士齐人邹阳、淮阴枚乘、吴庄忌夫子之徒，相如见而说之…","q":[["登原过水访相如，竹坞莎庭似故居。","刘沧 访友人郊居"],["箧留马卿赋，袖有刘弘书。","刘禹锡 送湘阳熊判官孺登府罢归钟陵因寄呈江西裴中丞二十三兄"]]},{"n":"长卿贫","d":"","s":"《史记》卷一百一十七〈司马相如列传〉～2999～","w":"司马相如者，蜀郡成都人也，字长卿。少时好读书，学击剑，故其亲名之曰犬子。相如既学，慕蔺相如之为人，更名相如。以赀为郎，事孝景帝，为武骑常侍，非其好也。会景帝不好辞赋，是时梁孝王来朝，从游说之士齐人邹阳、淮阴枚乘、吴庄忌夫子之徒，相如见而说之…","q":[["长卿牢落悲空舍，曼倩诙谐取自容。","李贺 南园十三首"],["家甚长卿贫，身多公干病。","武元衡 长安叙怀寄崔十五"]]},{"n":"长卿慢世","d":"","s":"《世说新语笺疏》中卷下〈品藻〉～542～","w":"王子猷、子敬兄弟共赏《高士传》人及《赞》。子敬赏井丹高洁，子猷云：「未若长卿慢世。」南朝梁·刘孝标注引嵇康《高士传》曰：「丹字大春，扶风郿人。博学高论，京师为之语曰：『五经纷纶井大春，未尝书刺谒一人。』北宫五王更请，莫能致。新阳侯阴就使人要…","q":[]},{"n":"封禅书","d":"茂陵书生：指司马相如，或指文人，多指落泊文人。唐卢纶《晚秋山中别业》：“茂陵秋最冷，谁念一书生？”","s":"《史记》卷一百一十七〈司马相如列传〉～3063～","w":"相如既病免，家居茂陵。天子曰：「司马相如病甚，可往从悉取其书；若不然，后失之矣。」使所忠往，而相如已死，家无书。问其妻，对曰：「长卿固未尝有书也。时时著书，人又取去，即空居。长卿未死时，为一卷书，曰有使者来求书，奏之。无他书。」其遗札书言封…","q":[["相如有遗草，一为问家人。","刘慎虚 寄江滔求孟六遗文"],["漳浦病多愁易老，茂陵书在信难通。","司马扎 白马津阻雨"]]},{"n":"成都骋驺引","d":"","s":"《史记》卷一一七《司马相如传》","w":"「天子问相如，相如曰：『邛、笮、……道亦易通，秦时尝通为郡县，至汉兴而罢。今诚复通，为置郡县，愈于南夷。』天子以为然，乃拜相如为中郎将，建节往使。」「至蜀，蜀太守以下郊迎，县令负弩矢先驱，蜀人以为宠。」","q":[["不能京兆画峨眉，翻向成都骋驺引。","骆宾王 代女道士王灵妃赠道士李荣"]]},{"n":"东家女","d":"三年送目：指女子爱慕男子。宋杨亿《宋玉》：“三年送目愁邻媛，七泽迷魂怨楚辞。”；宋玉墙：喻女子寄情之所。唐罗隐《桃花》：“数枝艳拂文君酒，半里红欹宋玉墙。”","s":"《昭明文选》卷十九〈赋癸·情·登徒子好色赋〉～892～","w":"大夫登徒子侍于楚王，短宋玉曰：「玉为人，体貌闲丽，口多微辞，又性好色。愿王勿与出入后宫。」王以登徒子之言问宋玉，玉曰：「体貌闲丽，所受于天也；口多微辞，所学于师也；至于好色，臣无有也。」王曰：「子不好色，亦有说乎？有说则止，无说则退。」玉曰…","q":[["西墙邻宋玉，窥见妾眉宇。","于濆 宫怨"],["因游李城北，偶向宋家东。","元稹 会真诗三十韵"]]},{"n":"翠华","d":"","s":"《汉书》卷五十七上《司马相如传上》","w":"《上林赋》：「建翠华之旗，树灵鼍之鼓。」唐·颜师古注：「翠华之旗，以翠羽为旗上葆也。」","q":[["回首春又归，翠华不能待。","刘驾 兰昌宫"],["障掩金鸡蓄祸机，翠华西拂蜀云飞。","崔橹 华清宫三首之二"]]},{"n":"前驱负弩","d":"","s":"《史记》卷一百一十七〈司马相如列传〉～3046～","w":"相如还报。唐蒙已略通夜郎，因通西南夷道，发巴、蜀、广汉卒，作者数万人。治道二岁，道不成，士卒多物故，费以巨万计。蜀民及汉用事者多言其不便。是时邛笮之君长闻南夷与汉通，得赏赐多，多欲愿为内臣妾，请吏，比南夷。天子问相如，相如曰：「邛、笮、冉、…","q":[["无能甘负弩，不慎在提衡。","刘禹锡 历阳书事七十韵并引"],["身负邦君弩，情纡御史骢。","张九龄 郡江南上别孙侍御"]]},{"n":"大人赋","d":"","s":"《汉书》卷五十七下〈司马相如列传下〉～2592～","w":"相如拜为孝文园令。上既美子虚之事，相如见上好仙，因曰：「上林之事未足美也，尚有靡者。臣尝为大人赋，未就，请具而奏之。」相如以为列仙之儒居山泽间，形容甚臞，此非帝王之仙意也，乃遂奏〈大人赋〉。天子大说，飘飘有陵云气游天地之閒意。","q":[["预知大人赋，掩却归来词。","独孤及 送陈兼应辟兼寄高适贾至"]]},{"n":"风流地","d":"","s":"《史记》卷一百一十七〈司马相如列传〉～3000～","w":"临邛中多富人，而卓王孙家僮八百人，程郑亦数百人，二人乃相谓曰：「令有贵客，为具召之。」并召令。令既至，卓氏客以百数。至日中，谒司马长卿，长卿谢病不能往，临邛令不敢尝食，自往迎相如。相如不得已，彊往，一坐尽倾。酒酣，临邛令前奏琴曰：「窃闻长卿…","q":[["临江起珠楼，不卖文君酒。","于濆 宫怨"],["不恨归日迟，莫向临邛去。","孟郊 古别离"]]},{"n":"卓女","d":"文君酒：咏酒或情爱。唐李百药《少年行》：“始酌文君酒，新吹弄玉萧。”；贳酒成都：咏人性情豪放，不惜以珍宝换取豪饮。唐骆宾王《艳情代郭氏赠卢照邻》：“掷果河阳君有分，贳酒成都妾亦然。”","s":"《汉书》卷五十七上〈司马相如列传〉～2530～","w":"临邛多富人，卓王孙僮客八百人，程郑亦数百人，乃相谓曰：「令有贵客，为具召之。并召令。」令既至，卓氏客以百数，至日中请司马长卿，长卿谢病不能临。临令不敢尝食，身自迎相如，相如为不得已而强往，一坐尽倾。酒酣，临邛令前奏琴曰：「窃闻长卿好之，愿…","q":[["楼下当垆称卓女，楼头伴客名莫愁。","元稹 西凉伎"],["莱子真为少，相如未免穷。","孟郊 赠转运陆中丞"]]},{"n":"东马严徐","d":"","s":"《汉书》卷六十四上〈严朱吾丘主父徐严终王贾列传上·严助〉～2775～","w":"严助，会稽吴人，严夫子子也，或言族家子也。郡举贤良，对策百馀人，武帝善助对，繇是独擢助为中大夫。后得朱买臣、吾丘寿王、司马相如、主父偃、徐乐、严安、东方朔、枚皋、胶仓、终军、严葱奇等，并在左右。是时征伐四夷，开置边郡，军旅数发，内改制度，朝…","q":[]},{"n":"相如赋","d":"","s":"《史记》卷一一七《司马相如列传》","w":"司马相如者，蜀郡成都人也，字长卿。少时好读书，学击剑，故其亲名之曰犬子。相如既学，慕蔺相如之为人，更名相如。以赀为郎，事孝景帝，为武骑常侍，非其好也。会景帝不好辞赋，是时梁孝王来朝，从游说之士齐人邹阳、淮阴枚乘、吴庄忌夫子之徒，相如见而说之…","q":[["献纳开东观，君王问长卿。","杜甫 赠陈二补阙"],["孟阳题剑阁，子云献甘泉。","储光羲 酬李处士山中见赠"]]},{"n":"求凰曲","d":"凤客：指风流才子。唐卢全《卓女怨》：“迷魂随凤客，娇思人琴心。”；求凰：喻男子求佳侣。金元好问《王子文琴斋》：“天上秋风月底霜，求凰一曲鬓丝长。”咏男女之情。唐岑参《糙陕县王主簿赴襄阳成亲》：“求凰应不远，去马剩须鞭。”","s":"《史记》卷一一七《司马相如列传》","w":"「会梁孝王卒，相如归，而家贫，无以自业。素与临邛令王吉相善，吉曰：『长卿久宦游不遂，而来过我。』于是相如往，舍都亭。临邛令缪为恭敬，日往朝相如。相如初尚见之，后称病，使从者谢吉，吉愈益谨肃。临邛中多富人，而卓王孙家僮八百人，程郑亦数百人，二…","q":[["求凤应不远，去马剩须鞭。","岑参 送陕县王主簿赴襄阳成亲"],["君不见相如绿绮琴，一抚一拍凤凰音。","张纮 行路难"]]},{"n":"赋罢为郎","d":"","s":"《史记》卷一一七《司马相如列传》","w":"上读子虚赋而善之，曰：「朕独不得与此人同时哉！」得意曰：「臣邑人司马相如自言为此赋。」上惊，乃召问相如。相如曰：「有是。然此乃诸侯之事，未足观也。请为天子游猎赋，赋成奏之。」上许，令尚书给笔札。相如以「子虚」，虚言也，为楚称；「乌有先生」者…","q":[["书成休逐客，赋罢遂为郎。","张继 洛阳作"]]},{"n":"赋上林","d":"","s":"《史记》卷一一七《司马相如列传》","w":"上读《子虚赋》而善之，曰：「朕独不得与此人同时哉！」得意曰：「臣邑人司马相如自言为此赋。」上惊，乃召问相如。相如曰：「有是。然此乃诸侯之事，未足观也。请为天子游猎赋，赋成奏之。」上许，令尚书给笔札。相如以「子虚」，虚言也，为楚称；「乌有先生…","q":[["本为成王业，初由赋上林。","张说 对酒行巴陵作"]]},{"n":"文似相如","d":"","s":"《汉书》卷八十七上《扬雄传上》","w":"先是时，蜀有司马相如，作赋甚弘丽温雅，雄心壮之，每作赋，常拟之以为式。……孝成帝时，客有荐雄文似相如者，上方郊祠甘泉泰畤、汾阴后土，以求继嗣，召雄待诏承明之庭。","q":[["玄成世业紫真官，文似相如貌胜潘。","崔峒 送韦八少府判官归东京"],["子云尝燕居，作赋似相如。","权德舆 户部王曹长杨考功崔刑部二院长并同钟陵使府之旧因以寄赠又陪郎署喜甚常僚因书所怀且叙所知"]]},{"n":"梁园赋","d":"延枚：指延集宾客。唐李商隐《忆雪》：“预约延枚酒，虚乘访戴船。”；授简：指奉命吟诗作赋。唐杜甫《又作此奉卫王》：“白头授简焉能赋，愧似相如为大夫。”","s":"《西京杂记》卷二","w":"梁孝王好营宫室苑囿之乐。作曜华之宫。筑兔园。园中有百灵山。山有肤寸石。落猿岩。栖龙岫。又有雁池池间有鹤洲凫渚。其诸宫观相连延亘数十里。奇果异树瑰禽怪兽毕备。主日与宫人宾客弋钓其中。","q":[["孙室临书幌，梁园泛酒杯。","令狐楚 省中直夜对雪寄李师素侍郎"],["有客怀兔园，吟诗绕城内。","曹邺 贺雪寄本府尚书"]]},{"n":"回书父老","d":"","s":"《史记》卷一一七《相马相如传》","w":"相如使时，蜀长老多言通西南夷不为用，唯大臣亦以为然。相如欲谏，业已建之，不敢，乃著书，籍以蜀父老为辞，而己诘难之，以风天子，且因宣其使指，令百姓知天子之意。","q":[["欲持画省郎官笔，回与临邛父老书。","王维 送崔五太守"]]},{"n":"贾马","d":"","s":"《晋书》卷九十二〈文苑列传·序言〉～2369～","w":"自时已降，轨躅同趋，西都贾马耀灵蛇于掌握，东汉班张发雕龙于绨椠，俱标称首，咸推雄伯。","q":[["舐笔和铅欺贾马，赞功论道鄙萧曹。","杜牧 长安杂题长句六首"],["论文徵贾马，述隐许求羊。","皎然 因游支硎寺寄邢端公"]]},{"n":"雷声","d":"","s":"《昭明文选》卷十六汉·司马长卿（相如）《长门赋》","w":"雷殷殷而响起兮，声象君之车音。","q":[["雷音后车远，事往落花时。","杜牧 杜秋娘诗"],["雷声匪君车，犹时过我庐。","钱起 离居夜雨奉寄李京兆"]]},{"n":"仙儒","d":"","s":"《史记》卷一百一十七〈司马相如列传〉～3056～","w":"相如拜为孝文园令。天子既美子虚之事，相如见上好仙道，因曰：「上林之事未足美也，尚有靡者。臣尝为大人赋，未就，请具而奏之。」相如以为列仙之传居山泽閒，形容甚臞，此非帝王之仙意也，乃遂就〈大人赋〉。唐·司马贞《史记索隐》注引徐广曰：「臞，瘦也。…","q":[]},{"n":"绿绮琴","d":"","s":"《昭明文选》卷三十晋·张孟阳（载）《拟四愁诗》","w":"「佳人遗我绿绮琴，何以赠之双南金。」唐·李贤注引傅玄《琴赋序》曰：「齐桓公有鸣琴曰号钟，楚庄有鸣琴曰绕梁，中世司马相如有绿绮，蔡邕有燋尾，皆名琴也。」","q":[["绿绮韵高湘女怨，青葭色映水禽寒。","刘沧 江行夜泊"],["惆怅妆成君不见，空教绿绮伴文君。","李余 临邛怨"]]},{"n":"马卿台","d":"","s":"《史记》卷一百一十七〈司马相如列传〉～3000～","w":"相如之临邛，从车骑，雍容閒雅甚都；及饮卓氏，弄琴，文君窃从户窥之，心悦而好之，恐不得当也。既罢，相如乃使人重赐文君侍者通殷勤。文君夜亡奔相如，相如乃与驰归成都。家居徒四壁立。","q":[["马卿台上应芜没，阮籍帷前空已矣。","司马逸客 雅琴篇"],["渐离初击筑，司马正弹琴。","李峤 市"]]},{"n":"枚马","d":"","s":"《文心雕龙》卷二〈诠赋〉","w":"初汉辞赋，顺流而作，陆贾扣其端，贾谊振其绪，枚马同其风，王扬骋其势。","q":[["入掌迁固笔，出参枚马词。","崔湜 景龙二年余自门下平章事削阶授江州员外司马寻拜襄州刺史春日赴襄阳途中言志"],["徐陈尝并作，枚马亦同时。","张说 酬崔光禄冬日述怀赠答"]]},{"n":"慕蔺","d":"","s":"《史记》卷一一七《司马相如列传》","w":"司马相如者，蜀郡成都人也，字长卿。少时好读书，学击剑，故其亲名之曰犬子。相如既学，慕蔺相如之为人，更名相如。","q":[["慕蔺岂曩古，攀嵇是当年。","李白 赠饶阳张司户燧"],["长卿慕蔺久，子猷意已深。","魏万 金陵酬李翰林谪仙子"]]},{"n":"拟相如","d":"","s":"《汉书》卷八十七上〈扬雄列传上〉～354～","w":"雄少而好学，不为章句，训诂通而已，博览无所不见。为人简易佚荡，口吃不能剧谈，默而好深湛之思，清静亡为，少耆欲，不汲汲于富贵，不戚戚于贫贱，不修廉隅以徼名当世。家产不过十金，乏无儋石之储，晏如也。自有大度，非圣哲之书不好也；非其意，虽富贵不事…","q":[]},{"n":"羌胡毂下起","d":"","s":"《史记》卷一一七《司马相如列传》","w":"相如口吃而善著书。常有消渴疾。与卓氏婚，饶于财。其进仕宦，未尝肯与公卿国家之事，称病閒居，不慕官爵。常从上至长杨猎，是时天子方好自击熊彘，驰逐野兽，相如上疏谏之。其辞曰：臣闻物有同类而殊能者，故力称乌获，捷言庆忌，勇期贲、育。臣之愚，窃以为…","q":[["羌胡毂下一朝起，敌国舟中非所拟。","柳宗元 古东门行"]]},{"n":"西湖处士","d":"","s":"《归田录》卷二～22～","w":"处士林逋居于杭州西湖之孤山。逋工笔画，善为诗，如「草泥行郭索，云木叫钩辀」，颇为士大夫所称。又梅花诗云：「疏影横斜水清浅，暗香浮动月黄昏。」评诗者谓：「前世咏梅者多矣，未有此句也。」又其临终为句云：「茂陵他日求遗，犹喜曾无封禅书。」尤为人…","q":[]},{"n":"青琴","d":"","s":"《史记》卷一百一十七〈司马相如列传〉～3039～","w":"《上林赋》：「若夫青琴宓妃之徒，绝殊离俗，姣冶娴都，靓庄刻饬，便嬛绰约。」唐·司马贞《史记索隐》引东汉·伏俨曰：「青琴，古神女也。」","q":[["黄鹅跌舞千年觥，仙人烛树蜡烟轻，清琴醉眼泪泓泓。","李贺 秦王饮酒"],["闲遣青琴飞小雪，自看碧玉破甘瓜。","鲍溶 夏日怀杜悰驸马"]]},{"n":"清尘","d":"","s":"《汉书》卷五十七下《司马相如传下》","w":"「相如因上疏谏。其辞曰：臣闻物有同类而殊能者，故力称乌获，捷言庆忌，勇期贲育。臣之愚，窃以为人诚有之，兽亦宜然。今陛下好陵阻险，射猛兽，卒然遇逸材之兽，骇不存之地，犯属车之清尘，舆不及还辕，人不暇施巧，虽有乌获、逢蒙之技不能用，枯木朽株尽为…","q":[["艰危参大府，前后间清尘。","杜甫 奉赠萧二十使君"]]},{"n":"曲终奏雅","d":"","s":"《汉书》卷五十七下〈司马相如传下〉～2609～","w":"赞曰：司马迁称「春秋推见至隐，易本隐以之显，大雅言王公大人，而德逮黎庶，小雅讥小己之得失，其流及上。所言虽殊，其合德一也。相如虽多虚辞滥说，然要其归引之于节俭，此亦诗之风谏何异？」扬雄以为靡丽之赋，劝百而风一，犹骋郑卫之声，曲终而奏雅，不已…","q":[]},{"n":"鹔鹴换酒","d":"","s":"《西京杂记》卷二","w":"司马相如初与卓文君还成都。居贫。愁懑。以所著鹔裘就市人阳昌贳酒与文君为欢。","q":[["谢尚自能鸲鹆舞，相如免脱鹔鹴裘。","李白 对雪醉后赠王历阳"],["鹔鹴换美酒，舞衣罢雕龙。","李白 怨歌行"]]},{"n":"卓王孙","d":"","s":"《史记》卷一百一十七〈司马相如列传〉～3000～","w":"临邛中多富人，而卓王孙家僮八百人，程郑亦数百人，二人乃相谓曰：「令有贵客，为具召之。」并召令。令既至，卓氏客以百数。至日中，谒司马长卿，长卿谢病不能往，临邛令不敢尝食，自往迎相如。相如不得已，彊往，一坐尽倾。酒酣，临邛令前奏琴曰：「窃闻长卿…","q":[["漉空沧海水，搜尽卓王孙。","杜牧 昔事文皇帝三十二韵"],["自应成旅逸，爱客有王孙。","韩翃 送故人归蜀"]]},{"n":"文园","d":"","s":"《史记》卷十〈孝文本纪〉～43～","w":"孝文皇帝，高祖中子也。高祖十一年春，已破陈豨军，定代地，立为代王，都中都。太后薄氏子。即位十七年，高后八年七月，高后崩。九月，诸吕吕产等欲为乱，以危刘氏，大臣共诛之，谋召立代王，事在吕后语中。南朝宋·裴骃集解引《汉书音义》：「讳恒。」","q":[["不堪程尽处，呜咽望文园。","权德舆 奉和郑宾客相公摄官丰陵扈从之作"],["旧居从代邸，新陇入文园。","皇甫冉 故齐王赠承天皇帝挽歌"]]},{"n":"武骑书","d":"","s":"《汉书》卷五十七上《司马相如传上》","w":"司马相如字长卿，蜀郡成都人也。少时好读书，学击剑，名犬子。相如既学，慕蔺相如之为人也，更名相如。以訾为郎，事孝景帝，为武骑常侍，非其好也。","q":[["已授文成履，空题武骑书。","张文宗 赋桥"]]},{"n":"相如病酒","d":"","s":"《史记》卷一百一十七〈司马相如列传〉～3053～","w":"相如口吃而善著书。常有消渴疾。与卓氏婚，饶于财。其进仕宦，未尝肯与公卿国家之事，称病閒居，不慕官爵。常从上至长杨猎，是时天子方好自击熊彘，驰逐野兽，相如上疏谏之。相如口吃而善著书。常有消渴疾。与卓氏婚，饶于财。其进仕宦，未尝肯与公卿国家之事…","q":[]},{"n":"相如返临邛","d":"","s":"《史记》卷一一七《司马相如列传》","w":"天子以为然，乃拜相如为中郎将，建节往使。副使王然于、壶充国、吕越人驰四乘之传，因巴蜀吏币物以赂西夷。至蜀，蜀太守以下郊迎，县令负弩矢先驱，蜀人以为宠。于是卓王孙、临邛诸公皆因门下献牛酒以交驩。卓王孙喟然而叹，自以得使女尚司马长卿晚，而厚分与…","q":[["相如若返临邛市，画舸朱轩万里游。","房千里 寄妾赵氏"]]},{"n":"相如倦","d":"","s":"《史记》卷一百一十七〈司马相如列传〉～3000～","w":"今文君已失身于司马长卿，长卿故倦游，虽贫，其人材足依也，且又令客，独柰何相辱如此！」卓王孙不得已，分予文君僮百人，钱百万，及其嫁时衣被财物。文君乃与相如归成都，买田宅，为富人。","q":[]},{"n":"相如檄","d":"","s":"《史记》卷一百一十七〈司马相如列传〉～3044～","w":"相如为郎数岁，会唐蒙使略通夜郎西僰中，发巴蜀吏卒千人，郡又多为发转漕万馀人，用兴法诛其渠帅，巴蜀民大惊恐。上闻之，乃使相如责唐蒙，因喻告巴蜀民以非上意。檄曰：「告巴蜀太守：蛮夷自擅不讨之日久矣，时侵犯边境，劳士大夫。陛下即位，存抚天下，辑安…","q":[]},{"n":"相如云梦","d":"","s":"《史记》卷一百一十七〈司马相如列传〉～3003～","w":"仆对曰：「唯唯。臣闻楚有七泽，尝见其一，未睹其馀也。臣之所见，盖特其小小者耳，名曰云梦。云梦者，方九百里，其中有山焉。其山则盘纡岪郁，隆崇嵂崒；岑岩参差，日月蔽亏；交错纠纷，上干青云；罢池陂?，下属江河。其土则丹青赭垩，雌黄白附，锡碧金银，…","q":[]},{"n":"扬马","d":"","s":"《文心雕龙·丽辞》","w":"「自扬马张蔡，崇盛丽辞。」","q":[["文章似扬马，风骨又清羸。","李端 赠何兆"],["乾坤几反覆，扬马宣同时。","杜甫 苏大侍御访江浦赋八韵记异（草堂诗本无此题。竟以序为题。八题诗止七韵。疑有脱误。）"]]},{"n":"夜失身","d":"","s":"《史记》卷一百一十七〈司马相如列传〉～3000～","w":"及饮卓氏，弄琴，文君窃从户窥之，心悦而好之，恐不得当也。既罢，相如乃使人重赐文君侍者通殷勤。文君夜亡奔相如，相如乃与驰归成都。家居徒四壁立。卓王孙大怒曰：「女至不材，我不忍杀，不分一钱也。」人或谓王孙，王孙终不听。文君久之不乐，曰：「长卿第…","q":[["一颦一笑千金重，肯似成都夜失身。","权德舆 杂兴五首"]]},{"n":"游梁","d":"","s":"《史记》卷一一七《司马相如列传》","w":"司马相如者，蜀郡成都人也，字长卿。少时好读书，学击剑，故其亲名之曰犬子。相如既学，慕蔺相如之为人，更名相如。以赀为郎，事孝景帝，为武骑常侍，非其好也。会景帝不好辞赋，是时梁孝王来朝，从游说之士齐人邹阳、淮阴枚乘、吴庄忌夫子之徒，相如见而说之…","q":[["过宋人应少，游梁客独愁。","李端 送王少府游河南"],["中年不得意，谢病客游梁。","王维 济上四贤咏成文学"]]},{"n":"喻蜀","d":"","s":"《史记》卷一一七《司马相如列传》","w":"相如为郎数岁，会唐蒙使略通夜郎西僰中，发巴蜀吏卒千人，郡又多为发转漕万馀人，用兴法诛其渠帅，巴蜀民大惊恐。上闻之，乃使相如责唐蒙，因喻告巴蜀民以非上意。","q":[["萧车安不定，蜀使下何之。","杜甫 夔府书怀四十韵"],["深怀喻蜀意，恸哭望王官。","杜甫 王命"]]},{"n":"子虚","d":"子虚：喻指优美的文章。唐王维《戏赠张五弟諲三首》之二：“染翰过草圣，赋诗轻《子虚》。”","s":"《史记》卷一百一十七〈司马相如列传〉～3002～","w":"居久之，蜀人杨得意为狗监，侍上。上读子虚赋而善之，曰：「朕独不得与此人同时哉！」得意曰：「臣邑人司马相如自言为此赋。」上惊，乃召问相如。相如曰：「有是。然此乃诸侯之事，未足观也。请为天子游猎赋，赋成奏之。」上许，令尚书给笔札。相如以「子虚」…","q":[["应须定取真知者，遣对明君说子虚。","吕温 道州酬送何山人之容州"],["尽是忘言客，听君诵子虚。","姚伦 过章秀才洛阳客舍"]]},{"n":"作赋客","d":"","s":"《汉书》卷八十七上《扬雄传上》","w":"先是时，蜀有司马相如，作赋甚弘丽温雅，雄心壮之，每作赋，常拟之以为式。","q":[["神交作赋客，力尽望乡台。","杜甫 云山"]]}],"4":[{"n":"垂天翼","d":"九万欲抟空：喻指志向或前程远大。唐李隆基《巡省途次上党旧宫赋》：“三千初击浪，九万欲抟空。”","s":"《庄子集释》卷一上〈内篇·逍遥游〉～2～","w":"北冥有鱼，其名为鲲。鲲之大，不知其几千里也。化而为鸟，其名为鹏。鹏之背，不知其几千里也；怒而飞，其翼若垂天之云。是乌也，海运则将徙于南冥。南冥者，天池也。齐谐者，志怪者也。谐之言曰：「鹏之徙于南冥也，水击三千里，扶摇而上者九万里，去以六月息…","q":[["三千初击浪，九万欲抟空。","李隆基 巡省途次上党旧宫赋"],["北阙驰心极，南图尚旅游。","于良史 冬日野望寄李赞府"]]},{"n":"知鱼乐","d":"观鱼：咏山水之乐。唐孟浩然《寻梅道士》：“重以观鱼乐，因之鼓枻歌。”","s":"《庄子集释》卷六下〈外篇·秋水〉～606～","w":"庄子与惠子游于濠梁之上。庄子曰：「倏鱼出游从容，是鱼之乐也。」惠子曰：「子非鱼，安知鱼之乐？」庄子曰：「子非我，安知我不知鱼之乐？」惠子曰：「我非子，固不知子矣；子固非鱼矣，子之不知鱼之乐全矣。」庄子曰：「请循其本。子曰『汝安知鱼乐』云者，…","q":[["南华在濠上，谁辩魏王瓠。","储光羲 贻王侍御出台掾丹阳"],["但乐濠梁鱼，岂怨钟山鹄。","吴融 绵竹山西四十韵"]]},{"n":"安排","d":"","s":"《庄子》内篇·卷三上《大宗师》","w":"安排而去化，乃入于寥天一。","q":[["终作适荆蛮，安排用庄叟。","杜甫 将适吴楚留别章使君留后兼幕府诸公得柳字"]]},{"n":"八千岁","d":"椿龄：喻长寿。唐吴筠《步虚词》其七：“绵绵庆不极，谁谓椿龄多。”","s":"《庄子集释》卷一上〈内篇·逍遥游〉～","w":"小知不及大知，小年不及大年。奚以知其然也？朝菌不知晦朔，蟪蛄不知春秋，此小年也。楚之南有冥灵者，以五百岁为春，五百岁为秋；上古有大椿者，以八千岁为春，八千岁为秋。而彭祖乃今以久特闻，众人匹之，不亦悲乎！唐·成玄英疏：「朝菌者，谓天时滞雨，于…","q":[["既许焚香为弟子，愿教年纪共椿同。","令狐楚 赠毛仙翁"],["莫将凡圣比云泥，椿菌之年本不齐。","崔元略 赠毛仙翁"]]},{"n":"郢匠","d":"郢匠：指技艺高超的人，或喻大毛笔。唐骆宾王《夏日游德州赠高四》：“成风郢匠斫，流水伯牙弦。”","s":"《庄子集释》卷八中〈杂篇·徐无鬼〉～843～","w":"庄子送葬，过惠子之墓，顾谓从者曰：「郢人垩慢其鼻端若蝇翼，使匠石斲之。匠石运斤成风，听而斲之，尽垩而鼻不伤，郢人立不失容。宋元君闻之，召匠石曰：『尝试为寡人为之。』匠石曰：『臣则尝能斲之。虽然，臣之质死久矣。』自夫子之死也，吾无以为质矣，吾…","q":[["郢人斤斫无痕迹，仙人衣裳弃刀尺。","刘禹锡 翰林白二十二学士见寄诗一百篇因以答贶"],["脱略磻溪钓，操持郢匠斤。","杜甫 奉赠鲜于京兆二十韵"]]},{"n":"白云乡","d":"","s":"《庄子》外篇·卷五上《天地》","w":"千岁厌世，去而上仙，乘彼白云，至于帝乡。","q":[["何由首西路，目断白云乡。","李群玉 自澧浦东游江表途出巴丘投员外从公虞"],["北别黄榆塞，南归白云乡。","于濆 戍客南归"]]},{"n":"汉阴机","d":"忘机：喻思想纯朴，与人交往没有机心。唐李商隐《赠田叟》：“鸥鸟忘机翻浃洽，交亲得路昧平生。”；汉阴灌：喻心地纯朴无机心。明何景明《立春日作》：“心存汉阴灌，躬学南阳耕。”","s":"《庄子集释》卷五下〈外篇·天运〉～433～","w":"子贡南游于楚，反于晋，过汉阴，见一丈人方将为圃畦，凿隧而入井，抱瓮而出灌，搰搰然用力甚多而见功寡。子贡曰：「有械于此，一日浸百畦，用力甚寡而见功多，夫子不欲乎？」为圃者卬而视之曰：「奈何？」曰：「凿木为机，后重前轻，挈水若抽，数如泆汤，其名…","q":[["已息汉阴诮，且同濠上观。","奚贾 严陵滩下寄常建"],["还嗟绝机叟，白首汉川阴。","崔湜 奉和幸韦嗣立山庄侍宴应制"]]},{"n":"西江水","d":"斗升水：喻急需的济助。唐刘禹锡《送张盥赴举》：“乞取斗升水，因之云汉津。”；涸鱼：喻处境困窘或相互救助。唐白居易《香炉峰下新置草堂即事咏怀题于石上》：“倦鸟得茂树，涸鱼返清源。”","s":"《庄子集释》卷九上〈杂篇·外物〉～924～","w":"庄周家贫，故往贷粟于监河侯。监河侯曰：「诺。我将得邑金，将贷子三百金，可乎？」庄周忿然作色曰：「周昨来，有中道而呼者。周顾视车辙中，有鲋鱼焉。周问之曰：『鲋鱼来！子何为者邪？』对曰：『我，东海之波臣也。君岂有斗升之水而活我哉？』周曰：『诺。…","q":[["石枯山木焦，鳞穷水泉涸。","刘长卿 奉和李大夫同吕评事太行苦热行兼寄院中诸公乃呈王员外"],["持法不须张密网，恩波自解惜枯鳞。","刘长卿 狱中闻收东京有赦"]]},{"n":"散樗","d":"散樗：用以自谦、，或指不愿为世俗做事。唐杜甫《送郑十八虔贬台州司户》：“郑公樗散鬓成丝，酒后常称老画师。”","s":"《庄子集释》卷一上〈内篇·逍遥游〉～39～","w":"惠子谓庄子曰：「吾有大树，人谓之樗。其大本拥肿而不中绳墨，其小枝卷曲而不中规矩，立之涂，匠者不顾。今子之言，大而无用，众所同去也。」","q":[["安知幽涧侧，独与散樗丛。","周存 禁中春松"],["散材无所用，老向琐闱眠。","姚合 送狄尚书镇太原"]]},{"n":"不材木","d":"不材木：喻无才而得福。宋苏轼《宥老楮》：“湖为寻丈地，养此不材木。”","s":"《庄子集释》卷七上〈外篇·山木〉～667～","w":"庄子行于山中，见大木，枝叶盛茂，伐木者止其旁而不取也。问其故，曰：「无所可用。」庄子曰：「此木以不材得终其天年。」夫子出于山，舍于故人之家。故人喜，命竖子杀雁而烹之。竖子请曰：「其一能鸣，其一不能鸣，请奚杀？」主人曰：「杀不能鸣者。」明日，…","q":[["庄叟虚悲雁，终童漫识艇。","李商隐 寄太原卢司空三十韵"],["方知不材者，生长漫婆娑。","杜甫 恶树"]]},{"n":"不辨牛马","d":"","s":"《庄子》外篇·卷六下《秋水》","w":"秋水时至，百川灌河，泾流之大，两涘渚崖之间，不辩牛马。于是焉河伯欣然自喜，以天下之美为尽在己。顺流而东行，至于北海，东面而视，不见水端，于是焉河伯始旋其面目，望洋向若而叹曰：「野语有之曰，『闻道百以为莫己若者』，我之谓也。且夫我尝闻少仲尼之…","q":[["悠悠想大方，此乃杯水滨。","刘禹锡 有僧言罗浮事因为诗以写之"],["惊涛遥起鹭，回岸不分牛。","孔德绍 王泽岭遭洪水"]]},{"n":"不龟手","d":"不龟药：喻平凡之物也能起大作用，或指才非所用。宋黄庭坚《戏答史应之三首》之二：“收得千金不龟药，短裙絖统暮江寒。”","s":"《庄子集释》卷一上〈内篇·逍遥游〉","w":"庄子曰：「夫子固拙于用大矣。宋人有善为不龟手之药者，世世以洴澼絖为事。客闻之，请买其方百金。聚族而谋曰：『我世世为洴澼絖，不过数金；今一朝而鬻技百金，请与之。』客得之，以说吴王。越有难，吴王使之将，冬与越人水战，大败越人，裂地而封之。能不龟…","q":[["谁怜不龟手，他处却封侯。","崔道融 旅行"],["侏儒自是长三尺，澼絖都来直数金。","胡宿 次韵徐爽见寄"]]},{"n":"不系舟","d":"","s":"《庄子集释》卷十上〈杂篇·列御寇〉～040～","w":"曰：「已矣，吾固告汝曰人将保汝，果保汝矣。非汝能使人保汝，而汝不能使人无保汝也，而焉用之感豫出异也！必且有感，摇而本才，又无谓也。与汝游者又莫汝告也，彼所小言，尽人毒也。莫觉莫悟，何相孰也！巧者劳而知者忧，无能者无所求，饱食而敖游，汎若不系…","q":[["独与不系舟，往来楚云里。","刘长卿 赠湘南渔父"],["宛溪霜夜听猿愁，去国长为不系舟。","李白 寄崔侍御"]]},{"n":"鸱吓","d":"","s":"《庄子集释》卷六下〈外篇·秋水〉～605～","w":"惠子相梁，庄子往见之。或谓惠子曰：「庄子来，欲代子相。」于是惠子恐，搜于国中三日三夜。庄子往见之，曰：「南方有鸟，其名为鹓雏，子知之乎？夫鹓雏发于南海而飞于北海，非梧桐不止，非练实不食，非醴泉不饮。于是鸱得腐鼠，鹓雏过之，仰而视之曰：『吓！…","q":[["忽闻饥乌一噪聚，瞥下云中争腐鼠。","刘禹锡 飞鸢操"],["鸱鸢啄腐疑雏凤，神鬼欺贫笑伯龙。","徐夤 西寨寓居之二"]]},{"n":"达生书","d":"","s":"《庄子》外篇·卷七上《达生》","w":"达生之情者，不务生之所无以为。","q":[["达生书一卷，名利付春冰。","李群玉 杜门"]]},{"n":"大块噫气","d":"","s":"《庄子集释》卷一下〈内篇·逍遥游〉～45～","w":"子綦曰：「夫大块噫气，其名为风。是唯无作，作则万窍怒呺。而独不闻之翏翏乎？山林之畏佳，大木百围之窍穴，似鼻，似口，似耳，似枅，似圈，似臼，似洼者，似污者；激者，謞者，叱者，吸者，叫者，号者，宎者，咬者，前者唱于而随者唱喁。泠风则小和，飘风则…","q":[["大块方噫气，何辞鼓青蘋。","李白 赠张相镐二首"],["噫欠为飘风，濯手大雨沱。","韩愈 读东方朔杂事"]]},{"n":"大年","d":"","s":"《庄子集释》卷一上〈外篇·逍遥游〉～","w":"小知不及大知，小年不及大年。奚以知其然也？朝菌不知晦朔，蟪蛄不知春秋，此小年也。楚之南有冥灵者，以五百岁为春，五百岁为秋；上古有大椿者，以八千岁为春，八千岁为秋。","q":[["大年方橐龠，小智即蜉蝣。","储光羲 题辛道士房"]]},{"n":"蝴蝶梦","d":"蝶梦：咏梦。唐骆宾王《同辛簿简仰酬思玄上人林泉四首》之二：“有蝶堪成梦，无羊可触藩。”","s":"《庄子集释》卷一下〈内篇·齐物论〉～2～","w":"昔者庄周梦为胡蝶，栩栩然胡蝶也，自喻适志与！不知周也。俄然觉，则蘧蘧然周也。不知周之梦为胡蝶与，胡蝶之梦为周与？周与胡蝶，则必有分矣。此之谓物化。","q":[["梦得成胡蝶，芳菲幸不遗。","刘威 闰三月"],["愿作南华蝶，翩翩绕此条。","吴融 杏花"]]},{"n":"五车书","d":"五车书：喻指读书多，学问深。唐王维《戏赠张五弟湮三首》之二：“张弟五车书，读书仍隐居。”","s":"《庄子集释》卷十下〈杂篇·天下〉～02～","w":"惠施多方，其书五车，其道舛驳，其言也不中。历物之意，曰：「至大无外，谓之大一；至小无内，谓之小一。无厚，不可积也，其大千里。天与地卑，山与泽平。日方中方睨，物方生方死。大同而与小同异，此之谓小同异；万物毕同毕异，此之谓大同异。南方无穷而有穷…","q":[["男儿一片气，何必五车书。","孟浩然 送告八从军"],["世人如要问生涯，满架堆床是五车。","方干 题悬溜岩隐者居"]]},{"n":"凤栖碧梧","d":"","s":"《庄子集释》卷六下〈外篇·秋水〉～605～","w":"惠子相梁，庄子往见之。或谓惠子曰：「庄子来，欲代子相。」于是惠子恐，搜于国中三日三夜。庄子往见之，曰：「南方有鸟，其名为鹓雏，子知之乎？夫鹓雏发于南海而飞于北海，非梧桐不止，非练实不食，非醴泉不饮。于是鸱得腐鼠，鹓雏过之，仰而视之曰：『吓！…","q":[]},{"n":"公器","d":"","s":"《庄子》外篇·卷五下《天运》","w":"「名，公器也，不可多取。仁义，先王之蘧庐也，而不可以久处，觏而多责。」晋·郭象注：「夫名者，天下之所共用。」唐·成玄英疏：「夫令誉善名，天下共用，必其多取，则矫饰过实而争竞斯起也。」","q":[["所不卖公器，动为苍生谋。","王维 献始兴公"],["名为公器无多取，利是身灾合少求。","白居易 感兴二首"]]},{"n":"含哺鼓腹","d":"","s":"《庄子》外篇·卷四中《马蹄》","w":"「夫赫胥氏之时，民居不知所为，行不知所之，含哺而熙，鼓腹而游，民能以此矣。」唐·成玄英疏：「赫胥，上古帝王也；亦言有赫然之德，使民胥附，故曰赫胥，盖炎帝也。夫行道之时，无为之世，心绝缘虑，安居而无所为；率性而动，游行而无所往。既而含哺而熙戏…","q":[["逍遥自得意，鼓腹醉中游。","岑参 南溪别业"],["触邪羊唅唅，鼓腹叟嘻嘻。","贯休 寿春节进"]]},{"n":"鼓盆歌","d":"漆园歌：喻丧妻及丧妻之痛。清王夫之《续哀雨诗》：“他日凭收柴市骨，此生已厌漆园歌。”","s":"《庄子集释》卷六下〈外篇·至乐〉～64～","w":"庄子妻死，惠子吊之，庄子则方箕踞鼓盆而歌。惠子曰：「与人居长子，老身死，不哭亦足矣，又鼓盆而歌，不亦甚乎！」庄子曰：「不然。是其始死也，我独何能无概然！察其始而本无生，非徒无生也，而本无形，非徒无形也，而本无气。杂乎芒芴之间，变而有气，气变…","q":[]},{"n":"鼓庄盆","d":"","s":"《庄子》外篇·卷六下《至乐》","w":"「庄子妻死，惠子吊之，庄子则方箕踞鼓盆而歌。」唐·成玄英疏：「盆，瓦缶也。庄子知生死之不二，达哀乐之为一，是以妻亡不哭，鼓盆而歌，垂脚箕踞，敖然自乐。」","q":[["小于潘岳头先白，学取庄周泪莫多。","元稹 六年春遣怀八首"],["相逢且问昭州事，曾鼓庄盆对逝川。","薛逢 送韩绛归淮南寄韩绰先辈"]]},{"n":"曳尾龟","d":"曳尾：咏雅逸生活。唐齐己《刳肠龟》：“到肠徒自屠，曳尾复何累。”","s":"《庄子》外篇·卷六下《秋水》","w":"「庄子钓于濮水，楚王使大夫二人往先焉，曰：『愿以境内累矣！』庄子持竿不顾，曰：『吾闻楚有神龟，死已三千岁矣，王巾笥而藏之庙堂之上。此龟者，宁其死为留骨而贵乎，宁其生而曳尾于涂中乎？』二大夫曰：『宁生而曳尾涂中。』庄子曰：『往矣！吾将曳尾于涂…","q":[["还寻九江去，安肯曳泥途。","丁泽 龟负图东都试"],["李斯溷鼠心应动，庄叟泥龟意已坚。","李咸用 物情"]]},{"n":"邯郸步","d":"邯郸步：指学习方法不当，不仅未学到新技能，反而失去了原有技能。宋欧阳修《镇阳读书》：“有类邯郸步，两失皆茫茫。”","s":"《庄子集释》卷六下〈外篇·秋水〉～598～","w":"公子牟隐机大息，仰天而笑曰：「子独不闻夫埳井之蛙乎？谓东海之鳖曰：『吾乐与！出跳梁乎井干之上，入休乎缺甃之崖；赴水则接腋持颐，蹶泥则没足灭跗；还虷蟹与科斗，莫吾能若也。且夫擅一壑之水，而跨跱埳井之乐，此亦至矣，夫子奚不时来入观乎！』东海之鳖…","q":[["邯郸笑匍匐，燕蒯受揶揄。","元稹 酬乐天东南行诗一百韵"],["寿陵失本步，笑杀邯郸人。","李白 古风之三十五"]]},{"n":"户外之屦","d":"","s":"《庄子集释》卷十上〈杂篇·列御寇〉～036～","w":"列御寇之齐，中道而反，遇伯昏瞀人。伯昏瞀人曰：「奚方而反？」伯昏瞀人曰：「善哉观乎！女处己，人将保女矣！」无几何而往，则户外之屦满矣。唐·成玄英疏：「无几何，谓无多时也。俄顷之间，伯昏往御寇之所，适见脱屦户外，跣足升堂，请益者多矣。」","q":[]},{"n":"环堵","d":"","s":"《庄子集释》卷九下〈杂篇·让王〉～975～","w":"原宪居鲁，环堵之室，茨以生草，蓬户不完，桑以为枢而瓮牖，二室，褐以为塞，上漏下湿，匡坐而弦。子贡乘大马，中绀而表素，轩车不容巷，往见原宪。原宪华冠縰履，杖藜而应门。子贡曰：「嘻！先生何病？」原宪应之曰：「宪闻之：『无财谓之贫，学而不能行谓之…","q":[]},{"n":"火膏","d":"","s":"《庄子》内篇·卷二中《人间世》","w":"山木自寇也，膏火自煎也。桂可食，故伐之；漆可用，故割之。人皆知有用之用，而莫知无用之用也。","q":[["何言为用薄，而与火膏同。","张九龄 杂诗五首"],["木直几自寇，石坚亦他攻。","张九龄 杂诗五首"]]},{"n":"魏王瓠","d":"魏王瓠：谦称自己才能差。唐储光羲《贻王侍御出台椽丹阳》：“南华在濠上，谁辨魏王瓠？”","s":"《庄子》内篇·卷一上《逍遥游》","w":"惠子谓庄子曰：「魏王贻我大瓠之种，我树之成而实五石，以盛水浆，其坚不能自举也。剖之以为瓢，则瓠落无所容。非不呺然大也，吾为其无用而掊之。」庄子曰：「夫子固拙于用大矣。宋人有善为不龟手之药者，世世以洴澼絖为事。客闻之，请买其方百金。聚族而谋曰…","q":[["南华在濠上，谁辩魏王瓠。","储光羲 贻王侍御出台掾丹阳"],["如何今濩落，闻君辛苦辞。","刘禹锡 和董庶中古散调词赠尹果毅"]]},{"n":"閒倚梧桐","d":"","s":"《庄子集释》卷二下〈内篇·德充符〉～222～","w":"庄子曰：「道与之貌，天与之形，无以好恶内伤其身。今子外乎子之神，劳乎子之精，倚树而吟，据槁梧而瞑。天选子之形，子以坚白鸣！」晋·郭象注：「夫神不休于性分之内，则外矣；精不止于自生之极，则劳矣。故行则倚树而吟，坐则据梧而睡，言有情者之自困也。…","q":[]},{"n":"决浮云","d":"","s":"《庄子》杂篇·卷十上《说剑》","w":"「此剑直之无前，举之无上，案之无下，运之无旁，上决浮云，下绝地纪。此剑一用，匡诸侯，天下服矣。此天子之剑也。」","q":[["不如持我决浮云，无令漫漫蔽白日。","白居易 新乐府（并序）之鸦九剑之思决壅也"]]},{"n":"两忘","d":"","s":"《庄子》内篇·卷三上《大宗师》","w":"「与其誉尧而非桀也，不如两忘而化其道。」","q":[["诚不如两忘，但以一概量。","韩愈 读皇甫湜公安园池诗书其后二首之一"]]},{"n":"六合","d":"","s":"《庄子集释》卷一下〈内篇·齐物论〉～83～","w":"夫道未始有封，言未始有常，为是而有畛也，请言其畛：有左，有右，有伦，有义，有分，有辩，有竞，有争，此之谓八德。六合之外，圣人存而不论；六合之内，圣人论而不议。春秋经世先王之志，圣人议而不辩。故分也者，有不分也；辩也者，有不辩也。曰：何也？圣…","q":[]},{"n":"蒙叟嗤夭","d":"","s":"《史记》卷六十三〈老子韩非列传·老子〉～243～","w":"庄子者，蒙人也，名周。唐·司马贞《史记索隐》：「《地理志》蒙县属梁国。刘向《别录》云宋之蒙人也。」","q":[]},{"n":"木尽天年","d":"","s":"《庄子集释》卷七上〈外篇·山中木〉～668～","w":"明日，弟子问于庄子曰：「昨日山中之木，以不材得终其天年；今主人之雁，以不材死；先生将何处？」庄子笑曰：「周将处乎材与不材之间。材与不材之间，似之而非也，故未免乎累。若夫乘道德而浮游则不然。」","q":[["虫全性命缘无毒，木尽天年为不才。","白居易 闲卧有所思二首"]]},{"n":"蓬心","d":"","s":"《庄子》内篇·卷一上《逍遥游》","w":"「今子有五石之瓠，何不虑以为大樽而浮乎江湖，而忧其瓠落无所容？则夫子犹有蓬之心也夫！」唐·成玄英疏：「蓬，草名，拳曲不直也。……而惠生既有蓬心，未能直达玄理，故妄起掊击之譬，讥刺《庄子》之书。」唐·陆德明《经典释文》引向秀云：「蓬者短不畅，…","q":[["鴳翼尝披隼，蓬心类倚麻。","柳宗元 同刘二十八院长述旧言怀感时书事奉寄澧州张员外使君五十二韵之作因其韵增至八十通赠二君子"]]},{"n":"漆园说剑","d":"","s":"《庄子》杂篇·卷十上《说剑》","w":"昔赵文王喜剑，剑士夹门而客三千馀人，日夜相击于前，死伤者岁百馀人，好之不厌。如是三年，国衰，诸侯谋之。太子悝患之，募左右曰：「孰能说王之意止剑士者，赐之千金。」左右曰：「庄子当能。」 ……曰：「天子之剑，以燕溪石城为锋，齐岱为锷，晋魏为脊，…","q":[["说剑尝宗漆园吏，戒严应笑棘门军。","独孤及 得柳员外书封寄近诗书中兼报新主行营兵马因代书戏答"]]},{"n":"千金聘楚","d":"","s":"《史记》卷六十三〈老子韩非列传·庄子〉～245～","w":"楚威王闻庄周贤，使使厚币迎之，许以为相。庄周笑谓楚使者曰：「千金，重利；卿相，尊位也。子独不见郊祭之牺牛乎？养食之数岁，衣以文绣，以入大庙。当是之时，虽欲为孤豚，岂可得乎？子亟去，无污我。我宁游戏污渎之中自快，无为有国者所羁，终身不仕，以快…","q":[]},{"n":"千里不留行","d":"","s":"《庄子集释》卷十上〈杂篇·说剑〉～06～","w":"昔赵文王喜剑，剑士夹门而客三千馀人，日夜相击于前，死伤者岁百馀人，好之不厌。如是三年，国衰，诸侯谋之。太子悝患之，募左右曰：「孰能说王之意止剑士者，赐之千金。」左右曰：「庄子当能。」太子乃使人以千金奉庄子。庄子弗受，与使者俱往见太子曰：「太…","q":[["十步杀一人，千里不留行。","李白 侠客行"]]},{"n":"说剑","d":"","s":"《庄子集释》卷十上〈杂篇·说剑〉～06～","w":"昔赵文王喜剑，剑士夹门而客三千馀人，日夜相击于前，死伤者岁百馀人，好之不厌。如是三年，国衰，诸侯谋之。太子悝患之，募左右曰：「孰能说王之意止剑士者，赐之千金。」左右曰：「庄子当能。」太子乃使人以千金奉庄子。……庄子曰：「诺。周善为剑。」………","q":[["庄周空说剑，墨翟耻论兵。","李白 秋夜独坐怀故山"],["谈天信浩荡，说剑纷纵横。","李白 赠韦秘书子春二首"]]},{"n":"庙牺","d":"","s":"《庄子集释》卷十下〈杂篇·列御寇〉～062～","w":"或聘于庄子。庄子应其使曰：「子见夫牺牛乎？衣以文绣，食以刍叔，及其牵而入于大庙，虽欲为孤犊，其可得乎！」","q":[["孤豚眠粪壤，不慕太庙牺。","韩愈 寄崔二十六立之"],["莫学鲁人疑海鸟，须知庄叟恶牺牛。","罗隐 村桥"]]},{"n":"万窍号呼","d":"","s":"《庄子集释》卷一下〈内篇·齐物论〉～45～","w":"子綦曰：「偃，不亦善乎，而问之也！今者吾丧我，汝知之乎？女闻人籁而未闻地籁，女闻地籁而未闻天籁夫！」子游曰：「敢问其方。」子綦曰：「夫大块噫气，其名为风。是唯无作，作则万窍怒呺。而独不闻之翏翏乎？山林之畏佳，大木百围之窍穴，似鼻，似口，似耳…","q":[]},{"n":"刳肠","d":"","s":"《庄子集释》卷九上〈杂篇·外物〉～933～","w":"宋元君夜半而梦人被发窥阿门，曰：「予自宰路之渊，予为清江使河伯之所，渔者余且得予。」元君觉，使人占之，曰：「此神龟也。」君曰：「渔者有余且乎？」左右曰：「有。」君曰：「令余且会朝。」明日，余且朝。君曰：「渔何得？」对曰：「且之网得白龟焉，其…","q":[["有志酬毛宝，无心畏豫且。","李群玉 龟"],["龟灵未免刳肠患，马失应无折足忧。","白居易 放言五首"]]},{"n":"无趾","d":"","s":"《庄子集释》卷二下〈内篇·德充符〉～202～","w":"鲁有兀者叔山无趾，踵见仲尼。仲尼曰：「子不谨，前既犯患若是矣。虽今来，何及矣！」无趾曰：「吾唯不知务而轻用吾身，吾是以亡足。今吾来也，犹有尊足者存，吾是以务全之也。夫天无不覆，地无不载，吾以夫子为天地，安知夫子之犹若是也！」","q":[["支离无趾犹自免，努力低飞逃后患。","柳宗元 跂乌词"]]},{"n":"向雕陵","d":"","s":"《庄子》外篇·卷七上《山木》","w":"庄周游于雕陵之樊，一异鹊自南方来者，翼广七尺，目大运寸，感周之颡而集于栗林。庄周曰：「此何鸟哉，翼殷不逝，目大不？」蹇裳躩步，执弹而留之。一蝉，方得美荫而忘其身；螳螂执翳而搏之，见得而忘其形；异鹊从而利之，见利而忘其真。庄周怵然曰：「噫！物…","q":[["知来有乾鹊，何不向雕陵。","李商隐 北禽"]]},{"n":"逍遥蒙庄子","d":"","s":"《庄子集释》卷一上〈内篇·逍遥游〉～7～","w":"若夫乘天地之正，而御六气之辩，以游无穷者，彼且恶乎待哉！故曰，至人无己，神人无功，圣人无名。","q":[["逍遥自在蒙庄子，汉主徒言河上公。","赵彦昭 奉和圣制幸韦嗣立山庄应制"]]},{"n":"夜持山去","d":"","s":"《庄子集释》卷三上〈内篇·大宗师〉～243～","w":"夫藏舟于壑，藏山于泽，谓之固矣。然而夜半有力者负之而走，昧者不知也。","q":[]},{"n":"专云壑","d":"","s":"《庄子集释》卷六下〈外篇·秋水〉～597～","w":"公孙龙问于魏牟曰：「龙少学先王之道，长而明仁义之行，合同异，杂坚白，然不然，可不可，困百家之知，穷众口之辩，吾自以为至达已。今吾闻庄子之言，茫焉异之，不知论之不及与，知之弗若与？今吾无所开吾喙，敢问其方。」公子牟隐机大息，仰天而笑曰：「子独…","q":[]},{"n":"贮火","d":"","s":"《庄子集释》卷九上〈杂篇·外物〉～920～","w":"外物不可必，故龙逢诛，比干戮，箕子狂，恶来死，桀纣亡。人主莫不欲其臣之忠，而忠未必信，故伍员流于江，苌弘死于蜀，藏其血三年而化为碧。人亲莫不欲其子之孝，而孝未必爱，故孝己忧而曾参悲。木与木相摩则然，金与火相守则流。阴阳错行，则天地大絯，于是…","q":[["心讶愁来惟贮火，眼知别后自添花。","韩愈 次邓州界"]]},{"n":"庄周打髑髅","d":"","s":"《庄子集释》卷六下〈外篇·至乐〉～67～","w":"庄子之楚，见空髑髅，髐然有形，撽以马捶，因而问之，曰：「夫子贪生失理，而为此乎？将子有亡国之事，斧钺之诛，而为此乎？将子有不善之行，愧遗父母妻子之丑，而为此乎？将子有冻馁之患，而为此乎？将子之春秋故及此乎？」于是语卒，援髑髅枕而卧。夜半，髑…","q":[]},{"n":"子桑寒饥","d":"","s":"《庄子集释》卷三上〈内篇·大宗师〉～285～","w":"子舆与子桑友，而霖雨十日。子舆曰：「子桑殆病矣！」裹饭而往食之。至子桑之门，则若歌若哭，鼓琴曰：「父邪！母邪！天乎！人乎！」有不任其声而趋举其诗焉。","q":[["昔年十日雨，子桑苦寒饥。哀歌坐空室，不怨但自悲。其友名子舆，忽然忧且思。搴裳触泥水，裹饭往食之。","韩愈 赠崔立之"]]}],"5":[{"n":"爱吾庐","d":"","s":"《陶渊明集》卷四〈读山海经十三首〉","w":"孟夏草木长，绕屋树扶疏。众鸟欣有托，吾亦爱吾庐。既耕亦已种，时还读我书。穷巷隔深辙，颇回故人车。欢然酌春酒，摘我园中蔬。微雨从东来，好风与之俱。泛览周王传，流观山海图。俯仰终宇宙，不乐复何如。","q":[["岂知陶靖节，只自爱吾庐。","李德裕 郊外即事寄侍郎大尹"],["偃须求五鼎，陶只爱吾庐。","杜牧 春末题池州弄水亭"]]},{"n":"羲皇上","d":"羲皇人：指生活清闲自适。唐李白《戏赠郑溧阳》：“清风北窗下，自谓羲皇人。”","s":"《全上古三代秦汉三国六朝文·全晋文》卷一百十一〈陶潜·与子俨等书〉～2097～","w":"告俨、俟、份、佚、佟。夫天地赋命，有生必有终，自古圣贤，谁能独免。子夏言曰：「死生有命，富贵在天。」四友之人，亲受音旨。发斯谈者，岂非穷达不可妄求，寿夭永无外请故邪。吾年过五十，少而穷苦荼毒。每以家毙，东西游走。性刚才拙，与物多忤。自量为已…","q":[["腹中无一物，高话羲皇年。","储光羲 同王十三维偶然作十首之三"],["竹庭瓶水新，深称北窗人。","周贺 赠皎然上人（一本无皎字）"]]},{"n":"醉菊花","d":"白衣酒：喻饮酒，或喻菊花。唐罗隐《菊丶“千载白衣酒，一生青女霜。”","s":"《艺文类聚》卷四〈岁时部中·九月九日〉～8～","w":"南朝宋·檀道鸾《续晋阳秋》曰。陶潜尝九月九日无酒。宅边菊丛中。摘菊盈把。坐其侧久。望见白衣至。乃王弘送酒也。即便就酌。醉而后归。","q":[["一丛黄菊地，九日白衣人。","刘方平 寄陇右严判官"],["无劳白衣酒，陶令自相携。","刘长卿 九日登李明府北楼"]]},{"n":"望白云","d":"","s":"晋·陶潜《陶渊明集》卷一《停云·序》","w":"「《停云》，思亲友也。」「其诗云：『霭霭停云。濛濛时雨。八表同昏。平路伊阻。静寄东轩。春醪独抚。良朋悠邈。搔首延伫。』『愿言怀人，舟车靡从。』『岂无他人，念子实多。愿言不获，抱恨如何。』」","q":[["致君丹槛折，哭友白云长。","杜甫 闻高常侍亡（原注。忠州作。）"],["老罢知明镜，悲来望白云。","杜甫 怀旧"]]},{"n":"杯中物","d":"","s":"《陶渊明集》卷三〈责子〉","w":"天运苟如此，且进杯中物。","q":[["清动杯中物，高随海上查。","杜甫 季秋苏五弟缨江楼夜宴崔十三评事韦少府侄三首"],["赖有杯中物，还同海上鸥。","杜甫 巴西驿亭观江涨呈窦使君二首"]]},{"n":"武陵溪","d":"桃源：后用以指隐居处或仙境。唐杜甫《不寐》：“多垒满山谷，桃源何处求？”","s":"《陶渊明集》卷六〈桃花源记〉","w":"晋太元中，武陵人捕鱼为业。缘溪行，忘路之远近，忽逢桃花林，夹岸数百步，中无杂树。芳草鲜美，落英缤纷。渔人甚异之，复前行，欲穷其林。林尽水源，便得一山，山有小口，仿佛若有光，便舍船从口入。初极狭，才通人，复行数十步，豁然开朗。土地平旷，屋舍俨…","q":[["浮世度千载，桃源方一春。","于武陵 赠王道士"],["曾逢异人说，风景似桃源。","于鹄 南溪书斋"]]},{"n":"不求甚解","d":"","s":"《陶渊明集》卷六〈五柳先生传〉","w":"闲静少言，不慕荣利。好读书，不求甚解，每有会意，欣然忘食。","q":[["书不求甚解，琴聊以自娱。","白居易 松斋自题"]]},{"n":"归去来","d":"","s":"《宋书》卷九十三〈隐逸列传·陶潜〉","w":"陶潜字渊明，或云渊明字元亮，寻阳柴桑人也。潜少有高趣，……闲静少言，不慕荣利。好读书，……躬耕自资，遂抱羸疾，复为镇军、建威参军，谓亲朋曰：「聊欲弦歌，以为三径之资，可乎？」执事者闻之，以为彭泽令。……郡遣督邮至，县吏白应束带见之，潜叹曰：…","q":[["陶令之官去，穷愁惨别魂。","崔峒 送陆明府之盱眙"],["前贤未必全堪学，莫读当时归去篇。","方干 送永嘉王令之任二首之一"]]},{"n":"见南山","d":"","s":"《陶渊明集》卷三〈饮酒二十首〉","w":"〈饮酒二十首〉其五：「采菊东篱下，悠然见南山。」","q":[["林端忽见南山色，马上还吟陶令诗。","钱起 晚过横灞寄张蓝田"]]},{"n":"荒三径","d":"","s":"《晋书》卷九十四〈隐逸列传·陶潜〉～246～","w":"义熙二年，解印去县，乃赋归去来。其辞曰：归去来兮，田园将芜，胡不归？既自以心为形役，奚惆怅而独悲？悟已往之不谏，知来者之可追。实迷途其未远，觉今是而昨非。舟遥遥以轻飏，风飘飘而吹衣，问征夫以前路，恨晨光之希微。乃瞻衡宇，载欣载奔，僮仆来迎，…","q":[["草生元亮径，花暗子云居。","王绩 田家三首"]]},{"n":"东篱菊","d":"","s":"晋·陶潜《陶渊明集》卷三《饮酒二十首》其五","w":"结庐在人境，而无车马喧。问君何能尔？心远地自偏。采菊东篱下，悠然见南山。山气日夕佳，飞鸟相与还。此还有真意，欲辩已忘言。","q":[["陶令篱边菊，秋来色转佳。","公乘亿 赋得秋菊有佳色"],["自有东篱菊，年年解作花。","刘长卿 过湖南羊（一作来）处士别业"]]},{"n":"我醉欲眠","d":"","s":"《宋书》卷九十三〈隐逸列传·陶潜〉","w":"潜不解音声，而畜素琴一张，无弦，每有酒适，辄抚弄以寄其意。贵贱造之者，有酒辄设，潜若先醉，便语客：「我醉欲眠，卿可去。」其真率如此。","q":[]},{"n":"樊笼","d":"","s":"《陶渊明集》卷二《归田园居五首》其一","w":"久在樊笼里，复得返自然。","q":[["本不将心挂名利，亦无情意在樊笼。","李群玉 请告出春明门"]]},{"n":"鸟倦飞还","d":"","s":"晋·陶潜《陶渊明集》卷五《归去来兮辞》","w":"策扶老而流憩，时翘首而遐观。云无心而出岫，鸟倦飞而知还","q":[["虚舟尚叹萦难解，飞鸟空惭倦未还。","崔橹 春晚岳阳言怀二首"]]},{"n":"孤云","d":"","s":"《昭明文选》卷三十〈诗己·杂诗下·咏贫士诗〉～39～","w":"万族各有托，孤云独无依。暧暧虚中灭，何时见馀辉。朝霞开宿雾，众鸟相与飞。迟迟出林翮，未夕复来归。量力守故辙，岂不寒与饥。知音苟不存，已矣何所悲！","q":[["孤云终负约，薄宦转堪伤。","郑谷 谷自乱离之后在西蜀半纪之馀多寓止精舍与园昉上人为净侣昉公于长松山旧斋尝约他日访会劳生多故游宦数年曩契未谐忽闻谢世吊吟四韵以吊之"]]},{"n":"五柳先生","d":"五株柳：喻指隐者。唐李白《嘲王厉阳不肯饮酒》。“浪抚一张琴，虚栽五株柳。”","s":"《宋书》卷九十三〈隐逸列传·陶潜〉～2286～","w":"潜少有高趣，尝著五柳先生传以自况，曰：「先生不知何许人，不详姓字，宅边有五柳树，因以为号焉。闲静少言，不慕荣利。好读书，不求甚解，每有会意，欣然忘食。性嗜酒，而家贫不能恒得。亲旧知其如此，或置酒招之，造饮辄尽，期在必醉，既醉而退，曾不吝情去…","q":[["高柳三五株，可以独逍遥。","储光羲 同王十三维偶然作十首"],["谢公台尚在，陶令柳潜衰。","刘得仁 和段校书冬夕寄题庐山"]]},{"n":"过虎溪","d":"虎溪相送：咏僧人。明吴廷翰《怀白云寺僧》：“几度南山不得归，虎溪相送迹应稀。”","s":"《莲社高贤传·百二十三人传》","w":"时远法师居东林。其处流泉匝寺下入于溪。每送客过此。辄有虎号鸣。因名虎溪。后送客未尝过。独陶渊明与修静至。语道契合不觉过溪。因相与大笑。","q":[["自喜他年接巾舄，沧浪地近虎溪头。","刘沧 与重幽上人话旧"],["日暮辞远公，虎溪相送出。","孟浩然 疾愈过龙泉寺精舍呈易业二公"]]},{"n":"羁鸟","d":"","s":"《陶渊明集》卷二《归田园居五首》其一","w":"羁鸟恋旧林，池鱼思故渊。","q":[["欲辞松月恋知音，去住多同羁鸟心。","刘沧 留别山中友人"]]},{"n":"閒情赋","d":"","s":"《全上古三代秦汉三国六朝文·全晋文》卷一百十一〈陶潜·闲情赋〉～2096～","w":"初张衡作〈定情赋〉，蔡邕作〈静情赋〉，检逸辞而宗澹泊，始则荡以虑，而终归闲正。将以抑流宕之邪心，谅有助于讽谏。缀文之士，奕代继作，并因触类，广其辞义。余园闾多暇，复染翰为之。虽文妙不足，庶不谬作者之意乎？","q":[]},{"n":"陶渊明","d":"","s":"南朝梁·钟嵘《诗品》卷中","w":"宋征士陶潜……古今隐逸诗人之宗也。","q":[["悬冠谢陶令，褫佩怀疏傅。","元晦 越亭二十韵"],["此尊可常满，谁是陶渊明。","元结 窊尊诗"]]},{"n":"靖节松","d":"","s":"《晋书》卷九十四〈隐逸列传·陶潜〉～246～","w":"归去来兮，田园将芜，胡不归？既自以心为形役，奚惆怅而独悲？悟已往之不谏，知来者之可追。实迷途其未远，觉今是而昨非。舟遥遥以轻飏，风飘飘而吹衣，问征夫以前路，恨晨光之希微。乃瞻衡宇，载欣载奔，僮仆来迎，稚子候门。三径就荒，松菊犹存。携幼入室，…","q":[]},{"n":"靖节勇退","d":"","s":"《全上古三代秦汉三国六朝文·全晋文》卷一百十一〈陶潜·感士不遇赋〉～2095～2～","w":"世流浪而遂徂，物群分以相形。密网裁而鱼骇，宏罗制而鸟惊。彼达人之善觉，乃逃禄而归耕。","q":[]},{"n":"篮舆","d":"","s":"《宋书》卷九十三《隐逸传·陶潜传》","w":"江州刺史王弘欲识之，不能致也。潜尝往庐山，弘令潜故人庞通之赍酒具于半道栗里要之，潜有脚疾，使一门生二儿舆篮舆，既至，欣然便共饮酌，俄顷弘至，亦无忤也。","q":[["想到家山无俗侣，逢迎只是坐篮舆。","权德舆 送李处士归弋阳山居"],["偶值乘篮舆，非关避白衣。","王维 酬严少尹徐舍人见过不遇"]]},{"n":"量革履","d":"","s":"《晋书》卷九十四《隐逸传·陶潜传》","w":"刺史王弘以元熙中临州，甚钦迟之，后自造焉。潜称疾不见，既而语人云：「我性不狎世，因疾守闲，幸非洁志慕声，岂敢以王公纡轸为荣邪！夫谬以不贤，此刘公干所以招谤君子，其罪不细也。」弘每令人候之，密知当往庐山，乃遣其故人庞通之等赍酒，先于半道要之。…","q":[["为君量革履，且愿住蓝舆。","韦应物 送丘员外归山"]]},{"n":"漉酒巾","d":"","s":"《宋书》卷九十三《隐逸传·陶潜传》","w":"贵贱造之者，有酒辄设，潜若先醉，便语客：「我醉欲眠，卿可去。」其真率如此。郡将候潜，值其酒熟，取头上葛巾漉酒，毕，还复著之。","q":[["草堂窗底漉春醅，山寺门前逢暮雨。","刘言史 葛巾歌"],["漉酒有巾无黍酿，负他黄菊满东篱。","司空图 五十"]]},{"n":"慢陶潜","d":"","s":"《晋书》卷九十四《隐逸传·陶潜传》","w":"执事者闻之，以为彭泽令。……郡遣督邮至县，吏白应束带见之，潜叹曰：「吾不能为五斗米折腰，拳拳事乡里小人邪！」义熙二年，解印去县，乃赋归去来。","q":[["他时如按县，不得慢陶潜。","杜甫 东津送韦讽摄阆州录事"]]},{"n":"渊明粟","d":"","s":"《先秦汉魏晋南北朝诗·晋诗》卷十六〈陶潜·归去来兮〉～986～","w":"余家贫，耕植不足以自给。幼稚盈室，瓶无储粟。","q":[]},{"n":"无弦琴","d":"无弦琴：喻自寻乐趣，或喻意趣高雅，或表示弦外情味。唐白居易《丘中有一士》之二：“行披带索衣，坐拍无弦琴。”","s":"《宋书》卷九十三〈隐逸列传·陶潜〉","w":"潜不解音声，而畜素琴一张，无弦，每有酒适，辄抚弄以寄其意。","q":[["陶令若能兼不饮，无弦琴亦是沽名。","司空图 书怀"],["五柳先生自识微，无言共笑手空挥。","司空图 歌者十二首"]]},{"n":"五斗米","d":"五斗米：喻微薄俸禄。唐岑参《送许拾遗恩归江宁拜亲》：“看君五斗米，不谢万户侯。”；斗粟：喻兄弟相残。唐李商隐《和郑愚赠汝阳王孙家筝妓二十韵》：“斗粟配新声，娣侄徒纤指。”","s":"《宋书》卷九十三〈隐逸列传·陶潜〉","w":"陶潜字渊明，或云渊明字元亮，寻阳柴桑人也。曾祖侃，晋大司马。潜少有高趣，尝著五柳先生传以自况，曰：先生不知何许人，不详姓字，宅边有五柳树，因以为号焉。闲静少言，不慕荣利。好读书，不求甚解，每有会意，欣然忘食。性嗜酒，而家贫不能恒得。亲旧知其…","q":[["想君畴昔高步时，肯料如今折腰事。","刘长卿 颍川留别司仓李万"],["折腰五斗间，僶俛随尘埃。","刘长卿 硖石遇雨宴前主簿从兄子英宅"]]},{"n":"陶令东皋","d":"","s":"《先秦汉魏晋南北朝诗·晋诗》卷十六〈陶潜·归去来兮〉～988～","w":"富贵非吾愿，帝乡不可期。怀良辰以孤往，或植杖而耘耔。登东皋以舒啸，临清流而赋诗。聊乘化以归尽，乐夫天命复奚疑。","q":[]},{"n":"陶令田园计","d":"","s":"《晋书》卷九十四〈隐逸列传·陶潜〉～246～","w":"以亲老家贫，起为州祭酒，不堪吏职，少日自解归。州召主簿，不就，躬耕自资，遂抱羸疾。复为镇军、建威参军，谓亲朋曰：「聊欲弦歌，以为三径之资可乎？」执事者闻之，以为彭泽令。在县公田悉令种秫谷，曰：「令吾常醉于酒足矣。」妻子固请种，乃使一顷五十…","q":[]},{"n":"陶令五男","d":"","s":"《陶渊明集》卷三《责子诗》","w":"白发被两鬓，肌肤不复实。虽有五男儿，总不好纸笔。","q":[["陶令五男曾不有，蒋生三径枉相过。","裴迪 春日与王右丞过新昌里访吕逸人不遇"]]},{"n":"陶潜观海图","d":"","s":"《陶渊明集》卷四〈读山海经十三首〉其一","w":"〈读山海经十三首〉其一：「孟夏草木长，绕屋树扶疏。众鸟欣有托，吾亦爱吾庐。既耕亦已种，时还读我书。 穷巷隔深辙，颇回故人车。欢然酌春酒，摘我园中蔬。微雨从东来，好风与之俱。 泛览周王传，流观山海图。俯仰终宇宙，不乐复何如？」","q":[["陶潜虽好事，观海只披图。","李德裕 海鱼骨"]]},{"n":"陶谢","d":"","s":"《宋书》卷九十三〈隐逸列传·陶潜〉～2287～","w":"亲老家贫，起为州祭酒，不堪吏职，少日，自解归。州召主簿，不就。躬耕自资，遂抱羸疾，复为镇军、建威参军，谓亲朋曰：「聊欲弦歌，以为三径之资，可乎？」执事者闻之，以为彭泽令。公田悉令吏种秫稻，妻子固请种，乃使二顷五十亩种秫，五十亩种。郡遣督…","q":[["喜于风骚地，忽见陶谢手。","李群玉 赠方处士兼以写别"],["新诗山水思，静入陶谢格。","李群玉 送郑子宽弃官东游便归女几"]]},{"n":"渊明趣","d":"","s":"《先秦汉魏晋南北朝诗·晋诗》卷十六〈陶潜·归去来兮〉～987～","w":"归去来兮田园将芜胡不归，既自以心为形役。奚惆怅而独悲，悟已往之不谏。知来者之可追，实迷途其未远，觉今是而昨非。舟遥遥以轻飏，风飘飘而吹衣。问征夫以前路，恨晨光之熹微。乃瞻衡宇，载欣载奔。僮仆欢迎，稚子候门。三径就荒，松菊犹存。携幼入室，有酒…","q":[]},{"n":"通子","d":"","s":"《陶渊明集》卷三《责子诗》","w":"虽有五男儿，总不好纸笔。……通子垂九龄，但觅梨与栗。","q":[["梨教通子守，酒是远师供。","李端 长安感事呈卢纶"],["各有文姬才稚齿，俱无通子继馀尘。","白居易 余思未尽加为六韵重寄微微"]]},{"n":"闲情赋","d":"","s":"《陶渊明集》卷五《闲情赋》","w":"初张衡作《定情赋》，蔡邕作《静情赋》，检逸辞而宗澹泊，始则荡以思虑，而终归闲正。将以抑流宕之邪心，谅有助于讽谏，缀文之士，奕代继作。并因触类，广其辞义，余园闾多暇，复染翰为之，虽文妙不足，庶不谬作者之意乎？","q":[["闲情欲赋思陶令，卧病和人问马卿。","牟融 写意二首"]]},{"n":"形役","d":"","s":"晋·陶潜《陶渊明集》卷五《归去来兮辞》","w":"「既自以心为形役，奚惆怅而独悲。」","q":[["形役良可嗟，唯能徇天道。","司马扎 效陶彭泽"],["山下禅庵老师在，愿将形役问空王。","司马扎 晓过伊水寄龙门僧"]]},{"n":"浔阳隐","d":"","s":"《陶潜传》","w":"时周续之入庐山。事释惠远。彭城刘遗民。亦遁迹匡山。渊明又不应徵命。谓之浔阳三隐。","q":[["莫爱浔阳隐，嫌官计亦非。","司空曙 送菊潭王明府"]]},{"n":"颜公付酒钱","d":"","s":"《宋书》卷九十三《隐逸传·陶潜传》","w":"颜延之为刘柳后军功曹，在寻阳，与潜情款。后为始安郡，经过，日日造潜，每往必酣饮致醉。临去，留二万钱与潜，潜悉送酒家，稍就取酒。","q":[["颜公二十万，尽付酒家钱。","李白 赠宣城宇文太守兼呈崔侍御"]]},{"n":"渊明风致","d":"","s":"《昭明文选》卷三十〈诗己·杂诗下·杂诗二首〉～39～","w":"结庐在人境，而无车马喧。问君何能尔？心远地自偏。采菊东篱下，悠然望南山。山气日夕佳，飞鸟相与还。此还有真意，欲辩已忘言。","q":[]},{"n":"元亮井","d":"","s":"《陶渊明集》卷二〈归田园居五首〉","w":"〈归田园居五首〉其四：「井灶有遗处，桑竹残朽株。」","q":[["万里忆归元亮井，三年从事亚夫营。","李商隐 二月二日"]]},{"n":"元亮自祭","d":"","s":"晋·陶潜《陶渊明集》卷七《自祭文》","w":"岁惟丁未。律中无射。天寒夜长。风气萧索。鸿雁于征。草木黄落。陶子将辞逆旅之馆。永归于本宅。故人悽其相悲。同祖行于今夕。羞以嘉蔬。荐以清酌。候颜己冥。聆音愈漠。呜呼哀哉。茫茫大块。悠悠高旻。是生万物。余得为人。自余为人。逢运之贫。箪瓢屡罄。絺…","q":[["伯伦每置随身锸，元亮先为自祭文。","白居易 哭崔二十四常侍"]]},{"n":"愿作锦鞋","d":"","s":"《陶渊明集》卷五《闲情赋》","w":"愿在丝而为履。附素足以周旋。悲行止之有节。空委弃于床前。","q":[["知君欲作闲情赋，应愿将身作锦鞋。","段成式 嘲飞卿七首之二"]]},{"n":"种秫田","d":"","s":"《宋书》卷九十三〈隐逸列传·陶潜〉","w":"陶潜字渊明，或云渊明字元亮，寻阳柴桑人也。……性嗜酒，而家贫不能恒得。亲旧知其如此，或置酒招之，造饮辄尽，期在必醉，既醉而退，曾不吝情去留。……亲老家贫，起为州祭酒，不堪吏职，少日，自解归。州召主簿，不就。躬耕自资，遂抱羸疾，复为镇军、建威…","q":[["来岁公田多种黍，莫教黄菊笑杨朱。","刘商 重阳日寄上饶李明府"],["如求神仙药，阶下亦种黍。但使长兀然，始见天地祖。","刘驾 效陶"]]},{"n":"柴桑","d":"","s":"《宋书》卷九十三〈隐逸列传·陶潜〉","w":"陶潜字渊明，或云渊明字元亮，寻阳柴桑人也。曾祖侃，晋大司马。","q":[["若起柴桑兴，无先漉酒巾。","曹松 赠雷乡张明府"],["累职比柴桑，清秋入楚乡。","卢纶 送乐平苗明府"]]},{"n":"陶令醉","d":"","s":"《宋书》卷九十三〈隐逸列传·陶潜〉","w":"陶潜字渊明，或云渊明字元亮，寻阳柴桑人也。……性嗜酒，而家贫不能恒得。亲旧知其如此，或置酒招之，造饮辄尽，期在必醉，既醉而退，曾不吝情去留。……先是，颜延之为刘柳后军功曹，在寻阳，与潜情款。后为始安郡，经过，日日造潜，每往必酣饮致醉。临去，…","q":[["壶觞须就陶彭泽，时俗犹传晋永和。","刘长卿 三月李明府后亭泛舟"],["日得谢客游，时堪陶令醉。","刘长卿 送薛据宰涉县"]]}],"6":[{"n":"爱酒扬雄","d":"","s":"《汉书》卷八十七下〈扬雄列传下〉～3585～","w":"雄以病免，复召为大夫。家素贫，耆酒，人希至其门。时有好事者载酒肴从游学，而钜鹿侯芭常从雄居，受其太玄、法言焉。刘歆亦尝观之，谓雄曰：「空自苦！今学者有禄利，然尚不能明易，又如玄何？吾恐后人用覆酱瓿也。」雄笑而不应。","q":[["醉酒扬雄宅，升堂子贱琴。","杜甫 夏日杨长宁宅送崔侍御常正字入京"]]},{"n":"八十一家","d":"","s":"《汉书》卷八十七下〈扬雄列传下〉～3575～","w":"故《玄》三方、九州、二十七部、八十一家、二百四十三表、七百二十九赞，分为三卷。","q":[["三千馀岁上下古，八十一家文字奇。","陆龟蒙 奉和袭美暇日独处见寄"]]},{"n":"草太玄","d":"","s":"《汉书》卷八十七下〈扬雄列传下〉～3565～","w":"哀帝时丁、傅、董贤用事，诸附离之者或起家至二千石。时雄方草太玄，有以自守，泊如也。或嘲雄以玄尚白，而雄解之，号曰解嘲。其辞曰：……扬子曰：「……仆诚不能与此数公者并，故默然独守吾太玄。」……雄以病免，复召为大夫。家素贫，耆酒，人希至其门。时…","q":[["空忆去年春雨后，燕泥时污太玄经。","储嗣宗 小楼"],["能令草玄者，回思入流风。","包融 和陈校书省中玩雪"]]},{"n":"吐凤才","d":"吐凤才：指写文章的好手。唐钱起《过张成侍御宅》：“丞相幕中吐凤人，文章心事每相亲。”；白凤：指文采华美。唐刘禹锡《酬乐天见贻贺金紫之什》：“久学文章含白凤，却因政事赐金鱼。”","s":"《西京杂记》卷二～076～2～","w":"扬雄读书，有人语之曰：「无为自苦，元故难传。」忽然不见。雄著《太元经》。梦吐凤凰，集元之上，顷而灭。","q":[["二赋人间真吐凤，五年溪上不惊鸥。","何颉之 和韩子苍游赤壁"],["久学文章含白凤，却因政事赐金鱼。","刘禹锡 酬乐天见贻贺金紫之什"]]},{"n":"班扬","d":"","s":"《昭明文选》卷六十南朝宋·王僧达《祭颜光禄文》","w":"「义穷机彖，文蔽班杨。」唐·李善注：「班，班固；杨，扬雄也。」","q":[["班扬名甚盛，嵇阮逸相须。","杜甫 哭台州郑司户苏少监"],["斯文崔魏徒，以我似班扬。","杜甫 壮游"]]},{"n":"畔牢愁","d":"","s":"《汉书》卷八十七上《扬雄传上》","w":"「乃作书，往往摭《离骚》文而反之，自岷山投诸江流以吊屈原，名曰《反离骚》；又旁《离骚》作重一篇，名曰《广骚》；又旁《惜诵》以下至《怀沙》一卷，名曰《畔牢愁》。」李奇注「畔，离也。牢，聊也。与君相离，愁而无聊也。」","q":[["旧隐来寻通德里，新篇写出畔牢愁。","刘禹锡 和苏郎中寻丰安里旧居寄主客张既中"],["梦寐几回迷蛱蝶，文章应解伴牢愁。","杜牧 寄浙东韩八评事"]]},{"n":"长杨赋","d":"","s":"《汉书》卷八十七下〈扬雄列传下〉～3557～","w":"明年，上将大誇胡人以多禽兽，秋，命右扶风发民入南山，西自斜，东至弘农，南驱汉中，张罗罔罝罘，捕熊罴豪猪虎豹狖玃狐菟麋鹿，载以槛车，输长杨射熊馆。以罔为周阹，纵禽兽其中，令胡人手搏之，自取其获，上亲临观焉。是时，农民不得收敛。雄从至射熊馆，…","q":[["早晚荐雄文似者，故人今已赋长杨。","李颀 寄司勋卢员外"],["一首长杨赋，应嫌索价高。","罗隐 寄制诰李舍人"]]},{"n":"谏猎","d":"","s":"《汉书》卷八十七上《扬雄传上》","w":"其十二月羽猎，雄从。以为昔在二帝三王，宫馆台榭沼池苑囿林麓薮泽财足以奉郊庙，御宾客，充庖厨而已，不夺百姓膏腴谷土桑柘之地。女有馀布，男有馀粟，国家殷富，上下交足，故甘露零其庭，醴泉流其唐，凤皇巢其树，黄龙游其沼，麒麟臻其囿，神爵栖其林。昔者…","q":[["王孙莫谏猎，贱妾解当熊。","夏至 咏冯昭仪当熊"],["买山犹未得，谏猎又非时。","戴叔伦 客舍秋怀呈骆正字士则"]]},{"n":"问奇字","d":"玄文覆酱：喻著作高深，无人能懂，或喻毫无价值。唐陆龟蒙《记事诗》：“骏骨正牵盐，玄文终覆瓿。”；问奇字：指从师受业或向人请教。唐韩愈《题张十八所居》：“端来问奇字，为我讲声行。”","s":"《汉书》卷八十七下《扬雄传下》","w":"赞曰：……雄以病免，复召为大夫。家素贫，耆酒，人希至其门。时有好事者载酒肴从游学，而钜鹿侯芭常从雄居，受其《太玄》、《法言》焉。刘歆亦尝观之，谓雄曰：「空自苦！今学者有禄利，然尚不能明易，又如玄何？吾恐后人用覆酱瓿也。」雄笑而不应。年七十一…","q":[["拟受太玄今不遇，可怜遗恨似侯芭。","皮日休 屣步访鲁望不遇"],["莫问盐车骏，谁看酱瓿玄。","陆龟蒙 袭美见题郊居十首因次韵酬之以伸荣谢"]]},{"n":"持戟","d":"","s":"《昭明文选》卷四十二、三国魏·曹子建（植）《与杨德祖书》","w":"「昔杨子云先朝执戟之臣耳。」唐·李善注：「《汉书》曰：扬雄奏羽猎赋，为郎。然郎皆执戟而侍也。东方朔《答客难》曰：官不过侍郎，位不过执戟。」","q":[["独有扬执戟，闭关草太玄。","李白 古风"],["执戟疲于下位，老夫好隐兮墙东。","王维 登楼歌"]]},{"n":"雕虫","d":"","s":"《法言·吾子》","w":"或问「吾子少而好赋」。曰：「然。童子彫虫篆刻。」俄而，曰：「壮夫不为也。","q":[["寻章摘句老雕虫，晓月当帘挂玉弓。","李贺 南园十三首之六"],["所学近雕虫，知难谒至公。","李频 长安书怀投知己"]]},{"n":"反离骚","d":"","s":"《汉书》卷八十七上〈扬雄列传上〉～355～","w":"先是时，蜀有司马相如，作赋甚弘丽温雅，雄心壮之，每作赋，常拟之以为式。又怪屈原文过相如，至不容，作离骚，自投江而死，悲其文，读之未尝不流涕也。以为君子得时则大行，不得时则龙蛇，遇不遇命也，何必湛身哉！乃作书，往往摭离骚文而反之，自岷山投诸江…","q":[["缘情无怨刺，却似反离骚。","钱起 江行无题一百首"]]},{"n":"相如赋","d":"","s":"《史记》卷一一七《司马相如列传》","w":"司马相如者，蜀郡成都人也，字长卿。少时好读书，学击剑，故其亲名之曰犬子。相如既学，慕蔺相如之为人，更名相如。以赀为郎，事孝景帝，为武骑常侍，非其好也。会景帝不好辞赋，是时梁孝王来朝，从游说之士齐人邹阳、淮阴枚乘、吴庄忌夫子之徒，相如见而说之…","q":[["献纳开东观，君王问长卿。","杜甫 赠陈二补阙"],["孟阳题剑阁，子云献甘泉。","储光羲 酬李处士山中见赠"]]},{"n":"文似相如","d":"","s":"《汉书》卷八十七上《扬雄传上》","w":"先是时，蜀有司马相如，作赋甚弘丽温雅，雄心壮之，每作赋，常拟之以为式。……孝成帝时，客有荐雄文似相如者，上方郊祠甘泉泰畤、汾阴后土，以求继嗣，召雄待诏承明之庭。","q":[["玄成世业紫真官，文似相如貌胜潘。","崔峒 送韦八少府判官归东京"],["子云尝燕居，作赋似相如。","权德舆 户部王曹长杨考功崔刑部二院长并同钟陵使府之旧因以寄赠又陪郎署喜甚常僚因书所怀且叙所知"]]},{"n":"侍甘泉","d":"","s":"《汉书》卷八十七上〈扬雄列传上〉～3522～","w":"孝成帝时，客有荐雄文似相如者，上方郊祠甘泉泰畤、汾阴后土，以求继嗣，召雄待诏承明之庭。正月，从上甘泉，还奏甘泉赋以风。……甘泉本因秦离宫，既奢泰，而武帝复增通天、高光、迎风。宫外近则洪厓、旁皇、储胥、弩阹，远则石关、封峦、枝鹊、露寒、棠、…","q":[]},{"n":"数杯资好事","d":"","s":"《汉书》卷八十七下《扬雄传赞》","w":"「雄以病免，复召为大夫。家素贫，耆酒，人希至其门。时有好事者载酒肴从游学，而钜鹿侯芭常从雄居，受其《太玄》、《法言》焉。」","q":[["贫穷老瘦家卖屐，好事就之为携酒。","杜甫 可叹"],["数杯资好事，异味烦县尹。","杜甫 赠郑十八贲"]]},{"n":"河东赋","d":"","s":"《汉书》卷八十七上〈扬雄列传上〉～3535～","w":"其三月，将祭后土，上乃帅群臣横大河，凑汾阴。既祭，行游介山，回安邑，顾龙门，览盐池，登历观，陟西岳以望八荒，迹殷周之虚，眇然以思唐虞之风。雄以为临川羡鱼不如归而结罔，还，上〈河东赋〉以劝，","q":[["扬雄更有河东赋，唯待吹嘘送上天。","杜甫 赠献纳使起居田舍人"]]},{"n":"羊质","d":"","s":"《法言义疏》卷四〈吾子〉～7～","w":"或曰：「有人焉，自云姓孔，而字仲尼。入其门，升其堂，伏其几，袭其裳，则可谓仲尼乎？」曰：「其文是也，其质非也。」「敢问质。」曰：「羊质而虎皮，见草而说，见豺而战，忘其皮之虎矣。」","q":[["惊疑豹文鼠，贪窃虎皮羊。","李商隐 赠送前刘五经映三十四韵"]]},{"n":"华芝","d":"","s":"《昭明文选》卷七汉·扬子云（雄）《甘泉赋》","w":"「于是乘舆乃登夫凤皇兮翳华芝。」唐·李善注：「服虔曰：『华芝，华盖也。』善曰：『言以华盖自翳也。』」","q":[["杨家二世安九重，不御华芝嫌六龙。","温庭筠 春江花月夜词"]]},{"n":"怀铅","d":"怀铅：指采访、笔记型著述。唐元稹《献荥阳公诗五十韵》：“空虚惭炙輠，点窜许怀铅。”","s":"《西京杂记》","w":"扬子云好事，尝怀铅提椠，从诸计吏，访殊方绝俗四方之语，以为裨补《輶轩》所载，亦洪意也。","q":[["色向怀铅白，光因翰简融。","包融 和陈校书省中玩雪"],["解薜龙凤署，怀铅兰桂丛。","李群玉 始忝四座奏状闻荐蒙恩授官旋进歌诗延英宣赐言怀纪事呈同馆诸公二十四韵"]]},{"n":"荐雄","d":"","s":"《汉书》卷八十七上《扬雄传上》","w":"孝成帝时，客有荐雄文似相如者，上方郊祠甘泉泰畤、汾阴后土，以求继嗣，召雄待诏承明之庭。","q":[["谁能为扬雄，一荐甘泉赋。","孟浩然 田园作"],["谁人世上为金口，借取明时一荐雄。","杜牧 送刘秀才归江陵"]]},{"n":"扬子解嘲","d":"","s":"《汉书》卷八十七下〈扬雄列传下〉～3565～","w":"「哀帝时丁、傅、董贤用事，诸附离之者或起家至二千石。时雄方草《太玄》，有以自守，泊如也。或雄以玄尚白，而雄解之，号曰《解潮》。」唐·颜师古注：「玄，黑色也。言雄作之不成，其色犹白，故无禄位也。」","q":[["旁人错比扬雄宅，懒惰无心作解嘲。","杜甫 堂成"],["曾闻贾谊陈奇策，肯学扬雄赋解嘲。","牟融 题赵支"]]},{"n":"金马门","d":"","s":"《汉书》卷八十七下〈扬雄传下〉～3566～","w":"「历金门上玉堂有日矣，曾不能画一奇，出一策，上说人主，下谈公卿。」东汉·应劭注：「金门，金马门也。」","q":[["玉堂金马隔青云，墨客儒生皆白首。","钱起 送褚大落第东归"],["金门自有西来约，莫待萤光照竹扉。","刘沧 送友人下第东归"]]},{"n":"九州箴","d":"","s":"《古文苑》卷十四汉·扬雄《百官箴》","w":"《冀州箴》曰：「洋洋冀州……牧臣司冀。敢告在阶。」《兖州箴》曰：「悠悠济河。……牧臣司兖。敢告执书。」《交州箴》曰：「交州荒裔……牧臣司交。敢告执宪。」","q":[["长怀五羖赎，终著九州箴。","李商隐 自桂林奉使江陵途中感怀寄献尚书"]]},{"n":"客难扬雄拓落","d":"","s":"《昭明文选》卷四十五〈对问设论辞序上·设论·解嘲〉～2006～","w":"客嘲杨子曰：「吾闻上世之士，人纲人纪，不生则已，生必上尊人君，下荣父母，析人之圭，儋人之爵，怀人之符，分人之禄，纡青拖紫，朱丹其毂。今吾子幸得遭明盛之世，处不讳之朝，与群贤同行，历金门，上玉堂有日矣，曾不能画一奇，出一策，上说人主，下谈公卿…","q":[]},{"n":"立谈","d":"","s":"《昭明文选》卷四十五汉·扬子云（雄）《解嘲》","w":"「夫上世之士，或解缚而相，或释褐而傅；或倚夷门而笑，或横江潭而渔；或七十说而不遇，或立谈间而封侯。」唐·李善注：「《史记》曰：『虞卿说赵孝成王，再见，为赵上卿，故号为虞卿。』」","q":[["南伯从事贤，君行立谈际。","杜甫 送樊二十三侍御赴汉中判官"]]},{"n":"美新作","d":"","s":"《昭明文选》卷四十八〈符命·剧秦美新〉～249～","w":"臣诚乐昭著新德，光之罔极，往时司马相如作封禅一篇，以彰汉氏之休。臣常有颠眴病，恐一旦先犬马，填沟壑，所怀不章，长恨黄泉，敢竭肝胆，写腹心，作剧秦美新一篇，虽未究万分之一，亦臣之极思也。","q":[["一睹美新作，斯瑕安可除。","李群玉 感兴四首"]]},{"n":"绵竹颂","d":"","s":"《昭明文选》卷七汉·杨子云（雄）《甘泉赋》","w":"「孝成帝时，客有荐雄文似相如者。」唐·李周翰注：「尝作《绵竹颂》，成帝时直宿郎杨庄颂此文，帝曰：『此似相如之文。』庄曰：『非也，此臣邑人扬子云。』帝即召见，拜为黄门侍郎。」","q":[["几时绵竹颂，拟荐子虚名。","李商隐 令狐舍人说昨夜西掖玩月因戏赠"]]},{"n":"墨客","d":"","s":"《汉书》卷八十七下《扬雄传下》","w":"雄从至射熊馆，还，上长杨赋，聊因笔墨之成文章，故藉翰林以为主人，子墨为客卿以风。其辞曰：子墨客卿问于翰林主人曰：「……」言未卒，墨客降席再拜稽首","q":[["经论传缁侣，文章遍墨卿。","严维 哭灵一上人"],["多士尽儒冠，墨客蔼云屯。","杜甫 赠蜀闾丘师兄"]]},{"n":"青雀","d":"","s":"《方言·輶轩使者绝代语释别国方言第九》～59～","w":"舟，自关而西谓之船，自关而东或谓之舟，或谓之航。南楚江湘凡船大者谓之舸，小舸谓之艖，艖谓之艒，小艒●谓之艇，艇长而薄者谓之艜，短而深者谓之●，小而深者谓之●。东南丹阳会稽之间谓艖为欚。桴谓之●，●谓之筏。筏，秦晋之通语也。江淮家居●中谓之荐…","q":[["闲逐维私向武城，北风青雀片时行。","刘言史 送人随姊夫任云安令"]]},{"n":"邱陵","d":"","s":"汉·扬雄《法言·学行》","w":"百川学海而至于海；丘陵学山而不至于山。","q":[["海峤年年别，丘陵徒自伤。","李益 长社窦明府宅夜送王屋道士常究子"]]},{"n":"尚玄","d":"","s":"《汉书》卷八十七下《扬雄传下》","w":"「哀帝时丁、傅、董贤用事，诸附离之者或起家至二千石。时雄方草《太玄》，有以自守，泊如也。或嘲雄以玄尚白，而雄解之，号曰解嘲。」唐·颜师古注：「玄，黑色也。言雄作之不成，其色犹白，故无禄位也。」","q":[["从来扬子宅，别有尚玄人。","王勃 赠李十四四首"],["薄宦惭尸素，终身拟尚玄。","王维 游悟真寺"]]},{"n":"天禄阁","d":"","s":"《三辅黄图》卷六〈桥〉","w":"天禄阁，藏典籍之所。《汉宫殿疏》云：「天禄、麒麟阁，萧何造。以藏秘书，处贤才也。」","q":[["继酬天禄署，俱尉甸侯家。","柳宗元 同刘二十八院长述旧言怀感时书事奉寄沣州张员外使君五十二韵之作因其韵增至八十通赠二君子"],["位高天禄阁，词异畔牢愁。","武元衡 闻相公三兄小园置宴以元衡寓直因寄上兼呈中书三兄"]]},{"n":"子云阁","d":"扬雄投阁：喻无故受牵连而获罪，走投无路。宋陆游《丰年行》：“书生识字亦聊尔，莫作扬雄老投阁。”","s":"《汉书》卷八十七下〈扬雄列传下〉～3584～","w":"王莽时，刘歆、甄丰皆为上公，莽既以符命自立，即位之后欲绝其原以神前事，而丰子寻、歆子棻复献之。莽诛丰父子，投棻四裔，辞所连及，便收不请。时雄校书天禄阁上，治狱使者来，欲收雄，雄恐不能自免，乃从阁上自投下，几死。莽闻之曰：「雄素不与事，何故在…","q":[["东望安仁省，西临子云阁。","上官仪 酬薛舍人万年宫晚景寓直怀友"],["投阁嗤扬子，飞书代鲁连。","张继 酬李书记校书越城秋夜见赠"]]},{"n":"吞凤","d":"","s":"旧题晋·葛洪《西京杂记》卷二","w":"「扬雄读书，有人语之曰：『无为自苦，元故难传。』忽然不见。雄著《太玄经》。梦吐凤凰集《玄》之上，顷而灭。」","q":[["子云吞白凤，遂吐太玄书。","李群玉 感兴四首之一"],["积学萤尝聚，微词凤早吞。","杜牧 川守大夫刘公早岁寓居敦行里肆有题壁十韵今之置第乃获旧居洛下大僚因有唱和叹咏不足辄献此诗"]]},{"n":"笑扬雄","d":"","s":"《汉书》卷八十七上《扬雄传上》","w":"「扬雄字子云，蜀郡成都人也。」「雄少而好学，不为章句，训诂通而已，博览无所不见。为人简易佚荡，口吃不能剧谈，默而好深湛之思，清静亡为，少耆欲，不汲汲于富贵，不戚戚于贫贱，不修廉隅以徼名当世。」","q":[["扬雄闭门空读书，门前碧草春离离。","戴叔伦 行路难"],["谬惭知蓟子，真怯笑扬雄。","杜甫 奉寄河南韦尹丈人（原注。甫敝庐在偃师。承韦公频有访问。故有下句。韦即韦济。）"]]},{"n":"扬马","d":"","s":"《文心雕龙·丽辞》","w":"「自扬马张蔡，崇盛丽辞。」","q":[["文章似扬马，风骨又清羸。","李端 赠何兆"],["乾坤几反覆，扬马宣同时。","杜甫 苏大侍御访江浦赋八韵记异（草堂诗本无此题。竟以序为题。八题诗止七韵。疑有脱误。）"]]},{"n":"扬雄赋","d":"","s":"《汉书》卷八十七上〈扬雄列传上〉","w":"扬雄字子云，蜀郡成都人也。其先出自有周伯侨者，以支庶初食采于晋之扬，因氏焉，不知伯侨周何别也。扬在河、汾之间，周衰而扬氏或称侯，号曰扬侯。会晋六卿争权，韩、魏、赵兴而范中行、知伯弊。当是时，偪扬侯，扬侯逃于楚巫山，因家焉。楚汉之兴也，扬氏溯…","q":[["无人荐子云，太息竟谁辨。","储光羲 秋次霸亭寄申大"],["不轻文举少，深叹子云疲。","崔融 哭蒋詹事俨"]]},{"n":"扬子寂寥","d":"","s":"《汉书》卷八十七下《扬雄传下》","w":"「雄年四十馀，自蜀来至游京师，大司马车骑将军王音奇其文雅，召以为门下史，荐雄待诏，岁馀，奏羽猎赋，除为郎，给事黄门，与王莽、刘歆并。哀帝之初，又与董贤同官。当成、哀、平间，莽、贤皆为三公，权倾人主，所荐莫不拔擢，而雄三世不徙官。」","q":[["永怀芸阁友，寂寞滞扬云。","孟浩然 初出关旅亭夜坐怀王大校书"],["贾生流寓日，扬子寂寥时。","张九龄 酬王六寒朝见贻"]]},{"n":"扬雄宅","d":"","s":"《汉书》卷八十七上《扬雄传上》","w":"「扬季官至庐江太守，汉元鼎间避仇复江上，处岷山之阳曰郫，有田一，有宅一区，世世以农桑为业。自季至雄，五世而传一子，故雄亡它扬于蜀。雄少而好学，不为章句，训诂通而已，博览无所不见。为人简易佚荡，口吃不能剧谈，默而好深湛之思，清静亡为，少耆…","q":[["披襟扬子宅，舒啸仰重闱。","任希古（一作知古。一作奉古。） 和长孙秘监伏日苦热"],["子云应寂寞，公叔为吹嘘。","张九龄 初发道中赠王司马兼寄诸公"]]},{"n":"扬执戟","d":"","s":"《汉书》卷八十七下《扬雄传下》","w":"「雄年四十馀，自蜀来至游京师，大司马车骑将军王音奇其文雅，召以为门下史，荐雄待诏，岁馀，奏羽猎赋，除为郎，给事黄门，与王莽、刘歆并。」","q":[["声名恒压鲍参军，班位不过扬执戟。","李端 赠康洽"],["应笑白须扬执戟，可怜春日老如何。","杨巨源 上裴中丞"]]},{"n":"月窟","d":"","s":"《汉书》卷八十七下《扬雄传下》","w":"《长杨赋》：「西厌月窟，东震日域。」东汉·服虔注：「月窟，月所生也。」","q":[["月窟宾诸夏，云官降九天。","刘禹锡 送工部张侍郎入蕃吊祭"],["荷戈月窟外，擐甲昆崙东。","岑参 北庭贻宗学士道别"]]}],"7":[{"n":"阿瞒","d":"","s":"《全上古三代秦汉三国六朝文·全三国文》卷一〈曹操〉～055～","w":"帝姓曹讳操，一名吉利，小字阿瞒。沛国谯人，汉相国参之后。","q":[]},{"n":"饱各飞扬","d":"","s":"《后汉书》卷七十五〈刘焉袁术吕布列传·吕布〉～2449～","w":"陈圭欲使子登诣曹操，布固不许，会使至，拜布为左将军，布大喜，即听登行，并令奉章谢恩。登见曹操，因陈布勇而无谋，轻于去就，宜早图之。操曰：「布狼子野心，诚难久养，非卿莫究其情伪。」即增圭秩中二千石，拜登广陵太守。临别，操执登手曰：「东方之事，…","q":[]},{"n":"失匕箸","d":"","s":"《三国志》卷三十二〈蜀书·先主备传〉～875～","w":"先主未出时，献帝舅车骑将军董承辞受帝衣带中密诏，当诛曹公。先主未发。是时曹公从容谓先主曰：「今天下英雄，唯使君与操耳。本初之徒，不足数也。」先主方食，失匕箸。遂与承及长水校尉种辑、将军吴子兰、王子服等同谋。会见使，未发。事觉，承等皆伏诛。南…","q":[["四夷闻风失匕箸，天子受贺登高楼。","刘禹锡 平蔡州三首"],["杯酒英雄君与操，文章微婉我知丘。","白居易 哭刘尚书梦得二首"]]},{"n":"蔡琰","d":"","s":"《后汉书》卷八十四〈列女传·董祀妻〉～2800～","w":"陈留董祀妻者，同郡蔡邕之女也，名琰，字文姬。博学有才辩，又妙于音律。适河东卫仲道。夫亡无子，归宁于家。兴平中，天下丧乱，文姬为胡骑所获，没于南匈奴左贤王，在胡中十二年，生二子。曹操素与邕善，痛其无嗣，乃遣使者以金璧赎之，而重嫁于祀。","q":[["文姬留此曲，千载一知音。","刘长卿 鄂渚听杜别驾弹胡琴"],["二妃烟尘外，凄凉转战归。胡笳悲蔡琰，汉使泣明妃。","李敬方 太和公主还宫"]]},{"n":"蔡琰请曹公","d":"","s":"《后汉书》卷八十四《列女传·董祀妻传》","w":"陈留董祀妻者，同郡蔡邕之女也，名琰，字文姬。博学有才辩，又妙于音律。适河东卫仲道。夫亡无子，归宁于家。兴平中，天下丧乱，文姬为胡骑所获，没于南匈奴左贤王，在胡中十二年，生二子。曹操素与邕善，痛其无嗣，乃遣使者以金璧赎之，而重嫁于祀。祀为屯田…","q":[["多君同蔡琰，流泪请曹公。","李白 在浔阳非所寄内"]]},{"n":"苍舒","d":"","s":"《春秋左传·文公十八年》","w":"「昔高阳氏有才子八人：苍舒……天下之民谓之『八恺。』」","q":[["苍舒留帝宠，子晋有仙才。","王维 恭懿太子挽歌五首之四"]]},{"n":"绝妙辞","d":"色丝文：称赞文章文辞华美。唐赵嘏《题曹娥庙》：“文字在碑碑已堕，波涛辜负色丝文。”","s":"《世说新语笺疏》中卷下〈捷悟〉～580～","w":"魏武尝过曹娥碑下，杨脩从，碑背上见题作「黄绢幼妇，外孙齑臼」八字。魏武谓脩曰：「解不？」答曰：「解。」魏武曰：「卿未可言，待我思之。」行三十里，魏武乃曰：「吾已得。」令脩别记所知。脩曰：「黄绢，色丝也，于字为绝。幼妇，少女也，于字为妙。外孙…","q":[["碑缺曹娥宅，林荒逸少居。","刘长卿 无锡东郭送友人游越"],["越鸟闻花里，曹娥想镜中。","刘长卿 送崔处士先适越"]]},{"n":"曹苻气势","d":"","s":"《资治通鉴》卷六十五〈汉纪五十七·孝献皇帝庚·建安十三年〉～2088～","w":"曹操自江陵将顺江东下。诸葛亮谓刘备曰：「事急矣，请奉命求救于孙将军。」遂与鲁肃俱诣孙权。亮见权于柴桑，说权曰：「海内大乱，将军起兵江东，刘豫州收众汉南，与曹操共争天下。今操芟夷大难，略已平矣，遂破荆州，威震四海。英雄无用武之地，故豫州遁逃至…","q":[]},{"n":"曹公黄祖","d":"","s":"《三国志》卷十〈魏书·荀彧传〉～33～","w":"又《平原祢衡传》曰：「衡字正平，建安初，自荆州北游许都，恃才傲逸，臧否过差，见不如己者不与语，人皆以是憎之。唯少府孔融高贵其才，上书荐之曰：『淑质贞亮，英才卓荦。初涉艺文，升堂睹奥；目所一见，辄诵于口，耳所暂闻，不忘于心。性与道合，思若有神…","q":[]},{"n":"铜雀歌舞","d":"","s":"《三国志》卷一〈魏书·武帝纪〉～32～","w":"十五年春，下令曰：「自古受命及中兴之君，曷尝不得贤人君子与之共治天下者乎！及其得贤也，曾不出闾巷，岂幸相遇哉？上之人不求之耳。今天下尚未定，此特求贤之急时也。『孟公绰为赵、魏老则优，不可以为滕、薛大夫』。若必廉士而后可用，则齐桓其何以霸世！…","q":[]},{"n":"渔阳掺","d":"祢生刺：咏怀才不遇。唐司空曙《送卢堪》：“莫使称生刺，空留怀袖中。”；祢衡挝：用以咏鼓乐，或指相骂，或指文人狂放不羁。唐李商隐《病中闻河东公乐营置酒口占寄上》：“必投潘岳果，谁掺祢衡挝。”","s":"《世说新语笺疏》上卷上〈言语〉～64～","w":"祢衡被魏武谪为鼓吏，正月半试鼓。南朝梁·刘孝标注引引《文士传》曰：「融数与武帝笺，称其才，帝倾心欲见。衡称疾不肯往，而数有言论。帝甚忿之，以其才名不杀，图欲辱之，乃令录为鼓吏。后至八月朝会，大阅试鼓节，作三重阁，列坐宾客。以帛绢制衣，作一岑…","q":[["莫使祢生刺，空留怀袖中。","司空曙 送卢堪"],["祢生投刺游，王粲吟诗谒。","孟郊 答韩愈李观别因献张徐州"]]},{"n":"愈头风","d":"陈琳檄：咏军府中有才能的文人。唐李白《江夏寄汉阳辅录事》：“君草陈琳檄，我书鲁连箭。”","s":"《三国志》卷二十一《魏书·王粲传》附《陈琳传》","w":"琳避难冀州，袁绍使典文章。袁氏败，琳归太祖。太祖谓曰：「卿昔为本初移书，但可罪状孤而已，恶恶止其身，何乃上及父祖邪？」琳谢罪，太祖爱其才而不咎。瑀少受学于蔡邕。建安中都护曹洪欲使掌书记，瑀终不为屈。太祖并以琳、瑀为司空军谋祭酒，管记室，军国…","q":[["孔璋旧檄家家有，叔度新歌处处听。","刘禹锡 令狐相公自天平移镇太原以诗申贺相公昔为并州从事"],["孔璋才素健，早晚檄书成。","刘长卿 行营酬吕侍御时尚书问罪襄阳军次汉东境上侍御以州邻寇贼复有水火迫于征税诗以见谕"]]},{"n":"周瑜破曹","d":"","s":"《三国志》卷四十七〈吴书·吴主权〉～7～","w":"「备进住夏口，使诸葛亮诣权，权遣周瑜、程普等行。是时曹公新得表众，形势甚盛，诸议者皆望风畏惧，多劝权迎之。惟瑜、肃执拒之议，意与权同。瑜、普为左右督，各领万人，与备俱进，遇于赤壁，大破曹公军。公烧其馀船引退，士卒饥疫，死者大半。」","q":[["赤壁争雄如梦里，且须歌舞宽离忧。","李白 江夏赠韦南陵冰"],["烈火张天照云海，周瑜于此破曹公。","李白 赤壁歌送别"]]},{"n":"赤壁楼船","d":"","s":"《三国志》卷四十七〈吴书·吴主权传〉～7～","w":"三年春，权复征黄祖，祖先遣舟兵拒军，都尉吕蒙破其前锋，而淩统、董袭等尽锐攻之，遂屠其城。祖挺身亡走，骑士冯则追枭其首，虏其男女数万口。是岁，使贺齐讨黟、歙，黟音伊。歙音摄。分歙为始新、新定、犁阳、休阳县，以六县为新都郡。荆州牧刘表死，鲁肃乞…","q":[]},{"n":"吊魏武","d":"","s":"《昭明文选》卷六十晋·陆士衡（机）《吊魏武帝文·序》","w":"「观其所以顾命冢嗣，贻谋四子，经国之略既远，隆家之训亦弘。又云：『吾在军中，持法是也。至小忿怒，大过失……。』善乎达人之谠言矣！声类曰：『谠，善言也。』持姬女而指季豹以示四子曰：『以累汝！』因泣下。伤哉！曩以天下自任，今以爱子托人。伤哉！曩…","q":[["请君骑马望西陵，为我殷勤吊魏武","李颀 送刘方平"]]},{"n":"盘中钓","d":"","s":"《后汉书》卷八十二下《方术传·左慈传》","w":"左慈字元放，庐江人也。少有神道。尝在司空曹操坐，操从容顾众宾曰：「今日高会，珍羞略备，所少吴松江鲈鱼耳。」放于下坐应曰：「此可得也。」因求铜盘贮水，以竹竿饵钓于盘中，须臾引一鲈鱼出。操大拊掌笑，会者皆惊。操曰：「一鱼不周坐席，可更得乎？」放…","q":[["玉管时来凤，铜盘即钓鱼。","王维 赠东岳焦炼师"],["卖鲊市中何许人，钓鱼坐上谁家子。","韩翃 赠别华阴道士"]]},{"n":"对酒当歌","d":"","s":"《昭明文选》卷二十七〈诗戊·乐府上·乐府二首〉～28～","w":"〈短歌行〉：「对酒当歌，人生几何！譬如朝露，去日苦多。慨当以慷，忧思难忘。何以解忧，唯有杜康。青青子衿，悠悠我心。但为君故，沈吟至今。呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙。明明如月，何时可掇？忧从中来，不可断绝。越陌度阡，枉用相存。契阔谈…","q":[["寂寞青陵台上月，秋风满树鹊南飞。","储嗣宗 宋州月夜感怀"],["中秋朗月静天河，乌鹊南飞客恨多。","刘沧 八月十五日夜玩月"]]},{"n":"分香","d":"","s":"《昭明文选》卷六十〈行状吊文祭文·吊文·吊曹操文〉～2594～","w":"而见魏武帝〈遗令〉，忾然叹息，伤怀者久之。……又曰：「吾婕妤妓人，皆著铜爵台。……」又云：「馀香可分与诸夫人。诸舍中无所为，学作履组卖也。」","q":[["平阳拊背穿驰道，铜雀分香下璧门。","杜牧 出宫人二首"],["咸池升日庆，铜雀分香悲。","杜牧 杜秋娘诗"]]},{"n":"鸡肋弃","d":"","s":"《三国志》卷一〈魏书·武帝纪〉～52～","w":"二十四年春正月，仁屠宛，斩音。夏侯渊与刘备战于阳平，为备所杀。三月，王自长安出斜谷，军遮要以临汉中，遂至阳平。备因险拒守。南朝宋·裴松之注引《九州春秋》曰：时王欲还，出令曰「鸡肋」，官属不知所谓。主簿杨脩便自严装，人惊问脩：「何以知之？」脩…","q":[["鸡肋曹公忿，猪肝仲叔惭。","罗隐 寄洪正师"]]},{"n":"卖履分香","d":"","s":"《昭明文选》卷六十〈行状吊文祭文·吊文·吊曹操文〉～2594～","w":"元康八年，机始以台郎出补著作，游乎秘阁，而见魏武帝遗令，忾然叹息，伤怀者久之。……又云：「馀香可分与诸夫人。诸舍中无所为，学作履组卖也。吾历官所得绶，皆著藏中。吾馀衣裘，可别为一藏。不能者兄弟可共分之。」唐·李善注：「舍中，谓众妾。众妾既无…","q":[]},{"n":"公安问曹瞒","d":"","s":"《三国志》卷三十二〈蜀书·先主备传〉～878～","w":"先主遣诸葛亮自结于孙权，权遣周瑜、程普等水军数万，与先主并力，与曹公战于赤壁，大破之，焚其舟船。先主与吴军水陆并进，追到南郡，时又疾疫，北军多死，曹公引归。先主表琦为荆州刺史，又南征四郡。武陵太守金旋、长沙太守韩玄、桂阳太守赵范、零陵太守刘…","q":[]},{"n":"横槊赋诗","d":"","s":"《旧唐书》卷一百九十下〈文苑列传下·杜甫〉～5055～","w":"建安之后，天下之士遭罹兵战，曹氏父子鞍马间为文，往往横槊赋诗，故其遒壮抑扬、冤哀悲离之作，尤极于古。","q":[]},{"n":"黄龙见谯","d":"","s":"《三国志》卷二《魏书·文帝纪》","w":"初，汉熹平五年，黄龙见谯，光禄大夫桥玄问太史令单飏：「此何祥也？」飏曰：「其国后当有王者兴，不及五十年，亦当复见。天事恒象，此其应也。」内黄殷登默而记之。至四十五年，登尚在。三月，黄龙见谯，登闻之曰：「单飏之言，其验兹乎！」","q":[["飞燕潜来赵，黄龙岂见谯。","唐彦谦 咸通中始闻褚河南归葬"]]},{"n":"火烧赤壁","d":"","s":"《三国志》卷五十四〈吴书·周瑜传〉～262～","w":"时刘备为曹公所破，欲引南渡江，与鲁肃遇于当阳，遂共图计，因进住夏口，遣诸葛亮诣权，权遂遣瑜及程普等与备并力逆曹公，遇于赤壁。时曹公军众已有疾病，初一交战，公军败退，引次江北。瑜等在南岸。瑜部将黄盖曰：「今寇众我寡，难与持久。然观操军船舰首尾…","q":[]},{"n":"渴望梅","d":"渴望梅：喻指以空想安慰自己。唐罗隐《丁亥岁作》：“病想医门渴望梅，十年心地反成灰。”","s":"《世说新语笺疏》下卷下〈假谲〉～85～","w":"魏武行役，失汲道，军皆渴，乃令曰：「前有大梅林，饶子，甘酸，可以解渴。」士卒闻之，口皆出水，乘此得及前源。","q":[["少留攀桂树，长渴望梅林。","崔备 清溪路中寄诸公"],["思君览章句，还复如望梅。","李山甫 山中依韵答刘书记见赠"]]},{"n":"生子当如孙仲谋","d":"","s":"《三国志》卷四十七〈吴书·吴主权传〉～8～","w":"十八年正月，曹公攻濡须，权与相拒月馀。曹公望权军，叹其齐肃，乃退。初，曹公恐江滨郡县为权所略，徵令内移。民转相惊，自庐江、九江、蕲春、广陵户十馀万皆东渡江，江西遂虚，合肥以南惟有皖城。南朝宋·裴松之注引《吴历》曰：「曹公出濡须，作油船，夜渡…","q":[]},{"n":"九牧争羡","d":"","s":"《昭明文选》卷四十一〈书上·论盛孝章书〉～873～","w":"岁月不居，时节如流。五十之年，忽焉已至，公为始满，融又过二。海内知识，零落殆尽，惟有会稽盛孝章尚存。其人困于孙氏，妻孥湮没，单孑独立，孤危愁苦。若使忧能伤人，此子不得永年矣！春秋传曰：「诸侯有相灭亡者，桓公不能救，则桓公耻之。」今孝章实丈夫…","q":[]},{"n":"老骥伏枥","d":"","s":"《宋书》卷二十一《乐志三》","w":"魏武帝《步出夏门行·龟虽寿》「骥老伏枥，志在千里。烈士暮年，壮心不已。」","q":[["朔风悲老骥，秋霜动鸷禽。","刘禹锡 学阮公体三首"],["老马思故枥，穷鳞忆深流。","戴叔伦 从军行"]]},{"n":"龙泉","d":"","s":"《昭明文选》卷四十二、三国魏·曹子健（植）《与杨德祖书》","w":"盖有南威之容，乃可以论于淑媛；有龙渊之利，乃可以议于割断。","q":[["金羁络骏马，锦带横龙泉。","李白 留别广陵诸公（一作留别邯郸故人）"],["薛公龙泉姿，其气在斗牛。","李群玉 将之京国赠薛员外"]]},{"n":"千里驹","d":"","s":"《楚辞补注》卷六〈卜居〉～76～","w":"屈原既放三年，不得复见，竭智尽忠，蔽鄣于谗。心烦意乱，不知所从乃往见太卜郑詹尹，曰：「余有所疑，愿因先生决之。」詹尹乃端策拂龟，曰：「君将何以教之？」屈原曰：吾宁悃悃款款，朴以忠乎？将送往劳来，斯无穷乎？宁诛锄草茅，以力耕乎？将游大人，以成…","q":[]},{"n":"七香车","d":"","s":"《全上古三代秦汉三国六朝文·全三国文》卷三〈曹操·与太尉杨彪书〉～070～","w":"操白：与足下同海内大义，足下不遗，以贤子见辅。比中国虽靖，方外未夷，今军征事大，百姓骚扰，吾制钟鼓之音。主簿宜守。而足下贤子，恃豪父之势，每不与吾同怀，即欲直绳，顾颇恨恨。谓其能改，遂转宽舒，复即宥贷，将延足下尊门大累，便令刑之。念卿父息之…","q":[]},{"n":"蛇乘雾","d":"","s":"《宋书》卷二十一《乐志三》","w":"魏武帝《步出夏门行·神归虽寿》：神龟虽寿，犹有竟时。腾蛇乘雾，终为土灰。","q":[["丹成作蛇乘白雾，千年重化玉井土。","李贺 拂舞歌辞"]]},{"n":"死绥","d":"","s":"《三国志》卷一《魏书·武帝纪》","w":"建安八年「己酉，令曰：『《司马法》』『将军死绥。』」南朝宋·裴松之注引王沉《魏书》：「绥，却也。有前一尺，无却一寸。」","q":[["死绥却是古来有，骁将自惊今日无。","杜牧 闻庆州赵纵使君与党项战中箭身死辄书长句"]]},{"n":"孙策","d":"","s":"《三国志》卷四十六《吴书·孙破虏讨逆传》","w":"「策为人，美姿颜，好笑语，性阔达听受，善于用人，是以士民见者，莫不尽心，乐为致死。刘繇弃军遁逃，诸郡守皆捐城郭奔走。吴人严白虎等众各万馀人，处处屯聚。吴景等欲先击破虎等，乃至会稽。策曰：『虎等群盗，非有大志，此成禽耳。』遂引兵渡浙江，据会稽…","q":[["十万梅鋗空寸土，三分孙策竟荒丘。","罗隐 吴门晚泊寄句曲道友"]]},{"n":"西陵望","d":"","s":"《昭明文选》卷六十晋·陆士衡（机）《吊魏武帝文序》","w":"见魏武帝《遗令》，忾然叹息，伤怀者久之。……又曰：「吾婕妤妓人，皆著铜爵台。于台堂上施八尺床，繐帐，朝晡上脯糒之属。月朝十五，辄向帐作妓。汝等时时登铜爵台，望吾西陵墓田。」","q":[["恭闻天子孝，不忍望铜台。","武元衡 顺宗至德大圣皇帝挽歌"],["魏武铜雀妓，日与欢乐并，一旦西陵望，欲歌先涕零。","白居易 和答诗十首（并序）之和思归乐"]]},{"n":"魏征西","d":"","s":"《三国志》卷一《魏书·武帝纪》","w":"「冬，作铜雀台。」南朝宋·裴松之注：《魏武故事》载公十二月己亥令曰：「孤始举孝廉，年少，自以本非岩穴知名之士，恐为海内人之所见凡愚，欲为一郡守，好作政教，以建立名誉，使世士明知之；故在济南，始除残去秽，平心选举，违迕诸常侍。以为彊豪所忿，恐…","q":[["青春带文绶，去事魏征西。","韩翃 送戴迪赴凤翔幕府"]]},{"n":"乌巢空幕","d":"","s":"《三国志》卷一〈魏书·武帝纪〉～2～","w":"袁绍运谷车数千乘至，公用荀攸计，遣徐晃、史涣邀击，大破之，尽烧其车。公与绍相拒连月，虽比战斩将，然众少粮尽，士卒疲乏。公谓运者曰：「却十五日为汝破绍，不复劳汝矣。」冬十月，绍遣车运谷，使淳于琼等五人将兵万馀人送之，宿绍营北四十里。绍谋臣许攸…","q":[]},{"n":"五色棒","d":"","s":"《三国志》卷一〈魏书·武帝操〉～2～","w":"「太祖少机警，有权数，而任侠放荡，不治行业，故世人未之奇也；惟梁国桥玄、南阳何颙异焉。玄谓太祖曰：『天下将乱，非命世之才不能济也，能安之者，其在君乎！』年二十，举孝廉为郎，除洛阳北部尉，迁顿丘令，徵拜议郎。」南朝梁·刘孝标注引《曹瞒传》曰：…","q":[["苍黄五色棒，掩遏一阳生。","李商隐 有感二首"],["立政思悬棒，谋身类触藩。","韦应物 示从子河南尉班"]]},{"n":"一曹三马","d":"","s":"《晋书》卷一〈高祖宣帝纪〉～20～","w":"帝内忌而外宽，猜忌多权变。魏武察帝有雄豪志，闻有狼顾相，欲验之。乃召使前行，令反顾，面正向后而身不动。又尝梦三马同食一槽，甚恶焉。因谓太子丕曰：「司马懿非人臣也，必预汝家事。」太子素与帝善，每相全佑，故免。帝于是勤于吏职，夜以忘寝，至于刍牧…","q":[]},{"n":"只鸡斗酒吊新邱","d":"","s":"《后汉书》卷五十一〈李陈庞陈桥列传·桥玄〉～697～","w":"初，曹操微时，人莫知者，尝往候玄，玄见而异焉，谓曰：「今天下将乱，安生民，者其在君乎！」操常感其知己。及后经过玄墓，辄悽怆致祭。自为其文曰：「故太尉桥公，懿德高轨，汎爱博容。国念明训，士思令谟。幽灵潜翳，邈哉缅矣！操以幼年，逮升堂室，特以顽…","q":[]}],"8":[{"n":"安兄杀嵇","d":"","s":"《三国志》卷二十一《魏书·王粲传》附《嵇康传》","w":"「至景元中，坐事诛。」南朝宋·裴松之注引《魏氏春秋》：「康与东平吕昭子巽及巽弟安亲善。会巽淫安妻徐氏，而诬安不孝，囚之。安引康为證，康义不负心，保明其事，安亦至烈，有济世志力。钟会劝大将军因此除之，遂杀安及康。」","q":[["吕安兄不道，都市杀嵇康。","白居易 杂感"]]},{"n":"锻铁","d":"","s":"《世说新语笺疏》下卷上〈简傲〉～767～","w":"钟士季精有才理，先不识嵇康。钟要于时贤俊之士，俱往寻康。康方大树下锻，向子期为佐鼓排。康扬槌不辍，傍若无人，移时不交一言。钟起去，康曰：「何所闻而来？何所见而去？」钟曰：「闻所闻而来，见所见而去。」南朝梁·刘孝标注引《文士传》曰：「康性绝巧…","q":[["中散山阳锻，愚公野谷村。","杜甫 赠比部萧郎中十兄"],["才淑随厮养，名贤隐锻炉。","杜甫 过南岳入洞庭湖"]]},{"n":"玉山颓","d":"","s":"《世说新语笺疏》下卷上〈容止〉～609～","w":"嵇康身长七尺八寸，风姿特秀。……见者叹曰：「萧萧肃肃，爽朗清举。」或云：「肃肃如松下风，高而徐引。」山公曰：「嵇叔夜之为人也，岩岩若孤松之独立；其醉也，傀俄若玉山之将崩。」","q":[["静怀琼树倚，醉忆玉山颓。","令孤楚 省中直夜对雪寄李师素侍郎"],["三月唯残一日春，玉山倾倒白鸥驯。","令狐楚 三月晦日会李员外座中频以老大不醉见讥因有此赠"]]},{"n":"题凡鸟","d":"凡鸟：喻庸才。唐张九龄《杂诗》之二：“凡鸟已相噪，凤凰安得知。”","s":"《世说新语笺疏》下卷上〈简傲〉～769～","w":"嵇康与吕安善，每一相思，千里命驾。安后来，值康不在，喜出户延之，不入。题门上作「凤」字而去。喜不觉，犹以为欣，故作。「凤」字，凡鸟也。","q":[["凡鸟已相噪，凤皇安得知。","张九龄 杂诗五首"],["谒客唯题凤，偷儿欲觇毡。","李端 晚春过夏侯校书值其沉醉戏赠"]]},{"n":"山阳笛","d":"山阳笛：喻悼念、怀念故友。唐司空曙《残老百哗歌同王员外耿拾遗吉中罕李端游慈思各赋一物》：“金谷筝中传不似，山阳笛里写难成。”","s":"《昭明文选》卷十六、三国魏·向子期（秀）《思旧赋·序》","w":"向秀字子期，河内怀人也。清悟有远识，少为山涛所知，雅好老庄之学。庄周著内外数十篇，历世才士虽有观者，莫适论其旨统也，秀乃为之隐解，发明奇趣，振起玄风，读之者超然心悟，莫不自足一时也。惠帝之世，郭象又述而广之，儒墨之见鄙，道家之言遂盛焉。始…","q":[["旧时闻笛泪，今夜重沾衣。","司空曙 冬夜耿拾遗王秀才就宿因伤故人"],["金谷筝中传不似，山阳笛里写难成。","司空曙 残莺百啭歌同王员外耿拾遗吉中孚李端游慈恩各赋一物"]]},{"n":"赋幽愤","d":"","s":"《晋书》卷四十九〈嵇康列传〉～372～","w":"性绝巧而好锻。宅中有一柳树甚茂，乃激水圜之，每夏月，居其下以锻。东平吕安服康高致，每一相思，辄千里命驾，康友而善之。后安为兄所枉诉，以事系狱，辞相證引，遂复收康。康性慎言行，一旦缧绁，乃作〈幽愤诗〉。","q":[]},{"n":"广陵散","d":"广陵散：喻哀悼怀才去世者。唐李白《忆崔郎中宗之游南阳遗吾孔子琴抚之潸然感旧》：“谁传广陵散，但哭邙山骨。”又喻指高雅乐曲。唐陈存《楚州赠别周愿侍御》：“淮南木叶飞，夜间广陵散。”","s":"《世说新语笺疏》中卷上〈雅量〉～344～","w":"嵇中散临刑东市，神气不变。索琴弹之，奏广陵散。曲终曰：「袁孝尼尝请学此散，吾靳固不与，广陵散于今绝矣！」太学生三千人上书，请以为师，不许。文王亦寻悔焉。","q":[["独悲形解后，谁听广陵弦。","李德裕 房公旧竹亭闻琴缅慕风流神期如在因重题此作"],["谁传广陵散，但哭邙山骨。","李白 忆崔郎中宗之游南阳遗吾孔子琴抚之潸然感旧"]]},{"n":"嵇叔夜","d":"","s":"《晋书》卷四十九《嵇康传》","w":"嵇康字叔夜，谯国铚人也。其先姓奚，会稽上虞人，以避怨，徙焉。铚有嵇山，家于其侧，因而命氏。兄喜，有当世才，历太仆、宗正。康早孤，有奇才，远迈不群。身长七尺八寸，美词气，有风仪，而土木形骸，不自藻饰，人以为龙章凤姿，天质自然。恬静寡欲，含垢匿…","q":[["携琴侍叔夜，负局访安期。","上官婉儿 游长宁公主流杯池"],["琴待嵇中散，杯思阮步兵。","元稹 病减逢春期白二十二辛大不至十韵"]]},{"n":"千里驾","d":"寻嵇：喻对朋友的思念。唐李白《酬坊州工司马与间正字对雪见赠》“访戴昔未偶，寻嵇此相得。”","s":"《世说新语笺疏》下卷上〈简傲〉～769～","w":"嵇康与吕安善，每一相思，千里命驾。","q":[["今朝忽枉嵇生驾，倒屣开门遥解颜。","崔兴宗 酬王维卢象见过林亭"],["同人千里驾，邻国五马车。","房琯 题汉州西湖"]]},{"n":"嵇康寡识","d":"","s":"《三国志》卷二十一《魏书·王粲传》附《嵇康传》","w":"「时又有谯郡嵇康，文辞壮丽，好言老、庄，而尚奇任侠。至景元中，坐事诛。」南朝宋·裴松之注引《魏氏春秋》：「初，康采药于汲郡共北山中，见隐者孙登。康欲与之言，登默然不对。踰时将去，康曰：『先生竟无言乎？』登乃曰：『子才多识寡，难乎免于今之世。…","q":[["嵇康殊寡识，张翰独知终。","王昌龄 赵十四兄见访"]]},{"n":"嵇康闲","d":"","s":"《晋书》卷四十九《嵇康传》","w":"古人有言，善莫近名。奉时恭默，咎悔不生。万石周慎，安亲保荣。世务纷纭，祇搅余情，安乐必诫，乃终利贞。煌煌灵芝，一年三秀；予独何为，有志不就。惩难思复，心焉内疚，庶勖将来，无馨无臭。采薇山阿，散发岩岫，永啸长吟，颐神养寿。","q":[["古有焕辉句，嵇康闲婆娑。请君吟啸之，正气庶不讹。","孟郊 访疾"]]},{"n":"山嵇","d":"","s":"《晋书》卷四十三〈山涛列传〉～223～","w":"山涛字巨源，河内怀人也。父曜，宛句令。涛早孤，居贫，少有器量，介然不群。性好庄老，每隐身自晦。与嵇康、吕安善，后遇阮籍，便为竹林之交，著忘言之契。康后坐事，临诛，谓子绍曰：「巨源在，汝不孤矣。」","q":[["范云堪晚友，嵇绍自不孤。","杜甫 别张十三建封"],["张老存家事，嵇康有故人。","杜甫 奉赠萧二十使君"]]},{"n":"嵇刘","d":"","s":"《晋书》卷四十九《嵇康传》","w":"所与神交者惟陈留阮籍、河内山涛，豫其流者河内向秀、沛国刘伶、籍兄子咸、琅邪王戎，遂为竹林之游，世所谓「竹林七贤」也。","q":[["酣酣天地宽，恍恍嵇刘伍。","杜牧 雨中作"]]},{"n":"嵇阮","d":"","s":"《昭明文选》卷四十三、三国魏·嵇叔夜（康）《与山巨源绝交书》","w":"阮嗣宗口不论人过，吾每师之，而未能及。至性过人，与物无伤，唯饮酒过差耳。至为礼法之士所绳，疾之如雠，幸赖大将军保持之耳。吾不如嗣宗之贤，而有慢弛之阙；又不识人情，闇于机宜；无万石之慎，而有好尽之累。久与事接，疵衅日兴，虽欲无患，其可得乎？","q":[["竹林一自王戎去，嵇阮虽贫兴未衰。","刘禹锡 和陈许王尚书酬白少傅侍郎长句因通简汝洛旧游之什"],["绛霄轻霭翊三台，稽阮襟怀管乐才。","李郢 奉陪裴相公重阳日游安乐池亭"]]},{"n":"嵇氏幼男","d":"","s":"《昭明文选》卷四十三、三国魏·嵇叔夜（康）《与山巨源绝交书》","w":"吾新失母兄之欢，意常悽切，女年十三，男年八岁，未及成人，况复多病，顾此悢悢，如何可言！","q":[["嵇氏幼男犹可悯，左家娇女岂能忘。","李商隐 王十二兄与畏之员外相访见招小饮时予以悼亡日近不去因寄"]]},{"n":"嵇向","d":"","s":"《晋书》卷四十九《向秀传》","w":"康善锻，秀为之佐，相对欣然，傍若无人。又共吕安灌园于山阳。康既被诛，秀应本郡计入洛。文帝问曰：「闻有箕山之志，何以在此？」秀曰：「以为巢许狷介之士，未达尧心，岂足多慕。」帝甚悦。秀乃自此役，作《思旧赋》云：余与嵇康、吕安居止接近，其人并有不…","q":[["嵇向林庐接，携手行将归。","钱起 客舍赠郑贲"]]},{"n":"嵇延祖","d":"","s":"《晋书》卷八十九《忠义传·嵇绍传》","w":"嵇绍字延祖，魏中散大夫康之子也。十岁而孤，事母孝谨。以父得罪，靖居私门。山涛领选，启武帝曰：「康诰有言：『父子罪不相及。』嵇绍贤侔郤缺，宜加旌命，请为秘书郎。」帝谓涛曰：「如卿所言，乃堪为丞，何但郎也。」乃发诏徵之，起家为秘书丞。","q":[["人间只有嵇延祖，最望山公启事来。","李商隐 赠宇文中丞"],["山公访嵇绍，赵武见韩侯。","李端 送诸暨裴少府"]]},{"n":"竹林七贤","d":"七贤：喻指文人放荡不羁，或指独立于世俗之外，或喻朋友的交情深厚。唐卢纶《秋夜同畅当宿潭上西亭》：“圆月出山头，七贤林下游。”","s":"《三国志》卷二十一〈魏书·王粲传·嵇康〉～605～","w":"时又有谯郡嵇康，文辞壮丽，好言老、庄，而尚奇任侠。至景元中，坐事诛。南朝宋·裴松之注引《魏氏春秋》曰：「康寓居河内之山阳县，与之游者，未尝见其喜愠之色。与陈留阮籍、河内山涛、河南向秀、籍兄子咸、琅邪王戎、沛人刘伶相与友善，游于竹林，号为七贤…","q":[["东篱摘芳菊，想见竹林游。","储光羲 仲夏饯魏四河北觐叔"],["超超青云器，婉婉竹林会。","储光羲 奉和韦判官献侍郎叔除河东采访使"]]},{"n":"绝交书","d":"","s":"《世说新语笺疏》下卷上〈栖逸〉～652～","w":"山公将去选曹，欲举嵇康；康与书告绝。南朝梁·刘孝标注引《嵇康别传》曰：「山巨源为吏部郎，迁散骑常侍，举康，康辞之，并与山绝。岂不识山之不以一官遇己情邪？亦欲标不屈之节，以杜举者之口耳！乃荅涛书，自说不堪流俗，而非薄汤武。大将军闻而恶之。」","q":[["况观绝交书，兼睹箴隐文。","吴筠 舟中遇柳伯存归潜山因有此赠"],["知道故人相忆否，嵇康不得懒修书。","徐铉 寄江都路员外"]]},{"n":"愧孙登","d":"","s":"《世说新语》下卷上《栖逸》","w":"「嵇康游于汲郡山中，遇道士孙登，遂与之游。康临去，登曰：『君才则高矣，保身之道不足。』」南朝梁·刘孝标注引《文士传》曰：「嘉平中，汲县民共入山中，见一人，所居悬岩百仞，丛林郁茂，而神明甚察。自云『孙姓，登名，字公和』。康闻，乃从游三年。问其…","q":[["淮王门有客，终不愧孙登。","杜甫 赠特进汝阳王二十韵"]]},{"n":"吏部访孤儿","d":"","s":"《世说新语》上卷下《政事》","w":"「嵇康被诛后，山公举康子为秘书丞。」","q":[["独闻山吏部，流涕访孤儿。","刘长卿 哭张员外继（公及夫人相次没于洪州）"]]},{"n":"龙性讵能驯","d":"","s":"《昭明文选》卷二十一南朝宋·颜延年（延之）《五君咏五首·嵇中散》","w":"「鸾翮有时铩，龙性谁能驯。」唐·李善注引《嵇康别传》曰：「康美音气，好容色，龙章凤姿，天质自然。」","q":[["凤歌空有问，龙性讵能驯。","陈子昂 酬李参军崇嗣旅馆见赠"]]},{"n":"论懒","d":"","s":"《昭明文选》卷四十三、三国魏·嵇叔夜（康）《与山巨源绝交书》","w":"「少加孤露，母兄见骄，不涉经学。性复疏懒，筋驽肉缓，头面常一月十五日不洗，不大闷痒，不能沐也。每常小便，而忍不起，令胞中略转乃起耳。」","q":[["何处同嵇懒，吾徒道异诸。","齐己 拟嵇康绝交寄湘中贯微康"],["莫学嵇康懒，且安原宪贫。","王维 山中示弟"]]},{"n":"目送飞鸿","d":"","s":"《昭明文选》卷二十四〈诗丙·赠答二·赠秀才入军五首〉","w":"息徒兰圃，秣马华山。流磻平皋，垂纶长川。目送归鸿，手挥五弦。俯仰自得，游心泰玄。嘉彼钓叟，得鱼忘筌。郢人逝矣，谁与尽言？","q":[["身骑天马多意气，目送飞鸿对豪贵。","任华 寄李白"],["鸿飞灭处犹目送，蝶舞闲时梦忽成。","权德舆 奉和礼部尚书酬杨著作竹亭歌"]]},{"n":"攀嵇","d":"","s":"《昭明文选》卷二十一南朝宋·颜延年（延之）《五君咏五首·向常侍》","w":"「交吕既鸿轩，攀嵇亦凤举。」唐·李善注：「《向秀别传》曰：秀常与嵇康偶锻于洛邑。」","q":[["正遂攀稽愿，翻追访戴欢。","吴融 和诸学士秋夕禁直偶雪"],["沿牒相逢楚水湄，竹林文酒此攀嵇。","胡宿 赵宗道归辇下"]]},{"n":"七不堪","d":"","s":"《昭明文选》卷四十三〈书下·与山巨源绝交书〉～923～","w":"又人伦有礼，朝廷有法，自惟至熟，有必不堪者七，甚不可者二：卧喜晚起，而当关呼之不置，一不堪也。抱琴行吟，弋钓草野，而吏卒守之，不得妄动，二不堪也。危坐一时，痹不得摇，性复多虱，把搔无已，而当裹以章服，揖拜上官，三不堪也。素不便书，又不喜作书…","q":[]},{"n":"起晚","d":"","s":"《昭明文选》卷四十三〈书下·与山巨源绝交书〉～923～","w":"有必不堪者七，甚不可者二：卧喜晚起，而当关呼之不置，一不堪也。","q":[["起晚堪从事，行迟更学仙。","杜甫 览镜呈柏中丞"]]},{"n":"中散琴","d":"","s":"《三国志》卷二十一〈魏书·王粲传·嵇康〉～606～","w":"南朝宋·裴松之注引《魏氏春秋》：康临刑自若，援琴而鼓，既而叹曰：「雅音于是绝矣！」","q":[["将军塞外多奇操，中散林间有正声。","司马逸客 雅琴篇"],["叔夜弹琴歌白雪，孙登长啸韵清风。","张昌宗 奉和圣制夏日游石淙山"]]},{"n":"三秀悲中散","d":"","s":"《昭明文选》卷二十三〈诗丙·哀伤·幽愤诗〉～084～","w":"煌煌灵芝，一年三秀；予独何为，有志不就。唐·李善注：「《楚辞》曰：『采三秀于山间。』王逸曰：『三秀，谓芝草也。』」","q":[["三秀悲中散，二毛伤虎贲。","刘禹锡 武陵书怀五十韵"]]},{"n":"山阳酒侣","d":"","s":"《水经注疏》卷九〈清水〉～805～","w":"又径七贤祠东，左右筠篁列植，冬夏不变贞萋。魏步兵校尉陈留阮籍、中散大夫谯国嵇康、晋司徒河内山涛、司徒琅琊王戎、黄门郎河内向秀、建威参军沛国刘伶、始平太守阮咸等，同居山阳，结自得之游，时人号之为竹林七贤。向子期所谓山阳旧居也。后人立庙于其处，…","q":[]},{"n":"叔夜刚肠","d":"","s":"《晋书》卷四十九〈嵇康列传〉～369～","w":"嵇康字叔夜，谯国铚人也。其先姓奚，会稽上虞人，以避怨，徙焉。铚有嵇山，家于其侧，因而命氏。兄喜，有当世才，历太仆、宗正。康早孤，有奇才，远迈不群。身长七尺八寸，美词气，有风仪，而土木形骸，不自藻饰，人以为龙章凤姿，天质自然。恬静寡欲，含垢匿…","q":[]},{"n":"土木形骸","d":"","s":"《世说新语》下卷上《容止》","w":"「刘伶身长六尺，貌甚丑悴，而悠悠忽忽，土木形骸。……嵇康身长七尺八寸，风姿特秀。」南朝梁·刘孝标注引《嵇康别传》：「康长七尺八寸，伟容色，土木形骸，不加饰厉，而龙章凤姿，天质自然。」","q":[["形骸元土木，舟楫复江湖。","杜甫 舟出江陵南浦奉寄郑少尹"]]},{"n":"养生遭杀","d":"","s":"《晋书》卷四十九〈嵇康列传〉～369～","w":"以为神仙禀之自然，非积学所得，至于导养得理，则安期、彭祖之伦可及，乃著养生论……初，康居贫，尝与向秀共锻于大树之下，以自赡给。颍川钟会，贵公子也，精练有才辩，故往造焉。康不为之礼，而锻不辍。良久会去，康谓曰：「何所闻而来？何所见而去？」会曰…","q":[["何必走马来为问，君不见嵇康养生遭杀戮。","杜甫 醉为马坠诸公携酒相看"]]},{"n":"玉架书隐","d":"","s":"晋·葛洪《神仙传》卷六《王烈》","w":"王烈，字长休，邯郸人也。烈入河东抱犊山中，得一石室，室中有两卷素书，烈读不知其字，不敢取，颇谙十数字形体，归书作以示嵇叔夜。叔夜尽知其字，烈喜，乃将叔夜往识其经，分明了了，往至失石室所在，烈窃语弟子曰，叔夜不应得道故也。","q":[["玉架残书隐，金坛旧迹迷。","王勃 观内怀仙"]]},{"n":"中散论","d":"","s":"《晋书》卷四十九《嵇康传》","w":"以为神仙禀之自然，非积学所得，至于导养得理，则安期、彭祖之伦可及，乃著《养生论》。","q":[["卧看中散论，愁忆太常斋。","高适 酬裴员外以诗代书"]]},{"n":"中散虱爬","d":"","s":"《昭明文选》卷四十三、三国魏·嵇叔夜（康）《与山巨源绝交书》","w":"又人伦有礼，朝廷有法，自惟至熟，有必不堪者七，甚不可者二：卧喜晚起，而当关呼之不置，一不堪也。抱琴行吟，弋钓草野，而吏卒守之，不得妄动，二不堪也。危坐一时，痹不得摇，性复多虱把搔无已，而当裹以章服，揖拜上官，三不堪也。","q":[["东门牛屡饭，中散虱空爬。","柳宗元 同刘二十八院长述旧言怀感时书事奉寄澧州张员外使君五十二韵之作因其韵增至八十通赠二君子"]]},{"n":"中散诗","d":"","s":"《诗品》卷中","w":"晋中散嵇康诗，颇似魏文，过为峻切，讦直露才，伤渊雅之致。然托谕清远，良有鉴裁，亦未失高流矣。","q":[["中散诗传画，将军扇续书。","司空曙 送曹同椅"]]}],"9":[{"n":"温泉浴罢","d":"","s":"《太平广记》卷四百八十六〈杂传记三·长恨传〉～3998～","w":"唐开元中，泰阶平，四海无事。玄宗在位岁久，倦于旰食宵衣，政无大小，始委于丞相。稍深居游宴，以声色自娱。先是，元献皇后武淑妃皆有宠，相次即世；宫中虽良家子千万数，无悦目者。上心忽忽不乐。时每岁十月，驾幸华清宫，内外命妇，焜耀景从，浴日馀波，赐…","q":[]},{"n":"梨花雨","d":"","s":"《全唐诗》卷四百三十五〈长恨歌〉","w":"汉皇重色思倾国，御宇多年求不得。杨家有女初长成，养在深闺人未识。天生丽质难自弃，一朝选在君王侧。回眸一笑百媚生，六宫粉黛无颜色。春寒赐浴华青池，温泉水滑洗凝脂。侍儿扶起娇无力，始是新承恩泽时。云鬓花颜金步摇【云鬓花冠金步摇】，芙蓉帐暖度春宵…","q":[]},{"n":"海棠春睡","d":"","s":"《海录碎事》卷十〈后妃门〉","w":"《太真外传》：「上皇登沉香亭，诏太真妃子。妃子时卯醉未醒，命力士从侍儿扶掖而至。妃子醉颜残妆，鬓乱钗横，不能再拜。上皇笑曰：『岂是妃子醉，真海棠睡未足耳。』」","q":[]},{"n":"尺箠平虏","d":"","s":"《旧唐书》卷一百四〈封常清列传〉～3209～","w":"十四载，入朝，十一月，谒玄宗于华清宫。时禄山已叛，玄宗言凶胡负恩之状，何方诛讨？常清奏曰：「禄山领凶徒十万，径犯中原，太平斯久，人不知战。然事有逆顺，势有奇变，臣请走马赴东京，开府库，募骁勇，挑马箠渡河，计日取逆胡之首悬于阙下。」玄宗方忧，…","q":[]},{"n":"名覆金瓯","d":"","s":"《新唐书》卷一百九〈崔义玄列传·（孙）崔琳〉～4098～","w":"其群从数十人，自兴宁里谒大明宫，冠盖驺哄相望。每岁时宴于家，以一榻置笏，犹重积其上。琳与弟太子詹事圭、光禄卿瑶俱列棨戟，世号「三戟崔家」。开元、天宝间，中外宗属无缌麻丧。初，玄宗每命相，皆先书其名，一日书琳等名，覆以金瓯，会太子入，帝谓曰：…","q":[]},{"n":"宫女说玄宗","d":"","s":"《全唐诗》卷四百十〈行宫〉","w":"寥落古行宫，宫花寂寞红。白头宫女在，閒坐说玄宗。","q":[]},{"n":"倚新妆","d":"","s":"《太平广记》卷二百四〈乐二·歌·李龟年〉～549～","w":"开元中，禁中初重木芍药，即今牡丹也。（开元《天宝花木记》云，禁中呼木芍药为牡丹）得四本，红、紫、浅红、通白者。上因移植于兴庆池东沉香亭前。会花方繁开，上乘照夜白，太真妃以步辇从。诏特选梨园弟子中尤者，得乐十六部。李龟年以歌擅一时之名，手捧檀…","q":[]},{"n":"荔枝无驿使","d":"","s":"《全唐诗》卷五百二十一〈过华清宫绝句三首〉","w":"〈过华清宫绝句三首〉其一：「长安回望绣成堆，山顶千门次第开。一骑红尘妃子笑，无人知是荔枝来【无人知道荔枝来】。」","q":[]},{"n":"太液池","d":"解语花：喻美人聪慧可人。清赵翼《题女史骆佩香秋灯课女图》：“一个娇娃解语花，崎窗亲课秋宵读。”","s":"《开元天宝遗事》卷下〈解语花〉","w":"明皇秋八月，太液池，有千叶白莲，数枝盛开。帝与贵戚宴赏，左右皆叹美久之。帝指贵妃示左右曰，争如我解语花。","q":[]},{"n":"华清赐浴","d":"","s":"《太平广记》卷四百八十六〈杂传记三·长恨传〉～3998～","w":"唐开元中，泰阶平，四海无事。玄宗在位岁久，倦于旰食宵衣，政无大小，始委于丞相。稍深居游宴，以声色自娱。先是，元献皇后武淑妃皆有宠，相次即世；宫中虽良家子千万数，无悦目者。上心忽忽不乐。时每岁十月，驾幸华清宫，内外命妇，焜耀景从，浴日馀波，赐…","q":[["春寒赐浴华清池，温泉水滑洗凝脂。","白居易 长恨歌"]]},{"n":"华清石莲","d":"","s":"《明皇杂录》卷下〈唐玄宗华清宫汤池之豪奢〉～28～","w":"玄宗幸华清宫，新广汤池，制作宏丽。安禄山于范阳以白玉石为鱼龙凫雁，仍为石梁及石莲花以献，雕镌巧妙，殆非人工。上大悦，命陈于汤中，又以石梁横?汤上，而莲花才出于水际。上因幸华清宫，至其所，解衣将入，而鱼龙凫雁皆若奋鳞举翼，状欲飞动。上甚恐，遽…","q":[]},{"n":"环儿","d":"","s":"《杨太真外传》","w":"杨贵妃小字玉环，弘农华阴人也。……二十八年十月，玄宗幸温泉宫，使高力士取杨氏女于寿邸，度为女道士，号太真，住内太真宫。天宝四载七月，册左卫中郎将韦昭训女配寿邸。是月，于凤凰园册太真宫女道士杨氏为贵妃，半后服用。进见之日，奏《霓裳羽衣曲》。","q":[]},{"n":"鬟剪","d":"","s":"《旧唐书》卷五十一〈后妃列传上·玄宗杨贵妃〉～280～","w":"天宝九载，贵妃复忤旨，送归外第。时吉温与中贵人善，温入奏曰：「妇人智识不远，有忤圣情，然贵妃久承恩顾，何惜宫中一席之地，使其就戮，安忍取辱于外哉！」上即令中使张韬光赐御馔，妃附韬光泣奏曰：「妾忤圣颜，罪当万死。衣服之外，皆圣恩所赐，无可遗留…","q":[]},{"n":"宁王玉笛","d":"","s":"《新唐书》卷二十二〈礼乐志十二〉～476～","w":"帝又好羯鼓，而宁王善吹横笛，达官大臣慕之，皆喜言音律。帝常称：「羯鼓，八音之领袖，诸乐不可方也。」盖本戎羯之乐，其音太蔟一均，龟兹、高昌、疏勒、天竺部皆用之，其声焦杀，特异众乐。","q":[]},{"n":"九龄疏谏","d":"","s":"《旧唐书》卷九十九〈张九龄列传〉～3099～","w":"时范阳节度使张守圭以裨将安禄山讨奚、契丹败衄，执送京师，请行朝典。九龄奏劾曰：「穰苴出军，必诛庄贾；孙武教战，亦斩宫嫔。守圭军令必行，禄山不宜免死。」上特舍之。九龄奏曰：「禄山狼子野心，面有逆相，臣请因罪戮之，冀绝后患。」上曰：「卿勿以王…","q":[]},{"n":"哭香囊","d":"","s":"《新唐书》卷七十六〈后妃列传上·杨贵妃〉～3495～","w":"帝至自蜀，道过其所，使祭之，且诏改葬。礼部侍郎李揆曰：「龙武将士以国忠负上速乱，为天下杀之。今葬妃，恐反仄自疑。」帝乃止。密遣中使者具棺椁它葬焉。启瘗，故香囊犹在，中人以献，帝视之，悽感流涕，命工貌妃于别殿，朝夕往，必为鲠欷。","q":[]},{"n":"梅妃","d":"","s":"《五朝小说大观·唐人百家·偏录家·第三十六帙》","w":"唐·曹邺《梅妃传》：「梅妃姓江氏，莆田人……名曰釆蘋。开元中。高力土使粤，妃笄矣，见其少廲，选归侍明皇。大见宠幸。……妃善属文，自比谢女，淡妆雅服，而姿态明秀，笔不可描画。性喜梅，所居门槛悉植数株，上榜曰『梅亭』。梅开赋赏，至夜分尚留恋花下…","q":[]},{"n":"明皇倚太真","d":"","s":"《开元天宝遗事》卷下〈天宝下·醒酒花〉","w":"明皇与贵妃幸华清宫，因宿酒初醒，凭妃子肩同看木芍药。上亲折一枝，与妃子?嗅其艳，帝曰：不惟萱草忘忧，此花香艳，尤能醒酒。","q":[]},{"n":"太真肥","d":"","s":"《杨太真外传》","w":"上在百花院便殿，因览《汉成帝内传》，时妃子后至，以手整上衣领，曰：「看何文书？」上笑曰：「莫问。知则又人。」觅去，乃是「汉成帝获飞燕，身轻欲不胜风。恐其飘翥，帝为造水晶盘，令宫人掌之而歌舞。又制七宝避风台，间以诸香，安于上，恐其四肢不禁」也…","q":[]},{"n":"霓裳曲","d":"","s":"《龙城录·明皇梦游广寒宫》","w":"开元六年，上皇与申天师道士鸿都客，八月望日夜，因天师作术，三人同在云上游月中，过一大门在玉光中飞浮，宫殿往来无定，寒气逼人，露濡衣袖皆湿，顷见一大宫府，榜曰「广寒清虚之府」，其守门兵卫甚严，白刃粲然，望之如凝雪。时三人皆止其下不得入，天师引…","q":[]},{"n":"盘中舞","d":"","s":"《杨太真外传》","w":"上在百花院便殿，因览《汉成帝内传》，时妃子后至，以手整上衣领，曰：「看何文书？」上笑曰：「莫问。知则又人。」觅去，乃是「汉成帝获飞燕，身轻欲不胜风。恐其飘翥，帝为造水晶盘，令宫人掌之而歌舞。又制七宝避风台，间以诸香，安于上，恐其四肢不禁」也…","q":[]},{"n":"三郎","d":"","s":"《大唐新语》卷九〈谀佞〉～44～","w":"太平公主沈断有谋，则天爱其类已。诛二张，灭韦氏，咸赖其力焉。睿宗朝，军国大事皆令宰相就宅咨决，然后以闻。睿宗与群臣呼公主为太平，玄宗为三郎。凡所奏请，必问曰：「与三郎商量未？」其见重如此。","q":[["三郎紫笛弄烟月，怨如别鹤呼羁雌。","郑嵎 津阳门诗"]]},{"n":"太平天子","d":"","s":"《明皇杂录》卷上〈玉龙子〉～7～","w":"唐天后尝召诸皇孙坐于殿上，观其嬉戏，取竺西国所贡玉环钏杯盘列于前后，纵令争取，以观其志。莫不奔竞，厚有所获，独玄宗端坐，略不为动。后大奇之，抚其背曰：「此儿当为太平天子。」遂命取玉龙子以赐。玉龙子，太宗于晋阳宫得之，文德皇后常置之衣箱中，及…","q":[]},{"n":"太真姊妹","d":"","s":"《旧唐书》卷五十一〈后妃列传上·玄宗杨贵妃〉～278～","w":"玄宗杨贵妃，高祖令本，金州刺史。父玄琰，蜀州司户。妃早孤，养于叔父河南府士曹玄。开元初，武惠妃特承宠遇，故王皇后废黜。二十四年惠妃薨，帝悼惜久之，后庭数千，无可意者。或奏玄琰女姿色冠代，宜蒙召见。时妃衣道士服，号曰太真。既进见，玄宗大悦。…","q":[]},{"n":"汤饼客","d":"","s":"《新唐书》卷七十六〈后妃列传上·玄宗王皇后〉～3490～","w":"玄宗皇后王氏，同州下邽人。……始，后以爱弛，不自安。承间泣曰：「陛下独不念阿忠脱紫半臂易斗面，为生日汤饼邪？」帝悯然动容。阿忠，后呼其父仁皎云。","q":[["引箸举汤饼，祝词天麒麟。","刘禹锡 送张盥赴举诗"]]},{"n":"唐明皇游广寒","d":"","s":"《龙城录·明皇梦游广寒宫》","w":"开元六年，上皇与申天师道士鸿都客，八月望日夜，因天师作术，三人同在云上游月中，过一大门在玉光中飞浮，宫殿往来无定，寒气逼人，露濡衣袖皆湿，顷见一大宫府，榜曰「广寒清虚之府」，其守门兵卫甚严，白刃粲然，望之如凝雪。时三人皆止其下不得入，天师引…","q":[]},{"n":"五花结队","d":"","s":"《旧唐书》卷五十一〈后妃列传上·玄宗杨贵妃〉～279～","w":"玄宗每年十月幸华清宫，国忠姊妹五家扈从，每家为一队，著一色衣，五家合队，照映如百花之焕发，而遗钿坠，瑟瑟珠翠，璨芳馥于路。","q":[]},{"n":"舞马","d":"","s":"《明皇杂录》补遗〈唐玄宗舞马〉～4～","w":"玄宗尝命?舞马四蹄各为左右，分为部目，为某家宠、某家骄。时塞外亦有善马来贡者，上俾之?习，无不曲尽其妙。因命衣以文绣，络以金银，饰其鬃鬣，间杂珠玉。其曲谓之《倾杯乐》者数十回，奋首鼓尾，纵横应节。……或命壮士举一榻，马舞于榻上。……每千秋节…","q":[]},{"n":"舞破霓裳","d":"","s":"《全唐诗》卷五百二十一〈过华清宫绝句三首〉","w":"〈过华清宫绝句三首〉其二：「新丰绿树起黄埃，数骑渔阳探使回【案：帝使中使辅璆琳探禄山反否。璆琳受禄山金。言禄山不反。】。霓裳一曲千峰上，舞破中原始下来。」","q":[]},{"n":"仙李盘根","d":"","s":"《杜诗详注》卷二","w":"《神仙传》：「老子生而能言，指李树曰：以此为我姓。」《老子内传》：「太上老君，姓李名耳，字伯阳，其母见日精下落如流星，飞入口中，因有娠。七十二岁，于陈涡水李树下，剖左掖而生。」《述异记》：「中山有缥李大如拳者，呼为仙李。」又云：「濑乡老子祠…","q":[["仙李盘根大，猗兰奕叶光。","杜甫 冬日洛城北谒玄元皇帝庙"]]},{"n":"仙人仙仗","d":"","s":"《太平广记》卷二十二〈神仙二十二·罗公远〉～47～","w":"开元中，中秋望夜，时玄宗于宫中玩月。公远奏曰：「陛下莫要至月中看否。」乃取拄杖，向空掷之，化为大桥，其色如银，请玄宗同登。约行数十里，精光夺目，寒色侵人，遂至大城阙。公远曰：「此月宫也。」","q":[]},{"n":"杨妃捧砚","d":"","s":"《摭遗》","w":"李白失意游华山，过县，宰方开门决事，白乘醉跨驴过门，宰怒，不知太白也。引至庭下曰：「汝何人？辄敢无礼！」白乞供状，状无姓名，曰：「曾龙巾拭吐，御手调羹，贵妃授砚，力士抹靴，天子门前尚容走马，华阳县里，不得我骑驴？」宰惊起，揖曰：「不知翰林至…","q":[]},{"n":"夜霖铃","d":"","s":"《杨太真外传》卷下","w":"上发马嵬……又至斜谷口，属霖雨涉旬，于栈道雨中闻铃声，隔山相应。上既悼念贵妃，因采其声为〈雨霖铃曲〉，以寄恨焉。","q":[]},{"n":"永新娇小","d":"","s":"《乐府杂录》","w":"开元中，内人有许和子者，本吉州永新县乐家女也，开元末选入宫，即以永新名之，籍于宜春院。善歌，能变新声。遇高秋朗月，台殿清虚，喉啭一声，响传九陌。","q":[]},{"n":"雨霖铃","d":"","s":"《太平御览》卷五百六十八〈乐部六·宴乐〉～2698～","w":"《乐府杂录》：「雨淋铃者，因唐明皇驾回至骆谷，闻雨淋銮铃，因令张野狐撰为曲名。」又曰：「还京乐者，唐明皇自蜀返正乐官，张野狐撰此曲。」","q":[]},{"n":"张徽一曲","d":"","s":"《明皇杂录》补遗〈雨霖铃曲〉～46～","w":"明皇既幸蜀，西南行初入斜谷，属霖雨涉旬，于栈道雨中闻铃，音与山相应。上既悼念贵妃，采其声为雨霖铃曲，以寄恨焉。时梨园子弟善吹觱篥者，张野狐为第一，此人从至蜀，上因以其曲授野狐。洎至德中，车驾复幸华清宫，从官嫔御多非旧人。上于望京楼下命野狐奏…","q":[]}],"10":[{"n":"拜尘","d":"望尘拜：喻馅媚权贵。清赵翼《有以疏慢见责者书以志愧》：“望尘未惯车前拜，樗散孤踪敢不恬。”","s":"《晋书》卷五十五〈潘岳列传〉～504～","w":"岳性轻躁，趋世利，与石崇等谄事贾谧，每候其出，与崇辄望尘而拜。","q":[["魏勃扫门，潘岳望尘。","李瀚 蒙求"]]},{"n":"潘鬓","d":"潘鬓：喻指年岁磋跎。唐元稹《酬翰林白学士代书一百韵》：“宁牛终夜永，潘鬓去年衰。”","s":"《春秋左传正义》卷十五〈僖公·传二十二年〉～248～","w":"楚人未既济。司马曰。彼众我寡。及其未既济也。请击之。公曰。不可。既济而未成列。又以告。公曰。未可。既陈而后击之。宋师败绩。公伤股。门官歼焉。国人皆咎公。公曰。君子不重伤。不禽二毛。古之为军也。不以阻隘也。寡人虽亡国之馀。不鼓不成列。子鱼曰。…","q":[["莫叹巴三峡，休惊鬓二毛。","元稹 送东川马逢侍御使回十韵"],["三秀悲中散，二毛伤虎贲。","刘禹锡 武陵书怀五十韵"]]},{"n":"安仁悼亡","d":"","s":"《昭明文选》卷二十三晋·潘安仁（岳）《悼亡诗三首》其一","w":"之子归穷泉，重壤永幽隔。私怀谁克从，淹留亦何益？……如彼翰林鸟，双栖一朝只。如彼游川鱼，比目中路析。……寝息何时忘，沈忧日盈积。","q":[["唯应月照簟，潘岳此时哀。","张九龄 故荥阳君苏氏挽歌词三首之三"],["悼伤潘岳重，树立马迁轻。","李商隐 五言述德抒情诗一首四十韵献上杜七兄仆射相公"]]},{"n":"潘骑省","d":"","s":"《昭明文选》卷十三晋·潘安仁（岳）《秋兴赋·序》","w":"晋十有四年，余春秋三十有二，始见二毛。以太尉掾兼虎贲中郎将，寓直于散骑之省。高阁连云，阳景罕曜，珥蝉冕而袭纨绮之士，此焉游处。","q":[["东望安仁省，西临子云阁。","上官仪 酬薛舍人万年宫晚景寓值怀友"],["伤秋非骑省，玄发白成斑。","司空曙 九日洛东亭"]]},{"n":"潘生拙","d":"","s":"《昭明文选》卷十六晋·潘安仁（岳）《闲居赋·序》","w":"自弱冠涉乎知命之年，八徙官而一进阶，再免，一除名，一不拜职，迁者三而已矣。虽通塞有遇，抑亦拙者之效也。昔通人和长舆之论余也，固谓拙于用多。称多则吾岂敢，言拙信而有徵。方今俊乂在官，百工惟时，拙者可以绝意乎宠荣之事矣。","q":[["既负潘生拙，俄从周任言。","张九龄 酬王履震游园林见贻"],["官序潘生拙，才名贾傅多。","杜甫 秋日寄题郑监湖上亭三首之二"]]},{"n":"白首同归","d":"","s":"《世说新语笺疏》下卷下〈仇隙〉～924～","w":"孙秀既恨石崇不与绿珠，又憾潘岳昔遇之不以礼。后秀为中书令，岳省内见之，因唤曰：「孙令，忆畴昔周旋不？」秀曰：「中心藏之，何日忘之？」岳于是始知必不免。后收石崇、欧阳坚石，同日收岳。石先送市，亦不相知。潘后至，石谓潘曰：「安仁，卿亦复尔邪？」…","q":[["当君白首同归日，是我青山独往时。","白居易 九年十一月二十一日感事而作（其日独游香山寺）"]]},{"n":"潘舆","d":"","s":"《昭明文选》卷十六〈赋辛·志下·闲居赋〉～705～","w":"太夫人乃御版舆，升轻轩，远览王畿，近周家园。体以行和，药以劳宣。常膳载加，旧痾有痊。唐·李善注：「版舆，车名。傅畅《晋诸公赞》曰：『傅祗以足疾，版舆上殿。版舆，一名步舆。』周迁《舆服杂事记》曰：『步舆方四尺，素木为之，以皮为襻，之，自天子…","q":[["鹊随金印喜，乌傍板舆飞。","岑参 奉送李宾客荆南迎亲"],["荣禄上及亲，之官随板舆。","岑参 酬成少尹骆谷行见呈"]]},{"n":"怀橘","d":"陆绩橘：咏孝顺。唐张祜《送卢弘本浙东觐省》：“怀中陆绩橘，江上伍员涛。”","s":"《三国志》卷五十七〈吴书·陆绩传〉～328～","w":"陆绩字公纪，吴郡吴人也。父康，汉末为庐江太守。绩年六岁，于九江见袁术。术出橘，绩怀三枚，去，拜辞堕地，术谓曰：「陆郎作宾客而怀橘乎？」绩跪答曰：「欲归遗母。」术大奇之。","q":[["献亲冬集书，比橘复何如。","姚合 送雍陶及第归觐"],["孝廉因岁贡，怀橘向秦川。","孟浩然 送张参明经举兼向泾州觐省"]]},{"n":"璧连","d":"","s":"《世说新语》下卷上《容止》","w":"潘安仁、夏侯湛并有美容，喜同行，时人谓之「连璧」。","q":[["慕友惭连璧，言姻喜附葭。","柳宗元 同刘二十八院长述旧言怀感时书事奉寄澧州张员外使君五十二韵之作因其韵增至八十通赠二君子"],["连璧本难双，分符刺小邦。","柳宗元 答刘连州邦字"]]},{"n":"潘安仁","d":"潘郎车：喻女子爱慕美男子。南朝梁徐陵《洛阳道二首》之一：“潘郎车欲满，无奈掷花何。”","s":"《世说新语笺疏》下卷上〈容止〉～60～","w":"潘岳妙有姿容，好神情。少时挟弹出洛阳道，妇人遇者，莫不连手共萦之。左太冲绝丑，亦复效岳游遨，于是群妪齐共乱唾之，委顿而返。南朝梁·刘孝标注引《语林》曰：「安仁至美，每行，老妪以果掷之，满车。张孟阳至丑，每行，小儿以瓦石投之，亦满车。」二说不…","q":[["杨生词赋比潘郎，不似前贤貌不扬。","刘商 赋得射雉歌送杨协律表弟赴婚期"],["廷尉张罗自不关，潘郎挟弹无情损。","刘禹锡 百舌吟"]]},{"n":"河阳花","d":"河阳一县花：用作咏花之词，或喻地方之美或地方官善于治理。唐李商隐《县中恼饮席》：“若无江氏五色笔，争奈河阳一县花。”","s":"《白氏六帖》卷二十一","w":"潘岳为河阳令，种桃李花，人号曰：河阳一县花。","q":[["花县到时铜墨贵，叶舟行处水云和。","刘三复 送黄明府晔赴岳州湘阴任"],["花县到时铜墨贵，叶舟行处水云和。","刘复 送黄晔明府岳州湘阴赴任"]]},{"n":"怀县作","d":"","s":"《昭明文选》卷二十六晋·潘安仁（岳）《在怀县作二首》","w":"南陆迎脩景，朱明送末垂。初伏启新节，隆暑方赫羲。朝想庆云兴，夕迟白日移。挥汗辞中宇，登城临清池。","q":[["辞后读君怀县作，定知三岁字犹新。","独孤 酬常郿县见赠"]]},{"n":"刘郎潘郎","d":"","s":"《太平广记》卷六十一〈女仙六·天台二女〉～383～","w":"刘晨、阮肇，入天台采药，远不得返，经十三日饥。遥望山上有桃树子熟，遂跻险援葛至其下，?数枚，饥止体充。欲下山，以杯取水，见芜菁叶流下，甚鲜妍。复有一杯流下，有胡麻饭焉。乃相谓曰：「此近人矣。」遂渡山。出一大溪，溪边有二女子，色甚美，见二人持…","q":[]},{"n":"潘陆","d":"","s":"《全上古三代秦汉三国六朝文·全梁文》卷五十五〈钟嵘·诗品上〉","w":"晋黄门郎潘岳诗，其源出于仲宣。翰林叹其翩翩然如翔禽之有羽毛，衣服之有绡縠，犹浅于陆机。谢混云：「潘诗烂若舒锦，无处不佳。陆文如披沙简金，往往见宝。」嵘谓益寿轻华，故以潘胜。翰林笃论，故叹陆为深。余常言陆才如海，潘才如江。","q":[["潘陆应同调，孙吴亦异时。","杜甫 暮春江陵送马大卿公恩命追赴阙下"],["双溪逢陆海，荆渚遇平津。","贯休 赠抱麻刘舍人"]]},{"n":"论巧拙","d":"","s":"《昭明文选》卷十六晋·潘安仁（岳）《闲居赋·序》","w":"「岳读汲黯传至司马安四至九卿，而良史书之，题以巧宦之目，未曾不慨然废书而叹也。曰：『嗟乎！巧诚有之，拙亦宜然。』」","q":[["休指宦游论巧拙，只将愚直祷神祇。","杜牧 题桐叶"]]},{"n":"美貌说潘安","d":"","s":"《世说新语笺疏》下卷上〈容止〉～60～","w":"潘岳妙有姿容，好神情。少时挟弹出洛阳道，妇人遇者，莫不连手共萦之。左太冲绝丑，亦复效岳游遨，于是群妪齐共乱唾之，委顿而返。南朝梁·刘孝标注引《岳别传》曰：「岳姿容甚美，风仪閒畅。」","q":[]},{"n":"鸣玉","d":"","s":"《昭明文选》卷十〈赋戊·纪行下·西征赋〉～","w":"飞翠緌，拖鸣玉，以出入禁门者众矣。唐·李善注引《礼记注疏》曰：「君子行则鸣佩玉。」","q":[["杖藜雪后临丹壑，鸣玉朝来散紫宸。","杜甫 冬至"]]},{"n":"潘赋登山","d":"","s":"《昭明文选》卷十三晋·潘安仁（岳）《秋兴赋》","w":"夫送归怀慕徒之恋兮，远行有羁旅之愤。临川感流以叹逝兮，登山怀远而悼近。彼四戚之疚心兮，遭一涂而难忍。嗟秋日之可哀兮，谅无愁而不尽。野有归燕，隰有翔隼。游氛朝兴，槁叶夕殒。","q":[["潘赋登山魂易断，楚歌遗佩怨何穷。","王初 书秋"]]},{"n":"潘怀县","d":"","s":"《昭明文选》卷十六晋·潘安仁（岳）《闲居赋》","w":"逮事世祖武皇帝，为河阳怀令，尚书郎，廷尉平。","q":[["潘令新诗忽寄来，分明绣段对花开。","施肩吾 酬张明府"],["今日潘怀县，同时陆浚仪。","杜甫 九日杨奉先会白水崔明府"]]},{"n":"潘锦","d":"","s":"《世说新语》上卷下《文学》","w":"孙兴公云：「潘文烂若披锦，无处不善；陆文若排沙简金，往往见宝。」","q":[["忽枉情人吐芳讯，临风不羡潘锦舒。","王起 和李校书自秘省见访知早入朝便入集贤不遇诗"]]},{"n":"閒居赋","d":"","s":"《晋书》卷五十五《潘岳传》","w":"岳性轻躁，趋世利，与石崇等谄事贾谧，每候其出，与崇辄望尘而拜。构悯怀之文，岳之辞也。谧二十四友，岳为其首。谧晋书限断，亦岳之辞也。其母数诮之曰：「尔当知足，而乾没不已乎？」而岳终不能改。既仕宦不达，乃作闲居赋。","q":[["潘岳闲居赋，钟期流水琴。","储光羲 同张侍御鼎和京兆萧兵曹华岁晚南园"],["潘岳闲居日，王戎戏陌辰。","李峤 李秀才近自涂口迁居新安适枉缄书见宽悲戚因以此答"]]},{"n":"潘诔","d":"","s":"《晋书》卷五十五《潘岳传》","w":"岳美姿仪，辞藻绝丽，尤善为哀诔之文。","q":[["只有安仁能作诔，何曾宋玉解招魂。","李商隐 哭刘蕡"]]},{"n":"西征想潘","d":"","s":"《晋书》卷五十五《潘岳传》","w":"潘岳自太傅主簿除名，「选为长安令，作西征赋，述所经人物山水，文清旨诣。」","q":[["北上频伤阮，西征未学潘。","郑愔 贬降至汝州广成驿"],["登高北望嗤梁叟，凭轼西征想潘掾。","骆宾王 畴昔篇"]]},{"n":"潘杨","d":"","s":"《昭明文选》卷五十六晋·潘安仁（岳）《杨仲武诔》","w":"杨绥，字仲武，荥阳宛陵人也。……既藉三叶世亲之恩，而子之姑，余之伉俪焉。往岁卒于德宫里。丧服同次，绸缪累月，苟人必有心，此亦款诚之至也。不幸短命，春秋二十九，元康九年夏五月己亥卒。呜呼哀哉！乃作诔曰：……潘杨之穆，有自来矣。矧乃今日，慎终如…","q":[["为结潘杨好，言过鄢郢城。","孟浩然 送桓子之郢成礼"],["通家殊孔李，旧好即潘杨。","柳宗元 弘农公以硕德伟材屈于诬枉左官三岁复为大僚天监昭明人心感悦宗元窜伏湘浦拜贺末由谨献诗五十韵以毕微志"]]},{"n":"潘鱼","d":"","s":"《昭明文选》卷二十三晋·潘安仁（岳）《悼亡诗三首》其一","w":"流芳未及歇，遗挂犹在壁。怅恍如或存，周遑忡惊惕。如彼翰林鸟，双栖一朝只。如彼游川鱼，比目中路析。","q":[["潘鱼从此隔，陈凤宛然飞。","沈佺期 天官崔侍郎夫人卢氏挽歌"]]},{"n":"潘园","d":"","s":"《昭明文选》卷十六晋·潘安仁（岳）《闲居赋》","w":"爰定我居，筑室穿池。长杨映沼，芳枳树篱。游鳞瀺灂，菡萏敷披。竹木蓊蔼，灵果参差。……太夫人乃御版舆，升轻轩，远览王畿，近周家园。","q":[["遥想潘园里，琴尊兴转清。","李群玉 湖阁晓晴寄呈从翁二首之二"],["莱子昼归今始好，潘园景色夏偏浓。","钱起 送冷朝阳擢第后归金陵觐省"]]},{"n":"潘兴","d":"","s":"《昭明文选》卷十三晋·潘安仁（岳）《秋兴赋》","w":"摄官承乏，猥厕朝列，夙兴晏寝，匪遑底宁。譬犹池鱼笼鸟，有江湖山薮之思，于是染翰操纸，慨然而赋。于时秋也，故以秋兴命篇。","q":[["才薄无潘兴，便便画偃庐。","刘言史 立秋日"],["作赋推潘岳，题诗许谢康。","李林甫 秋夜望月忆韩席等诸侍郎因以投赠"]]},{"n":"潘岳瘗夭","d":"","s":"《昭明文选》卷十晋·潘安仁（岳）《西征赋》","w":"「夭赤子于新安，坎路侧而瘗之。亭有千秋之号，子无七旬之期。虽勉励于延吴，实潜恸乎余慈。」唐·李善注：「《伤弱子·序》曰：「三月壬寅，弱子生。五月之长安。壬寅，次于新安之千秋亭。甲辰而弱子夭，乙巳瘗于亭东。」","q":[["瘗夭追潘岳，持危觅邓林。","杜甫 风疾舟中伏枕书怀三十六韵奉呈湖南亲友"]]},{"n":"潘子赋橘","d":"","s":"《艺文类聚》卷八十六","w":"晋·潘岳《橘赋》曰：余斋前橘树，冬夏再熟，聊为赋云尔。嗟嘉卉之芳华，信氛氲而芬馥，既蓊茸而萎蕤，且参差而橚矗。已郁郁而冬茂，亦离离而夏熟，至如广命宾客，历览游观，三清既设，百味星烂，炫熀乎玉案，照曜于金盘。故成都美其家园，江陵重其千树，既见…","q":[["既荣潘子赋，方重陆生言。","李峤 桔"]]},{"n":"萍蓬","d":"","s":"《昭明文选》卷十晋·潘安仁（岳）《西征赋》","w":"陋吾人之拘挛，飘萍浮而蓬转。","q":[["萍蓬风波急，桑榆日月侵。","韩愈 孟生诗"]]},{"n":"石火","d":"","s":"《昭明文选》卷二十六晋·潘安仁（岳）《河阳县作二首》其一","w":"人生天地间，百岁孰能要？颎如槁石火，瞥若截道飙。","q":[["人生石火光，通时少于塞。","子兰 短歌行"],["徒闭蓬门坐，频经石火迁。","寒山 诗"]]},{"n":"颜谢","d":"","s":"《宋书》卷七十三《颜延之传》","w":"延之与陈郡谢灵运俱以词彩齐名，自潘岳、陆机之后，文士莫及也，江左称颜、谢焉。所著并传于世。","q":[["颜谢徵文并，钟裴直事同。","司空曙 奉和常舍人晚秋集贤院即事寄徐薛二侍郎"],["世业大小礼，近通颜谢诗。","戴叔伦 抚州对事后送外生宋垓归饶州觐侍呈上姊夫"]]},{"n":"枣下悲歌","d":"","s":"《昭明文选》卷十八〈赋壬·音乐下·笙赋〉～859～","w":"咏园桃之夭夭，歌枣下之纂纂。歌曰：「枣下纂纂，朱实离离，宛其落矣，化为枯枝。人生不能行乐，死何以虚谥为。」唐·李善注引《古咄唶歌》曰：「枣下何攒攒，荣华各有时。枣欲初赤时，人从四边来。枣适今日赐，谁当仰视之。攒，聚貌。纂，与攒古字通。」","q":[["桃源迷路竟茫茫，枣下悲歌徒纂纂。","韩愈 游青龙寺赠崔大补阙"]]},{"n":"中郎作赋","d":"","s":"《昭明文选》卷十六〈赋辛·志下·闲居赋〉～699～","w":"晋十有四年，余春秋三十有二，始见二毛。以太尉掾兼虎贲中郎将，寓直于散骑之省。高阁连云，阳景罕曜，珥蝉冕而袭纨绮之士，此焉游处。","q":[["晋家都洛滨，朝廷多近臣。词赋归潘岳，繁华称季伦。梓泽春草菲，河阳乱华飞。","刘希夷 洛川怀古"],["行行潘生赋，赫赫曹公谋。","岑参 东归晚次潼关怀古"]]}],"11":[{"n":"班马香","d":"","s":"杜牧《冬至日寄小侄阿宜诗》","w":"高摘屈宋艳，浓薰班马香。","q":[]},{"n":"宋玉悲","d":"","s":"《楚辞》卷八《九辩》","w":"悲哉秋之为气也！萧瑟兮草木摇落而变衰，憭慄兮若在远行，登山临水兮送将归，……皇天平分四时兮，窃独悲此廪秋。……靓杪秋之遥夜兮，心缭悷而有哀。","q":[["贵来君却少，秋至老偏悲。","崔峒 寄上礼部李侍郎"],["我有新秋泪，非关宋玉悲。","畅当 别卢纶"]]},{"n":"独醒人","d":"","s":"《楚辞》卷七〈渔父〉","w":"屈原既放，游于江潭，行吟泽畔，颜色憔悴，形容枯槁。渔父见而问之曰：「子非三闾大夫与？何故至于斯？」屈原曰：「举世皆浊我独清，人皆醉我独醒，是以见放。」渔父曰：「圣人不凝滞于物，而能与世推移。世人皆浊，何不淈其泥而扬其波？人皆醉，何不餔其糟而…","q":[["忽逢幽隐处，如见独醒人。","于武陵 山上树"],["从来不爱三闾死，今日凭君莫独醒。","刘得仁 赠从弟谷"]]},{"n":"濯尘缨","d":"沧浪：指归隐。唐贾岛《重酬姚少府》：“沧浪余将还，知音激所习。”","s":"《楚辞补注》卷七〈渔父〉～80～","w":"屈原既放，游于江潭，行吟泽畔，颜色憔悴，形容枯槁。渔父见而问之怪屈原也。曰：「子非三闾大夫与？何故至于斯？」屈原曰：「举世皆浊我独清，众人皆醉我独醒，是以见放。」渔父曰：「圣人不凝滞于物，而能与世推移。世人皆浊，何不淈其泥而扬其波？众人皆醉…","q":[["濯缨易为水，何必泛沧浪。","于濆 感怀"],["青枫江上沧浪吟，白月宫中鹦鹉林。","储光羲 酬李壶关奉使行县忆诸公"]]},{"n":"屈贾","d":"","s":"《史记》卷八十四〈屈原贾生列传·贾生〉～249～","w":"贾生名谊，雒阳人也。年十八，以能诵诗属书闻于郡中。吴廷尉为河南守，闻其秀才，召置门下，甚幸爱。孝文皇帝初立，闻河南守吴公治平为天下第一，故与李斯同邑而常学事焉，乃徵为廷尉。廷尉乃言贾生年少，颇通诸子百家之书。文帝召以为博士。是时贾生年二十馀…","q":[["试与屈贾招清魂，荒唐大树悉楠桂。","唐扶 使南海道长沙题道林岳麓寺"],["中间屈贾辈，谗毁竟自取。","杜甫 上水遣怀"]]},{"n":"楚泽魂","d":"","s":"《史记》卷八十四《屈原列传》","w":"令尹子兰闻之大怒，卒使上官大夫短屈原于顷襄王，顷襄王怒而迁之。屈原至于江滨，被发行吟泽畔。颜色憔悴，形容枯槁。……乃作《怀沙》之赋。……于是怀石遂自沈汨罗以死。","q":[["莫渡汨罗水，回君忠孝肠。","于濆 戍客南归"],["若待清湘葬鱼了，纵然招得不堪招。","吴融 南迁途中作七首寄友人"]]},{"n":"初度","d":"","s":"《楚辞补注》卷一〈离骚经·王逸序〉","w":"帝高阳之苗裔兮，朕皇考曰伯庸。摄提贞于孟陬兮，惟庚寅吾以降。皇览揆余初度兮，肇锡余以嘉名。名余曰正则兮，字余曰灵均。纷吾既有此内美兮，又重之以脩能。汉·王逸注：「肇，始也。锡，赐也。嘉，善也。言父伯庸观我始生年时，度其日月，皆合天地之正中，…","q":[]},{"n":"初服","d":"","s":"《楚辞》卷一《离骚》","w":"「进不入以离尤兮，退将复脩吾初服。」东汉·王逸注：「言己诚欲遂进，竭其忠诚，君不肯纳，恐重遇祸，故将复去，脩吾初始清洁之服也。」","q":[["初服已惊玄发长，高情犹向碧云深。","刘禹锡 酬淮南廖参谋秋夕见过之作"]]},{"n":"楚臣伤江枫","d":"","s":"《楚辞》卷九《招魂》","w":"「湛湛江水兮上有枫，目极千里兮伤春心。魂兮归来哀江南！」东汉·王逸注：「言湛湛江水，浸润枫木，使之茂盛。伤己不蒙君惠，而身放弃，曾不若树木得其所也。」","q":[["楚臣伤江枫，谢客拾海月。","李白 同友人舟行游台越作"],["魂来枫叶青，魂返关塞黑。","杜甫 梦李白二首之一"]]},{"n":"楚辞招","d":"","s":"《楚辞补注》卷九〈招魂〉","w":"东汉·王逸《序》：「〈招魂〉者，宋玉之所作也。招者，召也。以手曰招，以言曰召。魂者，身之精也。宋玉怜哀屈原，忠而斥弃，愁懑山泽，魂魄放佚，厥命将落。故作〈招魂〉，欲以复其精神，延其年寿，外陈四方之恶，内崇楚国之美，以讽谏怀王，冀其觉悟而还之…","q":[["搔首惊闻楚些歌，拂衣归去泪悬河。","牟融 邵公母"],["我有迷魂招不得，雄鸡一声天下白。","李贺 致酒行"]]},{"n":"楚大夫","d":"","s":"《史记》卷八十四〈屈原贾生列传·屈原〉","w":"屈原者，名平，楚之同姓也。为楚怀王左徒。博闻彊志，明于治乱，娴于辞令。入则与王图议国事，以出号令；出则接遇宾客，应对诸侯。王甚任之。上官大夫与之同列，争宠而心害其能。怀王使屈原造为宪令，屈平属草未定。上官大夫见而欲夺之，屈平不与，因谗之曰…","q":[["北风吹楚树，此地独先秋。何事屈原恨，不随湘水流。","于武陵 夜泊湘江"],["寒潮欲上泛萍藻，寄荐三闾情自哀。","刘沧 江行书事"]]},{"n":"屈宋","d":"","s":"《隋书》卷七十六《文学传·王贞传》","w":"炀帝即位，齐王暕镇江都，闻其名，以书召之曰：「夫山藏美玉，光照廊庑之间，地蕴神剑，气浮星汉之表。是知毛遂颖脱，义感平原，孙慧文词，来迁东海。顾循寡薄，有怀髦彦，籍甚清风，为日久矣，未获披觌，良深伫迟。比高天流火，早应凉飙，陵云仙掌，方承清露…","q":[["荆门倒屈宋，梁苑倾邹枚。","李白 赠王判官时余归隐居庐山屏风叠"],["羁离交屈宋，牢落值颜闵。","杜甫 赠郑十八贲"]]},{"n":"楚佩","d":"","s":"《楚辞补注》卷二〈九歌·湘君〉～59～","w":"君不行兮夷犹，蹇谁留兮中洲？美要眇兮宜修，沛吾乘兮桂舟。令沅湘兮无波，使江水兮安流！望夫君兮未来，吹参差兮谁思！驾飞龙兮北征，邅吾道兮洞庭。薜荔柏兮蕙绸，荪桡兮兰旌。望涔阳兮极浦，横大江兮扬灵。扬灵兮未极，女婵媛兮为余太息。横流涕兮潺湲，隐…","q":[]},{"n":"吊屈","d":"吊楚臣：指自伤身世。唐李白《赠崔秋浦》：“应念金门客，投沙吊楚臣。”","s":"《史记》卷八十四《贾生列传》","w":"「贾生名谊，雒阳人也。」「绛、灌、东阳侯、冯敬之属尽害之，乃短贾生曰：『雒阳之人，年少初学，专欲擅权，纷乱诸事。』于是天子后亦疏之，不用其议，乃以贾生为长沙王太傅。贾生既辞往行，闻长沙卑湿，自以寿不得长，又以适去，意不自得。及渡湘水，为赋以…","q":[["贾生方吊屈，岂敢比南昌。","储光羲 奉酬张五丈垂赠"],["屈平君莫吊，肠断洞庭波。","刘长卿 同姜浚题裴式微余干东斋"]]},{"n":"詹尹","d":"","s":"《楚辞补注》卷六〈卜居〉","w":"屈原既放三年，不得复见，竭智尽忠，蔽鄣于谗。心烦意乱，不知所从乃往见太卜郑詹尹，曰：「余有所疑，愿因先生决之。」詹尹乃端策拂龟，曰：「君将何以教之？」屈原曰：吾宁悃悃款款，朴以忠乎？将送往劳来，斯无穷乎？宁诛锄草茅，以力耕乎？将游大人，以成…","q":[]},{"n":"问青天","d":"呵壁问天：喻指失意、愤感。唐李贺《公无出门》：“分明犹惧公不信，公看呵壁书问天。”","s":"《楚辞补注》卷三〈天问〉～85～","w":"〈天问〉者，屈原之所作也。何不言问天？天尊不可问，故曰天问也。屈原放逐，忧心愁悴。彷徨山泽，经历陵陆。嗟号昊旻，仰天叹息。见楚有先王之庙及公卿祠堂，图画天地山川神灵，琦玮僪佹，及古贤圣怪物行事。周流罢倦，休息其下，仰见图画，因书其壁，呵而问…","q":[["分明犹惧公不信，公看呵壁书问天。","李贺 公无出门"],["盈虚用舍轮舆旋，勿学灵均远问天。","赵冬曦 灉湖作"]]},{"n":"椒兰妒忌","d":"","s":"《楚辞》战国楚·屈原《离骚》","w":"「余以兰为可恃兮，羌无实而容长。委厥美以从俗兮，苟得列乎芳。椒专佞以慢慆兮，榝又欲充夫佩帏。」东汉·王逸注：「兰，怀王少弟，司马子兰也。」","q":[["椒兰争妒忌，绛灌共谗谄。","韩愈 陪杜侍御游湘西两寺独宿有题一首因献杨常侍"]]},{"n":"九阊","d":"","s":"《楚辞》战国楚·屈原《离骚》","w":"「吾令帝阍开关兮，倚阊阖而望予。」东汉·王逸注：「帝，谓天帝。阍，主门者也。阊阖，天门也。言己求贤不得，疾谗恶佞，将上诉天帝，使阍人开关，又倚天门望而距我，使我不得入也。」","q":[["神理今难问，予将叫帝关。","张乔 哭陈陶"],["白昼叫阍无近戚，缟衣饮气只门生。","李玖 喷玉泉冥会诗八首之白衣叟述甘棠馆西楹诗"]]},{"n":"靳尚","d":"","s":"《史记》卷八十四《屈原列传》","w":"「上官大夫与之同列，争宠而心害其能。怀王使屈原造为宪令，屈平属草稿未定。上官大夫见而欲夺之，屈平不与，因谗之曰：『王使屈平为令，众莫不知，每一令出，平伐其功，以为「非我莫能为」也。』王怒而疏屈平。」唐·张守节《史记正义》：「王逸云上官靳尚。…","q":[["欲慰灵均恨，先烧靳尚祠。","徐凝 浙西李尚书奏毁淫昏庙"]]},{"n":"九歌","d":"","s":"《楚辞补注》卷二〈九歌〉～55～","w":"〈九歌〉者，屈原之所作也。昔楚国南郢之邑，沅、湘之间，其俗信鬼而好祠。其祠必作歌乐，鼓舞以乐诸神。屈原放逐，窜伏其域，怀忧苦毒，愁思沸郁，出见俗人祭祀之礼，歌舞之乐，其词鄙陋，因为作《九歌》之曲。","q":[["惟有九歌词数首，里中留与赛蛮神。","刘禹锡 别夔州官吏"]]},{"n":"哺糟","d":"","s":"《楚辞补注》卷七〈渔父〉","w":"屈原既放，游于江潭，行吟泽畔，颜色憔悴，形容枯槁。渔父见而问之怪屈原也。曰：「子非三闾大夫与？何故至于斯？」屈原曰：「举世皆浊我独清，众人皆醉我独醒，是以见放。」渔父曰：「圣人不凝滞于物，而能与世推移。世人皆浊，何不淈其泥而扬其波？众人皆醉…","q":[["缅慕鼓枻翁，啸咏哺其糟。","柳宗元 游南亭夜还叙志七十韵"],["屈原《离骚》二十五，不肯餔啜糟与醨，惜哉此子巧言语，不到圣处宁非痴。","韩愈 感春四首之二"]]},{"n":"泽畔吟","d":"","s":"《史记》卷八十四〈屈原贾生列传〉～2486～","w":"屈原至于江滨，被发行吟泽畔。颜色憔悴，形容枯槁。渔父见而问之曰：「子非三闾大夫欤？何故而至此？」屈原曰：「举世混浊而我独清，众人皆醉而我独醒，是以见放。」渔父曰：「夫圣人者，不凝滞于物而能与世推移。举世混浊，何不随其流而扬其波？众人皆醉，何…","q":[["计日西归在，休为泽畔吟。","戎昱 送郑炼师贬辰州"],["竹花不给口，憔悴清湘滨。","李群玉 送萧绾之桂林"]]},{"n":"诛茅","d":"","s":"《楚辞补注》卷六〈卜居〉～76～","w":"屈原既放三年，不得复见，竭智尽忠，蔽鄣于谗。心烦意乱，不知所从乃往见太卜郑詹尹，曰：「余有所疑，愿因先生决之。」詹尹乃端策拂龟，曰：「君将何以教之？」屈原曰：吾宁悃悃款款，朴以忠乎？将送往劳来，斯无穷乎？宁诛锄草茅，以力耕乎？将游大人，以成…","q":[["三年拔薤成仁政，一日诛茅葺所居。","吴融 和峡州冯使君题所居"],["借宅诛茅绿，分囷指粟红。","吴融 赴阙次留献荆南成相公三十韵"]]},{"n":"千里驹","d":"","s":"《楚辞补注》卷六〈卜居〉～76～","w":"屈原既放三年，不得复见，竭智尽忠，蔽鄣于谗。心烦意乱，不知所从乃往见太卜郑詹尹，曰：「余有所疑，愿因先生决之。」詹尹乃端策拂龟，曰：「君将何以教之？」屈原曰：吾宁悃悃款款，朴以忠乎？将送往劳来，斯无穷乎？宁诛锄草茅，以力耕乎？将游大人，以成…","q":[]},{"n":"女媭","d":"","s":"《楚辞》战国楚·屈原《离骚》","w":"「女媭之婵媛兮，申申其詈予。」东汉·王逸注：「女媭，屈原姊也。婵媛，犹牵引也，一作掸援。」","q":[["虎口何婉娈，女媭空婵媛。","李白 古风"]]},{"n":"纫兰佩","d":"","s":"《楚辞》卷一《离骚》","w":"「扈江离与辟芷兮，纫秋兰以为佩。」东汉·王逸注：「纫，索也。兰，香草也，秋而芳。佩，饰也，所以象德。故行清洁者佩芳，德仁明者佩玉，能解结者佩觿，能决疑者佩玦，故孔子无所不佩也。言己脩身清洁，乃取江离、辟芷，以为衣被；纫索秋兰，以为佩饰。」","q":[["自甘逐客纫兰佩，不料平民著战衣。","徐铉 避难东归依韵和黄秀才见寄"],["不采而佩，于兰何伤。","韩愈 猗兰操"]]},{"n":"彭咸沦没","d":"","s":"《楚辞》卷一《离骚》","w":"「虽不周于今之人兮，愿依彭咸之遗则。」东汉·王逸注：「彭咸，殷贤大夫，谏其君不听，自投水而死。」","q":[["彭咸久沦没，此意与谁论。","李白 古风之五十一"]]},{"n":"奇服","d":"","s":"《楚辞》卷四《九章·涉江》","w":"余幼好此奇服兮，年既老而不衰。带长铗之陆离兮，冠切云之崔嵬。被明月兮佩宝璐。世溷浊而莫余知兮，吾方高驰而不顾。","q":[["楚客罢奇服，吴姬停棹歌。","李群玉 晚莲"]]},{"n":"脂韦","d":"","s":"《楚辞补注》卷六〈卜居〉","w":"屈原既放三年，不得复见，竭智尽忠，蔽鄣于谗。心烦意乱，不知所从乃往见太卜郑詹尹，曰：「余有所疑，愿因先生决之。」詹尹乃端策拂龟，曰：「君将何以教之？」屈原曰：吾宁悃悃款款，朴以忠乎？将送往劳来，斯无穷乎？宁诛锄草茅，以力耕乎？将游大人，以成…","q":[["出送抚背我涕挥，行行正直慎脂韦。","韩愈 送区弘南归"]]},{"n":"逐黄鹄","d":"","s":"《楚辞补注》卷六〈卜居〉","w":"屈原既放三年，不得复见，竭智尽忠，蔽鄣于谗。心烦意乱，不知所从乃往见太卜郑詹尹，曰：「余有所疑，愿因先生决之。」詹尹乃端策拂龟，曰：「君将何以教之？」屈原曰：吾宁悃悃款款，朴以忠乎？将送往劳来，斯无穷乎？宁诛锄草茅，以力耕乎？将游大人，以成…","q":[["入海观龙鱼，矫翮逐黄鹄。","韩愈 送诸葛觉往随州读书"]]},{"n":"枘凿","d":"","s":"《楚辞补注》卷一〈离骚经·王逸序〉～24～","w":"夫维圣哲以茂行兮，苟得用此下土。瞻前而顾后兮，相观民之计极。夫孰非义而可用兮，孰非善而可服。阽余身而危死兮，览余初其犹未悔。不量凿而正枘兮，固前脩以菹醢。宋·洪兴祖补注：「枘……刻木端所以入凿。」又〈九辩〉「圆凿而方枘兮。吾固知其锄铻而难入…","q":[]},{"n":"宋玉","d":"","s":"《史记》卷八十四《屈原列传》","w":"屈原既死之后，楚有宋玉、唐勒、景差之徒者，皆好辞而以赋见称；然皆祖屈原之从容辞令，终莫敢直谏。其后楚日以削，数十年竟为秦所灭。","q":[["楚王犹自惑，宋玉且将归。","岑参 送崔全被放归都觐省"],["高丘怀宋玉，访古一沾裳。","李白 宿巫山下"]]},{"n":"巫阳招","d":"","s":"《楚辞补注》卷九〈招魂〉～97～","w":"「帝告巫阳曰：『有人在下，我欲辅之。魂魄离散，汝筮予之！』……巫阳焉乃下招曰：『魂兮归来。』」","q":[["帝赐九河湔涕痕，又诏巫阳反其魂，徐命之前问何冤。","韩愈 陆浑山火和皇浦湜用其韵"]]}],"12":[{"n":"屋三间","d":"","s":"《世说新语笺疏》中卷下〈赏誉〉～443～","w":"蔡司徒在洛，见陆机兄弟住参佐廨中，三间瓦屋，士龙住东头，士衡住西头。士龙为人，文弱可爱。士衡长七尺馀，声作钟声，言多慷慨。","q":[["谁怜芳草生三径，参佐桥西陆士龙。","温庭筠 春暮宴罢寄宋寿先辈"]]},{"n":"陆谢","d":"","s":"南朝梁钟嵘《诗品·总论》","w":"昔 曹 刘 殆文章之圣， 陆 谢 为体贰之才。","q":[]},{"n":"黄耳犬","d":"","s":"《述异记》","w":"陆机少时，颇好游猎，在吴豪盛客献快犬名曰黄耳；机后仕洛，常将自随。此犬黠慧能解人语，又尝借人三百里外，犬识路自还，一日至家。机羁旅京师，久无家问，因戏语犬曰：「我家绝无书信，汝能赍书驰取消息不？」犬喜摇尾，作声应之。机试为书，盛以竹筒，系之…","q":[]},{"n":"川媚","d":"","s":"《昭明文选》卷十七晋·陆士衡（机）《文赋》","w":"「石韫玉而山辉。水怀珠而川媚。」唐·李善注：「虽无佳偶，因而留之，譬若水石之藏珠玉，山川为之辉媚也。」","q":[["徒看川色媚，空爱夜光浮。","王损之 赋得浊水求珠"],["润川终自媚，照乘且何由。","王起 浊水求珠"]]},{"n":"吊魏武","d":"","s":"《昭明文选》卷六十晋·陆士衡（机）《吊魏武帝文·序》","w":"「观其所以顾命冢嗣，贻谋四子，经国之略既远，隆家之训亦弘。又云：『吾在军中，持法是也。至小忿怒，大过失……。』善乎达人之谠言矣！声类曰：『谠，善言也。』持姬女而指季豹以示四子曰：『以累汝！』因泣下。伤哉！曩以天下自任，今以爱子托人。伤哉！曩…","q":[["请君骑马望西陵，为我殷勤吊魏武","李颀 送刘方平"]]},{"n":"陆弟","d":"","s":"《诗品》卷中","w":"清河之方平原，殆如陈思之匹白马；于其哲昆，故称二陆。","q":[["香名冠二陆，精鉴逢山涛。","刘长卿 客舍赠别韦九建赴任河南韦十七造赴任郑县就便觐省"],["洛中推二陆，莫久恋乡关。","喻凫 送石贲归吴兴"]]},{"n":"二十四友","d":"","s":"《晋书》卷六十二〈刘琨列传〉～679～","w":"刘琨字越石，中山魏昌人，汉中山靖王胜之后也。祖迈，有经国之才，为相国参军、散骑常侍。父蕃，清高冲俭，位至光禄大夫。琨少得俊朗之目，与范阳祖纳俱以雄豪著名。年二十六，为司隶从事。时征虏将军石崇河南金谷涧中有别庐，冠绝时辈，引致宾客，日以赋诗。…","q":[["珍重昔年金谷友，共来泉际话幽魂。","李玖 四丈夫同赋"],["嗣世衰微谁肯忧，二十四友日日空追游。","韦应物 金谷园歌"]]},{"n":"飞泉漱玉","d":"","s":"《昭明文选》卷二十二〈诗乙·招隐·招隐诗〉～029～","w":"明发心不夷，振衣聊踯躅。踯躅欲安之，幽人在浚谷。朝采南涧藻，夕息西山足。轻条象云构，密叶成翠幄。激楚伫兰林，回芳薄秀木。山溜何泠泠，飞泉漱鸣玉。哀音附灵波，颓响赴曾曲。至乐非有假，安事浇醇朴？富贵苟难图，税驾从所欲。唐·李善注引枚乘上书曰：…","q":[]},{"n":"焚砚","d":"焚砚：指自谦文才不如他人。唐冯伉《和权载之离合诗》：“息心欲焚砚，自腼陪群英。”","s":"《晋书》卷五十四《陆机传》","w":"机天才秀逸，辞藻宏丽，张华尝谓之曰：「人之为文，常恨才少，而子更患其多。」弟云尝与书曰：「君苗见兄文，辄欲烧其笔砚。」","q":[["君苗徒见爇，谁咏士衡篇。","李峤 砚"],["息心欲焚砚，自腼陪群英。","冯伉 和权载之离合诗"]]},{"n":"焚芝","d":"","s":"《昭明文选》卷十六晋·陆士衡（机）《叹逝赋》","w":"「信松茂而柏悦，嗟芝焚而蕙叹。」唐·李周翰注：「同类相感也……芝、蕙香草也，言亲友既逝，其情无聊。」","q":[["游人行变橘，逝者遽焚芝。","孔绍安 伤顾学士"]]},{"n":"风鉴","d":"","s":"《晋书》卷六十五〈王导列传〉～745～","w":"导字茂弘，光禄大夫览之孙也。父裁，镇军司马。导少有风鉴，识量清远。年十四，陈留高士张公见而奇之，谓其从兄敦曰：「此儿容貌志气，将相之器也。」","q":[]},{"n":"广宵翁","d":"","s":"《昭明文选》卷二十八晋·陆士衡（机）《挽歌诗》","w":"「广宵何寥廓，大暮安可晨？人往有反岁，我行无归年！」唐·李周翰注：「宵、暮，皆夜，谓圹中也。」","q":[["杼山砖塔禅，竟陵广宵翁。","孟郊 送陆畅归湖州因凭题故人皎然塔陆羽坟"]]},{"n":"华亭鹤","d":"","s":"《世说新语》下卷下《尤悔》","w":"「陆平原河桥败，为卢志所谗，被诛。临刑叹曰：『欲闻华亭鹤唳，可复得乎！』」南朝梁·刘孝标注引《八王故事》曰：「华亭，吴由拳县郊外墅也，有清泉茂林。吴平后，陆机兄弟共游于此十馀年。」","q":[["华亭失侣鹤，乘轩宠遂终。","孔德绍 赋得华亭鹤"],["死忆华亭闻唳鹤，老忧王室泣铜驼。","李商隐 曲江"]]},{"n":"犬书","d":"犬书：喻书信。唐李贺《始为奉礼忆昌谷山居》：“犬书曾去洛，鹤病悔游秦。”","s":"《艺文类聚》卷九十四〈兽部中·狗〉～639～","w":"旧题南朝梁·任昉《述异记》：陆机少时，颇好游猎，在吴豪盛客献快犬名曰黄耳；机后仕洛，常将自随。此犬黠慧能解人语，又尝借人三百里外，犬识路自还，一日至家。机羁旅京师，久无家问，因戏语犬曰：「我家绝无书信，汝能赍书驰取消息不？」犬喜摇尾，作声应…","q":[["犬书曾去洛，鹤病悔游秦。","李贺 始为奉礼忆昌谷山居"],["有猿挥泪尽，无犬附书频。","杜甫 雨晴"]]},{"n":"陆机兄弟","d":"","s":"《三国志》卷五十八〈吴书·陆抗〉～360～","w":"南朝宋·裴松之注引《机云别传》曰：晋太康末，俱入洛，造司空张华，华一见而奇之，曰：「伐吴之役，利在获二俊。」遂为之延誉，荐之诸公。太傅杨骏辟机为祭酒，转太子洗马、尚书著作郎。云为吴王郎中令，出宰浚仪，甚有惠政，吏民怀之，生为立祠。后并历显位…","q":[["洛水桥边雁影疏，陆机兄弟驻行车。","李益 中桥北送穆氏兄弟应制戏赠萧二策"],["士衡兄弟旧齐名，还似当年在洛城。","武元衡 夏日寄陆三达陆四逢并王念八仲周"]]},{"n":"千里莼","d":"","s":"《世说新语笺疏》上卷上〈言语〉～88～","w":"陆机诣王武子，武子前置数斛羊酪，指以示陆曰：「卿江东何以敌此？」陆云：「有千里莼羹，但未下盐豉耳！」","q":[["若逢广坐问羊酪，从此知名在一言。","刘禹锡 送周鲁儒赴举诗并引"],["江左重诗篇，陆生名久传。凤城来已熟，羊酪不嫌膻。","刘禹锡 送陆侍御归淮南使府五韵（用年字）"]]},{"n":"士龙笑","d":"","s":"《晋书》卷五十四〈陆云列传〉～48～","w":"云字士龙，六岁能属文，性清正，有才理。少与兄机齐名，虽文章不及机，而持论过之，号曰「二陆」。幼时吴尚书广陵闵鸿见而奇之，曰：「此儿若非龙驹，当是凤雏。」后举云贤良，时年十六……吴平，入洛。机初诣张华，华问云何在。机曰：「云有笑疾，未敢自见。…","q":[["谁惮士龙多笑疾，美髭终类晋司空。","李商隐 奉和太原公送前杨秀才戴兼招杨正字戎"]]},{"n":"潘陆","d":"","s":"《全上古三代秦汉三国六朝文·全梁文》卷五十五〈钟嵘·诗品上〉","w":"晋黄门郎潘岳诗，其源出于仲宣。翰林叹其翩翩然如翔禽之有羽毛，衣服之有绡縠，犹浅于陆机。谢混云：「潘诗烂若舒锦，无处不佳。陆文如披沙简金，往往见宝。」嵘谓益寿轻华，故以潘胜。翰林笃论，故叹陆为深。余常言陆才如海，潘才如江。","q":[["潘陆应同调，孙吴亦异时。","杜甫 暮春江陵送马大卿公恩命追赴阙下"],["双溪逢陆海，荆渚遇平津。","贯休 赠抱麻刘舍人"]]},{"n":"陆平原","d":"","s":"《晋书》卷五十四《陆机传》","w":"陆机字士衡，吴郡人也。祖逊，吴丞相。父抗，吴大司马。机身长七尺，其声如钟。少有异才，文章冠世，伏膺儒术，非礼不动。……至太康末，与弟云俱入洛，造太常张华。……时成都王颖推功不居，劳谦下士。机既感全济之恩，又见朝廷屡有变难，谓颖必能康隆晋室，…","q":[["平原思令弟，康乐谢贤昆。","王维 和陈监四郎秋雨中思从弟据"],["高谭魏国访先生，修刺平原过内史。","韩翃 送李湜下第归卫州便游河北"]]},{"n":"陆机雾","d":"","s":"《晋书》卷五十四《陆机传》","w":"机既死非其罪，士卒痛之，莫不流涕。是日昏雾昼合，大风折木，平地尺雪，议者以为陆氏之冤。","q":[["冤深陆机雾，愤积伍员涛。","张祜 哭汴州陆大夫"]]},{"n":"陆机云","d":"","s":"《晋书》卷五十四〈陆云列传〉～48～","w":"云字士龙，六岁能属文，性清正，有才理。少与兄机齐名，虽文章不及机，而持论过之，号曰「二陆」。幼时吴尚书广陵闵鸿见而奇之，曰：「此儿若非龙驹，当是凤雏。」后举云贤良，时年十六。","q":[]},{"n":"陆机作文赋","d":"","s":"《昭明文选》卷十七晋·陆士衡（机）《文赋》","w":"唐·李善注引臧荣绪《晋书》曰：机字士衡，吴郡人。祖逊，吴丞相。父抗，吴大司马。机少袭领父兵，为牙门将军。年二十而吴灭，退临旧里，与弟云勤学，积十一年。誉流京华，声溢四表，被徵为太子洗马，与弟云俱入洛。司徒张华，素重其名，旧相识以文。华呈天才…","q":[["陆机始拟誇文赋，不觉云间有士龙。","李商隐 赠孙绮新及第"],["陆机二十作文赋，汝更小年能缀文。","杜甫 醉歌行"]]},{"n":"披沙简金","d":"","s":"南朝梁·钟嵘《诗品》卷上《晋·黄门郎潘岳》","w":"谢混云：「潘诗烂若舒锦。陆文如披沙简金，往往见宝。」","q":[["手中一百篇，句句披沙金。","白居易 赠能七伦"],["赠我一篇行路吟，吟之句句披沙金。","白居易 醉后走笔酬刘五主簿长句之赠兼简张大贾二十四先辈昆季"]]},{"n":"平原赋","d":"","s":"晋·陆机《陆机集》卷三《叹逝赋·序》","w":"昔每闻长老追计平生，同时亲故，或凋落已尽，或仅有存者。余年方四十，而懿亲戚属，亡多存寡，昵交密友，亦不半在。或所曾共游一涂，同宴一室，十年之外，索然已尽，以是思哀。哀可知矣。","q":[["缅怀山阳笛，永恨平原赋。","李端 慈恩寺怀旧（并序）"],["无复平原赋，空馀邻笛声。","卢藏用 宋主簿鸣皋梦赵六予未及报而陈子云亡今（一无今字）追为此诗答宋兼贻平昔游旧"]]},{"n":"二陆入洛","d":"","s":"《三国志》卷五十八〈吴书·陆逊传·陆抗〉～360～","w":"南朝宋·裴松之注：「景弟机，字士衡，云字士龙。」《机云别传》曰：「晋太康末，俱入洛，造司空张华，华一见而奇之，曰：『伐吴之役，利在获二俊。』遂为之延誉，荐之诸公。太傅杨骏辟机为祭酒，转太子洗马、尚书著作郎。云为吴王郎中令，出宰浚仪，甚有惠政…","q":[["陆机初入洛，孙楚又游吴。","储嗣宗 早春怀薛公裕"],["陆云还入洛，潘岳更张筵。","李端 送杨少府赴阳翟"]]},{"n":"三俊","d":"","s":"《晋书》卷六十八〈顾荣列传〉～8～","w":"顾荣字彦先，吴国吴人也，为南土著姓。祖雍，吴丞相。父穆，宜都太守。荣机神朗悟，弱冠仕吴，为黄门侍郎、太子辅义都尉。吴平，与陆机兄弟同入洛，时人号为「三俊」。例拜为郎中，历尚书郎、太子中舍人、廷尉正。恒纵酒酣畅，谓友人张翰曰：「惟酒可以忘忧，…","q":[]},{"n":"士衡患多","d":"","s":"《晋书》卷五十四《陆机传》","w":"机天才秀逸，辞藻宏丽，张华尝谓之曰：「人之为文，常恨才少，而子更患其多。」","q":[["武仲不休，士衡患多。","李瀚 蒙求"]]},{"n":"士衡文","d":"","s":"《晋书》卷五十四〈陆机列传〉～467～","w":"陆机字士衡，吴郡人也。祖逊，吴丞相。父抗，吴大司马。机身长七尺，其声如钟。少有异才，文章冠世，","q":[["西陵倘一吊，应有士衡文。","皇甫冉 送萧献士"]]},{"n":"笑疾","d":"","s":"《晋书》卷五十四〈陆云列传〉～48～","w":"云字士龙，六岁能属文，性清正，有才理。少与兄机齐名，虽文章不及机，而持论过之，号曰「二陆」。幼时吴尚书广陵闵鸿见而奇之，曰：「此儿若非龙驹，当是凤雏。」后举云贤良，时年十六……吴平，入洛。机初诣张华，华问云何在。机曰：「云有笑疾，未敢自见。…","q":[]},{"n":"颜谢","d":"","s":"《宋书》卷七十三《颜延之传》","w":"延之与陈郡谢灵运俱以词彩齐名，自潘岳、陆机之后，文士莫及也，江左称颜、谢焉。所著并传于世。","q":[["颜谢徵文并，钟裴直事同。","司空曙 奉和常舍人晚秋集贤院即事寄徐薛二侍郎"],["世业大小礼，近通颜谢诗。","戴叔伦 抚州对事后送外生宋垓归饶州觐侍呈上姊夫"]]},{"n":"羊酪","d":"","s":"《太平御览》卷八百六十一〈饮食部十九·羹〉～3956～","w":"晋·郭澄之《郭子》：「陆士衡诣王武子，武子有数斛羊酪，指示陆机曰：『卿东吴何以敌此？』机曰：『千里莼羹，未下盐豉。』」","q":[]},{"n":"张华见陆云","d":"","s":"《晋书》卷三十六《张华传》","w":"初，陆机兄弟志气高爽，自以吴之名家，初入洛，不推中国人士，见华一面如旧，钦华德范，如师资之礼焉。华诛后，作诔，又为咏德赋以悼之。","q":[["不知何处清风夕，拟使张华见陆云。","马异 答卢仝结交诗"]]}],"13":[{"n":"鲍鱼腥","d":"","s":"《史记》卷六《秦始皇本纪》","w":"七月丙寅，始皇崩于沙丘平台。丞相斯为上崩在外，恐诸公子及天下有变，乃秘之，不发丧。棺载辒凉车中，故幸宦者参乘，所至上食。百官奏事如故，宦者辄从辒凉车中可其奏事。独子胡亥、赵高及所幸宦者五六人知上死。赵高故尝教胡亥书及狱律令法事，胡亥私幸之。…","q":[["刘彻茂陵多滞骨，嬴政梓棺费鲍鱼。","李贺 苦昼短"],["欲厌东南气，翻伤掩鲍车。","李显 幸秦始皇陵"]]},{"n":"秦坑","d":"","s":"《史记》卷六〈秦始皇本纪〉～254～","w":"丞相李斯曰：「五帝不相复，三代不相袭，各以治，非其相反，时变异也。今陛下创大业，建万世之功，固非愚儒所知。且越言乃三代之事，何足法也？异时诸侯并争，厚招游学。今天下已定，法令出一，百姓当家则力农工，士则学习法令辟禁。今诸生不师今而学古，以非…","q":[["秦火不爇舌，秦火空爇文。","孟郊 秋怀"],["政烦方改篆，愚俗乃焚书。","李显 幸秦始皇陵"]]},{"n":"秦封","d":"大夫松：咏松树，或喻受恩遇。唐鲍溶《闻国家将行封禅聊抒臣情》：“清跸间过素王庙，翠华高映大夫松。”","s":"《史记》卷六〈秦始皇本纪〉～242～","w":"二十八年，始皇东行郡县，上邹峄山。立石，与鲁诸儒生议，刻石颂秦德，议封禅望祭山川之事。乃遂上泰山，立石，封，祠祀。下，风雨暴至，休于树下，因封其树为五大夫。","q":[["寄怀丞相业，因擢大夫材。","唐扶 和兵部郑侍郎省中四松诗"],["风高大夫树，露下将军药。","张说 药园宴武辂沙将军赋得洛字"]]},{"n":"德水","d":"","s":"《史记》卷六《秦始皇本纪》","w":"更名河曰德水，以为水德之始。","q":[["千年清德水，九折满荣光。","段成式 河出荣光"]]},{"n":"驱石","d":"驱石：喻造桥有如神助。唐杜甫《陪李七司马造江上观造竹桥》：“合观却笑千年事，驱石何事到海东？”","s":"晋·伏琛《三齐略记》","w":"秦始皇于海中作石桥，海神为之竖柱。始皇求与相见。神曰：「我形丑，莫图我形，当与帝相见。」乃入海四十里，见海神，左右莫动手，工人潜以脚画其状。神怒曰：「帝负约，速去。」始皇转马还，前脚犹立，后脚随崩，仅得登岸。画者溺死于海，众山之石皆倾注，今…","q":[["谁能求得秦皇术，为我先驱紫阁峰。","施肩吾 鄠县村居"],["逐日巡海右，驱石驾沧津。","李白 古风"]]},{"n":"渡浙","d":"","s":"《史记》卷六〈秦始皇本纪〉～260～","w":"三十七年十月癸丑，始皇出游。左丞相斯从，右丞相去疾守。少子胡亥爱慕请从，上许之。十一月，行至云梦，望祀虞舜于九疑山。浮江下，观籍柯，渡海渚。过丹阳，至钱唐。临浙江，水波恶，乃西百二十里从狭中渡。上会稽，祭大禹，望于南海，而立石刻颂秦德。","q":[["铭功会稽岭，骋望琅琊台。","李白 古风之三"],["枕戈忆句践，渡浙想秦皇。","杜甫 壮游"]]},{"n":"反璧","d":"","s":"《史记》卷六〈秦始皇本纪〉～259～","w":"三十六年，荧惑守心。有坠星下东郡，至地为石，黔首或刻其石曰「始皇帝死而地分」。始皇闻之，遣御史逐问，莫服，尽取石旁居人诛之，因燔销其石。始皇不乐，使博士为仙真人诗，及行所游天下，传令乐人歌弦之。秋，使者从关东夜过华阴平舒道，有人持璧遮使者曰…","q":[["卯金竟握谶，反璧俄沦祀。","王无竞 北使长城"]]},{"n":"访蓬瀛","d":"","s":"《史记》卷二十八《封禅书》","w":"「自威、宣、燕昭使人入海求蓬莱、方丈、瀛洲。此三神山者，其傅在勃海中，去人不远；患且至，则船风引而去。盖尝有至者，诸仙人及不死之药皆在焉。其物禽兽尽白，而黄金银为宫阙。未至，望之如云；及到，三神山反居水下。临之，风辄引去，终莫能至云。世主莫…","q":[["仍闻遣方士，东海访蓬瀛。","王维 早朝"]]},{"n":"锋镝铸","d":"","s":"《史记》卷六《秦始皇本纪》","w":"收天下兵，聚之咸阳，销以为钟鐻，金人十二，重各千石，置廷宫中。","q":[["愿闻锋镝铸，莫使栋梁摧。","杜甫 秋日荆南述怀三十韵"]]},{"n":"古鼎跃水","d":"","s":"《史记》卷二十八《封禅书》","w":"周太史儋见秦献公……其后百二十岁而秦灭周，周之九鼎入于秦。或曰宋太丘社亡，而鼎没于泗水彭城下。","q":[["金绳铁索锁纽壮，古鼎跃水龙腾梭。","韩愈 石鼓歌"]]},{"n":"渐离矐","d":"","s":"《史记》卷八十六《刺客列传》","w":"高渐离变名姓为人庸保，匿作于宋子。久之，作苦，闻其家堂上客击筑，傍偟不能去。每出言曰：「彼有善有不善。」从者以告其主，曰：「彼庸乃知音，窃言是非。」家丈人召使前击筑，一坐称善，赐酒。而高渐离念久隐畏约无穷时，乃退，出其装匣中筑与其善衣，更容…","q":[["斯须到绝顶，似愈渐离矐。","皮日休 初夏游楞伽精舍"]]},{"n":"碣石","d":"","s":"《史记》卷六《秦始皇本纪》","w":"二十九年，始皇东游。至阳武博狼沙中，为盗所惊。求弗得，乃令天下大索十日。登之罘，刻石。……旋，遂之琅邪，道上党入。……三十二年，始皇之碣石，使燕人卢生求羡门、高誓。刻碣石门。坏城郭，决通堤防。","q":[["之罘思汉帝，碣石想秦皇。","李世民 春日望海"],["碣石朝烟灭，之罘归雁翔。","杨师道 奉和圣制春日望海"]]},{"n":"玉连环","d":"","s":"《战国策》卷十三〈齐策六·齐闵王之遇杀〉～472～","w":"秦始皇尝使使者遗君王后玉连环，曰：「齐多知，而解此环不？」君王后以示群臣，解臣不知解。君王后引椎椎破之，谢秦使曰：「谨以解矣。」","q":[["水精如意玉连环，下蔡城危莫破颜。","李商隐 赠歌妓二首"],["再三为谢齐皇后，要解连环别与人。","罗虬 比红儿诗之四十一"]]},{"n":"荆庆才疏","d":"","s":"《史记》卷八十六〈刺客列传·荆轲〉～2534～","w":"秦王闻之，大喜，乃朝服，设九宾，见燕使者咸阳宫。荆轲奉樊于期头函，而秦舞阳奉地图柙，以次进。至陛，秦舞阳色变振恐，群臣怪之。荆轲顾笑舞阳，前谢曰：「北蕃蛮夷之鄙人，未尝见天子，故振慑。愿大王少假借之，使得毕使于前。」秦王谓轲曰：「取舞阳所持…","q":[]},{"n":"骊峰","d":"","s":"《史记》卷六《秦始皇本纪》","w":"九月，葬始皇郦山。始皇初即位，穿治郦山，及并天下，天下徒送诣七十馀万人，穿三泉，下铜而致椁，宫观百官奇器珍怪徙臧满之。","q":[["他年免似骊山鬼，信有蓬莱不可寻。","刘威 感寓"],["骊山与茂陵，相对秋草绿。","司马扎 感古"]]},{"n":"李斯","d":"","s":"《史记》卷八十七《李斯列传》","w":"「李斯者，楚上蔡人也。」「从荀卿学帝王之术。」「至秦，会庄襄王卒，李斯乃求为秦相文信侯吕不韦舍人；不韦贤之，任以为郎。李斯因以得说，……秦王拜斯为客卿。」「二十馀年，竟并天下，尊主为皇帝，以斯为丞相。」「李斯喟然而叹曰：『嗟乎！吾闻之荀卿曰…","q":[["傅说版筑臣，李斯鹰犬人。歘起匡社稷，宁复长艰辛。","李白 冬夜醉宿龙门觉起言志"],["陆机雄才岂自保，李斯税驾苦不早。华亭鹤唳讵可闻，上蔡苍鹰何足道。","李白 行路难三首之三"]]},{"n":"牧童火","d":"","s":"《汉书》卷三十六〈楚元王列传·刘向〉～954～","w":"逮至吴王阖闾，违礼厚葬，十有馀年，越人发之。及秦惠文、武、昭、严襄五王，皆大作丘陇，多其瘗臧，咸尽发掘暴露，甚足悲也。秦始皇帝葬于骊山之阿，下锢三泉，上崇山坟，其高五十馀丈，周回五里有馀；石椁为游馆，人膏为灯烛，水银为江海，黄金为凫雁。珍宝…","q":[["牧童火入九泉底，烧作灰时犹未枯。","杜牧 过骊山作"]]},{"n":"秦皇东幸","d":"","s":"《史记》卷六〈秦始皇本纪〉～242～","w":"二十八年，始皇东行郡县，上邹峄山。立石，与鲁诸儒生议，刻石颂秦德，议封禅望祭山川之事。乃遂上泰山，立石，封，祠祀。下，风雨暴至，休于树下，因封其树为五大夫。禅梁父。刻所立石，其辞曰：「皇帝临位，作制明法，臣下脩饬。二十有六年，初并天下，罔不…","q":[["北巡非汉后，东幸异秦皇。","杨师道 奉和圣制春日望海"]]},{"n":"秦冤","d":"","s":"《太平御览》卷六百四十三〈刑法部九·狱〉～302～","w":"旧题汉·郭宪《东方朔传》：「孝武皇帝时，幸甘泉，至长平阪上，驰道中央有虫复而赤如生肝状……土召朔使驰往视之。还对曰：『怪哉！」上曰：『何谓也？』朔对曰：『秦始皇时拘系无罪，幽杀无辜，众庶怨恨，无所告诉，仰天而叹曰：「怪哉！」感动皇天。此愤气…","q":[["自悯秦冤痛，谁怜楚奏哀。","骆宾王 幽系书情通简知己"],["汲冢宁详蠹，秦牢讵辨冤。","骆宾王 早秋出塞寄东台详正学士"]]},{"n":"三泉","d":"","s":"《史记》卷六〈秦始皇本纪〉～265～","w":"「秦二世葬始皇骊山。始皇初即位，穿治骊山，及并天下，天下徒送诣七十馀万人，穿三泉，下铜而致椁，宫观百官奇器珍怪徙藏满之正。」唐·张守节《史记正义》：「颜师古云：『三重之泉，言至水也而。』」","q":[["但见三泉下，金棺葬寒灰。","李白 古风"]]},{"n":"沙邱","d":"","s":"《史记》卷六《秦始皇本纪》","w":"「七月丙寅，始皇崩于沙丘平台。」唐·张守节《史记正义》「括地志云：『沙丘台在邢州平乡县东北二十里。又云平乡县东北四十里。』按：始皇崩在沙丘之宫，平台之中。邢州去京一千六百五十里。」","q":[["牢落沙丘终古恨，寂寥函谷万年春。","李咸用 喻道"],["若使威可以制，力可以止，则秦皇不肯敛手下沙丘，孟贲不合低头入蒿里。","罗隐 芳树"]]},{"n":"上林","d":"","s":"《三辅黄图》","w":"汉上林苑，即秦之旧苑也。汉书云武帝建元三年开上林苑。","q":[]},{"n":"射鲸","d":"","s":"《史记》卷六〈秦始皇本纪〉～263～","w":"方士徐韨等入海求神药，数岁不得，费多，恐谴，乃诈曰：「蓬莱药可得，然常为大鲛鱼所苦，故不得至，愿请善射与俱，见则以连弩射之。」始皇梦与海神战，如人状。问占梦，博士曰：「水神不可见，以大鱼蛟龙为候。今上祷祠备谨，而有此恶神，当除去，而善神可致…","q":[["连弩射海鱼，长鲸正崔嵬。鬐鬣蔽青天，何由睹蓬莱。","李白 古风之三"]]},{"n":"亡秦非胡","d":"","s":"《史记》卷六〈秦始皇本纪〉～252～","w":"因使韩终、侯公、石生求仙人不死之药。始皇巡北边，从上郡入。燕人卢生使入海还，以鬼神事，因奏录图书，曰：「亡秦者胡也」。始皇乃使将军蒙恬发兵三十万人北击胡，略取河南地。」南朝宋·裴骃《史记集解》：「郑玄：『胡，胡亥，秦二世名也。秦见图书，不知…","q":[["秦王筑城何太愚，天实亡秦非北胡。","王翰 饮马长城窟行"]]},{"n":"羡门","d":"","s":"《昭明文选》卷十九战国楚·宋玉《高唐赋》","w":"有方之士，羡门高溪。","q":[["徐福竟何成，羡门徒空言。","独孤及 观海"],["安期羡门辈，列侍如公卿。","白居易 梦仙"]]},{"n":"挟书","d":"","s":"《汉书》卷二《惠帝纪》","w":"「三月甲子，皇帝冠，赦天下。省法令妨吏民者；除挟书律。长乐宫鸿台灾。宜阳雨血。」东汉·应劭注：「挟，藏也。」三国魏·张晏注：「秦律敢有挟书者族。」","q":[["挟书秦二世，壤宅汉诸王。","李商隐 赠送前刘五经映三十韵"]]},{"n":"一炬阿房","d":"","s":"《史记》卷六〈秦始皇本纪〉～256～","w":"三十五年，除道，道九原抵云阳，堑山堙谷，直通之。于是始皇以为咸阳人多，先王之宫廷小，吾闻周文王都丰，武王都镐，丰镐之閒，帝王之都也。乃营作朝宫渭南上林苑中。先作前殿阿房，东西五百步，南北五十丈，上可以坐万人，下可以建五丈旗。周驰为阁道，自殿…","q":[]},{"n":"银海雁飞","d":"","s":"《汉书》卷三十六《楚元王传》","w":"秦始皇帝葬于骊山之阿，下锢三泉，上崇山坟，其高五十馀丈，周回五里有馀；石椁为游馆，人膏为灯烛，水银为江海，黄金为凫雁。","q":[["鼎湖龙去远，银海雁飞深。","杜甫 骊山"]]},{"n":"赭君山","d":"","s":"《史记》卷六《秦始皇本纪》","w":"二十八年，皇帝作始。端平法度，万物之纪。……齐人徐韨等上书，言海中有三神山，名曰蓬莱、方丈、瀛洲，仙人居之。请得斋戒，与童男女求之。于是遣徐韨发童男女数千人，入海求仙人。始皇还，过彭城，斋戒祷祠，欲出周鼎泗水。使千人没水求之，弗得。乃西南渡…","q":[["想赭君山日，秦皇怒赫然。","李群玉 洞庭风雨二首之一"]]},{"n":"追风骠","d":"","s":"晋·崔豹《古今注》卷中《鸟兽》","w":"秦始皇有七名马：一曰追风，二曰逐兔，三曰蹑影，四曰追电，五曰飞翮，六曰铜雀，七曰晨凫。","q":[["妻子山中哭向天，须公枥上追风骠。","杜甫 徒步归行"]]},{"n":"秦皇","d":"","s":"《史记》卷六〈秦始皇本纪〉～259～","w":"三十六年，荧惑守心。有坠星下东郡，至地为石，黔首或刻其石曰「始皇帝死而地分」。始皇闻之，遣御史逐问，莫服，尽取石旁居人诛之，因燔销其石。始皇不乐，使博士为仙真人诗，及行所游天下，传令乐人歌弦之。秋，使者从关东夜过华阴平舒道，有人持璧遮使者曰…","q":[["微生祖龙代，却思尧舜道。","古之奇 秦人谣"],["祖龙已深惑，汉氏远徇欲。","司马扎 感古"]]},{"n":"祖洲灵草","d":"","s":"《海内十洲记》","w":"祖洲，近在东海之中，地方五百里，去西岸七万里，上有不死之草。草形如菰，苗长三四尺。人已死三日者，以草覆之，皆当时活也。服之令人长生。昔秦始皇大苑中，多枉死者横道，有鸟状，衔此草覆死人面，当时起坐而自活也。有司闻奏，始皇遣使者赍草，以向北郭鬼…","q":[]}],"14":[{"n":"八斗才","d":"八斗才：喻有才之人。唐李商隐《可叹》：“宓妃愁坐芝田馆，用尽陈王八斗才。”","s":"《释常谈》卷中","w":"八斗之才：文章多，谓之八斗之才。谢灵运尝曰：「天下才有一石，曹子建独占八斗，我得一斗，天下共分一斗。」","q":[["宓妃愁坐芝田馆，用尽陈王八斗才。","李商隐 可叹"]]},{"n":"随珠","d":"","s":"《搜神记》卷二十","w":"隋县溠水侧，有断蛇邱。隋侯出行，见大蛇被伤，中断，疑其灵异，使人以药封之，蛇乃能走，因号其处断蛇邱。岁馀，蛇衔明珠以报之。珠盈径寸，纯白，而夜有光，明如月之照，可以烛室。故谓之「隋侯珠，」亦曰「灵蛇珠，」又曰「明月珠。」","q":[["有声真汉相，无颣胜隋珠。","刘禹锡 奉和吏部杨尚书太常李卿二相公策免后即事述怀赠答十韵"],["自握蛇珠辞白屋，欲凭鸡卜谒金门。","刘禹锡 送周鲁儒赴举诗"]]},{"n":"曹刘","d":"","s":"南朝梁·钟嵘《诗品·总论》","w":"昔曹刘殆文章之圣。陆谢为体贰之才。","q":[["曹刘俯仰惭大敌，沈谢逡巡称小儿。","任华 寄杜拾遗"],["曹刘不免死，谁敢负年华。","孟郊 招文士饮"]]},{"n":"曹植","d":"","s":"《三国志》卷十九《魏书·陈思王植传》","w":"陈思王植字子建。年十岁馀，诵读《诗》、《论》及辞赋数十万言，善属文。太祖尝视其文，谓植曰：「汝倩人邪？」植跪曰：「言出为论，下笔成章，顾当面试，柰何倩人？」时邺铜爵台新城，太祖悉将诸子登台，使各为赋。植援笔立成，可观，太祖甚异之。性简易，不…","q":[["还依北堂下，曹植动文雄。","李峤 萱"],["已忝归曹植，何知对李膺。","杜甫 赠特进汝阳王二十韵"]]},{"n":"曹谢","d":"","s":"唐韩愈《县斋有怀》","w":"事业窥 皋 稷 ，文章蔑 曹 谢 。","q":[]},{"n":"屠门嚼","d":"","s":"《昭明文选》卷四十二〈书中·与吴季重书〉～905～","w":"植白：季重足下。前日虽因常调，得为密坐，虽燕饮弥日，其于别远会稀，犹不尽其劳积也。若夫觞酌凌波于前，箫笳发音于后，足下鹰扬其体，凤叹虎视，谓萧曹不足俦，卫霍不足侔也。左顾右眄，谓若无人，岂非吾子壮志哉！过屠门而大嚼，虽不得肉，贵且快意。唐·…","q":[["高歌酒市非狂者，大嚼屠门亦偶然。","罗隐 黄鹤驿偶题"],["肯效屠门嚼，久嫌弋者篡。","韩愈 崔十六少府摄伊阳以诗及书见投因酬三十韵"]]},{"n":"陈思多忧","d":"","s":"《三国志》卷十九《魏书·陈思王植传》","w":"太和元年，徙封浚仪。二年，复还雍丘。植常自愤怨，抱利器而无所施，上疏求自试。","q":[["赵壹赋命薄，陈思多世忧。","李群玉 将之京国赠薛员外"],["陈王抗表日，毛遂请行秋。","窦常 求自试"]]},{"n":"陈王赋","d":"","s":"《三国志》卷十九《魏书·陈思王植传》","w":"陈思王植字子建。年十岁馀，诵读诗、论及辞赋数十万言，善属文。太祖尝视其文，谓植曰：「汝倩人邪？」植跪曰：「言出为论，下笔成章，顾当面试，柰何倩人？」时邺铜爵台新城，太祖悉将诸子登台，使各为赋。植援笔立成，可观，太祖甚异之。……以陈四县封植为…","q":[["赋掩陈王作，杯如洛水流。","王维 奉和圣制与太子诸王三月三日龙池春禊应制"],["曾被陈王识，遥知江上迎。","皎然 秋日送择高上人往江西谒曹王"]]},{"n":"凌波步","d":"洛川神：咏神仙或美女。唐孟浩然《和张二自稷县还途中遇雪》：“歌疑郢中客，态比洛川神。”","s":"《昭明文选》卷十九〈赋癸·情·洛神赋〉～896～","w":"黄初三年，余朝京师，还济洛川。古人有言，斯水之神，名曰宓妃。感宋玉对楚王神女之事，遂作斯赋。其辞曰：余从京域言归东藩。背伊阙，越轘辕。经通谷，陵景山。日既西倾，车殆马烦。尔乃税驾乎蘅皋，秣驷乎芝田。容与乎阳林，流眄乎洛川。于是精移神骇，忽焉…","q":[["未减行雨荆台下，自比凌波洛浦游。","上官仪 题画障"],["还似洛妃乘雾去，碧天无际水空流。","冷朝阳 送红线"]]},{"n":"陈王宴平乐","d":"","s":"《昭明文选》卷二十七、三国魏·曹子建（植）《名都篇》","w":"我归宴平乐，美酒斗十千。脍鲤臇胎虾，寒鳖炙熊蹯。鸣俦啸匹旅，列坐竟长筵。连翩击鞠壤，巧捷惟万端。白日西南驰，光景不可攀。云散还城邑，清晨复来还。","q":[["陈王昔时宴平乐，斗酒十千恣欢谑。","李白 将进酒"]]},{"n":"触罗","d":"","s":"《乐府诗集》卷三十九、三国魏·曹植《野田黄雀行》","w":"不见篱间雀，见鹞自投罗。","q":[["俱来海上叹烟波，君佩银鱼我触罗。","李群玉 留别马使君"]]},{"n":"心倾藿","d":"","s":"《昭明文选》卷三十七〈表上·求通亲亲表〉～687～","w":"臣伏自惟省，无锥刀之用。及观陛下之所拔授，若以臣为异姓，窃自料度，不后于朝士矣。若得辞远游，戴武弁，解朱组，佩青绂，驸马、奉车，趣得一号，安宅京室，执鞭珥笔，出从华盖，入侍辇毂，承答圣问，拾遗左右，乃臣丹诚之至愿，不离于梦想者也。远慕鹿鸣君…","q":[]},{"n":"煮豆","d":"七步咏：指人才思敏捷，才气过人。唐于志宁《冬日宴群公于宅各赋一字得杯》：“俱裁七步咏，同倾三雅杯。”；萁燃：喻兄弟相逼，或喻内部不和。清黄蜜来《寄怀昌大风》：“屐虽齿折诚何碍，吟到其燃未免猜。”","s":"《世说新语笺疏》上卷下〈文学〉～244～","w":"文帝（曹丕）尝令东阿王（曹植）七步中作诗，不成者行大法。应声便为诗曰：「煮豆持作羹，漉菽以为汁。萁在釜下然，豆在釜中泣。本自同根生，相煎何太急？」帝深有惭色。","q":[["俱裁七步咏，同倾三雅杯。","于志宁 冬日宴群公于宅各赋一字得杯"],["豆萁才敏俊，羽猎正峥嵘。","元稹 答姨兄胡灵之见寄五十韵"]]},{"n":"二仪","d":"","s":"《曹植集》卷三〈惟汉行〉","w":"太极定二仪，清浊始以形。","q":[["二仪含皎澈，万象共澄鲜。","刘禹锡 奉和中书崔舍人八月十五日夜玩月二十韵"],["浪驱三岛至，江拆二仪开。","薛逢 大水"]]},{"n":"冯夷击鼓","d":"","s":"《昭明文选》卷十九、三国魏·曹子健（植）《洛神赋》","w":"冯夷鸣鼓，女娲清歌。","q":[["此时骊龙亦吐珠，冯夷击鼓群龙趋。","杜甫 渼陂行（陂在鄠县西五里。周一十四里）"],["遂有冯夷来击鼓，始知嬴女善吹箫。","杜甫 玉台观"]]},{"n":"回雪","d":"","s":"《昭明文选》卷十九、三国魏·曹子健（植）《洛神赋》","w":"「髣?兮若轻云之蔽月，飘飖兮若流风之回雪。」","q":[["回雪舞萦盈，萦盈若回雪。","李群玉 赠回雪"],["燕赵能歌有几人，为花回雪似含颦。","杨知至 和李尚书命妓歌饯崔侍御"]]},{"n":"寄明珰","d":"","s":"《昭明文选》卷十九〈赋癸·情·洛神赋〉～898～","w":"于是忽焉纵体，以遨以嬉。左倚采旄，右荫桂旗。芳蔼，芳香晻蔼也。《楚辞》曰：建雄虹之采旄。又曰：辛夷车兮结桂旗。攘皓腕于神浒兮，采湍濑之玄芝。尔雅曰：岸上曰浒。郭璞曰：厓上地也。毛诗曰：在河之浒。毛苌曰：浒，水厓也。汉书音义，应劭曰：濑，水流…","q":[]},{"n":"解佩","d":"","s":"《昭明文选》卷十九、三国魏·曹子建（植）《洛神赋》","w":"余情悦其淑美兮，心振荡而不怡。无良媒以接欢兮，托微波而通辞。愿诚素之先达兮，解玉佩以要之。","q":[["惯是洛滨要解佩，本是河间好数钱。","上官仪 和太尉戏赠高阳公"]]},{"n":"惊鸿","d":"","s":"《昭明文选》卷十九、三国魏·曹子建（植）《洛神赋》","w":"「其形也，翩若惊鸿，婉若游龙。」唐·李善注：「边让《章华台赋》曰：体迅轻鸿，荣曜春华。」","q":[["彩笔谕戎矜倚马，华堂留客看惊鸿。","刘禹锡 酬窦员外郡斋宴客偶命柘枝因见寄兼呈张十一院长元九侍御"]]},{"n":"倾藿","d":"","s":"《昭明文选》卷三十七〈表上·求通亲亲表〉～687～","w":"臣伏自惟省，无锥刀之用。及观陛下之所拔授，若以臣为异姓，窃自料度，不后于朝士矣。若得辞远游，戴武弁，解朱组，佩青绂，驸马、奉车，趣得一号，安宅京室，执鞭珥笔，出从华盖，入侍辇毂，承答圣问，拾遗左右，乃臣丹诚之至愿，不离于梦想者也。远慕鹿鸣君…","q":[["自惊一何幸，太阳还及葵。","李元纮 奉和圣制送张说上集贤学士赐宴"],["复恐红颜坐销铄，可怜明月方照灼，向影倾身比葵藿。","李如璧 明月"]]},{"n":"宓妃留枕","d":"","s":"《昭明文选》卷十九、三国魏·曹子建（植）《洛神赋》","w":"唐·李善注引《汉书音义》：「如淳曰：宓妃，伏羲女，溺死洛水，遂为洛水之神。」《记》曰：「魏东阿王，汉末求甄逸女，既不遂。太祖回与五官中郎将。植殊不平，昼思夜想，废寝与食。黄初中入朝，帝示植甄后玉镂金带枕，植见之，不觉泣。时已为郭后谗死。帝意…","q":[["贾氏窥帘韩掾少，宓妃留枕魏王才。","李商隐 无题四首"]]},{"n":"宓妃腰","d":"","s":"《昭明文选》卷十九、三国魏·曹子建（植）《洛神赋》并《序》","w":"古人有言，斯水之神，名曰宓妃。感宋玉对楚王神女之事，遂作斯赋。其辞曰：……肩若削成，腰若约素。","q":[["宓妃腰细才胜露，赵后身轻欲倚风。","李商隐 蜂"]]},{"n":"南国佳人","d":"","s":"《昭明文选》卷二十九〈诗己·杂诗上·杂诗六首〉～364～","w":"南国有佳人，华容若桃李。朝游江北岸，日夕宿湘沚。时俗薄朱颜，谁为发皓齿。俛仰岁将暮，荣耀难久恃。","q":[["窦闺织妇惭诗句，南国佳人怨锦衾。","李绅 新楼诗二十首城上蔷薇"],["虚传南国貌，争奈五陵心。","杜牧 为人题赠二首"]]},{"n":"气如虹","d":"","s":"《昭明文选》卷三十四〈七上·七启八首〉～587～","w":"镜机子曰：「此乃游侠之徒耳，未足称妙也。若夫田文无忌之俦，乃上古之俊公子也。皆飞仁扬义，腾跃道艺。游心无方，抗志云际。凌轹诸侯，驱驰当世。挥袂则九野生风，慷慨则气成虹蜺。吾子若当此之时，能从我而友之乎？」玄微子曰：「子亮愿焉。然方于大道，有…","q":[["马蹄隐耳声隆隆，入门下马气如虹。","李贺 高轩过"]]},{"n":"天人","d":"","s":"《三国志》卷二十一《魏书·王粲传》","w":"「自颍川邯郸淳。」晋·裴松之注引《魏略》：「太祖遣淳诣植。植初得淳甚喜，延入坐，不先与谈。时天暑热，植因呼常从取水自澡讫，傅粉。遂科头拍袒，胡舞五椎锻，跳丸击剑，诵俳优小说数千言讫，谓淳曰：『邯郸生何如邪？』于是乃更著衣帻，整仪容，与淳评说…","q":[["画堂授傅姆，天人亲捧持。","杜牧 杜秋娘诗"],["汝阳让帝子，眉宇真天人。","杜甫 八哀诗赠太子太师汝阳郡王琎"]]},{"n":"同队鱼","d":"","s":"三国魏·曹植《曹植集》卷二《种葛篇》","w":"与君初婚时，结发恩义深。……昔为同池鱼，今为商与参。","q":[["少长聚嬉戏，不殊同队鱼。","韩愈 符读书城南（符。愈之子。城南。愈别墅。）"]]},{"n":"托微波","d":"","s":"《昭明文选》卷十九、三国魏·曹子建（植）《洛神赋》","w":"余情悦其淑美兮，心振荡而不怡。无良媒以接欢兮，托微波而通辞。","q":[["无由见颜色，还自托微波。","李商隐 离思"]]},{"n":"舞随曹植马","d":"","s":"《昭明文选》卷十九、三国魏·曹子建（植）《洛神赋》","w":"余从京域言归东藩。背伊阙，越轘辕。经通谷，陵景山。日既西倾，车殆马烦。尔乃……流眄乎洛川。于是精移神骇，忽焉思散。俯则未察，仰以殊观。睹一丽人，于岩之畔。……飘飖兮若流风之回雪。","q":[["欲舞定随曹植马，有情应湿谢庄衣。","李商隐 对雪二首之一"]]},{"n":"一发双连","d":"","s":"《曹植集》卷三〈名都篇〉","w":"斗鸡东郊道，走马长楸间，驰骋未及半，双兔过我前。揽弓捷鸣镝，长驱上南山。左挽因右发，一纵两禽发。","q":[["狡免初迷窟，纤骊讵著鞭。三驱仍百步，一发遂双连。那似陈王意，空随乐府篇。","薛存诚 御箭连中双兔"]]},{"n":"应图求马","d":"","s":"《艺文类聚》卷九十三","w":"魏陈王曹植《献文帝马表》曰：臣于先武皇帝世，得大宛紫骍马一疋，形法应图，善持头尾，教令习拜，今辄已能，又能行与鼓节相应，谨以奉献。","q":[["应图求骏马，惊代得麒麟。","杜甫 上韦左相二十韵"]]},{"n":"子建","d":"","s":"《三国志》卷十九〈魏书·陈思王植传〉～557～","w":"陈思王植字子建。年十岁馀，诵读诗、论及辞赋数十万言，善属文。太祖尝视其文，谓植曰：「汝倩人邪？」植跪曰：「言出为论，下笔成章，顾当面试，柰何倩人？」时邺铜爵台新城，太祖悉将诸子登台，使各为赋。植援笔立成，可观，太祖甚异之。","q":[["子建文笔壮，河间经术存。","杜甫 别李义"],["赋料扬雄敌，诗看子建亲。","杜甫 奉赠韦左丞丈二十二韵"]]},{"n":"子建才","d":"","s":"《三国志》卷十九〈魏书·陈思王植传〉～557～","w":"陈思王植字子建。年十岁馀，诵读诗、论及辞赋数十万言，善属文。太祖尝视其文，谓植曰：「汝倩人邪？」植跪曰：「言出为论，下笔成章，顾当面试，柰何倩人？」时邺铜爵台新城，太祖悉将诸子登台，使各为赋。植援笔立成，可观，太祖甚异之。性简易，不治威仪。…","q":[]}],"15":[{"n":"八凯","d":"","s":"《史记》卷一〈五帝本纪·帝舜〉～35～","w":"「昔高阳氏有才子八人，世得其利，谓之『八恺』。高辛氏有才子八人，世谓之『八元』。此十六族者，世济其美，不陨其名。至于尧，尧未能举。舜举八恺，使主后土，以揆百事，莫不时序。举八元，使布五教于四方，父义，母慈，兄友，弟恭，子孝，内平外成。」唐·…","q":[["谢太傅须同八凯，姚梁公可并三台。","贯休 蜀王入大慈寺听讲"],["人知八凯须当国，猿到三声不用愁。","贯休 送薛侍郎贬峡州司马"]]},{"n":"八族","d":"","s":"《史记》卷一《五帝本纪·舜本纪》","w":"「昔高阳氏有才子八人，世得其利，谓之『八恺』。高辛氏有才子八人，世谓之『八元』。此十六族者，世济其美，不陨其名。至于尧，尧未能举。舜举八恺，使主后土，以揆百事，莫不时序。举八元，使布五教于四方，父义，母慈，兄友，弟恭，子孝，内平外成。」唐·…","q":[["八族未来谁北拱，四凶犹在莫南巡。","罗隐 湘妃庙"]]},{"n":"湘夫人","d":"江娥啼竹：咏忧伤之情，或咏竹。唐李贺《李凭箜篌引》：“江娥啼竹素女愁，李凭中国弹箜篌。”","s":"《艺文类聚》卷八十九〈木部下·竹〉～55～","w":"《博物志》曰：洞庭之山，帝之二女啼，以涕挥竹，竹尽班。今下隽有班皮竹。","q":[["愁如湘灵哭湘浦，咽咽哀音隔云雾。九嶷深翠转巍峨，仙骨寒消不知处。","僧鸾 赠李粲秀才"],["河汉夜阑孤雁度，潇湘水阔二妃愁。","刘沧 江楼月夜闻笛"]]},{"n":"弼违","d":"","s":"《尚书·虞书·益稷谟》","w":"「帝曰：『臣作朕股肱耳目……予违汝弼，汝无面从，退有后言。』」旧题汉·孔安国传：「我违道，汝当以义辅正我。无得面从我违，而退后有言我不可弼。」","q":[["抗节衷无隐，同心尚弼违。","羊士谔 和武相早朝中书候传点书怀奉呈"]]},{"n":"辟四门聪","d":"","s":"《尚书·虞书·舜典》","w":"「舜格于文祖，询于四岳，辟四门，明四目，达四聪。」旧题汉·孔安国传：「开辟四方之门未开者，广致众贤。」「广视听于四方，使天下无壅塞。」","q":[["方巡五年狩，更辟四门聪。","孙逖 奉和御制登鸳鸯楼即目应制"]]},{"n":"湘灵鼓瑟","d":"","s":"《楚辞补注》卷五〈远游〉～72～","w":"览方外之荒忽兮，沛罔象而自浮。祝融戒而还衡兮，腾告鸾鸟迎宓妃。张《咸池》奏《承云》兮，二女御《九韶》歌使湘灵鼓瑟兮，令海若舞冯夷。玄螭虫象并出进兮，形蟉而逶蛇。雌蜺便娟增挠兮，鸾鸟轩翥而翔飞。音乐博衍无终极兮，焉乃逝俳佪。","q":[["鼓宜尧女瑟，荡必蔡姬舟。","吴融 御沟十六韵"],["遥知月落酒醒处，五十弦从波上来。","吴融 送荆南从事之岳州"]]},{"n":"击壤歌","d":"击壤歌：称颂帝王治国有方。南朝陈张正见《从籍田应衡阳王教作五章》之五：“幸承滥吹末，击壤自为歌。”","s":"《论衡校释》卷八〈艺增〉～388～","w":"论语曰：「大哉！尧之为君也，荡荡乎民无能名焉。」传曰：「有年五十击壤于路者，观者曰：『大哉！尧之德乎！』击壤者曰：『吾日出而作，日入而息，凿井而饮，耕田而食，尧何等力？』」此言荡荡无能名之效也。","q":[["击壤将何幸，裴回望九门。","崔枢 赐耆老布帛（一作张复元诗）"],["野洽如坻咏，途喧击壤讴。","李峤 晚秋喜雨"]]},{"n":"岂其苗裔","d":"重瞳：指舜或项羽，或指有帝王之相。唐李白《远别离》：“九疑联绵皆相似，重瞳孤坟竟何是？”","s":"《史记》卷七〈项羽本纪〉～338～","w":"太史公曰：吾闻之周生曰「舜目盖重瞳子」，又闻项羽亦重瞳子。羽岂其苗裔邪？何兴之暴也！南朝宋·裴骃《史记集解》引尸子曰：「舜两眸子，是谓重瞳。」","q":[["项岂重瞳圣，夔犹一足𨆪。","陆龟蒙 江南秋怀寄华阳山人"]]},{"n":"窜苗","d":"","s":"《尚书·虞书·舜典》","w":"窜三苗于三危。","q":[["窜苗犹有孽，戮负自贻辜。","许敬宗 奉和执契静三边应诏"]]},{"n":"稻粱谋","d":"","s":"《全唐诗》卷二百一十六〈同诸公登慈恩寺塔〉【案：原注。时高适。薛据先有此作。按寺乃高宗在东宫时为文德皇后立。故名慈恩。】","w":"高标跨苍天【高标跨苍穹】，烈风无时休。自非旷士怀【自非壮士怀】，登兹翻百忧。方知象教力，足可追冥搜【立可追冥搜】。仰穿龙蛇窟，始出枝撑幽【始惊枝撑幽】。七星在北户【七星在户北】，河汉声西流。羲和鞭白日，少昊行清秋。秦山忽破碎【泰山忽破碎】，…","q":[]},{"n":"都俞","d":"","s":"《尚书》卷五〈虞书·益稷〉～67～","w":"禹曰：「都，帝！慎乃在位。」帝曰：「俞。」禹曰：「安汝止，惟几惟康，其弼直；惟动丕应。徯志以昭受上帝，天其申命用休。」","q":[]},{"n":"咏康哉","d":"","s":"《尚书·虞书·益稷谟》","w":"「乃更为歌曰：『元首明哉，股肱良哉，庶事康哉！』」旧题汉·孔安国传：「帝歌归美股肱，义未足，故续歌『先君后臣，众事乃安』，以成其义。」","q":[["还闻股肱郡，元首咏康哉。","张九龄 奉和圣制早度蒲津关"],["圣道逍遥更何事，愿将巴曲赞康哉。","杨巨源 早朝"]]},{"n":"官水土","d":"","s":"《尚书》卷三〈虞书·舜典〉～44～","w":"伯禹作司空。帝曰：「俞，咨禹，汝平水土，惟时懋哉。」","q":[["削玉风姿官水土，黑头公自古来难。","韩偓 和王舍人抚州饮席赠韦司空"]]},{"n":"舜弦","d":"","s":"《史记》卷二十四〈乐书〉～97～","w":"昔者舜作五弦之琴，以歌南风；夔始作乐，以赏诸侯。故天子之为乐也，以赏诸侯之有德者也。德盛而教尊，五谷时孰，然后赏之以乐。故其治民劳者，其舞行级远；其治民佚者，其舞行级短。故观其舞而知其德，闻其谥而知其行。南朝宋·裴骃《史记集解》：「王肃曰：…","q":[["应是南风曲，声声不合今。","于武陵 匣中琴"],["湛露羞依草，南风耻带熏。","令狐楚 青云干吕"]]},{"n":"历山","d":"","s":"《尚书》卷四〈虞书·大禹谟〉～58～","w":"三旬，苗民逆命。益赞于禹曰：「惟德动天，无远弗届。满招损，谦受益，时乃天道。」帝初于历山，往于田，日号泣于旻天、于父母。负罪引慝，祗载见瞽瞍，夔夔斋慄，瞽亦允若；至诚感神，矧兹有苗。禹拜昌言曰：「俞！班师振旅。」帝乃诞敷文德，舞乾羽于两阶。…","q":[["沧海举歌夔是相，历山回禅舜为君。","曹唐 三年冬大礼五首"]]},{"n":"明四目","d":"","s":"《尚书·虞书·舜典》","w":"「舜格于文祖，询于四岳，辟四门，明四目，达四聪。」唐·孔颖达疏：「明四方之目，使为巳远视四方也。」","q":[["褰旒明四目，伏槛纡三顾。","王维 奉和圣制御春明楼临古相园亭赋乐贤诗应制"],["大君明四目，烛之洞秋毫。","舒元舆 坊州按狱"]]},{"n":"神母呈图","d":"","s":"《太平御览》卷八十一","w":"《雒书灵准听》曰：有人方面、日衡、重华、握石椎，怀神珠，舜受终，凤皇仪，黄龙感，朱草生，蓂荚孳，西王母受益地图。」《注》：「西王母得益地之图来献。」","q":[["献图开益地，张乐奏钧天。","张说 奉和圣制暇日与兄弟同游兴庆宫作应制"],["六龙日驭天行健，神母呈图地道光。","鲍溶 忆郊天"]]},{"n":"舜宾","d":"","s":"《尚书·虞书·舜典》","w":"「宾于四门，四门穆穆。」旧题汉·孔安国传：「四门，四方之门。舜流四凶族，四方诸侯来朝者，舜宾迎之，皆有美德，无凶人。」唐·孔颖达疏：「又命使宾迎诸侯于四门，而来入者穆穆然皆有美德，无凶人也。」","q":[["辟门通舜宾，比屋封尧德。","骆宾王 夏日游德州赠高四"]]},{"n":"舜耕","d":"","s":"《史记》卷一《五帝本纪·舜本纪》","w":"「舜，冀州之人也。舜耕历山，渔雷泽，陶河滨，作什器于寿丘，就时于负夏。舜父瞽叟顽，母嚚，弟象傲，皆欲杀舜。舜顺适不失子道，兄弟孝慈。欲杀，不可得；即求，尝在侧。」南朝宋·裴骃《史记集解》引东汉·郑玄曰：「在河东。」唐·张守节《史记正义》引《…","q":[["舜耕馀草木，禹凿旧山川。","杜审言 和李大夫嗣真奉使存抚河东"]]},{"n":"舜衣裳","d":"","s":"《太平御览》卷八十","w":"《谯子法训》曰：唐虞之衣裳文法，禹稷之沟洫耕稼，人至今被之。","q":[["无私天雨露，有截舜衣裳。","杜牧 奉和门下相公送西川相公兼领相印出镇全蜀诗十八韵"],["平生五色线，愿补舜衣裳。","杜牧 郡斋独酌"]]},{"n":"舜禹让旒","d":"","s":"《史记》卷一《五帝本纪·舜本纪》","w":"子商均亦不肖，舜乃豫荐禹于天。十七年而崩。三年丧毕，禹亦乃让舜子，如舜让尧子。诸侯归之，然后禹践天子位。","q":[["伊皋争负鼎，舜禹让垂旒。","徐夤 依御史温飞卿华清宫二十二韵"]]},{"n":"舜蹠之分","d":"","s":"《孟子注疏》卷十三下〈尽心章句上〉～239～","w":"孟子曰。鸡鸣而起。孳孳为善者。舜之徒也。鸡鸣而起。孳孳为利者。蹠之徒也。欲知舜与蹠之分。无他。利与善之间也。","q":[]},{"n":"舜目重瞳","d":"","s":"《淮南子》卷十九《脩务训》","w":"舜二瞳子，是谓重明，作事成法，出言成章。","q":[["黄帝有四目，帝舜重其明。今天只两目，何故许食使偏盲。","韩愈 月蚀诗效玉川子作"]]},{"n":"御魑魅","d":"","s":"《春秋左传·文公十八年》","w":"「舜臣尧，宾于四门，流四凶族。浑敦、穷奇、梼杌、饕餮，投诸四裔，以御螭魅。」晋·杜预注：「投，弃也。裔，远也。放之四远，使当螭魅之灾。螭魅，山林异气所生，为人害者。」","q":[["金榜荣名俱失尽，病身为庶更投魑。","刘言史 偶题二首之一"],["从来御魑魅，多为才名误。","杜甫 有怀台州郑十八司户"]]},{"n":"四罪","d":"","s":"《尚书·虞书·尧典》","w":"流共工于幽洲，放驩兜于崇山，?三苖于三危，殛鲧于羽山，四罪而天下咸服。","q":[["不知四罪地，岂有再起辰。","韩愈 赠别元十八协律六首（元十八集虚见白乐天集桂林伯桂管观察使裴行立也）"]]},{"n":"万机","d":"","s":"《尚书·虞书·皋陶谟》","w":"「亡敖佚欲有国，兢兢业业，一日二日万机。」旧题汉·孔安国传：「几，微也。言当戒惧万事之微。」","q":[["时此万机暇，适与佳节并。","李适 重阳日赐宴曲江亭赋六韵诗用清字"]]},{"n":"无为","d":"","s":"《论语注疏·卫灵公》～37～","w":"子曰：「无为而治者其舜也与？夫何为哉？恭己正南面而已矣。」","q":[["谩倚无为日，还成不偶人。","许棠 陈情献江西李常侍五首"]]},{"n":"向重华诉","d":"","s":"《楚辞补注》卷一〈离骚经·王逸序〉～5～","w":"固时俗之工巧兮，偭规矩而改错。背绳墨以追曲兮，竞周容以为度。忳郁邑余侘傺兮，吾独穷困乎此时也。宁溘死以流亡兮，余不忍为此态也。鸷鸟之不群兮，自前世而固然。何方圜之能周兮，夫孰异道而相安。屈心而抑志兮，忍尤而攘诟。伏清白以死直兮，固前圣之所厚…","q":[]},{"n":"鸟耘","d":"","s":"东汉·王充《论衡》卷四《书虚》","w":"传书言：舜葬于苍梧，象为之耕；禹葬会稽，鸟为之田。盖以圣德所致，天使鸟兽报祐之也。世莫不然。如考实之，殆虚言也。夫舜、禹之德，不能过尧。尧葬于冀州，或言葬于崇山。冀州鸟兽不耕，而鸟兽独为舜、禹耕，何天恩之偏駮也？或曰：「舜、禹治水，不得宁处…","q":[["万方同象鸟，举恸满秋尘。","李商隐 昭肃皇帝挽歌辞三首之三"]]},{"n":"养十六相","d":"","s":"《春秋左传正义》卷二十〈文公·传七年〉～352～","w":"昔高阳氏有才子八人：苍舒、隤敱、梼戭、大临、尨降、庭坚、仲容、叔达、齐圣广渊，明允笃诚，天下之民，谓之八恺。高辛氏有才子八人：伯奋、仲堪、叔献、季仲、伯虎、仲熊、叔豹、季狸、忠肃共懿，宣慈惠和，天下之民，谓之八元。此十六族也，世济其美，不陨…","q":[["舜举能，身尊道何高。","杜甫 述古三首"]]},{"n":"岳牧","d":"","s":"《尚书·周书·周官》","w":"「唐虞稽古，建官惟百，内有百揆四岳，外有州牧侯伯。」旧题汉·孔安国传：「外置州牧十二，及五国之长。」唐·孔颖达疏：「四岳，内典四时之政，外主太岳之事，立四人也。外有州牧侯伯，牧，一州之长，侯伯，五国之长，各监其所部之国。」","q":[["幽燕通使者，岳牧用词人。","杜甫 送陵州路使君赴任"]]}],"16":[{"n":"阿连","d":"阿连：指兄弟。唐白居易《将归渭村先寄舍弟》：“为报阿连寒食下，与吾酿酒扫柴扉。”","s":"《宋书》卷六十七《谢灵运传》","w":"灵运既东还，与族弟惠连、东海何长瑜、颍川荀雍、泰山羊璿之，以文章赏会，共为山泽之游，时人谓之四友。惠连幼有才悟，而轻薄不为父方明所知。灵运去永嘉还始宁，时方明为会稽郡。灵运尝自始宁至会稽造方明，过视惠连，大相知赏。时长瑜教惠连读书，亦在郡内…","q":[["青门望离袂，魂为阿连销。","权德舆 送少清赴润州参军因思练旧居"],["贮之玉合才半饼，寄与阿连题数行。","卢纶 新茶咏寄上西川相公二十三舅大夫二十舅"]]},{"n":"比谢游","d":"","s":"《昭明文选》卷二十二南朝宋·谢灵运《登池上楼》","w":"潜虬媚幽姿，飞鸿响远音。薄霄愧云浮，栖川怍渊沈。进德智所拙，退耕力不任。徇禄反穷海，卧痾对空林。倾耳聆波澜，举目眺岖嵚。初景革绪风，新阳改故阴。池塘生春草，园柳变鸣禽。祁祁伤豳歌，萋萋感楚吟。","q":[["赋因王阁笔，思比谢游疏。","贾岛 登楼"]]},{"n":"池塘草","d":"梦惠连：指创作诗文有神来之笔。唐李白《书情寄从弟邢州长史昭》：“昨梦见惠连，朝吟谢公诗。”","s":"《全上古三代秦汉三国六朝文·全梁文》卷五十五〈钟嵘·诗品中〉～3278～","w":"宋法曹参军谢惠连诗，小谢才思富捷，恨其兰玉夙凋，故长辔未骋。秋怀捣衣之作，虽复灵运锐思，亦何以加焉？又工为绮丽歌谣，风人第一。《谢氏家录》云：「康乐每对惠连，辄得佳语。后在永嘉西堂思诗，竟日不就。寤寐间，忽见惠连，即成『池塘生春草』。故常云…","q":[["惯识江南春早处，长惊蓟北梦回时。谢家园里成吟久，只欠池塘一句诗。","吴融 莺"],["随梦入池塘，无心在金谷。","唐彦谦 春草"]]},{"n":"曹谢","d":"","s":"唐韩愈《县斋有怀》","w":"事业窥 皋 稷 ，文章蔑 曹 谢 。","q":[]},{"n":"陆谢","d":"","s":"南朝梁钟嵘《诗品·总论》","w":"昔 曹 刘 殆文章之圣， 陆 谢 为体贰之才。","q":[]},{"n":"临海作","d":"","s":"《宋书》卷六十七《谢灵运传》","w":"灵运既东还，与族弟惠连、东海何长瑜、颍川荀雍、泰山羊璿之，以文章赏会，共为山泽之游，时人谓之四友。","q":[["别后遥传临海作，可见羊何共和之。","李白 赠从弟南平太守之遥二首"],["初发强中作，题诗与惠连。","李白 送二季之江东"]]},{"n":"大谢","d":"","s":"《诗品》卷上〈宋临川太守谢灵运〉","w":"其源出于陈思，杂有景阳之体。故尚巧似，而逸荡过之。颇以繁富为累。嵘谓若人兴多才高，寓目辄书，内无乏思，外无遗物，其繁富，宜哉！然名章迥句，处处閒起，丽典新声，络绎奔会。譬犹青松之拔灌木；白玉之映尘沙，未足贬其高洁也。","q":[["有时鬼笑两三声，疑是大谢小谢李白来。","贯休 山中作"],["小谢清高大谢才，圣君令泰此方来。","贯休 归东阳临岐上杜使君七首"]]},{"n":"登山屐","d":"谢公屐：咏游山玩水。唐李白《梦游天姥吟留别》：“脚著谢公屐，身登青云梯。”","s":"《宋书》卷六十七〈谢灵运列传〉～775～","w":"灵运因父祖之资，生业甚厚。奴僮既众，义故门生数百，凿山浚湖，功役无已。寻山陟岭，必造幽峻，岩嶂千重，莫不备尽。登蹑常著木履，上山则去前齿，下山去其后齿。尝自始宁南山伐木开径，直至临海，从者数百人。临海太守王琇惊骇，谓为山贼，徐知是灵运乃安。…","q":[["雪里登山屐，林间漉酒巾。","朱放 经故贺宾各镜湖道士观"],["谢屐缘危磴，戎装逗远村。","李敬方 题黄山汤院"]]},{"n":"济江篇","d":"","s":"《昭明文选》卷二十五南朝宋·谢灵运《酬从弟惠连》","w":"倾想迟嘉音，果枉济江篇。","q":[["济江篇已出，书府俸犹贫。","耿湋 送郭正字归郢上"],["归来莫忘此，兼示济江篇。","高适 秦中送李九赴城"]]},{"n":"谢康乐","d":"","s":"《宋书》卷六十七《谢灵运传》","w":"谢灵运，陈郡阳夏人也。祖玄，晋车骑将军。父瑍，生而不慧，为秘书郎，蚤亡。灵运幼便颖悟，玄甚异之，谓亲知曰：「我乃生瑍，瑍那得生灵运！」灵运少好学，博览群书，文章之美，江左莫逮。从叔混特知爱之。袭封康乐公，食邑二千户。以国公例，除员外散骑侍郎…","q":[["诗想怀康乐，文应吊子胥。","储嗣宗 得越中书"],["遂使康乐侯，披榛著双屐。","刘长卿 奉陪萧使君入鲍达洞寻灵山寺"]]},{"n":"客儿","d":"","s":"南朝梁·钟嵘《诗品》卷上","w":"宋临川太守谢灵运诗，其源出于陈思，杂有景阳之体。故尚巧似，而逸荡过之，颇以繁芜为累。嵘谓若人兴多，才高博，寓目辄书，内无乏思，外无遗物，其繁富宜哉。然名章迥句，处处閒起，丽典新声，络绎奔会，譬犹青松之拔灌木，白玉之映尘沙，未足贬其高洁也。初…","q":[["何独谢客游，当为远公辈。","刘长卿 早春赠别赵居士还江左时长卿下第归嵩阳旧居"],["陈蕃悬榻待，谢客枉帆过。","刘长卿 送李校书适越谒杜中丞"]]},{"n":"两谢","d":"","s":"《宋书》卷六十七〈谢灵运列传〉～743～","w":"祖伐长安，骠骑将军道怜居守，版为咨议参军，转中书侍郎，又为世子中军咨议，黄门侍郎。奉使慰劳高祖于彭城，作撰征赋。……少帝即位，权在大臣，灵运构扇异同，非毁执政，司徒徐羡之等患之，出为永嘉太守。郡有名山水，灵运素所爱好，出守既不得志，遂肆意游…","q":[["孰知二谢将能事，颇学阴何苦用心。","杜甫 解闷十二首"]]},{"n":"两谢","d":"","s":"《宋书》卷五十六〈谢瞻列传〉～558～","w":"瞻善于文章，辞采之美，与族叔混、族弟灵运相抗。","q":[]},{"n":"谢临川","d":"","s":"《宋书》卷六十七〈谢灵运列传〉～777～","w":"太祖知其见诬，不罪也。不欲使东归，以为临川内史，加秩中二千石，[五九]在郡游放，不异永嘉，为有司所纠。","q":[["归共临川史，同翻贝叶文。","刘长卿 送方补上人之常州依萧使君"],["佳句已齐康宝月，清谈远指谢临川。","权德舆 送清洨上人谒信州陆员外"]]},{"n":"谢公","d":"","s":"《宋书》卷六十七《谢灵运传》","w":"灵运少好学，博览群书，文章之美，江左莫逮。从叔混特知爱之。袭封康乐公，食邑二千户。……起为散骑常侍，转太子左卫率。灵运为性褊激，多愆礼度，朝廷唯以文义处之，不以应实相许。自谓才能宜参权要，既不见知，常怀愤愤。庐陵王义真少好文籍，与灵运情款异…","q":[["独卧不成寐，苍然想谢公。","丘丹 秋丹宿石门馆"],["谢公秋思渺天涯，蜡屐登高为菊花。","令狐楚 奉和严司空重阳日同崔常侍崔郎及诸公登龙山落帽台佳宴"]]},{"n":"灵运曲笠","d":"","s":"《世说新语》上卷上《言语》","w":"「谢灵运好戴曲柄笠，孔隐士谓曰：『卿欲希心高远，何不能遗曲盖之貌？』谢答曰：『将不畏影者，未能忘怀。』」南朝梁·刘孝标注引《庄子》云：「渔父谓孔子曰：『人有畏影恶迹而去之走者，举足逾数而迹逾多，走逾疾而影不离，自以尚迟，疾走不休，绝力而死。…","q":[["灵运曲笠，林宗折巾。","李瀚 蒙求"]]},{"n":"始宁墅","d":"始宁墅：指归隐之所。唐皇甫冉《曾东游以诗寄之》：“迢迢始宁墅，芜没谢公宅。”","s":"《宋书》卷六十七〈谢灵运列传〉～754～","w":"灵运父祖并葬始宁县，并有故宅及墅，遂移籍会稽，修营别业，傍山带江，尽幽居之美。与隐士王弘之、孔淳之等纵放为娱，有终焉之志。","q":[["知君始宁隐，还缉旧荷裳。","戴叔伦 和河南罗主簿送校书兄归江南"],["迢迢始宁墅，芜没谢公宅，","皇甫冉 曾东游以诗寄之"]]},{"n":"陶谢","d":"","s":"《宋书》卷九十三〈隐逸列传·陶潜〉～2287～","w":"亲老家贫，起为州祭酒，不堪吏职，少日，自解归。州召主簿，不就。躬耕自资，遂抱羸疾，复为镇军、建威参军，谓亲朋曰：「聊欲弦歌，以为三径之资，可乎？」执事者闻之，以为彭泽令。公田悉令吏种秫稻，妻子固请种，乃使二顷五十亩种秫，五十亩种。郡遣督…","q":[["喜于风骚地，忽见陶谢手。","李群玉 赠方处士兼以写别"],["新诗山水思，静入陶谢格。","李群玉 送郑子宽弃官东游便归女几"]]},{"n":"谢公船","d":"","s":"《昭明文选》卷二十六南朝宋·谢灵运《富春渚》","w":"宵济渔浦潭，旦及富春郭。定山缅云雾，赤亭无淹薄。溯流触惊急，临圻阻参错。","q":[["明朝富春渚，应见谢公船。","皎然 送陆判官归杭州"]]},{"n":"谢公赏","d":"","s":"《昭明文选》卷二十六南朝宋·谢灵运《入彭蠡湖口》","w":"「攀崖照石镜，牵叶入松门。」唐·李善注：「张僧鉴《浔阳记》曰：石镜山东，有一圆石，悬崖明净，照人见形。」","q":[["早回谢公赏，今遇樵夫说。","鲍溶 庐山石镜"]]},{"n":"谢宅","d":"","s":"《宋书》卷六十七《谢灵运传》","w":"灵运父祖并葬始宁县，并有故宅及墅，遂移籍会稽，修营别业，傍山带江，尽幽居之美。与隐士王弘之、孔淳之等纵放为娱，有终焉之志。……作《山居赋》并自注，以言其事。曰：「……水草则萍藻蕴菼，雚蒲芹荪，蒹菰蘋蘩，蕝荇菱莲。虽备物之偕美，独扶渠之华鲜。…","q":[["旧阴依谢宅，新艳出萧墙。","常衮 咏冬瑰花"],["谢家门馆似山林，碧石青苔满树阴。","李端 题元注林园"]]},{"n":"谢家楼","d":"","s":"《昭明文选》卷二十二南朝宋·谢灵运《登池上楼》","w":"初景革绪风，新阳改故阴。池塘生春草，园柳变鸣禽。祁祁伤豳歌，萋萋感楚吟。","q":[["游客见时心自醉，无因得见谢家楼。","姚合 杨柳枝词五首之一"],["堤暖柳丝斜，风光属谢家。","杨巨源 春日有赠"]]},{"n":"谢家兄弟","d":"","s":"《宋书》卷五十三《谢方明传》附《谢惠连传》","w":"子惠连，幼而聪敏，年十岁，能属文，族兄灵运深相知赏，事在灵运传。","q":[["友朋汉相府，兄弟谢家诗。","耿湋 春日书情寄元校书伯和相国元子"],["人日春风绽早梅，谢家兄弟看花来。","鲍防 人日陪宣州范中丞传正与范侍御传真宴东峰亭"]]},{"n":"谢监","d":"","s":"《宋书》卷六十七《谢灵运传》","w":"太祖登祚，诛徐羡之等，徵为秘书监，再召不起，上使光禄大夫范泰与灵运书敦奖之，乃出就职。使整理秘阁书，补足遗阙。","q":[["幕中邀谢鉴，麾下得周郎。","杨巨源 上刘侍中"],["谢监营野墅，陶公爱吾庐。","杨巨源 和卢谏议朝回书情即事寄两省阁老兼呈二起居谏院诸院长"]]},{"n":"颜谢","d":"","s":"《宋书》卷七十三《颜延之传》","w":"延之与陈郡谢灵运俱以词彩齐名，自潘岳、陆机之后，文士莫及也，江左称颜、谢焉。所著并传于世。","q":[["颜谢徵文并，钟裴直事同。","司空曙 奉和常舍人晚秋集贤院即事寄徐薛二侍郎"],["世业大小礼，近通颜谢诗。","戴叔伦 抚州对事后送外生宋垓归饶州觐侍呈上姊夫"]]},{"n":"羊何","d":"","s":"《昭明文选》卷二十五〈诗丁·赠答三·登临海峤与从弟惠连〉～98～","w":"登临海峤初发彊中作与从弟惠连见羊何共和之","q":[["别后遥传临海作，可见羊何共和之。","李白 赠从弟南平太守之遥二首"]]},{"n":"永嘉游","d":"","s":"《宋书》卷六十七《谢灵运传》","w":"少帝即位，权在大臣，灵运构扇异同，非毁执政，司徒徐羡之等患之，出为永嘉太守。郡有名山水，灵运素所爱好。出守既不得志，遂肆意游遨，遍历诸县，动踰旬朔。理人听讼，不复关怀，所至辄为诗咏以致其意。","q":[["康乐上官去，永嘉游石门。江中有孤屿，千载迹犹存。我来游秋浦兴与谢公合，文因周子论。","李白 与周刚清溪玉镜潭宴别（潭在秋浦桃树陂下。余新名此潭）"]]},{"n":"沈谢","d":"","s":"《宋书》卷六十七《谢灵运传》","w":"谢灵运，陈郡阳夏人也。祖玄，晋车骑将军。父瑍，生而不慧，为秘书郎，蚤亡。灵运幼便颖悟，玄甚异之，谓亲知曰：「我乃生瑍，瑍那得生灵运！」灵运少好学，博览群书，文章之美，江左莫逮。从叔混特知爱之。袭封康乐公，食邑二千户。以国公例，除员外散骑侍郎…","q":[["曹刘俯仰惭大敌，沈谢逡巡称小儿。","任华 寄杜拾遗"],["新文生沈谢，异骨降松乔。","杜甫 哭王彭州抡"]]}],"17":[{"n":"拔帜","d":"拔帜：指在战争中战胜对手，据有其地。南朝陈张正见《赋得韩信诗》：“沉沙壅急水，拔帜上危城。”","s":"《史记》卷九十二《淮阴侯列传》","w":"信所出奇兵二千骑，共候赵空壁逐利，则驰入赵壁，皆拔赵旗，立汉赤帜二千。赵军已不胜，不能得信等，欲还归壁，壁皆汉赤帜，而大惊，以为汉皆已得赵王将矣，兵遂乱，遁走，赵将虽斩之，不能禁也。于是汉兵夹击，大破虏赵军，斩成安君泜水上，禽赵王歇。","q":[["或为拔帜走，或遭劘垒还。","皮日休 鲁望昨以五百言见贻过有褒美内揣庸陋弥增愧悚因成一千言上述吾唐文物之盛次叙相得之欢亦迭和之微旨也"]]},{"n":"追亡","d":"","s":"《史记》卷九十二〈淮阴侯列传〉～26～","w":"信数与萧何语，何奇之。至南郑，诸将行道亡者数十人，信度何等已数言上，上不我用，即亡。何闻信亡，不及以闻，自追之。人有言上曰：「丞相何亡。」上大怒，如失左右手。居一二日，何来谒上，上且怒且喜，骂何曰：「若亡，何也？」何曰：「臣不敢亡也，臣追亡…","q":[["公议今如此，登坛到即行。","姚合 赠卢大夫将军"],["儒有登坛贵，何人得此功。","姚合 送郑尚书赴兴元"]]},{"n":"背河一战","d":"背河一战：指用兵奇谋。唐王季友《古塞曲》：“日落沙尘昏，背河可一战。”","s":"《史记》卷九十二《淮阴侯列传》","w":"信乃使万人先行，出，背水陈。赵军望见而大笑。平旦，信建大将之旗鼓，鼓行出井陉口，赵开壁击之，大战良久。于是信、张耳详弃鼓旗，走水上军。水上军开入之，复疾战。赵果空壁争汉鼓旗，逐韩信、张耳。韩信、张耳已入水上军，军皆殊死战，不可败。信所出奇兵…","q":[["登山麾武节，背水纵神兵。","李世民 还陕述怀"],["日落沙尘昏，背河更一战。","王季友 古塞曲"]]},{"n":"长乐宫中一叹","d":"","s":"《史记》卷九十二〈淮阴侯列传〉～2628～","w":"信乃谋与家臣夜诈诏赦诸官徒奴，欲发以袭吕后、太子。部署已定，待豨报。其舍人得罪于信，信囚，欲杀之。舍人弟上变，告信欲反状于吕后。吕后欲召，恐其党不就，乃与萧相国谋，诈令人从上所来，言豨已得死，列侯群臣皆贺。相国绐信曰：「虽疾，彊入贺。」信入…","q":[]},{"n":"成萧何败萧何","d":"","s":"《容斋随笔·容斋续笔》卷八〈萧何绐韩信〉～32～","w":"黥布为其臣贲赫告反，高祖以语萧相国，相国曰：「布不宜有此，恐仇怨妄诬之，请系赫，使人微验淮南。」布遂反。韩信为人告反，吕后欲召，恐其不就，乃与萧相国谋，诈令人称陈豨已破，绐信曰：「虽病强入贺。」信入，即被诛。信之为大将军，实萧何所荐，今其死…","q":[]},{"n":"出胯下","d":"","s":"《史记》卷九十二〈淮阴侯列传〉～260～","w":"淮阴屠中少年有侮信者，曰：「若虽长大，好带刀剑，中情怯耳。」众辱之曰：「信能死，刺我；不能死，出我裤下。」于是信孰视之，俛出裤下，蒲伏。一市人皆笑信，以为怯。","q":[]},{"n":"一饭恩","d":"一饭恩：指困厄之中受人救助。唐李群玉《病起别主人》：“益愧千金少，情将一饭殊。”；漂母：喻施恩之人。晋陶潜《乞食》：“感子漂母惠，愧我非韩才。”","s":"《史记》卷九十二《淮阴侯列传》","w":"信钓于城下，诸母漂，有一母见信饥，饭信，竟漂数十日。信喜，谓漂母曰：「吾必有以重报母。」母怒曰：「大丈夫不能自食，吾哀王孙而进食，岂望报乎！」……信至国，召所从食漂母，赐千金。","q":[["漂母乡非远，王孙道岂沉。","张祜 宿淮阴水馆"],["曹卿礼公子，楚媪馈王孙。","张说 南中别王陵成崇"]]},{"n":"缚楚王","d":"","s":"《史记》卷九十二《淮阴侯列传》","w":"人有上书告楚王信反。高帝以陈平计，天子巡狩会诸侯，南方有云梦，发使告诸侯会陈：「吾将游云梦。」实欲袭信，信弗知。高祖且至楚，信欲发兵反，自度无罪，欲谒上，恐见禽。人或说信曰：「斩眛谒上，上必喜，无患。」信见眛计事。眛曰：「汉所以不击取楚，以…","q":[["日旗龙旆想飘扬，一索功高缚楚王。","杜牧 云梦泽"]]},{"n":"韩白","d":"","s":"《梁书》卷一《武帝纪上》","w":"高祖谓诸将曰：「荆州本畏襄阳人；加唇亡齿寒，自有伤弦之急，宁不闇同邪？我若总荆、雍之兵，扫定东夏，韩、白重出，不能为计。况以无算之昏主，役御刀应敕之徒哉？我能使山阳至荆，便即授首，诸君试观何如。」","q":[["伊夔事业扶千载，韩白机谋冠九州。","罗隐 钱尚父生日"]]},{"n":"韩侯出井陉","d":"","s":"《史记》卷九十二〈淮阴侯列传〉～266～","w":"韩信使人閒视，知其不用，还报，则大喜，乃敢引兵遂下。未至井陉口三十里，止舍。夜半传发，选轻骑二千人，人持一赤帜，从閒道蓖山而望赵军，诫曰：「赵见我走，必空壁逐我，若疾入赵壁，拔赵帜，立汉赤帜。」令其裨将传飧，曰：「今日破赵会食！」诸将皆莫信…","q":[]},{"n":"韩彭","d":"","s":"《昭明文选》卷四十一汉·李少卿（陵）《答苏武书》","w":"「昔萧樊囚絷，韩彭菹醢。」唐·李善注：「《史记》曰：『彭越反，高祖赦之，迁处蜀道，著青衣，行至郑，逢吕后从长安来，越泣曰：愿处故昌邑。后许诺。既至，白上曰：彭越，壮士也，今徙蜀，自遗患，不如诛之。令其舍人告越反，遂夷三族。』《黥布传》：『薛…","q":[["战败仍树勋，韩彭但空老。","刘长卿 从军六首之五"],["苍生属伊吕，明主仗韩彭。","刘长卿 至德三年春正月时谬蒙差摄海盐令闻王师收二京因书事寄上浙节度李侍郎中丞行营五十韵"]]},{"n":"韩信羞比灌","d":"","s":"《史记》卷九十二《淮阴侯列传》","w":"遂械系信。至雒阳，赦信罪，以为淮阴侯。信知汉王畏恶其能，常称病不朝从。信由此日夜怨望，居常鞅鞅，羞与绛、灌等列。","q":[["韩信羞将绛灌比，祢衡耻逐屠沽儿。","李白 答王十二寒夜独酌有怀"]]},{"n":"三杰","d":"","s":"《史记》卷八〈高祖本纪〉～380～","w":"高祖置酒雒阳南宫。高祖曰：「列侯诸将无敢隐朕，皆言其情。吾所以有天下者何？项氏之所以失天下者何？」高起、王陵对曰：「陛下慢而侮人，项羽仁而爱人。然陛下使人攻城略地，所降下者因以予之，与天下同利也。项羽妒贤嫉能，有功者害之，贤者疑之，战胜而不…","q":[["三贤事汉灭暴强，四贤镇岳宁边徼。","元稹 五弦弹"],["丰野光三杰，妫庭赞五臣。","任希古 和左仆射燕公春日端居述怀"]]},{"n":"淮笑韩信","d":"","s":"《史记》卷九十二《淮阴侯列传》","w":"淮阴侯韩信者，淮阴人也。始为布衣时，贫无行，不得推择为吏，又不能治生商贾，常从人寄食饮，人多厌之者，常数从其下乡南昌亭长寄食，数月，亭长妻患之，乃晨炊蓐食。食时信往，不为具食。信亦知其意，怒，竟绝去。信钓于城下，诸母漂，有一母见信饥，饭信，…","q":[["秦地谬为门下客，淮阴徒笑市中人。","崔峒 赠元秘书"],["淮阴不免恶少辱，阮生亦作穷途悲。","戴叔伦 行路难"]]},{"n":"淮阴侯","d":"","s":"《史记》卷九十二《淮阴侯列传》","w":"淮阴侯韩信者，淮阴人也。始为布衣时，贫无行，不得推择为吏，又不能治生商贾，常从人寄食饮，人多厌之者，常数从其下乡南昌亭长寄食，数月，亭长妻患之，乃晨炊蓐食。食时信往，不为具食。信亦知其意，怒，竟绝去。信钓于城下，诸母漂，有一母见信饥，饭信，…","q":[["闲吟一寄清朝侣，未必淮阴不拜侯。","薛能 暇日寓怀寄朝中亲友"]]},{"n":"蹑足封王","d":"","s":"《史记》卷九十二〈淮阴侯列传〉～262～","w":"汉四年，遂皆降平齐。使人言汉王曰：「齐伪诈多变，反覆之国也，南边楚，不为假王以镇之，其势不定。愿为假王便。」当是时，楚方急围汉王于荥阳，韩信使者至，发书，汉王大怒，骂曰：「吾困于此，旦暮望若来佐我，乃欲自立为王！」张良、陈平蹑汉王足，因附耳…","q":[]},{"n":"假王徼福","d":"","s":"《史记》卷九十二《淮阴侯列传》","w":"汉四年，遂皆降平齐。使人言汉王曰：「齐伪诈多变，反覆之国也，南边楚，不为假王以镇之，其势不定。愿为假王便。」当是时，楚方急围汉王于荥阳，韩信使者至，发书，汉王大怒，骂曰：「吾困于此，旦暮望若来佐我，乃欲自立为王！」","q":[["英主任贤增虎翼，假王徼福犯龙鳞。","李绅 却过淮阴吊韩信庙"]]},{"n":"解衣","d":"","s":"《史记》卷九十二《淮阴侯列传》","w":"汉四年，遂皆降平齐。使人言汉王曰：「齐伪诈多变，反覆之国也，南边楚，不为假王以镇之，其势不定。愿为假王便。」当是时，楚方急围汉王于荥阳，韩信使者至，发书，汉王大怒，骂曰：「吾困于此，旦暮望若来佐我，乃欲自立为王！」张良、陈平蹑汉王足，因附耳…","q":[["解衣延宠命，横剑总威名。","李适 奉和幸望春宫送朔方军大总管张仁亶"],["推食天厨至，投醪御酒传。","萧至忠 送张亶赴朔方应制"]]},{"n":"精兵处","d":"","s":"《史记》卷九十二《淮阴侯列传》","w":"陈豨拜为钜鹿守，辞于淮阴侯。淮阴侯挈其手，辟左右与之步于庭，仰天叹曰：「子可与言乎？欲与子有言也。」豨曰：「唯将军令之。」淮阴侯曰：「公之所居，天下精兵处也；而公，陛下之信幸臣也。人言公之畔，陛下必不信；再至，陛下乃疑矣；三至，必怒而自将。…","q":[["号为精兵处，齐蔡燕赵魏。","杜牧 感怀诗一首"]]},{"n":"蒯通言","d":"","s":"《史记》卷九十二〈淮阴侯列传〉～2623～","w":"武涉已去，齐人蒯通知天下权在韩信，欲为奇策而感动之，以相人说韩信曰：「仆尝受相人之术。」韩信曰：「先生相人何如？」对曰：「贵贱在于骨法，忧喜在于容色，成败在于决断，以此参之，万不失一。」韩信曰：「善。先生相寡人何如？」对曰：「愿少閒。」信曰…","q":[]},{"n":"哙伍","d":"","s":"《史记》卷九十二〈淮阴侯列传〉～2628～","w":"信知汉王畏恶其能，常称病不朝从。信由此日夜怨望，居常鞅鞅，羞与绛、灌等列。信尝过樊将军哙，哙跪拜送迎，言称臣，曰：「大王乃肯临臣！」信出门，笑曰：「生乃与哙等为伍！」上常从容与信言诸将能不，各有差。上问曰：「如我能将几何？」信曰：「陛下不过…","q":[]},{"n":"乞食子","d":"","s":"《史记》卷九十二《淮阴侯列传》","w":"淮阴侯韩信者，淮阴人也。始为布衣时，贫无行，不得推择为吏，又不能治生商贾，常从人寄食饮，人多厌之者，常数从其下乡南昌亭长寄食，数月，亭长妻患之，乃晨炊蓐食。食时信往，不为具食。信亦知其意，怒，竟绝去。","q":[["汉日大将军，少为乞食子。","白居易 读史五首"]]},{"n":"人杰","d":"","s":"《史记》卷八〈高祖本纪〉～380～","w":"高祖置酒雒阳南宫。高祖曰：「列侯诸将无敢隐朕，皆言其情。吾所以有天下者何？项氏之所以失天下者何？」高起、王陵对曰：「陛下慢而侮人，项羽仁而爱人。然陛下使人攻城略地，所降下者因以予之，与天下同利也。项羽妒贤嫉能，有功者害之，贤者疑之，战胜而不…","q":[]},{"n":"信越","d":"","s":"《史记》卷七《项羽本纪》","w":"汉王乃追项王至阳夏南，止军，与淮阴侯韩信、建成侯彭越期会而击楚军。至固陵，而信、越之兵不会。楚击汉军，大破之。汉王复入壁，深堑而自守。谓张子房曰：「诸侯不从约，为之柰何？」对曰：「楚兵且破，信、越未有分地，其不至固宜。君王能与共分天下，今可…","q":[["爪牙驱信越，腹心谋张陈。","王圭 咏汉高祖"],["信越功名高似狗，裴王气力大于牛。","罗隐 关亭春望"]]},{"n":"斩成安","d":"","s":"《史记》卷九十二〈淮阴侯列传〉～265～","w":"信与张耳以兵数万，欲东下井陉击赵。赵王、成安君陈馀闻汉且袭之也，聚兵井陉口，号称二十万。广武君李左车说成安君曰：「闻汉将韩信涉西河，虏魏王，禽夏说，新喋血阏与，今乃辅以张耳，议欲下赵，此乘胜而去国远斗，其锋不可当。臣闻千里馈粮，士有饥色，樵…","q":[["今朝拜韩信，计日斩成安。","王涯 从军词三首"]]},{"n":"追韩信","d":"追韩信：喻指重视贤人，善于保护人才。唐李商隐《四皓庙》；“萧何只解追韩信，岂得虚当第一功。”","s":"《史记》卷九十二《淮阴侯列传》","w":"信数与萧何语，何奇之。至南郑，诸将行道亡者数十人，信度何等已数言上，上不我用，即亡。何闻信亡，不及以闻，自追之。人有言上曰：「丞相何亡。」上大怒，如失左右手。居一二日，何来谒上，上且怒且喜，骂何曰：「若亡，何也？」何曰：「臣不敢亡也，臣追亡…","q":[["汉主追韩信，苍生起谢安。","杜甫 宴王使君宅题二首"]]},{"n":"左车略","d":"","s":"《史记》卷九十二《淮阴侯列传》","w":"「赵王、成安君陈馀闻汉且袭之也，聚兵井陉口，号称二十万。广武君李左车说成安君曰：『闻汉将韩信涉西河，虏魏王，禽夏说，新喋血阏与，今乃辅以张耳，议欲下赵，此乘胜而去国远斗，其锋不可当。臣闻千里馈粮，士有饥色，樵苏后爨，师不宿饱。今井陉之道，车…","q":[["恨无左军略，多愧鲁连生。","李白 闻李太尉大举秦兵百万出征东南懦夫请缨冀申一割之用半道病还留别金陵崔侍御十九韵"],["想到清油幕，长谋出左车。","李端 送王副使还并州"]]}],"18":[{"n":"孟韩","d":"","s":"宋苏洵《上田枢密书》","w":"孟 韩 之温醇， 迁 固 之雄刚， 孙 吴 之简切，投之所向，无不如意。","q":[]},{"n":"孟荀","d":"","s":"《文心雕龙·诸子》","w":"研夫 孟 荀 所述，理懿而辞雅。","q":[]},{"n":"孟邻","d":"","s":"汉·刘向《列女传》卷一《母仪·邹孟轲母传》","w":"邹孟轲之母也。号孟母。其舍近墓。孟子之少也，嬉游为墓间之事，踊跃筑埋。孟母曰：「此非吾所以居处子也。」乃去舍市傍。其嬉戏为贾人衒卖之事。孟母又曰：「此非吾所以居处子也。」复徙舍学宫之傍。其嬉游乃设俎豆揖让进退。孟母曰：「真可以居吾子矣。」遂…","q":[["偏知汉水广，应与孟家邻。","刘慎虚 寄江滔求孟六遗文"],["韦生堪继相，孟子愿依邻。","孟郊 题韦承总吴王故城下幽居"]]},{"n":"不忍觳觫牛","d":"觳觫：指牛。宋黄庭坚《题竹石牧牛卜“阿童三尺捶，御此老觳觫。”；觳觫车：指牛车。唐丘丹《奉酬重送归山》：“步出芙蓉府，归乘觳觫车。”","s":"《孟子注疏》卷一下〈梁惠王〉～2～","w":"曰：「臣闻之胡龁曰，王坐于堂上，有牵牛而过堂下者，王见之，曰：『牛何之？』对曰：『将以衅钟。』王曰：『舍之！吾不忍其觳觫，若无罪而就死地。』对曰：『然则废衅钟与？』曰：『何可废也？以羊易之！』不识有诸？」曰：「有之。」曰：「是心足以王矣。百…","q":[["问牛悲衅钟，说彘惊临牢。","柳宗元 游南亭夜还叙志七十韵"],["步出芙蓉府，归乘觳𧥆车。","丘丹 奉酬重送归山"]]},{"n":"定于一","d":"","s":"《孟子注疏》卷一下〈梁惠王章句上〉～2～","w":"孟子见梁襄王。出语人曰。望之不似人君。就之而不见所畏焉。卒然问曰。天下恶乎定。吾对曰。定于一。孰能一之。对曰。不嗜杀人者能一之。孰能与之。对曰。天下莫不与也。王知夫苗乎。七八月之间旱。则苗槁矣。天油然作云。沛然下雨。则苗浡然兴之矣。其如是孰…","q":[]},{"n":"洋洋乎","d":"","s":"《孟子注疏》卷九上〈万章章句上〉～62～","w":"曰：「然则舜伪喜者与？」曰：「否。昔者有馈生鱼于郑子产，子产使校人畜之池。校人烹之，反命曰：『始舍之圉圉焉，少则洋洋焉，攸然而逝。』子产曰『得其所哉！得其所哉！』校人出，曰：『孰谓子产智？予既烹而食之，曰：得其所哉？得其所哉。』故君子可欺以…","q":[]},{"n":"父母国","d":"","s":"《孟子注疏》卷十上〈万章章句上〉～76～","w":"孔子之去齐，接淅而行；去鲁，曰：「迟迟吾行也。」去父母国之道也。可以速而速，可以久而久，可以处而处，可以仕而仕，孔子也。","q":[["回看父母国，生死毕胡尘。","梁琼 昭君怨"]]},{"n":"潢潦无源","d":"","s":"《孟子》卷八上《离娄下》","w":"徐子曰：「仲尼亟称于水，曰：『水哉水哉！』何取于水也？」孟子曰：「源泉混混，不舍昼夜，盈科而后进，放乎四海，有本者如是，是之取尔，苟为无本，七八月之间雨集，沟浍皆盈，其涸也，可立而待也，故声闻过情，君子耻之。」","q":[["潢潦无根源，朝满夕已除。","韩愈 符读书城南"]]},{"n":"见溺不援","d":"","s":"《孟子》卷七《离娄上》","w":"淳于髡曰：「男女授受不亲，礼与？」孟子曰：「礼也。」曰：「嫂溺则援之以手乎？」曰：「嫂溺不援，是豺狼也。男女授受不亲，礼也；嫂溺援之以手者，权也。」","q":[["见溺不援能语狼，忍听丽玉传悲伤。","李咸用 公无渡河"]]},{"n":"尽信书","d":"","s":"《孟子》卷十四《尽心下》","w":"「孟子曰：『尽信《书》，则不如无《书》。吾于《武成》，取二三策而已。』」","q":[["拙谋却为多循理，所短深惭尽信书。","韩偓 闲居"]]},{"n":"孟子好辩","d":"","s":"《孟子注疏》卷六下〈滕文公章句下〉～7～","w":"公都子曰。外人皆称夫子好辩。敢问何也。孟子曰。予岂好辩哉。予不得已也。天下之生久矣。一治一乱。当尧之时。水逆行氾滥于中国。蛇龙居之。民无所定。下者为巢。上者为营窟。书曰。洚水警余。洚水者。洪水也。使禹治之。禹掘地而注之海。驱蛇龙而放之菹。水…","q":[]},{"n":"讴歌","d":"","s":"《孟子》卷九下《万章上》","w":"「尧崩，三年之丧毕，舜让辟丹朱于南河之南。诸侯朝觐者不之丹朱而之舜，狱讼者不之丹朱而之舜，讴歌者不讴歌丹朱而讴歌舜。舜曰『天也』，夫而后之中国践天子位焉，是为帝舜。」","q":[["揖让期明辟，讴歌且顺人。","陈子昂 奉和皇帝上礼抚事述怀应制"]]},{"n":"邹轲","d":"","s":"《史记》卷七十四〈孟子荀卿列传〉～2343～","w":"孟轲，驺人也。受业子思之门人。道既通，游事齐宣王，宣王不能用。适梁，梁惠王不果所言，则见以为迂远而阔于事情。当是之时，秦用商君，富国彊兵；楚、魏用吴起，战胜弱敌；齐威王、宣王用孙子、田忌之徒，而诸侯东面朝齐。天下方务于合从连衡，以攻伐为贤，…","q":[]},{"n":"千乘卿相","d":"","s":"《孟子注疏》卷一上〈梁惠王章句上〉～9～","w":"孟子见梁惠王。王曰：「叟不远千里而来，亦将有以利吾国乎？」孟子对曰：「王何必曰利？亦有仁义而已矣。王曰『何以利吾国』？大夫曰『何以利吾家』？士庶人曰『何以利吾身』？上下交征利而国危矣。万乘之国弑其君者，必千乘之家；千乘之国弑其君者，必百乘之…","q":[]},{"n":"丘轲自厄穷","d":"","s":"《史记》卷四十七〈孔子世家〉～905～","w":"孔子生鲁昌平乡陬邑。其先宋人也，曰孔防叔。防叔生伯夏，伯夏生叔梁纥。纥与颜氏女野合而生孔子，祷于尼丘得孔子。鲁襄公二十二年而孔子生。生而首上圩顶，故因名曰丘云。字仲尼，姓孔氏。……孔子贫且贱。及长，尝为季氏史，料量平；尝为司职吏而畜蕃息。由…","q":[]},{"n":"三乐","d":"","s":"《孟子》卷十三〈尽心上〉","w":"孟子曰：「君子有三乐，而王天下不与存焉。父母俱存，兄弟无故，一乐也。仰不愧于天，俯不怍于人，二乐也。得天下英才而教育之，三乐也。」","q":[["忘虑凭三乐，消闲信五禽。","王周 道院"],["古人三乐兮，我乐多之。","贯休 甘雨应祈"]]},{"n":"三宿","d":"","s":"《孟子注疏》卷四下〈公孙丑章句下〉～85～","w":"孟子去齐。君士语人曰：「不识王之不可以为汤武，则是不明也；识其不可，然且至，则是干泽也。千里而见王，不遇故去。三宿而后出昼，是何濡滞也？士则兹不悦。」高子以告。曰：「夫尹士恶知予哉？千里而见王，是予所欲也；不遇故去，岂予所欲哉？予不得已也。…","q":[["世缺一来应薄命，雨留三宿是前缘。","薛能 自广汉游三学山"],["世网留三宿，真源寄一杯。","赵璜 正月"]]},{"n":"无国要孟子","d":"","s":"《史记》卷七十四〈孟子荀卿列传〉～2434～","w":"孟轲，驺人也。受业子思之门人。道既通，游事齐宣王，宣王不能用。适梁，梁惠王不果所言，则见以为迂远而阔于事情。当是之时，秦用商君，富国彊兵；楚、魏用吴起，战胜弱敌；齐威王、宣王用孙子、田忌之徒，而诸侯东面朝齐。天下方务于合从连衡，以攻伐为贤，…","q":[["无国要孟子，有人毁仲尼。","杜牧 杜秋娘诗"]]},{"n":"揠苗","d":"","s":"《孟子》卷三《公孙丑上》","w":"「宋人有闵其苗之不长而揠之者，芒芒然归。谓其人曰：『今日病矣，予助苗长矣。』其子趋而往视之，苗则槁矣。天下之不助苗长者寡矣。以为无益而舍之者，不耘苗者也；助之长者，揠苗者也。非徒无益，而又害之。」","q":[["揠苗方灭裂，成器待陶钧。","贾岛 送令狐绹相公"]]},{"n":"养浩气","d":"","s":"《孟子注疏》卷三上〈公孙丑章句上〉～54～","w":"曰：「我知言，我善养吾浩然之气。」「敢问何谓浩然之气？」曰：「难言也。其为气也，至大至刚，以直养而无害，则塞于天地之閒。其为气也，配义与道；无是，馁也。」","q":[["兹游苟不嗣，浩气竟谁养。","柳宗元 法华寺石门精室三十韵"]]},{"n":"缘木","d":"","s":"《淮南子》卷十六《说山训》","w":"「为鱼德者，非挈而入渊，为猿赐者，非负而缘木，纵之其所而已。」东汉·高诱注：「喻为政，官方定物，能文者居文官，能武者居武官，故曰纵之其所而已。」东汉·赵岐注：「其不可得知缘乔木而求生鱼也。」","q":[["宦情缘木知非愿，王事敦人敢告劳。","独孤及 喜辱韩十四郎中书兼封近诗示代书题赠"]]},{"n":"曰利","d":"","s":"《孟子注疏》卷一上〈梁惠王章句上〉～9～","w":"孟子见梁惠王。王曰：「叟不远千里而来，亦将有以利吾国乎？」孟子对曰：「王何必曰利？亦有仁义而已矣。王曰『何以利吾国』？大夫曰『何以利吾家』？士庶人曰『何以利吾身』？上下交征利而国危矣。万乘之国弑其君者，必千乘之家；千乘之国弑其君者，必百乘之…","q":[]},{"n":"臧仓毁孟轲","d":"","s":"《孟子注疏》卷二下〈梁惠王章句下〉～47～","w":"鲁平公将出。嬖人臧仓者请曰：「他日君出，则必命有司所之。今乘舆已驾矣，有司未知所之。敢请。」公曰：「将见孟子。」曰：「何哉？君所为轻身以先于匹夫者，以为贤乎？礼义由贤者出。而孟子之后丧踰前丧。君无见焉！」公曰：「诺。」乐正子入见，曰：「君奚…","q":[]},{"n":"镃基","d":"","s":"《孟子》卷三《公孙丑上》","w":"齐人有言曰：「虽有智慧，不如乘势；虽有镃基，不如待时。」","q":[["开济由来变盛衰，五车才得号镃基。","温庭筠 简同志"]]},{"n":"梓匠轮舆","d":"","s":"《孟子》卷十四《尽心下》","w":"梓匠轮舆之工，能与人规矩法度，而不能使人之巧。","q":[["木知就规矩，在梓匠轮舆。人之能为人，由腹有诗书。","韩愈 符读书城南"]]},{"n":"孔孟","d":"","s":"《史记》卷四十七《孔子世家》","w":"「孔子生鲁昌平乡陬邑。」唐·司马贞《史记索隐》：「孔子居鲁之邹邑昌平乡之阙里也。」","q":[["末学惭邹鲁，深仁录弟兄。","皇甫冉 上礼部杨侍郎"],["邹鲁诗书国，应无鼙鼓喧。","郎士元 送裴补阙入河南"]]},{"n":"作俑","d":"","s":"《孟子注疏》卷一上〈梁惠王章句上〉～","w":"梁惠王曰：「寡人愿安承教。」孟子对曰：「杀人以梃与刃，有以异乎？」曰：「无以异也。」「以刃与政，有以异乎？」曰：「无以异也。」曰：「庖有肥肉，厩有肥马，民有饥色，野有饿莩，此率兽而食人也。兽相食，且人恶之，为民父母行政，不免于率兽而食人，恶…","q":[]}],"19":[{"n":"尊酒论文","d":"","s":"《全唐诗》卷二百二十四〈春日忆李白〉","w":"白也诗无敌【白也诗无数】，飘然思不群。清新庚开府，俊逸鲍参军【豪迈鲍参军】。渭北春天树，江东日暮云。何时一尊酒，重与细论文【重与话斯文】。","q":[]},{"n":"曲车","d":"","s":"《全唐诗》卷二百一十六〈饮中八仙歌〉","w":"知章【案：贺知章。会稽人。自称秘书外监。】骑马似乘船，眼花落井水底眠。汝阳【案：让皇帝长子琎。封汝阳王。】三斗始朝天，道逢曲车口流涎【道见曲车口流涎】。恨不移封向酒泉，左相【案：李适之。天宝元年为左丞相。】日兴费万钱。饮如长鲸吸百川，衔杯乐…","q":[]},{"n":"鲍谢","d":"","s":"《九家集注杜诗》卷五〈遣兴五首〉","w":"〈遣兴五首〉其五：「吾怜孟浩然，裋褐即长夜。赋诗何必多，往往凌鲍谢。清江空旧鱼【清江旧鱼美】，春雨馀甘蔗。南望东南云，令人几悲吒。」","q":[]},{"n":"被花恼","d":"","s":"《全唐诗》卷二百二十七〈江畔独步寻花七绝句七首〉","w":"〈江畔独步寻花七绝句七首〉其一：「江上被花恼不彻，无处告诉只颠狂。走觅南邻爱酒伴，经旬出饮独空床【案：原注。斛斯融。吾酒徒。】。」","q":[]},{"n":"并州快剪刀","d":"","s":"《全唐诗》卷二百一十九〈戏题画山水图歌【戏题王宰画山水图歌】〉【案：宰。蜀人。善画玲珑嵌空山水。】","w":"十日画一水，五日画一石。能事不受相促迫，王宰始肯留真迹。壮哉昆崙方壶图【壮哉昆崙方丈图】，挂君高堂之素壁。巴陵洞庭日本东，赤岸水与银河通【南岸水与银河通】。中有云气随飞龙，舟人渔子入浦溆。山木尽亚洪涛风【山木尽带洪涛风】，尤工远势古莫比，咫…","q":[]},{"n":"残膏乘馥","d":"","s":"《新唐书》卷二百一〈文艺列传上·赞曰〉～5738～","w":"赞曰：唐兴，诗人承陈、隋风流，浮靡相矜。至宋之问、沈佺期等，研揣声音，浮切不差，而号「律诗」，竞相袭沿。逮开元间，稍裁以雅正，然恃华者质反，好丽者壮违，人得一概，皆自名所长。至甫，浑涵汪茫，千汇万状，兼古今而有之，它人不足，甫乃厌馀，残膏剩…","q":[]},{"n":"太瘦生","d":"","s":"《旧唐书》卷一百九十下〈文苑列传下·杜甫〉～5055～","w":"天宝末诗人，甫与李白齐名，而白自负文格放达，讥甫龌龊，而有饭颗山之嘲诮。","q":[]},{"n":"眼前突兀","d":"","s":"《全唐诗》卷二百一十九〈茅屋为秋风所破歌〉","w":"八月秋高风怒号，卷我屋上三重茅。茅飞度江洒江郊【茅飞度江满江郊】，高者挂罥长林梢。者飘转沈塘坳【下者飘转沈堂坳】，南村群童欺我老无力。忍能对面为盗贼，公然抱茅入竹去。唇焦口燥呼不得，归来倚杖自叹息。俄顷风定云墨色，秋天漠漠向昏黑。布衾多年冷…","q":[]},{"n":"古希","d":"","s":"《全唐诗》卷二百二十五〈曲江二首〉","w":"〈曲江二首〉其二：「朝回日日典春衣，每日江头尽醉归。酒债寻常【案：八尺曰寻。倍寻曰常。】行处有，人生七十古来稀。穿花蛱蝶深深见【穿花蛱蝶深深舞】，点水蜻蜓款款飞【点水蜻蜓缓缓飞】。传语风光共流转，暂时相赏莫相违。」","q":[]},{"n":"儒冠误身","d":"","s":"《全唐诗》卷二百一十六〈奉赠韦左丞丈二十二韵〉","w":"纨裤不饿死，儒冠多误身。丈人试静听，贱子请具陈。甫昔少年日【甫昔妙年日】，早充观国宾。读书破万卷，下笔如有神。赋料扬雄敌，诗看子建亲。李邕求识面，王翰愿卜邻【王翰愿为邻】。自谓颇挺出【自谓颇挺生】【自谓颇挺特】，立登要路津。致君尧舜上，再使…","q":[]},{"n":"杜老草堂","d":"","s":"《旧唐书》卷一百九十下〈文苑列传下·杜甫〉～5054～","w":"上元二年冬，黄门侍郎、郑国公严武镇成都，奏为节度参谋、检校尚书工部员外郎，赐绯鱼袋。武与甫世旧，待遇甚隆。甫性褊躁，无器度，恃恩放恣，尝凭醉登武之床，瞪视武曰：「严挺之乃有此儿！」武虽急暴，不以为忤。甫于成都浣花里种竹植树，结庐枕江，纵酒啸…","q":[]},{"n":"杜陵饥客","d":"","s":"《全唐诗》卷二百一十六〈醉时歌〉【案：原注。赠广文馆博士郑虔。】","w":"诸公衮衮登台省【诸公衮衮登华省】，广文先生官独冷。甲第纷纷厌粱肉，广文先生饭不足。先生有道出羲皇，先生有才过屈宋【先生有文过屈宋】【先生所谈过屈宋】【先生所该过屈宋】【先生所抱过屈宋】。德尊一代常轗轲【德尊一代常轗壈】，名垂万古知何用。杜陵…","q":[["杜陵饥客眼长寒，蹇驴破帽随金鞍。","苏轼 续丽人行"]]},{"n":"杜陵泪","d":"","s":"《全唐诗》卷二百二十四〈一百五日夜对月〉","w":"无家对寒食，有泪如金波。斫却月中桂【折尽月中桂】，清光应更多。仳离放红蕊【披离放红蕊】，想像嚬青蛾。牛女漫愁思，秋期犹渡河。","q":[]},{"n":"相尔汝","d":"","s":"《全唐诗》卷二百一十六〈醉时歌〉【案：原注。赠广文馆博士郑虔。】","w":"诸公衮衮登台省【诸公衮衮登华省】，广文先生官独冷。甲第纷纷厌粱肉，广文先生饭不足。先生有道出羲皇，先生有才过屈宋【先生有文过屈宋】【先生所谈过屈宋】【先生所该过屈宋】【先生所抱过屈宋】。德尊一代常轗轲【德尊一代常轗壈】，名垂万古知何用。杜陵…","q":[]},{"n":"恩波凤池","d":"","s":"《全唐诗》卷二百三十五〈早朝大明宫呈两省僚友〉","w":"银烛熏天紫陌长【银烛朝天紫陌长】，禁城春色晓苍苍。千条弱柳垂青琐，百啭流莺绕建章【百啭流莺满建章】。剑佩声随玉墀步，衣冠身惹御炉香【衣冠身染御炉香】。共沐恩波凤池上【共沐恩波凤池里】，朝朝染翰侍君王。","q":[]},{"n":"枫林关塞","d":"","s":"《全唐诗》卷二百一十八〈梦李白二首〉","w":"〈梦李白二首〉其一：「死别已吞声，生别常恻恻。江南瘴疠地，逐客无消息【远客无消息】。故人入我梦，明我长相忆。恐非平生魂，路远不可测【路迷不可测】。魂来枫叶青【魂来枫林青】，魂返关塞黑【梦返关塞黑】。君今在罗网，何以有羽翼【何似有羽翼】。落月…","q":[]},{"n":"工部无心","d":"","s":"《全唐诗》卷六百七十五〈蜀中赏海棠〉","w":"浓澹芳春满蜀乡，半随风雨断莺肠【半随风雨断人肠】。浣花溪上堪惆怅，子美无心为发扬【子美无情为发扬】。【案：杜工部居西蜀。诗集中无海棠之题。】","q":[]},{"n":"关心药裹","d":"","s":"《全唐诗》卷二百三十三〈酬郭十五受判官〉","w":"才微岁老尚虚名【才微岁晚尚虚名】，卧病江湖春复生。药裹关心诗总废，花枝照眼句还成。祗同燕石能星陨，自得隋珠觉夜明。乔口橘洲风浪促，系帆何惜片时程。","q":[]},{"n":"李杜飘零","d":"","s":"《全唐诗》卷一百七十六〈鲁郡东石门送杜二甫〉","w":"醉别复几日，登临遍池台。何时石门路，重有金樽开。秋波落泗水，海色明徂徕。飞蓬各自远，且尽手中杯。","q":[]},{"n":"李侯痛饮","d":"","s":"《全唐诗》卷二百二十四〈与李十二白同寻范十隐居〉【案：李白集有寻鲁城北范居士诗。】","w":"李侯有佳句，往往似阴铿。余亦东蒙客，怜君如弟兄。醉眠秋共被，携手日同行【携手月同行】。更想幽期处，还寻北郭生。入门高兴发，侍立小童清。落景闻寒杵，屯云对古城。向来吟橘颂，谁欲讨莼羹【谁与讨莼羹】【惟欲讨莼羹】【惟与讨莼羹】。不愿论簪笏，悠悠…","q":[["歌舞平阳第，园亭沁水林。","李适 奉和初春幸太平公主南庄应制"]]},{"n":"岐王宅里","d":"","s":"《明皇杂录》卷下〈李龟年之遭遇〉～27～","w":"唐开元中，乐工李龟年、彭年、鹤年兄弟三人，皆有才学盛名。彭年善舞，鹤年、龟年能歌，尤妙制渭川，特承顾遇。于东都大起第宅，僭侈之制，踰于公侯。宅在东都通远里，中堂制度甲于都下。其后龟年流落江南，每遇良辰胜赏，为人歌数阕，座中闻之，莫不掩泣罢酒…","q":[]},{"n":"少陵爱酒觅南邻","d":"","s":"《全唐诗》卷二百二十七〈江畔独步寻花七绝句七首〉","w":"〈江畔独步寻花七绝句七首〉其一：「江上被花恼不彻，无处告诉只颠狂。走觅南邻爱酒伴，经旬出饮独空床【案：原注。斛斯融。吾酒徒。】。」","q":[]},{"n":"少陵献赋","d":"","s":"《杜诗集详注》卷二十四〈进三大礼赋表〉","w":"臣甫言。臣生长陛下淳朴之俗，行四十载矣。与麋鹿同群而处，浪迹于陛下丰草长林，实自弱冠之年矣。岂九州牧伯不岁贡豪俊于外，岂陛下明诏不仄席思贤于中哉。臣之愚顽，静无所取，以此知分，沈埋盛时，不敢依违，不敢激吁，默以渔樵之乐，自遣而已。顷者卖药都…","q":[]},{"n":"少陵醉里无闷","d":"","s":"《全唐诗》卷二百二十四〈题张氏隐居二首〉杜甫","w":"〈题张氏隐居二首〉其二：「之子时相见，邀人晚兴留。霁潭鳣发发【济潭鳣发发】，春草鹿呦呦。杜酒偏劳劝，张梨不外求。前村山路险，归醉每无愁。」","q":[]},{"n":"携高李","d":"","s":"《全唐诗》卷二百二十二〈昔游〉","w":"昔者与高【案：适。】李【案：白。】，晚登单父台【同登单父台】。寒芜际碣石，万里风云来。桑柘叶如雨，飞藿去裴回【飞藿共裴回】。清霜大泽冻，禽兽有馀哀。是时仓廪实，洞达寰区开【洞达寰瀛开】。猛士思灭胡，将帅望三台。君王无所惜，驾驭英雄材。幽燕盛…","q":[]},{"n":"一声鸡，东方白","d":"","s":"《全唐诗》卷三百九十一〈致酒行〉","w":"零落栖迟一杯酒，主人奉觞客长寿。主父西游困不归，家门折断门前柳。吾闻马周昔作新丰客，天荒地老无人识。空将笺上两行书，直犯龙颜请恩泽。我有迷魂招不得，雄鸡一声天下白。少年心事当拿云，谁念幽寒坐呜呃。","q":[]}],"20":[{"n":"爱山入剡寻李白","d":"","s":"《全唐诗》卷一百八十一〈秋下荆门〉","w":"霜落荆门江树空，布帆无恙挂秋风。此行不为鲈鱼鲙，自爱名山入剡中。","q":[]},{"n":"尊酒论文","d":"","s":"《全唐诗》卷二百二十四〈春日忆李白〉","w":"白也诗无敌【白也诗无数】，飘然思不群。清新庚开府，俊逸鲍参军【豪迈鲍参军】。渭北春天树，江东日暮云。何时一尊酒，重与细论文【重与话斯文】。","q":[]},{"n":"一斗百篇","d":"","s":"《菽园杂记》卷二～20～","w":"杜子美饮中八仙歌云：「李白一斗诗百篇，长安市上酒家眠，天子呼来不上船。」","q":[]},{"n":"骑鲸客","d":"","s":"《旧唐书》卷一百九十下〈文苑列传下·李白〉～5053～","w":"李白字太白，山东人。少有逸才，志气宏放，飘然有超世之心。父为任城尉，因家焉。少与鲁中诸生孔巢父、韩沔、裴政、张叔明、陶沔等隐于徂徕山，酣歌纵酒，时号「竹溪六逸」。天宝初，客游会稽，与道士吴筠隐于剡中。既而玄宗诏筠赴京师，筠荐之于朝，遣使召之…","q":[]},{"n":"妃子将军瞋","d":"","s":"《新唐书》卷二百二〈文艺列传中·李白〉～5762～","w":"天宝初，南入会稽，与吴筠善，筠被召，故白亦至长安。往见贺知章，知章见其文，叹曰：「子，谪仙人也！」言于玄宗，召见金銮殿，论当世事，奏颂一篇。帝赐食，亲为调羹，有诏供奉翰林。白犹与饮徒醉于市。帝坐沈香子亭，意有所感，欲得白为乐章，召入，而白已…","q":[]},{"n":"才大三千","d":"","s":"《欧阳修全集·居士外集》卷七〈赠王介甫〉","w":"翰林风月三千首，吏部文章二百年。老去自怜心尚在，后来谁与子争先。朱门歌舞争新态，绿绮尘埃试拂弦。常恨闻名不相识，相逢樽酒盍留连。","q":[]},{"n":"太瘦生","d":"","s":"《旧唐书》卷一百九十下〈文苑列传下·杜甫〉～5055～","w":"天宝末诗人，甫与李白齐名，而白自负文格放达，讥甫龌龊，而有饭颗山之嘲诮。","q":[]},{"n":"催唤谪仙","d":"","s":"《旧唐书》卷一百九十下〈文苑列传下·李白〉～5053～","w":"李白字太白，山东人。少有逸才，志气宏放，飘然有超世之心。父为任城尉，因家焉。少与鲁中诸生孔巢父、韩沔、裴政、张叔明、陶沔等隐于徂徕山，酣歌纵酒，时号「竹溪六逸」。天宝初，客游会稽，与道士吴筠隐于剡中。既而玄宗诏筠赴京师，筠荐之于朝，遣使召之…","q":[]},{"n":"诗卷长留","d":"","s":"《全唐诗》卷二百一十六〈送孔巢父谢病归游江东兼呈李白〉","w":"巢父掉头不肯住，东将入海随烟雾。诗卷长留天地间，钓竿欲拂珊瑚树【钓竿欲拂三珠树】。深山大泽龙蛇远，春寒野阴风景暮【花繁草青春日暮】。蓬莱织女回云车【仙人玉女回云车】，指点虚无是征路【指点虚无引归路】。自是君身有仙骨，世人那得知其故。惜君只欲…","q":[]},{"n":"钓鳌客","d":"","s":"《谈苑》卷四","w":"王严光有才不达，自号钓鳌客。巡游都邑球麻铁之资，以造钓具。有不应者，辄录姓名置箧中曰：「下钩时取此等蒙汉为饵。」其狂诞类此。张祐谒李绅，亦称「钓鳖客」。李怒曰：「既解钓鳖，以何为竿？」曰：「以虹为竿。」「以何为钩？」曰：「以明月为钩。」「以…","q":[]},{"n":"风流贺季真","d":"","s":"《全唐诗》卷一百八十二〈对酒忆贺监二首〉","w":"〈对酒忆贺监二首〉其一：「四明有狂客，风流贺季真。长安一相见，呼我谪仙人。昔好杯中物，翻为松下尘【今为松下尘】。金龟换酒处，却忆泪沾巾。」","q":[]},{"n":"芙蓉帐","d":"","s":"《全唐诗》卷一百八十四〈对酒〉","w":"蒲萄酒，金叵罗，吴姬十五细马驮。青黛画眉红锦靴，道字不正娇唱歌，玳瑁筵中怀里醉，芙蓉帐底奈君何。","q":[]},{"n":"倚新妆","d":"","s":"《太平广记》卷二百四〈乐二·歌·李龟年〉～549～","w":"开元中，禁中初重木芍药，即今牡丹也。（开元《天宝花木记》云，禁中呼木芍药为牡丹）得四本，红、紫、浅红、通白者。上因移植于兴庆池东沉香亭前。会花方繁开，上乘照夜白，太真妃以步辇从。诏特选梨园弟子中尤者，得乐十六部。李龟年以歌擅一时之名，手捧檀…","q":[]},{"n":"贺白文章","d":"","s":"《全唐诗》卷二百二十四〈春日忆李白〉","w":"白也诗无敌【白也诗无数】，飘然思不群。清新庚开府，俊逸鲍参军【豪迈鲍参军】。渭北春天树，江东日暮云。何时一尊酒，重与细论文【重与话斯文】。","q":[]},{"n":"李白坟","d":"","s":"《全唐文》卷三百二十一〈李华八·故翰林学士李君墓志铭〉～3250～","w":"呜呼！姑孰东南，青山北址，有唐高士李白之墓。呜呼哀哉！夫仁以安物，公其懋焉；义以济难，公其志焉；识以辩理，公其博焉；文以宣志，公其懿焉。宜其上为王师，下为伯友。年六十有二，不偶，赋〈临终歌〉而卒。悲夫！圣以立德，贤以立言，道以恒世，言以经俗…","q":[]},{"n":"李杜飘零","d":"","s":"《全唐诗》卷一百七十六〈鲁郡东石门送杜二甫〉","w":"醉别复几日，登临遍池台。何时石门路，重有金樽开。秋波落泗水，海色明徂徕。飞蓬各自远，且尽手中杯。","q":[]},{"n":"明月几时有","d":"","s":"《全唐诗》卷一百七十九〈把酒问月〉","w":"青天有月来几时，我今停杯一问之。人攀明月不可得，月行却与人相随。皎如飞镜临丹阙，绿烟灭尽清辉发。但见宵从海上来，宁知晓向云间没。白兔捣药秋复春，嫦娥孤栖与谁邻。今人不见古时月，今月曾经照古人。古人今人若流水，共看明月皆如此。唯愿当歌对酒时，…","q":[]},{"n":"力士脱靴","d":"力士脱靴：指狂傲不羁、蔑视权贵。唐贯休《古意》：“一朝力士脱靴后，玉上青蝇生一个。”","s":"《新唐书》卷二百二〈文艺列传中·李白〉～5762～","w":"天宝初，南入会稽，与吴筠善，筠被召，故白亦至长安。往见贺知章，知章见其文，叹曰：「子，谪仙人也！」言于玄宗，召见金銮殿，论当世事，奏颂一篇。帝赐食，亲为调羹，有诏供奉翰林。白犹与饮徒醉于市。帝坐沈香子亭，意有所感，欲得白为乐章，召入，而白已…","q":[]},{"n":"六逸","d":"","s":"《旧唐书》卷一百五十四〈孔巢父列传〉～4095～","w":"孔巢父，冀州人，字弱翁。父如圭，海州司户参军，以巢父赠工部郎中。巢父早勤文史，少时与韩准、裴政、李白、张叔明、陶沔隐于徂来山，时号「竹溪六逸」。","q":[]},{"n":"谪仙人","d":"","s":"《全唐诗》卷一百八十二〈对酒忆贺监二首〉","w":"〈对酒忆贺监二首〉并序：「太子宾客贺公。于长安紫极宫一见余。呼余为谪仙人。因解金龟换酒为乐。殁后对酒。怅然有怀。而作是诗。」诗云：「狂客归四明，山阴道士迎。敕赐镜湖水，为君台沼荣。人亡馀故宅，空有荷花生。念此杳如梦，凄然伤我情。」","q":[]},{"n":"御手调羹","d":"","s":"《新唐书》卷二百二〈文艺列传中·李白〉～5762～","w":"天宝初，南入会稽，与吴筠善，筠被召，故白亦至长安。往见贺知章，知章见其文，叹曰：「子，谪仙人也！」言于玄宗，召见金銮殿，论当世事，奏颂一篇。帝赐食，亲为调羹，有诏供奉翰林。白犹与饮徒醉于市。帝坐沈香子亭，意有所感，欲得白为乐章，召入，而白已…","q":[]},{"n":"题诗压崔颢","d":"","s":"《苕溪渔隐丛话》前集卷五〈李谪仙〉","w":"宋·李畋《该闻录》云：「唐崔颢《题武昌黄鹤楼》诗云：『昔人已乘白云去，此地空馀黄鹤楼。……烟波江上使人愁。』李太白负大名，尚曰：『眼前有景道不得，崔颢题诗在上头。』欲拟之较胜负，乃作《登金陵凤凰台》诗。」","q":[]},{"n":"吓蛮书","d":"","s":"《元刊杂剧三十种》下册〈李太白贬夜郎杂剧·第一折〉～33～","w":"舒开笺无皱，磨得墨有光，就霜毫写出凌烟像。文场立定中军帐，就兵床拜起元戎将。那里是尊前误草吓蛮书，便是我醉中纳了风魔状。","q":[]},{"n":"携高李","d":"","s":"《全唐诗》卷二百二十二〈昔游〉","w":"昔者与高【案：适。】李【案：白。】，晚登单父台【同登单父台】。寒芜际碣石，万里风云来。桑柘叶如雨，飞藿去裴回【飞藿共裴回】。清霜大泽冻，禽兽有馀哀。是时仓廪实，洞达寰区开【洞达寰瀛开】。猛士思灭胡，将帅望三台。君王无所惜，驾驭英雄材。幽燕盛…","q":[]},{"n":"佯狂太白","d":"","s":"《全唐诗》卷二百二十七〈不见〉【案：原注。近无李白消息。】","w":"不见李生久，佯狂真可哀。世人皆欲杀，吾意独怜才。敏捷诗千首，飘零酒一杯。匡山读书处，头白好归来【头白始归来】。","q":[]},{"n":"杨妃捧砚","d":"","s":"《摭遗》","w":"李白失意游华山，过县，宰方开门决事，白乘醉跨驴过门，宰怒，不知太白也。引至庭下曰：「汝何人？辄敢无礼！」白乞供状，状无姓名，曰：「曾龙巾拭吐，御手调羹，贵妃授砚，力士抹靴，天子门前尚容走马，华阳县里，不得我骑驴？」宰惊起，揖曰：「不知翰林至…","q":[]}],"21":[{"n":"东山丝竹","d":"","s":"《世说新语笺疏》上卷上〈言语〉～2～","w":"谢太傅语王右军曰：「中年伤于哀乐，与亲友别，辄作数日恶。」王曰：「年在桑榆，自然至此，正赖丝竹陶写。恒恐儿辈觉，损欣乐之趣。」","q":[]},{"n":"谢安石","d":"","s":"《晋书》卷七十九《谢安传》","w":"谢安字安石，尚从弟也。父裒，太常卿。安年四岁时，谯郡桓彝见而叹曰：「此儿风神秀彻，后当不减王东海。」及总角，神识沈敏，风宇条畅，善行书。弱冠，诣王濛清言良久，既去，濛子修曰：「向客何如大人？」濛曰：「此客亹亹，为来逼人。」王导亦深器之。由是…","q":[["南阳葛亮为友朋，东山谢安作邻里。","任华 寄杜抬遗"],["自是谢公心近得，登楼望月思依依。","刘沧 从郑郎中高州游东潭"]]},{"n":"泛海船","d":"","s":"《世说新语》中卷上《雅量》","w":"谢太傅盘桓东山时，与孙兴公诸人汎海戏。中兴书曰：「安先居会稽，与支道林、王羲之、许询共游处。出则渔弋山水，入则谈说属文，未尝有处世意也。」风起浪涌，孙、王诸人色并遽，便唱使还。太傅神情方王，吟啸不言。舟人以公貌闲意说，犹去不止。既风转急，浪…","q":[["安石泛溟渤，独啸长风还。逸韵动海上，高情出人间。","李白 与南陵常赞府游五松山"],["谢安舟楫风还起，梁苑池台雪欲飞。","杜甫 戏作寄上汉中王二首之二"]]},{"n":"东山妓","d":"","s":"《世说新语笺疏》中卷上〈识鉴〉～403～","w":"谢公在东山畜妓，简文曰：「安石必出。既与人同乐，亦不得不与人同忧。」南朝梁·刘孝标注引宋明帝《文章志》曰：「安纵心事外，疏略常节，每畜女妓，携持游肆也。」","q":[["闻道今年寒食日，东山旧路独行迟。","刘禹锡 窦夔州见寄寒食日忆故姬小红吹笙因和之"],["谢公兼出处，携妓玩林泉。","崔泰之 奉酬韦嗣立祭酒偶游龙门北溪忽怀骊山别业因以言志示弟淑奉呈诸大僚之作"]]},{"n":"鸡梦","d":"白鸡梦：指死亡。唐李白《东山吟》：“白鸡梦后三百岁，洒酒浇君同所欢、”","s":"《晋书》卷七十九〈谢安列传〉～2076～","w":"时会稽王道子专权，而奸谄颇相扇构，安出镇广陵之步丘，筑垒曰新城以避之。帝出祖于西池，献觞赋诗焉。安虽受朝寄，然东山之志始末不渝，每形于言色。及镇新城，尽室而行，造汎海之装，欲须经略粗定，自江道还东。雅志未就，遂遇疾笃。上疏请量宜旋旆，并召子…","q":[["白鸡梦后三百岁，洒酒浇君同所欢。","李白 东山吟（土山去江宁城二十五里。晋谢安携妓之所。○一作醉过谢安东山作东山吟。）"]]},{"n":"西州路","d":"","s":"《晋书》卷七十九《谢安传》","w":"「羊昙者，太山人，知名士也，为安所爱重。安薨后，辍乐弥年，行不由西州路。尝因石头大醉，扶路唱乐，不觉至州门。左右白曰：『此西州门。』昙悲感不已，以马策扣扉，诵曹子建诗曰：『生存华屋处，零落归山丘。』恸哭而去。」","q":[["季子生前别，羊昙醉后悲。","司空曙 哭苗员外呈张参军"],["满筵旧府笙歌在，独有羊昙最泪流。","杨巨源 酬卢员外"]]},{"n":"奔鲸","d":"","s":"《昭明文选》卷三十〈诗己·杂诗下·和王著作八公山〉～44～","w":"阽危赖宗衮，微管寄明牧。长蛇固能剪，奔鲸自此曝。唐·李善注：「长蛇，喻融；奔鲸，喻坚也。」","q":[]},{"n":"屐齿折","d":"喜折屐：指欣喜。宋苏轼《与叶淳老侯敦夫张秉道同相视新河秉道有诗次韵二首》之一：“怜君嗜好更迂阔，得我新诗喜折屐。”","s":"《世说新语笺疏》中卷上〈雅量〉～374～","w":"谢公与人围棋，俄而谢玄淮上信至。看书竟，默然无言，徐向局。客问淮上利害？答曰：「小儿辈大破贼。」意色举止，不异于常。南朝梁·刘孝标注引《续晋阳秋》曰：「初，符坚南寇，京师大震。谢安无惧色，方命驾出墅，与兄子玄围棋。夜还乃处分，少日皆办。破贼…","q":[["对棋陪谢傅，把剑觅徐君。","杜甫 别房太尉墓（在阆州）"]]},{"n":"小草出山","d":"小草出山：指隐者出仕，或用于自谦。来陆游《初拜再领祠宫之命有感》：“小草出山初已误，断云含雨欲何施。”","s":"《世说新语笺疏》下卷下〈排调〉～803～","w":"谢公始有东山之志，后严命屡臻，势不获已，始就桓公司马。于时人有饷桓公药草，中有「远志」。公取以问谢：「此药又名『小草』，何一物而有二称？」谢未即答。时郝隆在坐，应声答曰：「此甚易解：处则为远志，出则为小草。」谢甚有愧色。桓公目谢而笑曰：「郝…","q":[]},{"n":"为苍生","d":"东山起：指失势后重新得势、唐杜甫《暮秋枉裴道州手礼率尔遣兴寄近呈苏涣侍御》：“无数将军西第成，早作丞相东山起。”","s":"《世说新语》下卷下《排调》","w":"谢公在东山，朝命屡降而不动。后出为桓宣武司马，将发新亭，朝士咸出瞻送。高灵时为中丞，亦往相祖。先时，多少饮酒，因倚如醉，戏曰：「卿屡违朝旨，高卧东山，诸人每相与言：『安石不肯出，将如苍生何？』今亦苍生将如卿何？」谢笑而不答。","q":[["白屋藩魏主，苍生期谢公。","宋之问 伤王七秘书监"],["每劳苍生念，不以黄屋尊。","张九龄 奉和圣制赐诸州刺史以题座右"]]},{"n":"谢雪","d":"","s":"《世说新语》上卷上《言语》","w":"「谢太傅寒雪日内集，与儿女讲论文义。俄而雪骤，公欣然曰：『白雪纷纷何所似？』兄子胡儿曰：『撒盐空中差可拟。』兄女曰：『未若柳絮因风起。』公大笑乐。即公大兄无奕女，左将军王凝之妻也。」南朝梁·刘孝标注：「胡儿，谢朗小字也。」","q":[["谢庭风韵婕妤才，天纵斯文去不回。","窦常 过宋氏五女旧居"],["谢家争拟絮，越岭误惊梅。","令狐楚 省中直夜对雪寄李师素侍郎"]]},{"n":"东山屐","d":"东山：指隐居。唐王维《戏赠张五弟湮三首》之一：“吾弟东山时，心尚一何远。”","s":"《世说新语》下卷下《排调》","w":"「初，谢安在东山居，布衣，时兄弟已有富贵者。」又「谢公始有东山之志，后严命屡臻，势不获已，始就桓公司马。」","q":[["东山有谢安，枉道降鸣銮。","刘宪 奉和幸韦嗣立山庄侍宴应制"],["从此东山非昔游，长嗟人与弦俱绝。","刘禹锡 伤秦姝行"]]},{"n":"揽须","d":"桓伊筝：咏抚筝，或指心情悲愤。宋陆游《夜闻湖中渔歌》：“悲伤似击渐离筑，忠愤如抚桓伊筝。”","s":"《晋书》卷八十一〈桓宣列传·（族子）桓伊〉～28～","w":"时谢安女婿王国宝专利无检行，安恶其为人，每抑制之。及孝武末年，嗜酒好内，而会稽王道子昏醟尤甚，惟狎昵谄邪，于是国宝谗谀之计稍行于主相之间。而好利险诐之徒，以安功名盛极，而构会之，嫌隙遂成。帝召伊饮宴，安侍坐。帝命伊吹笛。伊神色无迕，即吹为一…","q":[["谢傅何由接，桓伊定不凡。","刘禹锡 和汴州令狐相公到镇改月偶书所怀"]]},{"n":"玉树枝","d":"","s":"《世说新语》上卷上《言语》","w":"谢太傅问诸子侄：「子弟亦何预人事，而正欲使其佳？」诸人莫有言者，车骑（谢玄）答曰：「譬如芝兰玉树，欲使其生于阶庭耳。」","q":[["谢庭瞻不远，潘省会于斯。","杜甫 同豆卢峰知字韵"],["子弟先卒伍，芝兰叠玙璠。","杜甫 览柏中允（一作丞）兼子侄数人除官制词因述父子兄弟四美载歌丝纶"]]},{"n":"风流谢安","d":"","s":"《南齐书》卷二十三〈王俭列传〉～436～","w":"俭长礼学，谙究朝仪，每博议，證引先儒，罕有其例。八坐丞郎，无能异者。令史咨事，宾客满席，俭应接铨序，傍无留滞。十日一还学，监试诸生，巾卷在庭，剑卫令史仪容甚盛。作解散髻，斜插帻簪，朝野慕之，相与放效。俭常谓人曰：「江左风流宰相，唯有谢安。」…","q":[]},{"n":"浩浩洪流","d":"","s":"《世说新语笺疏》中卷上〈雅量〉～369～","w":"桓公伏甲设馔，广延朝士，因此欲诛谢安、王坦之。王甚遽，问谢曰：「当作何计？」谢神意不变，谓文度曰：「晋阼存亡，在此一行。」相与俱前。王之恐状，转见于色。谢之宽容，愈表于貌。望阶趋席，方作洛生咏，讽「浩浩洪流」。桓惮其旷远，乃趣解兵。","q":[["彼亦一时，此亦一时。浩浩洪流之咏何必奇。","李白 东山吟"]]},{"n":"晋尚书","d":"","s":"《晋书》卷七十九〈谢安列传〉～2073～","w":"温当北征，会万病卒，安投笺求归。寻除吴兴太守。在官无当时誉，去后为人所思。顷之，徵拜侍中，迁吏部尚书、中护军。……寻为尚书仆射，领吏部，加后将军。……又于土山营墅，楼馆林竹甚盛，每携中外子侄往来游集，","q":[["非吏非隐晋尚书，一丘一壑降乘舆。","刘宪 奉和圣制幸韦嗣立山庄"]]},{"n":"拥鼻吟","d":"洛生咏：美称他人吟咏诵读。唐李白《经乱后将避地剡中留赠崔宣城》：“闷为洛生咏，醉发吴越调。”","s":"《世说新语笺疏》中卷上〈雅量〉～369～","w":"桓公伏甲设馔，广延朝士，因此欲诛谢安、王坦之。王甚遽，问谢曰：「当作何计？」谢神意不变，谓文度曰：「晋阼存亡，在此一行。」相与俱前。王之恐状，转见于色。谢之宽容，愈表于貌。望阶趋席，方作洛生咏，讽「浩浩洪流」。桓惮其旷远，乃趣解兵。王、谢旧…","q":[["方同洛下书生咏，又见军前大将旗。","刘禹锡 和陈许王尚书酬白少傅侍郎长句因通简汝洛旧游之什"],["自解书生咏，愁猿莫夜吟。","刘长卿 寄万州崔使君"]]},{"n":"围棋赌墅","d":"赌墅：喻临危不惧的大将风度，或指舅甥关系。唐孙元晏《晋·谢公赌墅》：“自从乞与羊昙后，赌墅功成更有谁？”","s":"《晋书》卷七十九《谢安传》","w":"时苻坚强盛，疆埸多虞，诸将败退相继。安遣弟石及兄子玄等应机征讨，所在克捷。拜卫将军、开府仪同三司，封建昌县公。坚后率众，号百万，次于淮肥，京师震恐。加安征讨大都督。玄入问计，安夷然无惧色，答曰：「已别有旨。」既而寂然。玄不敢复言，乃令张玄重…","q":[["曾经庾亮三秋月，下尽羊昙两路棋。","李郢 上裴晋公"],["谢公尝乞墅，宁氏终相宅。","权德舆 奉和崔评事寄外甥刘同"]]},{"n":"碎金","d":"","s":"《世说新语》上卷下《文学》","w":"桓公见谢安石作简文谥议，看竟，掷与坐上诸客曰：「此是安石碎金。」","q":[["鲁殿铿寒玉，苔山激碎金。","韦庄 和薛先辈见寄初秋寓怀即事之作二十韵"]]},{"n":"王谢登临","d":"","s":"《晋书》卷七十九《谢安传》","w":"寓居会稽，与王羲之及高阳许询、桑门支遁游处，出则渔弋山水，入则言咏属文，无处世意。扬州刺史庾冰以安有重名，必欲致之，累下郡县敦逼，不得已赴召，月馀告归。","q":[["王谢登临处，依依今尚存。","李嘉祐 送越州辛法曹之任"],["追怀王谢侣，更似会稽岑。","羊士谔 乾元初严黄门自京兆少尹贬牧巴郡乃赋诗十四韵刻于石壁"]]},{"n":"谢安问献之","d":"","s":"《晋书》卷八十《王羲之传》附《王献之传》","w":"谢安甚钦爱之，请为长史。安进号卫将军，复为长史。太元中，新起太极殿，安欲使献之题榜，以为万代宝，而难言之，试谓曰：「魏时陵云殿榜未题，而匠者误钉之，不可下，乃使韦仲将悬橙书之。比讫，须鬓尽白，裁馀气息。还语子弟，宜绝此法。」献之揣知其旨，正…","q":[["忆昔谢安问献之，时人虽见那得知。","权德舆 马秀才草书歌"]]},{"n":"谢安雅量","d":"","s":"《世说新语笺疏》中卷上〈雅量〉～369～","w":"谢太傅盘桓东山时，与孙兴公诸人汎海戏。风起浪涌，孙、王诸人色并遽，便唱使还。太傅神情方王，吟啸不言。舟人以公貌闲意说，犹去不止。既风转急，浪猛，诸人皆諠动不坐。公徐云：「如此，将无归！」众人即承响而回。于是审其量，足以镇安朝野。","q":[]},{"n":"谢傅舅甥贤","d":"","s":"《晋书》卷七十九《谢安传》","w":"安顾谓其甥羊昙曰：「以墅乞汝。」……羊昙者，太山人，知名士也，为安所爱重。安薨后，辍乐弥年，行不由西州路。","q":[["东武杨公姻娅重，西州谢傅舅甥贤。","武元衡 送李秀才赴滑州诣大夫舅"]]},{"n":"谢郎著帽","d":"","s":"《晋书》卷七十九〈谢安列传〉～2073～","w":"征西大将军桓温请为司马，将发新亭，朝士咸送，中丞高崧戏之曰：「卿累违朝旨，高卧东山，诸人每相与言，安石不肯出，将如苍生何！苍生今亦将如卿何！」安甚有愧色。既到，温甚喜，言生平，欢笑竟日。既出，温问左右：「颇尝见我有如此客不？」温后诣安，值其…","q":[]},{"n":"知名自谢公","d":"","s":"《晋书》卷七十九〈谢安列传〉～2076～","w":"安少有盛名，时多爱慕。乡人有罢中宿县者，还诣安。安问其归资，答曰：「有蒲葵扇五万。」安乃取其中者捉之，京师士庶竞市，价增数倍。","q":[["羡尔逢提握，知名自谢公。","雍裕之 题蒲葵扇"]]}],"22":[{"n":"阿戎可语","d":"","s":"《世说新语笺疏》下卷上〈简傲〉～766～","w":"王戎弱冠诣阮籍，时刘公荣在坐。阮谓王曰：「偶有二斗美酒，当与君共饮。彼公荣者，无预焉。」二人交觞酬酢，公荣遂不得一杯。而言语谈戏，三人无异。或有问之者，阮荅曰：「胜公荣者，不得不与饮酒；不如公荣者，不可不与饮酒；唯公荣，可不与饮酒。」南朝梁…","q":[]},{"n":"阿戎跨灶","d":"","s":"《全上古三代秦汉三国六朝文·全三国文》卷二十二〈王朗·杂箴〉～75～","w":"家人有严君焉，井灶之谓也。俾冬作夏，非灶孰能？俾夏作冬，非井孰闲。","q":[]},{"n":"穷途哭","d":"穷途哭：喻指对世事极度悲观。唐杜甫《秋暮枉裴道州手札》：“齿落未是无心人，舌存耻作穷途哭。”","s":"《三国志》卷二十一〈魏书·王粲传·阮籍〉～604～","w":"南朝宋·裴松之注引《魏氏春秋》曰：籍旷达不羁，不拘礼俗。性至孝，居丧虽不率常检，而毁几至灭性。兖州刺史王昶请与相见，终日不得与言，昶叹赏之，自以不能测也。太尉蒋济闻而辟之，后为尚书郎、曹爽参军，以疾归田里。岁馀，爽诛，太傅及大将军乃以为从事…","q":[["每耻穷途哭，今那客泪零。","元稹 饮致用神曲酒三十韵"],["自惭初识查头味，正是栖栖哭阮涂。","吴融 南迁途中作七首渡汉江初尝鳊鱼有作"]]},{"n":"青白眼","d":"青眼：喻对人看重或喜爱，亦指知己。唐王维《过卢四员外宅看饭僧共题七韵》：“三贤异七圣，青眼慕青莲。”；青眼客：指知心朋友。唐王维《赠韦穆十八》：“与君青眼客，共有白云心。”","s":"《晋书》卷四十九〈阮籍列传〉～36～","w":"籍虽不拘礼教，然发言玄远，口不臧否人物。性至孝，母终，正与人围棋，对者求止，籍留与决赌。既而饮酒二斗，举声一号，吐血数升。及将葬，食一蒸肫，饮二斗酒，然后临诀，直言穷矣，举声一号，因又吐血数升。毁瘠骨立，殆致灭性。裴楷往吊之，籍散发箕踞，醉…","q":[["青眼能留客，疏钟逼夜归。","刘商 题禅居废寺"],["旅途谁见客青眼，故国几多人白头。","刘沧 秋日寓怀"]]},{"n":"苏门啸","d":"","s":"《三国志》卷二十一〈魏书·王粲传·阮籍〉～604～","w":"南朝宋·裴松之注引《魏氏春秋》曰：「籍旷达不羁，不拘礼俗。性至孝，居丧虽不率常检，而毁几至灭性。兖州刺史王昶请与相见，终日不得与言，昶叹赏之，自以不能测也。太尉蒋济闻而辟之，后为尚书郎、曹爽参军，以疾归田里。岁馀，爽诛，太傅及大将军乃以为从…","q":[["尝希苏门啸，讵厌巴树猿。","元稹 酬独孤二十六送归通州"],["风泉有清音，何必苏门啸。","孟浩然 题终南翠微寺空上人房"]]},{"n":"胜公荣","d":"","s":"《世说新语笺疏》下卷上〈简傲〉～766～","w":"王戎弱冠诣阮籍，时刘公荣在坐。阮谓王曰：「偶有二斗美酒，当与君共饮。彼公荣者，无预焉。」二人交觞酬酢，公荣遂不得一杯。而言语谈戏，三人无异。或有问之者，阮荅曰：「胜公荣者，不得不与饮酒；不如公荣者，不可不与饮酒；唯公荣，可不与饮酒。」南朝梁…","q":[]},{"n":"阮步兵","d":"","s":"《三国志》卷二十一〈魏书·王粲传·阮籍〉～604～","w":"瑀子籍，才藻艳逸，而倜傥放荡，行己寡欲，以庄周为模则。官至步兵校尉。南朝宋·裴松之注引《魏氏春秋》曰：「籍旷达不羁，不拘礼俗。性至孝，居丧虽不率常检，而毁几至灭性。兖州刺史王昶请与相见，终日不得与言，昶叹赏之，自以不能测也。太尉蒋济闻而辟之…","q":[["琴待嵇中散，杯思阮步兵。","元稹 病减逢春期白二十二辛大不至十韵"],["可但步兵偏爱酒，也知光禄最能诗。","严武 巴岭答杜二见忆"]]},{"n":"乘驴上东平","d":"","s":"《艺文类聚》卷九十四","w":"晋·张隐《文士传》：晋文帝大亲阮籍，恒与谈戏，任其所欲。不迫以职事，籍从容常言：「平生曾游东平，乐其土风，愿得为东平太守。」文帝大悦，即从其意，籍便骑驴，径到郡，至皆坏府舍诸壁鄣，使内外相望，然教令清当，十馀日，便乘驴去。","q":[["阮籍为太守，乘驴上东平。剖竹十日间，一朝风化清。","李白 赠闾丘宿松"]]},{"n":"二阮","d":"","s":"《晋书》卷四十九《阮籍传》附《阮咸传》","w":"「咸字仲容。父熙，武都太守。咸任达不拘，与叔父籍为竹林之游。」","q":[["我家小阮贤，剖竹赤城边。","李白 送杨山人归天台"],["阮咸虽别巷，遥识此时心。","李端 寄上舍人叔"]]},{"n":"呼竖子","d":"","s":"《三国志》卷二十一〈魏书·王粲传·阮籍〉～604～","w":"南朝梁·刘孝标注引《魏氏春秋》曰：「籍旷达不羁，不拘礼俗。性至孝，居丧虽不率常检，而毁几至灭性。兖州刺史王昶请与相见，终日不得与言，昶叹赏之，自以不能测也。太尉蒋济闻而辟之，后为尚书郎、曹爽参军，以疾归田里。岁馀，爽诛，太傅及大将军乃以为从…","q":[["沈湎呼竖子，狂言非至公。抚掌黄河曲，嗤嗤阮嗣宗。","李白 登广武古战场怀古"],["可怜广武山前语，楚汉宁教作战场。","韩偓 秋郊闲望有感"]]},{"n":"嵇阮","d":"","s":"《昭明文选》卷四十三、三国魏·嵇叔夜（康）《与山巨源绝交书》","w":"阮嗣宗口不论人过，吾每师之，而未能及。至性过人，与物无伤，唯饮酒过差耳。至为礼法之士所绳，疾之如雠，幸赖大将军保持之耳。吾不如嗣宗之贤，而有慢弛之阙；又不识人情，闇于机宜；无万石之慎，而有好尽之累。久与事接，疵衅日兴，虽欲无患，其可得乎？","q":[["竹林一自王戎去，嵇阮虽贫兴未衰。","刘禹锡 和陈许王尚书酬白少傅侍郎长句因通简汝洛旧游之什"],["绛霄轻霭翊三台，稽阮襟怀管乐才。","李郢 奉陪裴相公重阳日游安乐池亭"]]},{"n":"嵇喜","d":"","s":"《晋书》卷四十九《阮籍传》","w":"籍又能为青白眼，见礼俗之士，以白眼对之。及嵇喜来吊，籍作白眼，喜不怿而退。","q":[["礼俗拘嵇喜，侯王忻戴逵。","李商隐 咏怀寄秘阁旧僚二十六韵"]]},{"n":"竹林七贤","d":"七贤：喻指文人放荡不羁，或指独立于世俗之外，或喻朋友的交情深厚。唐卢纶《秋夜同畅当宿潭上西亭》：“圆月出山头，七贤林下游。”","s":"《三国志》卷二十一〈魏书·王粲传·嵇康〉～605～","w":"时又有谯郡嵇康，文辞壮丽，好言老、庄，而尚奇任侠。至景元中，坐事诛。南朝宋·裴松之注引《魏氏春秋》曰：「康寓居河内之山阳县，与之游者，未尝见其喜愠之色。与陈留阮籍、河内山涛、河南向秀、籍兄子咸、琅邪王戎、沛人刘伶相与友善，游于竹林，号为七贤…","q":[["东篱摘芳菊，想见竹林游。","储光羲 仲夏饯魏四河北觐叔"],["超超青云器，婉婉竹林会。","储光羲 奉和韦判官献侍郎叔除河东采访使"]]},{"n":"刘公荣","d":"","s":"《世说新语》下卷上《简傲》","w":"「王戎弱冠诣阮籍，时刘公荣在坐。阮谓王曰：『偶有二斗美酒，当与君共饮。彼公荣者，无预焉。』二人交觞酬酢，公荣遂不得一杯。而言语谈戏，三人无异。或有问之者，阮荅曰：『胜公荣者，不得不与饮酒；不如公荣者，不可不与饮酒；唯公荣，可不与饮酒。』」","q":[["已恨流莺欺谢客，更将浮蚁与刘郎。","温庭筠 李羽处士寄新酝走笔戏酬"]]},{"n":"茂先王佐","d":"","s":"《晋书》卷三十六《张华传》","w":"张华字茂先，范阳方城人也。父平，魏渔阳郡守。华少孤贫，自牧羊，同郡卢钦见而器之。乡人刘放亦奇其才，以女妻焉。华学业优博，辞藻温丽，朗赡多通，图纬方伎之书莫不详览。少自修谨，造次必以礼度。勇于赴义，笃于周急。器识弘旷，时人罕能测之。初未知名，…","q":[["茂先实王佐，仲举信时英。","裴耀卿 敬酬张九龄当涂界留赠之作"]]},{"n":"未能免俗","d":"阮家贫：指生活贫困。唐王维《郑梁州相过》：“中厨办粗饭，应恕阮家贫。”","s":"《世说新语笺疏》下卷上〈任诞〉～732～","w":"阮仲容、步兵居道南，诸阮居道北。北阮皆富，南阮贫。七月七日，北阮盛晒衣，皆纱罗锦绮。仲容以竿挂大布犊鼻裈于中庭。人或怪之，答曰：「未能免俗，聊复尔耳！」南朝宋·裴松之注引《竹林七贤论》曰：「诸阮前世皆儒学，善居室，唯咸一家尚道弃事，好酒而贫…","q":[["近水方同梅市隐，曝衣多笑阮家贫。","司空曙 闲园即事寄暕公"],["南阮贫无酒，唯将泪湿衣。","李端 送别驾赴晋陵即舍人叔之兄"]]},{"n":"蓬池咏","d":"","s":"《昭明文选》卷二十三、三国魏·阮嗣宗（籍）《咏怀诗十七首》其十二","w":"徘徊蓬池上，还顾望大梁。绿水扬洪波，旷野莽茫茫。走兽交横驰，飞鸟相随翔。是时鹑火中，日月正相望。朔风厉严寒，阴气下微霜。羁旅无畴匹，俛仰怀哀伤。","q":[["却忆蓬池阮公咏，因吟渌水扬洪波。","李白 梁园吟"]]},{"n":"阮嗣宗","d":"","s":"《三国志》卷二十一《魏书·王粲传》附《阮籍传》","w":"「瑀子籍，才藻艳逸，而倜傥放荡，行己寡欲，以庄周为模则。官至步兵校尉。」","q":[["马卿台上应芜没，阮籍帷前空已矣。","司马逸客 雅琴篇"],["阮籍推名饮，清风满竹林。","孟浩然 听郑五愔弹琴"]]},{"n":"阮巷","d":"","s":"《晋书》卷四十九《阮籍传》附《阮咸传》","w":"咸字仲容。父熙，武都太守。咸任达不拘，与叔父籍为竹林之游，当世礼法者讥其所为。咸与籍居道南，诸阮居道北，北阮富而南阮贫。","q":[["到日应文会，风流胜阮家。","戴叔伦 送李审之桂州谒中丞叔"],["阮家今夜乐，应在竹林间。","李端 送张淑归觐叔父"]]},{"n":"文侯彗","d":"","s":"《昭明文选》卷四十、三国魏·阮嗣宗（籍）《诣蒋公》","w":"「子夏处西河之上，而文侯拥彗。」唐·李善注引《吕氏春秋》：「白圭曰：魏文侯师子夏。」唐·李善注引李奇《汉书》注：「拥彗为恭也。如今卒持帚也。」引李奇《汉书注》曰：「拥彗为恭也，如今卒持帚也。」","q":[["几分汉廷竹，夙拥文侯彗。","杜甫 赠秘书监江夏李公邕"]]},{"n":"无臧否","d":"","s":"《晋书》卷四十九〈阮籍列传〉～36～","w":"籍虽不拘礼教，然发言玄远，口不臧否人物。","q":[["辞满如脱屣，立言无否臧。","李颀 送刘四"]]},{"n":"啸阮","d":"","s":"《世说新语》下卷上《栖逸》","w":"阮步兵啸，闻数百步。苏门山中，忽有真人，樵伐者咸共传说。阮籍往观，见其人拥膝岩侧。籍登岭就之，箕踞相对。籍商略终古，上陈黄、农玄寂之道，下考三代盛德之美，以问之，仡然不应。复有为之教，栖神导气之术以观之，彼犹如前，凝瞩不转。籍因对之长啸。…","q":[["风来应啸阮，波动可琴嵇。","田游岩 弘农清岩曲有磐石可坐宋十一每拂拭待余寄赠之"]]},{"n":"一醉六十日","d":"","s":"《晋书》卷四十九〈阮籍列传〉～360～","w":"籍本有济世志，属魏晋之际，天下多故，名士少有全者，籍由是不与世事，遂酣饮为常。文帝初欲为武帝求婚于籍，籍醉六十日，不得言而止。","q":[["一醉六十日，古来闻阮生。","杜牧 自宣州赴官入京路逢裴坦判官归宣州因题赠"],["一醉六十日，一裘三十年。","高蟾 道中有感"]]},{"n":"诸阮英游","d":"","s":"《世说新语笺疏》下卷上〈任诞〉～734～","w":"诸阮皆能饮酒，仲容至宗人閒共集，不复用常杯斟酌，以大瓮盛酒，围坐，相向大酌。时有群猪来饮，直接去上，便共饮之。","q":[]},{"n":"竹里琴","d":"","s":"《晋书》卷四十九《阮籍传》","w":"阮籍字嗣宗，陈留尉氏人也。……或闭户视书，累月不出；或登临山水，经日忘归。博览群籍，尤好庄老。嗜酒能啸，善弹琴。当其得意，忽忘形骸。时人多谓之痴。","q":[["鸟哢花间曲，人弹竹里琴。","李端 题从叔沆林园"]]}],"23":[{"n":"安车","d":"","s":"《后汉书》卷八十三《逸民传·严光传》","w":"「严光字子陵，一名遵，会稽馀姚人也。少有高名，与光武同游学。及光武即位，乃变名姓，隐身不见。帝思其贤，乃令以物色访之。后齐国上言：『有一男子，披羊裘钓泽中。』帝疑其光，乃备安车玄纁，遣使聘之。三反而后至。」","q":[["安车未至柴关外，片玉已藏坟土新。","李咸用 悼范摅处士"],["想就安车召，宁期负矢还。","李商隐 灵仙阁晚眺寄郓州韦评事"]]},{"n":"白马生","d":"","s":"《后汉书》卷二十七《张湛传》","w":"后汉张湛字子孝，扶风平陵人也。建武五年，拜光禄勋。光武临朝，或有惰容，湛辄陈谏其失。常乘白马，上后见湛，辄曰：「白马生且复谏矣。」","q":[["闻君前日独庭争，汉帝偏知白马生。","刘禹锡 寄杨八拾遗（时出为国子主簿分司东都韩十八员外亦转国子博士同在洛阳）"],["群乌自朝夕，白马休横行。","杜甫 八哀诗（并序）赠左仆射郑国公严公武"]]},{"n":"白水龙飞","d":"","s":"《昭明文选》卷四东汉·张平子（衡）《南都赋》","w":"「夫南阳者，真所谓汉之旧都者也。远世则刘后甘厥龙醢，视鲁县而来迁，奉先帝而追孝，立唐祀乎尧山，固灵根于夏叶，终三代而始蕃，非纯德之宏图，孰能揆而处旃。近则考侯思故，匪居匪宁，秽长沙之无乐，历江湘而北征，曜朱光于白水，会九世而飞荣。」「唐·李…","q":[["赤眉立盆子，白水兴汉光。","李白 上云乐"],["白水龙飞已几春，偶逢遗迹问耕人。","韩愈 题广昌馆（在随州枣阳县南）"]]},{"n":"百万化鱼","d":"","s":"《后汉书》卷一上《光武帝纪上》","w":"进至邯郸，故赵缪王子林说光武曰：「赤眉今在河东，但决水灌之，百万之众可使为鱼。」","q":[["哀哉桃林战，百万化为鱼。","杜甫 潼关吏（安禄山兵北。哥舒翰请坚守潼关。明皇听杨国忠言。力趣出兵。翰抚膺恸哭而出。兵至灵宝溃。关遂失守。）"],["一国实三公，万人欲为鱼。","杜甫 草堂"]]},{"n":"赤伏","d":"","s":"晋·袁宏《后汉纪》卷一","w":"「五月，萧王自渔阳过范阳，命收葬士卒死者。至中山，群臣上尊号曰：『大王初征昆阳则王莽败亡，后伏邯郸则北州平定，此岂人力哉！三分天下而有其二，跨州据土，带甲百万。武功论之，无所与争；文德论之，无所与让。宜正号位，为社稷计。』王不听。诸将固请，…","q":[["赤伏起颓运，卧龙得孔明。","李白 读诸葛武侯传书怀赠长安崔少府叔封昆季"],["冯异献赤伏，邓生倏来臻。","李白 赠张相镐二首之一"]]},{"n":"赤眉立盆子","d":"","s":"《后汉书》卷十一《刘盆子传》","w":"东汉建武元年，赤眉军方阳劝樊崇：「不如立宗室，挟义诛伐。」「崇等以为然，而巫言益甚。前及郑，乃相与议曰：『今迫近长安，而鬼神如此，当求刘氏共尊立之。』六月，遂立盆子为帝，自号建世元年。」「盆子时年十五，被发徒跣，敝衣赭汗，见众拜，恐畏欲啼。…","q":[["赤眉立盆子，白水兴汉光。","李白 上云乐"]]},{"n":"舂陵王气","d":"","s":"《后汉书》卷一上〈光武帝本纪上〉～2～","w":"莽末，天下连岁灾蝗，寇盗锋起。地皇三年，南阳荒饥，诸家宾客多为小盗。光武避吏新野，因卖谷于宛。宛人李通等以图谶说光武云：「刘氏复起，李氏为辅。」光武初不敢当，然独念兄伯升素结轻客，必举大事，且王莽败亡已兆，天下方乱，遂与定谋，于是乃市兵弩。…","q":[]},{"n":"垂翅","d":"","s":"《后汉书》卷十七《溤异传》","w":"玺书劳异曰：「赤眉破平，士吏劳苦，始虽垂翅回溪，终能奋翼黾池，可谓失之东隅，收之桑榆。方论功赏，以荅大勋。」","q":[["垂翅徒衰老，先鞭不滞留。","杜甫 重送刘十弟判官"]]},{"n":"得陇望蜀","d":"","s":"《东观汉记》卷九《岑彭传》","w":"彭宠与吴汉围隗嚣于西城，敕彭书曰：「西城若下，便可将兵南击蜀虏，人苦不知足，既平陇，重望蜀，每一发兵，头鬓为白。」","q":[["物苦不知足，得陇又望蜀。","李白 古风之二十三"]]},{"n":"杜林驳尧","d":"","s":"《后汉书》卷二十七《杜林传》","w":"「杜林字伯山，扶风茂陵人也。父邺，成哀閒为凉州刺史。林少好学沈深，家既多书，又外氏张竦父子喜文采，林从竦受学，博洽多闻，时称通儒。」「光武闻林已还三辅，乃徵拜侍御史，引见，问以经书故旧及西州事，甚悦之，赐车马衣被。群寮知林以名德用，甚尊惮之…","q":[["寿王议鼎，杜林驳尧。","李瀚 蒙求"]]},{"n":"杜林官","d":"","s":"《后汉书》卷二十七《杜林传》","w":"「杜林字伯山，扶风茂陵人也。父邺，成哀閒为凉州刺史。林少好学沈深，家既多书，又外氏张竦父子喜文采，林从竦受学，博洽多闻，时称通儒。」「光武闻林已还三辅，乃徵拜侍御史，引见，问以经书故旧及西州事，甚悦之，赐车马衣被。群寮知林以名德用，甚尊惮之…","q":[["朱绂两参王俭府，绣衣三领杜林官。","罗隐 淮南送卢端公归台"]]},{"n":"伏波米","d":"聚米：指军事上分析地形。明陈瑚《李映碧廷尉遗地图》：“人关无复萧丞相，聚米空思马伏波。”","s":"《后汉书》卷二十四〈马援列传·马援〉～834～","w":"八年，帝自西征嚣，至漆，诸将多以王师之重，不宜远入险阻，计冘豫未决。会召援，夜至，帝大喜，引入，具以群议质之。援因说隗嚣将帅有土崩之埶，兵进有必破之状。又于帝前聚米为山谷，指画形埶，开示众军所从道径往来，分析曲折，昭然可晓。帝曰：「虏在吾目…","q":[["运筹知决胜，聚米似论边。","韦应物 酬豆卢仓曹题库壁见示"]]},{"n":"鼓车","d":"鼓车：指大材小用。唐杜甫《送从弟亚赴安西判官》：“吾闻驾鼓车，不合用骐骥。”","s":"《后汉书》卷七十六〈循吏列传〉～2457～","w":"建武十三年，异国有献名马者，日行千里，又进宝剑，贾兼百金，诏以马驾鼓车，剑赐骑士。","q":[["遭遇不遭遇，盐车与鼓车。","杜牧 骦骕骏"],["今日翔麟马，先宜驾鼓车。","杜甫 复愁十二首"]]},{"n":"光武","d":"","s":"《后汉书》卷一上《光武帝纪上》","w":"「世祖光武皇帝讳秀，字文叔，南阳蔡阳人，高祖九世之孙也，出自景帝生长沙定王发。」","q":[["遥欣克复美，光武安可同。","李白 流夜郎半道承恩放还兼欣剋复之美书怀示息秀才"]]},{"n":"汉威仪","d":"","s":"《后汉书》卷一上《光武帝纪上》","w":"更始将北都洛阳，以光武行司隶校尉，使前整修宫府。于是置僚属，作文移，从事司察，一如旧章。时三辅吏士东迎更始，见诸将过，皆冠帻，而服妇人衣，诸于绣镼，莫不笑之，或有畏而走者。及见司隶僚属，皆欢喜不自胜。老吏或垂涕曰：「不图今日复见汉官威仪！」…","q":[["独逢尧典日，再睹汉官时。","严武 酬别杜二"],["庶同昆阳举，再睹汉仪新。","李白 赠张相镐二首之一（时逃难在宿松山作。萧士赟云，此下八首非白作。）"]]},{"n":"佳气","d":"","s":"《白虎通》卷三〈封禅〉","w":"德至八方则祥风至，佳气时喜。","q":[["关河佳气散，夷夏哭声连。","姚合 文宗皇帝挽词三首"],["都人望翠华，佳气向金阙。","杜甫 北征"]]},{"n":"君章拒猎","d":"","s":"《后汉书》卷二十九《郅恽传》","w":"郅恽字君章，汝南西平人也。年十二失母，居丧过礼。及长，理韩诗、严氏春秋，明天文历数。……恽遂客居江夏教授，郡举孝廉，为上东城门候。帝尝出猎，车驾夜还，恽拒关不开。帝令从者见面于门閒。恽曰：「火明辽远。」遂不受诏。帝乃回从东中门入。明日，恽上…","q":[["广德从桥，君章拒猎。","李瀚 蒙求"]]},{"n":"昆阳举","d":"","s":"《汉书》卷九十九下《王莽传下》","w":"昆阳时已降汉，汉兵守之。严尤、陈茂与二公会，二公纵兵围昆阳。严尤曰：「称尊号者在宛下，宜亟进。彼破，诸城自定矣。」邑曰：「百万之师，所过当灭，今屠此城，喋血而进，前歌后舞，顾不快邪！」遂围城数十重。城中请降，不许。严尤又曰：「『归师勿遏，围…","q":[["庶同昆阳举，再睹汉仪新。","李白 赠张相镐二首"],["千载昆阳好功业，与君门下作恩威。","罗隐 经故洛阳城"]]},{"n":"刘文叔","d":"","s":"《后汉书》卷一上〈光武帝本纪上〉～","w":"世祖光武皇帝讳秀，字文叔，南阳蔡阳人，高祖九世之孙也，出自景帝生长沙定王发。发生舂陵节侯买，买生郁林太守外，外生钜鹿都尉回，回生南顿令钦，钦生光武。光武年九岁而孤，养于叔父良。身长七尺三寸，美须眉，大口，隆准，日角。性勤于稼穑，而兄伯升好侠…","q":[]},{"n":"隆准","d":"","s":"《史记》卷八《高祖本纪》","w":"「高祖为人，隆准而龙颜，美须髯，左股有七十二黑子。」南朝宋·裴骃《史记集解》引文颖曰：「高祖感龙而生，故其颜貌似龙，长颈而高鼻。」","q":[["我来不见隆准人，沥酒空馀庙中客。","李商隐 偶成转韵七十二句赠四同舍"],["高帝子孙尽隆准，龙种自与常人殊。","杜甫 哀王孙"]]},{"n":"南阳有近亲","d":"","s":"《后汉书》卷二十二〈朱景王杜马刘傅坚马列传·刘隆〉～780～","w":"帝见陈留吏牍上有书，视之，云：「颍川、弘农可问，河南、南阳不可问」。帝诘吏由趣，吏不肯服，抵言于长寿街上得之。帝怒。时显宗为东海公，年十二，在幄后言曰：「吏受郡敕，当欲以垦田相方耳。」帝曰：「即如此，何故言河南、南阳不可问？」对曰：「河南帝…","q":[["丘坟发掘当官路，何处南阳有近亲。","韩愈 题广昌馆"]]},{"n":"羡金吾","d":"","s":"《后汉书》卷十上《皇后纪·光烈阴皇后纪》","w":"光烈阴皇后讳丽华，南阳新野人。初，光武适新野，闻后美，心悦之。后至长安，见执金吾车骑甚盛，因叹曰：「仕宦当作执金吾，娶妻当得阴丽华。」更始元年六月，遂纳后于宛当成里，时年十九。及光武为司隶校尉，方西之洛阳，令后归新野。及邓奉起兵，后兄识为之…","q":[["长安少年无远图，一生惟羡执金吾。","王翰 饮马长城窟行"]]},{"n":"小敌怯","d":"","s":"《后汉书》卷一上〈光武帝本纪上〉～8～","w":"诸部喜曰：「刘将军平生见小敌怯，今见大敌勇，甚可怪也，且复居前。请助将军！」","q":[["异王册崇勋，小敌信所怯。","杜甫 八哀诗故司徒李公光弼"]]},{"n":"修高庙","d":"","s":"《后汉书》卷一上《光武帝纪上》","w":"「壬子，起高庙，建社稷于洛阳，立郊兆于城南，始正火德，色尚赤。」唐·李贤注引《汉礼制度》曰：「人君之居，前有朝，后有寝。终则制庙以象朝，后制寝以象寝。光武都洛阳，乃合高祖以下至平帝为一庙，藏十一帝主于其中。」","q":[["世祖修高庙，文公赏从臣。","杜甫 寄张十二山人彪三十韵"]]},{"n":"仲华遇主","d":"","s":"《后汉书》卷七十七《范晔传》","w":"樊晔字仲华，南阳新野人也。与光武少游旧。建武初，徵为侍御史，迁河东都尉，引见云台。初，光武微时，尝以事拘于新野，晔为市吏，馈饵一笥，帝德之不忘，仍赐晔御食，及乘舆服物。因戏之曰：「一笥饵得都尉，何如？」晔顿首辞谢。及至郡，诛讨大姓马适匡等。…","q":[["仲华遇主年犹少，公瑾论兵位已酬。","皇甫冉 送崔使君赴寿州"]]}],"24":[{"n":"安僻陋","d":"","s":"《史记》卷五十三《萧相国世家》","w":"何置田宅必居穷处，为家不治垣屋。曰：「后世贤，师吾俭；不贤，毋为势家所夺。」（「穷处」《汉书》卷三十九作「穷辟处」）","q":[["丘墙高莫比，萧宅僻还清。","姚合 和裴令公新成绿野堂即事"],["僻殊萧相宅，芜胜邵平园。","李吉甫 夏夜北园即事寄门下武相公"]]},{"n":"追亡","d":"","s":"《史记》卷九十二〈淮阴侯列传〉～26～","w":"信数与萧何语，何奇之。至南郑，诸将行道亡者数十人，信度何等已数言上，上不我用，即亡。何闻信亡，不及以闻，自追之。人有言上曰：「丞相何亡。」上大怒，如失左右手。居一二日，何来谒上，上且怒且喜，骂何曰：「若亡，何也？」何曰：「臣不敢亡也，臣追亡…","q":[["公议今如此，登坛到即行。","姚合 赠卢大夫将军"],["儒有登坛贵，何人得此功。","姚合 送郑尚书赴兴元"]]},{"n":"曹参次位","d":"","s":"《史记》卷五十三〈萧相国世家〉～206～","w":"列侯毕已受封，及奏位次，皆曰：「平阳侯曹参身被七十创，攻城略地，功最多，宜第一。」上已桡功臣，多封萧何，至位次未有以复难之，然心欲何第一。关内侯鄂君进曰：「群臣议皆误。夫曹参虽有野战略地之功，此特一时之事。夫上与楚相距五岁，常失军亡众，逃身…","q":[]},{"n":"曹参酒","d":"曹参酒：指丞相或官吏无为而治。唐李商隐《五百述德抒情诗一百四十韵》：“后饮曹参酒，先和傅说羹。”","s":"《史记》卷五十四《曹相国世家》","w":"参代何为汉相国，举事无所变更，一遵萧何约束。择郡国吏木诎于文辞，重厚长者，即召除为丞相史。吏之言文刻深，欲务声名者，辄斥去之。日夜饮醇酒。卿大夫已下吏及宾客见参不事事，来者皆欲有言。至者，参辄饮以醇酒，閒之，欲有所言，复饮之，醉而后去，终莫…","q":[["后饮曹参酒，先和傅说羹。","李商隐 五首述德抒情诗一首四十韵献上杜七兄仆射相公"],["西伯最怜耕让畔，曹参空爱酒盈樽。","贯休 大蜀皇帝潜龙日述圣德诗五首之五"]]},{"n":"曹参趣装","d":"","s":"《史记》卷五十四《曹相国世家》","w":"惠帝二年，萧何卒。参闻之，告舍人趣治行，「吾将入相」。居无何，使者果召参。","q":[["于公高门，曹参趣装。","李瀚 蒙求"]]},{"n":"成萧何败萧何","d":"","s":"《容斋随笔·容斋续笔》卷八〈萧何绐韩信〉～32～","w":"黥布为其臣贲赫告反，高祖以语萧相国，相国曰：「布不宜有此，恐仇怨妄诬之，请系赫，使人微验淮南。」布遂反。韩信为人告反，吕后欲召，恐其不就，乃与萧相国谋，诈令人称陈豨已破，绐信曰：「虽病强入贺。」信入，即被诛。信之为大将军，实萧何所荐，今其死…","q":[]},{"n":"功狗","d":"功人：喻谋臣。清王昙《留候词》：“功人功狗两无益，徒受亭公谩骂名。”；功臣狗：喻武将。清赵翼《悯忠寺石一坛相传唐太宗葬战骨处》：“岂乏功臣狗，兼多君子猿。”","s":"《史记》卷五十三〈萧相国世家〉～205～","w":"汉五年，既杀项羽，定天下，论功行封。群臣争功，岁馀功不决。高祖以萧何功最盛，封为酂侯，所食邑多。功臣皆曰：「臣等身被坚执锐，多者百馀战，少者数十合，攻城略地，大小各有差。今萧何未尝有汗马之劳，徒持文墨议论，不战，顾反居臣等上，何也？」高帝曰…","q":[["功人功狗两无益，徒受亭公谩骂名。","王昙 留候词"],["信越功名高似狗，裴王气力大于牛。未知至竟将何用，渭水泾川一向流。","罗隐 关亭春望"]]},{"n":"功曹非复萧何","d":"","s":"《三国志》卷五十七《吴书·虞翻传》","w":"策曰：「君言是也……」南朝宋·裴松之注引《江表传》：「策笑曰：『然。』因曰：『孤有征讨事，未得还府，卿复以功曹为吾萧何，守会稽耳。』」","q":[["勋业终（一作真）归马伏波，功曹非（一作无）复汉萧何。","杜甫 奉寄别马巴州（原注。时甫除京兆功曹。在东川。）"]]},{"n":"关中事","d":"","s":"《史记》卷五十三《萧相国世家》","w":"「汉二年，汉王与诸侯击楚，何守关中，侍太子，治栎阳。为法令约束，立宗庙社稷宫室县邑，辄奏上，可，许以从事；即不及奏上，辄以便宜施行，上来以闻。关中事计户口转漕给军，汉王数失军遁去，何常兴关中卒，辄补缺。上以此专属任何关中事。」「后功臣争功，…","q":[["今日关中事，萧何共尔忧。","刘长卿 重阳日鄂城楼送屈突司直"]]},{"n":"管萧","d":"","s":"《三国志》卷三十五《蜀书·诸葛亮传》","w":"昔萧何荐韩信，管仲举王子城父，皆忖己之长，未能兼有故也。亮之器能政理，抑亦管、萧之亚匹也，而时之名将无城父、韩信，故使功业陵迟，大义不及邪？盖天命有归，不可以智力争也。","q":[["将必继管萧，岂惟蹑应徐。","陆长源 酬孟十二新居见寄"]]},{"n":"韩侯出井陉","d":"","s":"《史记》卷九十二〈淮阴侯列传〉～266～","w":"韩信使人閒视，知其不用，还报，则大喜，乃敢引兵遂下。未至井陉口三十里，止舍。夜半传发，选轻骑二千人，人持一赤帜，从閒道蓖山而望赵军，诫曰：「赵见我走，必空壁逐我，若疾入赵壁，拔赵帜，立汉赤帜。」令其裨将传飧，曰：「今日破赵会食！」诸将皆莫信…","q":[]},{"n":"汉室赖图书","d":"","s":"《汉书》卷五十三《萧相国世家》","w":"及高祖起为沛公，何常为丞督事。沛公至咸阳，诸将皆争走金帛财物之府分之，何独先入收秦丞相御史律令图书藏之。沛公为汉王，以何为丞相。项王与诸侯屠烧咸阳而去。汉王所以具知天下塞，户口多少，彊弱之处，民所疾苦者，以何具得秦图书也。何进言韩信，汉王…","q":[["齐侯疏土宇，汉室赖图书。","王维 故太子太师徐公挽歌四首之二"]]},{"n":"三杰","d":"","s":"《史记》卷八〈高祖本纪〉～380～","w":"高祖置酒雒阳南宫。高祖曰：「列侯诸将无敢隐朕，皆言其情。吾所以有天下者何？项氏之所以失天下者何？」高起、王陵对曰：「陛下慢而侮人，项羽仁而爱人。然陛下使人攻城略地，所降下者因以予之，与天下同利也。项羽妒贤嫉能，有功者害之，贤者疑之，战胜而不…","q":[["三贤事汉灭暴强，四贤镇岳宁边徼。","元稹 五弦弹"],["丰野光三杰，妫庭赞五臣。","任希古 和左仆射燕公春日端居述怀"]]},{"n":"画一法","d":"","s":"《史记》卷五十四《曹相国世家》","w":"参为汉相国，出入三年。卒，谥懿侯。子窋代侯。百姓歌之曰：「萧何为法，顜若画一；曹参代之，守而勿失。载其清净，民以宁一。」","q":[["因隳画一法，且逐随时利。","杜牧 感怀诗一首"]]},{"n":"剑履","d":"","s":"《史记》卷五十三〈萧相国世家〉～206～","w":"关内侯鄂君进曰：「群臣议皆误。夫曹参虽有野战略地之功，此特一时之事。夫上与楚相距五岁，常失军亡众，逃身遁者数矣。然萧何常从关中遣军补其处，非上所诏令召，而数万众会上之乏绝者数矣。夫汉与楚相守荥阳数年，军无见粮，萧何转漕关中，给食不乏。陛下虽…","q":[["尚书剑履出明光，居守旌旗赴洛阳。","刘禹锡 同乐天送令狐相公赴东都留守"],["入朝荣剑履，退食偶琴书。","宋之问 奉和幸韦嗣立山庄侍宴应制"]]},{"n":"留文","d":"","s":"《史记》卷五十五〈留侯世家〉～2042～","w":"汉六年正月，封功臣。良未尝有战斗功，高帝曰：「运筹策帷帐中，决胜千里外，子房功也。自择齐三万户。」良曰：「始臣起下邳，与上会留，此天以臣授陛下。陛下用臣计，幸而时中，臣愿封留足矣，不敢当三万户。」乃封张良为留侯，与萧何等俱封。","q":[["吟寄短篇追往事，留文功业不寻常。","翁承赞 文明殿受册封闽王"]]},{"n":"昴宿","d":"","s":"《初学记》卷一","w":"《春秋纬·佐助期》：汉相萧何，长七尺八寸，昴星精，生耳参漏，月角大形。","q":[["昴星人杰当王佐，黄石仙翁识帝师。","徐夤 尚书荣拜恩命夤疾中辄课恶诗二首以申攀赞"],["李树影笼周柱史，昴星光照汉酂侯。","徐夤 府主仆射王抟生日"]]},{"n":"人杰","d":"","s":"《史记》卷八〈高祖本纪〉～380～","w":"高祖置酒雒阳南宫。高祖曰：「列侯诸将无敢隐朕，皆言其情。吾所以有天下者何？项氏之所以失天下者何？」高起、王陵对曰：「陛下慢而侮人，项羽仁而爱人。然陛下使人攻城略地，所降下者因以予之，与天下同利也。项羽妒贤嫉能，有功者害之，贤者疑之，战胜而不…","q":[]},{"n":"萧曹","d":"","s":"《汉书》卷三十九《萧何曹参传》","w":"赞曰：萧何、曹参皆起秦刀笔吏，当时录录未有奇节。汉兴，依日月之末光，何以信谨守管籥，参与韩信俱征伐。天下既定，因民之疾秦法，顺流与之更始，二人同心，遂安海内。淮阴、黥布等已灭，唯何、参擅功名，位冠群臣，声施后世，为一代之宗臣，庆流曲裔，盛矣…","q":[["宠荣连雨露，先后比萧曹。","姚合 和郑相演杨尚书蜀中唱和诗"],["萧曹曾作沛中吏，攀龙附凤当有时。","李白 猛虎行"]]},{"n":"萧相国","d":"","s":"《史记》卷五十三《萧相国世家》","w":"萧相国何者，沛丰人也。以文无害为沛主吏掾。高祖为布衣时，何数以吏事护高祖。高祖为亭长，常左右之。高祖以吏繇咸阳，吏皆送奉钱三，何独以五。……及高祖起为沛公，何常为丞督事。沛公至咸阳，诸将皆争走金帛财物之府分之，何独先入收秦丞相御史律令图书藏…","q":[["知己酂侯在，应怜脱粟人。","刘长卿 送裴郎中贬吉州"],["夫子墙还峻，酂侯宅过谦。","姚合 和座主相公西亭秋日即事"]]},{"n":"萧何律","d":"","s":"《史记》卷五十四《曹相国世家》","w":"百姓歌之曰：「萧何为法，顜若画一；曹参代之，守而勿失。载其清净，民以宁一。」","q":[["百馀年间未灾变，叔孙礼乐萧何律。","杜甫 忆昔二首之二"]]},{"n":"萧何识故侯","d":"","s":"《史记》卷五十三《萧相国世家》","w":"淮阴侯谋反关中，吕后用萧何计，诛淮阴侯，语在淮阴事中。上已闻淮阴侯诛，使使拜丞相何为相国，益封五千户，令卒五百人一都尉为相国卫。诸君皆贺，召平独吊。召平者，故秦东陵侯。秦破，为布衣，贫，种瓜于长安城东，瓜美，故世俗谓之「东陵瓜」，从召平以为…","q":[["贾谊辞明主，萧何识故侯。","刘长卿 送李使君贬连州"]]},{"n":"萧寇","d":"","s":"《后汉书》卷十六〈邓寇列传·寇恂〉～620～","w":"寇恂字子翼，上谷昌平人也，世为著姓。恂初为郡功曹，太守耿况甚重之。……光武南定河内，而更始大司马朱鲔等盛兵据洛阳。又并州未安，光武难其守，问于邓禹曰：「诸将谁可使守河内者？」禹曰：「昔高祖任萧何于关中，无复西顾之忧，所以得专精山东，终成大业…","q":[]},{"n":"萧张","d":"","s":"《史记》卷五十三〈萧相国世家〉～2020～","w":"唐·司马贞《史记索隐述赞》：「萧何为吏，文而无害。及佐兴王，举宗从沛。关中既守，转输是赖。汉军屡疲，秦兵必会。约法可久，收图可大。指兽发踪，其功实最。政称画一，居乃非泰。继绝宠勤，式旌砺带。」","q":[]},{"n":"雄都壮丽","d":"","s":"《史记》卷八《高祖本纪》","w":"萧丞相营作未央宫，立东阙、北阙、前殿、武库、太仓。高祖还，见宫阙壮甚，怒，谓萧何曰：「天下匈匈苦战数岁，成败未可知，是何治宫室过度也？」萧何曰：「天下方未定，故可因遂就宫室。且夫天子四海为家，非壮丽无以重威，且无令后世有以加也。」高祖乃说。","q":[["雄都元壮丽，望幸歘威神。","杜甫 江陵望幸"]]}],"25":[{"n":"碍门","d":"","s":"《三国志》卷四十二《蜀书·周群传》","w":"先主无须，故（张）裕以此及之。先主常衔其不逊，加忿其漏言，乃显裕谏争汉中不验，下狱，将诛之。诸葛亮表请其罪，先主答曰：「芳兰生门，不得不锄。」裕遂弃市。","q":[["遇赏宁充佩，为生莫碍门。","张九龄 园中时蔬尽皆锄理唯秋兰数本遂赋二章之二"],["在竹惭充箭，为兰幸免锄。","张南史 早春书事奉寄中书李舍人"]]},{"n":"鞠躬尽瘁","d":"","s":"《诸葛亮集·文集》卷一〈前出师表〉","w":"清·张澍案：「《蜀志》，建兴三年，曹丕殂，明年，曹睿立。五年，丞相亮率诸军北伐魏，乃上表。」","q":[]},{"n":"瑜亮","d":"","s":"《三国演义》第五七回","w":"﹝ 瑜 ﹞长叹曰：‘既生 瑜 ，何生 亮 ！’","q":[]},{"n":"丞相柏","d":"","s":"《全唐诗》卷二百二十六〈蜀相〉【案：诸葛亮祠在昭烈庙西。】","w":"丞相祠堂何处寻，锦官城外柏森森。映阶碧草自春色，隔叶黄鹂空好音【隔叶黄鹂多好音】。三顾频烦天下计【三顾频繁天下计】，两朝开济老臣心。出师未捷身先死【出师未用身先死】，长使英雄泪满襟。","q":[]},{"n":"龙蟠虎踞","d":"","s":"《太平御览》卷一百五十六〈州郡部二·京都下〉～887～","w":"刘备曾使诸葛亮至京，因睹秣陵山阜，叹曰：「钟山龙盘，石头虎踞，此帝王之宅。」（据《太平御览》卷一五六引）","q":[["龙蟠虎踞帝王州，帝子金陵访古丘。","李白 永王东巡歌十一首之四"],["龙虎势衰佳气歇，凤皇名在故台空。","李群玉 秣陵怀古"]]},{"n":"赤壁东风","d":"","s":"《三国志》卷五十四〈吴书·周瑜传〉～262～","w":"时刘备为曹公所破，欲引南渡江，与鲁肃遇于当阳，遂共图计，因进住夏口，遣诸葛亮诣权，权遂遣瑜及程普等与备并力逆曹公，遇于赤壁。时曹公军众已有疾病，初一交战，公军败退，引次江北。瑜等在南岸。瑜部将黄盖曰：「今寇众我寡，难与持久。然观操军船舰首尾…","q":[]},{"n":"春秋责帅","d":"","s":"《三国志》卷三十五〈蜀书·诸葛亮传〉～922～","w":"臣以弱才，叨窃非据，亲秉旄钺以厉三军，不能训章明法，临事而惧，至有街亭违命之阙，箕谷不戒之失，咎皆在臣授任无方。臣明不知人，恤事多闇，《春秋》责帅，臣职是当。请自贬三等，以督厥咎。","q":[["据鞍惭齿发，责帅惧春秋。","武元衡 酬李十一尚书西亭暇日书怀见寄十二韵之作"]]},{"n":"五月渡泸","d":"","s":"《三国志》卷三十五《蜀书·诸葛亮传》","w":"「建兴元年，封亮武乡侯，开府治事。顷之，又领益州牧。政事无巨细，咸决于亮。南中诸郡，并皆叛乱，亮以新遭大丧，故未便加兵，且遣使聘吴，因结和亲，遂为与国。三年春，亮率众南征，其秋悉平。军资所出，国以富饶，乃治戎讲武，以俟大举。五年，率诸军北驻…","q":[["苏卿持节终还汉，葛相行师自渡泸。","贾岛 巴兴作"]]},{"n":"草庐三顾","d":"三顾：咏帝王爱才求贤。唐杜甫《蜀相》：“三顾频烦天下计，两朝开济老臣心。”","s":"《三国志》卷三十五〈蜀书·诸葛亮传〉～94～","w":"诸葛亮〈出师表〉：「先帝不以臣卑鄙，猥自枉屈，三顾臣于草庐之中，咨臣以当世之事。」","q":[["赤墀高崱屴，一见如三顾。","储光羲 贻王侍御出台掾丹阳"],["乏才叨八使，徇禄非三顾。","元晦 越亭二十韵"]]},{"n":"卧南阳","d":"南阳卧：指有才之士隐居家中。唐韩偓《寄隐者》：“渭滨晦迹南阳卧，若比吾徒更寂寥。”","s":"《三国志》卷三十五《蜀书·诸葛亮传》","w":"时先主屯新野。徐庶见先主，先主器之，谓先主曰：「诸葛孔明者，卧龙也，将军岂愿见之乎？」先主曰：「君与俱来。」庶曰：「此人可就见，不可屈致也。将军宜枉驾顾之。」由是先主遂诣亮，凡三往，乃见。因屏人曰：「汉室倾颓，奸臣窃命，主上蒙尘。孤不度德量…","q":[["一吟梁甫曲，知是卧龙才。","刘禹锡 和杨侍郎初至郴州纪事书情题郡斋八韵"],["早识卧龙应有分，不妨从此蹑丹梯。","刘禹锡 洛中送杨处厚入关便游蜀"]]},{"n":"葛亮贵和篇","d":"","s":"《三国志》卷三十五《蜀书·诸葛亮传》附《诸葛氏集目录》","w":"《贵和》第十一","q":[["老翁慎莫怪少年，葛亮贵和书有篇。","杜甫 赤宵行"]]},{"n":"南阳躬耕","d":"","s":"《三国志》卷三十五《蜀书·诸葛亮传》","w":"诸葛亮字孔明，琅邪阳都人也。汉司隶校尉诸葛丰后也。父圭，字君贡，汉末为太山郡丞。亮早孤，从父玄为袁术所署豫章太守，玄将亮及亮弟均之官。会汉朝更选朱皓代玄。玄素与荆州牧刘表有旧，往依之。玄卒，亮躬陇亩，好为《梁父吟》。","q":[["耻学琅琊人，龙蟠事躬耕。","李白 邺中赠王大"],["昔者琅琊子，躬耕亦慨然。","陈子昂 赠赵六贞固二首之二"]]},{"n":"管葛","d":"","s":"《世说新语》中卷下《赏誉》","w":"殷渊源在墓所几十年。于时朝野以拟管、葛，起不起，以卜江左兴亡。","q":[["自言管葛竟谁许，长吁莫错还闭关。","李白 驾去温泉后赠杨山人"],["君臣各有分，管葛本时须。","杜甫 别张十三建封"]]},{"n":"管乐","d":"","s":"《三国志》卷三十五《蜀书·诸葛亮传》","w":"亮躬耕陇亩，好为《梁父吟》。身长八尺，每自比于管仲、乐毅，时人莫之许也。惟博陵崔州平、颍川徐庶元直与亮友善，谓为信然。","q":[["自顾躬耕者，才非管乐俦。","孟浩然 与黄侍御北津泛舟"],["夫子今管乐，英才冠三军。","李白 赠何七判官昌浩"]]},{"n":"君臣鱼水","d":"","s":"《三国志》卷三十五〈蜀书·诸葛亮传〉～92～","w":"时先主屯新野。徐庶见先主，先主器之，谓先主曰：「诸葛孔明者，卧龙也，将军岂愿见之乎？」先主曰：「君与俱来。」庶曰：「此人可就见，不可屈致也。将军宜枉驾顾之。」由是先主遂诣亮，凡三往，乃见。因屏人曰：「汉室倾颓，奸臣窃命，主上蒙尘。孤不度德量…","q":[]},{"n":"梁父吟","d":"","s":"《三国志》卷三十五〈蜀书·诸葛亮传〉～9～","w":"诸葛亮字孔明，琅邪阳都人也。汉司隶校尉诸葛丰后也。父圭，字君贡，汉末为太山郡丞。亮早孤，从父玄为袁术所署豫章太守，玄将亮及亮弟均之官。会汉朝更选朱皓代玄。玄素与荆州牧刘表有旧，往依之。玄卒，亮躬耕陇亩，好为〈梁父吟〉。身长八尺，每自比于管仲…","q":[["但歌考槃诗，不学梁父吟。","吴筠 题龚山人草堂"],["蜀相吟安在，羊公碣已磨。","张九龄 登襄阳岘山"]]},{"n":"鱼水亲","d":"","s":"《三国志》卷三十五《蜀书·诸葛亮传》","w":"「亮答曰：『诚如是则霸业可成，汉室可兴矣。』先主曰：『善。』于是与亮情好日密。关羽、张飞等不悦，先主解之曰：『孤之有孔明，如鱼之有水也。愿诸君勿复言。』羽、飞乃止。」","q":[["小白鸿翼于夷吾，刘葛鱼水本无二。","李白 君道曲（梁之雅歌有五篇。今作一章。）"],["稍令社稷安，自契鱼水亲。","杜甫 别蔡十四著作"]]},{"n":"吕葛","d":"","s":"《史记》卷三十二《齐太公世家》","w":"「太公望吕尚者，东海上人。其先祖尝为四岳，佐禹平水土甚有功。虞夏之际封于吕，或封于申，姓姜氏。夏商之时，申、吕或封枝庶子孙，或为庶人，尚其后苗裔也。本姓姜氏，从其封姓，故曰吕尚。」","q":[["凄其望吕葛，不复梦周孔。","杜甫 晚登瀼上堂"]]},{"n":"星落","d":"","s":"《三国志》卷三十五《蜀书·诸葛亮传》","w":"「亮疾病，卒于军，时年五十四。」南朝宋·裴松之注引《晋阳秋》曰：「有星赤而芒角，自东北西南流，投于亮营，三投再还，往大还小。俄而亮卒。」","q":[["子夜星才落，鸿毛鼎便移。","杜牧 和野人殷潜之题筹笔驿十四韵"],["严警当寒夜，前军落大星。","杜甫 故武卫将军挽歌三首"]]},{"n":"三分","d":"","s":"《三国志》卷三十五〈蜀书·诸葛亮传〉～99～","w":"诸葛亮〈前出师表〉：「先帝创业未半而中道崩殂，今天下三分，益州疲弊，此诚危急存亡之秋也。」","q":[["功盖三分国，名成八阵图。","杜甫 八阵图"],["殊方昔三分，霸气曾间发。","杜甫 鹿头山"]]},{"n":"蜀人爱诸葛","d":"","s":"《三国志》卷三十五《蜀书·诸葛亮传》","w":"至今梁、益之民，咨述亮者，言犹在耳，虽甘棠之咏召公，郑人之歌子产，无以远譬也。","q":[["诸葛蜀人爱，文翁儒化成。","杜甫 八哀诗赠左仆射郑国公严公武"]]},{"n":"武侯","d":"","s":"《三国志》卷三十五〈蜀书·诸葛亮传〉～97～","w":"亮以丞相录尚书事，假节。张飞卒后，领司隶校尉。章武三年春，先主于永安病笃，召亮于成都，属以后事，谓亮曰：「君才十倍曹丕，必能安国，终定大事。若嗣子可辅，辅之；如其不才，君可自取。」亮涕泣曰：「臣敢竭股肱之力，效忠贞之节，继之以死！」先主又为…","q":[["天地尘昏九鼎危，大貂曾出武侯师。","吴融 敷水有丐者云是马侍中诸孙悯而有赠"],["轻财重义真公子，长策沈机继武侯。","罗邺 上东川顾尚书"]]},{"n":"武侯征南","d":"","s":"《三国志》卷三十五《蜀书·诸葛亮传》","w":"「三年春，亮率众南征，其秋悉平。」南朝宋·裴松之注引《汉晋春秋》：「亮至南中，所在战捷。闻孟获者，为夷、汉所服，募生致之。既得，使观于营陈之閒，问曰：『此军何如？』获对曰：『向者不知虚实，故败。今蒙赐观看营陈，若祇如此，即定易胜耳。』亮笑，…","q":[["为报南蛮须屏迹，不同蜀将武侯功。","胡曾 草檄答南蛮有咏"]]},{"n":"遗巾帼","d":"","s":"《晋书》卷一《宣帝纪》","w":"时朝廷以亮侨军远寇，利在急战，每命帝持重，以候其变。亮数挑战，帝不出，因遗帝巾帼妇人之饰。帝怒，表请决战，天子不许，乃遣骨鲠臣卫尉辛毗杖节为军师以制之。","q":[["丑虏安足纪，可贻帼与巾。","李白 赠张相镐二首"],["宣王请战贻巾帼，始见才吞亦气吞。","武少仪 诸葛丞相庙"]]},{"n":"诛马谡","d":"","s":"《三国志》卷三十五〈蜀书·诸葛亮传〉～922～","w":"亮身率诸军攻祁山，戎陈整齐，赏罚肃而号令明，南安、天水、安定三郡叛魏应亮，关中响震。魏明帝西镇长安，命张合拒亮，亮使马谡督诸军在前，与合战于街亭。谡违亮节度，举动失宜，大为合所破。亮拔西县千馀家，还于汉中，戮谡以谢众。","q":[["军令未闻诛马谡，捷书惟是报孙歆。","李商隐 随师东"]]}],"26":[{"n":"欧苏","d":"","s":"金王若虚《送吕鹏举赴举序》","w":"故必探《语》《孟》之渊源，撷 欧 苏 之菁英。","q":[]},{"n":"苏黄","d":"","s":"《宋史·文苑传六·黄庭坚》","w":"庭坚 于文章尤长于诗， 蜀 、 江西 君子以 庭坚 配 轼 ，故称 苏 黄 。","q":[]},{"n":"苏米","d":"","s":"清赵翼《送刘石庵相公还朝》诗","w":"馀事到挥毫， 苏 米 不足夸。","q":[]},{"n":"齑瓮","d":"","s":"《苏轼文集》卷七十三〈禄有重轻〉","w":"王状元未第时，醉堕汴河，为水神扶出，曰：「公有三百千料钱，若死于此，何处消破？」明年遂登第。士有久不第者，亦效之，阳醉落河，河神亦扶出。士大喜曰：「吾料钱几何？」神曰：「吾不知也。但三百瓮黄齑，无处消破耳。」","q":[]},{"n":"雪堂壬戌","d":"","s":"《苏轼文集》卷一〈赤壁赋〉","w":"苏子愀然，正襟危坐，而问客曰：「何为其然也？」客曰：「『月明星稀，乌鹊南飞。』此非曹孟德之诗乎？西望夏口，东望武昌。山川相缪，郁乎苍苍。此非孟德之困于周郎者乎？方其破荆州，下江陵，顺流而东也，舳舻千里，旌旗蔽空，酾酒临江，横槊赋诗，固一世之…","q":[]},{"n":"出一头","d":"出头地：指学问或地位比别人高，清卓孝复《寄郑苏龛同年》：“曾让大名出头地，独留元气护高楼。”","s":"《邵氏闻见后录》卷十四～08～","w":"欧阳公谓曾子固云：「王介甫之文，更令开廓，勿造语，及模拟前人。」又云：「孟、韩文虽高，不必似之也。」谓梅圣俞云：「读苏轼之书，不觉汗出，快哉！老夫当避路，放他出一头地也。」又曰：「轼所言乐，乃脩所得深者尔，不意后生达斯理也。」欧阳公初接二公…","q":[["曾让大名出头地，独留元气护高楼。","卓孝复 寄郑苏龛同年"]]},{"n":"春梦婆","d":"春梦婆：喻好景不长。金元好问《出都诗》之一：“神仙不到秋风客，富贵空悲春梦婆。”","s":"《侯鲭录》","w":"《侯鲭录》：东坡在昌化，负大瓢行歌田间。老姥绩谓曰：「内翰昔时富贵，一场春梦。」东坡然之。里人因呼为春梦婆。","q":[]},{"n":"东坡思肉","d":"","s":"《竹坡诗话》","w":"东坡性喜嗜猪。在黄冈时，尝戏作食猪肉诗云：「黄州好猪肉，价贱如粪土。富者不肯吃，贫者不解煮。慢著火，少著水。火候足时他自美。每日起来打一碗，饱得自家君莫管。」此是东坡以文滑稽耳。","q":[]},{"n":"花竹秀野","d":"","s":"《苏轼诗集》卷十五〈司马君实独乐园〉","w":"青山在屋上，流水在屋下。中有五亩园，花竹秀而野。花香袭杖履，竹色侵杯斝。樽酒乐馀春，棋局消长夏。洛阳古多士，风俗犹尔雅。先生卧不出，冠盖倾洛社。虽云与众乐，中有独乐者。才全德不形，所贵知我寡。先生独何事，四海望陶冶。儿童诵君实，走卒知司马。…","q":[]},{"n":"河东狮吼","d":"","s":"《苏轼诗集》卷二十五〈寄吴德仁兼简陈季常〉","w":"东坡先生无一钱，十年家火烧凡铅。黄金可成河可塞，只有霜鬓无由玄。龙丘居士亦可怜，谈空说有夜不眠。忽闻河东狮子吼，拄杖落手心茫然。谁似濮阳公子贤，饮酒食肉自得仙。平生寓物不留物，在家学得忘家禅门前罢亚十顷田，清溪绕屋花连天。溪堂醉卧呼不醒，落…","q":[]},{"n":"鹤梦雪堂舟","d":"","s":"《苏轼文集》卷一〈后赤壁赋〉","w":"时夜将半，四顾寂寥，适有孤鹤，横江东来，翅如车轮，玄裳缟衣，戛然长鸣，掠予舟而西也。须臾客去，予亦就睡，梦一道士；羽衣翩跹，过临皋之下，揖予而言曰：「赤壁之游乐乎？」问其姓名，俛而不答。呜呼噫嘻，我知之矣，畴昔之夜，飞鸣而过我者，非子也耶？…","q":[]},{"n":"二苏","d":"","s":"《豫章集》卷三〈和答子瞻和子由常父忆馆中故事〉","w":"二苏上连璧，三孔立分鼎。少小看飞腾，中年嗟远屏。风撼鹡鸰枝，波寒鸿雁影。天不椓斯文，俱来集台省。日月黄道明，桃李春昼永。时平少犴狱，地禁绝蛙黾。颇怀修故事，文会陈果茗。当时群玉府，人物殊秀整。下直马阗阗，杯盘具俄顷。共醉凌波袜，谁窥投辖井。…","q":[]},{"n":"眉山帽","d":"","s":"《苕溪渔隐丛话》前集卷四十〈东坡三〉","w":"王直方《诗话》云：东坡尝令门人辈作《人不易物赋》，或人戏作一联曰：『伏其几而升其堂，曾非孔子；袭其书而戴其帽，未是苏公。』盖元祐之初，士大夫效东坡顶短檐高桶帽，谓之子瞻样，故云。","q":[]},{"n":"眉山文翰老","d":"","s":"《栾城后集》卷二十二〈亡兄子瞻端明墓志铭〉","w":"公讳轼，姓苏，字子瞻，一字和仲，世家眉山。」「公之于文，得之于天。少与辙皆师先君，初好贾谊、陆贽书，论古今治乱，不为空言。既而读《庄子集释》，喟然叹息曰：『吾昔有见于中，口未能言，今见《庄子集释》，得吾心矣。』乃出《中庸论》，其言微妙，皆古…","q":[]},{"n":"千里赠鹅毛","d":"","s":"《苏轼诗集》卷四十九〈杨州以土物寄少游〉","w":"鲜鲫经年秘醽醁，团脐紫蟹脂填腹。后春莼茁活如酥，先社姜芽肥胜肉。鸟子累累何足道，点缀盘飧亦时欲。淮南风俗事瓶罂，方法相传竟留蓄。且同千里寄鹅毛，何用孜孜饮麋鹿。","q":[]},{"n":"三白","d":"","s":"《苏轼诗集》卷二十七〈次韵王觌正言喜雪〉","w":"圣人与天通，有诏宽狱市。好语夜喧街，湿云朝覆砌。纷然退朝后，色映宫槐媚。欲誇剪刻工，故上朱蓝袂。我方执笔侍，未敢书上瑞。君犹伏阁争，高论亦少慰。霏霏止还作，盎盎风与气。神龙久潜伏，一怒势必倍。行当见三白，拜舞欢万岁。归来饮君家，酣咏追既醉。","q":[]},{"n":"三苏","d":"","s":"《苏轼诗集》卷三十一〈次韵子由使契丹到涿州见寄四首〉其三","w":"〈次韵子由使契丹到涿州见寄四首〉其三：「毡毳年来亦甚都，时时鴃舌问三苏。那知老病浑无用，欲向君王乞镜湖。」","q":[]},{"n":"拾芥","d":"拾芥：喻极其容易。清魏源《村居杂兴十四首呈筠谷从兄》：“誓将拾芥效，偿此三馀忙。”","s":"《汉书》卷七十五〈眭两夏侯京翼李列传·夏侯胜〉～359～","w":"始，胜每讲授，常谓诸生曰：「士病不明经术；经术苟明，其取青紫如俛拾地芥耳。学经不明，不如归耕。」唐·颜师古注曰：「地芥谓草芥之横在地上者。俛而拾之，言其易而必得也。青紫，卿大夫之服也。俛即俯字也。」","q":[]},{"n":"苏仙","d":"","s":"《豫章集》卷九〈次韵宋懋宗三月十四日到西池都人盛观翰林公出遨〉","w":"金狨系马晓莺边，不比春江上水船。人语车声喧法曲，花光楼影倒晴天。人间化鹤三千岁，海上看羊十九年。还作遨头惊俗眼，风流文物属苏仙。","q":[]},{"n":"苏赵","d":"","s":"《苏轼文集》卷一〈后赤壁赋〉","w":"时夜将半，四顾寂寥，适有孤鹤，横江东来，翅如车轮，玄裳缟衣，戛然长鸣，掠予舟而西也。须臾客去，予亦就睡，梦一道士；羽衣翩跹，过临皋之下，揖予而言曰：「赤壁之游乐乎？」问其姓名，俛而不答。呜呼噫嘻，我知之矣，畴昔之夜，飞鸣而过我者，非子也耶？…","q":[]},{"n":"野狐精","d":"","s":"《宋朝事实类苑》卷三十九〈诗歌赋咏·王苏更相是非〉～508～","w":"王文公见东坡醉白堂记，徐云：『此定是韩白优劣论』，东坡闻之，曰：『不若介甫虔州学记，乃学校策耳。』二公相诮或如此，然胜处未尝不相倾慕。元祐间，东坡奉祠西太一，见公旧题：『杨柳鸣蜩绿暗，荷花落日红酣。三十六陂春水，白头想见江南。』注目久之，曰…","q":[]},{"n":"玉版句","d":"","s":"《冷斋夜话》卷七〈东坡作偈戏慈云长老又与刘器之同参玉版禅〉","w":"东坡自海南至虔上，以水涸不可舟，逗留月馀，时过慈云寺浴。长老明鉴，魁梧如所画慈恩，然丛林不以道学与之。东坡作偈戏之曰：「居士无尘堪洗沐，老师有句借宣扬。窗间但见蝇钻纸，门外时闻佛放光。遍界难藏真薄相，一丝不挂且逢场。却须重说圆通偈，千眼熏笼…","q":[]},{"n":"拄笏看西山","d":"","s":"《苏轼诗集》卷六〈次韵胡完夫〉","w":"青衫别泪尚斓斑，十载江湖困抱关。老去上书还北阙，朝来拄笏看西山。相从杯酒形骸外，笑说平生醉梦间。万事会须咨伯始，白头容我占清闲。","q":[]},{"n":"子瞻居海岛","d":"","s":"《宋史》卷三百三十八〈苏轼列传〉～086～","w":"绍圣初，御史论轼掌内外制日，所作词命，以为讥斥先朝。遂以本官知英州，寻降一官，未至，贬宁远军节度副使，惠州安置。居三年，泊然无所蒂芥，人无贤愚，皆得其欢心。又贬琼州别驾，居昌化。昌化，故儋耳地，非人所居，药饵皆无有。初僦官屋以居，有司犹谓不…","q":[]}],"27":[{"n":"郎潜","d":"白发郎潜：指年老而怀才不遇。宋苏轼《次天字韵答岑岩起》：“莫叹郎潜生白发，圣朝求旧鄙鸢肩。”","s":"《昭明文选》卷十五〈赋辛·志中·思玄赋〉～662～","w":"「尉尨眉而郎潜兮，逮三叶而遘武。」唐·李善注引《汉武故事》曰：「颜驷，不知何许人，汉文帝时为郎。至武帝，尝辇过郎署，见驷尨眉皓发，上问曰：叟何时为郎？何其老也？答曰：臣文帝时为郎。文帝好文而臣好武，至景帝好美而臣貌丑，陛下即位好少而臣已老，…","q":[["遭逢好交日，黜落至公时。","李昌符 下第后蒙侍郎示意指于新先辈宣恩感谢"],["汉家尚壮今则老，发短心长知奈何。","李端 赠康洽"]]},{"n":"一斗粟","d":"","s":"《史记》卷一百一十八〈淮南衡山列传〉～3079～","w":"尽诛所与谋者。于是乃遣淮南王，载以辎车，令县以次传。是时袁盎谏上曰：「上素骄淮南王，弗为置严傅相，以故至此。且淮南王为人刚，今暴摧折之。臣恐卒逢雾露病死。陛下为有杀弟之名，柰何！」上曰：「吾特苦之耳，今复之。」县传淮南王者皆不敢发车封。淮南…","q":[["尺布之谣，塞耳不能听。","李白 上留田行"],["汉谣一斗粟，不与淮南舂。","李白 箜篌谣"]]},{"n":"赐铜山","d":"","s":"《史记》卷一二五《佞幸列传》","w":"孝文时中宠臣，士人则邓通，宦者则赵同、北宫伯子。北宫伯子以爱人长者；而赵同以星气幸，常为文帝参乘；邓通无伎能。邓通，蜀郡南安人也，以濯船为黄头郎。孝文帝梦欲上天，不能，有一黄头郎从后推之上天，顾见其衣裻带后穿。觉而之渐台，以梦中阴目求推者郎…","q":[["欢宴瑶台镐京集，赏赐铜山蜀道移。","薛稷 奉和幸安乐公主山庄应制"]]},{"n":"大横庚","d":"","s":"《史记》卷十〈孝文本纪〉～43～","w":"丞相陈平、太尉周勃等使人迎代王。代王问左右郎中令张武等。张武等议曰：「汉大臣皆故高帝时大将，习兵，多谋诈，此其属意非止此也，特畏高帝、吕太后威耳。今已诛诸吕，新啑血京师，此以迎大王为名，实不可信。愿大王称疾毋往，以观其变。」中尉宋昌进曰：「…","q":[["如无一战霸，安有大横庚。","李商隐 送千牛李将军赴阙五十韵"]]},{"n":"分汉廷竹","d":"","s":"《汉书》卷四《文帝纪》","w":"「九月，初与郡守为铜虎符、竹使符。」汉·应劭注：「铜虎符第一至第五，国家当发兵遣使者，至郡合符，符合乃听受之。竹使符皆以竹箭五枚，长五寸，镌刻篆书，第一至第五。」唐·颜师古注：「与郡守为符者，谓各分其半，右留京师，左以与之。」","q":[["几分汉廷竹，夙拥文侯彗。","杜甫 八哀诗赠秘书监江夏李公邕"]]},{"n":"浮云骢","d":"","s":"《西京杂记》卷二～075～2～","w":"文帝自代还，有良马九匹，皆天下之骏马也。一名浮云，一名赤电，一名绝群，一名逸骠，一名紫燕骝，一名绿螭骢，一名龙子，一名麟驹，一名绝尘，号为九逸，有来宣能御，代王号为王良，俱还代邸。","q":[["好乘浮云骢，佳期兰渚东。","李白 长干行二首之二"]]},{"n":"邯郸道","d":"","s":"《汉书》卷五十《张释之传》","w":"「从行至霸陵，上居外临厕。时慎夫人从，上指视慎夫人新丰道，曰：『此走邯郸道也。』」三国魏·张晏注：「慎夫人，邯郸人也。」","q":[["设备邯郸道，和亲逻些城。","杜甫 柳司马至"]]},{"n":"汉文遗美","d":"","s":"《史记》卷十《孝文本纪》","w":"尝欲作露台，召匠计之，直百金。上曰：「百金中民十家之产，吾奉先帝宫室，常恐羞之，何以台为！」","q":[["汉文有遗美，对此清飙生。","司马扎 筑台"]]},{"n":"汉主思李牧","d":"","s":"《史记》卷一○二《冯唐列传》","w":"上（汉文帝）既闻廉颇、李牧为人，良说，而搏髀曰：「嗟乎！吾独不得廉颇、李牧时为吾将，吾岂忧匈奴哉！」（冯）唐曰：「主臣！陛下虽得廉颇、李牧，弗能用也。」","q":[["汉主岂劳思李牧，赵王犹是用廉颇。","雍陶 罢还边将"]]},{"n":"河上公","d":"","s":"晋·葛洪《神仙传》卷三《河上公》","w":"汉文帝往见河上公，「公既抚掌坐跃，冉冉在虚空中，去地数丈，俯仰而答曰：『予上不至天，中不累人，下不居地。何民臣之有？』帝乃下车稽首。……公乃授素书二卷与帝，曰：『……勿以示非其人。』言毕失其所在。须臾云雾晦冥，天地泯合。帝甚贵之。论者以为文…","q":[["关门令尹谁能识，河上仙翁去不回。","崔曙 九日登望仙台呈刘明府容"],["河上喜相得，壶中趣每同。","李白 赠卢徵君昆弟"]]},{"n":"化人汉文帝","d":"","s":"《汉书》卷四〈文帝纪〉～34～","w":"赞曰：孝文皇帝即位二十三年，宫室苑囿车骑服御无所增益。有不便，辄弛以利民。尝欲作露台，召匠计之，直百金。上曰：「百金，中人十家之产也。吾奉先帝宫室，常恐羞之，何以台为！」身衣弋绨，所幸慎夫人衣不曳地，帷帐无文绣，以示敦朴，为天下先。治霸陵，…","q":[["以德化人汉文帝，侧身修道周宣王。","杜牧 皇风"]]},{"n":"经传拱汉皇","d":"","s":"晋·葛洪《神仙传》卷三《河上公》","w":"公结草为庵于河之滨。帝读《老子经》颇好之，敕诸王及大臣皆颂之，有所不解数事，时人莫能道之。闻时皆称河上公解《老子经》义旨，乃使所不决之事以问。公曰：「道尊德贵，非可遥问也。」帝即幸其庵躬问之……公乃授《素书》二卷与帝，曰：「熟研之，此经所疑…","q":[["身退卑周室，经传拱汉皇。","杜甫 冬日洛城北谒玄元皇帝庙"]]},{"n":"迎代邸","d":"","s":"《汉书》卷四《文帝纪》","w":"高后崩，诸吕谋为乱，欲危刘氏。丞相陈平、太尉周勃、朱虚侯刘章等共诛之，谋立代王。语在高后纪、高五王传。……遂即天子位。群臣以次侍。使太仆婴、东牟侯兴居先清宫，奉天子法驾迎代邸。皇帝即日夕入未央宫。","q":[["事殊迎代邸，喜异赏朱虚。","杜甫 赠李八秘书别三十韵"],["旧居从代邸，新陇入文园。","皇甫冉 故齐王赠承天皇帝挽歌"]]},{"n":"梁王傅","d":"","s":"《史记》卷八十四《贾生列传》","w":"后岁馀，贾生徵见。孝文帝方受釐，坐宣室。上因感鬼神事，而问鬼神之本。贾生因具道所以然之状。至夜半，文帝前席。既罢，曰：「吾久不见贾生，自以为过之，今不及也。」居顷之，拜贾生为梁怀王太傅。梁怀王，文帝之少子，爱，而好书，故令贾生傅之。","q":[["惆怅长岑长，寂寞梁王傅。","储光羲 贻王侍御出台掾丹阳"]]},{"n":"龙种","d":"","s":"《史记》卷四十九《外戚世家》","w":"汉王入织室，见薄姬有色，诏内后宫，岁馀不得幸。始姬少时，与管夫人、赵子儿相爱，约曰：「先贵无相忘。」已而管夫人、赵子儿先幸汉王。汉王坐河南宫成皋台，此两美人相与笑薄姬初时约。汉王闻之，问其故，两人具以实告汉王。汉王心惨然，怜薄姬，是日召而幸…","q":[["寄人龙种瘦，失母凤雏痴。","李商隐 杨本胜说于长安见小男阿衮"],["世上苍龙种，人间武帝孙。","李商隐 鄠杜马上念汉书一云五陵怀古"]]},{"n":"露台百金","d":"","s":"《史记》卷十《孝文本纪》","w":"孝文帝从代来，即位二十三年，宫室苑囿狗马服御无所增益，有不便，辄弛以利民。尝欲作露台，召匠计之，直百金。上曰：「百金中民十家之产，吾奉先帝宫室，常恐羞之，何以台为！」","q":[["汉文宜惜露台费，晋武须焚前殿裘。","沈佺期 七夕曝衣篇"],["苍生偃卧休征战，露台百金以为费。","高适 古歌行"]]},{"n":"求衣","d":"","s":"《汉书》卷五十一《邹阳传》","w":"「始孝文皇帝据关入立，寒心销志，不明求衣。」晋·臣瓒曰：「文帝入关而立，以天下多难，故乃寒心战慄，未明而起。」","q":[["履朔求衣早，临阳解佩羞。","徐夤 依御史温飞卿华清宫二十二韵"]]},{"n":"赏朱虚","d":"","s":"《史记》卷五十二《齐悼惠王世家》","w":"城阳景王章，齐悼惠王子，以朱虚侯与大臣共诛诸吕，而章身首先斩相国吕王产于未央宫。孝文帝既立，益封章二千户，赐金千斤。孝文二年，以齐之城阳郡立章为城阳王。立二年卒，子喜立，是为共王。","q":[["事殊迎代邸，喜异赏朱虚。","杜甫 赠李八秘书别三十韵"]]},{"n":"上空虚","d":"","s":"晋·葛洪《神仙传》卷三《河上公》","w":"汉文帝往见河上公，「公既抚掌坐跃，冉冉在虚空中，去地数丈，俯仰而答曰：『予上不至天，中不累人，下不居地。何民臣之有？』帝乃下车稽首。」","q":[["君恩深汉帝，且莫上空虚。","王维 和尹谏议史馆山池"]]},{"n":"文帝却马","d":"","s":"《汉书》卷六十四下〈严朱吾丘主父徐严终王贾列传·贾捐之〉～2832～","w":"至孝文皇帝，闵中国未安，偃武行文，则断狱数百，民赋四十，丁男三年而一事。时有献千里马者，诏曰：「鸾旗在前，属车在后，吉行日五十里，师行三十里，朕乘千里之马，独先安之？」于是还马，与道里费，而下诏曰：「朕不受献也，其令四方毋求来献。」当此之时…","q":[["文帝却之不肯乘，千里马去汉道兴。","白居易 八骏图"]]},{"n":"文景","d":"","s":"《汉书》卷五〈景帝纪〉～53～","w":"赞曰：孔子称「斯民，三代之所以直道而行也」，信哉！周秦之敝，罔密文峻，而奸轨不胜。汉兴，扫除烦苛，与民休息。至于孝文，加之以恭俭，孝景遵业，五六十载之间，至于移风易俗，黎民醇厚。周云成康，汉言文景，美矣！","q":[]},{"n":"一抔土","d":"","s":"《汉书》卷五十《张释之传》","w":"「其后人有盗高庙座前玉环，得，文帝怒，下廷尉治。案盗宗庙服御物者为奏，当弃市。上大怒曰：『人亡道，乃盗先帝器！吾属廷尉者，欲致之族，而君以法奏之，非吾所以共承宗庙意也。』释之免冠顿首谢曰：『法如是足也。且罪等，然以逆顺为基。今盗宗庙器而族之…","q":[["秦为三月火，汉乃一抔土。","权德舆 早夏青龙寺致斋凭眺感物因书十四韵"],["可怜贞质无今古，可叹隋陵一抔土。","卢纶 栖岩寺隋文帝马脑盏歌"]]},{"n":"紫燕","d":"","s":"《西京杂记》卷二","w":"文帝自代还。有良马九匹。皆天下之骏马也。一名浮云、一名赤电、一名绝群、一名逸骠、一名紫燕骝、一名绿螭骢、一名龙子、一名麟驹、一名绝尘、号为九逸、","q":[["中军留醉河阳城，娇嘶紫燕踏花行。","李贺 贵主征行乐"],["紫燕自超诣，翠駮谁剪剔。","杜甫 夜听许十损诵诗爱而有作"]]}],"28":[{"n":"武安君","d":"","s":"《史记》卷七十三〈白起王剪列传·白起〉～233～","w":"白起者，郿人也。善用兵，事秦昭王。昭王十三年，而白起为左庶长，将而击韩之新城。是岁，穰侯相秦，举任鄙以为汉中守。其明年，白起为左更，攻韩、魏于伊阙，斩首二十四万，又虏其将公孙喜，拔五城。起迁为国尉。涉河取韩安邑以东，到乾[河。明年，白起为大…","q":[["卫青谩作大将军，白起真成一竖子。","李白 述德兼陈情上哥舒大夫"],["西羌延国讨，白起佐军威。","李白 送白利从金吾董将军西征"]]},{"n":"蓬梗","d":"梗泛：喻指漂泊无定所。唐骆宾王《浮搓》：“似舟漂不定，如梗泛何从？”","s":"《战国策》卷十八〈赵策一·苏秦说李兑〉～603～","w":"苏秦说李兑曰：「雒阳乘轩车苏秦，家贫亲老，无罢车驽马，桑轮蓬箧羸，负书担橐，触尘埃，蒙霜露，越漳、河，足重茧，日百而舍，造外阙，愿见于前，口道天下之事。」李兑曰：「先生以鬼之言见我则可，若以人之事，兑尽知之矣。」苏秦对曰：「臣固以鬼之言见…","q":[["旧业丛台废苑东，几年为梗复为蓬。","刘言史 泊花石浦"],["旅食伤飘梗，岩栖忆采薇。","刘长卿 罢摄官后将还旧居留辞李侍御"]]},{"n":"黄金尽","d":"季子裘：咏人奔波劳碌。唐杜甫《摇落》：“鹅费羲之墨，貂除季子裘。”","s":"《战国策》卷三〈秦策一·苏秦始将连横〉～85～","w":"说秦王书十上而说不行。黑貂之裘弊，黄金百斤尽，资用乏绝，去秦而归。羸縢履蹻，负书担橐，形容枯槁，面目犁黑，状有归色。归至家，妻不下纴，嫂不为炊，父母不与言。苏秦喟叹曰：「妻不以我为夫，嫂不以我为叔，父母不以我为子，是皆秦之罪也。」乃夜发书，…","q":[["弊貂不称芙蓉幕，衰朽仍惭玳瑁簪。","吴仁壁 投谢钱武肃"],["铜梁剑阁几区区，十上探珠不见珠。","唐求 伤张玖秀才"]]},{"n":"玉桂","d":"","s":"《战国策》卷十六〈楚策三·苏秦之楚三日〉～538～","w":"苏秦之楚，三日乃得见乎王。谈卒，辞而行。楚王曰：「寡人闻先生，若闻古人。今先生乃不远千里而临寡人，曾不肯留，愿闻其说。」对曰：「楚国之食贵于玉，薪贵于桂，谒者难得见如鬼，王难得见如天帝。今令臣食玉炊桂，因鬼见帝。」王曰：「先生就舍，寡人闻命…","q":[["粮薪极桂玉，大道生榛刺。","李群玉 登宜春醉宿景星寺寄郑判官兼简空上人"],["冰霜想度商于冻，桂玉愁居帝里贫。","李群玉 金塘路中"]]},{"n":"刺股","d":"刺股：指勤学苦读。宋王安石《酬慕容员外》：“吹毛未识腰间剑，刺股犹藏袖里锥。”","s":"《战国策》卷三〈秦策一·苏秦始将连横〉～85～","w":"说秦王书十上而说不行。黑貂之裘弊，黄金百斤尽，资用乏绝，去秦而归。羸縢履蹻，负书担橐，形容枯槁，面目黧黑，状有归色。归至家，妻不下，嫂不为炊，父母不与言。苏秦喟叹曰：「妻不以我为夫，嫂不以我为叔，父母不以我为子，是皆秦之罪也。」乃夜发书，…","q":[["囊疏萤易透，锥钝股多坑。","元稹 答姨兄胡灵之见寄五十韵"],["刺股情方励，偷光思益深。","孟简 惜分阴"]]},{"n":"二顷田","d":"二顷田：指供温饱的田产，或用作归隐之词。元萨都刺《上赵凉国公》；“笑辞天上九鼎贵，来种江东二顷田。”","s":"《史记》卷六十九〈苏秦列传〉～226～","w":"北报赵王，乃行过雒阳，车骑辎重，诸侯各发使送之甚众众，疑于王者。周显王闻之恐惧，除道，使人郊劳。苏秦之昆弟妻嫂侧目不敢仰视，俯伏侍取食。苏秦笑谓其嫂曰：「何前倨而后恭也？」嫂委蒲服，以面掩地而谢曰：「见季子位高金多也。」苏秦喟然叹曰：「此…","q":[["负郭无良田，屈身徇微禄。","岑参 郡斋閒坐"],["未展干时策，徒抛负郭田。","温庭筠 感旧陈情五十韵献淮南李仆射"]]},{"n":"负书","d":"","s":"《战国策》卷三《秦策一》","w":"「说秦王书十上而说不行。黑貂之裘弊，黄金百斤尽，资用乏绝，去秦而归。羸縢履蹻，负书担橐，形容枯槁，面目犁黑，状有归色。」","q":[["负书犹在汉，怀策未闻秦。","陈子昂 送梁李二明府"]]},{"n":"韩王剑","d":"","s":"《史记》卷六十九《苏秦列传》","w":"于是说韩宣王曰：「韩北有巩、成皋之固，西有宜阳、商阪之塞，东有宛、穰、洧水，南有陉山，地方九百馀里，带甲数十万，天下之彊弓劲弩皆从韩出。……不战而地已削矣。臣闻鄙谚曰：『宁为鸡口，无为牛后。』今西面交臂而臣事秦，何异于牛后乎？夫以大王之贤，…","q":[["凄断韩王剑，生死濯公罗。罗悲翟公意，剑负韩王气。","骆王 夏日游德州赠高四"]]},{"n":"黄金印","d":"","s":"《史记》卷六十九〈苏秦列传〉","w":"于是资苏秦车马金帛以至赵。而奉阳君已死，即因说赵肃侯曰：「天下卿相人臣及布衣之士，皆高贤君之行义，皆愿奉教陈忠于前之日久矣。虽然，奉阳君妒而君不任事，是以宾客游士莫敢自尽于前者。今奉阳君捐馆舍，君乃今复与士民相亲也，臣故敢进其愚虑。……臣闻…","q":[["题桥每念相如志，佩印当期季子荣。","杜荀鹤 遣怀"],["腰间尽解苏秦印，波上虚迎范蠡船。","王铎 罢都统守镇滑州作"]]},{"n":"虎狼都","d":"","s":"《史记》卷六十九《苏秦列传》","w":"夫秦，虎狼之国也，有吞天下之心。秦，天下之仇雠也。","q":[["谶归龙凤质，威定虎狼都。","杜甫 行次昭陵"]]},{"n":"鸡口","d":"","s":"《战国策》卷二十六〈韩一·苏秦为楚合从说韩王〉～930～","w":"苏秦为楚合从说韩王曰：「韩北有巩、洛、成皋之固，西有宜阳、常阪之塞，东有宛、穰、洧水，南有陉山，地方千里，带甲数十万。天下之强弓劲弩，皆自韩出。溪子、少府时力、距来，皆射六百步之外。韩卒超足而射，百发不暇止，远者达胸，近者掩心。韩卒之剑戟，…","q":[["那能作牛后，更拟助洪基。","元稹 酬翰林白学士代书一百韵"],["宦情哂鸡口，世路倦羊肠。","窦群 东山月下怀友人"]]},{"n":"苏季子","d":"","s":"《史记》卷六十九〈苏秦列传〉～2277～","w":"太史公曰：苏秦兄弟三人，皆游说诸侯以显名，其术长于权变。而苏秦被反閒以死，天下共笑之，讳学其术。然世言苏秦多异，异时事有类之者皆附之苏秦。夫苏秦起闾阎，连六国从亲，此其智有过人者。吾故列其行事，次其时序，毋令独蒙恶声焉。","q":[["贪名笑吴起，说国叹苏秦。","唐彦谦 客中感怀"],["季子祸从怜富贵，颜生道在乐箪瓢。","李咸用 依韵修睦上人山居十首"]]},{"n":"六百步","d":"","s":"《史记》卷六十九《苏秦列传》","w":"于是说韩宣王曰：「韩北有巩、成皋之固，西有宜阳、商阪之塞，东有宛、穰、洧水，南有陉山，地方九百馀里，带甲数十万，天下之彊弓劲弩皆从韩出。溪子、少府时力、距来者，皆射六百步之外。」","q":[["苏秦六百步，持此说韩王。","李峤 弩"]]},{"n":"苏鬼","d":"苏鬼：指谒客。唐骆宾王《在江南赠宋五之间》：“李仙非易托，苏鬼尚难因。”","s":"《战国策》卷十六《楚策三》","w":"「苏秦之楚，三日乃得见乎王。谈卒，辞而行。楚王曰：『寡人闻先生，若闻古人。今先生乃不远千里而临寡人，曾不肯留，愿闻其说。』对曰：『楚国之食贵于玉，薪贵于桂，谒者难得见如鬼，王难得见如天帝。今令臣食玉炊桂，因鬼见帝。』」","q":[["李仙非易托，苏鬼尚难因。","骆宾王 在江南赠宋五之问"]]},{"n":"苏秦学","d":"","s":"《战国策》卷三〈秦策一·苏秦始将连横〉～85～","w":"说秦王书十上而说不行。黑貂之裘弊，黄金百斤尽，资用乏绝，去秦而归。羸縢履蹻，负书担橐，形容枯槁，面目犁黑，状有归色。归至家，妻不下纴，嫂不为炊，父母不与言。苏秦喟叹曰：「妻不以我为夫，嫂不以我为叔，父母不以我为子，是皆秦之罪也。」乃夜发书，…","q":[]},{"n":"苏张","d":"","s":"《史记》卷六十九〈苏秦列传〉～224～","w":"苏秦者，东周雒阳人也。东事师于齐，而习之于鬼谷先生。……苏秦既约六国从亲，归赵，赵肃侯封为武安君，乃投从约书于秦。秦兵不敢窥函谷关十五年。","q":[]},{"n":"苏张舌","d":"","s":"《史记》卷六十九《苏秦列传》","w":"「出游数岁，大困而归。兄弟嫂妹妻妾窃皆笑之，曰：『周人之俗，治产业，力工商，逐什二以为务。今子释本而事口舌，困，不亦宜乎！』苏秦闻之而惭。」","q":[["却假苏张舌，高誇周宋镡。","杜甫 风疾舟中伏枕书怀三十六韵奉呈湖南亲友"],["非故败他却成此，苏张终作多言鬼。","武元衡 行路难"]]},{"n":"天府","d":"","s":"《战国策》卷三〈秦策一·苏秦始将连横〉～78～","w":"苏秦始将连横说秦惠王曰：「大王之国，西有巴、蜀、汉中之利，北有胡貉、代马之用，南有巫山、黔中之限，东有肴、函之固。田肥美，民殷富，战车万乘，奋击百万，沃野千里，蓄积饶多，地势形便，此所谓天府，天下之雄国也。以大王之贤，士民之众，车骑之用，兵…","q":[]},{"n":"万乘相","d":"","s":"《汉书》卷六十五〈东方朔列传〉～2864～","w":"客难东方朔曰：「苏秦、张仪一当万乘之主，而都卿相之位，泽及后世。今子大夫修先王之术，慕圣人之义，讽诵诗书百家之言，不可胜数，著于竹帛，唇腐齿落，服膺而不释，好学乐道之效，明白甚矣；自以智能海内无双，则可谓博闻辩智矣。然悉力尽忠以事圣帝，旷日…","q":[["誓耕十亩田，不取万乘相。","韩愈 岳阳楼别窦司直"]]},{"n":"下机迎","d":"","s":"《战国策》卷三《秦策一》","w":"苏秦说秦王书十上而说不行。黑貂之裘弊，黄金百斤尽，资用乏绝，去秦而归。……归至家，妻不下，嫂不为炊，父母不与言。","q":[["借问还家何处好，玉人含笑下机迎。","钱起 送张参及第还家"]]},{"n":"阴揣","d":"","s":"《史记》卷六十九《苏秦列传》","w":"「于是得周书《阴符》，伏而读之。期年，以出揣摩，曰：『此可以说当世之君矣。』」","q":[["穰侯或见迟，苏生得阴揣。","张九龄 咏史"]]},{"n":"滞秦","d":"","s":"《史记》卷六十九《苏秦列传》","w":"乃西至秦。秦孝公卒。说惠王曰：「秦四塞之国，被山带渭，东有关河，西有汉中，南有巴蜀，北有代马，此天府也。以秦士民之众，兵法之教，可以吞天下，称帝而治。」秦王曰：「毛羽未成，不可以高蜚；文理未明，不可以并兼。」方诛商鞅，疾辩士，弗用。乃东之赵…","q":[["游秦复滞燕，不觉近衰年。","许棠 冬杪归陵阳别业五首之五"],["虚抛南楚滞西秦，白首依前衣白身。","许棠 献独孤尚书"]]},{"n":"纵横","d":"","s":"汉·扬雄《法言》卷十一《渊骞》","w":"仪、秦学乎鬼谷术而习乎纵横言，安中国者各十馀年。","q":[["二贤纵横器，久滞徒劳职。","刘长卿 对雨赠济阴马少府考城蒋少府兼献成武五兄南华二兄"],["纵横济时意，跌宕过人迹。","刘长卿 送元八游汝南"]]}],"29":[{"n":"八难","d":"","s":"《汉书》卷一上〈高帝纪上〉～39～","w":"食其欲立六国后以树党，汉王刻印，将遣食其立之。以问张良，良发八难。汉王辍饭吐哺，曰：「竖儒几败乃公事！」令趋销印。","q":[["八难掉舌枢，三略役心机。","白居易 答四皓庙"]]},{"n":"沧海君","d":"博浪飞椎：喻报仇雪恨。清朱彝尊《彭城道中咏古二首》之二：“博浪飞椎后，圯桥进履车。”","s":"《史记》卷五十五〈留侯世家〉～2033～","w":"留侯张良者，其先韩人也。大父开地，相韩昭侯、宣惠王、襄哀王。父平，相釐王、悼惠王。悼惠王二十三年，平卒。卒二十岁，秦灭韩。良年少，未宦事韩。韩破，良家僮三百人，弟死不葬，悉以家财求客刺秦王，为韩报仇，以大父、父五世相韩故。良尝学礼淮阳。东见…","q":[["金槌击政后，玉斗碎增前。","徐九皋 咏史"],["博浪飞椎后，圯桥进履车。","朱彝尊 彭城道中咏古二首之二"]]},{"n":"成羽翼","d":"","s":"《史记》卷五十五〈留侯世家〉～2046～","w":"汉十二年，上从击破布军归，疾益甚，愈欲易太子。留侯谏，不听，因疾不视事。叔孙太傅称说引古今，以死争太子。上详许之，犹欲易之。及燕，置酒，太子侍。四人从太子，年皆八十有馀，须眉皓白，衣冠甚伟。上怪之，问曰：「彼何为者？」四人前对，各言名姓，曰…","q":[]},{"n":"松乔","d":"","s":"《搜神记》卷一～","w":"赤松子者，神农时雨师也，服冰玉散，以教神农，能入火不烧。至昆崙山，常入西王母石室中，随风雨上下。炎帝少女追之，亦得仙，俱去。至高辛时，复为雨师，游人间。今之雨师本是焉。","q":[["自有园公紫芝侣，仍追少傅赤松游。","刘禹锡 自左冯归洛下酬乐天兼呈裴令公"],["向夕便思青琐拜，近年寻伴赤松游。","姚合 使两浙赠罗隐"]]},{"n":"帝王师","d":"取履：指尊老受教。宋陆游《霜天杂兴》：“毂城黄石今安在，取履犹思效子房。”","s":"《史记》卷五十五〈留侯世家〉～2034～","w":"良尝閒从容步游下邳圯上，有一老父，衣褐，至良所，直堕其履圯下，顾谓良曰：「孺子，下取履！」良鄂然，欲殴之。为其老，彊忍，下取履。父曰：「履我！」良业为取履，因长跪履之。父以足受，笑而去。良殊大惊，随目之。父去里所，复还，曰：「孺子可教矣。后…","q":[["黄石履看堕，洪崖肩可拍。","刘禹锡 游桃源一百韵"],["兵符今奉黄公略，书殿曾随翠凤翔。","刘禹锡 郡内书情献裴侍中留守"]]},{"n":"三杰","d":"","s":"《史记》卷八〈高祖本纪〉～380～","w":"高祖置酒雒阳南宫。高祖曰：「列侯诸将无敢隐朕，皆言其情。吾所以有天下者何？项氏之所以失天下者何？」高起、王陵对曰：「陛下慢而侮人，项羽仁而爱人。然陛下使人攻城略地，所降下者因以予之，与天下同利也。项羽妒贤嫉能，有功者害之，贤者疑之，战胜而不…","q":[["三贤事汉灭暴强，四贤镇岳宁边徼。","元稹 五弦弹"],["丰野光三杰，妫庭赞五臣。","任希古 和左仆射燕公春日端居述怀"]]},{"n":"鸿门","d":"","s":"《史记》卷七《项羽本纪》","w":"沛公旦日从百馀骑来见项王，至鸿门，谢曰：「臣与将军戮力而攻秦，将军战河北，臣战河南，然不自意能先入关破秦，得复见将军于此。今者有小人之言，令将军与臣有却。」项王曰：「此沛公左司马曹无伤言之；不然，籍何以至此。」项王即日因留沛公与饮。项王、项…","q":[["佐汉解鸿门，生唐为后身。","李白 赠张相镐二首之一"]]},{"n":"护汉储","d":"","s":"《汉书》卷四十《张良传》","w":"「汉十二年，上从破布归，疾益甚，愈欲易太子。良谏不听，因疾不视事。叔孙太傅称说引古，以死争太子。上阳许之，犹欲易之。及宴，置酒，太子侍。四人者从太子，年皆八十有馀，须眉皓白，衣冠甚伟。上怪，问曰：『何为者？』四人前对，各言其姓名。上乃惊曰：…","q":[["汉宫成羽翼，伊水弄参差。","储光羲 河中望鸟滩作贻吕四郎中"],["卒能匡惠帝，岂不赖留侯。","张说 赠崔公"]]},{"n":"张良烧栈","d":"","s":"《史记》卷五十五《留侯世家》","w":"汉元年正月，沛公为汉王，王巴蜀。汉王赐良金百溢，珠二斗，良具以献项伯。汉王亦因令良厚遗项伯，使请汉中地。项王乃许之，遂得汉中地。汉王之国，良送至褒中，遣良归韩。良因说汉王曰：「王何不烧绝所过栈道，示天下无还心，以固项王意。」乃使良还。行，烧…","q":[["黥布开关，张良烧栈。","李瀚 蒙求"]]},{"n":"蹑足封王","d":"","s":"《史记》卷九十二〈淮阴侯列传〉～262～","w":"汉四年，遂皆降平齐。使人言汉王曰：「齐伪诈多变，反覆之国也，南边楚，不为假王以镇之，其势不定。愿为假王便。」当是时，楚方急围汉王于荥阳，韩信使者至，发书，汉王大怒，骂曰：「吾困于此，旦暮望若来佐我，乃欲自立为王！」张良、陈平蹑汉王足，因附耳…","q":[]},{"n":"借前筹","d":"借箸：喻指谋划。唐杜牧《河惶》：“元载相公曾惜箸，宪宗皇帝亦留神。”","s":"《史记》卷五十五〈留侯世家〉～2040～","w":"汉三年，项羽急围汉王荥阳，汉王恐忧，与郦食其谋桡楚权。食其曰：「昔汤伐桀，封其后于杞。武王伐纣，封其后于宋。今秦失德弃义，侵伐诸侯社稷，灭六国之后，使无立锥之地。陛下诚能复立六国后世，毕已受印，此其君臣百姓必皆戴陛下之德，莫不乡风慕义，愿为…","q":[["元载相公曾借箸，宪宗皇帝亦留神。","杜牧 河湟"],["前筹自多暇，隐几接终朝。","杜甫 哭王彭州抡"]]},{"n":"君臣际会","d":"","s":"《论衡校释》卷三〈偶会第十〉～07～","w":"因此论圣贤迭起，犹此类也。圣主龙兴于仓卒，良辅超拔于际会。世谓韩信、张良辅助汉王，故秦灭汉兴，高祖得王。","q":[]},{"n":"留侯","d":"","s":"《史记》卷五十五《留侯世家》","w":"汉六年正月，封功臣。良未尝有战斗功，高帝曰：「运筹策帷帐中，决胜千里外，子房功也。自择齐三万户。」良曰：「始臣起下邳，与上会留，此天以臣授陛下。陛下用臣计，幸而时中，臣愿封留足矣，不敢当三万户。」乃封张良为留侯，与萧何等俱封。","q":[["留侯万户虽无分，病骨应消一片山。","司空图 偶作"],["山甫归应疾，留侯功复成。","张九龄 奉和圣制送尚书燕公赴朔方"]]},{"n":"留侯辟谷","d":"","s":"《史记》卷五十五〈留侯世家〉～2047～","w":"留侯从上击代，出奇计马邑下，及立萧何相国，所与上从容言天下事甚众众，非天下所以存亡，故不著。留侯乃称曰：「家世相韩，及韩灭，不爱万金之资，为韩报雠彊秦，天下振动。今以三寸舌为帝者师，封万户，位列侯，此布衣之极，于良足矣。愿弃人閒事，欲从赤松…","q":[["留侯却粒商翁去，甲第何人意气归。","司空图 有感二首之一"],["留侯常辟谷，何苦不长生。","王维 故太子太师徐公挽歌四首之一"]]},{"n":"留侯疾","d":"","s":"《史记》卷五十五〈留侯世家〉～2044～","w":"留侯从入关。留侯性多病，即道引不食谷，杜门不出岁馀。","q":[["未谢留侯疾，常怀仲蔚园。","李德裕 余所居平泉村舍近蒙韦常侍大尹特改嘉名因寄诗以谢"]]},{"n":"留侯貌","d":"","s":"《史记》卷五十五〈留侯世家〉～2049～","w":"太史公曰：学者多言无鬼神，然言有物。至如留侯所见老父予书，亦可怪矣。高祖离困者数矣，而留侯常有功力焉，岂可谓非天乎？上曰：「夫运筹筴帷帐之中，决胜千里外，吾不如子房。」余以为其人计魁梧奇伟，至见其图，状貌如妇人好女。盖孔子曰：「以貌取人，失…","q":[]},{"n":"留文","d":"","s":"《史记》卷五十五〈留侯世家〉～2042～","w":"汉六年正月，封功臣。良未尝有战斗功，高帝曰：「运筹策帷帐中，决胜千里外，子房功也。自择齐三万户。」良曰：「始臣起下邳，与上会留，此天以臣授陛下。陛下用臣计，幸而时中，臣愿封留足矣，不敢当三万户。」乃封张良为留侯，与萧何等俱封。","q":[["吟寄短篇追往事，留文功业不寻常。","翁承赞 文明殿受册封闽王"]]},{"n":"人杰","d":"","s":"《史记》卷八〈高祖本纪〉～380～","w":"高祖置酒雒阳南宫。高祖曰：「列侯诸将无敢隐朕，皆言其情。吾所以有天下者何？项氏之所以失天下者何？」高起、王陵对曰：「陛下慢而侮人，项羽仁而爱人。然陛下使人攻城略地，所降下者因以予之，与天下同利也。项羽妒贤嫉能，有功者害之，贤者疑之，战胜而不…","q":[]},{"n":"烧栈","d":"","s":"《史记》卷五十五《留侯世家》","w":"汉王之国，良送至褒中，遣良归韩。良因说汉王曰：「王何不烧绝所过栈道，示天下无还心，以固项王意。」乃使良还。行，烧绝栈道。","q":[["牢落新烧栈，苍茫旧筑坛。","杜甫 王命"],["朝廷烧栈北，鼓角满天东。","杜甫 陪章留后侍御宴南楼"]]},{"n":"碎玉斗","d":"","s":"《史记》卷七《项羽本纪》","w":"张良入谢，曰：「沛公不胜杯杓，不能辞。谨使臣良奉白璧一双，再拜献大王足下；玉斗一双，再拜奉大将军足下。」项王曰：「沛公安在？」良曰︰「闻大王有意督过之，脱身独去，已至军矣。」项王则受璧，置之坐上。亚父受玉斗，置之地，拔剑撞而破之，曰：「唉！…","q":[["忆昔范增碎玉斗，未使吴兵著白袍。","杜甫 久雨期王将军不至"]]},{"n":"养虎","d":"","s":"《史记》卷七《项羽本纪》","w":"汉欲西归，张良、陈平说曰：「汉有天下太半，而诸侯皆附之。楚兵罢食尽，此天亡楚之时也，不如因其机而遂取之。今释弗击，此所谓『养虎自遗患』也。」","q":[["嗾獒翻丑正，养虎欲求全。","韩偓 感事三十四韵"]]},{"n":"张邴","d":"","s":"《昭明文选》卷二十五南朝宋·谢灵运《还旧园作见颜范二中书》","w":"「偶与张邴合，久欲还东山。」唐·李善注：「《汉书》，张良曰：今以三寸舌为帝师，封万户，位列侯，此布衣之极，于良足矣。愿弃人间事，欲从赤松子学道轻举。又曰：琅邪邴汉亦有清行，兄子曼容亦养志自脩，为官不肯过六百石，辄自免去。」","q":[["张邴卧来休送客，菊花枫叶向谁秋。","司空曙 过阎采病居"],["劳生愧严郑，外物慕张邴。","杜甫 渼陂西南台"]]},{"n":"张子房","d":"","s":"《史记》卷五十五〈留侯世家〉～2036～","w":"后十年，陈涉等起兵，良亦聚少年百馀人。景驹自立为楚假王，在留。良欲往从之，道还沛公。沛公将数千人，略地下邳西，遂属焉。沛公拜良为厩将。良数以太公兵法说沛公，沛公善之，常用其策。良为他人者，皆不省。良曰：「沛公殆天授。」故遂从之，不去见景驹。…","q":[["心轻马融帐，谋夺子房帷。","元稹 酬翰林白学士代书一百韵"],["积德韦丞相，通神张子房。","崔泰之 同光禄弟冬日述怀"]]}],"30":[{"n":"山阴道士","d":"换鹅：喻以自己的高才绝技换取心爱之物，或喻书法作品高妙。唐李白《送贺宾客归越》：“山阴道士如相见，应写《黄庭》换白鹅。”","s":"《晋中兴书》卷七〈琅琊王录〉～424～","w":"王羲之字逸少。导之从子也。初讷于言。人未之知。年十三。尝见周顗。顗异之。时重牛心炙。座客未啖。先割啖之。羲之于是知名。及长。尤善草隶书。为今古冠绝。累迁为右将军。不乐京师。遂往会稽。与谢安、孙绰、等游处。山阴有道士养群鹅。羲之意甚悦。道士云…","q":[["道经今为写，不虑惜鹅群。","刘长卿 过包尊师山院"],["枥嘶支遁马，池养右军鹅。","孟浩然 宴荣二山池（一题作〔宴〕（晏）荣山人池亭）"]]},{"n":"白练裙","d":"","s":"《宋书》卷六十二〈羊欣列传〉～66～","w":"羊欣字敬元，泰山南城人也。曾祖忱，晋徐州刺史。祖权，黄门郎。父不疑，桂阳太守。欣少靖默，无竞于人，美言笑，善容止。汎览经籍，尤长隶书。不疑初为乌程令，欣时年十二，时王献之为吴兴太守，甚知爱之。献之尝夏月入县，欣著新绢裙昼寝，献之书裙数幅而去…","q":[["爱竹只应怜直节，书裙多是为奇童。","徐夤 山阴故事"]]},{"n":"传庾翼","d":"","s":"《晋书》卷八十《王羲之传》","w":"羲之书初不胜庾翼、郗愔，及其暮年方妙，尝以章草答庾亮，而翼深叹伏，因与羲之书云：「吾昔有伯英章草十纸，过江颠狈，遂乃亡失，常叹妙迹永绝。忽见足下答家兄书，焕若神明，顿还旧观。」","q":[["逸翰应藏法，高词肯浪吟。数须传庾翼，莫独与卢谌。","李商隐 自桂林奉使江陵途中感怀寄献尚书"],["忆昔鄱阳寺中见一碣，逋翁词兮逋翁扎。庾翼未服王右军，李白不知谁拟杀。","贯休 读顾况歌行"]]},{"n":"点漆","d":"","s":"《世说新语笺疏》下卷上〈容止〉～620～","w":"王右军见杜弘治，叹曰：「面如凝脂，眼如点漆，此神仙中人。」","q":[]},{"n":"坦腹东床","d":"坦腹：称美女婿。唐卢纶《送申屠正字湖南迎亲》：“坦腹定逢潘令醉，上楼应伴庾公闲。”","s":"《王隐晋书》卷七〈王羲之〉～32～","w":"晋·王隐《晋书》：王羲之幼有风操，郗虞卿闻王氏诸子皆俊，令使选婿。诸子皆饰容以待客，羲之独坦腹东、啮胡饼。神色自若，使具以告，虞卿曰：「此真吾子婿也，问为谁。果是逸少，乃妻之。」","q":[["赖有东床客，池塘免寂寥。","刘长卿 登迁（一作仙）仁楼酬子婿李穆"],["鸳鸯卷新赠，遥恋东床空。","孟郊 别妻家"]]},{"n":"二王","d":"","s":"北齐·颜之推《颜氏家训》卷七《杂艺》","w":"「梁氏秘阁散逸以来，吾见二王真草多矣。」清·赵曦明注：「二王，羲之、献之也。」","q":[["书札二王争巧拙，篇章七子避风流。","罗隐 寄酬邺王罗令公五首"]]},{"n":"弘治凝脂","d":"","s":"《世说新语》下卷上《容止》","w":"「王右军见杜弘治，叹曰：『面如凝脂，眼如点漆，此神仙中人。』时人有称王长史形者，蔡公曰：『恨诸人不见杜弘治耳！』」南朝梁刘孝标注引《江左名氏传》：「永和中，刘真长、谢仁祖共商略中朝人士。或曰：『杜弘治清标令上，为后来之美，又面如凝脂，眼如点…","q":[["平叔傅粉，弘治凝脂。","李瀚 蒙求"]]},{"n":"抗行比元常","d":"","s":"《晋书》卷八十《王羲之传》","w":"「羲之每自称『我书比钟繇，当抗行；比张芝书，犹当雁行也。』」唐。张彦远《法书要录》卷一晋。王右军（羲之）《自论书》「吾书比之钟张，当抗行。」","q":[["近来渐有临池兴，为报元常欲抗行。","刘禹锡 答后篇"]]},{"n":"兰亭会","d":"","s":"《晋书》卷八十《王羲之传》","w":"羲之雅好服食养性，不乐在京师，初渡浙江，便有终焉之志。会稽有佳山水，名士多居之，谢安未仕时亦居焉。孙绰、李充、许询、支遁等皆以文义冠世，并筑室东土，与羲之同好。尝与同志宴集于会稽山阴之兰亭，羲之自为之序以申其志，曰：永和九年，岁在癸丑，暮春…","q":[["闺馀春早景沉沉，禊饮风亭恣赏心。红袖青娥留永夕，汉阴宁肯羡山阴。","刘言史 奉酬"],["长忆山阴旧会时，王家兄弟尽相随。","李涉 送王六觐巢县叔父二首"]]},{"n":"毛骨","d":"","s":"《世说新语笺疏》中卷下〈赏誉〉～479～","w":"王右军道谢万石「在林泽中，为自遒上」。叹林公「器朗神俊」。道祖士少「风领毛骨，恐没世不复见如此人」。道刘真长「标云柯而不扶」。","q":[["众中见毛骨，犹是麒麟儿。","杜甫 奉送魏六丈佑少府之交广"]]},{"n":"右军誓墓","d":"","s":"《晋书》卷八十〈王羲之列传〉～200～","w":"时骠骑将军王述少有名誉，与羲之齐名，而羲之甚轻之，由是情好不协。述先为会稽，以母丧居郡境，羲之代述，止一吊，遂不重诣。述每闻角声，谓羲之当候己，辄洒扫而待之。如此者累年，而羲之竟不顾，述深以为恨。及述为扬州刺史，将就徵，周行郡界，而不过羲之…","q":[]},{"n":"曲几书留","d":"","s":"《晋书》卷八十《王羲之传》","w":"王羲之尝诣门生家，见棐几滑净，因书之，真草相半。后为其父误刮去之，门生惊懊者累日。","q":[["曲几书留小史家，草堂棋赌山阴墅。","王维 同崔傅答贤弟"]]},{"n":"人那得知","d":"人那得知：喻父子书法皆工妙。唐柳宗元《重赠二首》之一：“如今试遣隈墙问，已道世人那得知。”","s":"《世说新语》中卷下《品藻》","w":"「谢公问王子敬：『君书何如君家尊？』答曰：『固当不同。』公曰：『外人论殊不尔。』王曰：『外人那得知？』」南朝梁·刘孝标注引宋明帝（刘彧）《文章志》：「献之善隶书，变右军法为今体。字画秀媚，妙绝时伦，与父俱得名。其章草弱，殊不及父。或讯献之…","q":[["如今试遣隈墙问，已道世人那得知。","柳宗元 重赠二首"]]},{"n":"三少","d":"","s":"《晋书》卷八十〈王羲之列传〉～2093～","w":"王羲之字逸少，司徒导之从子也。祖正，尚书郎。父旷，淮南太守。元帝之过江也，旷首创其议。羲之幼讷于言，人未之奇。年十三，尝谒周顗，顗察而异之。时重牛心炙，坐客未啖，顗先割啖羲之，于是始知名。及长，辩赡，以骨鲠称，尤善隶书，为古今之冠，论者称其…","q":[]},{"n":"团扇草书","d":"","s":"《晋书》卷八十《王羲之传》","w":"王羲之曾任右军将军、会稽内史。「尝在蕺山见一老姥，持六角竹扇卖之。羲之书其扇，各为五字。姥初有愠色。因谓姥曰：『但言是王右军书，以求百钱邪。』姥如其言，人竞买之。」《白氏六帖》卷九：「王右军草书于团扇。」","q":[["屏风误点惑孙郎，团扇草书轻内史。","王维 故人张諲工诗善易卜兼能丹青草隶顷以诗见赠聊获酬之"]]},{"n":"王右军","d":"","s":"《晋书》卷八十《王羲之传》","w":"羲之既拜护军，又苦求宣城郡，不许，乃以为右军将军、会稽内史。……孙绰、李充、许询、支遁等皆以文义冠世，并筑室东土，与羲之同好。尝与同志宴集于会稽山阴之兰亭，羲之自为之序以申其志。","q":[["右军多住寺，此夜后池秋。","司空曙 秋夜忆兴善院寄苗发"],["晚憩支公室，故人逢右军。","孟浩然 同王九题就师山房"]]},{"n":"王谢登临","d":"","s":"《晋书》卷七十九《谢安传》","w":"寓居会稽，与王羲之及高阳许询、桑门支遁游处，出则渔弋山水，入则言咏属文，无处世意。扬州刺史庾冰以安有重名，必欲致之，累下郡县敦逼，不得已赴召，月馀告归。","q":[["王谢登临处，依依今尚存。","李嘉祐 送越州辛法曹之任"],["追怀王谢侣，更似会稽岑。","羊士谔 乾元初严黄门自京兆少尹贬牧巴郡乃赋诗十四韵刻于石壁"]]},{"n":"王逸少不学卫夫人","d":"","s":"《全上古三代秦汉三国六朝文·全晋文》卷二十六〈王羲之·题卫夫人笔阵图后〉～60～2～","w":"羲之少学卫夫人书，将谓大能。及渡江北游名山，比见李斯曹喜等书，又之许下。见钟繇梁鹄书，又之洛下。见蔡邕《石经三体书》，又于从兄洽处见张昶华岳碑，始知学卫夫人书。徒费年月耳，羲之遂改本师，仍于众碑学习焉，遂成书尔。时年五十有三，或恐风烛奄及，…","q":[]},{"n":"羲献","d":"","s":"《全唐文》卷四百三十二〈张怀瓘·书断评〉～4404～","w":"孙过庭云，元常专工于隶书，伯英犹精于草体，彼之二美，而羲献兼之，并有得也。","q":[]},{"n":"羲之有之","d":"","s":"《晋书》卷八十《王羲之传》","w":"王羲之子玄之、凝之、徽之、徽之子桢之、徽之弟操之、献之。","q":[["献子还生子，羲之又有之。","孟郊 子庆诗"]]},{"n":"逸少","d":"","s":"《晋书》卷八十《王羲之传》","w":"王羲之字逸少，司徒导之从子也。祖正，尚书郎。父旷，淮南太守。元帝之过江也，旷首创其议。羲之幼讷于言，人未之奇。年十三，尝谒周顗，顗察而异之。时重牛心炙，坐客未啖，顗先割啖羲之，于是始知名。及长，辩赡，以骨鲠称，尤善隶书，为古今之冠，论者称其…","q":[["邹枚入梁苑，逸少在山阴。","刘长卿 寄会稽公徐侍郎"],["碑缺曹娥宅，林荒逸少居。","刘长卿 无锡东郭送友人游越"]]},{"n":"钟王","d":"","s":"《晋书》卷八十〈王羲之列传〉～207～","w":"制曰：书契之兴，肇乎中古，绳文鸟迹，不可足观。末代去朴归华，舒笺点翰，争相誇尚，竞其工拙。伯英临池之妙，无复馀踪；师宜悬帐之奇，罕有遗迹。逮乎钟王以降，略可言焉。钟虽擅美一时，亦为迥绝，论其尽善，或有所疑。","q":[]},{"n":"右军书","d":"右军书：喻指书画作品。唐高适《途中寄徐录事》：“空多箧中赠，长见右军书。”","s":"《晋书·王羲之传》","w":"尝在蕺山见一老姥，持六角竹扇卖之。（王）羲之书其扇，各为五字。姥初有愠色。因谓姥曰：‘但言是王右军书，以求百钱邪。'姥如其言，人竞买之。","q":[["空多箧中赠，长见右军书。","高适 途中寄徐录事"]]}],"31":[{"n":"鞭笞","d":"","s":"《汉书》卷四十八《贾谊传》","w":"谊数上疏陈政事，多所欲匡建，其大略曰：「……陛下何不试以臣为属国之官以主匈奴？行臣之计，请必系单于之颈而制其命，伏中行说而笞其背，举匈奴之众唯上之令。」","q":[["臣实有长策，彼可徐鞭笞。","杜牧 雪中书怀"]]},{"n":"贾长沙","d":"长沙谪：喻指有才者遭贬滴。唐刘长卿《听笛歌》：“旧游怜我长沙谪，载酒沙头送迁客。”","s":"《史记》卷八十四《贾生列传》","w":"贾生以为汉兴至孝文二十馀年，天下和洽，而固当改正朔，易服色，法制度，定官名，兴礼乐，乃悉草具其事仪法，色尚黄，数用五，为官名，悉更秦之法。孝文帝初即位，谦让未遑也。诸律令所更定，及列侯悉就国，其说皆自贾生发之。于是天子议以为贾生任公卿之位。…","q":[["何事长沙谪，相逢楚水秋。","刘长卿 巡去岳阳却归鄂州使院留别郑洵侍御侍御先曾谪居此州"],["已似长沙傅，从今又几年。","刘长卿 新年作"]]},{"n":"屈贾","d":"","s":"《史记》卷八十四〈屈原贾生列传·贾生〉～249～","w":"贾生名谊，雒阳人也。年十八，以能诵诗属书闻于郡中。吴廷尉为河南守，闻其秀才，召置门下，甚幸爱。孝文皇帝初立，闻河南守吴公治平为天下第一，故与李斯同邑而常学事焉，乃徵为廷尉。廷尉乃言贾生年少，颇通诸子百家之书。文帝召以为博士。是时贾生年二十馀…","q":[["试与屈贾招清魂，荒唐大树悉楠桂。","唐扶 使南海道长沙题道林岳麓寺"],["中间屈贾辈，谗毁竟自取。","杜甫 上水遣怀"]]},{"n":"宣室召","d":"","s":"《史记》卷八十四〈屈原贾生列传·贾生〉～249～","w":"贾生名谊，雒阳人也。年十八，以能诵诗属书闻于郡中。吴廷尉为河南守，闻其秀才，召置门下，甚幸爱。孝文皇帝初立，闻河南守吴公治平为天下第一，故与李斯同邑而常学事焉，乃徵为廷尉。廷尉乃言贾生年少，颇通诸子百家之书。文帝召以为博士。是时贾生年二十馀…","q":[["运筹时所贵，前席礼偏深。","包佶 奉和柳相公中书言怀"],["登楼初有作，前席竟为荣。","杜甫 春日江村五首"]]},{"n":"愁单阏","d":"","s":"《史记》卷八十四《贾生列传》","w":"「贾生为长沙王太傅三年，有鸮飞入贾生舍，止于坐隅。楚人命鸮曰『服』。贾生既以适居长沙，长沙卑湿，自以为寿不得长，伤悼之，乃为赋以自广。其辞曰：单阏之岁兮，四月孟夏，庚子日施兮，服集予舍，止于坐隅，貌甚閒暇。异物来集兮，私怪其故，发书占之兮，…","q":[["贾赋愁单阏，邹书怯大梁。","柳宗元 弘农公以硕德伟材屈于诬枉左官三岁复为大僚天监昭明人心感悦宗元窜伏湘浦拜贺末由谨献诗五十韵以毕微志"]]},{"n":"吊屈","d":"吊楚臣：指自伤身世。唐李白《赠崔秋浦》：“应念金门客，投沙吊楚臣。”","s":"《史记》卷八十四《贾生列传》","w":"「贾生名谊，雒阳人也。」「绛、灌、东阳侯、冯敬之属尽害之，乃短贾生曰：『雒阳之人，年少初学，专欲擅权，纷乱诸事。』于是天子后亦疏之，不用其议，乃以贾生为长沙王太傅。贾生既辞往行，闻长沙卑湿，自以寿不得长，又以适去，意不自得。及渡湘水，为赋以…","q":[["贾生方吊屈，岂敢比南昌。","储光羲 奉酬张五丈垂赠"],["屈平君莫吊，肠断洞庭波。","刘长卿 同姜浚题裴式微余干东斋"]]},{"n":"傅好书王","d":"","s":"《史记》卷八十四《屈原贾生列传》","w":"拜贾生为梁怀王太傅。梁怀王，文帝之少子，爱，而好书，故令贾生傅之。","q":[["高居迁鼎邑，遥傅好书王。","柳宗元 弘农公以硕德伟才屈于诬枉左官三岁复为大僚天监昭明人心感悦宗元窜伏湘浦拜贺末由谨献诗五十韵以毕微志"]]},{"n":"过秦","d":"","s":"《昭明文选》卷五十一汉·贾谊《过秦论》","w":"唐·李善注：「《汉书》：应劭曰：『贾谊书第一篇名也，言秦之过。』」","q":[["闲摛丽藻嫌秋兴，静猎遗编笑过秦。","罗隐 酬寄右司李员外"],["袁安坠睫寻忧汉，贾谊濡毫但过秦。","韩偓 八月六日作四首"]]},{"n":"三太息","d":"","s":"《汉书》卷四十八〈贾谊列传〉～2265～","w":"赞曰：刘向称「贾谊言三代与秦治乱之意，其论甚美，通达国体，虽古之伊、管未能远过也。使时见用，功化必盛。为庸臣所害，甚可悼痛。」追观孝文玄默躬行以移风俗，谊之所陈略施行矣。","q":[["堪恨贾生曾恸哭，不缘清景为忧时。","唐彦谦 八月十六日夜月"],["劳收贾生泪，强起屈平身。","孟郊 罗氏花下奉招陈侍御"]]},{"n":"积薪","d":"","s":"《新书》卷一《数宁》～4～","w":"进言者皆曰：「天下已安矣。」臣独曰：「未安。」或者曰：「天下已治矣。」臣独曰：「未治。」恐逆意触死罪，虽然，诚不安，诚不治。故不敢顾身，敢不昧死以闻。夫曰天下安且治者，非至愚无知，固谀者耳，皆非事实，知治乱之体者也。夫抱火措之积薪之下，而寝…","q":[["畏闻巢幕险，宁寤积薪然。","韩偓 感事三十四韵"]]},{"n":"系名王","d":"","s":"《汉书》卷四十八《贾谊传》","w":"是时，匈奴彊，侵边。天下初定，制度疏阔。诸侯王僭儗，地过古制，淮南、济北王皆为逆诛。谊数上疏陈政事，多所欲匡建，其大略曰：「……今匈奴嫚姆侵掠，至不敬也，为天下患，至亡已也，而汉岁致金絮采缯以奉之。……陛下何不试以臣为属国之官以主匈奴？行臣…","q":[["欲令塞上无干戚，会待单于系颈时。","李昂 从军行"],["匈奴系头数应尽，明年应入蒲萄宫。","李白 送族弟绾从军安西"]]},{"n":"贾笔","d":"","s":"《汉书》卷四十八《贾谊传》","w":"贾谊，雒阳人也，年十八，以能诵诗书属文称于郡中。……谊数上疏陈政事，多所欲匡建，","q":[["贾笔论孤愤，严诗赋几篇。","杜甫 寄岳州贾司马六丈巴州严八使君两阁老五十韵"]]},{"n":"贾马","d":"","s":"《晋书》卷九十二〈文苑列传·序言〉～2369～","w":"自时已降，轨躅同趋，西都贾马耀灵蛇于掌握，东汉班张发雕龙于绨椠，俱标称首，咸推雄伯。","q":[["舐笔和铅欺贾马，赞功论道鄙萧曹。","杜牧 长安杂题长句六首"],["论文徵贾马，述隐许求羊。","皎然 因游支硎寺寄邢端公"]]},{"n":"贾生年","d":"","s":"《史记》卷八十四《贾生列传》","w":"居顷之，拜贾生为梁怀王太傅。梁怀王，文帝之少子，爱，而好书，故令贾生傅之。文帝复封淮南厉王子四人皆为列侯。贾生谏，以为患之兴自此起矣。贾生数上疏，言诸侯或连数郡，非古之制，可稍削之。文帝不听。居数年，怀王骑，堕马而死，无后。贾生自伤为傅无状…","q":[["回也实夭折，贾生亦脆促。","徐彦伯 题东山子李适碑阴二首"],["才高未及贾生年，何事孤魂逐逝川。","郑立之 哭林杰"]]},{"n":"洛阳年少","d":"","s":"《史记》卷八十四〈屈原贾生列传·贾生〉","w":"贾生名谊，雒阳人也。年十八，以能诵诗属书闻于郡中。吴廷尉为河南守，闻其秀才，召置门下，甚幸爱。孝文皇帝初立，闻河南守吴公治平为天下第一，故与李斯同邑而常学事焉，乃徵为廷尉。廷尉乃言贾生年少，颇通诸子百家之书。文帝召以为博士。是时贾生年二十馀…","q":[["洛阳才子何曾爱，下马贪趋广运门。","令狐楚 皇城中花园讥刘白赏春不及"],["高帝黜儒生，文皇谪才子。","储光羲 贻袁三拾遗谪作"]]},{"n":"梁王傅","d":"","s":"《史记》卷八十四《贾生列传》","w":"后岁馀，贾生徵见。孝文帝方受釐，坐宣室。上因感鬼神事，而问鬼神之本。贾生因具道所以然之状。至夜半，文帝前席。既罢，曰：「吾久不见贾生，自以为过之，今不及也。」居顷之，拜贾生为梁怀王太傅。梁怀王，文帝之少子，爱，而好书，故令贾生傅之。","q":[["惆怅长岑长，寂寞梁王傅。","储光羲 贻王侍御出台掾丹阳"]]},{"n":"三表","d":"","s":"《新书》卷四〈匈奴〉～73～","w":"臣为陛下建三表，设五饵，以此与单于争其民，则下匈奴犹振槁也。夫无道之人，何宜敢捍此其久，陛下幸用臣之计，臣且以事势谕天子之言，使匈奴大众之信陛下也，为通言耳，必行而弗易。梦中许人，觉且不背其信，陛下已诺，若日出之灼灼。故闻君一言，虽有微远…","q":[]},{"n":"长沙鵩","d":"贾鵩：指人去世的凶讯或预兆。唐罗隐《秋日怀孟夷庚》：“知己秦貂没，流年贾鵩悲。”","s":"《史记》卷八十四《贾生列传》","w":"贾生以为汉兴至孝文二十馀年，天下和洽，而固当改正朔，易服色，法制度，定官名，兴礼乐，乃悉草具其事仪法，色尚黄，数用五，为官名，悉更秦之法。孝文帝初即位，谦让未遑也。诸律令所更定，及列侯悉就国，其说皆自贾生发之。于是天子议以为贾生任公卿之位。…","q":[["如今贾谊赋，不漫说长沙。","于鹄 送迁客二首之一"],["曾为鹏鸟赋，喜过凿龙山。","刘禹锡 和李相公初归平泉过龙门南岭遥望山居即事"]]},{"n":"上治安","d":"","s":"《汉书》卷四十八〈贾谊列传〉～2230～","w":"是时，匈奴彊，侵边。天下初定，制度疏阔。诸侯王僭儗，地过古制，淮南、济北王皆为逆诛。谊数上疏陈政事，多所欲匡建，其大略曰：臣窃惟事势，可为痛哭者一，可为流涕者二，可为长太息者六，若其它背理而伤道者，难遍以疏举。进言者皆曰天下已安已治矣，臣独…","q":[]},{"n":"宣室","d":"","s":"《汉书》卷四十八《贾谊传》","w":"「后岁馀，文帝思谊，徵之。至，入见，上方受釐，坐宣室。」三国魏·苏林曰：「宣室，未央前正室也。」","q":[["九重宣室召，万里建溪行。","刘长卿 新安奉送穆谕德归朝赋得行字"],["伫看宣室召，汉法倚张纲。","刘长卿 酬皇甫侍御见寄时前相国姑藏公初临郡"]]},{"n":"正襟危坐","d":"","s":"《史记》卷一百二十七〈日者列传〉～326～","w":"宋忠、贾谊瞿然而悟，猎缨正襟危坐，曰：「吾望先生之状，听先生之辞，小子窃观于世，未尝见也。今何居之卑，何行之污？」","q":[]},{"n":"终贾","d":"","s":"《旧唐书》卷七十四〈马周列传〉～269～","w":"先是，京城诸街，每至晨暮，遣人传呼以警众。周遂奏诸街置鼓，每击以警众，令罢传呼，时人便之，太宗益加赏劳。俄拜给事中，十二年，转中书舍人。周有机辩，能敷奏，深识事端，动无不中。太宗尝曰：「我于马周，暂不见则便思之。」中书侍郎岑文本谓所亲曰：「…","q":[]}],"32":[{"n":"阿甄","d":"","s":"《三国志》卷五《魏书·后妃传》","w":"文昭甄皇后，中山无极人，明帝母，汉太保甄邯后也，世吏二千石。父逸，上蔡令。后三岁失父。后天下兵乱，加以饥馑，百姓皆卖金银珠玉宝物，时后家大有储谷，颇以买之。后年十馀岁，白母曰：「今世乱而多买宝物，匹夫无罪，怀璧为罪。又左右皆饥乏，不如以谷振…","q":[["啼蛄吊月钩栏下，屈膝铜铺锁阿甄。","李贺 宫娃歌"],["甄妃为妒出层宫，班女因猜下长信。","王諲 后庭怨"]]},{"n":"本初朔饮","d":"","s":"《岁时习俗资料汇编·新增月日纪古》卷之六上〈六月卷上·伏日〉～2085～","w":"魏文《典略》：大驾都许，使光禄大夫刘松北镇袁绍军，与绍子弟共饮宴，常以盛夏三伏之际，昼夜饮酒，至于无知，云以避一时之暑，故河朔有避暑饮。","q":[]},{"n":"蝉鬓","d":"","s":"《古今注》卷下《杂注》","w":"魏文帝宫人绝所宠者，有莫琼树……四人，日夕在侧。琼树乃制蝉鬓，缥缈如蝉翼，故曰蝉鬓。","q":[["婵娟两鬓秋蝉翼，宛转双蛾远山色。","白居易 井底引银瓶"]]},{"n":"煮豆","d":"七步咏：指人才思敏捷，才气过人。唐于志宁《冬日宴群公于宅各赋一字得杯》：“俱裁七步咏，同倾三雅杯。”；萁燃：喻兄弟相逼，或喻内部不和。清黄蜜来《寄怀昌大风》：“屐虽齿折诚何碍，吟到其燃未免猜。”","s":"《世说新语笺疏》上卷下〈文学〉～244～","w":"文帝（曹丕）尝令东阿王（曹植）七步中作诗，不成者行大法。应声便为诗曰：「煮豆持作羹，漉菽以为汁。萁在釜下然，豆在釜中泣。本自同根生，相煎何太急？」帝深有惭色。","q":[["俱裁七步咏，同倾三雅杯。","于志宁 冬日宴群公于宅各赋一字得杯"],["豆萁才敏俊，羽猎正峥嵘。","元稹 答姨兄胡灵之见寄五十韵"]]},{"n":"西园飞盖","d":"","s":"《昭明文选》卷二十〈诗甲·公宴·公宴诗〉～943～","w":"公子敬爱客，终宴不知疲。清夜游西园，飞盖相追随。明月澄清景，列宿正参差。秋兰被长阪，朱华冒绿池。潜鱼跃清波，好鸟鸣高枝。神飙接丹毂，轻辇随风移。飘飖放志意，千秋长若斯。","q":[["西园置酒地，日夕簪裾列。","刘驾 送李殷游边"],["东壁图书府，西园翰墨林。","张说 恩制赐食于丽正殿书院宴赋得林字"]]},{"n":"浮瓜","d":"","s":"《昭明文选》卷四十二〈书中·与朝歌令吴质书〉～895～","w":"每念昔日南皮之游，诚不可忘。既妙思六经，逍遥百氏；弹棋閒设，终以六博，高谈娱心，哀筝顺耳。驰骋北场，旅食南馆，浮甘瓜于清泉，沈朱李于寒水。","q":[["寒水浮瓜五月时，把君衣袖长河曲。","韩翃 送蓨县刘主簿楚"]]},{"n":"汗逾水浆","d":"","s":"《世说新语》上卷上《言语》","w":"「钟毓、钟会少有令誉。年十三，魏文帝闻之，语其父钟繇曰：『可令二子来。』于是敕见。毓面有汗，帝曰：『卿面何以汗？』毓对曰：『战战惶惶，汗出如浆。』复问会：『卿何以不汗？』对曰：『战战慄慄，汗不敢出。』」","q":[["老少多暍死，汗逾水浆翻。","杜甫 贻华阳柳少府"]]},{"n":"河朔余酲","d":"","s":"《全上古三代秦汉三国六朝文·全三国文》卷八〈曹丕·典论·酒诲〉～095～","w":"荆州牧刘表，跨有南土，子弟骄贵，并好酒。为三爵，大曰伯雅，次曰中雅，小曰季雅。伯雅受七胜，中雅受六胜，季雅受五胜。又设大针于杖端。客有醉酒寝地者，辄以劖刺之，验其醉醒，是酷于赵敬侯以筒酒灌人也。大驾都许，使光禄大夫刘松北镇袁绍军，与绍子弟日…","q":[]},{"n":"泪成血","d":"玉壶盛泪：指妇人哀伤落泪。宋钱惟演《无题》：“纨扇寄情虽自洁，玉壶盛泪只凝红。”","s":"旧题晋·王嘉《拾遗记》卷七《魏》","w":"「时文帝选良家子女，以入六宫。习以千金宝赂聘之。既得，便以献文帝。灵芸闻别父母，歔欷累日，泪下沾衣。至升车就路之时，以玉唾壶盛泪壶中，即如红色。既发常山，及至京师，壶中泪凝如血。」","q":[["谁家红泪客，不忍过瞿塘。","李贺 蜀国弦"]]},{"n":"华歆忤旨","d":"","s":"《三国志》卷十三《魏书·华歆传》","w":"「华歆字子鱼，平原高唐人也。……文帝即王位，拜相国，封安乐乡侯。及践阼，改为司徒。」南朝宋·裴松之注引华峤《谱?》：「文帝受禅，朝臣三公已下并受爵位；歆以形色忤时，徙为司徒，而不进爵。魏文帝久不怿，以问尚书令陈群曰：『我应天受禅，百辟群后，…","q":[["华歆忤旨，陈群蹙容。","李瀚 蒙求"]]},{"n":"画饼","d":"画饼：指用空想慰藉自己。唐李商隐《咏怀寄秘阁旧僚二十六韵》：“官衔同画饼，面貌乏凝脂。”","s":"《三国志》卷二十二《魏书·卢毓传》","w":"前此诸葛诞、邓飏等驰名誉，有四聪八达之诮，帝疾之。时举中书郎，诏曰：「得其人与否，在卢生耳。选举莫取有名，名如画地作饼，不可啖也。」","q":[["望梅閤老无妨渴，画饼尚书不救饥。","白居易 每见吕南二郎中新文辄窃有所叹惜因成长句以咏所怀"]]},{"n":"季重旧游","d":"","s":"《昭明文选》卷四十二〈书中·与吴质书〉～897～","w":"昔年疾疫，亲故多离其灾，徐陈应刘，一时俱逝，痛可言邪！昔日游处，行则连舆，止则接席，何曾须臾相失。每至觞酌流行，丝竹并奏，酒酣耳热，仰而赋诗，当此之时，忽然不自知乐也。谓百年己分，可长共相保。何图数年之间，零落略尽，言之伤心！","q":[["季重旧游多丧逝，子山新赋极悲哀。","韩偓 乱后春日途经野塘"]]},{"n":"建安诸子","d":"","s":"《昭明文选》卷五十二〈论二·典论论文〉～2270～","w":"今之文人，鲁国孔融文举，广陵陈琳孔璋，山阳王粲仲宣，北海徐干伟长，陈留阮瑀元瑜，汝南应玚德琏，东平刘桢公干：斯七子者，于学无所遗，于辞无所假，咸以自骋骥騄于千里，仰齐足而并驰。以此相服，亦良难矣。盖君子审己以度人，故能免于斯累，而作论文。","q":[]},{"n":"驴鸣一声","d":"","s":"《世说新语》下卷上《伤逝》","w":"王仲宣好驴鸣。既葬，文帝临其丧，顾语同游曰：「王好驴鸣，可各作一声以送之。」赴客皆一作驴鸣。","q":[["尘满空床屋见天，独作驴鸣一声去。","刘言史 题王况故居"]]},{"n":"三雅","d":"","s":"《太平御览》卷八四五","w":"三国魏·曹丕《典论》：刘表有酒爵三，大曰伯雅，次曰仲雅，小曰季雅。伯雅容七升，仲雅六升，季雅五升。","q":[["俱裁七步咏，同倾三雅杯。","于志宁 冬日宴群公于宅各赋一字得杯"],["酒每倾三雅，书能发百函。","刘禹锡 和汴州令狐相公到镇改月偶书所怀"]]},{"n":"魏储南馆","d":"","s":"《昭明文选》卷四十二、三国魏·魏文帝（曹丕）《与朝歌令吴质书》","w":"每念昔日南皮之游，诚不可忘。既妙思六经，逍遥百氏；弹棋閒设，终以六博，高谈娱心，哀筝顺耳。驰骋北场，旅食南馆，","q":[["魏储南馆，汉朝东阁。","李瀚 蒙求"]]},{"n":"魏公子","d":"","s":"《三国志》卷二《魏书·文帝纪》","w":"文皇帝讳丕，字子桓，武帝太子也。中平四年冬，生于谯。建安十六年，为五官中郎将、副丞相。二十二年，立为魏太子。","q":[["遥思魏公子，复忆李将军。","王维 送魏郡李太守赴任"]]},{"n":"魏文颁菊蕊","d":"","s":"《艺文类聚》卷四","w":"魏文帝《与钟繇书》曰：岁往月来，忽复九月九日。九为阳数，而日月并应，俗嘉其名，以为宜于长久，故以享宴高会。是月律中无射，言群木庶草，无有射而生。至于芳菊，纷然独荣，非夫含乾坤之纯和，体芬芳之淑气，孰能如此？故屈平悲冉冉之将老，思食秋菊之落英…","q":[["魏文颁菊蕊，汉武赐萸房。","沈佺期 九日临渭亭侍宴应制得长字"]]},{"n":"魏文手巾","d":"","s":"《三国志》卷二《魏书·文帝纪》","w":"「评曰：文帝天资文藻，下笔成章，博闻彊识，才蓺兼该；若加之旷大之度，励以公平之诚，迈志存道，克广德心，则古之贤主，何远之有哉！」南朝宋·裴松之注引《博物志》曰：「帝善弹棋，能用手巾角。时有一书生，又能低头以所冠著葛巾角撇棋。」","q":[["联翩百中皆造微，魏文手巾不足比。","李颀 弹棋歌"]]},{"n":"五色药","d":"","s":"《宋书》卷二十一〈乐志三〉～66～","w":"〈折杨柳行〉：西山一何高，高高殊无极。上有两仙僮，不饮亦不食。与我一丸药，光耀有五色。服药四五日，身体生羽翼。轻举乘浮云，倏忽行万亿。流览观四海，芒芒非所识。彭祖称七百，悠悠安可原。老聃适西戎，于今竟不还。王乔假虚词，赤松垂空言。达人识真伪…","q":[["何烦五色药，尊下即丹丘。","李群玉 半醉"]]},{"n":"辛毗引裾","d":"","s":"《三国志》卷二十五《魏书·辛毗传》","w":"辛毗字佐治，颍川阳翟人也。……文帝践阼，迁侍中，赐爵关内侯。时议改正朔。毗以魏氏遵舜、禹之统，应天顺民；至于汤、武，以战伐定天下，乃改正朔。孔子曰「行夏之时」，左氏传曰「夏数为得天正」，何必期于相反。帝善而从之。帝欲徙冀州士家十万户实河南。…","q":[["樊哙排闼，辛毗引裾。","李瀚 蒙求"]]},{"n":"一醉六十日","d":"","s":"《晋书》卷四十九〈阮籍列传〉～360～","w":"籍本有济世志，属魏晋之际，天下多故，名士少有全者，籍由是不与世事，遂酣饮为常。文帝初欲为武帝求婚于籍，籍醉六十日，不得言而止。","q":[["一醉六十日，古来闻阮生。","杜牧 自宣州赴官入京路逢裴坦判官归宣州因题赠"],["一醉六十日，一裘三十年。","高蟾 道中有感"]]}],"33":[{"n":"阳春曲","d":"巴人：指较俗的作品，或指民歌。唐权德舆《奉和于司空二十五丈新卜城南郊居接司徒公别墅即事书情奉献兼呈李裴相公》：“巴人宁敢和，空此愧游藩。”；巴歌：指通俗化的作品。唐孟浩然《同曹三御史行泛湖归越》：“秋人诗人意，巴歌和者稀…","s":"《昭明文选》卷四十五战国策·宋玉《对楚王问》","w":"「客有歌于郢中者，其始曰下里巴人，国中属而和者数千人；其为阳阿薤露，国中属而和者数百人；其为阳春白雪，国中属而和者不过数十人；引商刻羽，杂以流徵，国中属而和者不过数人而已。是其曲弥高，其和弥寡。」唐。李周翰注：「《下里》《巴人》，下曲名也；…","q":[["郢曲思朋执，轻纱画胜游。","于濆 和绵州于中丞越王作二首"],["白头老尹三川上，双和阳春喜复惊。","令狐楚 奉和仆射相公酬忠武李相公见寄之作"]]},{"n":"班马香","d":"","s":"杜牧《冬至日寄小侄阿宜诗》","w":"高摘屈宋艳，浓薰班马香。","q":[]},{"n":"宋玉悲","d":"","s":"《楚辞》卷八《九辩》","w":"悲哉秋之为气也！萧瑟兮草木摇落而变衰，憭慄兮若在远行，登山临水兮送将归，……皇天平分四时兮，窃独悲此廪秋。……靓杪秋之遥夜兮，心缭悷而有哀。","q":[["贵来君却少，秋至老偏悲。","崔峒 寄上礼部李侍郎"],["我有新秋泪，非关宋玉悲。","畅当 别卢纶"]]},{"n":"大王风","d":"","s":"《昭明文选》卷十三〈赋庚·物色·风赋〉～58～","w":"楚襄王游于兰台之宫。宋玉景差侍。有风飒然而至。王乃披襟而当之曰。快哉此风。寡人所与庶人共者邪。宋玉对曰。此独大王之风耳。庶人安得而共之。王曰。夫风者。天地之气。溥畅而至。不择贵贱高下而加焉。今子独以为寡人之风。岂有说乎。宋玉对曰。臣闻于师。…","q":[["依依宜织江雨空，雨中六月兰台风。","李贺 罗浮山父（一作人）与葛篇"],["雄风卷昏雾，干戈满楼船。","于濆 南越谣"]]},{"n":"朝云暮雨","d":"朝云暮雨：咏男女之情。唐李白《寄远》：“美人美人兮归去来，莫作朝云暮雨兮飞阳台。”","s":"《昭明文选》卷十九〈赋癸·情·高唐赋〉～875～","w":"昔者楚襄王与宋玉游于云梦之台，望高唐之观。其上独有云气，兮直上，忽兮改容，须臾之间，变化无穷。王问玉曰：「此何气也？」玉对曰：「所谓朝云者也。」王曰：「何谓朝云？」玉曰：「昔者先王尝游高唐，怠而昼寝，梦见一妇人曰：『妾巫山之女也，为高唐之…","q":[["曲留明怨惜，梦尽失欢娱。","杜甫 大历三年春白帝城放船出瞿塘峡久居夔府将适江陵漂泊有诗凡四十韵"],["未减行雨荆台下，自比凌波洛浦游。","上官仪 咏画障"]]},{"n":"楚辞招","d":"","s":"《楚辞补注》卷九〈招魂〉","w":"东汉·王逸《序》：「〈招魂〉者，宋玉之所作也。招者，召也。以手曰招，以言曰召。魂者，身之精也。宋玉怜哀屈原，忠而斥弃，愁懑山泽，魂魄放佚，厥命将落。故作〈招魂〉，欲以复其精神，延其年寿，外陈四方之恶，内崇楚国之美，以讽谏怀王，冀其觉悟而还之…","q":[["搔首惊闻楚些歌，拂衣归去泪悬河。","牟融 邵公母"],["我有迷魂招不得，雄鸡一声天下白。","李贺 致酒行"]]},{"n":"屈宋","d":"","s":"《隋书》卷七十六《文学传·王贞传》","w":"炀帝即位，齐王暕镇江都，闻其名，以书召之曰：「夫山藏美玉，光照廊庑之间，地蕴神剑，气浮星汉之表。是知毛遂颖脱，义感平原，孙慧文词，来迁东海。顾循寡薄，有怀髦彦，籍甚清风，为日久矣，未获披觌，良深伫迟。比高天流火，早应凉飙，陵云仙掌，方承清露…","q":[["荆门倒屈宋，梁苑倾邹枚。","李白 赠王判官时余归隐居庐山屏风叠"],["羁离交屈宋，牢落值颜闵。","杜甫 赠郑十八贲"]]},{"n":"东家女","d":"三年送目：指女子爱慕男子。宋杨亿《宋玉》：“三年送目愁邻媛，七泽迷魂怨楚辞。”；宋玉墙：喻女子寄情之所。唐罗隐《桃花》：“数枝艳拂文君酒，半里红欹宋玉墙。”","s":"《昭明文选》卷十九〈赋癸·情·登徒子好色赋〉～892～","w":"大夫登徒子侍于楚王，短宋玉曰：「玉为人，体貌闲丽，口多微辞，又性好色。愿王勿与出入后宫。」王以登徒子之言问宋玉，玉曰：「体貌闲丽，所受于天也；口多微辞，所学于师也；至于好色，臣无有也。」王曰：「子不好色，亦有说乎？有说则止，无说则退。」玉曰…","q":[["西墙邻宋玉，窥见妾眉宇。","于濆 宫怨"],["因游李城北，偶向宋家东。","元稹 会真诗三十韵"]]},{"n":"登徒言","d":"","s":"《昭明文选》卷十九战国楚·宋玉《登徒子好色赋》","w":"大夫登徒子侍于楚王，短宋玉曰：「玉为人，体貌闲丽，口多微辞，又性好色。愿王勿与出入后宫。」王以登徒子之言问宋玉，玉曰：「体貌闲丽，所受于天也；口多微辞，所学于师也；至于好色，臣无有也。」王曰：「子不好色，亦有说乎？有说则止，无说则退。」","q":[["一感登徒言，恩情遂中绝。","李白 感遇四首之四"]]},{"n":"独唱何须和","d":"","s":"《昭明文选》卷四十五〈对问设论辞序上·对问·对楚王问〉～999～","w":"楚襄王问于宋玉曰：「先生其有遗行与？何士民众庶不誉之甚也？」宋玉对曰：「唯，然，有之。愿大王宽其罪，使得毕其辞。客有歌于郢中者，其始曰下里巴人，国中属而和者数千人；其为阳阿薤露，国中属而和者数百人；其为阳春白雪，国中属而和者不过数十人；引商…","q":[]},{"n":"萍风","d":"","s":"《昭明文选》卷十三〈赋庚·物色·风赋〉～582～","w":"王曰：「夫风始安生哉？」宋玉对曰：「夫风生于地，起于青蘋之末。侵淫溪谷，盛怒于土囊之口。缘泰山之阿，舞于松柏之下。飘忽淜滂，激飏熛怒。耾耾雷声，回穴错迕。蹶石伐木，梢杀林莽。","q":[["秦台悲白首，楚泽怨青蘋。","刘长卿 负谪后登干越亭作"],["啸起青蘋末，吟瞩白云端。","孟云卿 新安江上寄处士"]]},{"n":"横陈","d":"","s":"《古文苑》卷二战国楚·宋玉《讽赋》","w":"主人之女又为臣歌曰：「内怵惕兮徂玉床，横自陈兮君之傍。君不御兮妾谁怨，日将至兮下黄泉。」","q":[["横陈每虚设，吉梦竟何成。","李百药 妾薄命"]]},{"n":"兰台公子","d":"","s":"《昭明文选》卷十三〈赋庚·物色·风赋〉～58～","w":"楚襄王游于兰台之宫，宋玉景差侍。有风飒然而至，王乃披襟而当之曰：「快哉此风！寡人所与庶人共者邪？」宋玉对曰：「此独大王之风耳，庶人安得而共之？」王曰：「夫风者，天地之气，溥畅而至，不择贵贱高下而加焉，今子独以为寡人之风，岂有说乎？」宋玉对曰…","q":[]},{"n":"料得怜宋玉","d":"","s":"《全唐诗》卷五百三十九〈席上作〉","w":"淡云轻雨拂高唐，玉殿秋来夜正长。料得也应怜宋玉，一生惟事楚襄王【整首一云：淡烟微雨恣高唐，一曲清尘绕画梁。料得也应怜宋玉，只因无奈楚襄王】。","q":[]},{"n":"束缟","d":"","s":"《昭明文选》卷十九〈赋癸·情·登徒子好色赋〉～892～","w":"大夫登徒子侍于楚王，短宋玉曰：「玉为人，体貌闲丽，口多微辞，又性好色。愿王勿与出入后宫。」王以登徒子之言问宋玉，玉曰：「体貌闲丽，所受于天也；口多微辞，所学于师也；至于好色，臣无有也。」王曰：「子不好色，亦有说乎？有说则止，无说则退。」玉曰…","q":[]},{"n":"宋玉","d":"","s":"《史记》卷八十四《屈原列传》","w":"屈原既死之后，楚有宋玉、唐勒、景差之徒者，皆好辞而以赋见称；然皆祖屈原之从容辞令，终莫敢直谏。其后楚日以削，数十年竟为秦所灭。","q":[["楚王犹自惑，宋玉且将归。","岑参 送崔全被放归都觐省"],["高丘怀宋玉，访古一沾裳。","李白 宿巫山下"]]},{"n":"宋玉词章","d":"","s":"《史记》卷八十四〈屈原贾生列传〉～249～","w":"屈原既死之后，楚有宋玉、唐勒、景差之徒者，皆好辞而以赋见称；然皆祖屈原之从容辞令，终莫敢直谏。其后楚日以削，数十年竟为秦所灭。","q":[]},{"n":"宋玉田","d":"","s":"《古文苑》卷一战国楚·宋玉《小言赋》","w":"楚襄王既登阳云之台，令诸大夫景差、唐勒、宋玉等并造《大言赋》，赋毕而宋玉受赏。王曰：「……贤人有能为《小言赋》者，赐之云梦之田。……」……宋玉曰：「无内之中，微物潜生，比之无象，言之无名，蒙蒙灭景，昧昧遗形，超于大虚之域，出于未兆之庭，纤于…","q":[["散下楚王国，分浇宋玉田。","李白 安州应城玉女汤作"]]},{"n":"巫阳招","d":"","s":"《楚辞补注》卷九〈招魂〉～97～","w":"「帝告巫阳曰：『有人在下，我欲辅之。魂魄离散，汝筮予之！』……巫阳焉乃下招曰：『魂兮归来。』」","q":[["帝赐九河湔涕痕，又诏巫阳反其魂，徐命之前问何冤。","韩愈 陆浑山火和皇浦湜用其韵"]]},{"n":"嫣然一笑","d":"","s":"《昭明文选》卷十九〈赋癸·情·登徒子好色赋〉～892～","w":"大夫登徒子侍于楚王，短宋玉曰：「玉为人，体貌闲丽，口多微辞，又性好色。愿王勿与出入后宫。」王以登徒子之言问宋玉，玉曰：「体貌闲丽，所受于天也；口多微辞，所学于师也；至于好色，臣无有也。」王曰：「子不好色，亦有说乎？有说则止，无说则退。」玉曰…","q":[["阳城迷处笑，京兆画时嚬。","吴融 倒次元韵"],["城堪迷下蔡，台合上姑苏。","吴融 即席十韵"]]},{"n":"摇落","d":"","s":"《楚辞》卷八《九辩》","w":"「悲哉秋之为气也！萧瑟兮草木摇落而变衰。」东汉·王逸注：「华叶陨零，肥润去也。」","q":[["何堪老泪交流日，多是秋风摇落时。","白居易 寄刘苏州"]]},{"n":"诛宋玉茅","d":"","s":"《庾子山集》卷二〈哀江南赋〉","w":"彼凌江而建国，始播迁于吾祖。分南阳而赐田，裂东岳而胙土。诛茅宋玉之宅，穿径临江之府。","q":[["虽非宋玉诛茅至，且学王家种竹来。","吴融 歧阳蒙相国借宅因抒怀投献"],["翠敛王孙草，荒诛宋玉茅。","罗隐 杜处士新居"]]}],"34":[{"n":"神州陆沉","d":"","s":"《世说新语笺疏》下卷下〈轻诋〉～834～","w":"桓公入洛，过淮、泗，践北境，与诸僚属登平乘楼，眺瞩中原，慨然曰：「遂使神州陆沈，百年丘墟，王夷甫诸人，不得不任其责！」袁虎率而对曰：「运自有废兴，岂必诸人之过？」桓公懔然作色，顾谓四坐曰：「诸君颇闻刘景升不？有大牛重千斤，啖刍豆十倍于常牛，…","q":[]},{"n":"扪虱谈","d":"扪虱：咏贤士举止不拘小节。唐李白《赠韦秘书子春》：“披云睹青天，扪虱话良图。”","s":"《太平御览》卷九百五十一〈虫豸部八·虱虮〉～4353～2～","w":"《续晋阳秋》：「咸阳王猛被缊袍而诣桓温，一见面谈当时之事，猛摸虱而言，傍若无人，温察而奇之。」","q":[["扪虱对桓公，愿得论悲辛。","李白 赠张相镐二首之一（时逃难在宿松山作。萧士赟云，此下八首非白作。）"],["披云睹青天，扪虱话良图。","李白 赠韦秘书子春二首之二"]]},{"n":"落帽风","d":"孟嘉帽：喻气度非凡，潇洒倜傥。唐独孤及《九月九日李苏州东楼宴》：“风前孟嘉帽，月下庾公楼。”；龙山：喻欢宴。唐末湾《重阳日陪韦卿宴》：“何必龙山好，南亭赏不睽。”","s":"《全上古三代秦汉三国六朝文·全晋文》卷一百十二〈陶潜·晋故征西大将军长史孟府君传〉～20～2～","w":"君讳嘉，字万年，江夏鄂人也。曾祖父宗，以孝行称，仕吴司马。祖父揖，元康中为庐陵太守。宗葬武昌新阳县，子孙家焉，遂为县人也。君少失父，奉母二弟居。娶大司马长沙桓公陶侃第十女，闺门孝友，人无能閒，乡闾称之。冲默有远量，弱冠俦类咸敬之。同郡郭逊，…","q":[["贵重近臣光绮席，笑怜从事落乌纱。","令孤楚 奉和严石空重阳日同崔常侍崔郎及诸公登龙山落帽台佳宴"],["登楼王粲望，落帽孟嘉情。","元稹 答姨兄胡灵之见寄五十韵"]]},{"n":"树犹如此","d":"","s":"《世说新语笺疏》上卷上〈言语〉～4～","w":"桓公北征经金城，见前为琅邪时种柳，皆已十围，慨然曰：「木犹如此，人何以堪！」攀枝执条，泫然流泪。","q":[]},{"n":"断肠猿","d":"断肠猿：咏悲思或咏猿。唐张说《岳州别子均》：“津亭拔心草，江路断肠猿。”","s":"《世说新语》下卷下《黜免》","w":"桓公入蜀，至三峡中，部伍中有得猿子者。其母缘岸哀号，行百馀里不去，遂跳上船，至便即绝。破视其腹中，肠皆寸寸断。公闻之，怒，命黜其人。","q":[["寸肠无计免，应只楚猿知。","吴融 松江晚泊"],["天寒雁度堪垂泪，日落猿啼欲断肠。","孟浩然 登万岁楼"]]},{"n":"痴黠相兼","d":"","s":"《世说新语》上卷下《文学》","w":"「或问顾长康：『君筝赋何如嵇康琴赋？』顾曰：『不赏者，作后出相遗。深识者，亦以高奇见贵。』」南朝梁·刘孝标注引宋明帝文章志曰：「桓温云：『顾长康体中痴黠各半，合而论之，正平平耳。』」","q":[["如含瓦砾竟何功，痴黠相兼似得中。","韩偓 味道"]]},{"n":"倚马才","d":"","s":"《世说新语笺疏》上卷下〈文学〉～273～","w":"桓宣武北征，袁虎时从，被责免官。会须露布文，唤袁倚马前令作。手不辍笔，俄得七纸，殊可观。东亭在侧，极叹其才。袁虎云：「当令齿舌閒得利。」南朝梁·刘孝标注引《文选集注》卷四十九〈三国名臣序赞注〉引臧荣绪《晋书》云：「袁宏好学，善属文，谢尚以为…","q":[["䌽笔谕戎矜倚马，华堂留客看惊鸿。","刘禹锡 酬窦员外郡斋宴客偶命柘枝因见寄兼呈张十一院长元九侍御"],["栖身未识登龙地，落笔元非倚马才。","吴融 灵池县见早梅"]]},{"n":"雌声","d":"","s":"《晋书》卷九十八《桓温传》","w":"初，温自以雄姿风气是宣帝、刘琨之俦，有以其比王敦者，意甚不平。及是征还，于北方得一巧作老婢，访之，乃琨伎女也，一见温，便潸然而泣。温问其故，答曰：「公甚似刘司空。」温大悦，出外整理衣冠，又呼婢问。婢云：「面甚似，恨薄；眼甚似，恨小；须甚似，…","q":[["雌声吐款要，酒壶缀羊腔。","韩愈 病中赠张十八"]]},{"n":"青州从事","d":"青州从事：咏酒。唐皮日休《醉中寄鲁望一壶并一绝》：“醉中不得亲相倚，故遣青州从事来。”","s":"《世说新语笺疏》下卷上〈术解〉～708～","w":"桓公有主簿善别酒，有酒辄令先尝。好者谓「青州从事」，恶者谓「平原督邮」。青州有齐郡，平原有鬲县。「从事」言「到脐」，「督邮」言在「鬲上住」。","q":[["醉中不得亲相倚，故遣青州从事来。","皮日休 醉中寄鲁望一壶并一绝"],["青州从事来偏熟，泉布先生老渐悭。","韦庄 江上题所居"]]},{"n":"得一老兵","d":"","s":"《晋书》卷七十九〈谢安列传·（安兄）谢奕〉～2080～","w":"奕字无奕，少有名誉。初为剡令，有老人犯法，奕以醇酒饮之，醉犹未已。安时年七八岁，在奕膝边，谏止之。奕为改容，遣之。与桓温善。温辟为安西司马，犹推布衣好。在温坐，岸帻笑咏，无异常日。桓温曰：「我方外司马。」奕每因酒，无复朝廷礼，尝逼温饮，温走…","q":[]},{"n":"令公喜","d":"","s":"《世说新语笺疏》下卷上〈宠礼〉～723～","w":"王珣、郗超并有奇才，为大司马所眷拔。珣为主簿，超为记室参军。超为人多须，珣状短小。于时荆州为之语曰：「髯参军，短主簿。能令公喜，能令公怒。」","q":[]},{"n":"汉南春","d":"","s":"北周·庾信《庾子山集》卷一《枯树赋》","w":"桓大司马闻而叹曰：「昔年种柳，依依汉南；今看摇落，凄怆江潭。树犹如此，人何以堪！」","q":[["树异桓宣武，园非顾辟疆。","唐彦谦 红叶"],["不似当时大司马，重来得见汉南春。","徐凝 浙东故孟尚书种柳"]]},{"n":"浩浩洪流","d":"","s":"《世说新语笺疏》中卷上〈雅量〉～369～","w":"桓公伏甲设馔，广延朝士，因此欲诛谢安、王坦之。王甚遽，问谢曰：「当作何计？」谢神意不变，谓文度曰：「晋阼存亡，在此一行。」相与俱前。王之恐状，转见于色。谢之宽容，愈表于貌。望阶趋席，方作洛生咏，讽「浩浩洪流」。桓惮其旷远，乃趣解兵。","q":[["彼亦一时，此亦一时。浩浩洪流之咏何必奇。","李白 东山吟"]]},{"n":"桓温奇骨","d":"","s":"《晋书》卷九十八《桓温传》","w":"桓温字元子，宣城太守彝之子也。生未而太原温峤见之，曰：「此儿有奇骨，可试使啼。」及闻其声，曰：「真英物也！」彝以峤所赏，故遂名之曰温。峤笑曰：「果尔，后将易吾姓也。」","q":[["桓温奇骨，邓艾大志。","李瀚 蒙求"]]},{"n":"可能无势，我驾驭卿","d":"","s":"《全上古三代秦汉三国六朝文·全晋文》卷一百十二〈陶潜·晋故征西大将军长史孟府君传〉","w":"君讳嘉，字万年，江夏鄂人也。曾祖父宗，以孝行称，仕吴司空。宋本作空，一作马，非。祖父揖，元康中为庐陵太守。宗葬武昌新阳县，子孙家焉，遂为县人也。君少失父，奉母二弟居。娶大司马长沙桓公陶侃第十女，闺门孝，友人无能间，乡闾称之。冲默有远量，弱冠…","q":[]},{"n":"那须预人家国","d":"","s":"《世说新语笺疏》下卷下〈轻诋〉～839～","w":"桓公欲迁都，以张拓定之业。孙长乐上表，谏此议甚有理。桓见表心服，而忿其为异，令人致意孙云：「君何不寻〈遂初赋〉，而彊知人家国事？」","q":[]},{"n":"宁作我","d":"","s":"《世说新语笺疏》中卷下〈品藻〉～52～","w":"桓公少与殷侯齐名，常有竞心。桓问殷：「卿何如我？」殷云：「我与我周旋久，宁作我。」","q":[]},{"n":"入幕","d":"","s":"《晋书》卷六十七〈郗鉴列传·（郗愔子）郗超〉～802～","w":"超字景兴，一字嘉宾。少卓荦不羁，有旷世之度，交游士林，每存胜拔，善谈论，义理精微。愔事天师道，而超奉佛。愔又好聚敛，积钱数千万，尝开库，任超所取。超性好施，一日中散与亲故都尽。其任心独诣，皆此类也。……桓温辟为征西大将军掾。温迁大司马，又转…","q":[]},{"n":"碎金","d":"","s":"《世说新语》上卷下《文学》","w":"桓公见谢安石作简文谥议，看竟，掷与坐上诸客曰：「此是安石碎金。」","q":[["鲁殿铿寒玉，苔山激碎金。","韦庄 和薛先辈见寄初秋寓怀即事之作二十韵"]]},{"n":"郗嘉宾","d":"","s":"《晋书》卷六十七〈郗鉴列传·（郗愔子）郗超〉～802～","w":"超字景兴，一字嘉宾。少卓荦不羁，有旷世之度，交游士林，每存胜拔，善谈论，义理精微。愔事天师道，而超奉佛。愔又好聚敛，积钱数千万，尝开库，任超所取。超性好施，一日中散与亲故都尽。其任心独诣，皆此类也。……桓温辟为征西大将军掾。温迁大司马，又转…","q":[]},{"n":"谢掾","d":"","s":"《晋书》卷六十五《王导传》附《王珣传》","w":"珣字元琳。弱冠与陈郡谢玄为桓温掾，俱为温所敬重，尝谓之曰：「谢掾年四十，必拥旄杖节。王掾当作黑头公。皆未易才也。」","q":[["隋邸旧僚推谢掾，汉廷高议得相如。","罗隐 淮南送工部卢员外赴阙"]]},{"n":"须作猬毛磔","d":"","s":"《晋书》卷九十八〈桓温列传〉～2568～","w":"温豪爽有风概，姿貌甚伟，面有七星。少与沛国刘惔善，惔尝称之曰：「温眼如紫石棱，须作猬毛磔，孙仲谋、晋宣王之流亚也。」选尚南康长公主，拜驸马都尉，袭爵万宁男，除琅邪太守，累迁徐州刺史。","q":[]}],"35":[{"n":"伯阳遁","d":"","s":"《史记》卷六十三《老子列传》","w":"老子脩道德，其学以自隐无名为务。居周久之，见周之衰，乃遂去。至关，关令尹喜曰：「子将隐矣，彊为我著书。」于是老子乃著书上下篇，言道德之意五千馀言而去，莫知其所终。","q":[["仲尼溺东鲁，伯阳遁西溟。","陈子昂 感遇诗三十八首"]]},{"n":"函谷关","d":"","s":"《史记》卷六十三〈老子韩非列传·老子〉～24～","w":"老子脩道德，其学以自隐无名为务。居周久之，见周之衰，乃遂去。至关，关令尹喜曰：「子将隐矣，彊为我著书。」于是老子乃著书上下篇，言道德之意五千馀言而去，莫知其所终。南朝宋·裴骃《史记集解》引《列仙传》曰：「关令尹喜者，周大夫也。善内学星宿，服…","q":[["紫气关临天地阔，黄金台贮俊贤多。","杜甫 承闻河北诸道节度入朝欢喜口号绝句十二首之九"],["西望瑶池降王母，东来紫气满函关。","杜甫 秋兴八首之五"]]},{"n":"宠辱惊","d":"","s":"《老子·道经·十三章》～48～","w":"宠辱若惊，贵大患若身。何谓宠辱？辱为下。得之若惊，失之若惊，是谓宠辱若惊。","q":[]},{"n":"聃丘","d":"","s":"《史记》卷四十七〈孔子世家〉～905～","w":"孔子生鲁昌平乡陬邑。其先宋人也，曰孔防叔。防叔生伯夏，伯夏生叔梁纥。纥与颜氏女野合而生孔子，祷于尼丘得孔子。鲁襄公二十二年而孔子生。生而首上圩顶，故因名曰丘云。字仲尼，姓孔氏。","q":[]},{"n":"青牛","d":"","s":"《史记》卷六十三《老子韩非列传》","w":"「老子脩道德，其学以自隐无名为务。居周久之，见周之衰，乃遂去。至关，关令尹喜曰：『子将隐矣，彊为我著书。』于是老子乃著书上下篇，言道德之意五千馀言而去，莫知其所终。」唐·司马贞《史记索隐》引《列仙传》：「老子西游，关令尹喜望见有紫气浮关，而…","q":[["白马公孙何处去，青牛老人更不还。","岑参 函谷关歌送刘评事使关西"],["白马高谈去，青牛真气来。","王勃 散关晨度"]]},{"n":"方瞳人","d":"方瞳人：喻神仙道士。唐陆龟蒙《人林屋洞》：“自非方瞳人，不敢窥洞口.”","s":"旧题晋·王嘉《拾遗记》卷三","w":"老聃在周之末，居反景日室之山，与世人绝迹。帷有黄发老叟五人，或乘鸿鹤，或衣羽毛，耳出于顶，瞳子皆方，面色玉洁，手握青筠之杖，与聃共谈天地之数。","q":[["麻姑山下逢真士，玄肤碧眼方瞳子。","李咸用 临川逢陈百年"],["山际逢羽人，方瞳好容颜。","李白 游泰山六首"]]},{"n":"化胡","d":"","s":"旧题汉·刘向《列仙传》卷上《关令尹喜》","w":"关令尹喜者，周大夫也。善内学星宿，服精华，隐德行仁，时人莫知。老子西游，喜先见其气，知真人当过，候物色而迹之，果得老子。老子亦知其奇，为著书。与老子俱之流沙之西，服臣胜实，莫知其所终。亦著书九篇，名关令子。","q":[["仲尼欲浮海，吾祖之流沙。","李白 古风"],["北走非通赵，西之似化胡。","骆宾王 久戍边城有怀京邑"]]},{"n":"黄老","d":"","s":"《史记》卷六十三《老子列传》附《申不害传》","w":"申子之学本于黄老而主刑名。著书二篇，号曰《申子》。","q":[["世业事黄老，妙年孤隐沦。","宋之问 始安秋日"]]},{"n":"老氏训","d":"","s":"《老子》第十二章","w":"五色令人目盲；五音令人耳聋；五味令人口爽；驰骋田猎，令人心发狂；难得之货，令人行妨。是以圣人为腹不为目。故去彼取此。","q":[["犹怀老氏训，感叹此欢娱。","高适 同群公出猎海上"]]},{"n":"老子犹龙","d":"","s":"《史记》卷六十三〈老子韩非列传·老子〉～239～","w":"老子者，楚苦县厉乡曲仁里人也，姓李氏，名耳，字聃，周守藏室之史也。孔子适周，将问礼于老子。老子曰：「子所言者，其人与骨皆已朽矣，独其言在耳。且君子得其时则驾，不得其时则蓬累而行。吾闻之，良贾深藏若虚，君子盛德容貌若愚。去子之骄气与多欲，态色…","q":[]},{"n":"指树日","d":"","s":"《神仙传》卷一〈老子〉","w":"老子者，名重耳，字伯阳。……或云，老子之母，适至李树下而生。老子生而能言，指李树曰：「以此为我姓。」","q":[["岁岁相传指树日，翩翩来伴庆云翔。","张说 舞马千秋万岁乐府词三首"],["李树影笼周柱史，昴星光照汉酂侯。","徐夤 府主仆射王抟生日"]]},{"n":"烹小鲜","d":"","s":"《老子·德经·六十章》","w":"治大国若烹小鲜。以道莅天下，其鬼不神。非其鬼不神，其神不伤人。非其神不伤人，圣人亦不伤人。夫两不相伤，故得交归。汉·河上公注：「烹小鱼不去肠，不去鳞，不敢挠，恐其糜也。」三国魏·王弼注：「不扰也。」","q":[["家怜双鲤断，才愧小鳞烹。","刘长卿 至德三年春正月时谬蒙差摄海盐令闻王师收二京因书事寄上浙西节度李侍郎中丞行营五十韵"],["宝剑诚可用，烹鲜是虚弃。","刘长卿 送薛据宰涉县"]]},{"n":"彭聃","d":"","s":"《楚辞》卷三《天问》","w":"「彭铿斟雉尧帝飨何，受寿永多夫何久长。」东汉·王逸注：「彭铿，彭祖也。好和滋味，善斟雉羹，能事帝尧，尧美而飨食之。」「言彭祖进雉羹于尧，尧飨食之以寿考。彭祖至八百岁，犹自悔不寿，」","q":[["颜回徒恨少成古，彭祖何曾老至今。","刘威 感寓"],["王母桃花千遍红，彭祖巫咸几回死。","李贺 浩歌"]]},{"n":"戎马生郊","d":"","s":"《老子》第四十六章","w":"天下有道，却走马以粪，天下无道，戎马生于郊。","q":[["戎马生郊日，贤人避地初。","张南史 早春书事奉寄中书李舍人"],["不谓生戎马，何知共酒杯。","杜甫 郑驸马池台喜遇郑广文同饮"]]},{"n":"舌为柔","d":"","s":"汉·刘向《说苑·敬慎》","w":"常摐有疾，老子往问焉，曰：「先生疾甚矣，无遗教可以语诸弟子者乎？」常摐曰：「子虽不问，吾将语子。」常摐曰：「过故乡而下车，子知之乎？」老子曰：「过故乡而下车，非谓其不忘故耶？」常摐曰：「嘻，是已。」常摐曰：「过乔木而趋，子知之乎？」老子曰：…","q":[["自从齿牙缺，始慕舌为柔。","韩愈 赴江陵途中寄赠王二十补阙李十一拾遗李二十六员外翰林三学士"]]},{"n":"守雌","d":"","s":"《老子》第二十八章","w":"「知其雄，守其雌，为天下溪。」汉·河上公注：「雄以喻尊，雌以喻卑。人虽知自尊显，当复守之以卑微，去之强梁，就雌之柔和。」","q":[["黠吏因封己，公才或守雌。","杜甫 赠崔十三评事公辅"]]},{"n":"橐籥功","d":"","s":"《老子》第五章","w":"天地之间，其犹橐蘥。虚而不屈，动而俞出。多言数穷，不如守中。","q":[["渐飏抟扶势，应从橐籥功。","张聿 景风扇物"]]},{"n":"五千言","d":"五千言：指《道德经》。唐李群王《别尹炼师》：“吾家五千言，至道悬日月。”","s":"《史记》卷六十三〈老子韩非列传·老子〉～24～","w":"老子脩道德，其学以自隐无名为务。居周久之，见周之衰，乃遂去。至关，关令尹喜曰：「子将隐矣，彊为我著书。」于是老子乃著书上下篇，言道德之意五千馀言而去，莫知其所终。","q":[["斋心调笔砚，唯写五千言。","姚合 武功县中作三十首"],["五千言外无文字，更有何词赠武皇。","曹唐 送刘尊师祗诏阙庭三首"]]},{"n":"象帝","d":"","s":"《老子》第四章","w":"吾不知谁知子，象帝之先。","q":[["象帝威容大，仙宗宝历赊。","韩愈 奉和杜相公太清宫纪事陈诚上李相公十六韵"]]},{"n":"徐甲","d":"","s":"《神仙传》卷一〈老子》","w":"老子有客徐甲，少赁于老子，约日雇百钱，计欠甲七百二十钱。甲见老子出关游行，速索偿不可得，乃倩人作辞，诣关令尹喜，以言老子。而为作辞者亦不知甲已随老子二百馀年矣，惟计甲所应直之多，许以女嫁甲。甲见女美，尤喜，遂通辞于尹。喜得辞一惊，乃见老子。…","q":[["不因杖屦逢周史，徐甲何曾有此身。","李商隐 赠华阳宋真人兼寄清都刘先生"],["弟子悲徐甲，门人泣蔡经。","李德裕 遥伤茅山县孙尊师三首之二"]]},{"n":"周史","d":"","s":"《高士传》卷上〈老子李耳〉～","w":"老子李耳字伯阳……生于殷时，为周柱下史，好养经气……后周德衰，乃乘青牛去，入大秦，过西关。","q":[["柱史从来非俗吏，青牛道士莫相疑。","储嗣宗 山邻"],["不因杖屦逢周史，徐甲何曾有此身。","李商隐 赠华阳宋真人兼寄清都刘先生"]]}],"36":[{"n":"吐哺握发","d":"周公吐哺：喻殷勤礼待贤士，或喻为政事而操心忙碌。三国魏曹操《短取行卜”周公吐哺，天下归心。”","s":"《史记》卷三十三〈鲁周公世家〉～58～","w":"于是卒相成王，而使其子伯禽代就封于鲁。周公戒伯禽曰：「我文王之子，武王之弟，成王之叔父，我于天下亦不贱矣。然我一沐三捉发，一饭三吐哺，起以待士，犹恐失天下之贤人。子之鲁，慎无以国骄人。」","q":[["上公频握发，才子共垂帷。","钱起 送任先生任唐山丞"],["重士过三哺，轻财抵一铢。","白居易 和微之春日投简阳明洞天五十韵"]]},{"n":"鸱鸮悲","d":"","s":"《尚书》卷十三〈周书·金縢〉～88～","w":"武王既丧，管叔及其群弟，乃流言于国曰：「公将不利于孺子。」周公乃告二公曰：「我之弗辟，我无以告我先王。」周公居东二年，则罪人斯得，于后，公乃为诗以贻王，名之曰〈鸱鸮〉，王亦未敢诮公。","q":[["鸱鸮悲东国，麋鹿泣姑苏。","陈子昂 感遇诗三十八首之十五"]]},{"n":"吾衰矣","d":"","s":"《论语·述而》～60～","w":"子曰：「甚矣，吾衰也！久矣，吾不复梦见周公！」","q":[["凄其望吕葛，不复梦周孔。","杜甫 晚登瀼上堂"]]},{"n":"分陜","d":"","s":"《春秋公羊传注疏》卷三〈隐公·隐公五年〉～34～","w":"九月。考仲子之宫。考宫者何。考。犹入室也。始祭仲子也。桓未君。则曷为祭仲子。隐为桓立。故为桓祭其母也。然则何言尔。成公意也。初献六羽。初者何。始也。六羽者何。舞也。初献六羽何以书。讥。何讥尔。讥始僭诸公也。六羽之为僭奈何。天子八佾。诸公六。…","q":[]},{"n":"弗堂","d":"","s":"《尚书》卷十三〈周书·大诰〉～93～","w":"王曰：「若昔，朕其逝。朕言艰日思。若考作室，既厎法，厥子乃弗肯堂，矧肯构？厥父菑，厥子乃弗肯播，矧肯获？厥考翼其肯曰：『予有后，弗弃基？』肆予曷敢不越卬敉宁王大命？若兄考，乃有友伐厥子，民养其劝弗救？」旧题汉·孔安国传：「以作室喻治政也。父…","q":[]},{"n":"公旦思周","d":"","s":"《史记》卷三十三《鲁周公世家》","w":"周公在丰，病，将没，曰：「必葬我成周，以明吾不敢离成王。」周公既卒，成王亦让，葬周公于毕，从文王，以明予小子不敢臣周公也。","q":[["谁言圣与哲，曾是不怀土。公旦既思周，宣尼亦念鲁。","李德裕 夏晚有怀平泉林居"]]},{"n":"管蔡","d":"","s":"《史记》卷三十五《管蔡世家》","w":"管叔鲜、蔡叔度者，周文王子而武王弟也。……武王既崩，成王少，周公旦专王室。管叔、蔡叔疑周公之为不利于成王，乃挟武庚以作乱。周公旦承成王命伐诛武庚，杀管叔，而放蔡叔，迁之，与车十乘，徒七十人从。……太史公曰：管蔡作乱，无足载者。","q":[["周公称大圣，管蔡宁相容。","李白 箜篌谣"]]},{"n":"姬旦制礼乐","d":"","s":"《礼记注疏》卷三十一〈明堂位〉～576～","w":"武王崩，成王幼弱，周公践天子之位，以治天下。六年，朝诸侯于明堂，制礼作乐，颁度量，而天下大服。","q":[["礼乐囚姬旦，诗书缚孔丘。","王绩 赠程处士"]]},{"n":"金滕","d":"","s":"《尚书·周书·金縢》","w":"公归，乃纳册于金縢之匮中，王翼日乃瘳。","q":[["千官不起金縢议，万国空瞻玉藻声。","曹唐 三年冬大礼五首"],["玉玺终无虑，金縢意不开。","温庭筠 中书令裴公挽歌词二首"]]},{"n":"鲁卫","d":"","s":"《论语·子路》","w":"「子曰：『鲁卫之政兄弟也。』三国魏·何晏《集解》引包氏曰：「鲁，周公之封；卫，康叔之封。周公、康叔既为兄弟，康叔睦于周公，其国之政亦如兄弟 。」","q":[["鲁卫弥尊重，徐陈略丧亡。","杜甫 戏题寄上汉中王三首之三"]]},{"n":"七月诗","d":"","s":"《毛诗正义》卷八之一〈国风·豳风·七月〉～279～","w":"毛诗序：「〈七月〉，陈王业也。周公遭变故，陈后稷先公风化之所由，致王业之艰难也。」","q":[["因思上党三年战，闲咏周公七月诗。","杜牧 即事"]]},{"n":"叔父居东","d":"","s":"《尚书》卷十三〈周书·金縢〉～88～","w":"公归，乃纳册于金縢之匮中。王翼日乃瘳。武王既丧，管叔及其群弟乃流言于国，曰：「公将不利于孺子。」周公乃告二公曰：「我之弗辟，我无以告我先王。」周公居东二年，则罪人斯得。于后，公乃为诗以贻王，名之曰「鸱鸮」；王亦未敢诮公。唐·孔颖达疏：「《诗…","q":[]},{"n":"伊周","d":"","s":"《汉书》卷四十《张陈王周传赞》","w":"「周勃为布衣时，鄙朴庸人，至登辅佐，匡国家难，诛诸吕，立孝文，为汉伊周，何其盛也！」唐·颜师古注：「处伊尹、周公之任。」","q":[["处贵有馀兴，伊周位不如。","钱起 晚出青门望终南别业"]]},{"n":"周姬旦","d":"","s":"《史记》卷四《周本纪》","w":"武王即位，太公望为师，周公旦为辅，召公、毕公之徒左右王，师脩文王绪业。……成王少，周初定天下，周公恐诸侯畔周，公乃摄行政当国。管叔、蔡叔群弟疑周公，与武庚作乱，畔周。周公奉成王命，伐诛武庚、管叔，放蔡叔。以微子开代殷后，国于宋。颇收殷馀民，…","q":[["卒卒周姬旦，栖栖鲁孔丘。","刘希夷 故园置酒"],["周公称大圣，管蔡宁相容。","李白 箜篌谣"]]},{"n":"周公在前鲁公后","d":"","s":"《春秋公羊传注疏》卷十四〈文公·十三年〉～77～","w":"周公何以称大庙于鲁？封鲁公以为周公也。周公拜乎前。鲁公拜乎后。曰：「生以养周公，死以为周公。」汉·何休解诂：「始受封时拜于文王庙也。《尚书》曰『用命赏于祖』是也。父子俱拜者，明以周公之功封鲁公也。」","q":[]},{"n":"周公祓禊","d":"","s":"《艺文类聚》卷四〈岁时部中·三月三日〉～63～","w":"《续齐谐记》曰：晋武帝问尚书郎挚虞曰：「三日曲水，其义何指？」答曰：「汉章帝时，平原徐肇，以三月初生三女，至三日俱亡，一村以为怪，乃相携之水滨盥洗。遂因水以汎觞，曲水之义起于此。」帝曰。「若如所谈，便非好事。」尚书郎束皙曰：「仲治小生，不足…","q":[]},{"n":"周公惧流言","d":"","s":"《史记》卷三十三〈鲁周公世家〉～58～","w":"「其后武王既崩，成王少，在强葆之中。周公恐天下闻武王崩而畔，周公乃践阼代成王摄行政当国。管叔及其群弟流言于国曰：『周公将不利于成王。』周公乃告太公望、召公奭曰：『我之所以弗辟而摄行政者，恐天下畔周，无以告我先王太王、王季、文王。三王之忧劳天…","q":[["周公恐惧流言后，王莽谦恭未篡时。","白居易 放言五首"]]},{"n":"周公留召","d":"","s":"《史记》卷三十四〈燕召公世家〉～549～","w":"其在成王时，召王为三公：自陕以西，召公主之；自陕以东，周公主之。成王既幼，周公摄政，当国践祚，召公疑之，作君奭。君奭不说周公。周公乃称「汤时有伊尹，假于皇天；在太戊时，则有若伊陟、臣扈，假于上帝，巫咸治王家；在祖乙时，则有若巫贤；在武丁时，…","q":[]},{"n":"周家叔父把元龟","d":"","s":"《尚书》卷十三〈周书·大诰〉～89～","w":"武王崩，三监及淮夷叛，周公相成王，将黜殷。作《大诰》。","q":[]},{"n":"周孔","d":"","s":"《昭明文选》卷十五东汉·张平子（衡）《归田赋》","w":"「弹五弦之妙指，咏周孔之图书。」唐·李善注：「周，周公；孔，孔子也。」","q":[["轩皇竟磨灭，周孔亦衰老。","孟云卿 放歌行"],["周孔传文教，萧曹授武经。","杜牧 分司东都寓居履道叨承川尹刘侍郎大夫恩知上四十韵"]]},{"n":"梓材","d":"","s":"《尚书·周书·梓材》","w":"「若作梓材，既勤朴斲，惟其涂丹雘。」旧题汉·孔安国传：「为政之术，如梓人治材为器。」","q":[["世惟材是梓，人仰骥中骅。","柳宗元 同刘二十八院长叙旧言怀感时书事奉寄张员外使君五十二韵之作因其韵增至八十通赠二君子"]]}],"37":[{"n":"欧苏","d":"","s":"金王若虚《送吕鹏举赴举序》","w":"故必探《语》《孟》之渊源，撷 欧 苏 之菁英。","q":[]},{"n":"孟韩","d":"","s":"宋苏洵《上田枢密书》","w":"孟 韩 之温醇， 迁 固 之雄刚， 孙 吴 之简切，投之所向，无不如意。","q":[]},{"n":"龙虎榜","d":"","s":"《新唐书》卷二百三〈文艺列传下·欧阳詹〉～5786～","w":"欧阳詹字行周，泉州晋江人。其先皆为本州州佐、县令。闽越地肥衍，有山泉禽鱼，虽能通文书吏事，不肯北宦。及常衮罢宰相为观察使，始择县乡秀民能文辞者，与为宾主钧礼，观游飨集必与，里人矜耀，故其俗稍相劝仕。初，詹与罗山甫同隐潘湖，往见衮，衮奇之。辞…","q":[]},{"n":"宝唾","d":"","s":"《全唐诗》卷七百九十一〈城南联句〉【案：此首又见张籍集。】","w":"竹影金琐碎【案：孟郊。】，泉音玉淙琤。琉璃剪木叶【案：韩愈。】，翡翠开园英。流滑随仄步【案：孟郊。】，搜寻得深行。遥岑出寸碧【案：韩愈。】，远目增双明。乾穟纷拄地【案：孟郊。】，化虫枯挶茎。木腐或垂耳【案：韩愈。】，草珠竞骈睛。浮虚有新斸【…","q":[]},{"n":"冰柱雪车","d":"","s":"《新唐书》卷一百七十六〈韩愈列传·刘叉〉～5268～","w":"时又有贾岛、刘叉，皆韩门弟子。刘叉者，亦一节士。少放肆为侠行，因酒杀人亡命。会赦，出，更折节读书，能为歌诗。然恃故时所负，不能俛仰贵人，常穿屐、破衣。闻愈接天下士，步归之，作冰柱、雪车二诗，出卢仝、孟郊右。樊宗师见，为独拜。能面道人短长，其…","q":[]},{"n":"盘谷序","d":"","s":"《全唐文》卷五百五十五〈韩愈九·送李愿归盘谷序〉～565～2～","w":"太行之阳有盘谷。盘谷之间，泉甘而土肥，草木丛茂，居民鲜少。或曰：「谓其环两山之间，故曰盘。」或曰：「是谷也，宅幽而势阻，隐者之所盘旋。」友人李愿居之。愿之言曰：「人之称大丈夫者，我知之矣：利泽施于人，名声昭于时，坐于庙朝，进退百官，而佐天子…","q":[]},{"n":"川泳云飞","d":"","s":"《全唐文》卷五百五十七〈韩愈十一·徐泗豪三州节度掌书记厅石记〉～5634～","w":"书记之任亦难矣！元戎整齐三军之士，统理所部之氓，以镇守邦国，赞天子施教化，而又外与宾客四邻交，其朝觐、聘问、慰荐、祭祀、祈祝之文，与所部之政，三军之号令升黜，凡文辞之事，皆出书记。非闳辨通敏兼人之才，莫宜居之。然皆元戎自辟，然后命于天子。苟…","q":[]},{"n":"儿时某邱某水","d":"","s":"《韩昌黎文集》卷四〈送杨少尹序〉","w":"昔疏广受二子以年老。一朝辞位而去。于时公卿设供张。祖道都门外。车数百两。道路观者多叹息泣下。共言其贤。汉史既传其事。而后世工画者又图其迹。至今照人耳目。赫赫若前日事。国子司业杨君巨源。方以能诗训后进。一旦以年满七十。亦白丞相去归其乡。世常说…","q":[]},{"n":"故园桃李待君花发","d":"","s":"《唐语林校證》卷六〈补遗〉～585～","w":"韩退之有二妾，一曰绛桃，一曰柳枝，皆能歌舞。初使王庭凑，至寿阳驿，绝句云：「风光欲动别长安，春半边城特地寒，不见园花兼巷柳，马头惟有月团团。」盖有所属也。柳枝后踰垣遁去，家人追获。及镇州初归，诗曰：「别来杨柳街头树，摆弄春风只欲飞。还有小园…","q":[]},{"n":"韩昌黎贬水曹","d":"","s":"《新唐书》一百七十六〈韩愈列传〉～5258～","w":"宪宗遣使者往凤翔迎佛骨入禁中，三日，乃送佛祠。王公士人奔走膜呗，至为夷法灼体肤，委珍贝，腾沓系路。愈闻恶之，乃上表曰：……表入，帝大怒，持示宰相，将抵以死。裴度、崔群曰︰「愈言讦牾，罪之诚宜。然非内怀至忠，安能及此？愿少宽假，以来谏争。」帝…","q":[]},{"n":"韩令裁成花丛","d":"","s":"《酉阳杂俎》卷十九〈广动植之四〉","w":"韩愈侍郎有疏从子侄自江淮来，年甚少，韩令学院中伴子弟，子弟悉为凌辱。韩知之，遂为街西假僧院令读书。经旬，寺主纲复诉其狂率，韩遽令归，且责曰：「市肆贱类营衣食，尚有一事长处。汝所为如此，竟作何物？」职拜谢，徐曰：「某有一艺，恨叔不知。」因指阶…","q":[]},{"n":"韩愈文章","d":"","s":"《旧唐书》卷一百六十〈韩愈列传〉～4203～","w":"常以为自魏、晋已还，为文者多拘偶对，而经诰之指归，迁、雄之气格，不复振起矣。故愈所为文，务反近体，抒意立言，自成一家新语。后学之士，取为师法。当时作者甚?，无以过之，故世称「韩文」焉。","q":[]},{"n":"虎榜","d":"","s":"《新唐书》卷二百三〈文艺列传下·欧阳詹〉～5786～","w":"欧阳詹字行周，泉州晋江人。其先皆为本州州佐、县令。闽越地肥衍，有山泉禽鱼，虽能通文书吏事，不肯北宦。及常衮罢宰相为观察使，始择县乡秀民能文辞者，与为宾主钧礼，观游飨集必与，里人矜耀，故其俗稍相劝仕。初，詹与罗山甫同隐潘湖，往见衮，衮奇之。辞…","q":[]},{"n":"眉间黄","d":"","s":"《全唐诗》卷三百四十四〈郾城晚饮奉赠副使马侍郎及冯【案：宿。】李【案：宗闵。】二员外〉【案：冯李时从裴度东征。】","w":"城上赤云呈胜气，眉间黄色见归期。幕中无事惟须饮，即是连镳向阙时。","q":[]},{"n":"今世无工","d":"","s":"《全唐文》卷五百五十六〈韩愈十·送杨少尹序〉～5623～","w":"昔疏广、受二子以年老，一朝辞位而去，于时公卿设供张，祖道都门外，车数百两，道路观者多叹息泣下，共言其贤。汉史既传其事，而后世工画者又图其迹，至今照人耳目，赫赫若前日事。国子司业杨君巨源，方以能诗训后进，一旦以年满七十，亦白丞相去归其乡。世常…","q":[]},{"n":"狂韩愈","d":"","s":"《全唐诗》卷三百四十五〈芍药歌【王司马红芍药歌】〉","w":"丈人庭中开好花，更无凡木争春华。翠茎红蕊天力与，此恩不属黄钟家。温馨熟美鲜香起，似笑无言习君子。霜刀剪汝天女劳，何事低头学桃李。娇痴婢子无灵性【娇痴婢子无性灵】，竞挽春衫来比并。欲将双颊一晞红【欲将双颊一稀红】，绿窗磨遍青铜镜。一尊春酒甘若…","q":[]},{"n":"柳枝","d":"","s":"《唐语林校證》卷六〈补遗〉～585～","w":"韩退之有二妾，一曰绛桃，一曰柳枝，皆能歌舞。初使王庭凑，至寿阳驿，绝句云：「风光欲动别长安，春半边城特地寒，不见园花兼巷柳，马头惟有月团团。」盖有所属也。柳枝后踰垣遁去，家人追获。及镇州初归，诗曰：「别来杨柳街头树，摆弄春风只欲飞。还有小园…","q":[]},{"n":"文公记","d":"","s":"《全唐文》卷五百五十七〈韩愈十一·新修滕王阁记〉～5635～","w":"愈少时，则闻江南多临观之美，而滕王阁独为第一，有瑰伟绝特之称。及得三王，所为序、赋、记等，壮其文辞，益欲往一观而读之，以忘吾忧，系官于朝，愿莫之遂。十四年，以言事斥守揭阳，便道取疾以至海上，又不得过南昌而观所谓滕王阁者。其冬，以天子进大号，…","q":[]},{"n":"瑶环瑜珥","d":"","s":"《全唐文》卷五百六十三〈韩愈十七·殿中少监马君墓志〉～5705～","w":"君讳继祖，司徒赠太师北平庄武王之孙，少府监赠太子少傅讳畅之子。生四岁，以门功拜太子舍人。积三十四年，五转而至殿中少监，年三十七以卒。有男八人，女二人。始子初冠，应进士贡在京师，穷不自存，以故人稚弟拜北平王于马前，王问而怜之，因得见于安邑里第…","q":[]},{"n":"玉雪","d":"","s":"《全唐文》卷五百六十四〈韩愈十八·幽州节度判官赠给事中清河张君墓志铭〉～5708～","w":"呜呼彻也。世慕顾以行，子揭揭也。噎暗以为生，子独割也。为彼不清，作玉雪也。仁义以为兵，用不缺折也。知死不失名，得猛烈也。自申于暗明，莫之夺也。我铭以贞之，不肖者之咀也。","q":[]},{"n":"周情孔思","d":"","s":"《全唐文》卷七百四十四〈李汉·唐吏部侍郎昌黎先生讳愈文集序〉～7697～2～","w":"汗澜卓踔，奫泫澄深，诡然而蛟龙翔，蔚然而虎凤跃，锵然而韶钧鸣，日光玉洁，周情孔思，千态万貌，卒泽于道德仁义，炳如也，洞视万古，湣恻当世，遂大拯颓风，教人自为。时人始而惊，中而笑且排，先生志益坚，其终人亦翕然，而随以定。","q":[]}],"38":[{"n":"三偷","d":"","s":"《博物志》卷八","w":"汉武帝好仙道，祭祀名山大泽，以求神仙之道。时西王母遣使乘白鹿告帝当来乃供帐九华殿以待之。七月七日夜漏七刻，王母乘紫云车而至……有三青鸟，如乌大，使侍母旁。时设九微灯。帝东面西向，王母索七桃，大如弹丸，以五枚与帝母食二枚。帝食桃辄以核著膝前，…","q":[["闲寻白鹿眠瑶草，暗摘红桃去洞天。","刘威 赠道者"],["惟应错认偷桃客，曼倩曾为汉侍郎。","崔澹 赠王福娘"]]},{"n":"金马客","d":"吏隐：指人行为高洁又不隐遁山林。元袁桶《次韵抵平石》：“金门吏隐愧相如，岁月这巡翰墨疏。”","s":"《史记》卷一百二十六〈滑稽列传〉～3205～","w":"朔行殿中，郎谓之曰：「人皆以先生为狂。」朔曰：「如朔等，所谓避世于朝廷閒者也。古之人，乃避世于深山中。」时坐席中，酒酣，据地歌曰：「陆沈于俗，避世金马门。宫殿中可以避世全身，何必深山之中，蒿庐之下。」金马门者，宦者署门也，门傍有铜马，故谓之…","q":[["复有金门客，来参萝薜衣。","储光羲 寻徐山人遇马舍人"],["锦帐为郎日，金门待诏时。","张说 李工部挽歌三首"]]},{"n":"东方朔","d":"","s":"《汉书》卷六十五《东方朔传》","w":"「东方朔字曼倩，平原厌次人也。武帝初即位，徵天下举方正贤良文学材力之士，待以不次之位，四方士多上书言得失，自衒鬻者以千数，其不足采者辄报闻罢。朔初来，上书曰：『……朔文辞不逊，高自称誉，上伟之，令待诏公车，奉禄薄，未得省见。』久之，朔绐驺朱…","q":[["侍郎跨方朔，中丞蔑周处。","储光羲 晚次东亭献郑州宋使君文"],["臣朔真何幸，常陪汉武游。","崔湜 幸白鹿观应制"]]},{"n":"大臣书","d":"","s":"《汉书》卷六十五《东方朔传》","w":"武帝初即位，徵天下举方正贤良文学材力之士，待以不次之位，四方士多上书言得失，……臣朔年二十二，长九尺三寸，目若悬珠，齿若编贝，勇若孟贲，捷若庆忌，廉若鲍叔，信若尾生。若此，可以为天子大臣矣。」","q":[["怀君欲何赠，愿上大臣书。","陈子昂 春夜别友人二首"]]},{"n":"电光䃸磹","d":"","s":"旧题汉·东方朔《海内十洲记·聚窟洲》","w":"「延和三年，武帝幸安定，而月支国遣使献香。」「献猛兽一头形如犬子似狸而色黄。」「使者乃指兽命唤一声，兽舐唇良久，忽叫，如天大雷霹雳，又两目如䃸磹之交光，光朗冲天，良久乃止。帝登时颠蹶掩耳，震动不能自止。」","q":[["电光䃸磹赪目䁔，顼冥收威避玄根。","韩愈 陆浑山火和皇甫湜用其韵（湜时为陆浑尉）"]]},{"n":"东方小儿","d":"","s":"晋·张华《博物志》卷八《史补》","w":"汉武帝好仙道，祭祀名山大泽以求神仙之道。时西王母遣使乘白鹿告帝当来，乃供帐九华殿以待之。七月七日夜漏七刻，王母乘紫云车而至于殿西。……帝东面西向，王母索七桃，大如弹丸，以五枚与帝，母食二枚。……唯帝与母对坐，其从者皆不得进。时东方朔窃从殿南…","q":[["仙桃不啻三回熟，饱见东方一小儿。","施肩吾 赠凌仙姥"],["愿同西王母，下顾东方朔。","李白 赠嵩山焦炼师"]]},{"n":"东马严徐","d":"","s":"《汉书》卷六十四上〈严朱吾丘主父徐严终王贾列传上·严助〉～2775～","w":"严助，会稽吴人，严夫子子也，或言族家子也。郡举贤良，对策百馀人，武帝善助对，繇是独擢助为中大夫。后得朱买臣、吾丘寿王、司马相如、主父偃、徐乐、严安、东方朔、枚皋、胶仓、终军、严葱奇等，并在左右。是时征伐四夷，开置边郡，军旅数发，内改制度，朝…","q":[]},{"n":"方朔去","d":"","s":"《太平广记》卷三〈神仙三·汉武帝〉～22～","w":"帝既见王母及上元夫人，乃信天下真有神仙之事。其后，帝以王母所授《五贞图》、《灵光经》及上元夫人所授《六甲灵飞十二事》自撰集为一卷，及诸经图，皆奉以黄金之箱封，以白玉之函，以珊瑚为轴，紫锦为囊，安著柏梁台上。数自斋洁朝拜，烧香洒扫，然后乃执省…","q":[["王母不来方朔去，更须重见李夫人。","李商隐 汉宫"],["青牛到日迎方朔，丹灶开时共稚川。","沈传师 赠毛仙翁"]]},{"n":"方朔诙谐","d":"","s":"《汉书》卷六十五〈东方朔列传〉～2863～","w":"武帝既招英俊，程其器能，用之如不及。时方外事胡越，内兴制度，国家多事，自公孙弘以下至司马迁皆奉使方外，或为郡国守相至公卿，而朔尝至太中大夫，后常为郎，与枚皋、郭舍人俱在左右，诙啁而已。久之，朔上书陈农战彊国之计，因自讼独不得大官，欲求试用。…","q":[["子云窥未遍，方朔谐太枉。","杜甫 八哀诗故著作郎贬台州司户荥阳郑公虔"]]},{"n":"上书囊","d":"","s":"《汉书》卷六十五《东方朔传》","w":"「上从容问朔：『吾欲化民，岂有道乎？』朔对曰：『尧舜禹汤文武成康上古之事，经历数千载，尚难言也，臣不敢陈。愿近述孝文皇帝之时，当世耆老皆闻见之。贵为天子，富有四海，身衣弋绨，足履革舄，以韦带剑，莞蒲为席，兵木无刃，衣缊无文，集上书囊以为殿帷…","q":[["茅茨覆宫殿，封章绽帷帐。","杜牧 感怀诗一首"],["凶兵铸农器，讲殿辟书帷。","杜甫 夔府书怀四十韵"]]},{"n":"细君","d":"细君：指妻子。来苏轼《上元侍饮》：“归来一点残灯在，犹有传柑遗细君。”","s":"《汉书》卷六十五《东方朔传》","w":"久之，伏日，诏赐从官肉。大官丞日晏不来，朔独拔剑割肉，谓其同官曰：「伏日当蚤归，请受赐。」即怀肉去。大官奏之。朔入，上曰：「昨赐肉，不待诏，以剑割肉而去之，何也？」朔免冠谢。上曰：「先生起自责也。」朔再拜曰：「朔来！朔来！受赐不待诏，何无礼…","q":[["尚想东方朔，诙谐割肉归。","杜甫 社日两篇"],["曲罢卿卿理驺驭，细君相望意何如。","权德舆 朝回阅乐寄绝句"]]},{"n":"王母蟠桃","d":"","s":"《艺文类聚》卷八十六〈果部上·桃〉～468～","w":"汉武故事曰：东郡献短人，呼东方朔。朔至，短人因指朔谓上曰：西王母种桃，三千岁一为子。此儿不良也，已三过偷之矣。后西王母下，出桃七枚，母因啖二，以五枚与帝。帝留核著前，母问曰：「用此何？」上曰：「此桃美，欲种之。」母笑曰：「此桃三千年一著子，…","q":[["阿母蟠桃香未齐，汉皇骨葬秋山碧。","张碧 惜花三首"],["唯应问王母，桃作几时花。","沈佺期 幸白鹿观应制"]]},{"n":"曼倩风流","d":"","s":"《太平御览》卷一百八十八〈居处部十六·〉～039～2～","w":"《汉武故事》：「西王母降，东方朔于朱雀牖中窥母，母谓帝曰：『此儿无赖，久被斥逐，原心无恶，寻当得还。』」","q":[]},{"n":"冕旒黈纩","d":"","s":"《汉书》卷六十五《东方朔传》","w":"「水至清则无鱼，人至察则无徒，冕而前旒，所以蔽明；黈纩充耳，所以塞聪。」唐·颜师古注：「黈，黄色也。纩，绵也。以黄绵为丸，用组悬之于冕，垂两耳旁，示不外听。」","q":[["褰旒去耳纩，调和进梅盐。","韩愈 苦寒"]]},{"n":"溺殿衙","d":"","s":"《汉书》卷六十五《东方朔传》","w":"「朔尝醉入殿中，小遗殿上，劾不敬。有诏免为庶人，待诏宦者署，因此对复为中郎，赐帛百匹。」唐·颜师古注：「小遗者，小便也。」","q":[["诋欺刘天子，正昼溺殿衙。","韩愈 读东方朔杂事"]]},{"n":"秦冤","d":"","s":"《太平御览》卷六百四十三〈刑法部九·狱〉～302～","w":"旧题汉·郭宪《东方朔传》：「孝武皇帝时，幸甘泉，至长平阪上，驰道中央有虫复而赤如生肝状……土召朔使驰往视之。还对曰：『怪哉！」上曰：『何谓也？』朔对曰：『秦始皇时拘系无罪，幽杀无辜，众庶怨恨，无所告诉，仰天而叹曰：「怪哉！」感动皇天。此愤气…","q":[["自悯秦冤痛，谁怜楚奏哀。","骆宾王 幽系书情通简知己"],["汲冢宁详蠹，秦牢讵辨冤。","骆宾王 早秋出塞寄东台详正学士"]]},{"n":"三冬学","d":"三冬学：咏读书。唐罗隐《投浙东王大夫二十韵》；“自愧三冬学。来窥数仞墙。”","s":"《汉书》卷六十五〈东方朔列传〉～284～","w":"东方朔字曼倩，平原厌次人也。武帝初即位，徵天下举方正贤良文学材力之士，待以不次之位，四方士多上书言得失，自衒鬻者以千数，其不足采者辄报闻罢。朔初来，上书曰：「臣朔少失父母，长养兄嫂。年十三学书，三冬文史足用。十五学击剑。十六学诗书，诵二十二…","q":[["曼倩三冬，陈思七步。","李瀚 蒙求"],["古人已用三冬足，年少今开万卷馀。","杜甫 柏学士茅屋"]]},{"n":"岁星","d":"","s":"旧题汉·郭宪《东方朔传》","w":"「朔未死时，谓同舍郎曰：『天下人无能知朔，知朔者唯太王公耳。』朔卒后，武帝得此语，即召太王公问之曰：『尔知东方朔乎？』公对曰：『不知。』公何所能？曰：『颇善星历。』帝问诸星皆具在否，曰：『诸星具在，独不见岁星十八年，今复见耳。』帝仰天叹曰：…","q":[["岁星入汉年，方朔见明主。","李白 书怀赠南陵常赞府"],["谓我是方朔，人间落岁星。","李白 留别西河刘少府"]]},{"n":"相涂","d":"","s":"《汉书》卷六十五《东方朔传》","w":"「时有幸倡郭舍人，滑稽不穷，常侍左右，曰：『朔狂，幸中耳，非至数也。臣愿令朔复射，朔中之，臣榜百，不能中，臣赐帛。』乃覆树上寄生，令朔射之。朔曰：『是寠薮也。』舍人曰：『果知朔不能中也。』朔曰：『生肉为脍，乾肉为脯；著树为寄生，盆下为寠数。…","q":[["善幻迷冰火，齐谐笑柏涂。","柳宗元 同刘二十八院长述旧言怀感时书事奉寄澧州张员外使君五十二韵之作因其韵增至八十通赠二君子"]]},{"n":"以筳撞钟","d":"","s":"《汉书》卷六十五《东方朔传》","w":"今世之处士，魁然无徒，廓然独居，上观许由，下察接舆，计同范蠡，忠合子胥，天下和平，与义相扶，寡耦少徒，固其宜也，子何疑于我哉？若夫燕之用乐毅，秦之任李斯，郦食其之下齐，说行如流，曲从如环，所欲必得，功若丘山，海内定，国家安，是遇其时也，子又…","q":[["微诚慕横草，琐力摧撞筵。","韩愈 答张彻（愈为四门博士时作。张彻。愈门下士。又愈之从子婿。）"],["东野不回头，有如寸筳撞钜钟。","韩愈 醉留东野"]]},{"n":"侏儒饱","d":"侏儒饱：喻小人得志而贤才受屈。元朱旭《杂诗》之二：“长身素米侏儒饱，飞将无功妄尉侯。”；曼倩饥：咏人生活清贫。唐许浑《早秋三首》之二：“老信相如渴，贫忧曼倩饥。”","s":"《汉书》卷六十五〈东方朔列传〉","w":"「朔文辞不逊，高自称誉，上伟之，令待诏公车，奉禄薄，未得省见。久之，朔绐驺朱儒，曰：「上以若曹无益于县官，耕田力作固不及人，临众处官不能治民，从军击虏不任兵事，无益于国用，徒索衣食，今欲尽杀若曹。」朱儒大恐，啼泣。朔教曰：「上即过，叩头请罪…","q":[["奸声入耳佞入心，侏儒饱饭夷齐饿。","元稹 立部伎"],["只取侏儒饱，不怜方朔饿。","寒山 诗三百三首"]]}],"39":[{"n":"温泉浴罢","d":"","s":"《太平广记》卷四百八十六〈杂传记三·长恨传〉～3998～","w":"唐开元中，泰阶平，四海无事。玄宗在位岁久，倦于旰食宵衣，政无大小，始委于丞相。稍深居游宴，以声色自娱。先是，元献皇后武淑妃皆有宠，相次即世；宫中虽良家子千万数，无悦目者。上心忽忽不乐。时每岁十月，驾幸华清宫，内外命妇，焜耀景从，浴日馀波，赐…","q":[]},{"n":"梨花雨","d":"","s":"《全唐诗》卷四百三十五〈长恨歌〉","w":"汉皇重色思倾国，御宇多年求不得。杨家有女初长成，养在深闺人未识。天生丽质难自弃，一朝选在君王侧。回眸一笑百媚生，六宫粉黛无颜色。春寒赐浴华青池，温泉水滑洗凝脂。侍儿扶起娇无力，始是新承恩泽时。云鬓花颜金步摇【云鬓花冠金步摇】，芙蓉帐暖度春宵…","q":[]},{"n":"妃子将军瞋","d":"","s":"《新唐书》卷二百二〈文艺列传中·李白〉～5762～","w":"天宝初，南入会稽，与吴筠善，筠被召，故白亦至长安。往见贺知章，知章见其文，叹曰：「子，谪仙人也！」言于玄宗，召见金銮殿，论当世事，奏颂一篇。帝赐食，亲为调羹，有诏供奉翰林。白犹与饮徒醉于市。帝坐沈香子亭，意有所感，欲得白为乐章，召入，而白已…","q":[]},{"n":"海棠春睡","d":"","s":"《海录碎事》卷十〈后妃门〉","w":"《太真外传》：「上皇登沉香亭，诏太真妃子。妃子时卯醉未醒，命力士从侍儿扶掖而至。妃子醉颜残妆，鬓乱钗横，不能再拜。上皇笑曰：『岂是妃子醉，真海棠睡未足耳。』」","q":[]},{"n":"芙蓉面","d":"","s":"《西京杂记》卷二～076～","w":"司马相如，初与卓文君还成都。居贫愁懑，以所著鹔?裘，就市人阳昌贳酒，与文君为欢。既而文君抱颈而泣，曰：「我平生富足，今乃以衣裘贳酒。」遂相与谋于成都卖酒。相如亲著犊鼻裈涤器以耻王孙，王孙果以为病，乃厚给文君，文君遂为富人。文君姣好眉色如望远…","q":[["芙蓉如面柳如眉，对此如何不泪垂。","白居易 长恨歌"]]},{"n":"倚新妆","d":"","s":"《太平广记》卷二百四〈乐二·歌·李龟年〉～549～","w":"开元中，禁中初重木芍药，即今牡丹也。（开元《天宝花木记》云，禁中呼木芍药为牡丹）得四本，红、紫、浅红、通白者。上因移植于兴庆池东沉香亭前。会花方繁开，上乘照夜白，太真妃以步辇从。诏特选梨园弟子中尤者，得乐十六部。李龟年以歌擅一时之名，手捧檀…","q":[]},{"n":"贵妃醉脸","d":"","s":"《松窗杂录》","w":"太和、开成中，有程脩己者，以善画得进谒。脩己始以孝廉召入籍，故上不甚以画者流视之。会春暮，内殿赏牡丹花。上颇好诗，因问脩己曰：「今京邑传唱牡丹花诗，谁为首出？」脩己对曰：「臣尝闻公卿者多吟赏中书舍人李正封诗……上闻之，嗟赏移时，杨妃方恃恩宠…","q":[]},{"n":"荔枝无驿使","d":"","s":"《全唐诗》卷五百二十一〈过华清宫绝句三首〉","w":"〈过华清宫绝句三首〉其一：「长安回望绣成堆，山顶千门次第开。一骑红尘妃子笑，无人知是荔枝来【无人知道荔枝来】。」","q":[]},{"n":"太液池","d":"解语花：喻美人聪慧可人。清赵翼《题女史骆佩香秋灯课女图》：“一个娇娃解语花，崎窗亲课秋宵读。”","s":"《开元天宝遗事》卷下〈解语花〉","w":"明皇秋八月，太液池，有千叶白莲，数枝盛开。帝与贵戚宴赏，左右皆叹美久之。帝指贵妃示左右曰，争如我解语花。","q":[]},{"n":"环儿","d":"","s":"《杨太真外传》","w":"杨贵妃小字玉环，弘农华阴人也。……二十八年十月，玄宗幸温泉宫，使高力士取杨氏女于寿邸，度为女道士，号太真，住内太真宫。天宝四载七月，册左卫中郎将韦昭训女配寿邸。是月，于凤凰园册太真宫女道士杨氏为贵妃，半后服用。进见之日，奏《霓裳羽衣曲》。","q":[]},{"n":"哭香囊","d":"","s":"《新唐书》卷七十六〈后妃列传上·杨贵妃〉～3495～","w":"帝至自蜀，道过其所，使祭之，且诏改葬。礼部侍郎李揆曰：「龙武将士以国忠负上速乱，为天下杀之。今葬妃，恐反仄自疑。」帝乃止。密遣中使者具棺椁它葬焉。启瘗，故香囊犹在，中人以献，帝视之，悽感流涕，命工貌妃于别殿，朝夕往，必为鲠欷。","q":[]},{"n":"力士脱靴","d":"力士脱靴：指狂傲不羁、蔑视权贵。唐贯休《古意》：“一朝力士脱靴后，玉上青蝇生一个。”","s":"《新唐书》卷二百二〈文艺列传中·李白〉～5762～","w":"天宝初，南入会稽，与吴筠善，筠被召，故白亦至长安。往见贺知章，知章见其文，叹曰：「子，谪仙人也！」言于玄宗，召见金銮殿，论当世事，奏颂一篇。帝赐食，亲为调羹，有诏供奉翰林。白犹与饮徒醉于市。帝坐沈香子亭，意有所感，欲得白为乐章，召入，而白已…","q":[]},{"n":"马嵬坡","d":"","s":"《旧唐书》卷五十一〈后妃列传上·玄宗杨贵妃〉～280～","w":"天宝中，范阳节度使安禄山大立边功，上深宠之。禄山来朝，帝令贵妃姊妹与禄山结为兄弟。禄山母事贵妃，每宴赐，锡赉稠沓。及禄山叛，露檄数国忠之罪。河北盗起，玄宗以皇太子为天下兵马元帅，监抚军国事。国忠大惧，诸杨聚哭，贵妃衔土陈请，帝遂不行内禅。及…","q":[]},{"n":"谪仙人","d":"","s":"《全唐诗》卷一百八十二〈对酒忆贺监二首〉","w":"〈对酒忆贺监二首〉并序：「太子宾客贺公。于长安紫极宫一见余。呼余为谪仙人。因解金龟换酒为乐。殁后对酒。怅然有怀。而作是诗。」诗云：「狂客归四明，山阴道士迎。敕赐镜湖水，为君台沼荣。人亡馀故宅，空有荷花生。念此杳如梦，凄然伤我情。」","q":[]},{"n":"御手调羹","d":"","s":"《新唐书》卷二百二〈文艺列传中·李白〉～5762～","w":"天宝初，南入会稽，与吴筠善，筠被召，故白亦至长安。往见贺知章，知章见其文，叹曰：「子，谪仙人也！」言于玄宗，召见金銮殿，论当世事，奏颂一篇。帝赐食，亲为调羹，有诏供奉翰林。白犹与饮徒醉于市。帝坐沈香子亭，意有所感，欲得白为乐章，召入，而白已…","q":[]},{"n":"五花结队","d":"","s":"《旧唐书》卷五十一〈后妃列传上·玄宗杨贵妃〉～279～","w":"玄宗每年十月幸华清宫，国忠姊妹五家扈从，每家为一队，著一色衣，五家合队，照映如百花之焕发，而遗钿坠，瑟瑟珠翠，璨芳馥于路。","q":[]},{"n":"舞破霓裳","d":"","s":"《全唐诗》卷五百二十一〈过华清宫绝句三首〉","w":"〈过华清宫绝句三首〉其二：「新丰绿树起黄埃，数骑渔阳探使回【案：帝使中使辅璆琳探禄山反否。璆琳受禄山金。言禄山不反。】。霓裳一曲千峰上，舞破中原始下来。」","q":[]},{"n":"杨妃捧砚","d":"","s":"《摭遗》","w":"李白失意游华山，过县，宰方开门决事，白乘醉跨驴过门，宰怒，不知太白也。引至庭下曰：「汝何人？辄敢无礼！」白乞供状，状无姓名，曰：「曾龙巾拭吐，御手调羹，贵妃授砚，力士抹靴，天子门前尚容走马，华阳县里，不得我骑驴？」宰惊起，揖曰：「不知翰林至…","q":[]},{"n":"杨妃袜","d":"","s":"《记事珠》","w":"杨贵妃死之日，马嵬妪得锦幼袜一只，遇过客一玩百钱，前后获钱无数。","q":[]},{"n":"杨家花","d":"","s":"《青琐高议》前集卷六〈骊山记〉","w":"帝又好花木，诏近郡送花赴骊宫。当时有献牡丹者，谓之「杨家红」，乃卫尉卿杨勉家花也。其花微红，甚爱之，命高力士将花上贵妃。贵妃方对妆，妃用手拈花，时匀面手脂在上，遂印于花上。帝见之，问其故，妃以状对。诏其花栽于先春馆。来岁花开，花上复有指红迹…","q":[]},{"n":"夜霖铃","d":"","s":"《杨太真外传》卷下","w":"上发马嵬……又至斜谷口，属霖雨涉旬，于栈道雨中闻铃声，隔山相应。上既悼念贵妃，因采其声为〈雨霖铃曲〉，以寄恨焉。","q":[]}],"40":[{"n":"北海樽","d":"北海樽：咏饮宴。宋陆游《石帆山下》：“尚嫌名挂东林社，那问尘生北海樽。”","s":"《艺文类聚》卷二十六〈人部十·言志〉～465～","w":"《张璠汉纪》曰：孔融拜太中大夫，虽居家失势，宾客日满其门，爱才乐士。常若不足，每叹曰：「坐上宾常满，樽中酒不空，吾无忧矣。」","q":[["油幕侣昆丘，粲然叠瑶琼。庾楼见清月，孔坐多绿醽。","刘禹锡 送李策秀才还湖南因寄幕中亲故兼简衡州吕八郎中"],["扇举遮王导，樽开见孔融。","李商隐 今月二日不自量度辄以诗一首四十韵干渎尊严伏蒙仁恩俯赐披览奖逾其实情溢于辞顾惟疏芜曷用酬戴复五言四十韵诗献上亦诗人咏叹不足之义也"]]},{"n":"小儿杨德祖","d":"","s":"《后汉书》卷八十下〈文苑列传下·祢衡〉～2652～","w":"祢衡字正平，平原般人也。少有才辩，而尚气刚傲，好矫时慢物。兴平中，避难荆州。建安初，来游许下。始达颍川，乃阴怀一刺，既而无所之适，至于刺字漫灭。是时许都新建，贤士大夫四方来集。或问衡曰：「盍从陈长文、司马伯达乎？」对曰：「吾焉能从屠沽儿耶！…","q":[["十五事文翰，大儿轻孔融。","李端 长安感事呈卢纶"]]},{"n":"渔阳掺","d":"祢生刺：咏怀才不遇。唐司空曙《送卢堪》：“莫使称生刺，空留怀袖中。”；祢衡挝：用以咏鼓乐，或指相骂，或指文人狂放不羁。唐李商隐《病中闻河东公乐营置酒口占寄上》：“必投潘岳果，谁掺祢衡挝。”","s":"《世说新语笺疏》上卷上〈言语〉～64～","w":"祢衡被魏武谪为鼓吏，正月半试鼓。南朝梁·刘孝标注引引《文士传》曰：「融数与武帝笺，称其才，帝倾心欲见。衡称疾不肯往，而数有言论。帝甚忿之，以其才名不杀，图欲辱之，乃令录为鼓吏。后至八月朝会，大阅试鼓节，作三重阁，列坐宾客。以帛绢制衣，作一岑…","q":[["莫使祢生刺，空留怀袖中。","司空曙 送卢堪"],["祢生投刺游，王粲吟诗谒。","孟郊 答韩愈李观别因献张徐州"]]},{"n":"人中奇","d":"","s":"《世说新语笺疏》上卷上〈言语〉～56～","w":"孔文举年十岁，随父到洛。时李元礼有盛名，为司隶校尉，诣门者皆俊才清称及中表亲戚乃通。文举至门，谓吏曰：「我是李府君亲。」既通，前坐。元礼问曰：「君与仆有何亲？」对曰：「昔先君仲尼与君先人伯阳，有师资之尊，是仆与君奕世为通好也。」元礼及宾客莫…","q":[]},{"n":"德祖家珍","d":"","s":"《世说新语笺疏》上卷上〈言语〉～05～","w":"梁国杨氏子，九岁，甚聪惠。孔君平诣其父，父不在，乃呼儿出，为设果。果有杨梅，孔指以示儿曰：「此是君家果。」儿应声答曰：「未闻孔雀是夫子家禽。」余嘉锡笺疏引李慈铭云：「案《金楼子·捷对篇》作杨子州答孔永语。《太平广记·诙谐门》引《启颜录》作晋…","q":[]},{"n":"迭宕孔文举","d":"","s":"《后汉书》卷七十〈孔融列传〉～2272～","w":"时年饥兵兴，操表制酒禁，融频书争之，多侮慢之辞。既见操雄诈渐著，数不能堪，故发辞偏宕，多致乖忤。……曹操既积嫌忌，而郗虑复搆成其罪，遂令丞相军谋祭酒路粹枉状奏融曰：「……又融为九列，不遵朝仪，秃巾微行，唐突宫掖。又前与白衣祢衡跌荡于言，云『…","q":[["迭宕孔文举，风流石季伦。","储光羲 秋夜贻马九"]]},{"n":"拂衣","d":"","s":"《后汉书》卷五十四〈杨震列传·（曾孙）杨彪〉～788～","w":"建安元年，从东都许。时天子新迁，大会公卿，兖州刺史曹操上殿，见彪色不悦，恐于此图之，未得宴设，托疾如厕，因出还营。彪以疾罢。时袁术僭乱，操托彪与术婚姻，诬以欲图废置，奏收下狱，劾以大逆。将作大匠孔融闻之，不及朝服，往见操曰：「杨公四世清德，…","q":[["肯学求名者，经年未拂衣。","李端 送丘丹归江东"],["吏情更觉沧洲远，老大悲伤未拂衣。","杜甫 曲江对酒"]]},{"n":"覆巢破卵","d":"","s":"《世说新语》上卷上《言语》","w":"「孔融被收，中外惶怖。时融儿大者九岁，小者八岁。二儿故琢钉戏，了无遽容。融谓使者曰：『冀罪止于身，二儿可得全不？』儿徐进曰：『大人岂见覆巢之下，复有完卵乎？』寻亦收至。」南朝梁·刘孝标注引《魏氏春秋》曰：「融对孙权使有讪谤之言，坐弃市。二子…","q":[["覆巢破卵方堪惧，取次梧桐凤且栖。","李咸用 寄题从兄坤载村居"]]},{"n":"河尹与孔融","d":"","s":"《后汉书》卷七十〈孔融列传〉～226～","w":"融幼有异才。年十岁，随父诣京师。时河南尹李膺以简重自居，不妄接士宾客，敕外自非当世名人及与通家，皆不得白。融欲观其人，故造膺门。语门者曰：「我是李君通家子弟。」门者言之。膺请融，问曰：「高明祖父尝与仆有恩旧乎？」融曰：「然。先君孔子与君先人…","q":[["有客传河尹，逢人问孔融。","杜甫 奉寄河南韦尹丈人"]]},{"n":"建安诸子","d":"","s":"《昭明文选》卷五十二〈论二·典论论文〉～2270～","w":"今之文人，鲁国孔融文举，广陵陈琳孔璋，山阳王粲仲宣，北海徐干伟长，陈留阮瑀元瑜，汝南应玚德琏，东平刘桢公干：斯七子者，于学无所遗，于辞无所假，咸以自骋骥騄于千里，仰齐足而并驰。以此相服，亦良难矣。盖君子审己以度人，故能免于斯累，而作论文。","q":[]},{"n":"九牧争羡","d":"","s":"《昭明文选》卷四十一〈书上·论盛孝章书〉～873～","w":"岁月不居，时节如流。五十之年，忽焉已至，公为始满，融又过二。海内知识，零落殆尽，惟有会稽盛孝章尚存。其人困于孙氏，妻孥湮没，单孑独立，孤危愁苦。若使忧能伤人，此子不得永年矣！春秋传曰：「诸侯有相灭亡者，桓公不能救，则桓公耻之。」今孝章实丈夫…","q":[]},{"n":"绝足","d":"","s":"《昭明文选》卷四十一〈书上·论盛孝章书〉～874～","w":"燕君市骏马之骨，非欲以骋道里，乃当以招绝足也。","q":[["风云随绝足，日月继高衢。","杜甫 行次昭陵"]]},{"n":"孔北海","d":"","s":"《后汉书》卷七十〈孔融列传〉～2263～","w":"后辟司空掾，拜中军候。在职三日，迁虎贲中郎将。会董卓废立，融每因对荅，辄有匡正之言。以忤卓旨，转为议郎。时黄巾寇数州，而北海最为贼冲，卓乃讽三府同举融为北海相。","q":[["多惭孔北海，传教及衡门。","李德裕 余所居平泉村舍近蒙韦常侍大尹特改嘉名因寄诗以谢"],["殷勤孔北海，时节易流移。","武元衡 送兄归洛使谒严司空"]]},{"n":"孔李通家","d":"","s":"《后汉书》卷七十〈孔融列传〉～226～","w":"融幼有异才。年十岁，随父诣京师。时河南尹李膺以简重自居，不妄接士宾客，敕外自非当世名人及与通家，皆不得白。融欲观其人，故造膺门。语门者曰：「我是李君通家子弟。」门者言之。膺请融，问曰：「高明祖父尝与仆有恩旧乎？」融曰：「然。先君孔子与君先人…","q":[["不是通家旧，频劳文举过。","李端 赠神童"],["通家殊孔李，旧好即潘杨。","柳宗元 弘农公以硕德伟才屈于诬枉左官三岁复为大僚天监昭明人心感悦宗元窜伏湘浦拜贺末由谨献五十韵以毕微志"]]},{"n":"孔融过五十","d":"","s":"《昭明文选》卷四十一〈书上·论盛孝章书〉～873～","w":"岁月不居，时节如流。五十之年，忽焉已至，公为始满，融又过二。海内知识，零落殆尽，惟有会稽盛孝章尚存。其人困于孙氏，妻孥湮没，单孑独立，孤危愁苦。若使忧能伤人，此子不得永年矣！","q":[["仲山方补衮，文举自伤年。","武元衡 奉酬中书相公至日圜丘行事合于中书宿斋移止于集贤院叙情见寄之什"],["莫怪孔融悲岁序，五侯门馆重娄卿。","武元衡 酬谈校书长安秋夜对月寄诸故旧"]]},{"n":"膺门得孔融","d":"","s":"《后汉书》卷七十《孔融传》","w":"敕外自非当世名人及与通家，皆不得白。融欲观其人，故造膺门。语门者曰：「我是李君通家子弟。」门者言之。膺请融，问曰：「高明祖父尝与仆有恩旧乎？」融曰：「然。先君孔子与君先人李老君（聃）同德比义，而相师友，则融与君累世通家。」","q":[["阁上掩书刘向去，门前修刺孔融来。","刘禹锡 同乐天送河南冯尹学士"],["定知洛下声名士，共说膺门得孔融。","许浑 送张厚浙东谒丁常侍（一作送张厚浙东修谒）"]]},{"n":"让果","d":"","s":"《后汉书》卷七十《孔融传》","w":"「融幼有异才。」唐·李贤注：「《融家传》曰：『兄弟七人，融第六，幼有自然之性。年四岁时，每与诸兄共食梨，融辄引小者。大人问其故，荅曰：『我小儿，法当取小者。』由是宗族奇之。』」别见晋·张隐《文士传》","q":[["兄弟相欢初让果，乡人争贺旧登龙。","钱起 送冷朝阳擢第后归金陵觐省"]]},{"n":"推文举","d":"","s":"《世说新语》上卷上《言语》","w":"「孔文举年十岁，随父到洛。时李元礼有盛名，为司隶校尉，诣门者皆峻才清称及中表亲戚乃通。文举至门，谓吏曰：『我是李府君亲。』既通，前坐。元礼问曰：『君与仆有何亲？』对曰：『昔先君仲尼与君先人伯阳，有师资之尊，是仆与君奕世为通好也。』元礼及宾客…","q":[["今日龙门下，谁知文举才。","孟浩然 姚开府山池"],["四座推文举，中郎许仲宣。","孟浩然 送张参明经举兼向泾州觐省"]]},{"n":"忘年友","d":"","s":"《后汉书》卷八十下〈文苑列传下·祢衡〉～2653～","w":"衡始弱冠，而融年四十，遂与为交友。","q":[]},{"n":"无胫致远","d":"","s":"《三国志》卷五十一〈吴书·孙韶传〉～24～","w":"初，孙权杀吴郡太守盛宪。南朝宋·裴松之注引《会稽典录》：「初，宪与少府孔融善，融忧其不免祸，乃与曹公书曰：『岁月不居，时节如流，五十之年，忽焉已至。公为始满，融又过二，海内知识，零落殆尽，惟会稽盛孝章尚存。其人困于孙氏，妻孥湮没，单孑独立，…","q":[["致远终无胫，怀贪遂息肩。","独孤绶 投珠于泉"]]},{"n":"鹗表","d":"鹗荐：指荐贤。宋苏轼《次韵王定国谢韩子华过饮》：“亲嫌妨鹗荐，相对发微泚。”","s":"《后汉书》卷八十下〈文苑列传下·祢衡〉","w":"唯善鲁国孔融及弘农杨脩。常称曰：「大儿孔文举，小儿杨德祖。馀子碌碌，莫足数也。」融亦深爱其才。衡始弱冠，而融年四十，遂与为交友。上疏荐之曰：「臣闻洪水横流，帝思俾乂，旁求四方，以招贤俊。昔孝武继统，将弘祖业，畴咨熙载，群士响臻。陛下睿圣，纂…","q":[["慈明八龙，祢衡一鹗。","李瀚 蒙求"],["修持清苦振佳声，众鸟那知一鹗情。","方干 寄于少监"]]}],"41":[{"n":"八采眉","d":"","s":"《春秋元命苞》","w":"尧眉八采，是谓通明，历象日月，璇玉作衡。（据《艺文类聚》卷十一引）","q":[["若非八彩眉，不可辄照临。","贯休 古镜词上刘侍郎"]]},{"n":"箕山颍水","d":"洗耳：指隐士清高脱俗。唐李白《送裴十八图南归嵩山》之二“归时莫洗耳，为我洗其心。”","s":"《庄子集释》卷一上〈内篇·逍遥游〉～22～","w":"尧让天下于许由，曰：「日月出矣，而爝火不息，其于光也，不亦难乎！时雨降矣，而犹浸灌，其于泽也，不亦劳乎！夫子立而天下治，而我犹尸之，吾自视缺然，请致天下。」许由曰：「子治天下，天下既已治也。而我犹代子，吾将为名乎？名者，实之宾也。吾将为宾乎…","q":[["箕山有高节，湘水有清源。","陈子昂 感遇诗三十八首之三十一"],["心到物自闲，何劳远箕颍。","元稹 表夏十首之二"]]},{"n":"崇山谪","d":"","s":"《尚书·虞书·舜典》","w":"放驩兜于崇山。","q":[["贞魂误向崇山没，冤气疑从湘水回。","杜牧 闻开江湘国宋下世二首之一"],["怜君更抱重泉恨，不见崇山谪去时。","杜牧 见宋拾遗题名处感而成诗"]]},{"n":"击壤歌","d":"击壤歌：称颂帝王治国有方。南朝陈张正见《从籍田应衡阳王教作五章》之五：“幸承滥吹末，击壤自为歌。”","s":"《论衡校释》卷八〈艺增〉～388～","w":"论语曰：「大哉！尧之为君也，荡荡乎民无能名焉。」传曰：「有年五十击壤于路者，观者曰：『大哉！尧之德乎！』击壤者曰：『吾日出而作，日入而息，凿井而饮，耕田而食，尧何等力？』」此言荡荡无能名之效也。","q":[["击壤将何幸，裴回望九门。","崔枢 赐耆老布帛（一作张复元诗）"],["野洽如坻咏，途喧击壤讴。","李峤 晚秋喜雨"]]},{"n":"帝尧文思","d":"","s":"《尚书》卷二〈虞书·尧典〉～8～","w":"昔在帝尧，聪明文思，光宅天下，将逊于位，让于虞舜。","q":[["羽翼怀商老，文思忆帝尧。","杜甫 收京三首"]]},{"n":"祝尧","d":"","s":"《庄子集释》卷五上〈外篇·天地〉～420～","w":"尧观乎华，华封人曰：「嘻，圣人！请祝圣人。」「使圣人寿。」尧曰：「辞。」「使圣人富。」尧曰：「辞。」「使圣人多男子。」尧曰：「辞。」封人曰：「寿，富，多男子，人之所欲也。女独不欲，何邪？」尧曰：「多男子则多惧，富则多事，寿则多辱。是三者，非…","q":[]},{"n":"谷林","d":"","s":"《史记》卷一《五帝本纪·尧本纪》","w":"「尧辟位凡二十八年而崩。」南朝宋·裴骃《史记集解》引《皇览》曰：「尧冢在济阴城阳。……《吕氏春秋》曰：『尧葬谷林』。引皇甫谧曰：「谷林即城阳。」","q":[["曙月思兰室，前山辨谷林。","权德舆 奉使丰陵职司卤薄通宵涉路因寄内"],["今日谷林归，灵辒烟雨霏。","权德舆 德宗神武孝文皇帝挽歌词三首之三"]]},{"n":"康衢颂","d":"","s":"《列子》卷四《仲尼》","w":"尧治天下五十年，不知天下治欤，不治欤？不知亿兆之愿戴己欤？不愿戴己欤？顾问左右，左右不知。问外朝，外朝不知。问在野，在野不知。尧乃微服游于康衢，闻儿童谣曰：「立我蒸民，莫匪尔极。不识不知，顺帝之则。」尧喜问曰：「谁教尔为此言？」童儿曰：「我…","q":[["未知康衢咏，所仰惟年丰。","李适 重阳日即事"],["永言念成功，颂德临康衢。","李隆基 过晋阳宫"]]},{"n":"尧蓂","d":"","s":"今本《竹书纪年·帝尧陶唐氏》","w":"「又有草夹阶而生，月朔始生一荚，月半而生十五荚，十六日以后，日落一荚，及晦而尽，月小则一荚焦而不落，名曰『蓂荚』，一曰『历荚』。」","q":[["大官陈禹玉，司历献尧蓂。","司空曙 和耿拾遗元日观早朝"],["节晦蓂全落，春迟柳暗催。","宋之问 奉和晦日幸昆明池应制"]]},{"n":"清洛荐尧书","d":"","s":"《艺文类聚》卷九十九","w":"《尚书中侯》：尧沉璧于雒。玄龟负书出。背甲赤文成字。","q":[["他时清洛汭，会荐帝尧书。","李群玉 龟"]]},{"n":"善卷","d":"","s":"《庄子》杂篇·卷九下《让王》","w":"舜以天下让善卷，善卷曰：「余立于宇宙之中，冬日衣皮毛，夏日衣葛絺；春耕种，形足以劳动；秋收敛，身足以休食；日出而作，日入而息，逍遥于天地之间而心意自得。吾何以天下为哉！悲夫，子之不知余也！」遂不受。于是去而入深山，莫知其处。","q":[["善卷让天子，务光亦逃名。","李白 雉子斑"],["善卷明时隐，黔娄在日贫。","王维 过沈居士山居哭之"]]},{"n":"上尧下由","d":"","s":"《史记》卷六十一〈伯夷列传〉～22～","w":"而说者曰尧让天下于许由，许由不受，耻之逃隐。","q":[["上有尧兮下有田，眠松阳兮漱颍流。","张楚金 逸人歌赠李山人"]]},{"n":"陶唐","d":"","s":"《尚书》卷七〈夏书·五子之歌〉～0～","w":"其三曰：惟彼陶唐，有此冀方。今失厥道，乱其纪纲，乃厎灭亡。旧题汉·孔安国传：「陶唐，帝尧氏，都冀州，统天下四方。」","q":[["逢人借问陶唐主，欲进冰蚕五色丝。","徐凝 员峤先生"],["一棹寒波思范蠡，满尊醇酒忆陶唐。","李咸用 和人湘中作"]]},{"n":"陶唐符命","d":"","s":"《艺文类聚》卷十一〈帝王部一·帝尧陶唐氏〉～23～","w":"《尚书中侯》：帝尧即位，荣光出河，休气四塞，龙马衔甲，赤文绿色，甲似龟背，五色，有列星之分、斗政之度、帝王录记、兴亡之数。","q":[["符命自陶唐，吾君应会昌。","段成式 河出荣光"]]},{"n":"望云","d":"","s":"《史记》卷一《五帝本纪·尧本纪》","w":"「帝尧者，放勋。其仁如天，其知如神。就之如日，望之如云。」唐·司马贞《史记索隐》：「如云之覆渥，言德化广大而浸润生人，人咸仰望之，故曰如百谷之仰膏雨也。」","q":[["望云思圣主，披雾隐群贤。","王维 游悟真寺"]]},{"n":"尧阶","d":"","s":"《太平御览》卷九九六","w":"旧题周·尹文《尹文子》：尧文天子，衣不重帛，食不兼味。土阶三尺，茅茨不剪。（据《太平御览》卷九九六引）","q":[["园绮生虽逢汉室，巢由死不谒尧阶。","徐夤 闻司空侍郎讣音"],["尧帝成茨罢，殷汤祭雨旋。","李峤 茅"]]},{"n":"尧寿","d":"","s":"《史记》卷一《五帝本纪·尧本纪》","w":"「帝尧者，放勋。」南朝宋·裴骃《史记集解》：「尧以甲申岁生，甲辰即帝位，甲午徵舜，甲寅舜代行天子事，辛巳崩，年百一十八，在位九十八年。」唐·张守节《史记正义》「孔安国云：『尧寿百一十六?。』」","q":[["丛觞祝尧寿，合鼎献汤厨。","张说 奉和圣制爰因巡省途次旧居应制"]]},{"n":"尧与蹠","d":"","s":"《孟子》卷六《滕文公下》","w":"仲子所居之室，伯夷之所筑与？抑亦盗蹠之所筑与？","q":[["世无洗耳翁，谁知尧与蹠。","李白 古风之二十四"]]},{"n":"颍客","d":"","s":"《高士传》卷上《许由》","w":"尧让天下于许由……由于是遁耕于中岳，颍水之阳，箕山之下，终身无经天下色。尧又召为九州长，由不欲闻之，洗耳于颍水滨。时其友巢父牵犊欲饮之，见由洗耳，问其故。对曰：「尧欲召我为九州长，恶闻其声，是故洗耳。」巢父曰：「子若处高岸深谷，人道不通，谁…","q":[["周王尊渭叟，颍客傲唐尧。","理莹 送戴三徵君还谷口旧居"],["草遍颍阳山，花开武陵水。","皇甫冉 春早"]]},{"n":"羽窟幽黄能","d":"","s":"《春秋左传·昭公七年》","w":"「昔尧殛鲧于羽山，其神化为黄熊，以入羽渊。」","q":[["近者三奸悉破碎，羽窟无底幽黄能。","韩愈 忆昨行和张十一"]]},{"n":"岳牧","d":"","s":"《尚书·周书·周官》","w":"「唐虞稽古，建官惟百，内有百揆四岳，外有州牧侯伯。」旧题汉·孔安国传：「外置州牧十二，及五国之长。」唐·孔颖达疏：「四岳，内典四时之政，外主太岳之事，立四人也。外有州牧侯伯，牧，一州之长，侯伯，五国之长，各监其所部之国。」","q":[["幽燕通使者，岳牧用词人。","杜甫 送陵州路使君赴任"]]}],"42":[{"n":"鼎湖龙去","d":"乌号：指良弓。晋阮籍《咏贫》之十二：“良弓挟乌号，明甲有精光。”；乘龙：指仙去或帝王权臣去世，或指接近帝王、权臣。三国曹植《仙人篇》：“不见轩辕氏，乘龙出鼎湖。”","s":"《史记》卷二十八〈封禅书〉～394～","w":"黄帝采首山铜，铸鼎于荆山下。鼎既成，有龙垂胡髯下迎黄帝。黄帝上骑，群臣后宫从上者七十馀人，龙乃上去。馀小臣不得上，乃悉持龙髯，龙髯拔，堕，堕黄帝之弓。百姓仰望黄帝既上天，乃抱其弓与胡髯号，故后世因名其处曰鼎湖，其弓曰乌号。","q":[["功成弃之去，乘龙上天游。","刘复 游仙"],["上界鼎成云缥缈，西陵舞罢泪阑干。","刘沧 秋日过昭陵"]]},{"n":"洞庭张乐","d":"","s":"《庄子集释》卷五下〈外篇·天运〉～50～","w":"北门成问于黄帝曰：「帝张咸池之乐于洞庭之野，吾始闻之惧，复闻之怠，卒闻之而惑；荡荡默默，乃不自得。」","q":[["犹疑帝轩辕，张乐就空旷。","韩愈 岳阳楼别窦司直"]]},{"n":"游童","d":"","s":"《庄子》杂篇·卷八中《徐无鬼》","w":"黄帝将见大隗乎具茨之山，方明为御，昌骖乘，张若謵朋前马，昆阍滑稽后车；至于襄城之野，七圣皆迷，无所问涂。适遇牧马童子，问涂焉，曰：「若知具茨之山乎？」曰：「然。」「若知大隗之所存乎？」曰：「然。」 黄帝曰：「异哉小童！非徒知具茨之山，又知…","q":[["七圣心迷运方厄，五丁力尽路犹窄。","元稹 望云骓马歌"],["路疑随大隗，心似问鸿蒙。","张说 九日进茱萸山诗五首之三"]]},{"n":"凤巢","d":"","s":"晋·皇甫谧《帝王世纪》","w":"黄帝服齐于中宫，坐于玄扈洛上，乃有大鸟，……其状如鹤，体备五色，三文成字，首文曰：顺德。背文曰：信义。膺文曰：仁智。不食生虫，不履生草，或止帝之东园，或巢阿阁。其饮食也，必自歌舞，音如箫笙。","q":[["万里相逢欢复泣，凤巢西隔九重门。","李商隐 赠刘司户"]]},{"n":"弓剑","d":"","s":"北魏·郦道元《水经注》卷三《河水篇》","w":"水出西南长城北，阳周县故城南桥山。昔二世赐蒙恬死于此。王莽更名上陵畤，山上有黄帝冢故也。帝崩，惟弓剑存焉，故世称黄帝仙矣。","q":[["旋见衣冠就东市，忽遗弓剑不西巡。","杜牧 河湟"],["先帝弓剑远，小臣馀此生。","杜甫 送覃二判官"]]},{"n":"画万国","d":"","s":"《汉书》卷二十八上《地理志上》","w":"昔在黄帝，作舟车以济不通，旁行天下，方制万里，画野分州，得百里之国万区。是故易称「先王建万国，亲诸侯」，书云「协和万国」，此之谓也。尧遭洪水，怀山襄陵，天下分绝，为十二州，使禹治之。水土既平，更制九州，列五服，任土作贡。","q":[["中画一万国，角角棋布方。","杜牧 郡斋独酌"]]},{"n":"黄帝四目","d":"","s":"《太平御览》卷七十九","w":"晋·黄甫谧《帝王世纪》：力牧、常先、大鸿、神农，皇直封钜人，镇大山、稽鬼、臾区、封胡、孔甲等，或以为师，或以为将，分掌四方，各如巳视，故号曰黄帝四目","q":[["念此明者，为天之眼睛黄帝有四目，帝舜重其明。今天只两目，何故许食使偏盲。","韩愈 月蚀诗效玉川子作"]]},{"n":"黄帝战蚩尤","d":"","s":"《山海经·大荒北经》","w":"蚩尤作兵伐黄帝，黄帝乃令应龙攻之冀州之野。应龙蓄水，蚩尤请风伯、雨师从，大风雨。黄帝乃下天女曰魃，雨止，遂杀蚩尤。魃不得复上，所居不雨。","q":[["云缠风束乱敲磕，黄帝未胜蚩尤强。","杜牧 大雨行"]]},{"n":"黄老","d":"","s":"《史记》卷六十三《老子列传》附《申不害传》","w":"申子之学本于黄老而主刑名。著书二篇，号曰《申子》。","q":[["世业事黄老，妙年孤隐沦。","宋之问 始安秋日"]]},{"n":"缙云仙子","d":"","s":"《太平御览》卷十二","w":"《郡国志》曰：括州括苍县缙云山，黄帝游仙之处。","q":[["汗漫东游黄鹤雏，缙云仙子住清都。","李群玉 谪仙吟赠赵道士"]]},{"n":"力牧","d":"","s":"《史记》卷一〈五帝本纪·黄帝〉～6～","w":"举风后、力牧、常先、大鸿以治民。南朝宋·裴骃《史记集解》：「班固曰：『力牧，黄帝相也。』」唐·张守节《史记正义》：「晋·皇甫谧《帝王世纪》云：『黄帝梦大风吹天下之尘垢皆去， 又梦人执千钧之弩，驱羊万群。帝寤而叹曰：「风为号令，执政者也。垢去…","q":[["曾无力牧御，宁待雨师迎。","李商隐 送千牛李将军赴阙五十韵"]]},{"n":"伶伦吹","d":"伶伦吹：咏音乐、音律。唐李商隐《钧天》：“伶伦吹裂孤生竹，却为知音不得听。”；伶伦采：咏竹。唐李贺《苦篁调啸引》：“伶伦采之自昆丘，轩辕诏遣中分作十二。”","s":"《吕氏春秋·纪部》卷五〈仲夏纪·古乐〉～284～","w":"昔黄帝令伶伦作为律。伶伦自大夏之西，乃之阮隃之阴，取竹于嶰溪之谷，以生空窍厚钧者、断两节间、其长三寸九分而吹之，以为黄钟之宫，吹曰『舍少』。次制十二筒，以之阮隃之下，听凤皇之鸣，以别十二律。其雄鸣为六，雌鸣亦六，以比黄钟之宫，适合。黄钟之宫…","q":[["未遭伶伦听，非安子猷宠。","元稹 寺院新竹"],["伶伦吹裂孤生竹，却为知音不得听。","李商隐 钧天"]]},{"n":"顺风","d":"","s":"《庄子集释》卷四下〈外篇·在宥〉～38～","w":"广成子南首而卧，黄帝顺下风膝行而进，再拜稽首而问曰：「闻吾子达于至道，敢问，治身柰何而可以长久？」","q":[["万乘驻山外，顺风祈一言。","王维 同卢拾遗过韦给事东山别业二十韵给事首春休沐维已陪游及乎是行亦预闻命会无车马不果斯诺"]]},{"n":"天老","d":"","s":"《古本竹书纪年辑證》卷上〈黄帝轩辕氏〉～90～","w":"庚申，天雾三日三夜，昼昏。帝问天老、力牧、容成曰：「于公何如？」天老曰：「臣闻之，国安，其主好文，则凤凰居之。国乱，其主好武，则凤凰去之。今凤凰翔于东郊而乐之，其鸣音中夷则，与天相副。以是观之，天有严教以赐帝，帝勿犯也。」召史卜之，龟燋。史…","q":[["期之比天老，真德辅帝鸿。","储光羲 刘先生闲居"],["明君越羲轩，天老坐三台。","李白 金陵凤凰台置酒"]]},{"n":"梧庭凤","d":"","s":"汉·韩婴《韩诗外传》卷八第八章","w":"黄帝即位，施惠承天，一道修德，惟仁是行，宇内和平，未见凤凰，惟思其象，夙寐晨兴，乃召天老而问之，曰：「凤象何如？」天老对曰：「夫凤象、鸿前麟后，蛇颈而鱼尾，龙文而龟身，燕颔而鸡啄；戴德负仁，抱中挟义；小音金，大音鼓；延颈奋翼，五彩备明；举动…","q":[["壁有真龙画，庭馀鸣凤梧。","张说 奉和圣制爰因省途次旧居应制"],["林引梧庭凤，泉归竹沼龙。","李峤 夏晚九成宫呈同僚"]]},{"n":"咸池音","d":"","s":"《礼记注疏》卷三十八〈乐记〉～677～","w":"大章章之也，咸池备矣。东汉·郑玄注：「黄帝所作乐名也，尧增修而用之。咸，皆也。池之言施也，言德之无不施也。」","q":[["作诗三百首，窅默咸池音。","韩愈 孟生诗"]]},{"n":"轩羲","d":"","s":"《玉台新咏》卷一东汉·张衡《同声歌》","w":"众夫所希见，天老教轩皇。","q":[["轩皇竟磨灭，周孔亦衰老。","孟云卿 放歌行"],["挺质本轩皇，申威振远方。","李峤 弩"]]},{"n":"轩辕作","d":"","s":"旧题隋·王度《古镜记》","w":"侯生常云：「昔者吾闻黄帝铸十五镜，其第一横径一尺五寸，法满月之数也，以其相差。」","q":[["得非轩辕作，妙绝世莫并。","李群玉 古镜"]]},{"n":"轩辕古镜","d":"","s":"《太平广记》卷二百三十〈器玩二·王度〉～76～","w":"侯生常云：「昔者吾闻黄帝铸十五镜。其第一横径一尺五寸，法满月之数也。以其相差，各校一寸。此第八镜也。」","q":[]},{"n":"涿鹿","d":"","s":"《史记》卷一《五帝本纪·黄帝本纪》","w":"轩辕之时，神农氏世衰。诸侯相侵伐，暴虐百姓，而神农氏弗能征。于是轩辕乃习用干戈，以征不享，诸侯咸来宾从。而蚩尤最为暴，莫能伐。炎帝欲侵陵诸侯，诸侯咸归轩辕。轩辕乃修德振兵，治五气，蓺五种，抚万民，度四方，教熊罴貔貅䝙虎，以与炎帝战于阪泉之野…","q":[["熊罴驱涿鹿，犀象走昆阳。","韦庄 和郑拾遗秋日感事一百韵"]]}],"43":[{"n":"髀肉生","d":"髀肉：喻因生活安逸而无所作为。唐白居剔题裴晋公女儿山刻石诗后》：“战袍破犹在，髀肉生欲圆。”","s":"《三国志》卷三十二〈蜀书·先主备传〉～876～","w":"曹公既破绍，自南击先主。先主遣麋竺、孙乾与刘表相闻，表自郊迎，以上宾礼待之，益其兵，使屯新野。荆州豪杰归先主者日益多，表疑其心，阴御之。南朝宋·裴松之注引《九州春秋》曰：「备住荆州数年，尝于表坐起至厕，见髀里肉生，慨然流涕。还坐，表怪问备，…","q":[["上山嫌䯗重，拔剑叹衣生。","姚合 赠卢大夫将军"],["自言无战伐，髀肉已曾生。","张祜 观宋州田大夫打毬"]]},{"n":"百尺楼","d":"上下床：慢待客人。清赵翼《题间游草后》之一：“共知殷浩宜高阁，偏伴陈登卧下床。”；楼上元龙：指尊贵之人。金元好问《寄希颜》之二：“山头杜甫长年瘦，楼上元龙先日豪。”","s":"《三国志》卷七〈魏书·吕布传·陈登〉","w":"陈登者，字元龙，在广陵有威名。又掎角吕布有功，加伏波将军，年三十九卒。后许汜与刘备并在荆州牧刘表坐，表与备共论天下人，汜曰：「陈元龙湖海之士，豪气不除。」备谓表曰：「许君论是非？」表曰：「欲言非，此君为善士，不宜虚言；欲言是，元龙名重天下。…","q":[["昨日临川谢病还，求田问舍独相关。","戴叔伦 题招隐寺"],["遥想荆州人物论，几回中夜惜元龙。","柳宗元 同刘二十八哭吕衡州兼寄江陵李元二侍御"]]},{"n":"骥才","d":"","s":"《三国志》卷三十七〈蜀书·庞统传〉～953～","w":"庞统字士元，襄阳人也。少时朴钝，未有识者。颍川司马徽清雅有知人鉴，统弱冠往见徽，徽采桑于树上，坐统在树下，共语自昼至夜。徽甚异之，称统当南州士之冠冕，由是渐显。后郡命为功曹。性好人伦，勤于长养。每所称述，多过其才，时人怪而问之，统答曰：「当…","q":[]},{"n":"失匕箸","d":"","s":"《三国志》卷三十二〈蜀书·先主备传〉～875～","w":"先主未出时，献帝舅车骑将军董承辞受帝衣带中密诏，当诛曹公。先主未发。是时曹公从容谓先主曰：「今天下英雄，唯使君与操耳。本初之徒，不足数也。」先主方食，失匕箸。遂与承及长水校尉种辑、将军吴子兰、王子服等同谋。会见使，未发。事觉，承等皆伏诛。南…","q":[["四夷闻风失匕箸，天子受贺登高楼。","刘禹锡 平蔡州三首"],["杯酒英雄君与操，文章微婉我知丘。","白居易 哭刘尚书梦得二首"]]},{"n":"闭门种菜","d":"","s":"《三国志》卷三十二〈蜀书·先主备传〉～875～","w":"南朝宋·裴松之注引胡冲《吴历》曰：「曹公数遣亲近密觇诸将有宾客酒食者，辄因事害之。备时闭门，将人种芜菁，曹公使人窥门。既去，备谓张飞、关羽曰：『吾岂种菜者乎？曹公必有疑意，不可复留。』其夜开后栅，与飞等轻骑俱去，所得赐遗衣服，悉封留之，乃往…","q":[]},{"n":"很石","d":"","s":"《苕溪渔隐丛话》前集卷二十四引〈蔡宽夫诗话〉","w":"润州甘露寺有块石，状如伏羊，形制略具，号很石。相传孙权尝据其上，与刘备论曹公。壁间旧有罗隐诗板云：「紫髯桑盖两沉吟，很石空存事莫寻。","q":[]},{"n":"池中物","d":"","s":"《三国志》卷五十四《吴书·周瑜传》","w":"权拜瑜偏将军，领南郡太守。以下隽、汉昌、刘阳、州陵为奉邑，屯据江陵。刘备以左将军领荆州牧，治公安。备诣京见权，瑜上疏曰：「刘备以枭雄之姿，而有关羽、张飞熊虎之将，必非久屈为人用者。愚谓大计宜徙备置吴，盛为筑宫室，多其美女玩好，以娱其耳目，分…","q":[["吾子得神仙，本是池中物。","杜甫 七月三日亭午已后较热退晚加小凉稳睡有诗因论壮年乐事戏呈元二十一曹长"],["岂是池中物，由来席上珍。","杜甫 上韦左相二十韵（见素。天宝元年。改侍中为左相。中书令为右相。十五载。见素从明皇幸蜀。至巴西。诏兼左相。封豳国公。）"]]},{"n":"赤壁楼船","d":"","s":"《三国志》卷四十七〈吴书·吴主权传〉～7～","w":"三年春，权复征黄祖，祖先遣舟兵拒军，都尉吕蒙破其前锋，而淩统、董袭等尽锐攻之，遂屠其城。祖挺身亡走，骑士冯则追枭其首，虏其男女数万口。是岁，使贺齐讨黟、歙，黟音伊。歙音摄。分歙为始新、新定、犁阳、休阳县，以六县为新都郡。荆州牧刘表死，鲁肃乞…","q":[]},{"n":"锄兰","d":"","s":"《三国志》卷四十二〈蜀书·周群传〉～02～","w":"裕又私语人曰：「岁在庚子，天下当易代，刘氏祚尽矣。主公得益州，九年之后，寅卯之间当失之。」人密白其言。初，先主与刘璋会涪时，裕为璋从事，侍坐。其人饶须，先主嘲之曰：「昔吾居涿县，特多毛姓，东西南北皆诸毛也，涿令称曰『诸毛绕涿居乎』！」裕即答…","q":[]},{"n":"草庐三顾","d":"三顾：咏帝王爱才求贤。唐杜甫《蜀相》：“三顾频烦天下计，两朝开济老臣心。”","s":"《三国志》卷三十五〈蜀书·诸葛亮传〉～94～","w":"诸葛亮〈出师表〉：「先帝不以臣卑鄙，猥自枉屈，三顾臣于草庐之中，咨臣以当世之事。」","q":[["赤墀高崱屴，一见如三顾。","储光羲 贻王侍御出台掾丹阳"],["乏才叨八使，徇禄非三顾。","元晦 越亭二十韵"]]},{"n":"公安问曹瞒","d":"","s":"《三国志》卷三十二〈蜀书·先主备传〉～878～","w":"先主遣诸葛亮自结于孙权，权遣周瑜、程普等水军数万，与先主并力，与曹公战于赤壁，大破之，焚其舟船。先主与吴军水陆并进，追到南郡，时又疾疫，北军多死，曹公引归。先主表琦为荆州刺史，又南征四郡。武陵太守金旋、长沙太守韩玄、桂阳太守赵范、零陵太守刘…","q":[]},{"n":"关羽","d":"","s":"《三国志》卷三十六《蜀书·关羽传》","w":"先主收江南诸郡，乃封拜元勋，以羽为襄阳太守、荡寇将军，驻江北。先主西定益州，拜羽董督荆州事。","q":[["湘西不得归关羽，河内犹宜借寇恂。","杜甫 奉寄章十侍御"]]},{"n":"马跃檀溪","d":"","s":"《三国志》卷三十二〈蜀书·先主备传〉～876～","w":"曹公既破绍，自南击先主。先主遣麋竺、孙乾与刘表相闻，表自郊迎，以上宾礼待之，益其兵，使屯新野。荆州豪杰归南朝宋·裴松之注引《世语》曰：「备屯樊城，刘表礼焉，惮其为人，不甚信用。曾请备宴会，蒯越、蔡瑁欲因会取备，备觉之，伪如厕，潜遁出。所乘马…","q":[]},{"n":"鱼水亲","d":"","s":"《三国志》卷三十五《蜀书·诸葛亮传》","w":"「亮答曰：『诚如是则霸业可成，汉室可兴矣。』先主曰：『善。』于是与亮情好日密。关羽、张飞等不悦，先主解之曰：『孤之有孔明，如鱼之有水也。愿诸君勿复言。』羽、飞乃止。」","q":[["小白鸿翼于夷吾，刘葛鱼水本无二。","李白 君道曲（梁之雅歌有五篇。今作一章。）"],["稍令社稷安，自契鱼水亲。","杜甫 别蔡十四著作"]]},{"n":"三分","d":"","s":"《三国志》卷三十五〈蜀书·诸葛亮传〉～99～","w":"诸葛亮〈前出师表〉：「先帝创业未半而中道崩殂，今天下三分，益州疲弊，此诚危急存亡之秋也。」","q":[["功盖三分国，名成八阵图。","杜甫 八阵图"],["殊方昔三分，霸气曾间发。","杜甫 鹿头山"]]},{"n":"桑盖","d":"","s":"《三国志》卷三十二〈蜀书·先主备传〉～87～","w":"先主少孤，与母贩履织席为业。舍东南角篱上有桑树生高五丈馀，遥望见童童如小车盖，往来者皆怪此树非凡，或谓当出贵人。先主少时，与宗中诸小儿于树下戏，言：「吾必当乘此羽葆盖车。」","q":[["紫髯桑盖此沈吟，很石犹存事可寻。","罗隐 题润州妙善前石羊"]]},{"n":"孙刘","d":"","s":"《南史》卷五十三〈梁武帝诸子列传·武陵王纪〉～328～","w":"初，天监中，震太阳门，成字曰：「绍宗梁位唯武王。」解者以武陵王当之，于是朝野属意焉。及侯景陷台城，上甲侯韶西上至硖，出武帝密敕，加纪侍中、假黄钺、都督征讨诸军事、骠骑大将军、太尉、承制。大宝元年六月辛酉，纪乃移告诸州征镇，遣世子圆照领二蜀精…","q":[]},{"n":"向古人求","d":"","s":"《三国志》卷七《魏书·吕布传》附《陈登传》","w":"「陈登者，字元龙，在广陵有威名。又掎角吕布有功，加伏波将军，年三十九卒。……备因言曰：『若元龙文武胆志，当求之于古耳，造次难得比也。』」","q":[["垂老遇君未恨晚，似君须向古人求。","杜甫 相逢歌（一作从行）赠严二别驾（一作严别驾相逢歌）"]]},{"n":"玄德依刘","d":"","s":"《三国志》卷三十二〈蜀书·先主备传〉～87～","w":"先主姓刘，讳备，字玄德，涿郡涿县人，汉景帝子中山靖王胜之后也。胜子贞，元狩六年封涿县陆城亭侯。坐酎金失侯，因家焉。先主祖雄，父弘，世仕州郡。雄举孝廉，官至东郡范令……。曹公既破绍，自南击先主。先主遣麋竺、孙乾与刘表相闻，表自郊迎，以上宾礼待…","q":[]}],"44":[{"n":"阿戎","d":"","s":"《世说新语》下卷上《简傲》","w":"「王戎弱冠诣阮籍，时刘公荣在坐。」南朝梁·刘孝标注引《竹林七贤论》曰：「初，籍与戎父浑俱为尚书郎，每造浑，坐未安，辄曰：『与卿语，不如与阿戎语。』就戎，必日夕而返。」","q":[["文人才力薄，终怕阿戎欺。","方干 酬故人陈乂都"],["叨陪丈人行，常恐阿戎欺。","李端 送单少府赴扶风"]]},{"n":"阿戎可语","d":"","s":"《世说新语笺疏》下卷上〈简傲〉～766～","w":"王戎弱冠诣阮籍，时刘公荣在坐。阮谓王曰：「偶有二斗美酒，当与君共饮。彼公荣者，无预焉。」二人交觞酬酢，公荣遂不得一杯。而言语谈戏，三人无异。或有问之者，阮荅曰：「胜公荣者，不得不与饮酒；不如公荣者，不可不与饮酒；唯公荣，可不与饮酒。」南朝梁…","q":[]},{"n":"阿戎跨灶","d":"","s":"《全上古三代秦汉三国六朝文·全三国文》卷二十二〈王朗·杂箴〉～75～","w":"家人有严君焉，井灶之谓也。俾冬作夏，非灶孰能？俾夏作冬，非井孰闲。","q":[]},{"n":"鹤在鸡群","d":"","s":"《世说新语笺疏》下卷上〈容止〉～62～","w":"有人语王戎曰：「嵇延祖卓卓如野鹤之在鸡群。」答曰：「君未见其父耳！」","q":[["又须随计吏，鸡鹤迥然分。","李咸用 宿隐者居"],["昨日朱门一见君，忽惊野鹤在鸡群。","李群玉 酬崔表仁"]]},{"n":"胜公荣","d":"","s":"《世说新语笺疏》下卷上〈简傲〉～766～","w":"王戎弱冠诣阮籍，时刘公荣在坐。阮谓王曰：「偶有二斗美酒，当与君共饮。彼公荣者，无预焉。」二人交觞酬酢，公荣遂不得一杯。而言语谈戏，三人无异。或有问之者，阮荅曰：「胜公荣者，不得不与饮酒；不如公荣者，不可不与饮酒；唯公荣，可不与饮酒。」南朝梁…","q":[]},{"n":"风尘表","d":"","s":"《晋书》卷四十三〈王戎列传〉～235～","w":"戎有人伦鉴识，尝目山涛如璞玉浑金，人皆钦其宝，莫知名其器；王衍神姿高彻，如瑶林琼树，自然是风尘表物。谓裴頠拙于用长，荀勖工于用短，陈道宁如束长竿。族弟敦有高名，戎恶之。敦每候戎，辄托疾不见。敦后果为逆乱。其鉴赏先见如此。","q":[]},{"n":"将无同","d":"三语掾：代称幕府官员。唐元稹《答姨兄胡灵之见寄五十韵》：“官曹三语掾，国器万寻帧。”又借指椽史之官。唐柳宗元《同刘二十八院长述旧言怀感时书事奉寄遵州张员外使君五十二韵之作用其韵增至八十通赠二君子》：“谁采中原寂，徒巾下泽…","s":"《世说新语笺疏》上卷下〈文学〉","w":"阮宣子（修）有令闻，太尉王夷甫（衍）见而问曰：「老、庄与圣教同异？」对曰：「将无同？」太尉善其言，辟之为掾。世谓「三语掾」。","q":[["可怜三语掾，长作九泉灰。","刘商 杂言同豆卢郎中郭南七里桥哀悼姚仓曹"],["更闻台阁求三语，遥想风流第一人。","王维 同崔傅答贤弟"]]},{"n":"黄公垆","d":"黄公肆：指酒店，或用于悼亡。唐白居易《晚春沽酒》：“醉卧黄公肆，人知我是谁。”","s":"《世说新语笺疏》下卷上〈伤逝〉～637～","w":"王浚冲为尚书令，著公服，乘轺车，经黄公酒垆下过，顾谓后车客：「吾昔与嵇叔夜、阮嗣宗共酣饮于此垆，竹林之游，亦预其末。自嵇生夭、阮公亡以来，便为时所羁绁。今日视此虽近，邈若山河。」","q":[["题诗随谢客，饮酒寄黄翁。","张南史 寄中书李舍人"],["朝朝饮酒黄公垆，脱帽露顶争叫呼。","李颀 别梁锽"]]},{"n":"竹林七贤","d":"七贤：喻指文人放荡不羁，或指独立于世俗之外，或喻朋友的交情深厚。唐卢纶《秋夜同畅当宿潭上西亭》：“圆月出山头，七贤林下游。”","s":"《三国志》卷二十一〈魏书·王粲传·嵇康〉～605～","w":"时又有谯郡嵇康，文辞壮丽，好言老、庄，而尚奇任侠。至景元中，坐事诛。南朝宋·裴松之注引《魏氏春秋》曰：「康寓居河内之山阳县，与之游者，未尝见其喜愠之色。与陈留阮籍、河内山涛、河南向秀、籍兄子咸、琅邪王戎、沛人刘伶相与友善，游于竹林，号为七贤…","q":[["东篱摘芳菊，想见竹林游。","储光羲 仲夏饯魏四河北觐叔"],["超超青云器，婉婉竹林会。","储光羲 奉和韦判官献侍郎叔除河东采访使"]]},{"n":"刘公荣","d":"","s":"《世说新语》下卷上《简傲》","w":"「王戎弱冠诣阮籍，时刘公荣在坐。阮谓王曰：『偶有二斗美酒，当与君共饮。彼公荣者，无预焉。』二人交觞酬酢，公荣遂不得一杯。而言语谈戏，三人无异。或有问之者，阮荅曰：『胜公荣者，不得不与饮酒；不如公荣者，不可不与饮酒；唯公荣，可不与饮酒。』」","q":[["已恨流莺欺谢客，更将浮蚁与刘郎。","温庭筠 李羽处士寄新酝走笔戏酬"]]},{"n":"裴王","d":"","s":"《艺文类聚》卷四十八","w":"南朝陈·江总《让吏部尚书表》曰：窃以汉置五曹，方今六尚，魏隆八凯，拟古六卿。延喻喉舌，远膺枢斗。至如东京许郭，西晋裴王，仰首伸眉，可得论列此矣。","q":[["裴王持藻镜，姚宋斡陶钧。","元稹 代曲江老人百韵"]]},{"n":"如意舞","d":"","s":"《世说新语》下卷上《任诞》","w":"「长史云：『谢掾能作异舞。』谢便起舞，神意甚暇。王公熟视，谓客曰：『使人思安丰。』」","q":[["昔曾如意舞，牵率强为看。","杜甫 宴忠州使君侄宅"],["剩欲提携如意舞，喜多行坐白头吟。","杜甫 舍弟观赴蓝田取妻子到江陵喜寄三首之二"]]},{"n":"俗物","d":"","s":"《世说新语笺疏》下卷下〈排调〉～78～","w":"嵇、阮、山、刘在竹林酣饮，王戎后往。步兵曰：「俗物已复来败人意！」王笑曰：「卿辈意，亦复可败邪？」南朝梁·刘孝标注：「《魏氏春秋》曰：『时谓王戎未能超俗也。』」","q":[["饮酣视八极，俗物都茫茫。","杜甫 壮游"],["眼前无俗物，多病也身轻。","杜甫 漫成二首"]]},{"n":"王戎简要","d":"","s":"《三国志》卷二十三〈魏书·裴潜传〉～674～","w":"南朝宋·裴松之注引《晋诸公赞》：「楷少与琅邪王戎俱为掾发名，钟会致之大将军司马文王曰：『裴楷清通，王戎简要。』文王即辟为掾，进历显位。」","q":[["王戎简要，裴楷清通。","李瀚 蒙求"]]},{"n":"戎眼","d":"","s":"《世说新语笺疏》下卷上〈容止〉～60～","w":"裴令公目：「王安丰眼烂烂如岩下电。」南朝梁·刘孝标注：「王戎形状短小，而目甚清炤，视日不眩。」","q":[["王戎似电休推病，周顗才醒众却惊。","羊昭业 皮袭美见留小燕次韵"]]},{"n":"王戎戏陌","d":"","s":"《晋书》卷四十三〈王戎列传〉～23～","w":"王戎字浚冲，琅邪临沂人也。祖雄，幽州刺史。父浑，凉州刺史、贞陵亭侯。戎幼而颖悟，神彩秀彻。视日不眩，裴楷见而目之曰：「戎眼烂烂，如岩下电。」年六七岁，于宣武场观戏，猛兽在槛中虓吼震地，众皆奔走，戎独立不动，神色自若。魏明帝于阁上见而奇之。又…","q":[["潘岳闲居日，王戎戏陌辰。","李峤 李"]]},{"n":"王戎牙筹","d":"","s":"《晋书》卷四十三〈王戎列传〉～234～","w":"戎以晋室方乱，慕蘧伯玉之为人，与时舒卷，无蹇谔之节。自经典选，未尝进寒素，退虚名，但与时浮沈，户调门选而已。寻拜司徒，虽位总鼎司，而委事僚寀。间乘小马，从便门而出游，见者不知其三公也。故吏多至大官，道路相遇辄避之。性好兴利，广收八方园田水碓…","q":[]},{"n":"小安丰","d":"","s":"《晋书》卷四十三〈王戎列传〉～23～","w":"王戎字浚冲，琅邪临沂人也。祖雄，幽州刺史。父浑，凉州刺史、贞陵亭侯。戎幼而颖悟，神彩秀彻。视日不眩，裴楷见而目之曰：「戎眼烂烂，如岩下电。」年六七岁，于宣武场观戏，猛兽在槛中虓吼震地，众皆奔走，戎独立不动，神色自若。魏明帝于阁上见而奇之。又…","q":[]},{"n":"瑶树","d":"","s":"《世说新语笺疏》中卷下〈赏誉〉～428～","w":"王戎云：「太尉神姿高彻，如瑶林琼树，自然是风尘外物。」","q":[["瑶树忽倾沧海里，醉乡翻在夜台中。","李群玉 哭郴州王使君"]]}],"45":[{"n":"从军乐","d":"从军乐：咏从军。唐刘长卿《奉和李大夫同吕评事太行苦热行兼寄院中诸公仍呈王员外》：“陈琳书记好，王粲从军乐。”","s":"《昭明文选》卷二十七〈诗戊·军戎·从军诗五首〉～269～","w":"从军有苦乐，但闻所从谁？所从神且武，焉得久劳师？相公征关右，赫怒震天威。一举灭獯虏，再举服羌夷。西收边地贼，忽若俯拾遗。陈赏越丘山，酒肉踰川坻。军人多饫饶，人马皆溢肥。徒行兼乘还，空出有馀资。拓地三千里，往返速若飞。歌舞入邺城，所愿获无违。…","q":[["悟主一言那可学，从军五首竟徒为。","窦牟 秋夕閒居对雨赠别卢七侍御坦"],["陈琳书记好，王粲从军乐。","刘长卿 奉和李大夫同吕评事太行苦热行兼寄院中诸公仍呈王员外"]]},{"n":"倒屣迎","d":"倒屣迎：指对贤才尊重，或指对宾客热情。唐王维《春过贺遂员外药园》：“画畏开厨走，来蒙倒屣迎。”","s":"《三国志》卷二十一〈魏书·王粲传〉～597～","w":"献帝西迁，粲徙长安，左中郎将蔡邕见而奇之。时邕才学显著，贵重朝廷，常车骑填巷，宾客盈坐。闻粲在门，倒屣迎之。粲至，年既幼弱，容状短小，一坐尽惊。邕曰：「此王公孙也，有异才，吾不如也。吾家书籍文章，尽当与之。」","q":[["兴比乘舟访，恩怀倒屣亲。","司空曙 送高胜重谒曹王"],["贱子曾尘国士知，登门倒屣忆当时。","吴融 偶题"]]},{"n":"仲宣楼","d":"王粲登楼：指咏叹流落他乡而怀念故土，或指登楼。唐戴叔伦《赠司空拾遗》：“陈琳草奏才还在，王粲登楼兴不赊。”","s":"《昭明文选》卷十一〈赋己·游览·登楼赋〉～489～","w":"登兹楼以四望兮，聊暇日以销忧。背坟衍之广陆兮，临皋隰之沃流。北弥陶牧，西接昭丘。华实蔽野，黍稷盈畴。虽信美而非吾土兮，曾何足以少留？遭纷浊而迁逝兮，漫踰纪以迄今。情眷眷而怀归兮，孰忧思之可任？凭轩槛以遥望兮，向北风而开襟。平原远而极目兮，蔽…","q":[["思乡每读登楼赋，对月空吟叩角歌。","刘沧 汶阳客舍"],["陈琳草奏才还在，王粲登楼兴未赊。","大易 赠司空拾遗"]]},{"n":"非吾土","d":"","s":"《昭明文选》卷十一〈赋己·游览·登楼赋〉～489～","w":"登兹楼以四望兮，聊暇日以销忧。览斯宇之所处兮，实显敞而寡仇。挟清漳之通浦兮，倚曲沮之长洲。背坟衍之广陆兮，临皋隰之沃流。北弥陶牧，西接昭丘。华实蔽野，黍稷盈畴。虽信美而非吾土兮，曾何足以少留？","q":[["此地非吾土，闲留又一年。","李频 秋夜山中思归送友人"],["故园汉上林，信美非吾土。","杜牧 题池州弄水亭"]]},{"n":"风流云散","d":"","s":"《昭明文选》卷二十三〈诗丙·赠答一·赠蔡子笃诗〉～02～","w":"翼翼飞鸾，载飞载东。云徂，言戾旧邦。舫舟翩翩，以溯大江。蔚矣荒涂，时行靡通。慨我怀慕，君子所同。悠悠世路，乱离多阻。济岱江行，邈焉异处。风流云散，一别如雨。人生实难，愿其弗与。瞻望遐路，允企伊伫。烈烈冬日，肃肃凄风。潜鳞在渊，归雁载轩。苟非…","q":[]},{"n":"建安诸子","d":"","s":"《昭明文选》卷五十二〈论二·典论论文〉～2270～","w":"今之文人，鲁国孔融文举，广陵陈琳孔璋，山阳王粲仲宣，北海徐干伟长，陈留阮瑀元瑜，汝南应玚德琏，东平刘桢公干：斯七子者，于学无所遗，于辞无所假，咸以自骋骥騄于千里，仰齐足而并驰。以此相服，亦良难矣。盖君子审己以度人，故能免于斯累，而作论文。","q":[]},{"n":"驴鸣一声","d":"","s":"《世说新语》下卷上《伤逝》","w":"王仲宣好驴鸣。既葬，文帝临其丧，顾语同游曰：「王好驴鸣，可各作一声以送之。」赴客皆一作驴鸣。","q":[["尘满空床屋见天，独作驴鸣一声去。","刘言史 题王况故居"]]},{"n":"麦城赋","d":"","s":"北魏·郦道元《水经注》卷三十二《沮水》","w":"「沮水又南径楚昭王墓，东对麦城，故王仲宣之赋《登楼》云：『西接昭丘，是也。』」","q":[["争奈乱罹人渐少，麦城新赋许谁传。","罗隐 寄京阙陆郎中昆仲"]]},{"n":"七哀","d":"","s":"《昭明文选》卷二十三〈诗丙·哀伤·七哀诗二首〉～087～","w":"〈七哀诗二首〉其一：「西京乱无象。豺虎方遘患。弃中国去，远身适荆蛮。亲戚对我悲，朋友相追攀。出门无所见。白骨蔽平原。出门无所见，白骨蔽平原。路有饥妇人，抱子弃草间。顾闻号泣声，挥涕独不还。未知身死处，何能两相完？南登霸陵岸，回首望长安。悟彼…","q":[["不到无生理，应堪赋七哀。","皎然 题馀不溪废寺"]]},{"n":"琴书与仲宣","d":"","s":"《三国志》卷二十一《魏书·王粲传》","w":"献帝西迁，粲徙长安，左中郎将蔡邕见而奇之。时邕才学显著，贵重朝廷，常车骑填巷，宾客盈坐。闻粲在门，倒屣迎之。粲至，年既幼弱，容状短小，一坐尽惊。邕曰：「此王公孙也，有异才，吾不如也。吾家书籍文章，尽当与之。」","q":[["商瞿五十知无子，更付琴书与仲宣。","元稹 听妻弹别鹤操"],["书籍终相与，青山隔故园。","杜甫 赠虞十五司马"]]},{"n":"适荆蛮","d":"","s":"《三国志》卷二十一〈魏书·王粲传〉～597～","w":"献帝西迁，粲徙长安，左中郎将蔡邕见而奇之。时邕才学显著，贵重朝廷，常车骑填巷，宾客盈坐。闻粲在门，倒屣迎之。粲至，年既幼弱，容状短小，一坐尽惊。邕曰：「此王公孙也，有异才，吾不如也。吾家书籍文章，尽当与之。」年十七，司徒辟，诏除黄门侍郎，以…","q":[["王粲频徵楚，君恩许入秦。","包佶 发襄阳后却寄公安人"],["汉家正离乱，王粲别荆蛮。","孟郊 感怀"]]},{"n":"王粲","d":"王粲：喻才子、诗人或幕宾。唐高适《答侯少府》：“吾党谢王粲，群贤推部诜。”","s":"《三国志》卷二十一〈魏书·王粲传〉～597～","w":"王粲字仲宣，山阳高平人也。曾祖父龚，祖父畅，皆为汉三公。父谦，为大将军何进长史。进以谦名公之冑，欲与为婚，见其二子，使择焉。谦弗许。以疾免，卒于家。献帝西迁，粲徙长安，左中郎将蔡邕见而奇之。时邕才学显著，贵重朝廷，常车骑填巷，宾客盈坐。闻粲…","q":[["兴掩寻安道，词胜命仲宣。","刘禹锡 奉和中书崔舍人八月十五日夜玩月二十韵"],["仲宣题尽平生恨，别处应难看屋梁。","吴融 湖州朝阳楼"]]},{"n":"王仲宣诵碑","d":"","s":"《三国志》卷二十一《魏书·王粲传》","w":"初，粲与人共行，读道边碑，人问曰：「卿能闇诵乎？」曰：「能。」因使背而诵之，不失一字。","q":[["我非王仲宣，去矣徒发蒙。","高适 观李九少府翥树宓子贱神祠碑"]]},{"n":"销忧","d":"","s":"《昭明文选》卷十一、三国魏·王仲宣（粲）《登楼赋》","w":"登兹楼以四望兮，聊暇古雅日以销忧。览斯宇之所处兮，实显敞而寡仇。挟清漳之通浦兮，倚曲沮之长洲。……平原远而极目兮，蔽荆山之高岑。","q":[["王粲尚为南郡客，别来何处更销忧。","刘长卿 和樊使君登润州城楼"],["王粲销忧日，江淹起恨年。","李峤 原"]]},{"n":"依刘表","d":"依刘表：喻依附权贵。唐李商隐《五言述德抒情诗一首四十韵献上杜七兄仆射相公》：“自是依刘表，安能比老彭。”","s":"《三国志》卷二十一《魏书·王粲传》","w":"年十七，司徒辟，诏除黄门侍郎，以西京扰乱，皆不就。乃之荆州依刘表。表以粲貌寝而体弱通侻，不甚重也。","q":[["公子道存知不弃，欲依刘表住南荆。","戴叔伦 送车参军江陵"],["自是依刘表，安能比老彭。","李商隐 五言述德抒情诗一首四十韵献上杜七兄仆射相公"]]},{"n":"仲宣独步","d":"","s":"《隋书》卷三十五《经籍志四》","w":"唐歌虞咏，商颂、周雅，?事缘情，纷纶相袭，自斯已降，其道弥繁。世有浇淳，时移治乱，文体迁变，邪正或殊。宋玉、屈原，激清风于南楚，严、邹、枚、马，陈盛藻于西京，平子艳发于东都，王粲独步于漳、滏。","q":[["仲宣独步，子建八斗。","李瀚 蒙求"]]},{"n":"仲宣覆棋","d":"","s":"《三国志》卷二十一《魏书·王粲传》","w":"初，粲与人共行，读道边碑，人问曰：「卿能闇诵乎？」曰：「能。」因使背而诵之，不失一字。观人围棋，局坏，粲为覆之。棋者不信，以帕盖局，使更以他局为之。用相比校，不误一道。其彊记默识如此。","q":[["江楼覆棋好，谁引仲宣过。","卢纶 送潘述应宏词下第归江南"]]},{"n":"仲宣襟","d":"","s":"《昭明文选》卷十一、三国魏·王仲宣（粲）《登楼赋》","w":"登兹楼以四望兮，聊暇日以销忧。览斯宇之所处兮，实显敞而寡仇。接清漳之通浦兮，倚曲阻之长洲。北弥陶牧，西接昭丘，虽信美而非吾土兮，曾何足以少留。凭轩槛以遥望，向北风而开襟。","q":[["如闻马融笛，若倚仲宣襟。","杜甫 风疾舟中伏枕书怀三十六韵奉呈湖南亲友"],["云架重楼出郡城，虹梁雅韵仲宣情。","王铤 登越王楼见乔公诗偶题"]]},{"n":"仲宣赋","d":"","s":"《三国志》卷二十一《魏书·王粲传》","w":"善属文，举笔便成，无所改定，时人常以为宿构；然正复精意覃思，亦不能加也。著诗、赋、论、议垂六十篇。","q":[["星台二妙逐王师，阮瑀军书王粲诗。","钱起 赋得青城山歌送杨杜二郎中赴蜀军"],["仲宣新有赋，叔夜近无书。","李端 哭张南史因寄南史侄叔宗"]]}],"46":[{"n":"管鲍","d":"","s":"《史记》卷六十二《管晏列传》","w":"管仲夷吾者，颍上人也。少时常与鲍叔牙游，鲍叔知其贤。管仲贫困，常欺鲍叔，鲍叔终善遇之，不以为言。已而鲍叔事齐公子小白，管仲事公子纠。及小白立为桓公，公子纠死，管仲囚焉。鲍叔遂进管仲。管仲既用，任政于齐，齐桓公以霸，九合诸侯，一匡天下，管仲之…","q":[["鲍叔知我贫，烹葵不为薄。","元稹 别李三"],["鲍叔幸相知，田苏颇同游。","刘长卿 送裴四判官赴河西军试"]]},{"n":"城社有狐","d":"","s":"《韩非子》卷十三〈外储说右上·说三〉～","w":"故桓公问管仲：「治国最奚患？」对曰：「最患社鼠矣。」公曰：「何患社鼠哉？」对曰：「君亦见夫为社者乎？树木而涂之，鼠穿其间，掘穴托其中，熏之则恐焚木，灌之则恐涂陀，此社鼠之所以不得也。今人君之左右，出则为势重而收利于民，入则比周而蔽恶于君，内…","q":[["庙堂虽稷契，城社有狐狸。","元稹 酬翰林白学士代书一百韵"],["诳天犹指鹿，依社尚凭狐。","李绅 趋翰苑遭诬构四十六韵"]]},{"n":"存老马","d":"老马：喻指阅历经验丰富者。唐杜甫《观安西兵过赴关中待命二首》之一：“老马夜知道，苍鹰饥著人。”","s":"《韩非子》卷七〈说林上〉～43～","w":"管仲、隰朋从桓公伐孤竹，春往而冬反，迷惑失道。管仲曰：「老马之智可用也。」乃放老马而随之，遂得道焉。乃放老马而随之，遂得道。行山中无水，隰朋曰：「蚁冬居山之阳，夏居山之阴，蚁壤一寸而仞有水。」乃掘地，遂得水。以管仲之圣，而隰朋之智，至其所不…","q":[["风沙移道路，仆马识山川。","姚合 送李琮归灵州觐省"],["征鸿辞塞雪，战马识边秋。","李频 送友人往振武"]]},{"n":"管葛","d":"","s":"《世说新语》中卷下《赏誉》","w":"殷渊源在墓所几十年。于时朝野以拟管、葛，起不起，以卜江左兴亡。","q":[["自言管葛竟谁许，长吁莫错还闭关。","李白 驾去温泉后赠杨山人"],["君臣各有分，管葛本时须。","杜甫 别张十三建封"]]},{"n":"管乐","d":"","s":"《三国志》卷三十五《蜀书·诸葛亮传》","w":"亮躬耕陇亩，好为《梁父吟》。身长八尺，每自比于管仲、乐毅，时人莫之许也。惟博陵崔州平、颍川徐庶元直与亮友善，谓为信然。","q":[["自顾躬耕者，才非管乐俦。","孟浩然 与黄侍御北津泛舟"],["夫子今管乐，英才冠三军。","李白 赠何七判官昌浩"]]},{"n":"管萧","d":"","s":"《三国志》卷三十五《蜀书·诸葛亮传》","w":"昔萧何荐韩信，管仲举王子城父，皆忖己之长，未能兼有故也。亮之器能政理，抑亦管、萧之亚匹也，而时之名将无城父、韩信，故使功业陵迟，大义不及邪？盖天命有归，不可以智力争也。","q":[["将必继管萧，岂惟蹑应徐。","陆长源 酬孟十二新居见寄"]]},{"n":"管夷吾","d":"","s":"《论语》卷七《宪问》","w":"子曰：「管仲相桓公，霸诸侯，一匡天下，民到于今受其赐。微管仲，吾其被发左衽矣。」","q":[["乐广云虽睹，夷吾风未春。","陈子昂 酬李参军崇嗣旅馆见赠"],["郡称廉叔度，朝议管夷吾。","高适 真定即事奉赠韦使君二十八韵"]]},{"n":"管仲相齐","d":"","s":"《史记》卷六十二〈管晏列传·管仲〉～23～","w":"管仲夷吾者，颍上人也。少时常与鲍叔牙游，鲍叔知其贤。管仲贫困，常欺鲍叔，鲍叔终善遇之，不以为言。已而鲍叔事齐公子小白，管仲事公子纠。及小白立为桓公，公子纠死，管仲囚焉。鲍叔遂进管仲。管仲既用，任政于齐，齐桓公以霸，九合诸侯，一匡天下，管仲之…","q":[]},{"n":"荐夷吾","d":"","s":"《国语》卷六《齐语》","w":"桓公自莒反于齐，使鲍叔为宰，辞曰：「臣，君之庸臣也。君加惠于臣，使不冻馁，则是君之赐也。若必治国家者，则非臣之所能也。若必治国家者，则其管夷吾乎。臣之所不若夷吾者五：宽惠柔民，弗若也；治国家不失其柄，弗若也；忠信可结于百姓，弗若也；制礼义可…","q":[["鲍生荐夷吾，一举置齐相。","李白 陈情赠友人"]]},{"n":"江左管夷吾","d":"","s":"《世说新语笺疏》上卷上〈言语〉～97～","w":"温峤初为刘琨使来过江。于时江左营建始尔，纲纪未举。温新至，深有诸虑。既诣王丞相，陈主上幽越，社稷焚灭，山陵夷毁之酷，有黍离之痛。温忠慨深烈，言与泗俱，丞相亦与之对泣。叙情既毕，便深自陈结，丞相亦厚相酬纳。既出，欢然言曰：「江左自有管夷吾，此…","q":[]},{"n":"九合诸侯","d":"","s":"《论语注疏·宪问》～26～","w":"子路曰：「桓公杀公子纠，召忽死之，管仲不死。」曰：「未仁乎？」子曰：「桓公九合诸侯，不以兵车，管仲之力也。如其仁！如其仁！」","q":[]},{"n":"民受其赐","d":"","s":"《论语·先宪》","w":"子贡曰：「管仲非仁者与？桓公杀公子纠，不能死，又相之。」子曰：「管仲相桓公，霸诸侯，一匡天下，民到于今受其赐；微管仲，吾其被发左衽矣！岂若匹夫匹妇之为谅也，自经于沟渎而莫之知也！」","q":[["道州民，民到于今受其赐。","白居易 新乐府（并序）之道州民之美（一有贤字）臣遇明主也"]]},{"n":"齐桓","d":"","s":"《史记》卷三十二《齐太公世家》","w":"「六日至齐，则小白已入，高傒立之，是为桓公。」「桓公既得管仲，与鲍叔、隰朋、高傒修齐国政，连五家之兵，设轻重鱼盐之利，以赡贫穷，禄贤能，齐人皆说。……七年，诸侯会桓公于甄，而桓公于是始霸焉。」","q":[["扶持社稷似齐桓，百万雄师贵可观。","贯休 大蜀皇帝潜龙日述圣德诗五首"]]},{"n":"三走","d":"","s":"《史记》卷六十二《管仲列传》","w":"吾尝三仕三见逐于君，鲍叔不以我为不肖，知我不遭时也。吾尝三战三走，鲍叔不以我怯，知我有老母也。","q":[["吾闻壮夫重心骨，古人三走无摧捽。","李贺 送沈亚之歌"]]},{"n":"射钩","d":"","s":"《春秋左传·僖公二十四年》","w":"「齐桓公置射钩而使管仲相。」晋·杜预注：「乾时之役，管仲射桓公，中带钩。」","q":[["射后呼父，钓翁王春师。","杜牧 杜秋娘诗"]]},{"n":"听曲知宁戚","d":"","s":"《列女传》卷六《辩通传·齐管妾婧》","w":"妾婧者，齐相管仲之妾也。宁戚欲见桓公，道无从，乃为人仆。将车宿齐东门之外，桓公因出，宁戚击牛角而商歌，甚悲，桓公异之，使管仲迎之，宁戚称曰：「浩浩乎白水！」管仲不知所谓，不朝五日，而有忧色，其妾婧进曰：「今君不朝五日而有忧色，敢问国家之事耶…","q":[["听曲知宁戚，夷吾因小妻。","李白 鞠歌行"]]},{"n":"微尔","d":"","s":"《论语》卷七《宪问》","w":"子曰：「管仲相桓公，霸诸侯，一匡天下，民到于今受其赐。微管仲，吾其被发左衽矣。」","q":[["微尔人尽非，于今国犹活。","杜甫 北征"]]},{"n":"小白鸿翼","d":"","s":"《管子·霸形》～429～","w":"桓公在位，管仲隰朋见立，有间，有贰槛飞而过之，桓公叹曰：「仲父，今彼鸿鹄，有时而南，有时而北，有时而往，有时而来，四方无远，所欲至而至焉，非唯有羽翼之故，是以能通其意于天下乎。」管仲隰朋不对。桓公曰：「二子何故不对？」管子对曰：「君有霸王之…","q":[["小白鸿翼于夷吾，刘葛鱼水本无二。","李白 君道曲"]]},{"n":"正名五字","d":"","s":"《管子·揆度》","w":"桓公曰：「事名二，正名五，而天下治。」「何谓事名二？」对曰：「天筴，阳也。壤筴，阴也，此谓事名二。」曰：「何谓正名五。」对曰：「权也、衡也、规也、矩也、准也，此谓正名五。其在色者，青黄白黑赤也。其在声者。宫商角徵羽也。其在味者，醉辛咸苦甘也…","q":[["正名推五字，贵仕仰三圭。","权德舆 酬张秘监阁老喜太常中书二阁老与德舆同日迁官相代之作（时秘书监亦同日拜命）"]]}],"47":[{"n":"爨桐","d":"焦琴：美称琴，或喻人才遭到埋没。宋王禹偁《秋居幽兴》之二：“幽兴将何遣，焦琴贳酒杯。”","s":"《后汉书》卷六十下〈蔡邕列传下〉～2004～","w":"吴人有烧桐以爨者，邕闻火烈之声，知其良木，因请而裁为琴，果有美音，而其尾犹焦，故时人名曰「焦尾琴」焉。","q":[["应谓焦桐堪采斫，不知谁是柳吴兴。","张又新 吹台山"],["焦尾何人听，凉宵对月弹。","李咸用 山居"]]},{"n":"边让忆蔡邕","d":"","s":"《后汉书》卷八十下《文苑传·边让传》","w":"「边让字文礼，陈留浚仪人也。少辩博，能属文。作章华赋，虽多淫丽之辞，而终之以正。」「议郎蔡邕深敬之，以为让宜处高任，乃荐于何进。」「让后以高才擢进，屡迁，出为九江太守，不以为能也。」","q":[["边让今朝忆蔡邕，无心裁曲卧春风。","李贺 南园十三首"]]},{"n":"伯喈迁塞","d":"","s":"《后汉书》卷六十下《蔡邕传》","w":"蔡邕字伯喈，陈留圉人也。……时妖异数见，人相惊扰。其年七月，诏召邕与光禄大夫杨赐、谏议大夫马日磾、议郎张华、太史令单飏诣金商门，引入崇德殿，……章奏，帝览而叹息，因起更衣，曹节于后窃视之，悉宣语左右，事遂漏露。其为邕所裁黜者，皆侧目思报。……","q":[["伯喈迁塞北，亭伯之辽东。","李百药 途中述杯"]]},{"n":"伯喈文篆","d":"","s":"《法书要录》卷一","w":"南朝宋·羊欣《采能书人名》：陈留蔡邕，后汉左中郎将。善篆书，采斯（李斯）、喜（曹喜）之法，真定宜父碑文犹传于事，传者师焉。","q":[["伯喈文与篆，虚作汉家贤。","李嘉祐 送从叔阳冰祇召赴都"]]},{"n":"蔡姬","d":"","s":"《后汉书》卷八十四〈列女列传·董祀妻〉～2800～","w":"陈留董祀妻者，同郡蔡邕之女也，名琰，字文姬。博学有才辩，又妙于音律。适河东卫仲道。夫亡无子，归宁于家。兴平中，天下丧乱，文姬为胡骑所获，没于南匈奴左贤王，在胡中十二年，生二子。曹操素与邕善，痛其无嗣，乃遣使者以金璧赎之，而重嫁于祀。……祀为…","q":[]},{"n":"蔡家亲","d":"","s":"《博物志》卷六《人名考》","w":"蔡伯喈母，袁公妹曜卿姑也。","q":[["平生自有分，况是蔡家亲。","司空曙 喜外弟卢纶见宿"]]},{"n":"蔡琰","d":"","s":"《后汉书》卷八十四〈列女传·董祀妻〉～2800～","w":"陈留董祀妻者，同郡蔡邕之女也，名琰，字文姬。博学有才辩，又妙于音律。适河东卫仲道。夫亡无子，归宁于家。兴平中，天下丧乱，文姬为胡骑所获，没于南匈奴左贤王，在胡中十二年，生二子。曹操素与邕善，痛其无嗣，乃遣使者以金璧赎之，而重嫁于祀。","q":[["文姬留此曲，千载一知音。","刘长卿 鄂渚听杜别驾弹胡琴"],["二妃烟尘外，凄凉转战归。胡笳悲蔡琰，汉使泣明妃。","李敬方 太和公主还宫"]]},{"n":"蔡琰辨琴","d":"","s":"《艺文类聚》卷四十四","w":"《蔡琰别传》曰：琰，字文姬，蔡邕之女，年六岁。夜鼓琴，弦断。琰曰：「第二弦。」邕故断一弦，而问之。琰曰：「第四弦。」邕曰：「偶得之矣。」琰曰：「吴札观化，知兴亡之国；师旷吹律，识南风之不竞。由此观之，何足不知？」","q":[["梁鸿五噫，蔡琰辨琴。","李瀚 蒙求"]]},{"n":"蔡邕书籍","d":"","s":"《后汉书》卷八十四《列女传·董祀妻传》","w":"操因问曰：「闻夫人家先多坟籍，犹能忆识之不？」文姬曰：「昔亡父赐书四千许卷，流离涂炭，罔有存者。今所诵忆，裁四百馀篇耳。」操曰：「今当使十吏就夫人写之。」文姬曰：「妾闻男女之别，礼不亲授。乞给纸笔，真草唯命。」于是缮书送之，文无遗误。","q":[["农桑子云业，书籍蔡邕家。","耿湋 题杨著别业"]]},{"n":"蔡家残史","d":"","s":"《后汉书》卷六十下《蔡邕传》","w":"「邕前在东观，与卢植、韩说等撰补后汉记，会遭事流离，不及得成，因上书自陈，奏其所著十意，分别首目，连置章左。……其撰集汉事，未见录以继后史。适作《灵纪》及十意，又补诸列传四十二篇，因李傕之乱，湮没多不存。」唐·李贤注：「犹《前书》十志也。」","q":[["还有蔡家残史籍，可能分与外人传。","戴叔伦 少女生日感怀"],["汲书荀勖定，汉史蔡邕专。","卢纶 和常舍人晚秋集贤院即事十二韵寄赠江南徐薛二侍郎"]]},{"n":"崔蔡","d":"","s":"《晋书》卷三十六《卫瓘传》附《卫恒传》","w":"汉末又有蔡邕，采斯喜之法，为古今杂形，然精密闲理不如淳也。邕作《篆势》曰：「鸟遗迹，皇颉循。圣作则，制斯文。体有六，篆为真。……聊俯仰而详观，举大较而论旃。」汉兴而有草书，不知作者姓名。至章帝时，齐相杜度号善作篇。后有崔瑗、崔寔，亦皆称工。…","q":[["妙绝当动鬼神泣，崔蔡幽魂更心死。","朱逵 怀素上人草书歌"]]},{"n":"倒屣迎","d":"倒屣迎：指对贤才尊重，或指对宾客热情。唐王维《春过贺遂员外药园》：“画畏开厨走，来蒙倒屣迎。”","s":"《三国志》卷二十一〈魏书·王粲传〉～597～","w":"献帝西迁，粲徙长安，左中郎将蔡邕见而奇之。时邕才学显著，贵重朝廷，常车骑填巷，宾客盈坐。闻粲在门，倒屣迎之。粲至，年既幼弱，容状短小，一坐尽惊。邕曰：「此王公孙也，有异才，吾不如也。吾家书籍文章，尽当与之。」","q":[["兴比乘舟访，恩怀倒屣亲。","司空曙 送高胜重谒曹王"],["贱子曾尘国士知，登门倒屣忆当时。","吴融 偶题"]]},{"n":"得蔡邕书","d":"","s":"晋·张华《博物志》卷六《人名考》","w":"蔡邕有书近万卷，汉末年载数车与王粲。","q":[["不知登座客，谁得蔡邕书。","耿湋 题清源寺"]]},{"n":"断弦问文姬","d":"","s":"《艺文类聚》卷四十四〈乐部四·琴〉～782～","w":"《别传》曰：琰，字文姬，蔡邕之女。年六岁，夜鼓琴，弦断。琰曰：「第二弦。」邕故断一弦，而问之。琰曰：「第四弦。」邕曰：「偶得之矣。」琰曰：「吴札观化，知兴亡之国；师旷吹律。识南风之不竞。由此观之，何足不知。」","q":[]},{"n":"郭泰碑铭","d":"郭泰碑铭：称颂人生前品行。唐罗隐《围城偶作》：“自从郭泰碑铭后，只见黄金不见人。”","s":"《后汉书》卷六十八〈郭符许列传·郭太〉～2226～","w":"建宁元年，太傅陈蕃、大将军窦武为阉人所害，林宗哭之于野，恸。既而叹曰：「『人之云亡，邦国殄瘁』。『瞻乌爰止，不知于谁之屋』耳。」明年春，卒于家，时年四十二。四方之士千馀人，皆来会葬。同志者乃共刻石立碑，蔡邕为其文，既而谓涿郡卢植曰：「吾为碑…","q":[["会葬知元伯，看碑识蔡邕。","张说 李工部挽歌三首"],["自从郭泰碑铭后，只见黄金不见文。","罗隐 圉城偶作"]]},{"n":"柯笛","d":"柯笛：咏笛。唐李縠《浙东罢府西归酬别张广文皮先辈陆秀才》：“兰亭旧址虽曾见，柯笛遗音更不传。”","s":"《后汉书》卷六十下〈蔡邕列传下〉～2003～","w":"「邕虑卒不免，乃亡命江海，远迹吴会。」唐·李贤注引晋·张骘《文士传》曰：「邕告吴人曰：『吾昔尝经会稽高迁亭，见屋椽竹东閒第十六可以为笛。』取用，果有异声。」伏滔〈长笛赋序〉云「柯亭之观，以竹为椽，邕取为笛，奇声独绝」也。","q":[["兰亭旧趾虽曾见，柯笛遗音更不传。","李縠 浙东罢府西归酬别张广文皮先辈陆秀才"],["调高银字声还侧，物比柯亭韵校奇。","杜牧 寄珉笛与宇文舍人"]]},{"n":"洛阳狱","d":"","s":"《后汉书》卷六十下〈蔡邕列传下〉～2002～","w":"于是下邕、质于洛阳狱，劾以仇怨奉公，议害大臣，大不敬，弃市。事奏，中常侍吕强悯邕无罪，请之，帝亦更思其章，有诏减死一等，与家属髡钳徙朔方，不得以赦令除。","q":[["终悲洛阳狱，事近小臣敝。","杜甫 八哀诗赠秘书监江夏李公邕"]]},{"n":"琴书与仲宣","d":"","s":"《三国志》卷二十一《魏书·王粲传》","w":"献帝西迁，粲徙长安，左中郎将蔡邕见而奇之。时邕才学显著，贵重朝廷，常车骑填巷，宾客盈坐。闻粲在门，倒屣迎之。粲至，年既幼弱，容状短小，一坐尽惊。邕曰：「此王公孙也，有异才，吾不如也。吾家书籍文章，尽当与之。」","q":[["商瞿五十知无子，更付琴书与仲宣。","元稹 听妻弹别鹤操"],["书籍终相与，青山隔故园。","杜甫 赠虞十五司马"]]},{"n":"为螳螂动杀机","d":"","s":"《后汉书》卷六十下《蔡邕传》","w":"吴人有烧桐以爨者，邕闻火烈之声，知其良木，因请而裁为琴，果有美音，而其尾犹焦，故时人名曰「焦尾琴」焉。初，邕在陈留也，其邻人有以酒食召邕者，比往而酒以酣焉。客有弹琴于屏，邕至门试潜听之，曰：「嘻！以乐召我而有杀心，何也？」遂反。将命者告主人…","q":[["胸中免被风波挠，肯为螳螂动杀机。","司空图 歌者十二首"]]}],"48":[{"n":"八千子弟","d":"","s":"《史记》卷七〈项羽本纪〉～336～","w":"于是项王乃欲东渡乌江。乌江亭长舣船待，谓项王曰：「江东虽小，地方千里，众数十万人，亦足王也。愿大王急渡。今独臣有船，汉军至，无以渡。」项王笑曰：「天之亡我，我何渡为！且籍与江东子弟八千人渡江而西，今无一人还，纵江东父兄怜而王我，我何面目见之…","q":[["呼吸八千人，横行起江东。","李白 登广武古战场怀古"]]},{"n":"气盖世","d":"楚歌：喻孤军被围或处境窘迫。唐李商隐《泪》：“人去紫台秋人塞，兵残楚帐夜闻歌。”","s":"《史记》卷七〈项羽本纪〉～333～","w":"项王军壁垓下，兵少食尽，汉军及诸侯兵围之数重。夜闻汉军四面皆楚歌，项王乃大惊曰：「汉皆已得楚乎？是何楚人之多也！」项王则夜起，饮帐中。有美人名虞，常幸从；骏马名骓，常骑之。于是项王乃悲歌慷慨，自为诗曰：「力拔山兮气盖世，时不利兮骓不逝。骓不…","q":[["高皇冷笑重瞳客，盖世拔山何所为。","徐夤 偶书"],["空持拔山志，欲夺天地德。","曹邺 秦后作"]]},{"n":"岂其苗裔","d":"重瞳：指舜或项羽，或指有帝王之相。唐李白《远别离》：“九疑联绵皆相似，重瞳孤坟竟何是？”","s":"《史记》卷七〈项羽本纪〉～338～","w":"太史公曰：吾闻之周生曰「舜目盖重瞳子」，又闻项羽亦重瞳子。羽岂其苗裔邪？何兴之暴也！南朝宋·裴骃《史记集解》引尸子曰：「舜两眸子，是谓重瞳。」","q":[["项岂重瞳圣，夔犹一足𨆪。","陆龟蒙 江南秋怀寄华阳山人"]]},{"n":"斗酒彘肩","d":"","s":"《史记》卷七〈项羽本纪〉～33～","w":"项王曰：「壮士，赐之卮酒。」则与斗卮酒。哙拜谢，起，立而饮之。项王曰：「赐之彘肩。」则与一生彘肩。樊哙覆其盾于地，加彘肩上，拔剑切而啖之。","q":[]},{"n":"范增","d":"","s":"《史记》卷七〈项羽本纪〉～325～","w":"项王欲听之。历阳侯范增曰：「汉易与耳，今释弗取，后必悔之。」项王乃与范增急围荥阳。汉王患之，乃用陈平计閒项王。项王使者来，为太牢具，举欲进之。见使者，详惊愕曰：「吾以为亚父使者，乃反项王使者。」更持去，以恶食食项王使者。使者归报项王，项王乃…","q":[]},{"n":"割鸿沟","d":"","s":"《史记》卷七《项羽本纪》","w":"「项王乃与汉约，中分天下，割鸿沟以西者为汉，鸿沟而东者为楚。」南朝宋·裴骃《史记集解》：「文颖曰：『于荥阳下引河东南为鸿沟。』」唐·张守节《史记正义》：「张华云：『大梁城在浚仪县北，县西北渠水东经此城南，又北屈分为二渠。其一渠东南流，始皇凿…","q":[["搀抢扫河洛，直割鸿沟半。","李白 南奔书怀"],["大盗割鸿沟，如风扫秋叶。","李白 赠王判官时馀归隐居庐山屏风叠"]]},{"n":"鸿门","d":"","s":"《史记》卷七《项羽本纪》","w":"沛公旦日从百馀骑来见项王，至鸿门，谢曰：「臣与将军戮力而攻秦，将军战河北，臣战河南，然不自意能先入关破秦，得复见将军于此。今者有小人之言，令将军与臣有却。」项王曰：「此沛公左司马曹无伤言之；不然，籍何以至此。」项王即日因留沛公与饮。项王、项…","q":[["佐汉解鸿门，生唐为后身。","李白 赠张相镐二首之一"]]},{"n":"纪信诈帝","d":"","s":"《汉书》卷一上《高帝纪上》","w":"「夏四月，项羽围汉荥阳，汉王请和，割荥阳以西者为汉。亚父劝项羽急攻荥阳，汉王患之。陈平反间既行，羽果疑亚父。亚父大怒而去，发病死。」「五月，将军纪信曰：『事急矣！臣请诳楚，可以间出。』于是陈平夜出女子东门二千馀人，楚因四面击之。纪信乃乘王车…","q":[["郦寄卖友，纪信诈帝。","李瀚 蒙求"]]},{"n":"衣锦还乡","d":"","s":"《史记》卷七〈项羽本纪〉～35～","w":"居数日，项羽引兵西屠咸阳，杀秦降王子婴，烧秦宫室，火三月不灭；收其货宝妇女而东。人或说项王曰：「关中阻山河四塞，地肥饶，可都以霸。」项王见秦宫皆以烧残破，又心怀思欲东归，曰：「富贵不归故乡，如衣绣夜行，谁知之者！」说者曰：「人言楚人沐猴而冠…","q":[["若逢楚王贵，不作夜行人。","李峤 锦"]]},{"n":"梅鋗十万","d":"","s":"《史记》卷七《项羽本纪》","w":"项王使人致命怀王。怀王曰：「如约。」乃尊怀王为义帝。项王欲自王，先王诸将相。谓曰：「天下初发难时，假立诸侯后以伐秦。然身被坚执锐首事，暴露于野三年，灭秦定天下者，皆将相诸君与籍之力也。义帝虽无功，故当分其地而王之。」诸将皆曰：「善。」乃分天…","q":[["十万梅鋗空寸土，三分孙策竟荒丘。","罗隐 吴门晚泊寄句曲道友"]]},{"n":"扪足","d":"","s":"《史记》卷八〈高祖本纪〉～376～","w":"楚汉久相持未决，丁壮苦军旅，老弱罢转饟。汉王项羽相与临广武之閒而语。项羽欲与汉王独身挑战。汉王数项羽曰：「始与项羽俱受命怀王，曰先入定关中者王之，项羽负约，王我于蜀汉，罪一。秦项羽矫杀卿子冠军而自尊，罪二。项羽已救赵，当还报，而擅劫诸侯兵入…","q":[]},{"n":"沐猴冠","d":"楚沐猴：喻徒有其表之人。宋苏轼《代书答梁先》：“强名太守古徐州，忘归不如楚沐猴。”；沐猴冠：喻徒有其表。目光短浅之人。宋苏拭《锦溪》：“楚人休笑沐猴冠，越俗徒夸翁子贤。”","s":"《史记》卷七《项羽本纪》","w":"人或说项王曰：「关中阻山河四塞，地肥饶，可都以霸。」项王见秦宫皆以烧残破，又心怀思欲东归，曰：「富贵不归故乡，如衣绣夜行，谁知之者！」说者曰：「人言楚人沐猴而冠耳，果然。」项王闻之，烹说者。","q":[["不独凄凉眼前事，咸阳一火便成原。","吴融 废宅"],["国为项籍屠，君同华元戮。","张九龄 和黄门卢监望秦始皇陵"]]},{"n":"神骓","d":"","s":"《史记》卷七〈项羽本纪〉～333～","w":"骏马名骓，常骑之。于是项王乃悲歌慷慨，自为诗曰：「力拔山兮气盖世，时不利兮骓不逝。骓不逝兮可柰何，虞兮虞兮柰若何！」歌数阕，美人和之。项王泣数行下，左右皆泣，莫能仰视。于是项王乃上马骑，麾下壮士骑从者八百馀人，直夜溃围南出，驰走。平明，汉军…","q":[["催榜渡乌江，神骓泣向风。","李贺 马诗二十三首"]]},{"n":"碎玉斗","d":"","s":"《史记》卷七《项羽本纪》","w":"张良入谢，曰：「沛公不胜杯杓，不能辞。谨使臣良奉白璧一双，再拜献大王足下；玉斗一双，再拜奉大将军足下。」项王曰：「沛公安在？」良曰︰「闻大王有意督过之，脱身独去，已至军矣。」项王则受璧，置之坐上。亚父受玉斗，置之地，拔剑撞而破之，曰：「唉！…","q":[["忆昔范增碎玉斗，未使吴兵著白袍。","杜甫 久雨期王将军不至"]]},{"n":"徙帝","d":"","s":"《史记》卷七《项羽本记》","w":"乃求楚怀王孙心民閒，为人牧羊，立以为楚怀王，从民所望也。陈婴为楚上柱国，封五县，与怀王都盱台。项梁自号为武信君。……楚兵已破于定陶，怀王恐，从盱台之彭城，并项羽、吕臣军自将之。以吕臣为司徒，以其父吕青为令尹。以沛公为砀郡长，封为武安侯，将砀…","q":[["徙帝留馀地，封王表旧城。","骆宾王 早发淮口望盱眙"]]},{"n":"养虎","d":"","s":"《史记》卷七《项羽本纪》","w":"汉欲西归，张良、陈平说曰：「汉有天下太半，而诸侯皆附之。楚兵罢食尽，此天亡楚之时也，不如因其机而遂取之。今释弗击，此所谓『养虎自遗患』也。」","q":[["嗾獒翻丑正，养虎欲求全。","韩偓 感事三十四韵"]]},{"n":"虞兮楚","d":"","s":"《史记》卷七〈项羽本纪〉～333～","w":"项王军壁垓下，兵少食尽，汉军及诸侯兵围之数重。夜闻汉军四面皆楚歌，项王乃大惊曰：「汉皆已得楚乎？是何楚人之多也！」项王则夜起，饮帐中。有美人名虞，常幸从；骏马名骓，常骑之。于是项王乃悲歌慷慨，自为诗曰：「力拔山兮气盖世，时不利兮骓不逝。骓不…","q":[]},{"n":"鲰生","d":"","s":"《汉书》卷四十〈张陈王周传·张良〉～2027～","w":"项羽至鸿门，欲击沛公，项伯夜驰至沛公军，私见良，欲与俱去。良曰：「臣为韩王送沛公，今事有急，亡去不义。」乃具语沛公。沛公大惊，曰：「为之柰何？」良曰：「沛公诚欲背项王邪？」沛公曰：「鲰生说我距关毋内诸侯，秦地可王也，故听之。」良曰：「沛公自…","q":[]}],"49":[{"n":"千呼万唤","d":"","s":"《全唐诗》卷四百三十五〈琵琶引〉","w":"千呼万唤始出来，犹抱琵琶半遮面。转轴拨弦三两声，未成曲调先有情。弦弦掩抑声声思，似诉平生不得意。低眉信手续续弹，说尽心中无限事。轻拢慢撚抹复桃，初为霓裳后六幺。……","q":[]},{"n":"间关莺语","d":"","s":"《全唐诗》卷四百三十五〈琵琶引〉","w":"低眉信手续续弹，说尽心中无限事。轻拢慢撚抹复桃，初为霓裳后六幺。大弦嘈嘈如急雨，小弦切切如私语。嘈嘈切切错杂弹，大珠小珠落玉盘。间关莺语花底滑，幽咽泉流水下滩。水泉冷涩弦疑绝，疑绝不通声暂歇。别有幽愁暗恨生，此时无声胜有声。银瓶乍破水将迸，…","q":[]},{"n":"青衫泪","d":"","s":"《全唐诗》卷四百三十五〈琵琶引〉","w":"并序：「元和十年，予左迁九江郡司马。明年秋，送客湓浦口，闻船中夜弹琵琶者【闻舟中夜弹琵琶者】。听其音，铮铮然有京都声【铮铮然有京邑声】，问其人，本长安倡女，尝学琵琶于穆、曹二善才。年长色衰，委身为贾人妇。遂命酒，使快弹数曲。曲罢，悯默，自叙…","q":[]},{"n":"白俗","d":"","s":"《苏轼文集》卷六三〈祭柳子玉文〉","w":"猗欤子玉，南国之秀。甚敏而文，声发自幼。从横武库，炳蔚文囿。独以诗呜，天锡雄咮。元轻白俗，郊寒岛瘦。嘹然一吟，众作卑陋。凡今卿相，伊昔朋旧。平视青云，可到宁骤。孰云坎轲，白发垂脰。才高绝俗，性疏来诟。谪居穷山，遂侣猩狖。夜衾不絮，朝甑绝馏。…","q":[]},{"n":"病与乐天相伴","d":"","s":"《全唐诗》卷四百五十八〈春尽日宴罢感事独吟〉","w":"五年三月今朝尽，客散筵空独掩扉。病共乐天相伴住，春随樊子一时归。閒听莺语移时立，思逐杨花触处飞。金带缒腰衫委地，年年衰瘦不胜衣。","q":[]},{"n":"兜率乐天","d":"","s":"《全唐文》卷六百八十一〈白居易二十六·祭中书韦相公文〉～6865～2～","w":"真谛非空，灵鹫山中，既同前会，兜率天上，岂无后期。呜呼韦君，先后间耳，伏惟尚飨。","q":[]},{"n":"乐天诗句","d":"","s":"《新唐书》卷一百十九〈白居易列传〉～4300～","w":"白居易字乐天，其先盖太原人。北齐五兵尚书建，有功于时，赐田韩城，子孙家焉。又徙下邽。父季庚，为彭城令，李正己之叛，说刺史李洧自归，累擢襄州别驾。……东都所居履道里，疏沼种树，构石楼香山，凿八节滩，自号醉吟先生，为之传。暮节惑浮屠道尤甚，至经…","q":[]},{"n":"玲珑","d":"","s":"《碧鸡漫志》卷一〈唐绝句定为歌曲〉","w":"白乐天守杭，元微之赠云：「休遣玲珑唱我诗，我诗多是别君辞。」自注云：「乐人高玲珑能歌，歌予数十诗。」","q":[]},{"n":"萌草出","d":"","s":"《礼记·月令》","w":"孟春之月……是月也，天气下降，地气上腾，天地和同，草木萌动。","q":[["为君使无私之光及万物，蛰虫昭苏萌草出。","白居易 鸦九剑"]]},{"n":"弄梅","d":"","s":"《全唐诗》卷六百八十三〈偶见【鞦韆】〉","w":"鞦韆打困解罗裙，指点醍醐索一尊【指点醍醐酒一尊】。见客入来和笑走，手搓梅子映中门。","q":[]},{"n":"青山约","d":"","s":"《全唐诗》卷四百四十九〈和微之春日投简阳明洞天五十韵〉","w":"青阳行已半，白日坐将徂。越国强仍大，稽城高且孤。利饶盐煮海，名胜水澄湖。牛斗天垂象，台明地展图【案：天台、四明二山。】。瑰奇填市井，佳丽溢闉阇。句践遗风霸，西施旧俗姝。船头龙夭矫，桥脚兽睢盱。乡味珍蟛蚎【乡味珍彭越】，时鲜贵鹧鸪。语言诸夏异…","q":[]},{"n":"诗豪","d":"","s":"《全唐文》卷六百七十七〈白居易二十二·刘白唱和集解〉～6920～","w":"彭城刘梦得，诗豪者也，其锋森然，少敢当者。予不量力，往往犯之。夫合应者声同，交争者力敌，一往一复，欲罢不能。繇是每制一篇，先相视草，视竟则兴作，兴作则文成。一二年来，日寻笔砚，同和赠答，不觉滋多。至太和三年春，以前纸墨所存者，凡一百三十八首…","q":[]},{"n":"我白君元，各自为长庆","d":"","s":"《全唐文》卷六百五十三〈元稹七·白氏长庆集序〉～6644～","w":"《白氏长庆集》者，太原人白居易之所作，居易字乐天。乐天始言，试指「之」、「无」二字，能不误（原注：具乐天与予书）。始既言，读书勤敏，与他儿异。五六岁识声韵，十五志诗赋，二十七举进士。贞元末，进士尚驰竞，不尚文，就中六籍尤摈落。礼部侍郎高郢始…","q":[]},{"n":"香山居士","d":"","s":"《旧唐书》卷一百六十六〈白居易列传〉～4356～","w":"会昌中，请罢太子少傅，以刑部尚书致仕。与香山僧如满结香火社，每肩舆往来，白衣鸠杖，自称香山居士。","q":[]},{"n":"压倒元白","d":"","s":"《太平广记》卷一百七十八〈贡举一·宴集〉～329～","w":"宝历，杨嗣复具庆下，继放两榜。时于陵自东洛入觐，嗣复率生徒迎于潼关。既而大宴于新昌里第，于陵与所执坐于正寝，公领诸生翊坐于两序。时元、白俱在。皆赋诗于席上。唯刑部侍郎杨汝士诗后成。元、白览之失色。诗曰：「隔坐应须赐御屏，尽将仙翰入高冥。文章…","q":[]},{"n":"杨琼","d":"","s":"《全唐诗》卷四百四十四〈问杨琼〉","w":"古人唱歌兼唱情，今人唱歌唯唱声。欲说向君君不会，试将此语问杨琼。","q":[]},{"n":"杨枝","d":"","s":"《容斋随笔·容斋五笔》卷九〈不能忘情吟〉～907～","w":"既书白公钟情蛮、素于前卷，今复见其不能忘情吟一篇，尤为之感叹，辄载其文，因以自警。其序云：「乐天既老，又病风。乃录家事，会经费，去长物。妓有樊素者，年二十馀，绰绰有歌舞态，善唱杨柳枝，人多以曲名名之，由是名闻洛下，籍在经费中，将放之。……」","q":[]},{"n":"元白","d":"","s":"《全唐文》卷七百六十五〈唐诗类选后序〉～7960～","w":"余为类选三十年。神思耗竭。不觉老之将至。今大纲已定。勒成一家。庶及生存。免负平昔。若元相国稹白尚书居易。擅名一时。天下称为元白。学者翕然。号元和诗。其家集浩大。不可雕摘。今共无所取。盖微志存焉。所不足于此者。以删定之初。如相国令狐楚李凉公逢…","q":[]}],"50":[{"n":"床下伊人心素疑","d":"","s":"《后汉书》卷二十四〈马援列传·马援〉～842～","w":"援谓黄门郎梁松、窦固曰：「凡人为贵，当使可贱，如卿等欲不可复贱，居高坚自持，勉思鄙言。」松后果以贵满致灾，固亦几不免。援尝有疾，梁松来候之，独拜床下，援不荅。松去后，诸子问曰：「梁伯孙帝婿，贵重朝廷，公卿已下莫不惮之，大人柰何独不为礼？」援…","q":[]},{"n":"画虎不成","d":"","s":"《后汉书》卷二十四〈马援列传·马援〉～844～","w":"初，兄子严、敦并喜讥议，而通轻侠客。援前在交阯，还书诫之曰：「吾欲汝曹闻人过失，如闻父母之名，耳可得闻，口不可得言也。好论议人长短，妄是非正法，此吾所大恶也，宁死不愿闻子孙有此行也。汝曹知吾恶之甚矣，所以复言者，施衿结缡，申父母之戒，欲使汝…","q":[["落笔思成虎，悬梭待化龙。","李咸用 夜吟"],["雕龙心己切，画虎意何成。","李商隐 五言述德抒情诗一首四十韵献上杜七兄仆射相公"]]},{"n":"鸢跕水","d":"","s":"《后汉书》卷二十四〈马援列传·马援〉～838～","w":"封援为新息侯，食邑三千户。援乃击牛酾酒，劳飨军士。从容谓官属曰：「吾从弟少游常哀吾慷慨多大志，曰：『士生一世，但取衣食裁足，乘下泽车，御款段马，为郡掾史，守坟墓，乡里称善人，斯可矣。致求盈馀，但自苦耳。』当吾在浪泊、西里閒，虏未灭之时，下潦…","q":[["凌空瘴气堕飞鸟，解语山魈恼病人。","施肩吾 送人南游"],["东走穷归鹤，南征尽跕鸢。","杜甫 秋日夔府咏怀奉寄郑监李宾客一百韵"]]},{"n":"马伏波","d":"","s":"《史记》卷一百一十一〈卫卫将军骠骑列传〉～2945～","w":"将军路博德，平州人。以右北平太守从骠骑将军有功，为符离侯。骠骑死后，博德以卫尉为伏波将军，伐破南越，益封。其后坐法失侯。为彊弩都尉，屯居延，卒。","q":[["伏波初树羽，待尔静川鳞。","刘长卿 送独孤判官赴岭"],["伏波箫鼓水云中，长戟如霜大旆红。","司空曙 送人归黔府"]]},{"n":"薏苡明珠","d":"","s":"《后汉书》卷二十四〈马援列传·马援〉～846～","w":"初，援在交阯，常饵薏苡实，用能轻身省欲，以胜瘴气。南方薏苡实大，援欲以为种，军还，载之一车。时人以为南土珍怪，权贵皆望之。援时方有宠，故莫以闻。及卒后，有上书谮之者，以为前所载还，皆明珠文犀。马武与于陵侯侯昱等皆以章言其状，帝益怒。援妻孥惶…","q":[["珠玑当尽掷，薏苡讵能谗。","元稹 送崔侍御之岭南二十韵"],["不须留薏苡，重遣世人疑。","李群玉 湘阴县送迁客北归"]]},{"n":"伏波米","d":"聚米：指军事上分析地形。明陈瑚《李映碧廷尉遗地图》：“人关无复萧丞相，聚米空思马伏波。”","s":"《后汉书》卷二十四〈马援列传·马援〉～834～","w":"八年，帝自西征嚣，至漆，诸将多以王师之重，不宜远入险阻，计冘豫未决。会召援，夜至，帝大喜，引入，具以群议质之。援因说隗嚣将帅有土崩之埶，兵进有必破之状。又于帝前聚米为山谷，指画形埶，开示众军所从道径往来，分析曲折，昭然可晓。帝曰：「虏在吾目…","q":[["运筹知决胜，聚米似论边。","韦应物 酬豆卢仓曹题库壁见示"]]},{"n":"伏波铜柱","d":"","s":"《后汉书》卷二十四〈马援列传·马援〉～839～","w":"援将楼船大小二千馀艘，战士二万馀人，进击九真贼徵侧馀党都羊等，自无功至居风，斩获五千馀人，峤南悉平。唐·李贤注引《广州记》曰：「援到交阯，立铜柱，为汉之极界也。」","q":[["珠厓天外郡，铜柱海南标。","宋之问 早发韶州"],["君恩过铜柱，戎节限交州。","曹松 南游"]]},{"n":"矍铄翁","d":"","s":"《后汉书》卷二十四《马援传》","w":"「武威将军刘尚击武陵五溪蛮夷，深入，军没，援因复请行。时年六十二，帝悯其老，未许之。援自请曰；『臣尚能被甲上马。』帝令试之。援据鞍顾眄，以示可用。帝笑曰：『矍铄哉是翁也！』遂遣援率中郎将马武、耿舒、刘匡、孙永等，将十二郡募士及刑四万馀人征…","q":[["愧无秋豪力，谁念矍铄翁。","李白 流夜郎半道承恩放还兼欣剋复之美书怀示息秀才"],["垂泪方投笔，伤时即据鞍。","杜甫 送杨六判官使西蕃"]]},{"n":"老子颇哀","d":"","s":"《后汉书》卷二十四〈马援列传·马援〉～835～","w":"九年，拜援为太中大夫，副来歙监诸将平凉州。自王莽末，西羌寇边，遂入居塞内，金城属县多为虏有。来歙奏言陇西侵残，非马援莫能定。十一年夏，玺书拜援陇西太守。……援务开恩信，宽以待下，任吏以职，但总大体而已。宾客故人，日满其门。诸曹时白外事，援辄…","q":[]},{"n":"马革裹尸","d":"","s":"《后汉书》卷二十四〈马援列传〉～84～","w":"初，援军还，将至，故人多迎劳之，平陵人孟冀，名有计谋，于坐贺援。援谓之曰：「吾望子有善言，反同众人邪？昔伏波将军路博德开置七郡，裁封数百户；今我微劳，猥飨大县，功薄赏厚，何以能长久乎？先生奚用相济？」冀曰：「愚不及。」援曰：「方今匈奴、乌桓…","q":[["喋血多壮胆，裹革无怯魂。","员半千 陇头水"],["羊皮赎去士，马革敛还尸。","慧侃 闻侯方儿来寇"]]},{"n":"马少游","d":"","s":"《后汉书》卷二十四《马援传》","w":"援乃击牛酾酒，劳飨军士。从容谓官属曰：「吾从弟少游常哀吾慷慨多大志，曰：『士生一世，但取衣食裁足，乘下泽车，御款段马，为郡掾史，守坟墓，乡里称善人，斯可矣。致求盈馀，但自苦耳。』当吾在浪泊、西里閒，虏未灭之时，下潦上雾，……卧念少游平生时语…","q":[["一以功名累，翻思马少游。","刘禹锡 经伏波神祠"]]},{"n":"马援击蛮未遇","d":"","s":"《后汉书》卷二十四〈马援列传·马援〉～842～","w":"二十四年，武威将军刘尚击武陵五溪蛮夷，深入，军没，援因复请行。时年六十二，帝悯其老，未许之。援自请曰；「臣尚能被甲上马。」帝令试之。援据鞍顾眄，以示可用。帝笑曰：「矍铄哉是翁也！」遂遣援率中郎将马武、耿舒、刘匡、孙永等，将十二郡募士及刑四…","q":[]},{"n":"求赢馀","d":"","s":"《后汉书》卷二十四《马援传》","w":"从容谓官属曰：「吾从弟少游常哀吾慷慨多大志，曰：『士生一世，但取衣食裁足，乘下泽车，御款段马，为郡掾史，守坟墓，乡里称善人，斯可矣。致求盈馀，但自苦耳。』」","q":[["岂必求赢馀，所要石与甔。","韩愈 秋怀诗十一首之七"]]},{"n":"少马援","d":"","s":"《后汉书》卷二十四〈马援列传·马援〉～827～","w":"马援字文渊，扶风茂陵人也。其先赵奢为赵将，号曰马服君，子孙因为氏。武帝时，以吏二千石自邯郸徙焉。曾祖父通，以功封重合侯，坐兄何罗反，被诛，故援再世不显。援三兄况、余、员，并有才能，王莽时皆为二千石。……援年十二而孤，少有大志，诸兄奇之。尝受…","q":[]},{"n":"少游衣食","d":"","s":"《后汉书》卷二十四〈马援列传·马援〉～838～","w":"又交阯女子徵侧及女弟徵贰反，攻没其郡，九真、日南、合浦蛮夷皆应之，寇略岭外六十馀城，侧自立为王。于是玺书拜援伏波将军，以扶乐侯刘隆为副，督楼船将军段志等南击交阯。军至合浦而志病卒，诏援并将其兵。遂缘海而进，随山刊道千馀里。十八年春，军至浪泊…","q":[]},{"n":"文渊","d":"","s":"《后汉书》卷二十四〈马援列传·马援〉～827～","w":"马援字文渊，扶风茂陵人也。其先赵奢为赵将，号曰马服君，子孙因为氏。武帝时，以吏二千石自邯郸徙焉。曾祖父通，以功封重合侯，坐兄何罗反，被诛，故援再世不显。援三兄况、余、员，并有才能，王莽时皆为二千石。援年十二而孤，少有大志，诸兄奇之。……、九…","q":[]},{"n":"武陵曲","d":"","s":"《古今注》卷中〈音乐〉","w":"〈武陵深〉，马援为南征之所作。援门生爰寄生，善吹笛，援作歌和之，名曰〈武陵深〉。其曲曰：「滔滔武溪一何深，鸟飞不度，兽不能临。嗟哉武陵兮所毒淫！」","q":[["胡骑中宵堪北走，武陵一曲想南征。","杜甫 吹笛"]]}],"51":[{"n":"磻溪","d":"傅野：喻贤士在野。唐杜甫《秋日荆南述怀》：“贤非梦傅野，隐类凿颜坯。”；朝歌屠叟：喻未被赏识的贤德之士。唐李白《梁甫吟》：“君不见朝歌屠叟辞棘津，八十西来钓渭滨。”","s":"《史记》卷三十二〈齐太公世家〉～477～","w":"太公望吕尚者，东海上人。其先祖尝为四岳，佐禹平水土甚有功。虞夏之际封于吕，或封于申，姓姜氏。夏商之时，申、吕或封枝庶子孙，或为庶人，尚其后苗裔也。本姓姜氏，从其封姓，故曰吕尚。吕尚盖尝穷困，年老矣，以渔钓奸周西伯。西伯将出猎，卜之，曰「所获…","q":[["超超渭滨器，落落山西名。","储光羲 哥舒大夫颂德"],["垂纶非钓国，好学异希颜。","储光羲 游茅山五首"]]},{"n":"非熊","d":"非熊：指扶持国政之相。唐元稹《有鸟二十章》：“文王长在苑中猎，何日非熊休卖屠？”","s":"《史记》卷三十二〈齐太公世家〉～477～","w":"吕尚盖尝穷困，年老矣，以渔钓奸周西伯。西伯将出猎，卜之，曰「所获非龙非?，非虎非罴；所获霸王之辅」。于是周西伯猎，果遇太公于渭之阳，与语大说，曰：「自吾先君太公曰『当有圣人适周，周以兴』。子真是邪？吾太公望子久矣。」故号之曰「太公望」，载与…","q":[["非熊从渭水，瑞翟想陈仓。","魏知古 从猎渭川献诗"],["非熊之兆庆无极，愿纪雄名传百蛮。","卢纶 腊日观咸宁王部曲娑勒摛豹歌"]]},{"n":"丹书","d":"","s":"《大戴礼记·武王践阼》～223～","w":"武王践阼三日，召士大夫而问焉，曰：「恶有藏之约、行之行，万世可以为子孙常者乎？」诸大夫对曰：「未得闻也！」然后召师尚父而问焉，曰：「昔黄帝颛顼之道存乎？意亦忽不可得见与？」师尚父曰：「在丹书，王欲闻之，则齐矣！」王齐三日，端冕，师尚父亦端冕…","q":[]},{"n":"后车载归","d":"","s":"《史记》卷三十二〈齐太公世家〉～477～","w":"吕尚盖尝穷困，年老矣，以渔钓奸周西伯。西伯将出猎，卜之，曰「所获非龙非?，非虎非罴；所获霸王之辅」。于是周西伯猎，果遇太公于渭之阳，与语大说，曰：「自吾先君太公曰『当有圣人适周，周以兴』。子真是邪？吾太公望子久矣。」故号之曰「太公望」，载与…","q":[]},{"n":"姜子牙","d":"","s":"《史记》卷三十二〈齐太公世家〉～477～","w":"太公望吕尚者，东海上人。其先祖尝为四岳，佐禹平水土甚有功。虞夏之际封于吕，或封于申，姓姜氏。夏商之时，申、吕或封枝庶子孙，或为庶人，尚其后苗裔也。本姓姜氏，从其封姓，故曰吕尚。吕尚盖尝穷困，年老矣，以渔钓奸周西伯。西伯将出猎，卜之，曰：「所…","q":[["西伯纵逢头已白，步兵如在眼应青。","李咸用 依韵修睦上人山居十首之九"],["不知姜子牙，何处钓流水。","李咸用 寓意"]]},{"n":"金相","d":"","s":"《毛诗正义》卷十六之三〈大雅·文王之什·棫朴〉～558～","w":"追琢其章，金玉其相。勉勉我王，纲纪四方。唐·孔颖达疏：「言文王之有圣德，其文如彫琢，其质如金玉。」","q":[]},{"n":"乞言","d":"","s":"《礼记注疏》卷二十〈文王世子〉～394～","w":"凡祭，与养老、乞言、合语之礼，皆小乐正诏之于东序。东汉·郑玄注；「乞言，养老人之贤者，因从乞善言可行者也。」","q":[["伫见公车起，圣代待乞言。","权德舆 酬别蔡十二见赠"]]},{"n":"让畔","d":"","s":"《史记》卷四《周本纪》","w":"西伯阴行善，诸侯皆来决平。于是虞、芮之人有狱不能决，乃如周。入界，耕者皆让畔，民俗皆让长。虞、芮之人未见西伯，皆惭，相谓曰：「吾所争，周人所耻，何往为，祇取辱耳。」遂还，俱让而去。诸侯闻之，曰「西伯盖受命之君」。","q":[["树古棠阴在，耕馀让畔空。","李隆基 途次陕州"],["川原馀让畔，歌吹忆遗棠。","蔡希寂 陕中作"]]},{"n":"三时孝养","d":"三时孝养：喻孝养父母。唐韩愈《大行皇太后挽歌词三首》之一：“一纪尊名正，三时孝养荣。”","s":"《礼记注疏》卷二十〈文王世子〉～39～","w":"文王之为世子，朝于王季日三。鸡初鸣而衣服，至于寝门外，问内竖之御者曰：「今日安否何如？」内竖曰：「安。」文王乃喜。及日中又至，亦如之。及莫又至，亦如之。","q":[["一纪尊名正，三时孝养荣。","韩愈 大行皇太后挽歌词三首"]]},{"n":"西伯","d":"","s":"《孟子》卷七《离娄上》","w":"孟子曰：「伯夷辟纣，居北海之滨，闻文王作，兴曰：『盍归乎来！吾闻西伯善养老者。』」","q":[["文王已云没，谁顾好爵縻。","刘叉 答孟东野"],["文王已没不复生，直之道何时行。","卢仝 直吟"]]},{"n":"文王避雨陵","d":"","s":"《春秋左传·僖公三十二年》","w":"「殽有二陵焉，其南陵夏后皋之墓，其北陵文王之所避风雨也。」晋·杜预注：「崤在弘农渑池县西，大阜曰陵。」「此道在二殽之间南谷中，谷深委曲，两山相嵌，故可以辟风雨。」","q":[["烟横博望乘槎水，日上文王避雨陵。","唐彦谦 蒲津河亭"]]},{"n":"文王喻复","d":"","s":"《周易注疏》卷三〈复〉～64～","w":"《复》：亨。出入无疾。朋来无咎。反复其道，七日来复，利有攸往。三国魏·王弼注：「阳气始剥尽，至来复时，凡七日。」","q":[["文王喻复今朝是，子晋吹笙此日同。","李商隐 人日即事"]]},{"n":"问膳","d":"","s":"《礼记·文王世子》","w":"「文王之为世子，朝于王季日三，鸡初鸣而衣服，至于寝门外，问内竖之御者曰：『今日安否何如？』内竖曰：『安。』文王乃喜。及日中又至，亦如之，及莫又至，亦如之。其有不安节，则内竖以告文王，文王色忧，行不能正履，王季复膳，然后亦复初。食上，必在视寒…","q":[["鸡鸣常问膳，今恨玉京留。","王维 恭懿太子挽歌五首"]]},{"n":"莘渭","d":"","s":"《史记》卷三十二〈齐太公世家〉～478～","w":"于是周西伯猎，果遇太公于渭之阳，与语大说，曰：「自吾先君太公曰『当有圣人适周，周以兴』。子真是邪？吾太公望子久矣。」故号之曰「太公望」，载与俱归，立为师。","q":[["贤多隐屠钓，王肯载同归。","杜甫 伤春五首"]]},{"n":"鬻熊师","d":"","s":"《春秋左传·僖公二十六年》","w":"「夔子不祀祝融与鬻熊。」晋·杜预注：「祝融，高辛氏之火正，楚之远祖也。鬻熊，祝融之十二世孙。」","q":[["迹参前马圣，名缀鬻熊师。","张说 赠赵公"]]},{"n":"周王梦","d":"","s":"《礼记·文王世子》","w":"「文王谓武王曰：『女何梦矣？』武王对曰：『梦帝与我九龄？』」文王曰：『女以为何也？』武王曰：『西方有九国焉，君王其终抚诸。』文王曰：『非也。古者谓年龄，齿亦龄也。我百，尔九十，吾与尔三焉。』文王九十七乃终。武王九十三而终。」东汉·郑玄注：「…","q":[["岂比周王梦，徒言得九龄。","李频 府试老人星见"]]},{"n":"周王寿考","d":"","s":"《毛诗正义》卷十六之三〈大雅·文王之什·棫朴〉～557～","w":"倬彼云汉，为章于天。周王寿考，遐不作人。追琢其章，金玉其相。勉勉我王，纲纪四方。东汉。郑玄笺：「周王，文王也。文王是时九十馀矣，故云寿考。」","q":[]}],"52":[{"n":"卧薪尝胆","d":"饮胆：喻失败后刻苦自砺，奋发用强，报仇雪耻。唐刘驾《姑苏台》：“勾践饮胆日。吴酒正满杯。”","s":"《史记》卷四十一〈越王句践世家〉～742～","w":"吴既赦越，越王句践反国，乃苦身焦思，置胆于坐，坐卧即仰胆，饮食亦尝胆也。曰：「女忘会稽之耻邪？」身自耕作，夫人自织，食不加肉，衣不重采，折节下贤人，厚遇宾客，振贫吊死，与百姓同其劳。欲使范蠡治国政，蠡对曰：「兵甲之事，种不如蠡；填抚国家，亲…","q":[["句践胆未尝，夫差心已误。","于濆 经馆娃宫"],["越王尝胆安可敌，远取石田何所益。","刘长卿 登吴古城歌"]]},{"n":"五湖船","d":"","s":"《国语》卷二十一〈越语下·范蠡乘轻舟以浮于五湖〉～658～","w":"反至五湖，范蠡辞于王曰：「君王勉之，臣不复入越国矣。」王曰：「不谷疑子之所谓者何也？」对曰：「臣闻之，为人臣者，君忧臣劳，君辱臣死。昔者君王辱于会稽，臣所以不死者，为此事也。今事已济矣，蠡请从会稽之罚。」王曰：「所不掩子之恶，扬子之美者，使…","q":[["天地庄生马，江湖范蠡舟，逍遥堪自乐，浩荡信无忧。","高适 古乐府飞龙曲留上陈左相"],["范蠡舟偏小，王乔鹤不群。","杜甫 观李固请司马弟山水图三首"]]},{"n":"藏弓","d":"","s":"《史记》卷四十一〈越王句践世家〉～746～","w":"句践已平吴，乃以兵北渡淮，与齐、晋诸侯会于徐州，致贡于周。周元王使人赐句践胙，命为伯。句践已去，渡淮南，以淮上地与楚，归吴所侵宋地于宋，与鲁泗东方百里。当是时，越兵横行于江、淮东，诸侯毕贺，号称霸王。范蠡遂去，自齐遗大夫种书曰：「蜚鸟尽，良…","q":[["藏弓身已退，焚稿事难闻。","刘长卿 秋日夏口涉汉阳献李相公"],["弓藏狡兔尽，慷慨念心伤。","王圭 咏淮阴侯"]]},{"n":"臣妾","d":"","s":"《史记》卷四十一《越王勾践世家》","w":"「吴王闻之，悉发精兵击越，败之夫椒。越王乃以馀兵五千人保栖于会稽。吴王追而围之。」「乃令大夫种行成于吴，膝行顿首曰：『君王亡臣句践使陪臣种敢告下执事：句践请为臣，妻为妾。」吴王将许之。子胥言于吴王曰：『天以越赐吴，勿许也。』种还，以报句践。…","q":[["未散河阳卒，思明伪臣妾。","杜甫 八哀诗（并序）之故司徒李公光弼（光弼已封王。赠太保。称司徒者，以其功名著于司徒时。洗兵马亦云司徒清鉴悬明镜。）"]]},{"n":"豪曹","d":"","s":"《越绝书》卷十一《越绝外传·记宝剑》","w":"越王句践有宝剑五，闻于天下。客有能相剑者，名薛烛。王召而问之，曰：「吾有宝剑五，请以示之。」薛烛对曰：「愚理不足以言，大王请，不得已。」乃召掌者，王使取毫曹。薛烛对曰：「毫曹，非宝剑也。夫宝剑，五色并见，莫能相胜。毫曹已擅名矣，非宝剑也。」","q":[["金羁络騕袅，玉匣闭豪曹。","韩翃 东城水亭宴李侍御副使"]]},{"n":"怒蛙","d":"","s":"《韩非子》卷九〈内储说上·说三〉～554～","w":"越王虑伐吴，欲人之轻死也，出见怒蛙乃为之式，从者曰：『奚敬于此？』王曰：『为其有气故也。』明年之请以头献王者岁十馀人。由此观之，誉之足以杀人矣。一曰。越王句践见怒蛙而式之，御者曰：『何为式？』王曰：『蛙有气如此，可无为式乎？』士人闻之曰：『…","q":[["耳静烦喧蚁，魂惊怯怒蛙。","柳宗元 同刘二十八院长述旧言怀感时书事奉寄澧州张员外使君五十二韵之作因其韵增至八十通赠二君子"],["虽蒙句践礼，竟不闻报效。","韩愈 答柳柳州食虾蟆"]]},{"n":"木客歌","d":"","s":"《吴越春秋》卷九〈句践阴谋外传·勾践十年〉～23～","w":"种曰：「吴王好起宫室，用工不辍。王选名山神材，奉而献之。」越王乃使木工三千馀人，入山伐木，献之吴，一年，师无所幸，作士思归，皆有怨望之心，而歌〈木客〉之吟。一夜，天生神木一双，大二十围，长五十寻，阳为文梓，阴为缏楠。……乃使大夫种献之于吴王…","q":[]},{"n":"乌喙意儿别","d":"","s":"《史记》卷四十一〈越王句践世家〉～746～","w":"句践已平吴，乃以兵北渡淮，与齐、晋诸侯会于徐州，致贡于周。周元王使人赐句践胙，命为伯。句践已去，渡淮南，以淮上地与楚，归吴所侵宋地于宋，与鲁泗东方百里。当是时，越兵横行于江、淮东，诸侯毕贺，号称霸王。范蠡遂去，自齐遗大夫种书曰：「蜚鸟尽，良…","q":[]},{"n":"十年生聚","d":"","s":"《春秋左传正义》卷五十七〈哀公·传元年〉～990～","w":"吴王夫差败越于夫椒。报槜李也。遂入越。越子以甲楯五千。保于会稽。使大夫种因吴大宰嚭以行成。吴子将许之。伍员曰。不可。臣闻之。树德莫如滋。去疾莫如尽。昔有过浇。杀斟灌以伐斟鄩。灭夏后相。后缗方娠。逃出自窦。归于有仍。生少康焉。为仍牧正。惎浇能…","q":[]},{"n":"投醪","d":"","s":"《吕氏春秋》卷九《季秋纪·顺民》","w":"「越王苦会稽之耻，欲深得民心，以致必死于吴。身不安枕席，口不甘厚味，目不视靡曼，耳不听钟鼓。三年苦身劳力，焦唇乾肺。内亲群臣，下养百姓，以来其心。有甘脆不足分，弗敢食；有酒流之江，与民同之。」东汉·高诱注：「投醪，同味。」","q":[["欲识投醪遍，应从落帽看。","张登 重阳宴集同用寒字"],["作鼓将军气，投醪壮士觞。","卢从愿 奉和圣制送张说巡边"]]},{"n":"甬东","d":"","s":"《春秋左传正义》卷六十〈哀公·传二十二年〉～049～","w":"冬，十一月，丁卯，越灭吴，请使吴王居甬东，辞曰：「孤老矣，焉能事君？」乃缢。越人以归。晋·杜预注：「甬东，越地。会稽句章县东海中洲也。」","q":[]},{"n":"越赂伯嚭","d":"","s":"《史记》卷四十一〈越王句践世家〉～740～","w":"三年，句践闻吴王夫差日夜勒兵，且以报越，越欲先吴未发往伐之。范蠡谏曰：「不可。臣闻兵者凶器也，战者逆德也，争者事之末也。阴谋逆德，好用凶器，试身于所末，上帝禁之，行者不利。」越王曰：「吾已决之矣。」遂兴师。吴王闻之，悉发精兵击越，败之夫椒。…","q":[]},{"n":"越台","d":"","s":"《太平御览》卷一百七十八〈居处部六·台下〉～996～2～","w":"吴既败越王勾践于会稽山上，地方千里。勾践得范蠡之谋，躬教民以耕桑，延四方之士，作台于外而馆贤士，会稽之上有越台。","q":[]},{"n":"钟阜蓼","d":"","s":"东汉·赵晔《吴越春秋》卷八《句践归国外传》","w":"越王念复吴雠非一旦也，苦身劳心，夜以接日。目卧则攻之以蓼，足寒则渍之以水，冬常抱冰，夏还握火，愁心苦志，悬胆于户，出入尝之，不绝于口。","q":[["好移钟阜蓼，莫种首阳薇。","吴融 和睦州卢中丞题茅堂十韵"]]},{"n":"苧罗山","d":"","s":"《吴越春秋》卷九〈勾践阴谋外传·勾践十二年〉～28～","w":"十二年，越王谓大夫种曰：「孤闻吴王淫而好色，惑乱湎，不领政事，因此而谋，可乎？」种曰：「可破。夫吴王淫而好色，宰嚭佞以曳心，往献美女，其必受之。惟王选择美女二人而进之。」越王曰：「善。」乃使相者国中得苧萝山鬻薪之女，曰西施、郑旦。饰以罗榖…","q":[["此去若逢花柳月，栖禅莫向苧萝山。","施肩吾 送僧游越"]]},{"n":"思范蠡","d":"","s":"《吴越春秋》卷十《句践伐吴林外传》","w":"范蠡既去，越王愀然变色，召大夫种曰：「蠡可追乎？」种曰：「不及也。」王曰：「柰何？」种曰：「蠡去时，阴画六，阳画三，日前之神，莫能制者。玄武天空威行，孰敢止者？度天关，涉天梁，后入天一。前翳神光，言之者死，视之者狂。臣愿大王勿复追也。蠡终不…","q":[["不学铸金思范蠡，乞言犹许上丹墀。","窦常 奉贺太保岐公承恩致政"]]}],"53":[{"n":"阿童","d":"","s":"《晋书》卷三十四《羊祜传》","w":"又时吴有童谣曰：「阿童复阿童，衔刀浮渡江。不畏岸上兽，但畏水中龙。」祜闻之曰：「此必水军有功，但当思应其名者耳。」会益州刺史王浚徵为大司农，祜知其可任，浚又小字阿童，因表留浚监益州诸军事，加龙骧将军，密令修舟楫，为顺流之计。","q":[["人间无阿童，犹唱水中龙。","李贺 王浚墓下作"]]},{"n":"罢亥市","d":"","s":"《晋书》卷三十四《羊祜传》","w":"帝将有灭吴之志，以祜为都督荆州诸军事、假节，散骑常侍、卫将军如故。祜率营兵出镇南夏，开设庠序，绥怀远近，甚得江汉之心。……疾渐笃，乃举杜预自代。寻卒，时年五十八。帝素服哭之，甚哀。是日大寒，帝涕泪沾须鬓，皆为冰焉。南州人征市日闻祜丧，莫不号…","q":[["市若荆州罢，池如薛县平。","崔融 户部尚书崔公挽歌"],["湘南罢亥市，汉上改词曹。","权德舆 湖南观察使故相国袁公挽歌二首"]]},{"n":"藏环","d":"","s":"《晋书》卷三十四《羊祜传》","w":"祜年五岁，时令乳母取所弄金环。乳母曰：「汝先无此物。」祜即诣邻人李氏东垣桑树中探得之。主人惊曰：「此吾亡儿所失物也，云何持去！」乳母具言之，李氏悲惋。时人异之，谓李氏子则祜之前身也。","q":[["纵使得如羊叔子，不闻兼记旧交情。","元稹 僧如展及韦载同游碧涧寺各赋诗予落句云他生莫忘灵山座满壁人名后会稀"],["认得旧溪兼旧意，恰如羊祜识金环。","吴融 阌乡寓居十首钓竿"]]},{"n":"改词曹","d":"","s":"《晋书》卷三十四〈羊祜列传〉～022～","w":"祜所著文章及为老子传并行于世。襄阳百姓于岘山祜平生游憩之所建碑立庙，岁时飨祭焉。望其碑者莫不流涕，杜预因名为堕泪碑。荆州人为祜讳名，屋室皆以门为称，改户曹为辞曹焉。","q":[["辞曹讳羊祜，此驿何不侔。","元稹 阳城驿"],["湘南罢亥市，汉上改词曹。","权德舆 湖南观察使故相国袁公挽歌二首"]]},{"n":"轻裘缓带","d":"","s":"《晋书》卷三十四〈羊祜列传〉～04～","w":"帝将有灭吴之志，以祜为都督荆州诸军事、假节，散骑常侍、卫将军如故。祜率营兵出镇南夏，开设庠序，绥怀远近，甚得江汉之心。与吴人开布大信，降者欲去皆听之。时长吏丧官，后人恶之，多毁坏旧府，祜以死生有命，非由居室，书下征镇，普加禁断。吴石城守去襄…","q":[]},{"n":"堕泪碑","d":"","s":"《晋书》卷三十四〈羊祜列传〉～020～","w":"祜乐山水，每风景，必造岘山，置酒言咏，终日不倦。尝慨然叹息，顾谓从事中郎邹湛等曰：「自有宇宙，便有此山。由来贤达胜士，登此远望，如我与卿者多矣！皆湮灭无闻，使人悲伤。如百岁后有知，魂魄犹应登此也。」湛曰：「公德冠四海，道嗣前哲，令闻令望，必…","q":[["羊公名渐远，唯有岘山碑。","元稹 襄阳道"],["好辞千古事，堕泪万家人。","刘长卿 朱放自杭州与故里相使君立碑回因以奉简吏部杨侍郎制文"]]},{"n":"对叔子风流","d":"","s":"《三国志》卷五十八〈吴书·陆逊传·陆抗传〉～354～","w":"抗字幼节，孙策外孙也。逊卒时，年二十，拜建武校尉，领逊众五千人，送葬东还，诣都谢恩。孙权以杨竺所白逊二十事问抗，禁绝宾客，中使临诘，抗无所顾问，事事条答，权意渐解。赤乌九年，迁立节中郎将，与诸葛恪换屯柴桑。抗临去，皆更缮完城围，葺其墙屋，居…","q":[]},{"n":"焚稿","d":"","s":"《晋书》卷三十四《羊祜传》","w":"祜历职二朝，任典枢要，政事损益，皆咨访焉，势利之求，无所关与。其嘉谋谠议，皆焚其草，故世莫闻。凡所进达，人皆不知所由。或谓祜慎密太过者，祜曰：「是何言欤！夫入则造膝，出则诡辞，君臣不密之诫，吾惟惧其不及。不能举贤取异，岂得不愧知人之难哉！且…","q":[["藏弓身已退，焚稿事难闻。","刘长卿 秋日夏口涉汉阳献李相公"],["对客默焚稿，何人知谏书。","杨巨源 和卢谏议朝回书情即事寄两省阁老兼呈二起居谏院诸院长"]]},{"n":"陆抗尝药","d":"","s":"《晋书》卷三十四〈羊祜列传〉～07～","w":"祜与陆抗相对，使命交通，抗称祜之德量，虽乐毅、诸葛孔明不能过也。抗尝病，祜馈之药，抗服之无疑心。人多谏抗，抗曰：「羊祜岂酖人者！」时谈以为华元、子反复见于今日。抗每告其戍曰：「彼专为德，我专为暴，是不战而自服也。各保分界而已，无求细利。」孙…","q":[["惭非叔子空持药，更请伯言审细看。","周繇 以人参遗段成式"],["句践投醪，陆抗尝药。","李瀚 蒙求"]]},{"n":"羊叔子","d":"","s":"《晋书》卷三十四《羊祜传》","w":"「羊祜字叔子，泰山南城人也。」「帝将有灭吴之志，以祜为都督荆州诸军事、假节，散骑常侍、卫将军如故。祜率营兵出镇南夏，开设庠序，绥怀远近，甚得江汉之心。」「祜卒二岁而吴平，群臣上寿，帝执爵流涕曰：『此羊太傅之功也。』」","q":[["叔子神如在，山公兴未阑。","孟浩然 卢明府九日岘山宴袁使君张郎中崔员外"],["比肩羊叔子，千载岂无才。","张说 四月一日过江赴荆州"]]},{"n":"忘形湛辈","d":"","s":"《晋书》卷三十四〈羊祜列传〉～020～","w":"祜乐山水，每风景，必造岘山，置酒言咏，终日不倦。尝慨然叹息，顾谓从事中郎邹湛等曰：「自有宇宙，便有此山。由来贤达胜士，登此远望，如我与卿者多矣！皆湮灭无闻，使人悲伤。如百岁后有知，魂魄犹应登此也。」湛曰：「公德冠四海，道嗣前哲，令闻令望，必…","q":[]},{"n":"羊杜","d":"","s":"《苏轼诗集》卷二〈襄阳古乐府三首〉","w":"〈襄阳古乐府三首〉其三：「使君未来襄阳愁，提戈入市裹毡裘。自从毡裘南渡沔，襄阳无事多春游。襄阳春游乐何许，岘山之阳汉江浦。使君朱旆来翻翻，人道使君似羊、杜。道边逢人问洛阳，中原苦战春田荒。北人闻道襄阳乐，目送飞鸿应断肠。」旧题宋·王十朋注引…","q":[]},{"n":"羊公","d":"","s":"《晋书》卷三十四《羊祜传》","w":"「吴人翕然悦服，称为羊公，不之名也。」","q":[["重城洞启肃秋烟，共说羊公在镇年。","司空曙 秋日趋府上张大夫"],["羊公留宴岘山亭，洛浦高歌五夜情。","崔元范 李尚书命妓歌饯有作奉酬"]]},{"n":"羊公灭吹鱼","d":"","s":"《晋书》卷三十四《羊祜传》","w":"「在军常轻裘缓带，身不被甲，铃閤之下，侍卫者不过十数人，而颇以畋渔废政。尝欲夜出，军司徐胤执棨当营门曰：『将军都督万里，安可轻脱！将军之安危，亦国家之安危也。胤今日若死，此门乃开耳。』祜改容谢之，此后稀出矣。」","q":[["君向东州问徐胤，羊公何事灭吹鱼。","卢纶 送史寀滑州谒贾仆射"]]},{"n":"羊祜江山","d":"","s":"《晋书》卷三十四《羊祜传》","w":"「祜乐山水，每风景，必造岘山，置酒言咏，终日不倦。尝慨然叹息，顾谓从事中郎邹湛等曰：『自有宇宙，便有此山。由来贤达胜士，登此远望，如我与卿者多矣！皆湮灭无闻，使人悲伤。如百岁后有知，魂魄犹应登此也。』」","q":[["楚王城垒空秋色，羊祜江山祗暝光。","吴融 和座主尚书登布善寺楼"],["何事此中如世外，应缘羊祜是仙才。","方干 题睦州郡中千峰榭"]]},{"n":"羊与陆","d":"","s":"《晋书》卷三十四〈羊祜列传〉～07～","w":"祜与陆抗相对，使命交通，抗称祜之德量，虽乐毅、诸葛孔明不能过也。抗尝病，祜馈之药，抗服之无疑心。人多谏抗，抗曰：「羊祜岂酖人者！」时谈以为华元、子反复见于今日。抗每告其戍曰：「彼专为德，我专为暴，是不战而自服也。各保分界而已，无求细利。」孙…","q":[]}],"54":[{"n":"尊酒论文","d":"","s":"《全唐诗》卷二百二十四〈春日忆李白〉","w":"白也诗无敌【白也诗无数】，飘然思不群。清新庚开府，俊逸鲍参军【豪迈鲍参军】。渭北春天树，江东日暮云。何时一尊酒，重与细论文【重与话斯文】。","q":[]},{"n":"玉壶冰","d":"","s":"《昭明文选》卷二十八〈诗戊·乐府下·乐府八首·白头吟〉～327～","w":"直如朱丝绳，清如玉壶冰。何惭宿昔意，猜恨坐相仍。人情贱恩旧，世议逐衰兴。毫发一为瑕，丘山不可胜。食苗实硕鼠，玷白信苍蝇。凫鹄远成美，薪刍前见陵。申黜褒女进，班去赵姬升。周王日沦惑，汉帝益嗟称。心赏犹难恃，貌恭岂易凭。古来共如此，非君独抚膺。","q":[["鲍壶冰皎洁，王佩玉丁东。","李商隐 今月二日不自量度辄以诗一首四十韵干渎尊严伏蒙仁恩俯赐披览奖逾其实"],["清规无以况，且用玉壶冰。","李商隐 别薛岩宾"]]},{"n":"沈鲍","d":"","s":"《梁书》卷十三《沈约传》","w":"沈约字休文，吴兴武康人也。……高祖受禅，为尚书仆射，封建昌县侯，邑千户，常侍如故。又拜约母谢为建昌国太夫人。奉策之日，右仆射范云等二十馀人咸来致拜，朝野以为荣。俄迁尚书左仆射，常侍如故。寻兼领军，加侍中。天监二年，遭母忧，舆驾亲出临吊，以约…","q":[["高岑殊缓步，沈鲍得同行。","杜甫 寄彭州高三十五使君适虢州岑二十七长史参三十韵"]]},{"n":"鲍谢","d":"","s":"《九家集注杜诗》卷五〈遣兴五首〉","w":"〈遣兴五首〉其五：「吾怜孟浩然，裋褐即长夜。赋诗何必多，往往凌鲍谢。清江空旧鱼【清江旧鱼美】，春雨馀甘蔗。南望东南云，令人几悲吒。」","q":[]},{"n":"鲍照葵","d":"","s":"《鲍参军集》卷一《园葵赋》","w":"乃羹乃瀹，堆鼎盈筐。甘旨茜脆，柔滑芬芳。……荡然任心，乐道安命。","q":[["嫩割周颙韭，肥烹鲍照葵。","李商隐 题李上谟壁"]]},{"n":"床头钱","d":"","s":"南朝宋·鲍照《鲍参军集》卷四《拟行路难十八首》其五","w":"且愿得志数相就，床头恒有沽酒钱。","q":[["闲时耐相访，正有床头钱。","岑参 郡斋南池招杨辚"]]},{"n":"大雷书","d":"","s":"《鲍参军集》卷二、南朝宋·鲍照《登大雷岸与妹书》","w":"略","q":[["结荷倦水宿，却寄大雷书。","李白 秋浦寄内"]]},{"n":"河清颂","d":"","s":"《宋书》卷五十一〈宗室列传·临川王刘道规·子义庆义庆子烨、衍〉～477～","w":"鲍照字明远，文辞赡逸，尝为古乐府，文甚遒丽。元嘉中，河、济俱清，当时以为美瑞，照为《河清颂》，其序甚工。","q":[["隐士休歌紫芝曲，词人解撰河清颂。","杜甫 洗兵马"]]},{"n":"汤公","d":"","s":"《宋书》卷七十一《徐之湛传》","w":"「时有沙门释惠休，善属文，辞采绮艳，湛之与之甚厚。世祖命使还俗。本姓汤，」","q":[["萧寺春风正落花，淹留数宿惠休家。","刘沧 晚春宿僧院"],["若有诗相赠，期君忆惠休。","司空曙 秋夜忆兴善院寄苗发"]]},{"n":"江鲍","d":"","s":"南朝梁·钟嵘《诗品》卷中","w":"齐光禄江淹诗：文通诗体总杂，善于摹拟。筋力于王微，成就于谢朓。","q":[["览君荆山作，江鲍堪动色。","李白 经乱离后天恩流夜郎忆旧游书怀赠江夏韦太守良宰"],["流传江鲍体，相顾免无儿。","杜甫 赠毕四（曜）"]]},{"n":"金英与侍郎","d":"","s":"《鲍氏集》卷八〈赠鲍郎诗〉","w":"玳枝兮金英，绿叶兮金茎。不入君王杯，低彩还自荣。想君不相艳，酒上视尘生。当令芳意重，无使盛年倾。","q":[["空花一散不知处，谁采金英与侍郎。","柳宗元 闻彻上人亡寄侍郎杨丈"]]},{"n":"鲍庾","d":"","s":"北宋·郭祥正《送马东玉朝散还朝》","w":"唯君最相知，称谓等鲍庾。","q":[]},{"n":"握中丹","d":"","s":"《鲍参军集》卷五《赠故人马子乔诗六首》其五","w":"皎如川上鹄，赫似握中丹。宿心谁不欺，明白古所难。","q":[["何以写此心，赠君握中丹。","孟郊 赠姚怤别"]]},{"n":"芜城作","d":"","s":"《昭明文选》卷十一南朝宋·鲍明远（照）《芜城赋》","w":"唐·李善注：「《集》云：登广陵故城。」","q":[["草玄寄杨子，作赋得芜城。","皎然 兵后与故人别予西上至今在扬楚因有是寄"],["芜城登眺作，才动广陵人。","贾岛 送沈鹤"]]},{"n":"沈休文","d":"","s":"《梁书》卷十三《沈约传》","w":"沈约字休文，吴兴武康人也。……高祖受禅，为尚书仆射，封建昌县侯，邑千户，常侍如故。又拜约母谢为建昌国太夫人。奉策之日，右仆射范云等二十馀人咸来致拜，朝野以为荣。俄迁尚书左仆射，常侍如故。寻兼领军，加侍中。天监二年，遭母忧，舆驾亲出临吊，以约…","q":[["忽见隐侯裁一咏，还须书向郡楼中。","刘言史 处州月夜穆中丞席和主人"],["待到秋深好时节，与君长醉隐侯家。","吴仁璧 南徐题友人郊居"]]},{"n":"鲍明远","d":"","s":"《宋书》卷五十一《宗室传·刘义庆传》附《鲍照传》","w":"鲍照字明远，文辞赡逸，尝为古乐府，文甚遒丽。……临海王子顼为荆州，照为前军参军，掌书记之任。子顼败，为乱兵所杀。","q":[["乐章轻鲍照，碑板笑颜竣。","元稹 代曲江老人百韵"],["如逢祢处士，似见鲍参军。","岑参 送弘文李校书往南汉拜亲"]]}],"55":[{"n":"瑜亮","d":"","s":"《三国演义》第五七回","w":"﹝ 瑜 ﹞长叹曰：‘既生 瑜 ，何生 亮 ！’","q":[]},{"n":"池中物","d":"","s":"《三国志》卷五十四《吴书·周瑜传》","w":"权拜瑜偏将军，领南郡太守。以下隽、汉昌、刘阳、州陵为奉邑，屯据江陵。刘备以左将军领荆州牧，治公安。备诣京见权，瑜上疏曰：「刘备以枭雄之姿，而有关羽、张飞熊虎之将，必非久屈为人用者。愚谓大计宜徙备置吴，盛为筑宫室，多其美女玩好，以娱其耳目，分…","q":[["吾子得神仙，本是池中物。","杜甫 七月三日亭午已后较热退晚加小凉稳睡有诗因论壮年乐事戏呈元二十一曹长"],["岂是池中物，由来席上珍。","杜甫 上韦左相二十韵（见素。天宝元年。改侍中为左相。中书令为右相。十五载。见素从明皇幸蜀。至巴西。诏兼左相。封豳国公。）"]]},{"n":"周瑜破曹","d":"","s":"《三国志》卷四十七〈吴书·吴主权〉～7～","w":"「备进住夏口，使诸葛亮诣权，权遣周瑜、程普等行。是时曹公新得表众，形势甚盛，诸议者皆望风畏惧，多劝权迎之。惟瑜、肃执拒之议，意与权同。瑜、普为左右督，各领万人，与备俱进，遇于赤壁，大破曹公军。公烧其馀船引退，士卒饥疫，死者大半。」","q":[["赤壁争雄如梦里，且须歌舞宽离忧。","李白 江夏赠韦南陵冰"],["烈火张天照云海，周瑜于此破曹公。","李白 赤壁歌送别"]]},{"n":"赤壁楼船","d":"","s":"《三国志》卷四十七〈吴书·吴主权传〉～7～","w":"三年春，权复征黄祖，祖先遣舟兵拒军，都尉吕蒙破其前锋，而淩统、董袭等尽锐攻之，遂屠其城。祖挺身亡走，骑士冯则追枭其首，虏其男女数万口。是岁，使贺齐讨黟、歙，黟音伊。歙音摄。分歙为始新、新定、犁阳、休阳县，以六县为新都郡。荆州牧刘表死，鲁肃乞…","q":[]},{"n":"大小乔","d":"","s":"《三国志》卷五十四〈吴书·周瑜传〉～259～","w":"瑜长壮有姿貌。初，孙坚兴义兵讨董卓，徙家于舒。坚子策与瑜同年，独相友善，瑜推道南大宅以舍策，升堂拜母，有无通共。瑜从父尚为丹杨太守，瑜往省之。会策将东渡，到历阳，驰书报瑜，瑜将兵迎策。策大喜曰：「吾得卿，谐也。」遂从攻横江、当利，皆拔之。乃…","q":[["西京才子旁看取，何似乔家那窈娘。","杜牧 偶呈郑先辈"],["周郎若见红儿貌，料得无心念小乔。","罗虬 比红儿诗"]]},{"n":"周郎顾","d":"周郎顾：咏乐曲或知音。唐李端《听筝》：“欲得周郎顾，时时误拂弦。”","s":"《三国志》卷五十四〈吴书·周瑜传〉～265～","w":"瑜少精意于音乐，虽三爵之后，其有阙误，瑜必知之，知之必顾，故时人谣曰：「曲有误，周郎顾。」","q":[["周郎一回顾，听唱纥那声。","刘禹锡 纥那曲二首"],["惭和周郎应见顾，感知大造竟无穷。","刘耕 和主司王起"]]},{"n":"道南宅","d":"","s":"《三国志》卷五十四《吴书·周瑜传》","w":"瑜长壮有姿貌。初，孙坚兴义兵讨董卓，徙家于舒。坚子策与瑜同年，独相友善，瑜推道南大宅以舍策，升堂拜母，有无通共。","q":[["但苦山北寒，谁知道南宅。","李白 赠友人三首之三"]]},{"n":"分宅","d":"","s":"《昭明文选》卷五十五南朝梁·刘孝标（峻）《广绝交论》","w":"「自昔把臂之英，金兰之友，曾无羊舌下泣之仁，宁慕郈成分宅之德。」唐·李善注：「孔丛子曰：郈成子自鲁聘晋，过于卫，右宰毂臣止而觞之，陈乐而不作，酣毕而送以璧，成子不辞。其仆曰：不辞，何也？成子曰：夫止而觞我，亲我也；陈乐不作，告我哀也；送我以…","q":[["分宅脱骖间，感激怀未济。","杜甫 八哀诗赠秘书监江夏李公邕"]]},{"n":"公瑾","d":"","s":"《三国志》卷五十四〈吴书·周瑜传〉～259～","w":"周瑜字公瑾，庐江舒人也。从祖父景，景子忠，皆为汉太尉。父异，洛阳令。瑜长壮有姿貌。初，孙坚兴义兵讨董卓，徙家于舒。坚子策与瑜同年，独相友善，瑜推道南大宅以舍策，升堂拜母，有无通共。瑜从父尚为丹杨太守，瑜往省之。会策将东渡，到历阳，驰书报瑜，…","q":[]},{"n":"公瑾论兵","d":"","s":"《三国志》卷五十四《吴书·周瑜传》","w":"十三年春，权讨江夏，瑜为前部大督。其年九月，曹公入荆州，刘琮举众降，曹公得其水军，船步兵数十万，将士闻之皆恐。权延见群下，问以计策。议者咸曰：「曹公豺虎也，然托名汉相，挟天子以征四方，动以朝廷为辞，今日拒之，事更不顺。且将军大势，可以拒操者…","q":[["仲华遇主年犹少，公瑾论兵位已酬。","皇甫冉 送崔使君赴寿州"]]},{"n":"万人英","d":"","s":"《毛诗正义》卷五之三〈国风·魏风·汾沮洳〉～207～","w":"彼汾沮洳，言采其莫。彼其之子，美无度；美无度，殊异乎公路。彼汾一方，言采其桑。彼其之子，美如英；美如英，殊异乎公行。彼汾一曲，言采其藚。彼其之子，美如玉；美如玉，殊异乎公族。 唐·孔颖达疏：「《礼运注》云：『英，俊选之尤者。』则英是贤才绝异…","q":[]},{"n":"指囷","d":"指囷：喻指慷慨之友。唐李咸用《古意论交》：“见义必许死，临危当指国。”","s":"《三国志》卷五十四《吴书·鲁肃传》","w":"周瑜为居巢长，将数百人故过候肃，并求资粮。肃家有两囷米，各三千斛，肃乃指一囷与周瑜，瑜益知其奇也，遂相亲结，定侨、札之分。","q":[["赠粟囷应指，登桥柱必题。","杜甫 水宿遣兴奉呈群公"]]},{"n":"周黄策略","d":"","s":"《三国志》卷五十四〈吴书·周瑜传〉～262～","w":"瑜部将黄盖曰：「今寇众我寡，难与持久。然观操军船舰首尾相接，可烧而走也。」乃取蒙冲斗舰数十艘，实以薪草，膏油灌其中，裹以帷幕，上建牙旗，先书报曹公，欺以欲降。又豫备走舸，各系大船后，因引次俱前。曹公军吏士皆延颈观望，指言盖降。盖放诸船，同时…","q":[]},{"n":"周郎","d":"","s":"《三国志》卷五十四《吴书·周瑜传》","w":"是岁，建安三年也。策亲自迎瑜，授建威中郎将，即与兵二千人，骑五十匹。瑜时年二十四，吴中皆呼为周郎。","q":[["三十拥旄谁不羡，周郎少小立奇功。","刘长卿 观校猎上淮西相公"],["阿侯系锦觅周郎，凭仗东风好相送。","李贺 春怀引"]]},{"n":"周醪","d":"","s":"《三国志》卷五十四《吴书·周瑜传》","w":"「是时权位为将军，诸将宾客为礼尚简，而瑜独先尽敬，便执臣节。性度恢廓，大率为得人，惟与程普不睦。」南朝宋·裴松之注引《江表传》曰：「普颇以年长，数陵侮瑜。瑜折节容下，终不与校。普后自敬服而亲重之，乃告人曰：『与周公瑾交，若饮醇醪，不觉自醉。…","q":[["周醪忽同醉，牙弦乃共挥。","许敬宗 冬日宴于庶子宅各赋一字得归"]]}],"56":[{"n":"尧眉","d":"","s":"《艺文类聚》卷十一〈帝王部一·帝尧陶唐氏〉～23～","w":"《尚书·尧典》曰：若稽古帝尧，曰放勋。钦明文思安安，允恭克让。光被四表，格于上下。克明俊德，以亲九族。九族既睦，平章百姓。百姓昭明，协和万邦，黎民于变时邕。《论语》曰：大哉尧之为君也。巍巍乎，唯天为大，唯尧则之，荡荡乎民无能名焉。巍巍乎其有…","q":[]},{"n":"湘夫人","d":"江娥啼竹：咏忧伤之情，或咏竹。唐李贺《李凭箜篌引》：“江娥啼竹素女愁，李凭中国弹箜篌。”","s":"《艺文类聚》卷八十九〈木部下·竹〉～55～","w":"《博物志》曰：洞庭之山，帝之二女啼，以涕挥竹，竹尽班。今下隽有班皮竹。","q":[["愁如湘灵哭湘浦，咽咽哀音隔云雾。九嶷深翠转巍峨，仙骨寒消不知处。","僧鸾 赠李粲秀才"],["河汉夜阑孤雁度，潇湘水阔二妃愁。","刘沧 江楼月夜闻笛"]]},{"n":"比屋逢尧世","d":"","s":"《新语·无为》～65～","w":"夫法令所以诛暴也，故曾、闵之孝，夷、齐之廉，此宁畏法教而为之者哉？故尧、舜之民，可比屋而封，桀、纣之民，可比屋而诛，何者？化使其然也。故近河之地湿，而近山之木长者，以类相及也。高山出云，丘阜生气，四渎东流，百川无西行者，小象大而少从多也。","q":[]},{"n":"鹪鹩一枝","d":"","s":"《庄子》内篇·卷一上《逍遥游》","w":"尧让天下于许由，曰：「日月出矣而爝火不息，其于光也，不亦难乎！时雨降矣而犹浸灌，其于泽也，不亦劳乎！夫子立而天下治，而我犹尸之，吾自视缺然。请致天下。」许由曰：「子治天下，天下既已治也。而我犹代子，吾将为名乎？名者，实之宾也。吾将为宾乎？鹪…","q":[["雕鹗失势病，鹪鹩假翼翔。","孟郊 落第"],["手欠东堂桂一枝，家书不敢便言归。","李咸用 投所知"]]},{"n":"九男事帝","d":"","s":"《史记》卷一〈五帝本纪·帝舜〉～33～","w":"舜年二十以孝闻。三十而帝尧问可用者，四岳咸荐虞舜，曰可。于是尧乃以二女妻舜以观其内，使九男与处以观其外。舜居妫汭，内行弥谨。尧二女不敢以贵骄事舜亲戚，甚有妇道。尧九男皆益笃。舜耕历山，历山之人皆让畔；渔雷泽，雷泽上人皆让居；陶河滨，河滨器皆…","q":[]},{"n":"荣光休气","d":"","s":"《艺文类聚》卷十一〈帝王部一·帝尧陶唐氏〉～23～","w":"《尚书中候》曰：帝尧即政，荣光出河，休气四塞，龙马衔甲，赤文绿色。","q":[["荣光休气纷五彩，千年一清圣人在。","李白 西岳云台歌送丹丘子"]]},{"n":"四岳","d":"","s":"《尚书·虞书·尧典》","w":"「帝曰：『咨四岳。』」旧题汉·孔安国传：「四岳即上羲和之四子，分掌四岳之诸侯，故称焉。」","q":[["尧有四岳明至理，汉二千石真分忧。","杜甫 寄裴施州（裴冕坐李辅国贬施州刺史）"],["昔在尧四岳，今之黄颍川。","杜甫 赠李十五丈别（李秘书文嶷）"]]},{"n":"唐尧咨禹","d":"","s":"《尚书》卷三〈虞书·舜典〉～44～","w":"舜曰：「咨！四岳！有能奋庸，熙帝之载，使宅百揆，亮采惠畴？」佥曰：「伯禹作司空。」帝曰：「俞咨！禹，汝平水土；惟时懋哉！」禹拜稽首，让于稷、契暨皋陶。帝曰：「俞，汝往哉！」帝曰：「弃！黎民阻饥。汝后稷，播时百谷。」帝曰：「契，百姓不亲，五品…","q":[]},{"n":"唐虞","d":"","s":"《尚书》卷十八〈周书·周官〉～269～","w":"王曰：「若昔大猷，制治于未乱，保邦于未危。曰：『唐虞稽古，建官惟百，内有百揆四岳，外有州牧侯伯。庶政惟和，万国咸宁。』夏、商官倍，亦克用乂。明王立政，不惟其官，惟其人。今予小子，祗勤于德，夙夜不逮。仰惟前代时若，训迪厥官。」","q":[]},{"n":"尧历","d":"","s":"《宋书》卷二十七《符瑞志上》","w":"帝尧之母曰庆都，生于斗维之野，常有黄云覆护其上。及长，观于三河，常有龙随之。一旦龙负图而至，其文要曰：「亦受天祐。」眉八彩，鬓发长七尺二寸，面锐上丰下，足履翼宿。既而阴风四合，赤龙感之。孕十四月而生尧于丹陵，其状如图。及长，身长十尺，有圣德…","q":[]},{"n":"五翁","d":"","s":"《宋书》卷二十七《符瑞志上》","w":"帝尧之母曰庆都，生于斗维之野，常有黄云覆护其上。及长，观于三河，常有龙随之。一旦龙负图而至，其文要曰：「亦受天祐。」眉八彩，鬓发长七尺二寸，面锐上丰下，足履翼宿。既而阴风四合，赤龙感之。孕十四月而生尧于丹陵，其状如图。及长，身长十尺，有圣德…","q":[["洗花蒸叶滤清酒，待与夫人邀五翁。","曹唐 小游仙诗九十八首"],["未作三台辅，宁为五老臣。","李峤 星"]]},{"n":"尧禅舜","d":"","s":"《史记》卷一《五帝本纪·尧本纪》","w":"「尧立七十年得舜，二十年而老，令舜摄行天子之政，荐之于天。尧辟位凡二十八年而崩。百姓悲哀，如丧父母。三年，四方莫举乐，以思尧。尧知子丹朱之不肖，不足授天下，于是乃权授舜。」","q":[["古来尧禅舜，何必罪驩兜。","沈佺期 从驩州廨宅移住山间水亭赠苏使君"]]},{"n":"尧舜","d":"","s":"《礼记·大学》","w":"尧舜率天下以仁，而民从之。桀纣率天下以暴，而民从之。","q":[["尧舜传天下，同心致太平。","张说 东都酺宴四首"],["尧舜之事不足惊，自余嚣嚣直可轻。","李白 怀仙歌"]]},{"n":"有虞宫殿","d":"","s":"《史记》卷一〈五帝本纪·帝舜〉～45～","w":"自黄帝至舜、禹，皆同姓而异其国号，以章明德。故黄帝为有熊，帝颛顼为高阳，帝喾为高辛，帝尧为陶唐，帝舜为有虞。帝禹为夏后而别氏，姓姒氏。契为商，姓子氏。弃为周，姓姬氏。南朝宋·裴骃《史记集解》引皇甫谧曰：「舜嫔于虞，因以为氏，今河东大阳西山上…","q":[]},{"n":"岳牧","d":"","s":"《尚书·周书·周官》","w":"「唐虞稽古，建官惟百，内有百揆四岳，外有州牧侯伯。」旧题汉·孔安国传：「外置州牧十二，及五国之长。」唐·孔颖达疏：「四岳，内典四时之政，外主太岳之事，立四人也。外有州牧侯伯，牧，一州之长，侯伯，五国之长，各监其所部之国。」","q":[["幽燕通使者，岳牧用词人。","杜甫 送陵州路使君赴任"]]}],"57":[{"n":"太师尚父","d":"","s":"《毛诗正义》卷十六之二〈大雅·文王之什·大明〉～540～","w":"明明在下，赫赫在上。天难忱斯，不易维王。天位殷适，使不挟四方。挚仲氏任，自彼殷商。来嫁于周，曰嫔于京。乃及王季，维德之行。大任有身，生此文王。维此文王，小心翼翼。昭事上帝，聿怀多福。厥德不回，以受方国。天监在下，有命既集。文王初载，天作之合…","q":[]},{"n":"周吕","d":"","s":"《宋书·周朗传》","w":"今天子以 炎轩 之德，冢辅以 姬 吕 之贤，故赫然发怒，将以 匈奴 衅旗，恻然动仁，欲使馀氓被惠。","q":[]},{"n":"磻溪","d":"傅野：喻贤士在野。唐杜甫《秋日荆南述怀》：“贤非梦傅野，隐类凿颜坯。”；朝歌屠叟：喻未被赏识的贤德之士。唐李白《梁甫吟》：“君不见朝歌屠叟辞棘津，八十西来钓渭滨。”","s":"《史记》卷三十二〈齐太公世家〉～477～","w":"太公望吕尚者，东海上人。其先祖尝为四岳，佐禹平水土甚有功。虞夏之际封于吕，或封于申，姓姜氏。夏商之时，申、吕或封枝庶子孙，或为庶人，尚其后苗裔也。本姓姜氏，从其封姓，故曰吕尚。吕尚盖尝穷困，年老矣，以渔钓奸周西伯。西伯将出猎，卜之，曰「所获…","q":[["超超渭滨器，落落山西名。","储光羲 哥舒大夫颂德"],["垂纶非钓国，好学异希颜。","储光羲 游茅山五首"]]},{"n":"丹书","d":"","s":"《大戴礼记·武王践阼》～223～","w":"武王践阼三日，召士大夫而问焉，曰：「恶有藏之约、行之行，万世可以为子孙常者乎？」诸大夫对曰：「未得闻也！」然后召师尚父而问焉，曰：「昔黄帝颛顼之道存乎？意亦忽不可得见与？」师尚父曰：「在丹书，王欲闻之，则齐矣！」王齐三日，端冕，师尚父亦端冕…","q":[]},{"n":"二老","d":"","s":"《孟子注疏》卷七下〈离娄章句上〉～33～","w":"孟子曰：「伯夷辟纣，居北海之滨，闻文王作，兴曰：『盍归乎来！吾闻西伯善养老者。』太公辟纣，居东海之滨二老者，天下之大老也，而归之，是天下之父归之也。闻文王作，兴曰：『盍归乎来！吾闻西伯善养老者。』」","q":[["与子成二老，来往亦风流。","杜甫 寄赞上人"]]},{"n":"后车载归","d":"","s":"《史记》卷三十二〈齐太公世家〉～477～","w":"吕尚盖尝穷困，年老矣，以渔钓奸周西伯。西伯将出猎，卜之，曰「所获非龙非?，非虎非罴；所获霸王之辅」。于是周西伯猎，果遇太公于渭之阳，与语大说，曰：「自吾先君太公曰『当有圣人适周，周以兴』。子真是邪？吾太公望子久矣。」故号之曰「太公望」，载与…","q":[]},{"n":"灌坛风","d":"灌坛雨：咏雨，或喻有德政。唐杜甫《题都县郭三十二明府茅屋壁》：“云散灌坛雨，春青彭泽田。”","s":"《搜神记》卷四","w":"文王以太公望为灌坛令，期年，风不鸣条。文王梦一妇人，甚丽，当道而哭。问其故。曰：「吾泰山之女，嫁为东海妇，欲归，今为灌坛令当道有德，废我行；我行，必有大风疾雨，大风疾雨，是毁其德也。」文王觉，召太公问之。是日果有疾雨暴风，从太公邑外而过。文…","q":[["云散灌坛雨，春青彭泽田。","杜甫 题郪县郭三十二明府茅屋壁"],["灌坛有遗风，单父多鸣琴。","高适 同房侍御山园新亭与邢判官同游"]]},{"n":"良谋子牙","d":"","s":"《史记》卷三十二〈齐太公世家〉～478～","w":"周西伯昌之脱羑里归，与吕尚阴谋修德以倾商政，其事多兵权与奇计，故后世之言兵及周之阴权皆宗太公为本谋。周西伯政平，及断虞芮之讼，而诗人称西伯受命曰文王。伐崇、密须、犬夷，大作丰邑。天下三分，其二归周者，太公之谋计居多。文王崩，武王即位。九年，…","q":[]},{"n":"吕葛","d":"","s":"《史记》卷三十二《齐太公世家》","w":"「太公望吕尚者，东海上人。其先祖尝为四岳，佐禹平水土甚有功。虞夏之际封于吕，或封于申，姓姜氏。夏商之时，申、吕或封枝庶子孙，或为庶人，尚其后苗裔也。本姓姜氏，从其封姓，故曰吕尚。」","q":[["凄其望吕葛，不复梦周孔。","杜甫 晚登瀼上堂"]]},{"n":"吕尚封国","d":"","s":"《史记》卷四《周本纪》","w":"于是封功臣谋士，而师尚父为首封。封尚父于营丘，曰齐。","q":[["吕尚封国邑，傅说已盐梅。","杜甫 昔游"]]},{"n":"孟津","d":"","s":"《史记》卷三十二〈齐太公世家〉～479～","w":"文王崩，武王即位。九年，欲修文王业，东伐以观诸侯集否。师行，师尚父左杖黄钺，右把白旄以誓，曰：「苍兕苍兕，总尔众庶，与尔舟楫，后至者斩！」遂至盟津。诸侯不期而会者八百诸侯。诸侯皆曰：「纣可伐也。」武王曰：「未可。」还师，与太公作此太誓。","q":[]},{"n":"太公两齿","d":"","s":"《荀子·君道篇》～28～","w":"倜然乃举太公于州人而用之，岂私之也哉！以为亲邪？则周姬姓也，而彼姜姓也；以为故邪？则未尝相识也；以为好丽邪？则夫人行年七十有二，齳然而齿堕矣。","q":[["忆昔太公仕进初，口含两齿无赢馀。","韩愈 赠刘师服"]]},{"n":"王者师","d":"","s":"《史记》卷三十二〈齐太公世家〉～477～","w":"吕尚盖尝穷困，年老矣，以渔钓奸周西伯。西伯将出猎，卜之，曰「所获非龙非，非虎非罴；所获霸王之辅」。于是周西伯猎，果遇太公于渭之阳，与语大说，曰：「自吾先君太公曰『当有圣人适周，周以兴』。子真是邪？吾太公望子久矣。」故号之曰「太公望」，载与俱…","q":[["射钩后呼父，钓翁王者师。","杜牧 杜秋娘诗"]]},{"n":"伊吕","d":"","s":"《汉书》卷五十六《董仲舒传赞》","w":"「刘向称『董仲舒有王佐之材，虽伊吕亡以加。』」唐·颜师古注：「伊，伊尹。吕，吕望也。」","q":[["苍生属伊吕，明主仗韩彭。","刘长卿 至德三年春正月时谬蒙差摄海盐令闻王师收二京因书事寄上浙西节度李侍郎中丞行营五十韵"],["伊吕代封爵，夷齐终身饥。","孟郊 罪松"]]},{"n":"鹰扬","d":"","s":"《诗经·大雅·大明》","w":"「维师尚父，时维鹰扬。凉彼武王，肆伐大商，会朝清明。」汉·毛氏传：「鹰扬，如鹰之飞扬也。」","q":[["诗人何所咏，尚父欲鹰扬。","张九龄 钱王尚书出边"],["蒙轮皆突骑，按剑尽鹰扬。","李隆基 平胡"]]}],"58":[{"n":"捧心颦","d":"丑女效颦：指丑陋而强学美好之人。唐李白《古风五十九首》之三十五：“丑女来效颦，还家惊四邻。”；捧心：喻指仿效弄巧成拙，或喻美女病态。唐”柳宗元《重赠二首》之二：“世世悠悠不识真，姜芽尽是捧心人。’”","s":"《庄子集释》卷五下〈外篇·天运〉～5～","w":"孔子西游于卫。颜渊问师金曰：「以夫子之行为奚如？」师金曰：「惜乎，而夫子其穷哉！」颜渊曰：「何也？」师金曰：「夫刍狗之未陈也，盛以箧衍，巾以文绣，尸祝齐戒以将之。及其已陈也，行者践其首脊，苏者取而爨之而已；将复取而盛以箧衍，巾以文绣，游居寝…","q":[["翻惭效颦者，却笑从人迟。","于濆 拟古意"],["丑女来效颦，还家惊四邻。","李白 古风之三十五"]]},{"n":"颜巷","d":"颜回：指有修养、能安于贫困生活的贤才。唐王绩《被召谢病》：“颜回唯乐道，原宪岂伤贫。”","s":"《史记》卷六十七〈仲尼弟子列传〉～288～","w":"颜回者，鲁人也，字子渊。少孔子三十岁。颜渊问仁，孔子曰：「克己复礼，天下归仁焉。」 孔子曰：「贤哉回也！一箪食，一瓢饮，在陋巷，人不堪其忧，回也不改其乐。」「回也如愚；退而省其私，亦足以发，回也不愚。」「用之则行，舍之则藏，唯我与尔有是夫！…","q":[["陋巷满蓬蒿，谁知有颜子。","于濆 秦富人"],["春草秋风老此身，一瓢长醉任家贫。","刘商 醉后"]]},{"n":"附骥尾","d":"","s":"《史记》卷六十一《伯夷列传》","w":"「颜渊虽笃学，附骥尾而行益显。」唐·司马贞《史记索隐》：「苍蝇附骥尾而致千里，以譬颜回因孔子而名彰也。」","q":[["千里江山陪骥尾，五更风水失龙鳞。","张曙 下第戏状元崔昭纬"],["若向云衢陪骥尾，直须天畔落旄头。","李咸用 和彭进士感怀"]]},{"n":"耕十亩田","d":"","s":"《庄子》杂篇·卷九下《让王》","w":"孔子谓颜回曰：「回，来！家贫居卑，胡不仕乎？」颜回对曰：「不愿仕。回有郭外之田五十亩，足以给饘粥；郭内之田十亩，足以为丝麻；鼓琴足以自娱，所学夫子之道者足以自乐也。回不愿仕。」","q":[["誓耕十亩田，不取万乘相。","韩愈 岳阳楼别窦司直"]]},{"n":"桓山禽","d":"","s":"《孔子家语》卷五《颜回》","w":"孔子在卫，昧旦晨兴，颜回侍侧，闻哭者之声甚哀。子曰：「回，汝知此何所哭乎？」对曰：「回以此哭声非但为死者而已，又有生离别者也。」子曰：「何以知之？」对曰：「回闻桓山之鸟，生四子焉，羽翼既成，将分于四海，其母悲鸣而送之，哀声有似于此，谓其往而…","q":[["荀氏八龙唯欠一，桓山四凤已过三。","包何 相里使君第七男生日"],["桓山之禽别离苦，欲去回翔不能征。","李白 上留田行"]]},{"n":"回夭折","d":"","s":"《史记》卷六十七《仲尼弟子列传》","w":"回年二十九，发尽白，蚤死。孔子哭之恸，曰：「自吾有回，门人益亲。」鲁哀公问：「弟子孰为好学？」孔子对曰：「有颜回者好学，不迁怒，不贰过。不幸短命死矣，今也则亡。」","q":[["回也实夭折，贾生亦脆促。","徐彦伯 题东山子李适碑阴二首"]]},{"n":"回愚","d":"","s":"《论语·为政》","w":"「子曰：『吾与回言终日，不违，如愚。退而省其私，亦足以发，回也不愚。』」","q":[["礼数全优知隗始，讨论常见念回愚。","杜牧 送王侍御赴夏口座主幕"]]},{"n":"屡空","d":"","s":"《论语·先进》","w":"「子曰：『回也其庶乎，屡空。』」三国魏·何晏集解：「言回庶几圣道，虽数空匮而乐在其中。」","q":[["旅兹殊俗远，竟以屡空迫。","杜甫 郑典设自施州归"]]},{"n":"入寥天一","d":"","s":"《庄子集释》卷三上〈内篇·大宗师〉～274～","w":"颜回问仲尼曰：「孟孙才，其母死，哭泣无涕，中心不戚，居丧不哀。无是三者，以善处丧盖鲁国。固有无其实而得其名者乎？回壹怪之。」仲尼曰：「夫孟孙氏尽之矣，进于知矣。唯简之而不得，夫已有所简矣。孟孙氏不知所以生，不知所以死；不知就先，不知就后；若…","q":[]},{"n":"十哲","d":"","s":"《旧唐书》卷二十四〈礼仪志四〉～99～","w":"初，开元八年，国子司业李元瓘奏称：「先圣孔宣父庙，先师颜子配座，今其像立侍，配享合坐。十哲弟子，虽复列像庙堂，不预享祀。谨检祠令：何休、范宁等二十二贤，犹沾从祀，望请春秋释奠，列享在二十二贤之上。七十子，请准旧都监堂图形于壁，兼为立赞，庶敦…","q":[]},{"n":"拾尘","d":"","s":"《吕氏春秋·览部》卷十七〈审分览·任数〉～066～","w":"孔子穷乎陈、蔡之间，藜羹不斟，七日不尝粒，昼寝。颜回索米，得而爨之，几熟。孔子望见颜回攫其甑中而食之。选间，食熟，谒孔子而进食。孔子佯为不见之。孔子起曰：「今者梦见先君，食洁而后馈。」颜回对曰：「不可。向者煤室入甑中，弃食不祥，回攫而饭之。…","q":[["拾尘掇蜂，疑圣猜贤。","李白 雪谗诗赠友人"],["机事齐飘瓦，嫌猜比拾尘。","柳宗元 酬娄秀才将之淮南所赠之升"]]},{"n":"吴练","d":"","s":"《论衡》卷四《书虚》","w":"孔子东南望，吴阊门外有系白马，引颜渊指以示之，曰：「若见吴昌门乎？」颜渊曰：「见之。」孔子曰：「门外何有？」曰：「有如系练之状。」","q":[["吴练已知随影没，朔风犹想带嘶闻。","刘威 伤曾秀才马"]]},{"n":"颜闵","d":"","s":"《论语·先进》","w":"德行：颜渊、闵子骞、冉伯牛、仲弓。……子曰：「孝哉闵子骞！人不间于其父母昆弟之言。」","q":[["儒风久沦弊，颜闵寿不长。","刘商 哭韩淮端公兼上崔中丞"],["羁离交屈宋，牢落值颜闵。","杜甫 赠郑十八贲"]]},{"n":"子渊","d":"","s":"《史记》卷六十七〈仲尼弟子列传〉～287～","w":"颜回者，鲁人也，字子渊。少孔子三十岁。颜渊问仁，孔子曰：「克己复礼，天下归仁焉。」孔子曰：「贤哉回也！一箪食，一瓢饮，在陋巷，人不堪其忧，回也不改其乐。」「回也如愚；退而省其私，亦足以发，回也不愚。」「用之则行，舍之则藏，唯我与尔有是夫！」","q":[["子渊将叔度，自古不得已。","权德舆 哭李晦群崔季文二处士"]]},{"n":"颜曾","d":"","s":"词典","w":"孔子弟子颜回和曾参并称。","q":[]}],"59":[{"n":"很石","d":"","s":"《苕溪渔隐丛话》前集卷二十四引〈蔡宽夫诗话〉","w":"润州甘露寺有块石，状如伏羊，形制略具，号很石。相传孙权尝据其上，与刘备论曹公。壁间旧有罗隐诗板云：「紫髯桑盖两沉吟，很石空存事莫寻。","q":[]},{"n":"池中物","d":"","s":"《三国志》卷五十四《吴书·周瑜传》","w":"权拜瑜偏将军，领南郡太守。以下隽、汉昌、刘阳、州陵为奉邑，屯据江陵。刘备以左将军领荆州牧，治公安。备诣京见权，瑜上疏曰：「刘备以枭雄之姿，而有关羽、张飞熊虎之将，必非久屈为人用者。愚谓大计宜徙备置吴，盛为筑宫室，多其美女玩好，以娱其耳目，分…","q":[["吾子得神仙，本是池中物。","杜甫 七月三日亭午已后较热退晚加小凉稳睡有诗因论壮年乐事戏呈元二十一曹长"],["岂是池中物，由来席上珍。","杜甫 上韦左相二十韵（见素。天宝元年。改侍中为左相。中书令为右相。十五载。见素从明皇幸蜀。至巴西。诏兼左相。封豳国公。）"]]},{"n":"周瑜破曹","d":"","s":"《三国志》卷四十七〈吴书·吴主权〉～7～","w":"「备进住夏口，使诸葛亮诣权，权遣周瑜、程普等行。是时曹公新得表众，形势甚盛，诸议者皆望风畏惧，多劝权迎之。惟瑜、肃执拒之议，意与权同。瑜、普为左右督，各领万人，与备俱进，遇于赤壁，大破曹公军。公烧其馀船引退，士卒饥疫，死者大半。」","q":[["赤壁争雄如梦里，且须歌舞宽离忧。","李白 江夏赠韦南陵冰"],["烈火张天照云海，周瑜于此破曹公。","李白 赤壁歌送别"]]},{"n":"赤壁楼船","d":"","s":"《三国志》卷四十七〈吴书·吴主权传〉～7～","w":"三年春，权复征黄祖，祖先遣舟兵拒军，都尉吕蒙破其前锋，而淩统、董袭等尽锐攻之，遂屠其城。祖挺身亡走，骑士冯则追枭其首，虏其男女数万口。是岁，使贺齐讨黟、歙，黟音伊。歙音摄。分歙为始新、新定、犁阳、休阳县，以六县为新都郡。荆州牧刘表死，鲁肃乞…","q":[]},{"n":"赤马","d":"","s":"晋·崔豹《古今注》卷下《杂注》","w":"「孙权名舸为赤马，言其飞驰如马之走陆也。」","q":[["楚竹青阳路，吴江赤马船。","韩翃 赠别韦兵曹归池州"],["青牛游华岳，赤马走吴宫。","骆宾王 秋日钱陆道士陈文林"]]},{"n":"公安问曹瞒","d":"","s":"《三国志》卷三十二〈蜀书·先主备传〉～878～","w":"先主遣诸葛亮自结于孙权，权遣周瑜、程普等水军数万，与先主并力，与曹公战于赤壁，大破之，焚其舟船。先主与吴军水陆并进，追到南郡，时又疾疫，北军多死，曹公引归。先主表琦为荆州刺史，又南征四郡。武陵太守金旋、长沙太守韩玄、桂阳太守赵范、零陵太守刘…","q":[]},{"n":"火烧赤壁","d":"","s":"《三国志》卷五十四〈吴书·周瑜传〉～262～","w":"时刘备为曹公所破，欲引南渡江，与鲁肃遇于当阳，遂共图计，因进住夏口，遣诸葛亮诣权，权遂遣瑜及程普等与备并力逆曹公，遇于赤壁。时曹公军众已有疾病，初一交战，公军败退，引次江北。瑜等在南岸。瑜部将黄盖曰：「今寇众我寡，难与持久。然观操军船舰首尾…","q":[]},{"n":"金陵王气","d":"","s":"《三国志》卷五十三《吴书·张纮传》","w":"「纮建计宜出都秣陵，权从之。」南朝宋·裴松之注引《江表传》曰：「纮谓权曰：『秣陵，楚武王所置，名为金陵。地势冈阜连石头，访问故老，云昔秦始皇东巡会稽经此县，望气者云金陵地形有王者都邑之气，故掘断连冈，改名秣陵。今处所具存，地有其气，天之所命…","q":[["东南天子气，扫地入函京。","李群玉 石头城"],["龙虎势衰佳气歇，凤皇名在故台空。","李群玉 秣陵怀古"]]},{"n":"生子当如孙仲谋","d":"","s":"《三国志》卷四十七〈吴书·吴主权传〉～8～","w":"十八年正月，曹公攻濡须，权与相拒月馀。曹公望权军，叹其齐肃，乃退。初，曹公恐江滨郡县为权所略，徵令内移。民转相惊，自庐江、九江、蕲春、广陵户十馀万皆东渡江，江西遂虚，合肥以南惟有皖城。南朝宋·裴松之注引《吴历》曰：「曹公出濡须，作油船，夜渡…","q":[]},{"n":"如刻画","d":"","s":"《汉书》卷六十九《赵充国传》","w":"「赵充国字翁孙，陇西上邽人也。」「武帝时，以假司马从贰师将军击匈奴，大为虏所围。汉军乏食数日，死伤者多，充国乃与壮士百馀人溃围陷陈，贰师引兵随之，遂得解。身被二十馀创，贰师奏状，诏徵充国诣行在所。武帝亲见视其创，嗟叹之，拜为中郎，迁车骑将军…","q":[["唯有老身如刻画，犹期圣主解衣看。","李端 题故将军庄"]]},{"n":"识吕蒙","d":"","s":"《三国志》卷四十七《吴书·吴主传》","w":"遣都尉赵咨使魏。魏帝问曰：「吴王何等主也？」咨对曰：「聪明仁智，雄略之主也。」帝问其状，咨曰：「纳鲁肃于凡品，是其聪也；拔吕蒙于行陈，是其明也；获于禁而不害，是其仁也；取荆州而兵不血刃，是其智也；据三州虎视于天下，是其雄也；屈身于陛下，是其…","q":[["军事留孙楚，行间识吕蒙。","杜甫 投赠哥舒开府二十韵"]]},{"n":"孙刘","d":"","s":"《南史》卷五十三〈梁武帝诸子列传·武陵王纪〉～328～","w":"初，天监中，震太阳门，成字曰：「绍宗梁位唯武王。」解者以武陵王当之，于是朝野属意焉。及侯景陷台城，上甲侯韶西上至硖，出武帝密敕，加纪侍中、假黄钺、都督征讨诸军事、骠骑大将军、太尉、承制。大宝元年六月辛酉，纪乃移告诸州征镇，遣世子圆照领二蜀精…","q":[]},{"n":"万人英","d":"","s":"《毛诗正义》卷五之三〈国风·魏风·汾沮洳〉～207～","w":"彼汾沮洳，言采其莫。彼其之子，美无度；美无度，殊异乎公路。彼汾一方，言采其桑。彼其之子，美如英；美如英，殊异乎公行。彼汾一曲，言采其藚。彼其之子，美如玉；美如玉，殊异乎公族。 唐·孔颖达疏：「《礼运注》云：『英，俊选之尤者。』则英是贤才绝异…","q":[]},{"n":"伊籍一拜","d":"","s":"《三国志》卷三十八《蜀书·伊籍传》","w":"伊籍字机伯，山阳人。少依邑人镇南将军刘表。先主之在荆州，籍常往来自托。表卒，遂随先主南渡江，从入益州。益州既定，以籍为左将军从事中郎，见待亚于简雍、孙乾等。遣东使于吴，孙权闻其才辩，欲逆折以辞。籍适入拜，权曰：「劳事无道之君乎？」籍既对曰：…","q":[["伊籍一拜，郦生长揖。","李瀚 蒙求"],["莫问伊嵇懒，流年已付他。","齐己 渚宫莫问诗一十五首"]]},{"n":"紫髯将","d":"","s":"《三国志》卷四十七《吴书·孙权传》","w":"「权乘骏马越津桥得去。」南朝宋·裴松之注引《献帝春秋》曰：「张辽问吴降人：『向有紫髯将军，长上短下，便马善射，是谁？』降人答曰：『是孙会稽。』辽及乐进相遇，言不早知之，急追自得，举军叹恨。」","q":[["若比紫髯分鼎足，未闻馀力有琼瑰。","罗隐 春日投钱塘元帅尚父二首之一"],["紫髯桑盖此沈吟，很石犹存事可寻。","罗隐 题润州妙善前石羊"]]}],"60":[{"n":"班马香","d":"","s":"杜牧《冬至日寄小侄阿宜诗》","w":"高摘屈宋艳，浓薰班马香。","q":[]},{"n":"班马","d":"","s":"《晋书》卷八十二《陈寿等传论》","w":"丘明既没，班马迭兴，奋鸿笔于西京，骋直词于东观。","q":[["高摘屈宋艳，浓薰班马香。","杜牧 冬至日寄小侄阿宜诗"],["绮园难贮林栖意，班马须持笔削权。","黄滔 遇罗员外衮"]]},{"n":"马迁下蚕室","d":"","s":"《汉书》卷六十二〈司马迁列传〉～2729～","w":"夫仆与李陵俱居门下，素非相善也，趣舍异路，未尝衔杯酒接殷勤之欢。然仆观其为人自奇士，事亲孝，与士信，临财廉，取予义，分别有让，恭俭下人，常思奋不顾身以徇国家之急。其素所畜积也，仆以为有国士之风。夫人臣出万死不顾一生之计，赴公家之难，斯已奇矣…","q":[["马迁下蚕室，嵇康就囹圄。","白居易 读史五首"],["都尉身降虏，宫刑加子长。","白居易 杂感"]]},{"n":"刺客传","d":"","s":"《史记》卷一三○《太史公自序》","w":"曹子匕首，鲁获其田，齐明其信；豫让义不为二心。作《刺客列传》第二十六。","q":[["何惭刺客传，不著报雠名。","韩愈 学诸进士作精卫衔石填海诗"]]},{"n":"画地难入","d":"","s":"《汉书》卷六十二〈司马迁列传〉～2732～","w":"司马迁〈报任安书〉：「故士有画地为牢势不入，削木为吏议不对，定计于鲜也。」","q":[["画地终难入，书空自不安。","骆宾王 畴昔篇"]]},{"n":"九回肠","d":"","s":"《汉书》卷六十二〈司马迁列传〉～2736～","w":"司马迁〈报任安书〉：「是以肠一日而九回，居则忽忽若有所亡，出则不知所如往。每念斯耻，汗未尝不发背沾衣也。」","q":[["画桥春煖清歌夜，肯信愁肠日九回。","崔橹 春日即事"],["中夜恨火来，焚烧九回肠。","李群玉 自澧浦东游江表途出巴丘投员外从公虞"]]},{"n":"九牛一毛","d":"","s":"《汉书》卷六十二《司马迁传》","w":"司马迁答任安书曰：假令仆伏法受诛，若九牛亡一毛，与蝼蚁何异！","q":[["独鹤初冲太虚日，九牛新落一毛时。","杜牧 洛中监察病假满送韦楚老拾遗归朝"],["权门众所趋，有客动百千。九牛亡一毛，未在多少间。","韩愈 庭楸"]]},{"n":"良史迁","d":"","s":"《汉书》卷六十二《司马迁传》","w":"迁生龙门，耕牧河山之阳。年十岁则诵古文。二十而南游江淮，上会稽，探禹穴，窥九疑，浮沅湘。北涉汶泗，讲业齐鲁之都，观夫子遗风，乡射邹峄；隘困蕃、薛、彭城，过梁楚以归。于是迁仕为郎中，奉使西征巴蜀以南，略邛、笮、昆明，还报命。……卒三岁，而迁为…","q":[["大名将起魏，良史更逢迁。","孙逖 冬末送魏起居赴京"]]},{"n":"马迁树立轻","d":"","s":"《汉书》卷六十二〈司马迁列传〉～2732～","w":"倡优畜之，流俗之所轻也。假令仆伏法受诛，若九牛亡一毛，与蝼蚁何异？而世又不与能死节者比，特以为智穷罪极，不能自免，卒就死耳。何也？素所自树立使然。","q":[["悼伤潘岳重，树立马迁轻。","李商隐 五言述德抒情诗一首四十韵献上杜七兄仆射相公"]]},{"n":"牛马走","d":"","s":"《昭明文选》卷四十一汉·司马子长（迁）《报任少卿书》","w":"「太史公牛马走司马迁再拜言，少卿足下：曩者辱赐书，教以顺于接物，推贤进士为务。」唐·李善注：「走，犹仆也。言己为太史公掌牛马之仆，自谦之辞也。」","q":[["自怜牛马走，未识犬羊心。","李宣远 近无西耗"]]},{"n":"迁固","d":"","s":"《南齐书》卷五十二《文学传·崔慰祖传》","w":"与从弟纬书云：「常欲更注迁、固二史，采史、汉所漏二百馀事，在厨簏，可检写之，以存大意。」","q":[["入掌迁固笔，出参枚马词。","崔湜 景龙二年余自门下平章事削阶授江州员外司马寻拜襄州刺史春日赴襄阳途中言志"]]},{"n":"学贯天人际","d":"","s":"《汉书》卷六十二〈司马迁列传〉～2735～","w":"司马迁《报任安书》：……仆窃不逊，近自托于无能之辞，网罗天下放失旧闻，考之行事，稽其成败兴坏之理，凡百三十篇，亦欲以究天人之际，通古今之变，成一家之言。草创未就，适会此祸，惜其不成，是以就极刑而无愠色。仆诚已著此书，藏之名山，传之其人通邑大…","q":[["网罗穷象系，述作究天人。","刘升 奉和圣制送张说上集贤学士赐宴"],["著论穷天人，千春秘麟阁。","李白 赠参寥子"]]},{"n":"留滞周南","d":"","s":"《史记》卷一三○《太史公自序》","w":"「是岁天子始建汉家之封，而太史公留滞周南，不得与从事，故发愤且卒。」唐·司马贞《史记索隐》：「张晏注：「自陕已东，皆周南之地也。」","q":[["尉佗虽北拜，太史尚南留。","杜甫 奉送王信州崟北归"],["周南留滞古所惜，南极老人应寿昌。","杜甫 寄韩谏议"]]},{"n":"摇尾","d":"","s":"《汉书》卷六十二《司马迁传》","w":"迁既被刑之后，为中书令，尊宠任职。故人益州刺史任安予迁书，责以古贤臣之义。迁报之曰：……猛虎处深山，百兽震恐，及其在阱槛之中，摇尾而求食，积威约之渐也。","q":[["客道耻摇尾，皇恩宽犯鳞。","杜牧 宣城赠萧兵曲"],["处困羞摇尾，怀忠壮犯鳞。","杜牧 梁秀才以早春旅次大梁将归郊扉言怀兼别示亦蒙见赠凡二十韵走笔依韵"]]},{"n":"执鞭","d":"","s":"《史记》卷六十二《管晏传赞》","w":"「假令晏子而在，余虽为之执鞭，所欣慕焉。」唐·司马贞《史记索隐》：「太史公之羡慕仰企平仲之行，假令晏生在世，己虽与之为仆隶，为之执鞭，亦所欣慕。其好贤乐善如此。贤哉良史，可以示人臣之炯戒也。」","q":[["讲序居重席，群儒愿执鞭。","张籍 赠殷山人"],["陆公馀德机云在，如我酬恩合执鞭。","杜牧 怀钟陵旧游四首之一"]]}],"61":[{"n":"八公","d":"","s":"《史记》卷一百一十八〈淮南衡山列传〉～3082～","w":"淮南王安为人好读书鼓琴，不喜弋猎狗马驰骋，亦欲以行阴德拊循百姓，流誉天下。时时怨望厉王死，时欲畔逆，未有因也。及建元二年，淮南王入朝。素善武安侯，武安侯时为太尉，乃逆王霸上，与王语曰：「方今上无太子，大王亲高皇帝孙，行仁义，天下莫不闻。即宫…","q":[["八公携手五云去，空馀桂树愁杀人。","李白 白毫子歌"],["菱歌五湖远，桂树八公邻。","李颀 送乔琳"]]},{"n":"云中鸡犬","d":"云中鸡犬：喻仙家生活。唐罗隐（广陵开元寺阁上作》：“云中鸡犬刘安过，月里留歌扬帝归。”","s":"《论衡校释》卷七〈道虚〉～37～","w":"儒书言：淮南王学道，招会天下有道之人。倾一国之尊，下道术之士，是以道术之士，并会淮南，奇方异术，莫不争出。王遂得道，举家升天。畜产皆仙，犬吠于天上，鸡鸣于云中。此言仙药有馀，犬鸡食之，并随王而升天也。","q":[["鸡犬疑沾药，耕桑似避秦。","储嗣宗 春游望仙谷"],["犬入五云音信绝，凤楼凝碧悄无声。","储嗣宗 胡山"]]},{"n":"小山丛桂","d":"","s":"《楚辞补注》卷十二〈招隐士〉～232～","w":"〈招隐士〉者，淮南小山之所作也。昔淮南王安，博雅好古，招怀天下俊伟之士。自八公之徒，咸慕其德，而归其仁，各竭才智，著作篇章，分造辞赋，以类相从，故或称小山，或称大山。其义犹《诗》有〈小雅〉、〈大雅〉也。小山之徒，闵伤屈原，又怪其文升天乘云，…","q":[["淮南有小山，嬴女隐其间。","张昌宗 太平公主山亭侍宴"],["既荷大君恩，还蒙小山遇。","张说 修书院学士奉敕宴梁王宅赋得树字"]]},{"n":"都厕处刘安","d":"","s":"《太平广记》卷八〈神仙八·刘安〉～53～","w":"《吴记具说》云：安未得上天，遇诸仙伯，安少习尊贵，稀为卑下之礼，坐起不恭，语声高亮，或误称「寡人」。于是仙伯主者奏安云：不敬，应斥遣去。八公为之谢过，乃见赦，谪守都厕三年。后为散仙人，不得处职，但得不死而已。","q":[]},{"n":"麋鹿游","d":"","s":"《史记》卷一百一十八〈淮南衡山列传〉～3085～","w":"王坐东宫，召伍被与谋，曰：「将军上。」被怅然曰：「上宽赦大王，王复安得此亡国之语乎！臣闻子胥谏吴王，吴王不用，乃曰：『臣今见麋鹿游姑苏之台也。』今臣亦见宫中生荆棘，露沾衣也。」","q":[["可怜荒堞晚冥濛，麋鹿呦呦达遗址。","刘商 姑苏怀古送秀才下第归江南"],["桑田东海变，麋鹿姑苏游。","张九龄 经江宁览旧迹至玄武湖"]]},{"n":"鸿宝","d":"","s":"《汉书》卷三十六《楚元王传》附《刘向传》","w":"「上复兴神仙方术之事，而淮南有《枕中鸿宝》《苑秘书》。」唐·颜师古注：「《鸿宝》《苑秘书》，并道术篇名。臧在枕中，言常存录之不漏泄也。」","q":[["鸿宝宁全秘，丹梯庶可凌。","杜甫 赠特进汝阳王二十韵"],["方外留鸿宝，人间得善书。","权德舆 赠文敬太子挽歌词二首之二"]]},{"n":"淮南药","d":"","s":"《汉书》卷四十四《淮南王传》","w":"淮南王安为人好书，鼓琴，不喜弋猎狗马驰骋，亦欲以行阴德拊循百姓，流名誉。招致宾客方术之士数千人，作为《内书》二十一篇，《外书》甚众，又有《中篇》八卷，言神仙黄白之术，亦二十馀万言。……上使宗正以符节治王。未至，安自刑杀。","q":[["漫作琉璃碗，淮王误合丹。","岑参 成王挽砍"],["汉主存仙要，淮南爱道机。","崔融 和梁王众传张光禄是王子晋后身"]]},{"n":"淮南食时","d":"","s":"《汉书》卷四十四《淮南王传》","w":"淮南王安为人好读书鼓琴，不喜弋猎狗马驰骋，亦欲以行阴德拊循百姓，流誉天下。……时武帝方好艺文，以安属为诸父，辩博善为文辞，甚尊重之。每为报书及赐，常召司马相如等视草乃遣。初，安入朝，献所作内篇，新出，上爱秘之。使为《离骚传》，旦受诏，日食时…","q":[["淮南食时，左思十稔。","李瀚 蒙求"]]},{"n":"大小山","d":"","s":"《楚辞》汉·淮南小山《招隐士》","w":"东汉·王逸《序》：《招隐士》者，淮南小山之所作也。昔淮南王安，博雅好古，招怀天下俊伟之士。自八公之徒，咸慕其德，而归其仁，各竭才智，著作篇章，分造辞赋，以类相从，故或称小山，或称大山。其义犹《诗》有《小雅》、《大雅》也。小山之徒，闵伤屈原，…","q":[["望高汉相东西阁，名重淮王大小山。","罗隐 暇日投钱尚父"]]},{"n":"淮王客","d":"","s":"晋·葛洪《神仙传》卷四《刘安》","w":"汉淮南王刘安者，汉高帝之孙也。其父厉王长，得罪徙蜀，道死，文帝哀之，而裂其地，尽以封长子，故安得封淮南王。时诸王子贵侈，莫不以声色游猎犬马为事，唯安独折节下士，笃好儒学，兼占候方术，养士数千人，皆天下俊士。作内书二十二篇，又中篇八章，言神仙…","q":[["淮王门有客，终不愧孙登。","杜甫 赠特进汝阳王二十韵"]]},{"n":"淮王身死","d":"","s":"《史记》卷一一八《淮南衡山列传》","w":"天子使宗正以符节治王。未至，淮南王安自刭杀。","q":[["淮王身死桂树折，徐福一去音书绝。","顾况 行路难三首之三"]]},{"n":"刘安","d":"","s":"晋·崔豹《古今注》卷中《音乐》","w":"「淮南王服食求仙，遍礼方士。遂与方士相携俱去，莫知所往。小山之徒，思恋不已，乃作《淮南王》曲焉。」","q":[["何曾见天上，著得刘安宅。","刘叉 自古无长生劝姚合酒（一本作劝杨勉酒）"],["万卷仙经三尺琴，刘安闻说是知音。","吕严 七言"]]},{"n":"刘安仙籍","d":"","s":"《神仙传》卷六〈淮南王〉","w":"淮南王安，好神仙之道。海内方士从其游者多矣。一旦，有八公诣之，容状衰老，枯槁伛偻，阍者谓之曰：「王之所好，神仙度世长生久视之道，必须有异于人，王乃礼接，今公衰老如此，非王所宜见也。」拒之数四，公求见不已，阍者对如初。八公曰：「王以我衰老不欲…","q":[]},{"n":"枕中术","d":"","s":"《汉书》卷三十六《楚王元传》附《刘向传》","w":"「上复兴神仙方术之事，而淮南有《枕中鸿宝》、《苑秘书》，书言神仙使鬼物为金之术。」唐·颜师古注：「《鸿宝》、《苑秘书》，并道术篇名，藏在枕中，言常存录之，不漏泄也。」","q":[["仍闻枕中术，曾授汉淮王。","于鹄 题服柏先生"],["枕中经妙谁传与，肘后方新自写将。","周渭 赠龙兴观主吴崇岳"]]}],"62":[{"n":"咄石生","d":"","s":"《晋书》卷四十三《山涛传》","w":"山涛字巨源，河内怀人也。……举孝廉，州辟部河南从事。与石鉴共宿，涛夜起蹴鉴曰：「今为何等时而眠邪！知太傅卧何意？」鉴曰：「宰相三不朝，与尺一令归第，卿何虑也！」涛曰：「咄！石生无事马蹄间邪！」投传而去。未二年，果有曹爽之事，遂隐身不交世务。","q":[["巨源咄石生，何事马蹄间。","李白 送赵判官赴黔府中丞叔幕"]]},{"n":"山公启事","d":"山公启事：喻知人能鉴，荐才举贤。唐李商隐《赠宇文中丞》：“人间只有嵇延祖，最望山公启事来。”","s":"《晋书》卷四十三〈山涛列传〉～225～","w":"涛再居选职十有馀年，每一官缺，辄启拟数人，诏旨有所向，然后显奏，随帝意所欲为先。故帝之所用，或非举首，众情不察，以涛轻重任意。或谮之于帝，故帝手诏戒涛曰：「夫用人惟才，不遗疏远单贱，天下便化矣。」而涛行之自若，一年之后众情乃寝。涛所奏甄拔人…","q":[["山公启事罢，吉甫颂声传。","张九龄 奉和吏部崔尚书雨后大明朝堂望南山"],["本谓山公启，而今殁始扬。","张九龄 故徐州刺史赠吏部侍郎苏公挽歌词三首"]]},{"n":"山嵇","d":"","s":"《晋书》卷四十三〈山涛列传〉～223～","w":"山涛字巨源，河内怀人也。父曜，宛句令。涛早孤，居贫，少有器量，介然不群。性好庄老，每隐身自晦。与嵇康、吕安善，后遇阮籍，便为竹林之交，著忘言之契。康后坐事，临诛，谓子绍曰：「巨源在，汝不孤矣。」","q":[["范云堪晚友，嵇绍自不孤。","杜甫 别张十三建封"],["张老存家事，嵇康有故人。","杜甫 奉赠萧二十使君"]]},{"n":"嵇氏幼男","d":"","s":"《昭明文选》卷四十三、三国魏·嵇叔夜（康）《与山巨源绝交书》","w":"吾新失母兄之欢，意常悽切，女年十三，男年八岁，未及成人，况复多病，顾此悢悢，如何可言！","q":[["嵇氏幼男犹可悯，左家娇女岂能忘。","李商隐 王十二兄与畏之员外相访见招小饮时予以悼亡日近不去因寄"]]},{"n":"嵇延祖","d":"","s":"《晋书》卷八十九《忠义传·嵇绍传》","w":"嵇绍字延祖，魏中散大夫康之子也。十岁而孤，事母孝谨。以父得罪，靖居私门。山涛领选，启武帝曰：「康诰有言：『父子罪不相及。』嵇绍贤侔郤缺，宜加旌命，请为秘书郎。」帝谓涛曰：「如卿所言，乃堪为丞，何但郎也。」乃发诏徵之，起家为秘书丞。","q":[["人间只有嵇延祖，最望山公启事来。","李商隐 赠宇文中丞"],["山公访嵇绍，赵武见韩侯。","李端 送诸暨裴少府"]]},{"n":"竹林七贤","d":"七贤：喻指文人放荡不羁，或指独立于世俗之外，或喻朋友的交情深厚。唐卢纶《秋夜同畅当宿潭上西亭》：“圆月出山头，七贤林下游。”","s":"《三国志》卷二十一〈魏书·王粲传·嵇康〉～605～","w":"时又有谯郡嵇康，文辞壮丽，好言老、庄，而尚奇任侠。至景元中，坐事诛。南朝宋·裴松之注引《魏氏春秋》曰：「康寓居河内之山阳县，与之游者，未尝见其喜愠之色。与陈留阮籍、河内山涛、河南向秀、籍兄子咸、琅邪王戎、沛人刘伶相与友善，游于竹林，号为七贤…","q":[["东篱摘芳菊，想见竹林游。","储光羲 仲夏饯魏四河北觐叔"],["超超青云器，婉婉竹林会。","储光羲 奉和韦判官献侍郎叔除河东采访使"]]},{"n":"酒困山涛","d":"","s":"《晋书》卷四十三〈山涛列传〉～228～","w":"涛饮酒至八斗方醉，帝欲试之，乃以酒八斗饮涛，而密益其酒，涛极本量而止。","q":[]},{"n":"绝交书","d":"","s":"《世说新语笺疏》下卷上〈栖逸〉～652～","w":"山公将去选曹，欲举嵇康；康与书告绝。南朝梁·刘孝标注引《嵇康别传》曰：「山巨源为吏部郎，迁散骑常侍，举康，康辞之，并与山绝。岂不识山之不以一官遇己情邪？亦欲标不屈之节，以杜举者之口耳！乃荅涛书，自说不堪流俗，而非薄汤武。大将军闻而恶之。」","q":[["况观绝交书，兼睹箴隐文。","吴筠 舟中遇柳伯存归潜山因有此赠"],["知道故人相忆否，嵇康不得懒修书。","徐铉 寄江都路员外"]]},{"n":"吏部访孤儿","d":"","s":"《世说新语》上卷下《政事》","w":"「嵇康被诛后，山公举康子为秘书丞。」","q":[["独闻山吏部，流涕访孤儿。","刘长卿 哭张员外继（公及夫人相次没于洪州）"]]},{"n":"论懒","d":"","s":"《昭明文选》卷四十三、三国魏·嵇叔夜（康）《与山巨源绝交书》","w":"「少加孤露，母兄见骄，不涉经学。性复疏懒，筋驽肉缓，头面常一月十五日不洗，不大闷痒，不能沐也。每常小便，而忍不起，令胞中略转乃起耳。」","q":[["何处同嵇懒，吾徒道异诸。","齐己 拟嵇康绝交寄湘中贯微康"],["莫学嵇康懒，且安原宪贫。","王维 山中示弟"]]},{"n":"宁馨儿","d":"","s":"《晋书》卷四十三〈王戎列传·（从弟）王衍〉～235～","w":"衍字夷甫，神情明秀，风姿详雅。总角尝造山涛，涛嗟叹良久，既去，目而送之曰：「何物老妪，生宁馨儿！然误天下苍生者，未必非此人也。」","q":[]},{"n":"山巨源书","d":"","s":"《昭明文选》卷四十三〈书下·与山巨源绝交书〉～923～","w":"唐·李善注引《魏氏春秋》曰：「山涛为选曹郎，举康自代。康答书拒绝，因自说不堪流俗，而非薄汤、武。大将军闻而恶焉。」","q":[]},{"n":"山吏部","d":"","s":"《晋书》卷四十三《山涛传》","w":"山涛字巨源，河内怀人也。……与宣穆后有中表亲，是以见景帝。帝曰：「吕望欲仕邪？」命司隶举秀才，除郎中。转骠骑将军王昶从事中郎。久之，拜赵国相，迁尚书吏部郎。……及羊祜执政，时人欲危裴秀，涛正色保持之。由是失权臣意，出为冀州刺史，加宁远将军。…","q":[["仙翁昨日事，应见此时情。","刘太真 贡院寄前主司萧尚书听"],["香名冠二陆，精鉴逢山涛。","刘长卿 客舍赠别韦九建赴任河南韦十七造赴任郑县就便觐省"]]},{"n":"中散诗","d":"","s":"《诗品》卷中","w":"晋中散嵇康诗，颇似魏文，过为峻切，讦直露才，伤渊雅之致。然托谕清远，良有鉴裁，亦未失高流矣。","q":[["中散诗传画，将军扇续书。","司空曙 送曹同椅"]]}],"63":[{"n":"射斗牛","d":"丰城气：喻有声誉。才华。唐杨炯《和刘长庄答十九兄》：“宝剑丰城气、明珠魏国珍。”；丰城龙剑：指宝剑，或喻出类拔革之人及华美宝贵之物。金元好问《赠答平阳仇舜臣》：“沧海骊珠能几见，丰城龙剑不终藏。”","s":"《晋书》卷三十六〈张华列传〉～075～","w":"初，吴之未灭也，斗牛之间常有紫气，道术者皆以吴方强盛，未可图也，惟华以为不然。及吴平之后，紫气愈明。华闻豫章人雷焕妙达纬象，乃要焕宿，屏人曰：「可共寻天文，知将来吉凶。」因登楼仰观。焕曰：「仆察之久矣，惟斗牛之间颇有异气。」华曰：「是何祥也…","q":[["负户愁读书，剑光忿冲斗。","储光羲 狱中贻姚张薛李郑柳诸公"],["牛斗之气，蓄于昆溪。","元希声 赠皇甫侍御赴都八首"]]},{"n":"坼中台","d":"","s":"《晋书》卷三十六〈张华列传〉～074～","w":"初，华所封壮武郡有桑化为柏，识者以为不祥。又华第舍及监省数有妖怪。少子韪以中台星坼，劝华逊位。华不从，曰：「天道玄远，惟修德以应之耳。不如静以待之，以俟天命。」及伦、秀将废贾后，秀使司马雅夜告华曰：「今社稷将危，赵王欲与公共匡朝廷，为霸者之…","q":[["自从星坼中台后，化作双龙去不归。","李群玉 宝剑"],["星坼台衡地，曾为人所怜。","杜甫 奉送苏州李二十五长史丈之任"]]},{"n":"广武庐","d":"","s":"《昭明文选》卷二十四〈诗丙·赠答二·赠张华〉～35～","w":"四时更代谢，悬象迭卷舒。暮春忽复来，和风与节俱。俯临清泉涌，仰观嘉木敷。周旋我陋圃，西瞻广武庐。既贵不忘俭，处有能存无。镇俗在简约，树塞焉足摹。在昔同班司，今者并园墟。私愿偕黄发，逍遥综琴书。举爵茂阴下，携手共踌躇。奚用遗形骸，忘筌在得鱼。…","q":[["高阁安仁省，名园广武庐。","郑絪 奉和武相公省中宿斋酬李相公见寄"]]},{"n":"豪气张华","d":"","s":"《晋书》卷三十六〈张华列传〉～068～","w":"张华字茂先，范阳方城人也。父平，魏渔阳郡守。华少孤贫，自牧羊，同郡卢钦见而器之。乡人刘放亦奇其才，以女妻焉。华学业优博，辞藻温丽，朗赡多通，图纬方伎之书莫不详览。少自修谨，造次必以礼度。勇于赴义，笃于周急。器识弘旷，时人罕能测之。……华性好…","q":[]},{"n":"士龙笑","d":"","s":"《晋书》卷五十四〈陆云列传〉～48～","w":"云字士龙，六岁能属文，性清正，有才理。少与兄机齐名，虽文章不及机，而持论过之，号曰「二陆」。幼时吴尚书广陵闵鸿见而奇之，曰：「此儿若非龙驹，当是凤雏。」后举云贤良，时年十六……吴平，入洛。机初诣张华，华问云何在。机曰：「云有笑疾，未敢自见。…","q":[["谁惮士龙多笑疾，美髭终类晋司空。","李商隐 奉和太原公送前杨秀才戴兼招杨正字戎"]]},{"n":"龙跳","d":"","s":"《晋书》卷九十二〈文苑列传·褚陶〉～238～","w":"州郡辟，不就。吴平，召补尚书郎。张华见之，谓陆机曰：「君兄弟龙跃云津，顾彦先凤鸣朝阳，谓东南之宝已尽，不意复见褚生。」机曰：「公但未睹不鸣不跃者耳。」华曰：「故知延州之德不孤，川岳之宝不匮矣。」迁九真太守，转中尉。年五十五卒。","q":[]},{"n":"茂先博物","d":"","s":"《晋书》卷三十六《张华传》","w":"张华字茂先，范阳方城人也。父平，魏渔阳郡守。华少孤贫，自牧羊，同郡卢钦见而器之。乡人刘放亦奇其才，以女妻焉。华学业优博，辞藻温丽，朗赡多通，图纬方伎之书莫不详览。少自修谨，造次必以礼度。勇于赴义，笃于周急。器识弘旷，时人罕能测之。……华著博…","q":[["佐命留侯业，词华博物才。","李皓 奉和圣制送张说上集贤学士赐宴"],["茂先惭博物，平子谢文章。","李隆基 送张说巡边"]]},{"n":"茂先王佐","d":"","s":"《晋书》卷三十六《张华传》","w":"张华字茂先，范阳方城人也。父平，魏渔阳郡守。华少孤贫，自牧羊，同郡卢钦见而器之。乡人刘放亦奇其才，以女妻焉。华学业优博，辞藻温丽，朗赡多通，图纬方伎之书莫不详览。少自修谨，造次必以礼度。勇于赴义，笃于周急。器识弘旷，时人罕能测之。初未知名，…","q":[["茂先实王佐，仲举信时英。","裴耀卿 敬酬张九龄当涂界留赠之作"]]},{"n":"茂先知味","d":"","s":"晋·张华《博物志》","w":"樱桃者或如弹丸，或如手指。春秋冬夏，华实竟岁。（据《博物志校證》附录引）","q":[["茂先知味易，曼倩恨偷难。","权德舆 酬裴杰秀才新樱桃"]]},{"n":"张华识","d":"","s":"《晋书》卷三十六《张华传》","w":"华性好人物，诱进不倦，至于穷贱候门之士有一介之善者，便咨嗟称咏，为之延誉。","q":[["自知终有张华识，不向沧洲理钓丝。","温庭筠 题西明寺僧院"],["名自张华显，词因葛亮吟。","韦庄 和薛先辈见寄初秋寓怀即事之作二十韵"]]},{"n":"士衡患多","d":"","s":"《晋书》卷五十四《陆机传》","w":"机天才秀逸，辞藻宏丽，张华尝谓之曰：「人之为文，常恨才少，而子更患其多。」","q":[["武仲不休，士衡患多。","李瀚 蒙求"]]},{"n":"司空羡","d":"","s":"《晋书》卷三十六《张华传》","w":"「华名重一世，众所推服，晋史及仪礼宪章并属于华，多所损益，当时诏诰皆所草定，声誉益盛，有台辅之望焉。」「数年，代下邳王晃为司空，领著作。」","q":[["文独司空羡，书兼太尉能。","司空曙 送翰林张学士岭南勒圣碑"]]},{"n":"张华见陆云","d":"","s":"《晋书》卷三十六《张华传》","w":"初，陆机兄弟志气高爽，自以吴之名家，初入洛，不推中国人士，见华一面如旧，钦华德范，如师资之礼焉。华诛后，作诔，又为咏德赋以悼之。","q":[["不知何处清风夕，拟使张华见陆云。","马异 答卢仝结交诗"]]},{"n":"张华史汉","d":"","s":"《世说新语》上卷上《言语》","w":"「诸名士共至洛水戏。还，乐令问王夷甫曰：『今日戏乐乎？』王曰：『裴仆射善谈名理，混混有雅致；张茂先论史汉，靡靡可听；我与王安丰戎也。说延陵、子房，亦超超玄箸。』」南朝梁·刘孝标注引《晋阳秋》曰：「华博览洽闻，无不贯综。世祖尝问汉事，及建章千…","q":[["束皙言谈妙，张华史汉遒。","沈佺期 三日独坐驩州思忆旧游"]]}],"64":[{"n":"绿耳","d":"八骏：指骏马。唐韦应物《酬郑户曹骊山感怀》：“万马自腾踏，八骏按辔行。”","s":"《列子集释》卷三〈周穆王篇〉～90～","w":"王大悦。不恤国事，不乐臣妾，肆意远游。命驾八骏之乘，右服骅骝而左绿耳，右骖赤骥而左白羲，主车则造父为御，泰丙为右；次车之乘，右服渠黄而左踰轮，左骖盗骊而右山子，柏夭主车，参百为御，奔戎为右。","q":[["巡非瑶水远，迹是雕墙后。","杜甫 九成宫"],["来参八骏列，不假贰师功。","周存 西戎献马"]]},{"n":"赤骥","d":"","s":"《穆天子传》卷四《八骏翔行章》","w":"「天子命驾八骏之乘……右骖赤骥，而左白义。天子乃遂东南翔行，驰驱千里。」","q":[["鸣驺辞凤苑，赤骥最承恩。","李贺 马诗二十三首之三"],["放蹄知赤骥，捩翅服苍鹰。","杜甫 寄刘峡州伯华使君四十韵"]]},{"n":"沙虫猿鹤","d":"虫沙猿鹤：喻战中死亡的官兵。唐韩愈《送区弘南归》：“穆昔南征军不归，虫沙猿鹤伏以飞。”","s":"《艺文类聚》卷九十五","w":"晋·葛洪《抱朴子》：「周穆王南征，一军皆化，君子为猿为鹤，小人为虫为沙。」（据《艺文类聚》卷九十五引）","q":[["君子变猿鹤，小人为沙虫。","李白 古风"],["穆昔南征军不归，虫沙猿鹤伏以飞。","韩愈 送区弘南归"]]},{"n":"黄竹咏","d":"","s":"《穆天子传》卷五～47～","w":"日中大寒，北风雨雪，有冻人，天子作诗三章以哀民曰：「我徂黄竹，●员閟寒，帝收九行。嗟我公侯，百辟冢卿，皇我万民，旦夕勿忘。我徂黄竹，●员閟寒，帝收九行。嗟我公侯，百辟冢卿，皇我万民，旦夕勿穷。有皎者●，翩翩其飞，嗟我公侯，●勿则●。居乐甚寡…","q":[["一承黄竹咏，长奉白茅居。","宋之问 奉和幸韦嗣立山庄侍宴应制"],["悬知穆天子，黄竹谩言诗。","徐彦伯 游禁苑幸临渴亭遇雪应制"]]},{"n":"假鼋鼍","d":"","s":"《艺文类聚》卷九","w":"《竹书纪年》：周穆王三十七年，伐楚，大起九师，至于九江，比鼋鼍为梁。","q":[["难假鼋鼍力，空瞻乌鹊毛。","杜甫 临邑舍弟书至苦雨黄河泛溢堤防之患簿领所忧因寄此诗用宽其意"]]},{"n":"金玉裁王度","d":"","s":"《春秋左传·昭公十二年》","w":"思我王度，式如玉，式如金。","q":[["金玉美王度，欢康谣国风。","武元衡 奉和圣制丰年多庆九日示怀"],["金玉裁王度，丹书奉帝俞。","武元衡 奉酬淮南中书相公见寄"]]},{"n":"穆天子","d":"","s":"《史记》卷四《周本纪》","w":"昭王南巡狩不返，卒于江上。其卒不赴告，讳之也。立昭王子满，是为穆王。穆王即位，春秋已五十矣。……穆王立五十五年，崩，子共王繄扈立。","q":[["无路洞天寻穆满，有时人世美刘郎。","李昭象 学仙词寄顾云"],["穆满不再活，无人昆阆骑。","李群玉 骢马"]]},{"n":"七萃","d":"","s":"《穆天子传》卷一～2～","w":"赐七萃之士战。庚寅，北风雨雪。天子以寒之故，命王属休。晋·郭璞注：「萃，集也，聚也；亦犹传有七舆大夫，皆聚集有势力者，为王之爪牙也。」","q":[["七萃和銮动，三条葆吹回。","李德裕 郊坛回舆中书二相公蒙圣慈召至御马前仰感恩遇辄书是诗兼呈二相公"],["何如穆天子，七萃几劳师。","苏颋 扈从凤泉和崔黄门喜恩旨解严罢围之作"]]},{"n":"伤盛姬","d":"","s":"《穆天子传》卷六","w":"「天子赐之上姬之长，是曰盛门。天子乃为之台，是曰重璧之台。」「盛姬求饮，天子命人取浆而给，是曰壶輲。天子西至于重璧之台，盛姬告病薨。天子哀之，是曰哀次。天子乃殡盛姬于毂丘之庙。」「天子南葬盛姬于乐池之南。」「视皇后之葬法。」","q":[["君不见穆王三日哭，重璧台前伤盛姬。","白居易 新乐府（并序）之李夫人之鉴嬖惑也"]]},{"n":"天子之马","d":"","s":"《穆天子传》","w":"天子之马走千里，胜人猛兽。天子之狗走百里，执虎豹。","q":[["吾闻天子之马走千里，今之画图无乃是。","杜甫 天育骠骑歌"]]},{"n":"心膂良臣","d":"","s":"《尚书》卷十九〈周书·君牙〉～293～","w":"王若曰：「呜呼！君牙，惟乃祖乃父，世笃忠贞，服劳王家，厥有成绩，纪于太常。惟予小子，嗣守文、武、成、康遗绪，亦惟先正之臣，克左右乱四方。心之忧危，若蹈虎尾，涉于春冰。今命尔予翼，作股肱心膂。缵乃旧服，无忝祖考，弘敷五典，式和民则。尔身克正，…","q":[]},{"n":"悬圃","d":"","s":"《楚辞》战国楚·屈原《离骚》","w":"「夕余至乎县圃。」东汉·王逸注：「县圃神山，在昆崙之上。」","q":[["今朝出豫临悬圃，明日陪游向赤城。","崔融 嵩山石淙侍宴应制"],["玉管会玄圃，火枣承天姻。","李商隐 戊辰会静中出贻同志二十韵"]]},{"n":"瑶池","d":"","s":"《穆天子传》卷一","w":"吉日甲子，天子宾于西王毋。……乙丑，天子觞西王毋于瑶池之上，西王毋为天子谣。","q":[["所宜巢三鸟，影入瑶池碧。","刘驾 琪树下因吟六韵呈先达者"],["周王久谢瑶池赏，汉主悬惭玉树宫。","姚崇 奉和圣制夏日游石淙山"]]},{"n":"周穆八荒","d":"","s":"《穆天子传》卷三","w":"吉日甲子，天子宾于西王母。执玄圭白璧以见西王母，献锦组百缕，金玉百斤。西王母再拜受之。乙丑，天子觞西王母于瑶池之上。西王母为天子谣","q":[["周穆八荒意，汉皇万乘尊。","李白 古风"],["秦王登碣石，周后袭昆仑。何必在遐远，方称万宇尊。","武平一 奉和幸新丰温泉宫应制"]]}],"65":[{"n":"刘伶醉","d":"刘伶好酒：指嗜酒。明于谦《醉时歌》：“刘伶好酒世称贤，李白骑鲸飞上天。”","s":"《晋书》卷四十九《刘伶传》","w":"「刘伶字伯伦，沛国人也。身长六尺，容貌甚陋。放情肆志，常以细宇宙齐万物为心。澹默少言，不妄交游，与阮籍、嵇康相遇，欣然神解，携手入林。初不以家产有无介意。常乘鹿车，携一壶酒，使人荷锸而随之，谓曰：『死便埋我。』其遗形骸如此。」","q":[["刘伶好酒世称贤，李白骑鲸飞上天。","于谦 醉时歌"],["长羡刘伶辈，高眠出世间。","姚合 武功县中作三十首"]]},{"n":"刘伶妇","d":"刘伶妇：喻劝戒酒之人。宋苏拭《小儿》：“大胜刘伶妇，区区为酒钱。”","s":"《世说新语笺疏》下卷上〈任诞〉～729～","w":"刘伶病酒，渴甚，从妇求酒。妇捐酒毁器，涕泣谏曰：「君饮太过，非摄生之道，必宜断之！」伶曰：「甚善。我不能自禁，唯当祝鬼神，自誓断之耳！便可具酒肉。」妇曰：「敬闻命。」供酒肉于神前，请伶祝誓。伶跪而祝曰：「天生刘伶，以酒为名，一饮一斛，五斗解…","q":[]},{"n":"伯伦狂","d":"","s":"《世说新语笺疏》下卷上〈任诞〉～729～","w":"刘伶病酒，渴甚，从妇求酒。妇捐酒毁器，涕泣谏曰：「君饮太过，非摄生之道，必宜断之！」伶曰：「甚善。我不能自禁，唯当祝鬼神，自誓断之耳！便可具酒肉。」妇曰：「敬闻命。」供酒肉于神前，请伶祝誓。伶跪而祝曰：「天生刘伶，以酒为名，一饮一斛，五斗解…","q":[]},{"n":"鹿车","d":"","s":"《世说新语》上卷下《文学》","w":"「刘伶著《酒德颂》，意气所寄。」南朝梁·刘孝标注引《名士传》曰：「伶字伯伦，沛郡人。肆意放荡，以宇宙为狭。常乘鹿车，携一壶酒，使人荷锸随之，云：『死便掘地以埋。』土木形骸，遨游一世。」","q":[["伯伦每置随身锸，元亮先为自祭文。莫道高风无继者，一千年内有崔君。","白居易 哭崔二十四常侍"],["邴原虽不无端醉，也爱临风从鹿车。","郑璧 和袭美索友人酒"]]},{"n":"醉乡侯","d":"","s":"《晋书》卷四十九〈刘伶列传〉～375～","w":"刘伶字伯伦，沛国人也。身长六尺，容貌甚陋。放情肆志，常以细宇宙齐万物为心。澹默少言，不妄交游，与阮籍、嵇康相遇，欣然神解，携手入林。初不以家产有无介意。常乘鹿车，携一壶酒，使人荷锸而随之，谓曰：「死便埋我。」其遗形骸如此。尝渴甚，求酒于其妻…","q":[["念昔挥毫端，不独观酒德。","杜甫 殿中杨监见示张旭草书图"]]},{"n":"二豪不数刘伶","d":"","s":"《昭明文选》卷四十七〈颂赞·颂·酒德颂〉～2099～","w":"有大人先生，以天地为一朝，万期为须臾，日月为扃牖，八荒为庭衢。行无辙?，居无室庐，幕天席地，纵意所如。止则操卮执觚，动则挈榼提壶，惟酒是务，焉知其馀。有贵介公子、搢绅处士，闻吾风声，议其所以，乃奋袂攘襟，怒目切齿，陈说礼法，是非蜂起。先生于…","q":[]},{"n":"嵇刘","d":"","s":"《晋书》卷四十九《嵇康传》","w":"所与神交者惟陈留阮籍、河内山涛，豫其流者河内向秀、沛国刘伶、籍兄子咸、琅邪王戎，遂为竹林之游，世所谓「竹林七贤」也。","q":[["酣酣天地宽，恍恍嵇刘伍。","杜牧 雨中作"]]},{"n":"竹林七贤","d":"七贤：喻指文人放荡不羁，或指独立于世俗之外，或喻朋友的交情深厚。唐卢纶《秋夜同畅当宿潭上西亭》：“圆月出山头，七贤林下游。”","s":"《三国志》卷二十一〈魏书·王粲传·嵇康〉～605～","w":"时又有谯郡嵇康，文辞壮丽，好言老、庄，而尚奇任侠。至景元中，坐事诛。南朝宋·裴松之注引《魏氏春秋》曰：「康寓居河内之山阳县，与之游者，未尝见其喜愠之色。与陈留阮籍、河内山涛、河南向秀、籍兄子咸、琅邪王戎、沛人刘伶相与友善，游于竹林，号为七贤…","q":[["东篱摘芳菊，想见竹林游。","储光羲 仲夏饯魏四河北觐叔"],["超超青云器，婉婉竹林会。","储光羲 奉和韦判官献侍郎叔除河东采访使"]]},{"n":"刘伶解酲","d":"","s":"《世说新语》下卷上《任诞》","w":"「刘伶病酒，渴甚。从妇求酒。妇捐酒毁器，涕泣谏曰：『君饮太过，非摄生之道，必宜断之！』伶曰：『甚善。我不能自禁，唯当祝鬼神，自誓断之耳。便可具酒肉。』妇曰：『敬闻命。』供酒肉于神前，请伶祝誓。伶跪而祝曰：『天生刘伶，以酒为名，一饮一斛，五斗…","q":[["太常应已醉，刘君恒带酲。","李百药 妾薄命"],["解酲元有数，不用吓刘伶。","李益 答窦二曹长留酒还榼"]]},{"n":"幕天席地","d":"","s":"《昭明文选》卷四十七〈颂赞·颂·酒德颂〉～2098～","w":"有大人先生，以天地为一朝，万期为须臾。日月为扃牖，八荒为庭衢。行无辙，居无室庐。幕天席地，纵意所如。止则操执觚，动则挈榼提壶。唯酒是务，焉知其馀。有贵介公子，搢绅处士。闻吾风声，议其所以。乃奋袂攘襟，怒目切齿。陈说礼法，是非锋起。先生于…","q":[["谁向刘灵天幕内，更当陶令北窗风。","李商隐 假日"],["天地为幕席，富贵如泥沙。嵇刘陶阮徒，不足置齿牙。","白居易 和新楼北园偶集从孙公度周巡官韩秀才卢秀才范处士小饮郑侍御判官周刘二从事皆先归"]]},{"n":"曝裈当屋","d":"","s":"《世说新语》下卷上《任诞》","w":"刘伶恒纵酒放达，或脱衣裸形在屋中，人见讥之。伶曰：「我以天地为栋宇，屋室为㡓衣，诸君何为入我㡓中？」","q":[["曝裈还当屋，张幕便成天。","李端 晚春过夏侯校书值其沉醉戏赠"]]},{"n":"土木形骸","d":"","s":"《世说新语》下卷上《容止》","w":"「刘伶身长六尺，貌甚丑悴，而悠悠忽忽，土木形骸。……嵇康身长七尺八寸，风姿特秀。」南朝梁·刘孝标注引《嵇康别传》：「康长七尺八寸，伟容色，土木形骸，不加饰厉，而龙章凤姿，天质自然。」","q":[["形骸元土木，舟楫复江湖。","杜甫 舟出江陵南浦奉寄郑少尹"]]},{"n":"衔杯对刘","d":"","s":"《昭明文选》卷四十七晋·刘伯伦（伶）《酒德颂》","w":"有大人先生，以天地为一朝，万期为须臾，日月为扃牖，八荒为庭衢。行无辙迹，居无室庐，幕天席地，纵意所如。止则操卮执觚，动则挈榼提壶，惟酒是务，焉知其馀。有贵介公子、搢绅处士，闻吾风声，议其所以，乃奋袂攘襟，怒目切齿，陈说礼法，是非蜂起。先生于…","q":[["结绶还逢育，衔杯且对刘。","陈子昂 江上暂别萧四刘三旋欣接遇"]]},{"n":"尊拳","d":"刘伶鸡肋：喻身体瘦弱，不堪一击。宋黄庭坚《谢答闻善二兄九绝句》：“阮籍醉睡不论昏，刘伶鸡肋避尊拳。”","s":"《晋书》卷四十九〈刘伶列传〉","w":"刘伶字伯伦，沛国人也。身长六尺，容貌甚陋。放情肆志，常以细宇宙齐万物为心。澹默少言，不妄交游，与阮籍、嵇康相遇，欣然神解，携手入林。初不以家产有无介意。常乘鹿车，携一壶酒，使人荷锸而随之，谓曰：「死便埋我。」其遗形骸如此。尝渴甚，求酒于其妻…","q":[]}],"66":[{"n":"白鱼跃舟","d":"","s":"《史记》卷四《周本纪》","w":"「武王渡河，中流，白鱼跃入王舟中。」南朝宋·裴骃《史记集解》：「马融曰：『鱼者，介鳞之物，兵象也。白者，殷家之正色，言殷之兵众与周之象也。』」","q":[["瑞凤飞来随帝辇，祥鱼出戏跃王舟。","苏瑰 兴庆池侍宴应制"]]},{"n":"倒载干戈","d":"","s":"《礼记·乐记》","w":"「武王克殷。反商。……车甲?而藏之府库。而弗复用。倒载干戈。包之以虎皮。将帅之士。使为诸侯。名之曰建橐。然后天下知武王之不复用兵也。」东汉·郑玄注：「包干戈以虎皮，明能以武服兵也。」唐·孔颖达疏：「包之以虎皮者，虎皮，武猛之物也。用此虎皮包…","q":[["萧条井邑如鱼尾，早晚干戈识虎皮。","杜牧 即事"],["倒载干戈是何日，近来麋鹿欲相随。","杜荀鹤 春日山居寄友人"]]},{"n":"鼎迁","d":"","s":"《春秋左传·桓公二年》","w":"「臧哀伯谏曰：『……武王克商。迁九鼎于雒邑。义士犹或非之。』」晋·杜预注：「九鼎，殷所受夏九鼎也。武王克商，乃营雒邑而后去之，又迁九鼎焉，时但营洛邑，未有都城。」","q":[["高居迁鼎邑，遥傅好书王。","柳宗元 弘农公以硕德伟材屈于诬枉（弘农公杨凭也。为御史李夷简所弹）左官三岁复为大僚天监昭明人心感悦宗元窜伏湘浦拜贺末由谨献诗五十韵以毕微志"],["水斗宫初毁，风变鼎将迁。","陆敬 游隋故都"]]},{"n":"宴镐","d":"","s":"《诗经·小雅·鱼藻》","w":"「王在在镐，岂乐饮酒。」东汉·郑玄笺：「岂，亦乐也。天下平安，万物得其性，武王何所处乎？处于镐京，乐八音之乐，与群臣饮酒而巳。」","q":[["镐饮周文乐，汾歌汉武才。","宋之问 奉和晦日幸昆明池应制"],["酆镐谁将敌，横汾未可方。","宋若宪 奉和御制麟德殿宴百宫"]]},{"n":"休牛","d":"归马华山阳：指罢战休兵。唐杜甫《有感五首》之二：“大君先息战，归马华山阳。”","s":"《尚书·周书·武成》","w":"「王朝步自周，于征伐商，厥四月哉生明，王来自商，至于丰，乃偃武修文，归马于华山之阳，放牛于桃林之野，示天下弗服。」旧题汉·孔安国传：「山南曰阳，桃林在华山东，皆非长养牛马之地，欲使自生自死，示天下不复乘用。」","q":[["愿得华山之下长归马，野田无复堆冤者。","张碧 野田行"],["欲向桃林下，先过梓树中。","李峤 牛"]]},{"n":"火乌","d":"","s":"《史记》卷四〈周本纪〉～20～","w":"武王渡河，中流，白鱼跃入王舟中，武王俯取以祭。既渡，有火自上复于下，至于王屋，流为乌，其色赤，其声魄云。南朝宋·裴骃《史记集解》注引郑玄曰：「《书说》云乌有孝名。武王卒父大业，故乌瑞臻。赤者，周之正色也。」","q":[["火乌日暗崩腾云，秦皇虎视苍生群。","李贺 白虎行"]]},{"n":"剪商","d":"","s":"《诗经·鲁颂·閟宫》","w":"「后稷之孙，实维大王。居岐之阳，实始剪商。」东汉·郑玄注：「剪，断也。大王自豳徙居岐阳，四方之民咸归往之，于时而有王迹，故云是始断商。」","q":[["缅惟剪商后，岂独微禹叹。","张九龄 奉和圣制幸晋阳宫"]]},{"n":"救暍","d":"","s":"《初学记》","w":"晋·皇甫谧《帝王世纪》：武王自孟津还及于周，见喝人，王自左拥而右扇之。","q":[["前圣慎焚巫，武王亲救暍。","杜甫 七月三日亭午已后较热退晚加小凉稳睡有诗因论壮年乐事戏呈元二十一曹长"]]},{"n":"吕尚封国","d":"","s":"《史记》卷四《周本纪》","w":"于是封功臣谋士，而师尚父为首封。封尚父于营丘，曰齐。","q":[["吕尚封国邑，傅说已盐梅。","杜甫 昔游"]]},{"n":"七步师旋","d":"","s":"《尚书》卷十一〈周书·牧誓〉～59～","w":"今予发，惟恭行天之罚。今日之事，不愆于六步、七步，乃止，齐焉。夫子勖哉！不愆于四伐、五伐、六伐、七伐，乃止，齐焉。勖哉夫子！尚桓桓，如虎如貔，如熊如罴，于商郊。","q":[["列射三侯满，兴师七步旋。","李峤 熊"]]},{"n":"武王击纣","d":"","s":"《史记》卷四〈周本纪〉～24～","w":"帝纣闻武王来，亦发兵七十万人距武王。武王使师尚父与百夫致师，以大卒驰帝纣师。纣师虽众，皆无战之心，心欲武王亟入。纣师皆倒兵以战，以开武王。武王驰之，纣兵皆崩畔纣。纣走，反入登于鹿台之上，蒙衣其殊玉，自燔于火而死。武王持大白旗以麾诸侯，诸侯毕…","q":[["太古初断鳌，武王亲击纣。","元稹 说剑"]]},{"n":"西旅獒","d":"","s":"《尚书·周书·旅獒》","w":"「惟克商，遂通道于九夷八蛮，西旅厎贡厥獒。」旧题汉·孔安国传：「西旅之长致贡其獒。犬高四尺曰獒，以大为异。」","q":[["重来越裳雉，再返西旅獒。","柳宗元 游南亭夜还叙志七十韵"]]},{"n":"阴骘","d":"","s":"《尚书·周书·洪范》","w":"「惟十有三祀，王访于箕子，王乃言曰：『乌呼，箕子！惟天阴骘下民，相协厥居，我不知其彝伦攸?。」旧题汉·孔安国传：「骘，定也，天不言而默定下民。」","q":[["乃知阴骘数，制在造化情。","皎然 同薛员外谊喜雨诗兼上杨使君"]]},{"n":"周诵","d":"","s":"《史记》卷四〈周本纪〉～3～","w":"武王病。天下未集，群公惧，穆卜，周公乃祓斋，自为质，欲代武王，武王有瘳。后而崩，太子诵代立，是为成王。","q":[["逖矣凌周诵，遥哉掩汉庄。","李元嘉 奉和同太子监守违恋"]]}],"67":[{"n":"访莘","d":"","s":"《孟子》卷九下《万章上》","w":"「孟子曰：『否，不然。』伊尹耕于有莘之野，而乐尧舜之道焉，非其义也，非其道也，禄之以天下弗顾也。系马千驷，弗视也，非其义也，非其道也。一介不以与人，一介不以取诸人，汤使人以币聘之。嚣嚣然曰：『我何以汤之聘币为哉？我岂若处畎亩之中，由是以乐尧…","q":[["迹岩劳傅想，窥野访莘情。","李世民 春日登陕州城楼俯眺原野回丹碧缀烟霞密翠班红芳菲花柳即目川岫聊以命篇"]]},{"n":"放太甲","d":"","s":"《史记》卷三〈殷本纪〉～98～","w":"汤崩，太子太丁未立而卒，于是乃立太丁之弟外丙，是为帝外丙。帝外丙即位三年，崩，立外丙之弟中壬，是为帝中壬。帝中壬即位四年，崩，伊尹乃立太丁之子太甲。太甲，成汤适长孙也，是为帝太甲。帝太甲元年，伊尹作伊训，作肆命，作徂后。帝太甲既立三年，不明…","q":[["桐宫放太甲，摄政无愧色。三年帝明道，委质终辅翼。","李白 纪南陵题五松山"]]},{"n":"负鼎","d":"","s":"《史记》卷三《殷本纪》","w":"「伊尹名阿衡。阿衡欲奸汤而无由，乃为有莘氏媵臣，负鼎俎，以滋味说汤，致于王道。或曰，伊尹处士，汤使人聘迎之，五反然后肯往从汤，言素王及九主之事。汤举任以国政。伊尹去汤适夏。既丑有夏，复归于亳。入自北门，遇女鸠、女房，作《女鸠女房》。」唐·司…","q":[["空怀伊尹心，何补尧舜治。","唐彦谦 宿田家（第十四句缺一字）"],["进无负鼎说，退惭补衮诗。","崔湜 景龙二年余自门下平章事削阶授江州员外司马寻拜襄州刺史春日赴襄阳途中言志"]]},{"n":"夔龙","d":"","s":"《尚书·虞书·舜典》","w":"「伯拜稽首，让于夔龙，……帝曰：『俞往钦哉！』帝曰：『夔，命汝典乐，教冑子。直而温，宽而栗。刚而无虐，而无傲。……神人以和。』夔曰：『于予击石，拊石，百兽率舞。』帝曰：『龙，朕堲谗说殄行，震惊朕师，命汝作纳言，夙夜出纳朕命，惟允。』」旧题…","q":[["圣哲承休运，伊夔列上台。","丁仙芝 越棠贡白雉（一作孙昌胤诗）"],["并进夔龙位，仍齐龟鹤年。","刘禹锡 奉和淮南李相公早秋即事寄成都武相公"]]},{"n":"生空桑","d":"","s":"北魏·郦道元《水经注》卷十五《伊水》","w":"昔有莘氏女，采桑于伊川，得婴儿于空桑中，言其母孕于伊水之滨，梦神告之曰，臼水出而东走。母明视而见臼水出焉，告其邻居而走，顾望其邑，咸为水矣。其母化为空桑，子在其中矣。莘女取而献之，命养于庖，长而有贤德，殷以为尹，曰伊尹也。","q":[["伊尹生空桑，捐庖佐皇极。","李白 纪南陵题五松山"]]},{"n":"汤左相","d":"","s":"《史记》卷三《殷本纪》","w":"伊尹处士，汤使人聘迎之，五反然后肯往从汤，言素王及九主之事。汤举任以国政。","q":[["位高汤左相，权总汉诸侯。","张继 奉送王相公赴幽州（一作韩翃诗。题下有巡边二字）"]]},{"n":"莘渭","d":"","s":"《史记》卷三十二〈齐太公世家〉～478～","w":"于是周西伯猎，果遇太公于渭之阳，与语大说，曰：「自吾先君太公曰『当有圣人适周，周以兴』。子真是邪？吾太公望子久矣。」故号之曰「太公望」，载与俱归，立为师。","q":[["贤多隐屠钓，王肯载同归。","杜甫 伤春五首"]]},{"n":"伊傅","d":"","s":"《后汉书》卷五十二〈崔骃列传·崔骃〉～705～","w":"建武初，朝廷多荐言之者，幽州刺史又举篆贤良。篆自以宗门受莽伪宠，惭愧汉朝，遂辞归不仕。客居荥阳，闭门潜思，著周易林六十四篇，用决吉凶，多所占验。临终作赋以自悼，名曰慰志。其辞曰：「嘉昔人之遘辰兮，美伊、傅之●时。应规矩之淑质兮，过班、倕而裁…","q":[]},{"n":"伊皋","d":"","s":"《汉书》卷四十《张陈王周传赞》","w":"「时固始弱冠，奏记说苍曰：『……将军宜详唐、殷之举，察伊、皋之荐，令远近无偏，幽隐必达。』」唐·李贤注：「尧举皋陶，汤举伊尹。」","q":[["方将袭伊皋，永以崇夏殷。","储光羲 敬酬陈掾亲家翁秋夜有赠"],["伊皋争负鼎，舜禹让垂旒。","徐夤 依御史一本无御史二字温飞卿华清宫二十二韵"]]},{"n":"伊霍","d":"","s":"《后汉书》卷七十八《宦者传·序》","w":"或称伊、霍之勋，无谢于往载；或谓良、平之画，复兴于当今。","q":[["长笑应刘悲显达，每嫌伊霍少诗篇。","罗隐 寄酬邺王罗令公五首"]]},{"n":"伊吕","d":"","s":"《汉书》卷五十六《董仲舒传赞》","w":"「刘向称『董仲舒有王佐之材，虽伊吕亡以加。』」唐·颜师古注：「伊，伊尹。吕，吕望也。」","q":[["苍生属伊吕，明主仗韩彭。","刘长卿 至德三年春正月时谬蒙差摄海盐令闻王师收二京因书事寄上浙西节度李侍郎中丞行营五十韵"],["伊吕代封爵，夷齐终身饥。","孟郊 罪松"]]},{"n":"伊周","d":"","s":"《汉书》卷四十《张陈王周传赞》","w":"「周勃为布衣时，鄙朴庸人，至登辅佐，匡国家难，诛诸吕，立孝文，为汉伊周，何其盛也！」唐·颜师古注：「处伊尹、周公之任。」","q":[["处贵有馀兴，伊周位不如。","钱起 晚出青门望终南别业"]]},{"n":"致君尧舜","d":"","s":"《孟子注疏》卷九下〈万章章句上〉～70～","w":"伊尹耕于有莘之野，而乐尧舜之道焉。非其义也，非其道也，禄之以天下，弗顾也；系马千驷，弗视也。非其义也，非其道也，一介不以与人，一介不以取诸人，汤使人以币聘之，嚣嚣然曰：『我何以汤之聘币为哉？我岂若处畎亩之中，由是以乐尧舜之道哉？』汤三使往聘…","q":[["仕宦至公相，致君作尧汤。","杜牧 冬至日寄小侄阿宜诗"],["致君尧舜上，再使风俗淳。","杜甫 奉赠韦左丞丈二十二韵"]]}],"68":[{"n":"郭奕心醉","d":"","s":"《世说新语》中卷下《赏誉》","w":"「山公举阮咸为吏部郎，目曰：『清真寡欲，万物不能移也。』」南朝梁·刘孝标注引《名士传》曰：「咸字仲容，陈留人，籍兄子也。任达不拘，当世皆怪其所为。及与之处，少嗜欲，哀乐至到，过绝于人，然后皆忘其向议。为散骑侍郎。山涛举为吏部，武帝不用。太原…","q":[["何晏神伏，郭奕心醉。","李瀚 蒙求"]]},{"n":"二阮","d":"","s":"《晋书》卷四十九《阮籍传》附《阮咸传》","w":"「咸字仲容。父熙，武都太守。咸任达不拘，与叔父籍为竹林之游。」","q":[["我家小阮贤，剖竹赤城边。","李白 送杨山人归天台"],["阮咸虽别巷，遥识此时心。","李端 寄上舍人叔"]]},{"n":"竹林七贤","d":"七贤：喻指文人放荡不羁，或指独立于世俗之外，或喻朋友的交情深厚。唐卢纶《秋夜同畅当宿潭上西亭》：“圆月出山头，七贤林下游。”","s":"《三国志》卷二十一〈魏书·王粲传·嵇康〉～605～","w":"时又有谯郡嵇康，文辞壮丽，好言老、庄，而尚奇任侠。至景元中，坐事诛。南朝宋·裴松之注引《魏氏春秋》曰：「康寓居河内之山阳县，与之游者，未尝见其喜愠之色。与陈留阮籍、河内山涛、河南向秀、籍兄子咸、琅邪王戎、沛人刘伶相与友善，游于竹林，号为七贤…","q":[["东篱摘芳菊，想见竹林游。","储光羲 仲夏饯魏四河北觐叔"],["超超青云器，婉婉竹林会。","储光羲 奉和韦判官献侍郎叔除河东采访使"]]},{"n":"酒盆","d":"","s":"《晋书》卷四十九〈阮籍列传·（兄子）阮咸〉","w":"诸阮皆饮酒，咸至，宗人间共集，不复用杯觞斟酌，以大盆盛酒，圆坐相向，大酌更饮。","q":[["归来冷笑悲身事，唤妇呼儿索酒盆。","杜牧 哭韩绰"]]},{"n":"累骑","d":"","s":"《世说新语》下卷上《任诞》","w":"阮仲容先幸姑家鲜卑婢。及居母丧，姑当远移，初云当留婢，既发，定将去。仲容借客驴箸重服自追之，累骑而返。曰：「人种不可失！」即遥集之母也。","q":[["傥恕相如瘦，应容累骑还。","段成式 和周繇见嘲"]]},{"n":"未能免俗","d":"阮家贫：指生活贫困。唐王维《郑梁州相过》：“中厨办粗饭，应恕阮家贫。”","s":"《世说新语笺疏》下卷上〈任诞〉～732～","w":"阮仲容、步兵居道南，诸阮居道北。北阮皆富，南阮贫。七月七日，北阮盛晒衣，皆纱罗锦绮。仲容以竿挂大布犊鼻裈于中庭。人或怪之，答曰：「未能免俗，聊复尔耳！」南朝宋·裴松之注引《竹林七贤论》曰：「诸阮前世皆儒学，善居室，唯咸一家尚道弃事，好酒而贫…","q":[["近水方同梅市隐，曝衣多笑阮家贫。","司空曙 闲园即事寄暕公"],["南阮贫无酒，唯将泪湿衣。","李端 送别驾赴晋陵即舍人叔之兄"]]},{"n":"青云器","d":"","s":"《昭明文选》卷二十一〈诗乙·咏史·五君咏五首·阮始平〉～00～","w":"仲容青云器，实禀生民秀。达音何用深？识微在金奏。唐·李善注：「青云，言高远也。《史记》太史公曰：『夫闾巷之人，欲砥行立名者，非附青云之士，恶能施于后代哉！』」","q":[["仲容青云，叔夜玉山。","李瀚 蒙求"],["白社陶元亮，青云阮仲容。","李端 奉和秘书元丞杪秋忆终南旧居"]]},{"n":"阮巷","d":"","s":"《晋书》卷四十九《阮籍传》附《阮咸传》","w":"咸字仲容。父熙，武都太守。咸任达不拘，与叔父籍为竹林之游，当世礼法者讥其所为。咸与籍居道南，诸阮居道北，北阮富而南阮贫。","q":[["到日应文会，风流胜阮家。","戴叔伦 送李审之桂州谒中丞叔"],["阮家今夜乐，应在竹林间。","李端 送张淑归觐叔父"]]},{"n":"阮始平","d":"","s":"《晋书》卷四十九《阮籍传》附《阮咸传》","w":"「历任散骑侍郎……出补始平太守。」","q":[["适逢阮始平，立马问长安。","独孤及 贾员外处见中书贾舍人巴陵诗集览之怀旧代书寄赠"]]},{"n":"阮太守","d":"","s":"《晋书》卷四十九《阮籍传》","w":"「咸字仲容。父熙，武都太守。咸任达不拘，与叔父籍为竹林之游，当世礼法者讥其所为。咸与籍居道南，诸阮居道北，北阮富而南阮贫。七月七日，北阮盛晒衣服，皆锦绮粲目。咸以竿挂大布犊鼻于庭，人或怪之，答曰：『未能免俗，聊复尔耳！』」「咸妙解音律，善弹…","q":[["仲容铜琵琶，项直声凄凄。","李商隐 戏题枢言草阁三十二韵"],["方知阮太守，一听识其微。","皎然 奉和裴使君清春夜南堂听陈山人弹白雪"]]},{"n":"阮咸竹林兴","d":"","s":"《晋书》卷四十九〈阮籍列传·（兄子）阮咸〉～362～","w":"咸字仲容。父熙，武都太守。咸任达不拘，与叔父籍为竹林之游，当世礼法者讥其所为。咸与籍居道南，诸阮居道北，北阮富而南阮贫。七月七日，北阮盛晒衣服，皆锦绮粲目。咸以竿挂大布犊鼻于庭，人或怪之，答曰：「未能免俗，聊复尔耳！」咸妙解音律，善弹琵琶。…","q":[]},{"n":"一麾出守","d":"","s":"《昭明文选》卷二十一南朝宋·颜延年（延之）《五君咏五首·阮始平》","w":"屡荐不入官，一麾乃出守。","q":[["莫笑一麾东下计，满江秋浪碧参差。","杜牧 即事"],["欲把一麾江海去，乐游原上望昭陵。","杜牧 将赴吴兴登乐游原一绝"]]},{"n":"竹里琴","d":"","s":"《晋书》卷四十九《阮籍传》","w":"阮籍字嗣宗，陈留尉氏人也。……或闭户视书，累月不出；或登临山水，经日忘归。博览群籍，尤好庄老。嗜酒能啸，善弹琴。当其得意，忽忘形骸。时人多谓之痴。","q":[["鸟哢花间曲，人弹竹里琴。","李端 题从叔沆林园"]]}],"69":[{"n":"沈鲍","d":"","s":"《梁书》卷十三《沈约传》","w":"沈约字休文，吴兴武康人也。……高祖受禅，为尚书仆射，封建昌县侯，邑千户，常侍如故。又拜约母谢为建昌国太夫人。奉策之日，右仆射范云等二十馀人咸来致拜，朝野以为荣。俄迁尚书左仆射，常侍如故。寻兼领军，加侍中。天监二年，遭母忧，舆驾亲出临吊，以约…","q":[["高岑殊缓步，沈鲍得同行。","杜甫 寄彭州高三十五使君适虢州岑二十七长史参三十韵"]]},{"n":"飞弹圆熟","d":"","s":"《南史》卷二十二〈王昙首列传·王筠〉～609～","w":"沈约每见筠文咨嗟，尝谓曰：「昔蔡伯喈见王仲宣，称曰王公之孙，吾家书籍悉当相与。仆虽不敏，请附斯言。自谢朓诸贤零落，平生意好殆绝，不谓疲暮复逢于君。」约于郊居宅阁斋，请筠为草木十咏书之壁，皆直写文辞，不加篇题。约谓人曰：「此诗指物程形，无假题…","q":[]},{"n":"飞光","d":"","s":"《昭明文选》卷二十二〈诗乙·游览·宿东园〉～06～","w":"陈王斗鸡道，安仁采樵路。东郊岂异昔，聊可闲余步。野径既盘纡，荒阡亦交互。槿篱疏复密，荆扉新且故。树顶鸣风飙，草根积霜露。惊麇去不息，征鸟时相顾。茅栋啸秋鸱，平岗走寒兔。夕阴带曾阜，长烟引轻素。飞光忽我遒，宁止岁云暮。若蒙西山药，颓龄傥能度。","q":[["飞光飞光，劝尔一杯酒。","李贺 苦昼短"]]},{"n":"何范","d":"","s":"《梁书》卷四十九《文学传上·何逊传》","w":"逊八岁能赋诗，弱冠州举秀才，南乡范云见其对策，大相称赏，因结忘年交好。自是一文一咏，云辄嗟赏，谓所亲曰：「顷观文人，质则过儒，丽则伤俗；其能含清浊，中今古，见之何生矣。」沈约亦爱其文，尝谓逊曰：「吾每读卿诗，一日三复，犹不能已。」其为名流所…","q":[["不妨何范尽诗家，未解当年重物华。","李商隐 漫成三首之一"],["沈范早知何水部，曹刘不待薛郎中。","杜甫 解闷十二首"]]},{"n":"沈范","d":"","s":"唐杜甫《解闷》诗之四","w":"沈 范 早知 何水部 ， 曹 刘 不待 薛郎中 。","q":[]},{"n":"郊居赋","d":"","s":"《梁书》卷十三《沈约传》","w":"约性不饮酒，少嗜欲，虽时遇隆重，而居处俭素。立宅东田，瞩望郊阜。尝为《郊居赋》。","q":[["名重郊居赋，才高独酌谣。","皎然 送沈居士还太原"]]},{"n":"摸索何刘沈谢","d":"","s":"《隋唐嘉话》中～26～","w":"许敬宗性轻傲，见人多忘之。或谓其不聪，曰：「卿自难记，若遇何、刘、沈、谢，暗中摸索著，亦可识。」","q":[]},{"n":"沈东阳","d":"","s":"《梁书》卷十三《沈约传》","w":"隆昌元年，除吏部郎，出为宁朔将军、东阳太守。","q":[["未曾无兴咏，多谢沈东阳。","钱起 江行无题一百首"],["城中金络骑，出饯沈东阳。","韩翃 鲁中送鲁使君归郑州"]]},{"n":"带围宽","d":"","s":"《梁书》卷十三《沈约传》","w":"沈约字休文，吴兴武康人也。……隆昌元年，除吏部郎，出为宁朔将军、东阳太守。……约久处端揆，有志台司，论者咸谓为宜，而帝终不用，乃求外出，又不见许。与徐勉素善，遂以书陈情于勉曰：「吾弱年孤苦，傍无棋属，往者将坠于地，契阔屯邅，困于朝夕，崎岖薄…","q":[["沈约只能瘦，潘仁岂是才。","李商隐 寄裴衡"],["哀同庾开府，瘦极沈尚书。","李商隐 有怀在蒙飞卿"]]},{"n":"沈尚书","d":"","s":"《梁书》卷十三《沈约传》","w":"明帝即位，进号辅国将军，徵为五兵尚书，迁国子祭酒。……梁台建，为散骑常侍、吏部尚书，兼右仆射。高祖受禅，为尚书仆射，封建昌县侯，邑千户，常侍如故。又拜约母谢为建昌国太夫人。奉策之日，右仆射范云等二十馀人咸来致拜，朝野以为荣。俄迁尚书左仆射，…","q":[["妙略多推霍骠骑，能文独见沈尚书。","韩翃 寄令狐尚书"],["去事沈尚书，应怜词赋好。","韩翃 送李明府赴滑州"]]},{"n":"何刘","d":"","s":"《梁书》卷四十九〈文学列传上·何逊〉～693～","w":"初，逊文章与刘孝绰并见重于世，世谓之「何刘」。世祖著论论之云：「诗多而能者沈约，少而能者谢朓、何逊。」","q":[["何刘沈谢力未工，才兼鲍昭愁绝倒。","杜甫 苏端薛复筵简薛华醉歌"]]},{"n":"沈休文","d":"","s":"《梁书》卷十三《沈约传》","w":"沈约字休文，吴兴武康人也。……高祖受禅，为尚书仆射，封建昌县侯，邑千户，常侍如故。又拜约母谢为建昌国太夫人。奉策之日，右仆射范云等二十馀人咸来致拜，朝野以为荣。俄迁尚书左仆射，常侍如故。寻兼领军，加侍中。天监二年，遭母忧，舆驾亲出临吊，以约…","q":[["忽见隐侯裁一咏，还须书向郡楼中。","刘言史 处州月夜穆中丞席和主人"],["待到秋深好时节，与君长醉隐侯家。","吴仁璧 南徐题友人郊居"]]},{"n":"沈谢","d":"","s":"《宋书》卷六十七《谢灵运传》","w":"谢灵运，陈郡阳夏人也。祖玄，晋车骑将军。父瑍，生而不慧，为秘书郎，蚤亡。灵运幼便颖悟，玄甚异之，谓亲知曰：「我乃生瑍，瑍那得生灵运！」灵运少好学，博览群书，文章之美，江左莫逮。从叔混特知爱之。袭封康乐公，食邑二千户。以国公例，除员外散骑侍郎…","q":[["曹刘俯仰惭大敌，沈谢逡巡称小儿。","任华 寄杜拾遗"],["新文生沈谢，异骨降松乔。","杜甫 哭王彭州抡"]]}],"70":[{"n":"白首同归","d":"","s":"《世说新语笺疏》下卷下〈仇隙〉～924～","w":"孙秀既恨石崇不与绿珠，又憾潘岳昔遇之不以礼。后秀为中书令，岳省内见之，因唤曰：「孙令，忆畴昔周旋不？」秀曰：「中心藏之，何日忘之？」岳于是始知必不免。后收石崇、欧阳坚石，同日收岳。石先送市，亦不相知。潘后至，石谓潘曰：「安仁，卿亦复尔邪？」…","q":[["当君白首同归日，是我青山独往时。","白居易 九年十一月二十一日感事而作（其日独游香山寺）"]]},{"n":"绿珠楼","d":"","s":"《晋书》卷三十三〈石苞列传·（子）石乔·（子）石崇〉～004～","w":"崇字季伦，生于青州，故小名齐奴。少敏惠，勇而有谋。……及贾谧诛，崇以党与免官。时赵王伦专权，崇甥欧阳建与伦有隙。崇有妓曰绿珠，美而艳，善吹笛。孙秀使人求之。崇时在金谷别馆，方登凉台，临清流，妇人侍侧。使者以告。崇尽出其婢妾数十人以示之，皆蕴…","q":[["四者俱不闻，空传堕楼客。","于濆 金谷感怀"],["亚水依岩半倾侧，笼云隐雾多愁绝。绿珠语尽身欲投，汉武眼穿神渐灭。","元稹 山枇杷"]]},{"n":"二十四友","d":"","s":"《晋书》卷六十二〈刘琨列传〉～679～","w":"刘琨字越石，中山魏昌人，汉中山靖王胜之后也。祖迈，有经国之才，为相国参军、散骑常侍。父蕃，清高冲俭，位至光禄大夫。琨少得俊朗之目，与范阳祖纳俱以雄豪著名。年二十六，为司隶从事。时征虏将军石崇河南金谷涧中有别庐，冠绝时辈，引致宾客，日以赋诗。…","q":[["珍重昔年金谷友，共来泉际话幽魂。","李玖 四丈夫同赋"],["嗣世衰微谁肯忧，二十四友日日空追游。","韦应物 金谷园歌"]]},{"n":"珊瑚枝","d":"","s":"《世说新语》下卷下《汰侈》","w":"石崇与王恺争豪，并穷绮丽，以饰舆服。武帝，恺之甥也，每助恺。尝以一珊瑚树，高二尺许赐恺。枝柯扶疏，世罕其比。恺以示崇。崇视讫，以铁如意击之，应手而碎。恺既惋惜，又以为疾己之宝，声色甚厉。崇曰：「不足恨，今还卿。」乃命左右悉取珊瑚树，有三尺四…","q":[["红锦障收，珊瑚树碎，至今笑石崇王恺。","李咸用 富贵曲"],["季伦怒击珊瑚摧，灵芸整鬓步摇折。","李沇 方响歌"]]},{"n":"季伦锦帐","d":"","s":"《世说新语笺疏》下卷下〈汰侈〉～878～","w":"王君夫以?糒澳釜，石季伦用蜡烛作炊。君夫作紫丝布步障碧绫裹四十里，石崇作锦步障五十里以敌之。石以椒为泥，王以赤石脂泥壁。","q":[]},{"n":"金谷园","d":"","s":"《水经注疏》卷十六〈谷水〉～384～","w":"谷水又东，左会金谷水。水出太白原，东南流，历金谷，谓之金谷水。东南流，径晋卫尉卿石崇之故居也。石季伦《谷金诗集·序》曰：「余以元康七年，从太仆卿出为征虏将军，有别庐在河南界金谷涧中，有清泉茂树，众果竹柏，药草蔽翳。」","q":[["叶落上阳树，草衰金谷园。","于武陵 洛中晴望"],["平阳擅歌舞，金谷盛招携。","刘洎 安德山池宴集"]]},{"n":"锦步障","d":"","s":"《晋书》卷三十三〈石苞列传·（子）石乔·（子）石崇〉～004～","w":"崇字季伦，生于青州，故小名齐奴。少敏惠，勇而有谋。苞临终，分财物与诸子，独不及崇。其母以为言，苞曰：「此儿虽小，后自能得。」年二十馀，为修武令，有能名。入为散骑郎，迁城阳太守。伐吴有功，封安阳乡侯。在郡虽有职务，好学不倦，以疾自解。顷之，拜…","q":[["犹疑施锦帐，堪叹罢朱纨。","侯冽 金谷园花发怀古"],["可怜夹水锦步障，羞数石家金谷园。","李群玉 山榴"]]},{"n":"石家蜡烛","d":"","s":"《世说新语》下卷下《汰侈》","w":"王君夫以饴糒澳釜，石季伦用蜡烛作炊。君夫作紫丝布步障碧绫裹四十里，石崇作锦步障五十里以敌之。石以椒为泥，王以赤石脂泥壁。","q":[["漆灯夜照真无数，蜡炬晨炊竟未休。","李商隐 十字水期韦潘侍御同年不至时韦寓居水次故郭邠宁宅"],["石家蜡烛何曾剪，荀令香炉可待熏。","李商隐 牡丹"]]},{"n":"石季伦","d":"","s":"《晋书》卷三十三《石苞传》附《石崇传》","w":"崇字季伦，生于青州，故小名齐奴。少敏惠，勇而有谋。……财产丰积，室宇宏丽。后房百数，皆曳纨绣，珥金翠。丝竹尽当时之选，庖膳穷水陆之珍。","q":[["齐奴却是来东市，不为红儿死更冤。","罗虬 比红儿诗"],["迭宕孔文举，风流石季伦。","储光羲 秋庭贻马九"]]},{"n":"石崇富","d":"","s":"《晋书》卷三十三〈石苞列传·（子）石乔·（子）石崇〉～004～","w":"崇字季伦，生于青州，故小名齐奴。少敏惠，勇而有谋。苞临终，分财物与诸子，独不及崇。其母以为言，苞曰：「此儿虽小，后自能得。」年二十馀，为修武令，有能名。入为散骑郎，迁城阳太守。伐吴有功，封安阳乡侯。在郡虽有职务，好学不倦，以疾自解。顷之，拜…","q":[]},{"n":"石崇香枣","d":"","s":"《太平御览》卷九六五","w":"《世说新语》：王大将军尝至石崇家，如厕，见漆箱中盛乾枣，本以塞鼻，王遂食尽，群婢莫不笑。","q":[["长筹未必输孙皓，香枣何劳问石崇。","李商隐 药转"]]},{"n":"石尉望尘","d":"","s":"《晋书》卷三十三〈石苞列传·（子）石乔·（子）石崇〉～006～","w":"崇颖悟有才气，而任侠无行检。在荆州，劫远使商客，致富不赀。徵为大司农，以徵书未至擅去官免。顷之，拜太仆，出为征虏将军，假节、监徐州诸军事，镇下邳。崇有别馆在河阳之金谷，一名梓泽，送者倾都，帐饮于此焉。至镇，与徐州刺史高诞争酒相侮，为军司所奏…","q":[]},{"n":"梓泽","d":"","s":"《晋书》卷三十三《石苞传》附《石崇传》","w":"崇有别馆在河阳之金谷，一名梓泽，送者倾都，帐饮于此焉。","q":[["梓泽年光往复来，杜霸游人去不回。","于季子 早春洛阳答杜审言"],["梓泽花犹满，灵和柳未凋。","唐彦谦 汉代"]]}],"71":[{"n":"北郭骚","d":"","s":"《吕氏春秋》卷十二《季冬纪·士节》","w":"齐有北郭骚者，结罘罔，捆蒲苇，织履，以养其母，犹不足，踵门见晏子曰：「窃说先生之义，愿乞所以养母者。」晏子使人分仓粟府金而遗之，辞金受粟。有閒，晏子见疑于景公，出奔，过北郭骚之门而辞。北郭骚沐浴而见晏子曰：「夫子将焉适？」晏子曰：「见疑于齐…","q":[["日暖自萧条，花悲北郭骚。","李贺 感春"],["谁言北郭贫，能分晏婴粟。","钱起 小园招隐"]]},{"n":"渡淮橘成枳","d":"","s":"《晏子春秋》卷六〈内篇杂下·楚王欲辱晏子指盗者为齐人晏子对以橘〉～392～","w":"晏子将至楚，楚闻之，谓左右曰：「晏婴，齐之习辞者也，今方来，吾欲辱之，何以也？」左右对曰：「为其来也，臣请缚一人，过王而行，王曰：『何为者也？』对曰：『齐人也。』王曰：『何坐？』曰：『坐盗。』」晏子至，楚王赐晏子酒，酒酣，吏二缚一人诣王，王…","q":[["渡江之橘踰汶貉，反时易性安能长。","元稹 驯犀"],["未胜晏子江南橘，莫比潘家大谷梨。","崔兴宗 和王维敕赐百官樱桃"]]},{"n":"齐三士","d":"三士桃：喻指用计杀人。唐卢象《追凉历下古城西北隅此地有清泉乔木》：“闲荫七贤地，醉餐三士桃。”","s":"《晏子春秋》卷二《内篇·谏下》","w":"公孙接、田开疆、古冶子事景公，以勇力搏虎闻。晏子过而趋，三子者不起，晏子入见公曰：「臣闻明君之蓄勇力之士也，上有君臣之义，下有长率之伦，内可以禁暴，外可以威敌，上利其功，下服其勇，故尊其位，重其禄。今君之蓄勇力之士也，上无君臣之义，下无长率…","q":[["二桃杀三士，讵假剑如霜。","李白 惧谗"],["世人见我轻鸿毛，力排南山三壮士，齐相杀之费二桃。","李白 梁甫吟"]]},{"n":"圣相","d":"","s":"《晏子春秋》卷八《外篇》","w":"仲尼相鲁，景公患之，谓晏子曰：「邻国有圣人，敌国之忧也。今孔子相鲁若何？」晏子对曰：「君其勿忧。彼鲁君，弱主也；孔子，圣相也。」","q":[["帝得圣相相曰度，贼斫不死神扶持。","李商隐 韩碑"]]},{"n":"脱骖","d":"","s":"《史记》卷六十二〈管晏列传·晏平仲〉～235～","w":"越石父贤，在缧绁中。晏子出，遭之涂，解左骖赎之，载归。弗谢，入闺。久之，越石父请绝。晏子戄然，摄衣冠谢曰：「婴虽不仁，免子于，何子求绝之速也？」石父曰：「不然。吾闻君子诎于不知己而信于知己者。方吾在缧绁中，彼不知我也。夫子既已感寤而赎我，…","q":[["分宅脱骖间，感激怀未济。","杜甫 八哀诗赠秘书监江夏李公邕"],["不知门下客，谁上晏婴骖。","贯休 和毛学士舍人早春"]]},{"n":"晏子裘","d":"晏裘：指生活节俭。唐杜牧《冬至日遇京使发寄舍弟》：“旅馆夜忧姜被冷，暮江寒觉晏裘轻。”","s":"《晏子春秋》卷六《内篇杂下》","w":"景公饮酒，田桓子侍，望见晏子，而复于公曰：「请浮晏子。」公曰：「何故也？」无宇对曰：「晏子衣缁布之衣，麋鹿之裘，栈轸之车，而驾驽马以朝，是隐君之赐也。」","q":[["旅馆夜忧姜被冷，暮江寒觉晏裘轻。","杜牧 冬至日遇京使发寄舍弟"],["高德闻郑履，俭居称晏裘。","武元衡 酬李十一尚书西亭暇日书怀见寄十二韵之作"]]},{"n":"晏御扬扬","d":"","s":"《史记》卷六十二《管晏列传》","w":"晏子为齐相，出，其御之妻从门閒而窥其夫。其夫为相御，拥大盖，策驷马，意气扬扬甚自得也。既而归，其妻请去。夫问其故。妻曰：「晏子长不满六尺，身相齐国，名显诸侯。今者妾观其出，志念深矣，常有以自下者。今子长八尺，乃为人仆御，然子之意自以为足，妾…","q":[["晏御扬扬，五鹿岳岳。","李瀚 蒙求"]]},{"n":"晏子","d":"","s":"《史记》卷六十二〈管晏列传·晏平仲〉～234～","w":"晏平仲婴者，莱之夷维人也。事齐灵公、庄公、景公，以节俭力行重于齐。既相齐，食不重肉，妾不衣帛。其在朝，君语及之，即危言；语不及之，即危行。国有道，即顺命；无道，即衡命。以此三世显名于诸侯。","q":[["还如齐晏子，再见狄梁公。","贯休 闻王慥常侍卒三首"]]},{"n":"晏婴宅","d":"","s":"《春秋左传·昭公三年》","w":"初，景公欲更晏子之宅，曰：「子之宅近市，湫隘嚣尘，不可以居，请更诸爽垲者。」辞曰：「君之先臣容焉，臣不足以嗣之，于臣侈矣。且小人近市，朝夕得所求，小人之利也，敢烦里旅？」","q":[["严陵虽说临溪隐，晏子还闻近市居。","徐夤 赠表弟黄校书辂"]]},{"n":"楹语","d":"","s":"《晏子春秋》卷六《内篇杂下》","w":"晏子病，将死，凿楹纳书焉，谓其妻曰：「楹语也，子壮而示之。」及壮，发书之言曰：「布帛不可穷，穷不可饰；牛马不可穷，穷不可服；士不可穷，穷不可任；国不可穷，穷不可窃也。」","q":[["经出宣尼壁，书留晏子楹。","李商隐 五言述德抒情诗一首四十韵献上杜七兄仆射相公"]]},{"n":"晏子赠行","d":"","s":"《晏子春秋》卷五《内篇杂上》","w":"曾子将行，晏子送之曰：「君子赠人以轩，不若以言。吾请以言之，以轩乎？」曾子曰：「请以言。」晏子曰：「今夫车轮，山之直木也，良匠揉之，其圆中规，虽有槁暴，不复嬴矣，故君子慎隐揉。和氏之璧，井里之困也，良工修之，则为存国之宝，故君子慎所修。今夫…","q":[["相国齐晏子，赠行不及言。","李白 郑鲁郡刘长史迁弘农长史"]]},{"n":"一语折冲遐裔","d":"","s":"《晏子春秋》卷五〈内篇杂上·晋欲攻齐使人往观晏子以礼侍而折其谋〉～325～","w":"晋平公欲伐齐，使范昭往观焉。景公觞之，饮酒酣，范昭曰：「请君之弃樽。」公曰：「酌寡人之樽，进之于客。」范昭已饮，晏子曰：「彻樽，更之。」樽觯具矣，范昭佯醉，不说而起舞，谓太师曰：「能为我调成周之乐乎？吾为子舞之。」太师曰：「冥臣不习。」范昭…","q":[]},{"n":"执鞭","d":"","s":"《史记》卷六十二《管晏传赞》","w":"「假令晏子而在，余虽为之执鞭，所欣慕焉。」唐·司马贞《史记索隐》：「太史公之羡慕仰企平仲之行，假令晏生在世，己虽与之为仆隶，为之执鞭，亦所欣慕。其好贤乐善如此。贤哉良史，可以示人臣之炯戒也。」","q":[["讲序居重席，群儒愿执鞭。","张籍 赠殷山人"],["陆公馀德机云在，如我酬恩合执鞭。","杜牧 怀钟陵旧游四首之一"]]}],"72":[{"n":"客无毡","d":"半毡：指体恤寒士。宋胡宿《赵宗道归辇下》：“半毡未暖还伤别，一臂初交又解携。”","s":"《梁书》卷三十六〈江革列传〉～522～","w":"江革字休映，济阳考城人也。祖齐之，宋尚书金部郎。父柔之，齐尚书仓部郎，有孝行，以母忧毁卒。革幼而聪敏，早有才思，六岁便解属文，柔之深加赏器，曰：「此儿必兴吾门。」九岁丁父艰，与弟观同生，少孤贫，傍无师友，兄弟自相训勖，读书精力不倦。十六丧母…","q":[]},{"n":"鲍谢","d":"","s":"《九家集注杜诗》卷五〈遣兴五首〉","w":"〈遣兴五首〉其五：「吾怜孟浩然，裋褐即长夜。赋诗何必多，往往凌鲍谢。清江空旧鱼【清江旧鱼美】，春雨馀甘蔗。南望东南云，令人几悲吒。」","q":[]},{"n":"红药翻阶","d":"","s":"《昭明文选》卷三十〈诗己·杂诗下·直中书省〉～408～","w":"紫殿肃阴阴，彤庭赫弘敞。风动万年枝，日华承露掌。玲珑结绮钱，深沈映朱网。红药当阶翻，苍苔依砌上。兹言翔凤池，鸣佩多清响。信美非吾室，中园思偃仰。朋情以郁陶，春物方骀荡。安得凌风翰，聊恣山泉赏。","q":[]},{"n":"何谢","d":"","s":"《梁书》卷四十九《文学传上·何逊传》","w":"初，逊文章与刘孝绰并见重于世，世谓之「何刘」。世祖著论论之云：「诗多而能者沈约，少而能者谢朓、何逊。」","q":[["诗人识何谢，居士别宗雷。","李端 得山中道友书寄苗钱二员外"],["孤悄欺何谢，云波不可寻。","栖白 赠李溟秀才"]]},{"n":"佳丽地","d":"","s":"《昭明文选》卷二十八〈诗戊·乐府下·鼓吹曲〉～33～","w":"江南佳丽地，金陵帝王州。逶迤带渌水，迢递起朱楼。飞甍夹驰道，垂杨荫御沟。凝笳翼高盖，鼓送华辀。献纳云台表，功名良可收。","q":[["谢朓诗中佳丽地，夫差传里水犀军。","杜牧 润州二首"]]},{"n":"解道澄江如练","d":"","s":"《全唐诗》卷一百六十六〈金陵城西楼月下吟〉","w":"金陵夜寂凉风发，独上高楼望吴越。白云映水摇空城，白露垂珠滴秋月。月下沈吟久不归，古来相接眼中稀。解道澄江净如练，令人长忆谢玄晖。","q":[]},{"n":"练色铺江","d":"","s":"《昭明文选》卷二十七〈诗戊·行旅下·晚登三山还望京邑〉～263～","w":"灞涘望长安，河阳视京县。白日丽飞甍，参差皆可见。馀霞散成绮，澄江静如练。喧鸟覆春洲，杂英满芳甸。去矣方滞淫，怀哉罢欢宴。有情知望乡，谁能缜不变？","q":[["谢朓留霞绮，甘宁弃锦张。","唐彦谦 红叶"],["练色铺江晚，潮声逐渚回。","萧遘 春诗"]]},{"n":"两谢","d":"","s":"《宋书》卷六十七〈谢灵运列传〉～743～","w":"祖伐长安，骠骑将军道怜居守，版为咨议参军，转中书侍郎，又为世子中军咨议，黄门侍郎。奉使慰劳高祖于彭城，作撰征赋。……少帝即位，权在大臣，灵运构扇异同，非毁执政，司徒徐羡之等患之，出为永嘉太守。郡有名山水，灵运素所爱好，出守既不得志，遂肆意游…","q":[["孰知二谢将能事，颇学阴何苦用心。","杜甫 解闷十二首"]]},{"n":"摸索何刘沈谢","d":"","s":"《隋唐嘉话》中～26～","w":"许敬宗性轻傲，见人多忘之。或谓其不聪，曰：「卿自难记，若遇何、刘、沈、谢，暗中摸索著，亦可识。」","q":[]},{"n":"何刘","d":"","s":"《梁书》卷四十九〈文学列传上·何逊〉～693～","w":"初，逊文章与刘孝绰并见重于世，世谓之「何刘」。世祖著论论之云：「诗多而能者沈约，少而能者谢朓、何逊。」","q":[["何刘沈谢力未工，才兼鲍昭愁绝倒。","杜甫 苏端薛复筵简薛华醉歌"]]},{"n":"谢宣城","d":"","s":"《南齐书》卷四十七〈谢朓列传〉～825～","w":"谢朓字玄晖，陈郡阳夏人也。祖述，吴兴太守。父纬，散骑侍郎。朓少好学，有美名，文章清丽。……高宗辅政，以朓为骠骑咨议，领记室，掌霸府文笔。又掌中书诏诰，除秘书丞，未拜，仍转中书郎。出为宣城太守，以选复为中书郎。……朓善草隶，长五言诗，沈约常云…","q":[["玄晖翻佐理，闻到郡斋频。","刘长卿 奉和赵给事使君留赠李婺州舍人兼谢舍人别驾之什"],["林中阮生集，池上谢公题。","刘长卿 奉陪郑中丞自宣州解印与诸侄宴余干后溪"]]},{"n":"谢文学","d":"","s":"《南齐书》卷四十七《谢朓传》","w":"朓少好学，有美名，文章清丽。解褐豫章王太尉行参军，度随王东中郎府，转王俭卫军东閤祭酒，太子舍人、随王镇西功曹，转文学。","q":[["因知谢文学，晓望比尘埃。","司空曙 雨夜见投之作"],["如何谢文学，还起会云吟。","孟郊 同茅郎中使君送河南裴文学"]]},{"n":"宣城畏曝鳃","d":"","s":"《昭明文选》卷三十南朝齐·谢玄晖（朓）《观朝雨》","w":"朔风吹飞雨，萧条江上来。既洒百常观，复集九成台。空濛如薄雾，散漫似轻埃。平明振衣坐，重门犹未开。耳目暂无扰，怀古信悠哉。戢翼希骧首，乘流畏曝鳃。","q":[["始信宜城守，乘流畏曝腮。","钱起 窃秋对雨"]]}],"73":[{"n":"龙梭","d":"","s":"《太平御览》卷四十八〈地部十三·南楚诸山·钓矶山〉～363～","w":"南朝宋·刘敬叔《异苑》：「钓矶山者，陶侃尝钓于此山下，水中得织梭一枚，还挂壁上。后化成赤龙，从空而去。其山石上，犹有侃迹存焉。」","q":[["落笔思成虎，县梭待化龙。","李咸用 夜吟"],["陶家壁上精灵物，风雨未来终是梭。","李咸用 宿渔家"]]},{"n":"剪髻","d":"剪髻：喻贤母教子有方，或喻诚心待客。宋黄庭坚《乐寿县君吕氏挽词二首》之一：“剪舍宾筵盛，齐眉妇礼闲。”","s":"《晋书》卷六十六《陶侃传》","w":"侃早孤贫，为县吏。鄱阳孝廉范逵尝过侃，时仓卒无以待宾，其母乃截发得双髲，以易酒肴，乐饮极欢，虽仆从亦过所望。","q":[["自陈剪髻鬟，鬻市充杯酒。","杜甫 送重表侄王砅"]]},{"n":"老子婆娑","d":"","s":"《晋书》卷六十六〈陶侃列传〉～778～","w":"侃在军四十一载，雄毅有权，明悟善决断。自南陵迄于白帝数千里中，路不拾遗。苏峻之役，庾亮轻进失利。亮司马殷融诣侃谢曰：「将军为此，非融等所裁。」将军王章至，曰：「章自为之，将军不知也。」侃曰：「昔殷融为君子，王章为小人；今王章为君子，殷融为小…","q":[]},{"n":"武昌柳","d":"陶公柳：咏柳，或喻军纪严明。宋苏轼《游武昌寒溪西山寺》：“空传孙郎石，无复陶公柳。”","s":"《世说新语笺疏》上卷下〈政事〉～79～","w":"陶公性检厉，勤于事。南朝梁·刘孝标注引《晋阳秋》曰：「侃练核庶事，勤务稼穑，虽戎陈武士，皆劝厉之。有奉馈者，皆问其所由。若力役所致，欢喜慰赐；若他所得，则呵辱还之。是以军民勤于农稼，家给人足。性纤密好问，颇类赵广汉。尝课营种柳，都尉夏施盗拔…","q":[["缘忧武昌柳，遂忆洛阳花。","李商隐 病中闻河东公乐营置酒口占寄上"]]},{"n":"陶公战舰","d":"","s":"《晋书》卷六十六〈陶侃列传〉～769～","w":"陈敏之乱，弘以侃为江夏太守，加鹰扬将军。……又加侃为督护，使与诸军并力距恢。侃乃以运船为战舰，或言不可，侃曰：「用官物讨官贼，但须列上有本末耳。」于是击恢，所向必破。侃戎政齐肃，凡有虏获，皆分士卒，身无私焉。后以母忧去职。尝有二客来吊，不哭…","q":[["陶公战舰空滩雨，贾傅承尘破庙风。","李商隐 潭州"]]},{"n":"陶侃酒限","d":"","s":"《晋书》卷六十六〈陶侃列传〉～778～","w":"侃每饮酒有定限，常欢有馀而限已竭，浩等劝更少进，侃悽怀良久曰：「年少曾有酒失，亡亲见约，故不敢踰。」","q":[["陈遗饭感，陶侃酒限。","李瀚 蒙求"]]},{"n":"陶侃明鉴","d":"","s":"《晋书》卷六十六〈陶侃列传〉～778～","w":"侃在军四十一载，雄毅有权，明悟善决断。自南陵迄于白帝数千里中，路不拾遗。苏峻之役，庾亮轻进失利。亮司马殷融诣侃谢曰：「将军为此，非融等所裁。」将军王章至，曰：「章自为之，将军不知也。」侃曰：「昔殷融为君子，王章为小人；今王章为君子，殷融为小…","q":[]},{"n":"陶使君","d":"","s":"《晋书》卷六十六《陶侃传》","w":"侃之佐史辞诣王敦曰：「州将陶使君孤根特立，从微至著，……太兴初，进号平南将军，寻加都督交州军事。及王敦举兵反，诏侃以本官领江州刺史，寻转都督、湘州刺史。","q":[["闲心近掩陶使君，诗兴遥齐谢康乐。","韩翃 赠兖州孟都督"]]},{"n":"陶武威","d":"","s":"《晋书》卷六十六《陶侃传》附《陶舆传》","w":"臻弟舆，果烈善战，以功累迁武威将军。……自是每战辄克，贼望见舆军，相谓曰：「避陶武威。」无敢当者。","q":[["上客钟大理，主人陶武威。","韩翃 送卢大理赵侍御祭东岳兼寄孟兖州"]]},{"n":"陶庾","d":"","s":"《晋书》卷六十六〈陶侃列传〉～776～","w":"诏侃都督江州，领刺史，增置左右长史、司马、从事中郎四人，掾属十二人。侃旋于巴陵，因移镇武昌。","q":[]},{"n":"运百甓","d":"运甓：喻指因立志建功立业而勤勉自励。唐元稹《纪怀赠李六户曹崔二十功曹五十韵》：“运甓调辛苦，闻鸡屡寝兴。”；运甓翁：喻不安悠闲、奋发向上之人。宋黄庭坚《寄南阳谢外舅》：“谁令运甓翁，见谓牧猪奴。”","s":"《裴子语林》～3～","w":"陶太尉既作广州，优游无事。常朝自运甓于斋外，暮运于斋内。人问之，陶曰：『吾方致力中原，恐为尔优游，不复堪事。』","q":[["运甓调辛苦，闻鸡屡寝兴。","元稹 纪怀赠李六户曹崔二十功曹五十韵"],["眼为看书损，肱因运甓伤。","白居易 渭村退居寄礼部崔侍郎翰林钱舍人诗一百韵"]]},{"n":"种柳营中","d":"","s":"《晋书》卷六十六〈陶侃列传〉～778～","w":"侃在军四十一载，雄毅有权，明悟善决断。自南陵迄于白帝数千里中，路不拾遗。苏峻之役，庾亮轻进失利。亮司马殷融诣侃谢曰：「将军为此，非融等所裁。」将军王章至，曰：「章自为之，将军不知也。」侃曰：「昔殷融为君子，王章为小人；今王章为君子，殷融为小…","q":[["种柳营中暗，题书赐馆娃。","李贺 梁公子"]]}],"74":[{"n":"长君","d":"","s":"《汉书》卷五十四〈李广苏建列传·苏建·（子）苏武〉～2464～","w":"初，武与李陵俱为侍中，武使匈奴明年，陵降，不敢求武。久之，单于使陵至海上，为武置酒设乐，因谓武曰：「单于闻陵与子卿素厚，故使陵来说足下，虚心欲相待。终不得归汉，空自苦亡人之地，信义安所见乎？前长君为奉车，从至雍棫阳宫，扶辇下除，触柱折辕，劾…","q":[]},{"n":"大刀头","d":"刀环有约：环、还谐音，用以咏思乡之情。清尤侗《挽叶元礼台人三首》之二：“刀环有约劳恩妇，剑铁无家泣老亲。”","s":"《汉书》卷五十四〈李广苏建列传·李广·（孙）李陵〉～2458～","w":"昭帝立，大将军霍光、左将军上官桀辅政，素与陵善，遣陵故人陇西任立政等三人俱至匈奴招陵。立政等至，单于置酒赐汉使者，李陵、卫律皆侍坐。立政等见陵，未得私语，即目视陵，而数数自循其刀环，握其足，阴谕之，言可还归汉也。","q":[["佳期应借问，为报在刀头。","宋之问 望月有怀"],["百战苦不归，刀头怨明月。","常建 塞上曲"]]},{"n":"丁年","d":"","s":"《昭明文选》卷四十一〈书上·答苏武书〉～852～","w":"且足下昔以单车之使，适万乘之虏，遭时不遇，至于伏剑不顾，流离辛苦，几死朔北之野。丁年奉使，皓首而归。老母终堂，生妻去帷。此天下所希闻，古今所未有也。蛮貊之人，尚犹嘉子之节，况为天下之主乎？陵谓足下，当享茅土之荐，受千乘之赏。唐·李善曰：「丁…","q":[]},{"n":"李少卿","d":"","s":"《史记》卷一○九《李将军列传》附《李陵传》","w":"李陵既壮，选为建章监，监诸骑。善射，爱士卒。天子以为李氏世将，而使将八百骑。尝深入匈奴二千馀里，过居延视地形，无所见虏而还。拜为骑都尉，将丹阳楚人五千人，教射酒泉、张掖以屯卫胡。数岁，天汉二年秋，贰师将军李广利将三万骑击匈奴右贤王于祁连天山…","q":[["不是史迁书与说，谁知孤负李陵心。","司空图 狂题十八首之三"],["亭伯去安在，李陵降未归。","李白 奔亡道中五首之二"]]},{"n":"河梁","d":"","s":"《昭明文选》卷二十九〈诗己·杂诗上·与苏武诗三首〉～353～","w":"〈与苏武诗三首〉其三：「携手上河梁，游子暮何之？徘徊蹊路侧，悢悢不得辞。行人难久留，各言长相思。安知非日月，弦望自有时。」","q":[["落花如便去，楼上即河梁。","唐彦谦 春残"],["河梁暮相遇，草草不复言。","孟郊 感怀"]]},{"n":"空弮","d":"","s":"《汉书》卷六十二〈司马迁列传〉～2729～","w":"司马迁〈报任安书〉：「且李陵提步卒不满五千，深践戎马之地，足历王庭，垂饵虎口，横挑彊胡，卬亿万之师，与单于连战十馀日，所杀过当。虏救死扶伤不给，旃裘之君长咸震怖，乃悉徵左右贤王，举引弓之民，一国共攻而围之。转斗千里，矢尽道穷，救兵不至，士卒…","q":[["空拳转斗地，数板不沈城。","李商隐 送千牛李将军赴阙五十韵"],["纵有命世才，不如一空弮。","皮日休 鲁望昨以五百言见贻过有褒美内揣庸陋弥增愧悚因成一千言上述吾唐文物之盛次叙相得之欢亦迭和之微旨也"]]},{"n":"兰山羞","d":"","s":"《汉书》卷五十四《李广传》","w":"天汉二年，贰师将军伐匈奴。李陵自请带一队人马「到兰干山南以分单于兵。」遭到匈奴数万人的包围。「汉军南行，未至鞮汗山，一日五十万矢皆尽，即弃车去。」李陵与韩延年突围，韩战死，「陵曰：『无面目报陛下！』遂降。」","q":[["莫作兰山下，空令汉国羞。","骆宾王 夕次蒲类津（一作晚泊蒲类）"]]},{"n":"李都尉","d":"","s":"《汉书》卷五十四《李广传》附《李陵传》","w":"「武帝以为有广之风，使将八百骑，深入匈奴二千馀里，过居延视地形，不见虏，还。拜为骑都尉，将勇敢五千人，教射酒泉、张掖以备胡。」","q":[["昔从李都尉，双鞬照马蹄。","戎昱 从军行"]]},{"n":"李陵寄书","d":"李将军：咏异域流亡之人。唐鲍溶《陇头水》：“生归苏属国，死别李将军。”","s":"《昭明文选》卷四十一汉·李少卿（陵）《答苏武书》","w":"「自从初降，以至今日，身之困穷，独坐愁苦。……前书仓卒，未尽所怀，故复略而言之。……人绝路殊，生为别世之人，死为异域之鬼，长与足下生死辞矣。」","q":[["数篇留别我，羞杀李将军。","杜牧 赠张祜"],["李陵寄书别苏武，自有生人无此苦。","顾况 刘禅奴弹琵琶歌"]]},{"n":"李陵诗","d":"李陵诗：指悲苦之辞。唐薛能《题盐铁李尚书沪州别业》：“备足好中还有闲，许昌军里李陵诗。”","s":"《昭明文选》卷二十九汉·李少卿（陵）《与苏武三首》","w":"「良时不再至，离别在须臾。」（其一）「嘉会难再遇，三载为千秋。」（其二）「携手上河梁，游子暮何之。……努力崇明德，皓首以为期。」（其三）","q":[["备足好中还有阙，许昌军里李陵诗。","薛能 题盐铁李尚书浐州别业"]]},{"n":"少卿应识子卿心","d":"","s":"《昭明文选》卷四十一汉·李少卿（陵）《答苏武书》","w":"嗟乎子卿！人之相知，贵相知心。","q":[["流落天涯谁见问，少卿应识子卿心。","韦庄 钟陵夜阑作"]]},{"n":"书报天涯","d":"","s":"《昭明文选》卷四十一〈书上·李少卿答苏武书〉～847～","w":"自从初降，以至今日，身之穷困，独坐愁苦，终日无，但见异类。韦鞲毳幕，以御风雨。膻肉酪浆，以充饥渴。举目言笑，谁与为欢？胡地玄冰，边土惨裂，但闻悲风萧条之声。凉秋九月，塞外草衰。夜不能寐，侧耳远听，胡笳互动，牧马悲鸣，吟啸成群，边声四起。晨坐…","q":[["李陵没胡沙，苏武还汉家。鸿雁向西北，因书报天涯。","李白 千里思"],["传书问苏武，陵也独何心。","郑愔 胡笳曲"]]}],"75":[{"n":"长沮桀溺","d":"","s":"《论语注疏·微子》","q":[["从他烟棹更南去，休向津头问去程。","司空图 淅上（作江淅上是今郧阳府地在秦楚之交故有秦云楚两之句）"],["苦作南行约，劳生始问津。","周贺 赠皎然上人（一本无皎字）"]]},{"n":"负米归","d":"负米：喻奉养父母，或喻为奉养父母而在外谋求禄米。唐杜甫《八哀诗·故秘书少监武功苏公源明》：“负米晚为身，每食脸必泫。”","s":"《孔子家语》卷二《致思》","q":[["负米晚为身，每食脸必泫。","杜甫 八哀诗（并序）故秘书少监武功苏公源明"],["负米力葵外，读书秋树根。","杜甫 孟氏（集有过孟十二仓曹十四主簿兄弟诗）"]]},{"n":"固穷","d":"","s":"《论语注疏·卫灵公》","q":[["自乐固穷心，天意在何处。","于濆 富农诗"],["道家贵至柔，儒生何固穷。","张九龄 杂诗五首"]]},{"n":"洁身乱伦","d":"","s":"《论语·微子》","q":[["故知忠孝生天性，洁身乱伦安足拟。","韩愈 寄卢仝"]]},{"n":"蒲密","d":"","s":"《昭明文选》卷五十五晋·陆士衡（机）《演连珠五十首》其三十二","q":[["蒲密遥千载，鸣琴始一追。","张说 徐高御挽歌"]]},{"n":"杀伐仿佛","d":"","s":"《孔子家语》卷八《辨乐》","q":[["耳闻读书声，杀伐灾髣髴。","杜甫 题衡山县文宣王庙新学堂呈陆宰"]]},{"n":"十哲","d":"","s":"《旧唐书》卷二十四〈礼仪志四〉","q":[]},{"n":"滔滔天下","d":"","s":"《论语》卷九《微子》","q":[["衰世难修道，花时不称贫。滔滔天下者，何处问通津。","李咸用 春日忆李白"]]},{"n":"无力犹能肆汝杯","d":"","s":"《论语注疏·宪问》","q":[]},{"n":"由之瑟","d":"升堂：喻学识造诣精深。唐杜甫《戏题寄上汉中王三首》之三：“空余枚叟在，应念早升堂。”；由也瑟：指自谦学识不够精深。唐窦庠《酬韩愈侍郎登岳阳楼见赠》：“自悲由也瑟，敢坠孔悝铭。”","s":"《论语注疏·先进》","q":[["空余枚叟在，应念早升堂。","杜甫 戏题寄上汉中王三首之三"],["敢衒由之瑟，甘循赐也墙。","杨巨源 上刘侍中"]]},{"n":"仲由缨","d":"仲由缨：咏慷慨赴死。唐李商隐《送千牛李将军赴阀五十韵》：“幽囚苏武节，弃市仲由缨。”","s":"《史记》卷六十七《仲尼弟子列传》","q":[["子路已成血，嵇康今尚嗤。","孟郊 乱离"],["勇果鲁仲由，文赋蜀相如。","崔璐 览皮先辈圣制因作十韵以寄用伸款仰"]]},{"n":"仲由","d":"仲由：喻不畏牺牲的勇士。唐崔潞《览皮先辈盛制因作十韵以寄用伸款仰》：“勇果鲁仲由，文赋蜀相如。”","s":"《史记》卷六十七〈仲尼弟子列传〉","q":[]}],"76":[{"n":"屋三间","d":"","s":"《世说新语笺疏》中卷下〈赏誉〉","q":[["谁怜芳草生三径，参佐桥西陆士龙。","温庭筠 春暮宴罢寄宋寿先辈"]]},{"n":"陆弟","d":"","s":"《诗品》卷中","q":[["香名冠二陆，精鉴逢山涛。","刘长卿 客舍赠别韦九建赴任河南韦十七造赴任郑县就便觐省"],["洛中推二陆，莫久恋乡关。","喻凫 送石贲归吴兴"]]},{"n":"二十四友","d":"","s":"《晋书》卷六十二〈刘琨列传〉","q":[["珍重昔年金谷友，共来泉际话幽魂。","李玖 四丈夫同赋"],["嗣世衰微谁肯忧，二十四友日日空追游。","韦应物 金谷园歌"]]},{"n":"凤雏","d":"","s":"《晋书》卷五十四〈陆云列传〉","q":[["寄人龙种瘦，失母凤雏痴。","李商隐 杨本胜说于长安见小男阿衮"],["凤穴雏皆好，龙门客又新。","杜甫 奉赠鲜于京兆二十韵"]]},{"n":"华亭鹤","d":"","s":"《世说新语》下卷下《尤悔》","q":[["华亭失侣鹤，乘轩宠遂终。","孔德绍 赋得华亭鹤"],["死忆华亭闻唳鹤，老忧王室泣铜驼。","李商隐 曲江"]]},{"n":"陆机兄弟","d":"","s":"《三国志》卷五十八〈吴书·陆抗〉","q":[["洛水桥边雁影疏，陆机兄弟驻行车。","李益 中桥北送穆氏兄弟应制戏赠萧二策"],["士衡兄弟旧齐名，还似当年在洛城。","武元衡 夏日寄陆三达陆四逢并王念八仲周"]]},{"n":"士龙笑","d":"","s":"《晋书》卷五十四〈陆云列传〉","q":[["谁惮士龙多笑疾，美髭终类晋司空。","李商隐 奉和太原公送前杨秀才戴兼招杨正字戎"]]},{"n":"陆机云","d":"","s":"《晋书》卷五十四〈陆云列传〉","q":[]},{"n":"陆浚仪","d":"","s":"《晋书》卷五十四《陆云传》","q":[["今日潘怀县，同时陆浚仪。","杜甫 九日杨奉先会白水崔明府"]]},{"n":"陆士龙","d":"云间陆士龙：指有才华者。宋苏轼《次韵刘景文西湖席上》：“将辞邺下刘公斡，却见云间陆士龙。”","s":"《世说新语笺疏》下卷下〈排调〉","q":[["却忆士龙宾阁，清琴绿竹萧萧。","李嘉祐 白田西忆楚州使君弟"],["日下徒推鹤，天涯正对萤。","李商隐 奉寄安国大师兼简子蒙"]]},{"n":"二陆入洛","d":"","s":"《三国志》卷五十八〈吴书·陆逊传·陆抗〉","q":[["陆机初入洛，孙楚又游吴。","储嗣宗 早春怀薛公裕"],["陆云还入洛，潘岳更张筵。","李端 送杨少府赴阳翟"]]},{"n":"张华见陆云","d":"","s":"《晋书》卷三十六《张华传》","q":[["不知何处清风夕，拟使张华见陆云。","马异 答卢仝结交诗"]]}],"77":[{"n":"西王母","d":"","s":"《穆天子传》卷三","q":[["听者即王母，泠泠和瑟琴。","储光羲 升天行贻卢六健"],["君看西王母，千载美容颜。","储光羲 田家杂兴八首"]]},{"n":"绿耳","d":"八骏：指骏马。唐韦应物《酬郑户曹骊山感怀》：“万马自腾踏，八骏按辔行。”","s":"《列子集释》卷三〈周穆王篇〉","q":[["巡非瑶水远，迹是雕墙后。","杜甫 九成宫"],["来参八骏列，不假贰师功。","周存 西戎献马"]]},{"n":"白环","d":"","s":"《宋书》卷二十九《符瑞志下》","q":[["不知何国致白环，复道诸山得银瓮。","杜甫 洗兵马（原注。收京后作。）"]]},{"n":"许飞琼","d":"","s":"《太平广记》卷三〈神仙三·汉武帝〉","q":[["碧玉妆粉比，飞琼秾艳均。","孟郊 南阳公请东樱桃亭子春宴"],["解佩空怜郑交甫，吹箫不逐许飞琼。","李康成 玉华仙子歌"]]},{"n":"龟山","d":"","s":"旧题汉·桓驎《西王母传》","q":[["羽车潜下玉龟山，尘世何由睹蕣颜。","严休复 唐昌观玉蕊花折有仙人游怅然成二绝"]]},{"n":"旷原","d":"","s":"《穆天子传》卷三《旷原大猎章》","q":[["阆风入辙迹，旷原延冥搜。","杜甫 奉同郭给事汤东灵湫作"]]},{"n":"曼倩风流","d":"","s":"《太平御览》卷一百八十八〈居处部十六·〉2～","q":[]},{"n":"青鸟使","d":"青鸟：指神仙，或爱情的使者。唐李侨《拟古东飞伯劳西飞燕》：“传书青鸟迎萧凤，巫岭荆台一通梦。”","s":"《山海经·山经》卷二〈西山经〉","q":[["寄音青鸟翼，谢尔碧海流。","刘复 游仙"],["得意紫鸾休舞镜，断踪青鸟罢衔笺。","刘损 愤惋诗三首"]]},{"n":"神母呈图","d":"","s":"《太平御览》卷八十一","q":[["献图开益地，张乐奏钧天。","张说 奉和圣制暇日与兄弟同游兴庆宫作应制"],["六龙日驭天行健，神母呈图地道光。","鲍溶 忆郊天"]]},{"n":"瑶池","d":"","s":"《穆天子传》卷一","q":[["所宜巢三鸟，影入瑶池碧。","刘驾 琪树下因吟六韵呈先达者"],["周王久谢瑶池赏，汉主悬惭玉树宫。","姚崇 奉和圣制夏日游石淙山"]]},{"n":"玉山","d":"玉山：喻男子体形或醉态。唐李白《襄阳歌》：“清风朗月不用一钱买，玉山自倒非人推。”","s":"《山海经·西山经》","q":[["未谙沧海路，何处玉山岑。","李商隐 摇落"],["玉山高与阆风齐，玉水清流不贮泥。","李商隐 玉山"]]},{"n":"紫云车","d":"","s":"《博物志》卷八《史补》","q":[["聘之碧瑶佩，载以紫云车。","杜牧 张好好诗"]]}],"78":[{"n":"安刘","d":"","s":"《史记》卷八《高祖本纪》","q":[["诛吕鬼神动，安刘天地开。","高适 酬裴员外以诗代书"]]},{"n":"长者车","d":"长者车：咏贫寒而有才者。唐张九龄《送宛句赵少府》。“林下纷相送，多逢长者车。”","s":"《史记》卷五十六〈陈丞相世家〉","q":[["辙迹陈家巷，诗书孟子邻。","张九龄 与袁补阙寻蔡拾遗"],["林下纷相送，多逢长者车。","张九龄 送宛句赵少府"]]},{"n":"陈平","d":"","s":"《史记》卷五十六《陈丞相世家》","q":[["陈平无产业，尼父倦东西。","孟浩然 久滞越中贻谢南池会稽贺少府"],["汲黯言当直，陈平智本奇。","崔融 哭蒋詹事俨"]]},{"n":"陈平不久贫","d":"","s":"《史记》卷五十六《陈丞相世家》","q":[["也闻阮籍寻常醉，见说陈平不久贫。","崔峒 赠元秘书"]]},{"n":"临俎","d":"陈平社：指人在生活琐事中显现才能。金李俊民《即事》：“谁能宰似陈平社，那免悲如宋玉秋？”","s":"《史记》卷五十六《陈丞相世家》","q":[["今年社日分馀肉，不值陈平又不均。","刘言史 嘉兴社日"],["陈平亦分肉，太史竟论功。","杜甫 社日两篇"]]},{"n":"横理庚庚","d":"","s":"《史记》卷十〈孝文本纪〉","q":[]},{"n":"决策欺陈","d":"","s":"《史记》卷五十六《陈丞相世家》","q":[["勒功思比宪，决略暗欺陈。","骆宾王 咏怀古意上裴侍郎"]]},{"n":"六奇","d":"","s":"《史记》卷五十六〈陈丞相世家〉","q":[["未展六奇术，先亏一篑功。","李世民 伤辽东战亡"],["对敌六奇举，临戎八阵张。","李世民 宴中山"]]},{"n":"平勃","d":"","s":"《汉书》卷二十三〈刑法志〉","q":[]},{"n":"席门","d":"席门：指贫居。唐罗邺《自遣》：“焚鱼酌醴醉尧代，吟向席门聊自娱。”","s":"《史记》卷五十六〈陈丞相世家〉","q":[["还思长者辙，恐避席为门。","杜甫 弊庐遣兴奉寄严公"],["焚鱼酌醴醉尧代，吟向席门聊自娱。","罗邺 自遗"]]},{"n":"萧陈","d":"","s":"《史记》卷五十六《陈丞相世家》","q":[["智勇冠终古，萧陈难与群。","李白 送张秀才谒高中丞"]]},{"n":"养虎","d":"","s":"《史记》卷七《项羽本纪》","q":[["嗾獒翻丑正，养虎欲求全。","韩偓 感事三十四韵"]]}],"79":[{"n":"安刘","d":"","s":"《史记》卷八《高祖本纪》","q":[["诛吕鬼神动，安刘天地开。","高适 酬裴员外以诗代书"]]},{"n":"给丧","d":"","s":"《史记》卷五十七《绛侯周勃世家》","q":[["给丧蹶张辈，廊庙冠峨危。","杜牧 杜秋娘诗"]]},{"n":"绛灌","d":"","s":"《史记》卷十八《高祖功臣侯者年表》","q":[["汉家绛灌余兵气，晋代浮虚安足贵。","张说 城南亭作"],["物忌忠良表是非，朝驱绛灌为雠敌。","李绅 逾岭峤止荒陬抵高要"]]},{"n":"绛侯","d":"","s":"《史记》卷五十七〈绛侯周勃世家〉","q":[]},{"n":"迎代邸","d":"","s":"《汉书》卷四《文帝纪》","q":[["事殊迎代邸，喜异赏朱虚。","杜甫 赠李八秘书别三十韵"],["旧居从代邸，新陇入文园。","皇甫冉 故齐王赠承天皇帝挽歌"]]},{"n":"郦寄卖友","d":"","s":"《史记》卷九十五〈樊郦滕灌列传·郦商〉","q":[["郦寄卖友，纪信诈帝。","李瀚 蒙求"]]},{"n":"平勃","d":"","s":"《汉书》卷二十三〈刑法志〉","q":[]},{"n":"三十六将军","d":"","s":"《史记》卷一百六〈吴王濞列传〉","q":[["汉家三十六将军，东方雷动横阵云。","柳宗元 古东门行"]]},{"n":"右袒","d":"","s":"《史记》卷九《吕太后本纪》","q":[["左牵犬马诚难测，右袒簪缨最负恩。","韩偓 八月六日作四首"]]},{"n":"狱吏尊","d":"","s":"《史记》卷五十七《绛侯周勃世家》","q":[["寄谢韩安国，何惊狱吏尊。","陈子昂 宴胡楚真禁所"]]},{"n":"周勃","d":"","s":"《史记》卷五十七《绛侯周勃世家》","q":[["不知周勃者，荣幸定何如。","宋璟 奉和御制璟与张说源乾曜同日上官命宴都堂赐诗应制"]]},{"n":"左袒","d":"","s":"《汉书》卷三《高后纪》","q":[["南军不袒左边袖，四老安刘是灭刘。","杜牧 题商山四皓庙一绝"],["烈烈张汉阳，左袒清诸武。","皇甫澈 赋四相诗（并序）赋四相诗（并序）赋四相诗（并序）中书令钟绍京赋四相诗（并序）赋四相诗（并序）礼部尚书门下侍平章事李山见赋四相诗（并序），赋四相诗（并序）门下侍郎平章事王缙"]]}],"80":[{"n":"鲍鱼腥","d":"","s":"《史记》卷六《秦始皇本纪》","q":[["刘彻茂陵多滞骨，嬴政梓棺费鲍鱼。","李贺 苦昼短"],["欲厌东南气，翻伤掩鲍车。","李显 幸秦始皇陵"]]},{"n":"上蔡门","d":"黄犬悲：指为官受害而追悔莫及。宋苏轼《雨中过舒教授》：“飞鸢悔前笑，黄犬悲晚悟。”","s":"《史记》卷八十七〈李斯列传〉","q":[["赤龙已赴东方暗，黄犬徒怀上蔡悲。","储嗣宗 长安怀古"],["青蝇岂独悲虞氏，黄犬应闻笑李斯。","李德裕 到恶溪夜泊芦岛"]]},{"n":"秦坑","d":"","s":"《史记》卷六〈秦始皇本纪〉","q":[["秦火不爇舌，秦火空爇文。","孟郊 秋怀"],["政烦方改篆，愚俗乃焚书。","李显 幸秦始皇陵"]]},{"n":"仓中鼠","d":"","s":"《史记》卷八十七〈李斯列传〉","q":[["安羡仓中鼠，危同幕上禽。","韦庄 同旧韵"],["李斯不向仓中悟，徐福应无物外游。","韦庄 咸阳怀古"]]},{"n":"词异秦丞相","d":"","s":"《史记》卷六《秦始皇本纪》","q":[["词异秦丞相，铭非窦冠军。","韦蟾 上元三首"]]},{"n":"德馨神歆","d":"","s":"《尚书·周书·君陈》","q":[["竹实凤所食，德馨神所歆。","韩愈 孟生诗"]]},{"n":"李斯","d":"","s":"《史记》卷八十七《李斯列传》","q":[["傅说版筑臣，李斯鹰犬人。歘起匡社稷，宁复长艰辛。","李白 冬夜醉宿龙门觉起言志"],["陆机雄才岂自保，李斯税驾苦不早。华亭鹤唳讵可闻，上蔡苍鹰何足道。","李白 行路难三首之三"]]},{"n":"李斯溷鼠","d":"李斯溷鼠：喻指人热衷名利。唐李咸用《物情》：“李斯涵鼠心应动，庄叟泥龟意已坚。”","s":"《史记》卷八十七《李斯列传》","q":[["李斯溷鼠心应动，庄叟泥龟意已坚。","李咸用 物情"],["长笑李斯称溷鼠，每多庄叟喻牺牛。","薛逢 惊秋"]]},{"n":"李斯忌韩非","d":"","s":"《史记》卷六十三《韩非列传》","q":[["勾践岂能容范蠡，李斯何暇救韩非。","孟迟 寄浙右旧幕僚"]]},{"n":"秦逐客","d":"","s":"《史记》卷八十七《李斯列传》","q":[["仙公一奏思归引，逐客初闻自泫然。","刘禹锡 闻道士弹思归引"],["书成休逐客，赋罢遂为郎。","张继 洛阳作"]]},{"n":"赵高谋李斯","d":"","s":"《史记》卷八十七〈李斯列传〉","q":[["弘恭陷萧望，赵高谋李斯。","白居易 读史五首"]]},{"n":"竹帛烟消","d":"","s":"《史记》卷六〈秦始皇本纪〉","q":[]}],"81":[{"n":"小儿杨德祖","d":"","s":"《后汉书》卷八十下〈文苑列传下·祢衡〉","q":[["十五事文翰，大儿轻孔融。","李端 长安感事呈卢纶"]]},{"n":"曹公黄祖","d":"","s":"《三国志》卷十〈魏书·荀彧传〉","q":[]},{"n":"渔阳掺","d":"祢生刺：咏怀才不遇。唐司空曙《送卢堪》：“莫使称生刺，空留怀袖中。”；祢衡挝：用以咏鼓乐，或指相骂，或指文人狂放不羁。唐李商隐《病中闻河东公乐营置酒口占寄上》：“必投潘岳果，谁掺祢衡挝。”","s":"《世说新语笺疏》上卷上〈言语〉","q":[["莫使祢生刺，空留怀袖中。","司空曙 送卢堪"],["祢生投刺游，王粲吟诗谒。","孟郊 答韩愈李观别因献张徐州"]]},{"n":"耻逐屠沽","d":"","s":"《后汉书》卷八十下〈文苑列传·祢衡〉","q":[["韩信羞将绛灌比，祢衡耻逐屠沽儿。","李白 答王十二寒夜独酌有怀"]]},{"n":"黄祖不怜","d":"","s":"《后汉书》卷八十下《文苑传·祢衡传》","q":[["黄祖不怜鹦鹉客，志公偏赏麒麟儿。","李山甫 赴举别所知"],["遐思祢衡才，令人怨黄祖。","李群玉 汉阳春晚"]]},{"n":"剪翎送笼","d":"","s":"《昭明文选》卷十三东汉·祢正平（衡）《鹦鹉赋》","q":[["剪翎送笼中，使看百鸟翔。","韩愈 调张籍"]]},{"n":"祢生","d":"","s":"《后汉书》卷八十下〈文苑列传·祢衡〉","q":[["如逢祢处士，似见鲍参军。","岑参 送宏文李校书往汉南拜亲"],["时通有诏徵枚乘，世乱无人荐祢衡。","徐夤 龙蛰二首"]]},{"n":"祢衡俊","d":"","s":"《昭明文选》卷三十七〈表上·荐祢衡表〉","q":[["处士祢衡俊，诸生原宪贫。","杜甫 寄李十二白二十韵"]]},{"n":"忘年友","d":"","s":"《后汉书》卷八十下〈文苑列传下·祢衡〉","q":[]},{"n":"厌祢衡","d":"","s":"《后汉书》卷八十下《文苑传·祢衡传》","q":[["径欲依刘表，还疑厌祢衡。","杜甫 奉送郭中丞兼太仆卿充陇右节度使三十韵（郭英乂）"],["使者求颜阖，诸公厌祢衡。","杜甫 敬赠郑谏议十韵"]]},{"n":"鹗表","d":"鹗荐：指荐贤。宋苏轼《次韵王定国谢韩子华过饮》：“亲嫌妨鹗荐，相对发微泚。”","s":"《后汉书》卷八十下〈文苑列传下·祢衡〉","q":[["慈明八龙，祢衡一鹗。","李瀚 蒙求"],["修持清苦振佳声，众鸟那知一鹗情。","方干 寄于少监"]]},{"n":"鹦鹉赋","d":"","s":"《后汉书》卷八十下《文苑传·祢衡传》","q":[["莫倚善题鹦鹉赋，何须不著鵔鸃冠。","严武 寄题杜拾遗锦江野亭"],["援笔便成鹦鹉赋，洗花须用桔槔泉。","方干 赠中岩王处士"]]}],"82":[{"n":"阿龙","d":"","s":"《世说新语笺疏》下卷上〈企羡〉","q":[]},{"n":"百口累","d":"","s":"《晋书》卷六十九《周顗传》","q":[["知同百口累，曷日办抽簪。","独孤及 得李滁州书以玉潭庄见托因书春思以诗代答"]]},{"n":"新亭泪","d":"对泣新亭：指忧国忧民之情。宋陆游《水乡泛舟》：“悲歌易水轻燕侠，对泣新亭笑楚国。”","s":"《世说新语笺疏》上卷上〈言语〉","q":[["莫道新亭人对泣，异乡殊代也沾衣。","吴融 过渑池书事"],["报国捐躯实壮夫，楚囚垂欲复神都。","唐彦谚 奉使岐下闻唐弘夫行军为贼所擒伤而有作"]]},{"n":"风鉴","d":"","s":"《晋书》卷六十五〈王导列传〉","q":[]},{"n":"王谢风流","d":"乌衣巷：喻王公贵族的居处，或咏王公贵族之往事。唐刘禹锡《乌衣巷》：“朱雀桥边野草花，乌衣巷口夕阳斜。”","s":"《世说新语笺疏》中卷上〈雅量〉","q":[["朱雀桥边野草花，乌衣巷口夕阳斜。","刘禹锡 金陵五题"],["旧时王谢堂前燕，飞入寻常百姓家。","刘禹锡 金陵五题乌衣巷"]]},{"n":"公望","d":"","s":"《世说新语笺疏》中卷下〈品藻〉","q":[["虞騪才望，戴渊锋颖。","李瀚 蒙求"],["友于皆挺拔，公望各端倪。","杜甫 奉赠太常张卿二十韵"]]},{"n":"瓜葛一枰同","d":"","s":"《晋书》卷六十五〈王导列传·王悦〉","q":[]},{"n":"加公九锡","d":"","s":"《世说新语笺疏》下卷下〈轻诋〉","q":[]},{"n":"堂前燕","d":"","s":"《全唐诗》卷三百六十五〈金陵五题五首〉","q":[]},{"n":"王导公忠","d":"","s":"《晋书》卷六十五《王导传》","q":[["谢安高洁，王导公忠。","李瀚 蒙求"],["已有孔明传将略，更闻王导得神机。","韦庄 闻官军继至未睹凯旋"]]},{"n":"岩岩立","d":"","s":"《毛诗正义》卷十二之一〈小雅·节南山之什·节南山〉","q":[]},{"n":"元规尘","d":"元规尘：喻高官权贵气势凌人，又泛指尘污。唐李白《送岑征君归鸣皋山》：“西来一摇扇，共拂元规尘。”","s":"《世说新语》下卷下《轻诋》","q":[["扇举遮王导，樽开见孔融。","李商隐 今月二日不自量度辄以诗一首四十韵干渎尊严伏蒙仁恩俯赐披览奖逾其实"],["西来一摇扇，共拂元规尘。","李白 送岑征君归鸣皋山"]]}],"83":[{"n":"五湖船","d":"","s":"《国语》卷二十一〈越语下·范蠡乘轻舟以浮于五湖〉","q":[["天地庄生马，江湖范蠡舟，逍遥堪自乐，浩荡信无忧。","高适 古乐府飞龙曲留上陈左相"],["范蠡舟偏小，王乔鹤不群。","杜甫 观李固请司马弟山水图三首"]]},{"n":"馆娃宫","d":"","s":"《吴越春秋》卷九〈勾践阴谋外传·勾践十二年〉","q":[["分明石潭里，宜照浣纱人。","张子容 春江花月夜二首之一"],["别有浣纱吴女郎，行尽绿潭潭转幽。","李白 和卢侍御通塘曲"]]},{"n":"藏弓","d":"","s":"《史记》卷四十一〈越王句践世家〉","q":[["藏弓身已退，焚稿事难闻。","刘长卿 秋日夏口涉汉阳献李相公"],["弓藏狡兔尽，慷慨念心伤。","王圭 咏淮阴侯"]]},{"n":"秋娘金缕","d":"","s":"《全唐诗》卷五百二十〈杜秋娘〉","q":[]},{"n":"黄金铸","d":"","s":"《国语》卷二十一〈越语下·范蠡乘轻舟以浮于五湖〉","q":[]},{"n":"鸱夷子","d":"","s":"《史记》卷四十一〈越王句践世家〉","q":[["不知鸱夷子，更入五湖去。","司马扎 美刘太保"],["鸱夷近何去，空山临沧溟。","崔国辅 宿范浦"]]},{"n":"范大夫","d":"","s":"《史记》卷四十一《越王句践世家》","q":[["几时逢范蠡，处处是通津。","厉玄 从军行"],["黄金范蠡曾辞禄，白首虞翻未信方。","唐彦谦 任潜谋隐之作"]]},{"n":"计然策","d":"","s":"《史记》卷一百二十九〈货殖列传〉","q":[]},{"n":"乌喙意儿别","d":"","s":"《史记》卷四十一〈越王句践世家〉","q":[]},{"n":"陶朱","d":"陶朱：指富贵之人。唐高适《真定即事奉赠韦使君二十八韵》：“田园同季子，储蓄异陶朱。”","s":"《史记》卷一百二十九〈货殖列传〉","q":[["陶朱虽相越，本有五湖心。","李白 留别王司马嵩"],["不知战国官荣者，谁似陶朱得始终。","汪遵 五湖"]]},{"n":"种蠡","d":"","s":"《史记》卷四十一〈越王句践世家〉","q":[]},{"n":"思范蠡","d":"","s":"《吴越春秋》卷十《句践伐吴林外传》","q":[["不学铸金思范蠡，乞言犹许上丹墀。","窦常 奉贺太保岐公承恩致政"]]}],"84":[{"n":"博陆受遗顾","d":"","s":"《汉书》卷六十八《霍光传》","q":[["绛侯与博陆，忠朴受遗顾。","李华 杂诗六首之五"]]},{"n":"不书名","d":"","s":"《汉书》卷五十四〈李广苏建列传·苏武〉","q":[["神皇麒麟阁，大将不书名。","储光羲 次天元十载华阴发兵作时有郎官点发"]]},{"n":"冯子都","d":"","s":"《汉书》卷六十八《霍光传》","q":[["绣帐博山炉，银鞍冯子都。","李益 金吾子"],["空歌汉代萧相国，肯事霍家冯子都。","李颀 放歌行答从弟墨卿"]]},{"n":"凤辖","d":"","s":"南朝梁·吴均《续齐谐记》","q":[["丹凤栖金辖，非熊载宝轩。","李峤 车"],["凤辖将军位，龙门司隶家。","郭良 题李将军山亭"]]},{"n":"负芒","d":"","s":"《汉书》卷六十八《霍光传》","q":[["成王已兴诮，宣帝如负芒。","王绩 赠梁公"],["我闻忽如负芒刺，不独为君空叹息。","贯休 行路难"]]},{"n":"麒麟阁","d":"","s":"《汉书》卷五十四〈李广苏建列传·苏武〉","q":[["若非载笔登麟阁，定是吹箫伴凤台。","于季子 早春洛阳答杜审言"],["新登麒麟阁，适脱獬豸冠。","岑参 送张秘书充刘相公通汴河判官便赴江外觐省"]]},{"n":"霍家亲","d":"","s":"《汉书》卷六十八《霍光传》","q":[["翩翩不知处，传是霍家亲。","司空曙 观猎骑"]]},{"n":"霍光","d":"","s":"《史记》卷二十《建元以来侯者年表》","q":[["长安甲第高入云，谁家居住霍将军。","崔颢 长安道"],["四海霍光第，六宫张奉营。","罗隐 使者"]]},{"n":"手画三军势","d":"","s":"《汉书》卷五十九〈张汤列传·张汤〉","q":[["生知七曜历，手画三军势。","杜甫 送樊二十三侍御赴汉中判官"]]},{"n":"燕客书诈","d":"","s":"《汉书》卷六十八《霍光传》","q":[["燕客书方诈，尧门信未孚，","李绅 趋翰苑遭诬构四十六韵"]]},{"n":"伊霍","d":"","s":"《后汉书》卷七十八《宦者传·序》","q":[["长笑应刘悲显达，每嫌伊霍少诗篇。","罗隐 寄酬邺王罗令公五首"]]},{"n":"子都","d":"","s":"《汉书》卷六十八《霍光传》","q":[["执心轻子都，信节冠秋胡。","顾况 瑶草春"]]}],"85":[{"n":"埋玉树","d":"埋玉：用以悼亡。宋陆游《与高安刘丞游大愚观壁间两苏先生诗》：“泉扃一埋玉，世事几炊黍。”；埋玉树：用以悼亡。宋陆游《与高安刘丞游大愚观壁间两苏先生诗》：“泉扃一埋玉，世事几炊黍。”","s":"《世说新语》下卷上《伤逝》","q":[["已悲泉下双琪树，又惜天边一卧龙。","李德裕 忆金门旧游奉寄江西沈大夫"],["鲤庭埋玉树，那忍见门人。","李端 慈恩寺怀旧"]]},{"n":"庾楼","d":"庾公楼：指风流儒雅之场所。唐卢纶《送申居正字往湖南迎亲……》：“坦腹定逢潘令罪，上楼应伴庚公闲。”","s":"《世说新语笺疏》下卷上〈容止〉","q":[["遥想高楼上，唯君对庾公。","司空曙 龙池寺望月寄韦使君阎别驾"],["庾公明月吟连曙，谢守青山看入秋。","吴融 离霅溪感事献郑员外"]]},{"n":"丰年玉，荒年谷","d":"","s":"《世说新语笺疏》中卷下〈赏誉〉","q":[]},{"n":"陶庾","d":"","s":"《晋书》卷六十六〈陶侃列传〉","q":[]},{"n":"庾公","d":"","s":"《晋书》卷七十三《庾亮传》","q":[["庾亮恃才高更逸，方闻墨翰已成章。","方干 月"],["梅仙调步骤，庾亮拂櫜鞬。","杜牧 奉送中丞姊夫侍自大理卿出镇江西叙事书怀因成二十韵"]]},{"n":"庾公病","d":"","s":"《晋书》卷七十三《庾亮传》","q":[["庾公念病宜清暑，遣向僧家占上方。","何元上 所居寺院凉夜输情呈上吕和叔温郎中"]]},{"n":"庾公尘","d":"","s":"《世说新语笺疏》下卷下〈轻诋〉","q":[]},{"n":"庾舅","d":"","s":"《晋书》卷七十三《庾亮传》","q":[["庾舅已能窥帝室，王都还是预人家。","罗隐 建康"]]},{"n":"庾征西","d":"","s":"《晋书》卷七十三《庾亮传》","q":[["不遇庾征西，云谁展怀抱。","萧颖士 仰答韦司业垂访五首之三"]]},{"n":"元规尘","d":"元规尘：喻高官权贵气势凌人，又泛指尘污。唐李白《送岑征君归鸣皋山》：“西来一摇扇，共拂元规尘。”","s":"《世说新语》下卷下《轻诋》","q":[["扇举遮王导，樽开见孔融。","李商隐 今月二日不自量度辄以诗一首四十韵干渎尊严伏蒙仁恩俯赐披览奖逾其实"],["西来一摇扇，共拂元规尘。","李白 送岑征君归鸣皋山"]]},{"n":"元规端委，幼舆邱壑","d":"","s":"《世说新语笺疏》中卷下〈品藻〉","q":[]},{"n":"元规清谈","d":"","s":"《晋书》卷七十三〈庾亮列传〉","q":[]}],"86":[{"n":"人中奇","d":"","s":"《世说新语笺疏》上卷上〈言语〉","q":[]},{"n":"龙门客","d":"李膺门：指官高品端的门第。唐杜牧《川守大夫刘公早岁……》：“昔为扬子宅，今是李膺门。”；登龙：喻得到有声望者援引而提高身价。唐高适《奉酬睢阳路太守见赠之作》：“相马知何限，登龙反自疑。”","s":"《后汉书》卷六十七〈党锢列传·李膺〉","q":[["永愿登龙门，相将持此节。","储光羲 酬李处士山中见赠"],["无因接元礼，共载比神仙。","刘禹锡 和东川王相公新涨驿池八韵"]]},{"n":"神仙侣","d":"仙侣同舟：喻指知己，或指沽名人的光。唐杜甫《秋兴》之八：“佳人拾翠春相问，仙侣同舟晚更移。”","s":"《后汉书》卷六十八《郭太传》","q":[["山宜姑射貌，江泛李膺舟。","于瑰 和绵州于中丞登越王楼作二首之一"],["物外须仙侣，人间要使君。","姚合 寄绛州李使君"]]},{"n":"逢尧舜","d":"","s":"《南史》卷五十五〈邓元起列传·李膺〉","q":[["生逢尧舜君，不忍便永诀。","杜甫 自京赴奉先县咏怀五百字"]]},{"n":"河尹与孔融","d":"","s":"《后汉书》卷七十〈孔融列传〉","q":[["有客传河尹，逢人问孔融。","杜甫 奉寄河南韦尹丈人"]]},{"n":"膺门得孔融","d":"","s":"《后汉书》卷七十《孔融传》","q":[["阁上掩书刘向去，门前修刺孔融来。","刘禹锡 同乐天送河南冯尹学士"],["定知洛下声名士，共说膺门得孔融。","许浑 送张厚浙东谒丁常侍（一作送张厚浙东修谒）"]]},{"n":"李杜诛","d":"","s":"《后汉书》卷六十七《杜密传》","q":[["喜无李杜诛，敢惮髡钳苦。","杜牧 李甘诗"]]},{"n":"李膺","d":"","s":"《后汉书》卷六十七《党锢传·李膺传》","q":[["又岂复忧朝廷苦弛慢，中官转纵横，李膺勾党即罹患，窦武忠谋又未行。","吴融 风雨吟"],["李膺门客为闲客，梅福官衔改旧衔。","周朴 喜贺拔先辈衡阳除正字"]]},{"n":"李元礼","d":"","s":"《后汉书》卷六十七〈党锢列传·李膺〉","q":[]},{"n":"漏夺","d":"","s":"《后汉书》卷六十七《党锢传·李膺传》","q":[["当时漏夺无人问，出宰东阳笑杀君。","戴叔伦 敬酬陆山人二首之一"]]},{"n":"元礼归纶氏","d":"","s":"《后汉书》卷六十七〈党锢列传·李膺〉","q":[["元礼去归缑氏学，江充来见犬台宫。","杜牧 李给事中敏二首"]]},{"n":"钟李","d":"","s":"《后汉书》卷六十二《钟皓传》","q":[["恩义同钟李，埙篪实弟兄。","杜牧 寄内兄和州崔员外十二韵"]]}],"87":[{"n":"比屋封","d":"","s":"《新语·无为》","q":[["辟门通舜宾，比屋封尧德。","骆宾王 夏日游德州赠高四"]]},{"n":"翻覆手","d":"","s":"《史记》卷九十七〈郦生陆贾列传·陆贾〉","q":[["翻手作云覆手雨，纷纷轻薄何须数。","杜甫 贫交行"]]},{"n":"陆贾装","d":"陆贾分金：指官吏退休后安排家业，分发钱财。唐骆宾王《帝京篇》：“陆贾分金将宴喜，陈遵投辖正留宾。”","s":"《汉书》卷四十三〈郦陆朱刘叔孙列传·陆贾〉","q":[["我有延陵剑，君无陆贾金。","李白 送曲十少府"],["行李千金赠，衣冠八尺身。","杜甫 奉寄李十五秘书二首"]]},{"n":"籍甚汉公卿","d":"","s":"《汉书》卷四十三《陆贾传》","q":[["还将海沂咏，籍甚汉公卿。","皇甫冉 送荣别驾赴华州"]]},{"n":"刘郎马上","d":"","s":"《史记》卷九十七〈郦生陆贾列传·陆贾〉","q":[]},{"n":"陆贾","d":"","s":"《史记》卷九十七《陆贾列传》","q":[["陆贾千年后，谁看朝汉台。","刘长卿 送裴二十端公使岭南"],["南来作尉任嚣力，北向称臣陆贾功。","许浑 登尉佗楼"]]},{"n":"陆贾著书","d":"","s":"《史记》卷九十七《陆贾列传》","q":[["著书同陆贾，待诏比王褒。","李德裕 述梦诗四十韵"]]},{"n":"马上得天下","d":"","s":"《史记》卷九十七〈郦生陆贾列传·陆贾〉","q":[["莫言马上得天下，自古英雄尽解诗。","林宽 歌风台"]]},{"n":"能言陆贾","d":"","s":"《汉书》卷四十三〈郦陆朱刘叔孙列传·陆贾〉","q":[]},{"n":"千金橐","d":"","s":"《史记》卷九十七〈郦生陆贾列传·陆贾〉","q":[]},{"n":"优游慕陆","d":"","s":"《昭明文选》卷四十五东汉·班孟坚（固）《答宾戏》","q":[["优游应慕陆，止足定师张。","皎然 因游支硎寺寄邢端公"]]}],"88":[{"n":"渔人犯白龙","d":"","s":"汉·刘向《说苑》卷九《正谏》","q":[["白龙改常服，偶被豫且制。","李白 枯鱼过河泣"],["且贪原兽轻黄屋，宁畏渔人犯白龙。","钱起 汉武出猎"]]},{"n":"素车白马","d":"灵胥：指河神。来陆游《乙丑夏秋之交小舟早夜往来湖中戏成绝句》：“千年未息灵胥怒，卷地潮声到枕边。”","s":"《吴越春秋》卷五〈夫差内传·十三年〉","q":[["行叹鸱夷没，遽惜湛卢飞。","骆宾王 夕次旧吴"],["但褫千人魄，那知伍相心。","姚合 杭州观潮"]]},{"n":"哭秦庭","d":"秦庭哭：指为国解难。唐李百药《郢城怀古》：“莫救夷陵火，无复秦庭哭。”","s":"《春秋左传正义》卷五十四〈定公·传四年〉","q":[["包胥心独许，连夜哭秦兵。千乘徒虚尔，一夫安可轻。","元稹 楚歌十首"],["包胥非救楚，随会反留秦。","张说 过庾信宅"]]},{"n":"鞭尸","d":"鞭尸：喻泄愤报仇。唐李白《酬裴侍御对而感时见赠》：“鞭尸辱已及，堂卜罗宿莽。”","s":"《史记》卷六十六《伍子胥列传》","q":[["岂料奔吴士，鞭尸郢市门。","元稹 楚歌十首之三"],["运开展宿愤，入楚鞭平王。","李白 游溧阳北湖亭望瓦屋山怀古赠同旅"]]},{"n":"楚逐伍胥","d":"","s":"《史记》卷六十六《伍子胥列传》","q":[["汉求季布鲁朱家，楚逐伍胥去章华。","李白 江上赠窦长史"]]},{"n":"吴市吹箫","d":"吴市吹箫：指因生活困顿而流浪飘泊，有为而未遇。清康有为《泛海至天津入京复还上海》：‘方朔长安徒索米，子胥吴市又吹箫。”","s":"《史记》卷七十九《范雎列传》","q":[["子胥昔乞食，此女倾壶浆。","李白 游溧阳北湖亭望瓦屋山怀古赠同旅"],["方朔长安徒索米，子胥吴市又吹箫。","康有为 泛海至天津入京复还上海"]]},{"n":"麋鹿游","d":"","s":"《史记》卷一百一十八〈淮南衡山列传〉","q":[["可怜荒堞晚冥濛，麋鹿呦呦达遗址。","刘商 姑苏怀古送秀才下第归江南"],["桑田东海变，麋鹿姑苏游。","张九龄 经江宁览旧迹至玄武湖"]]},{"n":"水仙","d":"","s":"《庄子》内篇·卷三上《大宗师》","q":[["飘泊南庭老，祗应学水仙。","杜甫 舟中"]]},{"n":"亡珠","d":"","s":"《韩非子》卷七《说林上》","q":[["悬剑空留信，亡珠尚识机。","骆宾王 夕次旧吴"]]},{"n":"抉眼","d":"伍员抉目：咏忠臣蒙冤。唐李绅《姑苏台杂句》：“伍员抉目看吴灭，范蠡全身霸西越。”","s":"《史记》卷六十六〈伍子胥列传〉","q":[["王道潜隳伍员死，可叹斗间瞻王气。","刘商 姑苏怀古送秀才下第归江南"],["伍员杀身谁不冤，竟看墓树如所言。","刘长卿 登吴古城歌"]]},{"n":"伍员忠谏","d":"","s":"《史记》卷六十六《伍子胥列传》","q":[["伍员结舌长嘘嚱，忠谏无因到君耳。","刘商 姑苏怀古送秀才下第归江南"],["当年国门外，谁识伍员忠。","杜牧 吴宫词二首"]]}],"89":[{"n":"易水寒","d":"燕丹客：喻勇士。唐骆宾王《送郑少府人辽共赋快客运从戎》：“不学燕丹客，空歌易水寒。”","s":"《史记》卷八十六〈刺客列传·荆轲〉","q":[["须知易水歌，至死无悔吝。","李咸用 猛虎行"],["击筑饮美酒，剑歌易水湄。","李白 少年行二首"]]},{"n":"长虹吐日","d":"","s":"《史记》卷八十三〈鲁仲连邹阳列传·邹阳〉","q":[["长虹吐白日，仓卒反受诛。","柳宗元 咏荆轲"]]},{"n":"燕市悲歌","d":"冲冠：喻指愤怒。唐卢照邻《咏史四首》之四：“直发上冲冠，壮气横三气。”","s":"《史记》卷八十六〈刺客列传·荆轲〉","q":[["高唱荆卿歌，乱击相如缶。","元稹 说剑"],["燕市悲歌又送君，目随征雁过寒云。","李涉 送魏简能东游二首之二"]]},{"n":"荆轲","d":"","s":"《史记》卷八十六〈刺客列传·荆轲〉","q":[["荆轲只为闲言语，不与燕丹了得人。","李山甫 游侠儿"],["方朔初闻汉，荆轲昔向秦。","李峤 史"]]},{"n":"荆庆才疏","d":"","s":"《史记》卷八十六〈刺客列传·荆轲〉","q":[]},{"n":"献图","d":"图穷：喻最终显露本意或真相。宋钱惟演《始皇》：“金椎漫筑甘泉道，匕首还献督亢图。”","s":"《战国策》卷三十一〈燕策三·燕太子丹质于秦亡归〉","q":[["燕丹卷地图，陈平绾花绶。","元稹 说剑"]]},{"n":"鲁句践","d":"","s":"《史记》卷八十六《刺客列传·荆轲传》","q":[["因声鲁句践，争情勿相欺。","李白 少年行二首之一"]]},{"n":"天雨粟","d":"","s":"《史记》卷八十六〈刺客列传〉","q":[]},{"n":"戏荆卿","d":"","s":"《史记》卷八十六〈刺客列传·荆轲〉","q":[]},{"n":"吐长虹","d":"燕丹客：喻勇士。唐骆宾王《送郑少府人辽共赋快客运从戎》：“不学燕丹客，空歌易水寒。”","s":"《汉书》卷五十一《邹阳传》","q":[["太白夜食昴，长虹日中贯。","李白 南奔书怀（一作自丹阳南奔道中作。此诗萧士赟云是伪作。）"],["羞道易水寒，从令日贯虹。","李白 结客少年场行"]]},{"n":"燕太子","d":"","s":"《史记》卷三十四《燕召公世家》","q":[["经过燕太子，结托并州儿。","李白 少年行二首之一"]]}],"90":[{"n":"苏武节","d":"羝乳：指无法办到之事。元袁桷《题郝伯常雁足》：“不须羝乳终回汉，肯学鸡鸣诈度关。”；苏武节：喻忠臣出使，宁死不屈。唐戎昱《闻颜尚书陷贼中》：“能持苏武节，不受马超勋。”","s":"《汉书》卷五十四〈李广苏建列传·苏建·（子）苏武〉","q":[["握雪海上餐，拂沙陇头寝。","李白 塞下曲六首之二"],["就烹感汉使，握节悲阳秋。","李德裕 东郡怀古二首之阳给事"]]},{"n":"传雁","d":"雁书：喻书信。唐杜甫《秋日荆南送石首薛明诗》：“岁满归凫舄，秋来把雁书。”","s":"《汉书》卷五十四〈李广苏建列传·苏武〉","q":[["当日苏武单于问，道是宾鸿解传信。","刘商 胡笳十八拍"],["家书欲寄雁飞远，客恨正深秋又来。","刘威 早秋归"]]},{"n":"苍鴚","d":"","s":"《汉书》卷五十四〈李广苏建列·苏建·（子）苏武〉","q":[]},{"n":"充国画麟阁","d":"","s":"《汉书》卷六十九《赵充国传》","q":[["明年麟阁上，充国画于斯。","苏颋 饯赵尚书摄御史大夫赴朔方军"]]},{"n":"苏属国","d":"","s":"《汉书》卷五十四《苏建传》附《苏武传》","q":[["名亚典属国，良选谏大夫。","戴叔伦 奉天酬别郑谏议云逵卢拾遗景亮见别之作"],["属国归何晚，楼兰斩未还。","杜甫 秦州杂诗二十首之七"]]},{"n":"麒麟阁","d":"","s":"《汉书》卷五十四〈李广苏建列传·苏武〉","q":[["若非载笔登麟阁，定是吹箫伴凤台。","于季子 早春洛阳答杜审言"],["新登麒麟阁，适脱獬豸冠。","岑参 送张秘书充刘相公通汴河判官便赴江外觐省"]]},{"n":"鸿鳞","d":"","s":"《汉书》卷五十四〈李广苏建列·苏建·（子）苏武〉","q":[]},{"n":"胡秦","d":"","s":"《艺文类聚》卷二十九","q":[["同衾成楚越，别岛类胡秦。","陈子昂 合州津口别舍弟至东阳峡步趁不及眷然有忆作以示之"]]},{"n":"山西将","d":"","s":"《汉书》卷六十九〈赵充国辛庆忌列传〉","q":[]},{"n":"少卿应识子卿心","d":"","s":"《昭明文选》卷四十一汉·李少卿（陵）《答苏武书》","q":[["流落天涯谁见问，少卿应识子卿心。","韦庄 钟陵夜阑作"]]},{"n":"苏辛","d":"","s":"《汉书》卷六十九《赵充国辛庆忌传赞》","q":[["田窦长留醉，苏辛曲护岐。","牡牧 少年行"]]}],"91":[{"n":"十日饮","d":"十日欢：指朋友相见而饮酒尽欢。唐李白《寻鲁城北范居士失道落苍耳中见范置酒摘苍耳作》：“近作十曰欢，远为千载期。”","s":"《史记》卷七十九〈范雎蔡泽列传·范雎列传〉","q":[["愿学平原十日饮，此时不忍歌骊驹。","韩翃 赠兖州孟都督"]]},{"n":"囊中锥","d":"","s":"《史记》卷七十六〈平原君虞卿列传·平原君〉","q":[["叶怯穿杨箭，囊藏透颖锥。","元稹 酬翰林白学士代书一百韵"],["颖微囊未出，寒甚谷难吹。","刘禹锡 罢郡归洛阳寄友人"]]},{"n":"斩美人","d":"","s":"《史记》卷七十六〈平原君虞卿列传·平原君〉","q":[["蛾眉笑躄者，宾客去平原。却斩美人首，三千还骏奔。","李白 送薛九被谗去鲁"],["若教粗及红儿貌，争取楼前斩爱姬。","罗虬 比红儿诗之六十三"]]},{"n":"重九鼎","d":"","s":"《史记》卷七十六〈平原君虞卿列传·平原君〉","q":[]},{"n":"买丝绣平原","d":"","s":"《史记》卷七十六〈平原君虞卿列传·平原君〉","q":[["买丝绣作平原君，有酒惟浇赵州土。","李贺 浩歌"]]},{"n":"毛遂堕井","d":"","s":"旧题汉·葛洪《西京杂记》卷六","q":[["野人未必非毛遂，太守还须是孟尝。","张祜 江上旅泊呈杜员外"],["毛遂不堕井，曾参宁杀人。","李白 系浔阳上崔相涣三首"]]},{"n":"平原君","d":"","s":"《史记》卷七十六《平原君列传》","q":[["对酒怜君安可论，当官爱士如平原。","刘长卿 江楼送太康郭主簿赴岭南"],["十年同在平原客，更遣何人哭寝门。","孟郊 哭李丹员外并寄杜中丞"]]},{"n":"平原客","d":"","s":"《史记》卷七十六《平原君列传》","q":[["金罍美酒满座春，平原爱才多众宾。满堂尽是忠义士，何意得有谗谀人。","崔颢 孟门行"],["身为平原客，家有邯郸娼。","王维 济上四贤咏（三首。济州官舍作。）之成文学"]]},{"n":"千钟酒","d":"","s":"《孔丛子》卷下〈儒服〉","q":[]},{"n":"锐头儿","d":"","s":"晋·孔衍《春秋后语·赵语》","q":[["锐头将军来何迟，令我心中苦不足。","杜甫 久雨期王将军不至"],["长陵锐头儿，出猎待明发。","杜甫 遣兴五首之二"]]},{"n":"四佳公子","d":"","s":"《汉书》卷九十二〈游侠列传〉","q":[]}],"92":[{"n":"王庾","d":"","s":"《北史·艺术传下·姚最》","q":[]},{"n":"碧鸡使","d":"","s":"《汉书》卷二十五下《郊祀志下》","q":[["怨已惊秦凤，灵应识汉鸡。","吴融 岐下闻杜鹃"],["如何碧鸡使，把诏紫微天。","杜甫 阆州奉送二十四舅仗自京赴任青城"]]},{"n":"传洞箫","d":"","s":"《汉书》卷六十四下《王褒传》","q":[["王褒轶材晚始入，宫女已能传洞箫。","李德裕 雨中自秘书省访王三侍御知早入朝便入集贤侍御任集贤校书及升柏台又与秘阁相对同院张学士亦余特厚故以诗赠之"]]},{"n":"乐职吟","d":"","s":"《汉书》卷六十四下《王褒传》","q":[["闲似淮阳卧，恭闻乐职吟。","羊士谔 上元日紫极宫门观州民然灯张乐"]]},{"n":"历块","d":"","s":"《汉书》卷六十四下《王褒传》","q":[["出尘皆野鹤，历块匪辕驹。","杜甫 大历三年春白帝城放船出瞿塘峡久居夔府将适江陵漂泊有诗凡四十韵"],["龙文虎脊皆君驭，历块过都见尔曹。","杜甫 戏为六绝句"]]},{"n":"四子讲德","d":"","s":"《昭明文选》卷五十一汉·王子渊（褒）《四子讲德论序》","q":[["四子醉时争讲德，笑论黄霸屈为邦。","钱起 九日宴浙江西亭"]]},{"n":"王褒","d":"","s":"《汉书》卷六十四〈严朱吾丘主父徐严终王贾列传·王褒〉","q":[["定知欲报淮南诏，促召王褒入九重。","刘禹锡 逢王十二学士入翰林因以诗赠"],["著书同陆贾，待诏比王褒。","李德裕 述梦诗四十韵"]]},{"n":"王褒柏惨","d":"","s":"《艺文类聚》卷八十八","q":[["王褒柏惨，闵损衣单。","李瀚 蒙求"]]},{"n":"王褒颂","d":"","s":"《汉书》卷六十四下〈严朱吾丘主父徐严终王贾列传下·王褒〉","q":[]},{"n":"王褒雅音","d":"","s":"《汉书》卷六十四〈严朱吾丘主父徐严终王贾列传·王褒〉","q":[["虞舜调清管，王褒赋雅音。","李峤 箫"]]},{"n":"王枚","d":"","s":"《汉书》卷六十四〈严朱吾丘主父徐严终王贾列传·王褒〉","q":[["王枚俱得从，浅浅愧飞毫。","李适 奉和圣制九日侍宴应制得高字"],["谬忝王枚列，多惭雨露恩。","武平一 奉和幸新丰温泉宫应制"]]}],"93":[{"n":"故将军","d":"故将军：指旧时之将军，或喻失势之人。宋陆游《余为成都帅师参议成将军汉卿相从无虚日为赋此诗》：“山中岂识故将军，但怪英姿凛不群。”；灞陵夜猎：指旧有权位已失，受人欺侮。唐李商隐《少年》：“灞陵夜猎随田窦，不识寒郊自转蓬。”","s":"《史记》卷一百九〈李将军列传〉","q":[["日暮灞陵原上猎，李将军是故将军。","李商隐 旧将军"],["乱离多醉尉，愁杀李将军。","杜甫 南极"]]},{"n":"射石","d":"","s":"《史记》卷一百九〈李将军列传〉","q":[["精感石没羽，岂忘惮险艰。","李白 豫章行"]]},{"n":"不封侯","d":"","s":"《史记》卷一百九〈李将军列传〉","q":[["白发今非老，青云数有奇。","李嘉祐 故吏部郎中赠给事中韦公挽歌二首之一"],["江山非久适，命数未终奇。","李频 送于生入蜀"]]},{"n":"桃李无言","d":"成蹊：喻指花事繁盛。唐贺知章《望人家桃李花》：“桃李从来露井傍，成蹊结影矜艳阳。”","s":"《史记》卷一百九〈李将军列传〉","q":[["愿莫随桃李，芳菲不为言。","周弘亮 曲江亭望慈恩寺杏花发"],["有恨开兰室，无言对李蹊。","唐彦谦 春雨"]]},{"n":"解鞍","d":"","s":"《史记》卷一○九《李将军列传》","q":[["解鞍欺李广，煮弩笑臧洪。","吴融 赴阙次留献荆南成相公三十韵"]]},{"n":"李将军","d":"","s":"《史记》卷一○九《李将军列传》","q":[["汉代李将军，微功合可咍。","岑参 使交河郡郡在火山脚其地苦热无雨雪献封大夫"],["夜宴李将军，欲望心相许。","曹邺 东武吟"]]},{"n":"山西将","d":"","s":"《汉书》卷六十九〈赵充国辛庆忌列传〉","q":[]},{"n":"射雕者","d":"","s":"《史记》卷一百九〈李将军列传〉","q":[["胡中射雕者，此日犹不能。翩翩羽林儿，锦臂飞苍鹰。","孟郊 羽林行"]]},{"n":"射虎","d":"射虎：指武将勇猛。唐卢纶《送彭开府往云中觐使君兄》：“夺旗貂帐侧，射虎雪林前。”","s":"《史记》卷一百九〈李将军列传〉","q":[["秋山年长头陀处，说我军前射虎归。","刘商 赠头陀师"],["故将移住南山边，短衣匹马随李广，看射猛虎终残年。","杜甫 曲江三章章五句之三"]]},{"n":"天下无双将","d":"","s":"《汉书》卷五十四《李广传》","q":[["天下无双将，关西第一雄。","杜牧 题永崇西平王宅太尉愬院六韵"]]},{"n":"万户侯","d":"","s":"《战国策》卷十一〈齐策四·齐宣王见颜斶〉","q":[["留侯万户虽无分，病骨应消一片山。","司空图 偶作"],["侯印几人封万户，侬家只办买孤峰。","司空图 白菊杂书四首"]]}],"94":[{"n":"东阁梅","d":"","s":"《先秦汉魏晋南北朝诗·梁诗》卷九〈何逊·诗·咏树诗〉","q":[["东阁官梅动诗兴，还如何逊在扬州。","杜甫 和裴迪登蜀州东亭送客逢早梅相忆见寄"]]},{"n":"何范","d":"","s":"《梁书》卷四十九《文学传上·何逊传》","q":[["不妨何范尽诗家，未解当年重物华。","李商隐 漫成三首之一"],["沈范早知何水部，曹刘不待薛郎中。","杜甫 解闷十二首"]]},{"n":"何逊滴阶","d":"","s":"南朝梁·何逊《何逊集》卷二《临行与故游夜别》","q":[["一夜自怜无羽翼，独当何逊滴阶愁。","吴融 寄殿院高侍御"],["雨滴秦中夜，猿闻峡外声。已吟何逊恨，还赋屈平情。","吴融 府试雨夜帝里闻猿声"]]},{"n":"何水部","d":"","s":"《南史》卷三十三〈何承天列传·（曾孙）何逊〉","q":[["论文谁可制，记室有何郎。","司空曙 送庞判官赴黔中"],["知己欲依何水部，乡人今正贱东丘。","严维 馀姚祗役奉简鲍参军"]]},{"n":"何谢","d":"","s":"《梁书》卷四十九《文学传上·何逊传》","q":[["诗人识何谢，居士别宗雷。","李端 得山中道友书寄苗钱二员外"],["孤悄欺何谢，云波不可寻。","栖白 赠李溟秀才"]]},{"n":"何逊","d":"","s":"《梁书》卷四十九《何逊传》","q":[["不如何逊无佳句，若比冯唐是壮年。","张乔 省中偶作"],["酒边旧侣真何逊，云里新声是莫愁。","曹松 陪湖南李中丞宴隐溪"]]},{"n":"摸索何刘沈谢","d":"","s":"《隋唐嘉话》中","q":[]},{"n":"三何许水曹","d":"","s":"《梁书》卷五十〈文学列传下·何思澄〉","q":[["诸谢偏推永嘉守，三何独许水曹郎。","李嘉祐 送舍弟"]]},{"n":"何刘","d":"","s":"《梁书》卷四十九〈文学列传上·何逊〉","q":[["何刘沈谢力未工，才兼鲍昭愁绝倒。","杜甫 苏端薛复筵简薛华醉歌"]]},{"n":"水曹","d":"","s":"《梁书》卷四十九〈文学列传上·何逊〉","q":[["省中官最美，无似水曹郎。前代佳名逊，当时重姓张。","朱庆余 贺张水部员外拜命"],["晴光一一呈金刹，诗思浸浸逼水曹。","裴夷直 和邢郎中病中重阳强游乐游原"]]},{"n":"阴何","d":"","s":"《陈书》卷三十四《阴铿传》","q":[["阴何尚清省，沈宋歘联翩。","杜甫 秋日夔府咏怀奉寄郑监李宾客一百韵"],["孰知二谢将能事，颇学阴何苦用心。","杜甫 解闷十二首"]]}],"95":[{"n":"与客携壶","d":"","s":"《全唐诗》卷五百二十二〈九日齐安登高【九日齐山登高】〉","q":[]},{"n":"秋娘金缕","d":"","s":"《全唐诗》卷五百二十〈杜秋娘〉","q":[]},{"n":"杜牧成名居五","d":"","s":"《唐摭言》卷六〈公荐〉","q":[]},{"n":"杜牧粗才","d":"","s":"《旧唐书》卷一百四十七〈杜佑列传·杜牧〉","q":[]},{"n":"杜牧风流","d":"","s":"《本事诗·高逸》","q":[]},{"n":"分司狂御史","d":"","s":"《本事诗·高逸》","q":[]},{"n":"荔枝无驿使","d":"","s":"《全唐诗》卷五百二十一〈过华清宫绝句三首〉","q":[]},{"n":"离骚之裔","d":"","s":"《全唐文》卷七百五十三〈杜牧六·太常寺奉礼部李贺歌诗集序〉2～","q":[]},{"n":"三生杜牧","d":"","s":"《宋诗钞·山谷诗钞》","q":[]},{"n":"书记平安","d":"","s":"《芝田录》","q":[]},{"n":"小杜","d":"","s":"《新唐书》卷一百六十六〈杜佑列传·（孙）杜牧〉","q":[]}],"96":[{"n":"食无鱼","d":"冯谖有鱼：指贤士怀才未遇，或反指受器重。宋苏轼《次韵周开祖长官见寄》：“犀首正缘无事饮，冯援应为有鱼留。”","s":"《战国策》卷十一〈齐四·齐人有冯谖者〉","q":[["不知弹铗客，何处感新恩。","于武陵 过侯王故第"],["此来多愧食鱼心，东阁将辞强一吟。","刘沧 入关留别主人"]]},{"n":"雍门琴","d":"雍门哀：喻指悲伤、感慨。宋朱熹《登定王台》：“从知爽鸠乐，莫作雍门哀。”","s":"《说苑》卷十一〈善说〉","q":[["感事不关河里笛，伤心应倍雍门琴。","唐彦谦 春阴"],["市若荆州罢，池如薛县平。","崔融 户部尚书崔公挽歌"]]},{"n":"鸡鸣狗盗","d":"鸡鸣狗盗：喻指人物或技能不伦不类、委琐卑下、唐宋之间《过函谷关》；“鸡鸣将狗盗，论德不论勋。”","s":"《史记》卷七十五〈孟尝君列传〉","q":[["犹嫌未远函关道，正睡刚闻报晓鸡。","吴融 阌乡寓居十首茆堂"],["鸡鸣将狗盗，论德不论勋。","宋之问 过函谷关"]]},{"n":"营三窟","d":"兔藏三窟：喻指谋求避祸之道。唐杜甫《见王监兵马使说近山有白黑二鹰赋诗二首》之一：“鹏碍九天须却避，兔藏三窟莫深忧。”","s":"《战国策》卷十一〈齐四·齐人有冯谖者〉","q":[["世事徒三窟，儿童且一经。","唐彦谦 梅亭"],["孟尝习狡兔，三窟赖冯谖。","李白 送薛九被谗去鲁"]]},{"n":"市义","d":"市义：喻有雄才远见，或喻收买民心。唐刘禹锡《许给事见示哭工部刘尚书诗因命同作》。“总戎宽得众，市义贵能贫。”","s":"《战国策》卷十一《齐策四》","q":[["总戎宽得众，市义贵能贫。","刘禹锡 许给事见示哭工部刘尚书诗因命同作（从叔望山河间）"],["谁能买仁义，令子无寒饥。","姚合 送张宗原"]]},{"n":"孟尝君","d":"","s":"《史记》卷七十五〈孟尝君列传〉","q":[["初迷武陵路，复出孟尝门。","刘长卿 秦系顷以家事获谤因出旧山每荷观察崔公见知欲归未遂感其流寓诗以赠之"],["野人未必非毛遂，太守还须是孟尝。","张祜 江上旅泊呈杜员外"]]},{"n":"三千客","d":"三千客：指贵客盈门。宋范成大《次韵甄云卿晚登浮丘亭》：“宾筵旧压三千客，燕榭新高十二城。”","s":"《史记》卷七十七〈魏公子列传〉","q":[["食恩三千士，一旦为豺狼。","孟郊 汴州离乱后忆韩愈李翱"],["若无三千客，谁道信陵君。","李白 博平郑太守自庐山千里相寻入江夏北市门见访却之武陵立马赠别"]]},{"n":"四佳公子","d":"","s":"《汉书》卷九十二〈游侠列传〉","q":[]},{"n":"田文饭","d":"","s":"《史记》卷七十五《孟尝君列传》","q":[["顾荣锡炙，田文比饭。","李瀚 蒙求"],["共食田文饭，先之梅福官。","李端 送丁少府往唐上"]]},{"n":"田文有命","d":"","s":"《史记》卷七十五《孟尝君列传》","q":[["向栩非才徒隐灶，田文有命那关户。","李端 杂歌"]]},{"n":"相门出相","d":"","s":"《史记》卷七十五〈孟尝君列传〉","q":[["自古相门还出相，如今人望在岩廊。","刘禹锡 送李尚书领滑州"]]}],"97":[{"n":"九叙重歌","d":"","s":"《尚书》卷四〈虞书·大禹谟〉","q":[]},{"n":"万国执玉","d":"","s":"《春秋左传正义》卷五十八〈哀公·传七年〉","q":[]},{"n":"禹凿","d":"","s":"《孟子注疏》卷五〈滕文公上〉","q":[["往来行旅弊，开凿禹功存。","孟浩然 入峡寄弟"],["井邑观秦野，山河念禹功。","孙逖 奉和御制登鸳鸯楼寓目应制"]]},{"n":"禹绩","d":"","s":"《春秋左传正义》卷五十七〈哀公·传元年〉","q":[["谋谟收禹绩，四面出雄劲。","韩愈 东都遇春"]]},{"n":"禹命子","d":"","s":"《史记》卷二《夏本纪》","q":[["禹功亦命子，涿鹿亲戎行。","杜甫 壮游"]]},{"n":"禹让","d":"","s":"《尚书》卷四〈虞书·大禹谟〉","q":[["周惭散马出，禹让浚川回。","钱起 观法架自凤翔回"]]},{"n":"禹汤","d":"","s":"《礼记·礼运》","q":[["在德期巢燧，居安法禹汤。","苏颋 敬和崔尚书大明朝堂雨后望终南山见示之作"],["得失鉴齐楚，仁思念禹汤。","魏知古 从猎渭川献诗"]]},{"n":"禹汤罪己","d":"","s":"《春秋左传正义》卷九〈庄公·传十一年〉","q":[["且如歌笑日挥金，应笑禹汤能罪己。","钱起 秋霖曲"]]},{"n":"禹穴","d":"","s":"《史记》卷一百三十〈太史公自序〉","q":[["禹穴探书罢，天台作赋游。","张继 会稽秋晚奉呈于太守"],["亦恐浅深同禹穴，兼云制度象污樽。","方干 僧院小泉井"]]},{"n":"禹玉","d":"","s":"《艺文类聚》卷十一〈帝王部一·帝禹夏后氏〉","q":[["大官陈禹玉，司历献尧蓂。","司空曙 和耿拾遗元日观早朝"]]}],"98":[{"n":"弃瓢","d":"","s":"东汉·蔡邕《琴操》","q":[["一瓢遗却在何处，应挂天台最老松。","施肩吾 遇王山人"],["邑罕悬磬贫，山无挂瓢逸。","李峤 扈从还洛呈侍从群官"]]},{"n":"买山钱","d":"","s":"《世说新语》下卷下《排调》","q":[["沃洲能共隐，不用道林钱。","刘长卿 初到碧涧招明契上人"],["支遁初求道，深公笑买山。","孟浩然 宿立公房"]]},{"n":"不教污两耳","d":"","s":"《史记》卷六十一〈伯夷列传〉","q":[]},{"n":"巢由","d":"","s":"《遵生八笺·尘外遐举笺·历代高隐姓氏·巢父》","q":[["如知巢与许，千载迹犹新。","于武陵 寻山"],["巢由薄天下，俗士营一官。","唐彦谦 六月十三日上陈微博士"]]},{"n":"箕山颍水","d":"洗耳：指隐士清高脱俗。唐李白《送裴十八图南归嵩山》之二“归时莫洗耳，为我洗其心。”","s":"《庄子集释》卷一上〈内篇·逍遥游〉","q":[["箕山有高节，湘水有清源。","陈子昂 感遇诗三十八首之三十一"],["心到物自闲，何劳远箕颍。","元稹 表夏十首之二"]]},{"n":"鹪鹩一枝","d":"","s":"《庄子》内篇·卷一上《逍遥游》","q":[["雕鹗失势病，鹪鹩假翼翔。","孟郊 落第"],["手欠东堂桂一枝，家书不敢便言归。","李咸用 投所知"]]},{"n":"上尧下由","d":"","s":"《史记》卷六十一〈伯夷列传〉","q":[["上有尧兮下有田，眠松阳兮漱颍流。","张楚金 逸人歌赠李山人"]]},{"n":"逃尧","d":"","s":"《庄子》内篇·卷一上《逍遥游》","q":[["匡时知已老，圣代耻逃尧。","严维 赠别刘长卿时赴河南严中丞幕府"],["颍上逃尧者，何如此养真。","钱起 题温处士山居"]]},{"n":"许由","d":"","s":"《庄子》内篇·卷一上《逍遥游》","q":[["缣书若有寄，为访许由邻。","刘方平 寄陇右严判官"],["滩上思严子，山中忆许由。","岑参 宿关西客舍寄东山严许二山人时天宝初七月初三日在内学见有高道举征"]]},{"n":"颍客","d":"","s":"《高士传》卷上《许由》","q":[["周王尊渭叟，颍客傲唐尧。","理莹 送戴三徵君还谷口旧居"],["草遍颍阳山，花开武陵水。","皇甫冉 春早"]]}],"99":[{"n":"抗行比元常","d":"","s":"《晋书》卷八十《王羲之传》","q":[["近来渐有临池兴，为报元常欲抗行。","刘禹锡 答后篇"]]},{"n":"卖饼诉公羊","d":"","s":"《三国志》卷二十三〈魏书·裴潜传〉","q":[["啖螯讥尔雅，卖饼诉公羊。","唐彦谦 送樊琯司业归朝"]]},{"n":"太尉","d":"","s":"《三国志》卷十三〈魏书·钟繇传〉","q":[["文独司空羡，书兼太尉能。","司空曙 送翰林张学士岭南勒圣碑"]]},{"n":"魏文颁菊蕊","d":"","s":"《艺文类聚》卷四","q":[["魏文颁菊蕊，汉武赐萸房。","沈佺期 九日临渭亭侍宴应制得长字"]]},{"n":"元常","d":"","s":"《太平广记》卷二百九〈书四·杂编·姜诩已下〉","q":[]},{"n":"钟大理","d":"","s":"《三国志》卷十三〈魏书·钟繇传〉","q":[["翰墨已齐钟大理，风流好继谢宣城。","韩翃 送夏侯侍郎"],["上客钟大理，主人陶武威。","韩翃 送卢大理赵侍御祭东岳兼寄孟兖州"]]},{"n":"钟太尉","d":"","s":"《三国志》卷十三〈魏书·钟繇传〉","q":[["清言只到卫家儿，用笔能誇钟太尉。","李颀 同张员外諲酬笔之作"]]},{"n":"钟王","d":"","s":"《晋书》卷八十〈王羲之列传〉","q":[]},{"n":"钟繇笔","d":"","s":"《晋书》卷三十六《卫瓘传》附《卫恒传》","q":[["既握钟繇笔，须调傅说羹。","贯休 送卢舍人朝觐"]]},{"n":"钟繇字","d":"","s":"《晋书》卷三十六〈卫瓘列传·（子）卫恒〉","q":[]}],"100":[{"n":"布帆无恙","d":"布帆无恙：指旅途平安。唐李白《秋下荆门》：“露落荆门江树空，布帆无恙挂秋风。”","s":"《世说新语笺疏》下卷下〈排调〉","q":[["霜落荆门江树空，布帆无恙挂秋风。","李白 秋下荆门"]]},{"n":"顾虎头","d":"","s":"《晋书》卷九十二〈文苑列传·顾恺之〉","q":[]},{"n":"长康丹青","d":"","s":"《晋书》卷九十二《文苑传·顾恺之传》","q":[["图画风流似长康，文词体格效陈王。","李嘉祐 访韩司空不遇"],["王湛床头见周易，长康传里好丹青。","李颀 同张员外諲酬答之作"]]},{"n":"痴黠相兼","d":"","s":"《世说新语》上卷下《文学》","q":[["如含瓦砾竟何功，痴黠相兼似得中。","韩偓 味道"]]},{"n":"丹青图画飞去无踪","d":"","s":"《世说新语笺疏》下卷上〈巧蓺〉","q":[]},{"n":"啖蔗","d":"","s":"《世说新语》下卷下《排调》","q":[["初味犹啖蔗，遂通斯建瓴。","韩愈 答张彻"]]},{"n":"顾恺之","d":"","s":"《晋书》卷九十二《文苑传·顾恺之传》","q":[["题处尚寻王内史，画时应是顾将军。","温庭筠 法云寺双桧"],["痴号多于顾恺之，更无馀事可从知。","皮日休 新秋即事三首"]]},{"n":"顾氏传神","d":"","s":"《世说新语笺疏》下卷上〈巧蓺〉","q":[["生公吐辩真无敌，顾氏传神实有灵。","李群玉 规公业在净名得甚入仆近获顾长康月宫真影对戴安道所画文殊走笔此篇以屈瞻礼"]]},{"n":"棘刺情","d":"","s":"《晋书》卷九十二《文苑传·顾恺之传》","q":[["额点梅花样，心通棘刺情。","吴融 个人三十韵"]]},{"n":"泪成河","d":"","s":"《世说新语笺疏》上卷上〈言语〉","q":[["犹有泪成河，经天复东注。","杜甫 得舍弟消息"]]}],"101":[{"n":"避风台","d":"","s":"《太平广记》卷二百三十六〈奢侈一·沙棠舟〉","q":[["向春罗袖薄，谁念舞台风。","杜牧 寄远"],["方知汉成帝，虚筑避风台。","贾至 赠薛瑶英"]]},{"n":"留仙裙","d":"","s":"《五朝小说大观·魏晋小说》","q":[]},{"n":"赵家姊妹","d":"","s":"《汉书》卷九十七下〈外戚列传下·孝成赵皇后〉","q":[]},{"n":"赵飞燕","d":"飞燕：喻指宫妇或歌女。唐李白《宫中行乐词八首》之二：“宫中谁第一，飞燕在昭阳。”","s":"《汉书》卷九十七下〈外戚列传下·孝成赵皇后〉","q":[["倏忽不相期，思倾赵飞燕","于濆 越溪女"],["岂知赵飞燕，满髻钗黄金。","于濆 里中女"]]},{"n":"掌中看","d":"","s":"《梁书》卷三十九〈羊侃列传〉","q":[["客泪休沾汉水滨，舞腰羞杀汉宫人。","司空图 杨柳枝寿杯词十八首"],["掌中舞罢箫声绝，三十六宫秋夜长。","徐凝 汉宫曲"]]},{"n":"凤皇","d":"","s":"旧题晋·葛洪《西京杂记》","q":[["醉客沾鹦鹉，佳人指凤皇。","杜甫 陪柏中丞观宴将士二首"]]},{"n":"如红玉","d":"","s":"旧题晋·葛洪《西京杂记》卷一","q":[["春营骑将如红玉，走马捎鞭上空绿。","李贺 贵主征行乐"],["青丝发落丛鬓疏，红玉肤销系裙慢。","白居易 陵园妾"]]},{"n":"赵李经过","d":"","s":"《昭明文选》卷二十三〈诗丙·咏怀·咏怀诗十七首〉","q":[["城中相识尽繁华，日夜经过赵李家。","王维 洛阳女儿行"],["田窦方贵幸，赵李新相知。","郑愔 少年行"]]},{"n":"赵燕扫粉","d":"","s":"旧题汉·伶玄《飞燕外传》","q":[["卷衣秦帝，扫粉赵燕。","李贺 春昼"]]},{"n":"啄皇孙","d":"","s":"《汉书》卷九十七上《外戚传上·孝成赵皇后传》","q":[["复闻飞燕琢皇孙，皇孙不死燕啄折。","王翰 飞燕篇"]]}],"102":[{"n":"避风台","d":"","s":"《太平广记》卷二百三十六〈奢侈一·沙棠舟〉","q":[["向春罗袖薄，谁念舞台风。","杜牧 寄远"],["方知汉成帝，虚筑避风台。","贾至 赠薛瑶英"]]},{"n":"长杨赋","d":"","s":"《汉书》卷八十七下〈扬雄列传下〉","q":[["早晚荐雄文似者，故人今已赋长杨。","李颀 寄司勋卢员外"],["一首长杨赋，应嫌索价高。","罗隐 寄制诰李舍人"]]},{"n":"画堂","d":"","s":"《汉书》卷九十八《元后传》","q":[["画堂授傅姆，天人亲捧持。","杜牧 杜秋娘诗"]]},{"n":"今为时怜","d":"","s":"《汉书》卷二十七中之上《五行志》","q":[["赫赫萧京兆，今为时所怜。","杜甫 遣兴五首"]]},{"n":"绝驰道","d":"","s":"《汉书》卷十《成帝纪》","q":[["平明走马绝驰道，呼鹰挟弹通缭垣。","李益 汉宫少年行"],["虽蒙绝驰道，京兆别开阡。","王维 恭懿太子挽歌五首"]]},{"n":"绵竹颂","d":"","s":"《昭明文选》卷七汉·杨子云（雄）《甘泉赋》","q":[["几时绵竹颂，拟荐子虚名。","李商隐 令狐舍人说昨夜西掖玩月因戏赠"]]},{"n":"盘中舞","d":"","s":"《杨太真外传》","q":[]},{"n":"五侯","d":"","s":"《汉书》卷九十八〈元后列传〉","q":[["五侯初买笑，建章方落籍。","于濆 织素谣"],["人间物象分千里，天上笙歌醉五侯。","刘睽 题越王楼寄献中丞使君"]]},{"n":"壮发","d":"","s":"《汉书》卷九十七下《赵皇后传》","q":[["燕禖得皇子，壮发绿緌緌。","杜牧 杜秋娘诗并序"]]},{"n":"啄皇孙","d":"","s":"《汉书》卷九十七上《外戚传上·孝成赵皇后传》","q":[["复闻飞燕琢皇孙，皇孙不死燕啄折。","王翰 飞燕篇"]]}],"103":[{"n":"曹公黄祖","d":"","s":"《三国志》卷十〈魏书·荀彧传〉","q":[]},{"n":"仲宣楼","d":"王粲登楼：指咏叹流落他乡而怀念故土，或指登楼。唐戴叔伦《赠司空拾遗》：“陈琳草奏才还在，王粲登楼兴不赊。”","s":"《昭明文选》卷十一〈赋己·游览·登楼赋〉","q":[["思乡每读登楼赋，对月空吟叩角歌。","刘沧 汶阳客舍"],["陈琳草奏才还在，王粲登楼兴未赊。","大易 赠司空拾遗"]]},{"n":"刘景升","d":"","s":"《三国志》卷六〈魏书·刘表传〉","q":[]},{"n":"生子当如孙仲谋","d":"","s":"《三国志》卷四十七〈吴书·吴主权传〉","q":[]},{"n":"刘表焉取","d":"","s":"《后汉书》卷八十三《逸民传·庞公传》","q":[["刘表虽遗恨，庞公至死藏。","杜甫 寄彭州高三十五使君适虢州岑二十七长史参三十韵"],["举家依鹿门，刘表焉得取。","杜甫 遣兴五首"]]},{"n":"刘表坐谈","d":"","s":"《三国志》卷十四〈魏书·郭嘉传〉","q":[]},{"n":"三雅","d":"","s":"《太平御览》卷八四五","q":[["俱裁七步咏，同倾三雅杯。","于志宁 冬日宴群公于宅各赋一字得杯"],["酒每倾三雅，书能发百函。","刘禹锡 和汴州令狐相公到镇改月偶书所怀"]]},{"n":"司马称好","d":"","s":"《世说新语》上卷上《言语》","q":[["东平为善，司马称好。","李瀚 蒙求"]]},{"n":"依刘表","d":"依刘表：喻依附权贵。唐李商隐《五言述德抒情诗一首四十韵献上杜七兄仆射相公》：“自是依刘表，安能比老彭。”","s":"《三国志》卷二十一《魏书·王粲传》","q":[["公子道存知不弃，欲依刘表住南荆。","戴叔伦 送车参军江陵"],["自是依刘表，安能比老彭。","李商隐 五言述德抒情诗一首四十韵献上杜七兄仆射相公"]]},{"n":"玄德依刘","d":"","s":"《三国志》卷三十二〈蜀书·先主备传〉","q":[]}],"104":[{"n":"比玉","d":"","s":"《世说新语笺疏》下卷上〈容止〉","q":[["尝值偷琴处，亲闻比玉时。","司空曙 哭苗员外呈张参军"]]},{"n":"玉山行","d":"玉人：喻指男子美貌。唐卢纶《酬金部王郎中省中春日见寄》：“鹤侣正疑芳景引，玉人那为簿书沉。”","s":"《世说新语笺疏》下卷上〈容止〉","q":[["共惜不成金谷妓，虚令看杀玉车人。","王翰 观蛮童为伎之作"],["拂墙花影动，疑是玉人来。","崔莺莺 答张生（一作明月三五夜）"]]},{"n":"冰翁","d":"","s":"《世说新语笺疏》上卷上〈言语〉","q":[]},{"n":"梦乘车","d":"","s":"《世说新语笺疏》上卷下〈文学〉","q":[]},{"n":"三倒","d":"","s":"《世说新语笺疏》中卷下〈赏誉〉","q":[]},{"n":"叔宝清","d":"","s":"《晋书》卷三十六〈卫瓘列传·（孙）卫玠、（恒族弟）卫展〉","q":[["羸将卫玠比，冷共邺侯同。","李端 长安感事呈卢纶"],["我亦休文瘦，君能叔宝清。","陆龟蒙 奉酬袭美早春病中书事"]]},{"n":"卫玠","d":"卫玠：用于称美外甥。唐李端《酬丘拱外甥览余旧文见寄》：“舅乏郗鉴爱，君如卫玠贤。”","s":"《世说新语笺疏》下卷上〈容止〉","q":[["花当西施面，泉胜卫玠清。","元稹 独游"],["舅乏郤鉴爱，君如卫玠贤。","李端 酬丘拱外甥览余旧文见寄"]]},{"n":"卫玠琼瑶色","d":"","s":"《世说新语笺疏》下卷上〈容止〉","q":[["貌应同卫玠，鬓且异潘生。","李端 送吉中孚拜官归楚州"],["人同卫叔美，客似长卿才。","李适 安乐公主移入新宅"]]},{"n":"彦辅怜卫叔","d":"","s":"《晋书》卷三十六《卫瓘传》附《卫玠传》","q":[["秦家重萧史，彦辅怜卫叔。","白居易 和梦游春一百韵"]]},{"n":"玉润","d":"","s":"《世说新语》上卷上《言语》","q":[["玉润终孤立，珠明得暗藏。","杜甫 送大理封主簿五郎亲事不合却赴通州主簿前阆州贤子余与主簿平章郑氏女子垂欲纳（一有采字）郑氏伯父京书至女子已许他族亲事遂停"]]}],"105":[{"n":"洪崖肩","d":"","s":"《太平广记》卷四〈神仙四·卫叔卿〉","q":[["仙井今犹在，洪崖久不还。","张九龄 登城楼望西山作"],["缅思洪崖术，欲往沧海隔。","李白 日夕山中忽然有怀"]]},{"n":"五色笔","d":"才尽：喻因年老而才思退减。唐杜甫《送顾八分文学适洪吉州》：“才尽伤形体，病渴污官位。”；江淹梦：指文采不凡。唐方干《再题路支使南亭》：“睡时分得江淹梦，五色毫端弄逸才。”","s":"《南史》卷五十九〈江淹列传〉","q":[["锦窠不是寻常锦，兼向丘迟夺得来。","司空图 少仪"],["都缘有意重熏裛，更洒江毫上玉堂。","吴融 薛舍人见徵恩赐香并二十八字同寄"]]},{"n":"郭璞阴阳决","d":"","s":"《晋书》卷七十二〈郭璞列传〉","q":[]},{"n":"郭璞游仙","d":"","s":"《昭明文选》卷二十一晋·郭景纯（璞）《游仙诗》","q":[["郭璞赋游仙，始愿今可就。","钱起 登覆釜山遇道人二首之一"]]},{"n":"景纯","d":"","s":"《晋书》卷七十二《郭璞传》","q":[["虚座怜王述，遗篇恸景纯。","褚亮 伤始平李少府正己"]]},{"n":"青囊","d":"青囊：指道士之术。唐杜甫《奉寄河南韦尹丈人》：“青囊仍雅逸，章甫尚西东。”","s":"《晋书》卷七十二〈郭璞列传〉","q":[["锦帙开诗轴，青囊结道书。","杜牧 许七侍御弃官东归潇洒江南颇闻自适高秋企望题诗寄赠十韵"],["刘根丹篆三千字，郭璞青囊两卷书。","杜牧 赠朱道灵"]]},{"n":"青溪道士","d":"","s":"《昭明文选》卷二十一〈诗乙·游仙·游仙〉","q":[["青溪道士人不识，上天下天鹤一只。","高骈 步虚词"]]},{"n":"水仙","d":"","s":"《庄子》内篇·卷三上《大宗师》","q":[["飘泊南庭老，祗应学水仙。","杜甫 舟中"]]},{"n":"文魮","d":"","s":"《昭明文选》卷十二〈赋己·江海·江赋〉","q":[["文魮隔雾朝含碧，老蚌凌波夜吐丹。","曹松 南海"]]},{"n":"注尔雅虫鱼","d":"","s":"《尔雅注疏》卷一〈尔雅序〉","q":[["《尔雅》注虫鱼，定非磊落人。","韩愈 读皇甫湜公安园池读书其后二首"]]}],"106":[{"n":"匈奴未灭","d":"去病无家：指公而忘私。明陈子龙《奉酬越大夫卓凡见赠之作》：“去病无家原为国，信陵有客尽知兵。”","s":"《史记》卷一百一十一〈卫将军骠骑列传〉","q":[["孟母迁邻罢，将军辞第初。","李峤 宅"],["匈奴未灭不言家，驱逐行行边徼赊。","李昂 从军行"]]},{"n":"霍嫖姚","d":"","s":"《史记》卷一百一十一《卫将军骠骑列传》","q":[["帝念霍嫖姚，诏发咸林兵。","储光羲 次天元十载华阴发兵伯时有郎官点发"],["喷沫团香小桂条，玉鞭兼赐霍嫖姚。","刘言史 春游曲"]]},{"n":"冠军侯","d":"","s":"《史记》卷一一一《卫将军骠骑列传》","q":[["大君忽霆震，诏爵冠军侯。","储光羲 送丘健至州敕放作时任下封尉"],["碧玉芳年事冠军，清歌空得隔花闻。","杨巨源 观妓人入道二首之二"]]},{"n":"金人祭","d":"","s":"《汉书》卷九十四上〈匈奴列传上〉","q":[["玉塞去金人，二万四千里。","李贺 摩多楼子"],["当取金人祭，还歌凯入都。","陈子昂 答韩使同在边"]]},{"n":"临海","d":"","s":"《史记》卷一百一十一〈卫将军骠骑列传〉","q":[["临海旧来闻骠骑，寻河本自有中郎。","崔融 从军行"]]},{"n":"六骡西走","d":"","s":"《史记》卷一百一十一〈卫将军骠骑列传〉","q":[]},{"n":"祁连冢","d":"","s":"《史记》卷一一一《卫将军骠骑列传》","q":[["细柳旧营犹锁月，祁连新冢已封苔。","吴融 彭门用兵后经汴路三首之一"]]},{"n":"未学孙吴","d":"","s":"《史记》卷一一一《卫将军骠骑列传》","q":[["李广从来先将士，卫青未肯学孙吴。","高适 送浑将军出塞"]]},{"n":"卫霍","d":"","s":"《史记》卷一一一《卫将军骠骑列传》","q":[["卫霍待富贵，岂能无乾坤。","于濆 寒下曲"],["赤肉痛金疮，他人成卫霍。","于濆 边游录成卒言"]]},{"n":"燕支落汉","d":"","s":"《史记》卷一一○《匈奴列传》","q":[["燕支落汉家，妇女无华色。","李白 塞上曲"]]}],"107":[{"n":"毋忘在莒","d":"","s":"《史记》卷三十二〈齐太公世家〉","q":[]},{"n":"白石烂","d":"宁戚牛：咏人怀才未遇。唐李白《秋浦歌十七首》之七：“醉上山公马，寒歌宁戚牛。”","s":"《楚辞》战国楚·屈原《离骚》","q":[["思乡每读登楼赋，对月空吟叩角歌。","刘沧 汶阳客舍"],["魏阙望中何日见，商歌奏罢复谁听。","严维 韦情献相公"]]},{"n":"伏虎威","d":"","s":"《管子》卷十六《小问》","q":[["不从桓公猎，何能伏虎威。","李贺 马诗二十三首"]]},{"n":"愚公谷","d":"愚公谷：喻雅逸之地。唐王维《愚公谷三首》之三：“借问愚公谷，与君聊一寻。”","s":"《艺文类聚》卷九〈水部下·谷〉","q":[["知老何山是，思归愚谷中。","姚合 书怀寄友人"],["兴来林是竹，归卧谷名愚。","孟浩然 寻张五回夜园作"]]},{"n":"桓公事","d":"","s":"《史记》卷八十六〈刺客列传·曹沫〉","q":[["秦皇本诈力，事与桓公殊。奈何效曹子，实谓勇且愚。","柳宗元 咏荆轲"]]},{"n":"齐侯紫衣","d":"","s":"《韩非子》卷十一《外储说左上》","q":[["齐侯好紫衣，魏帝妇人饰。","李华 杂诗六首"]]},{"n":"齐桓","d":"","s":"《史记》卷三十二《齐太公世家》","q":[["扶持社稷似齐桓，百万雄师贵可观。","贯休 大蜀皇帝潜龙日述圣德诗五首"]]},{"n":"射钩","d":"","s":"《春秋左传·僖公二十四年》","q":[["射后呼父，钓翁王春师。","杜牧 杜秋娘诗"]]},{"n":"小白鸿翼","d":"","s":"《管子·霸形》","q":[["小白鸿翼于夷吾，刘葛鱼水本无二。","李白 君道曲"]]},{"n":"斫轮","d":"","s":"《庄子》外篇·卷五中《天道》","q":[["车轮徒已斲，堂构惜仍亏。","杜甫 偶题"]]}],"108":[{"n":"病卧漳滨","d":"","s":"《昭明文选》卷二十三〈诗丙·赠答一·赠五官中郎将四首〉","q":[["伏枕嗟公干，归山羡子平。","孟浩然 李氏园林卧疾"],["众病婴公干，群忧集孝璋。","李端 宿荐福寺东池有怀故园因寄元校书"]]},{"n":"曹刘","d":"","s":"南朝梁·钟嵘《诗品·总论》","q":[["曹刘俯仰惭大敌，沈谢逡巡称小儿。","任华 寄杜拾遗"],["曹刘不免死，谁敢负年华。","孟郊 招文士饮"]]},{"n":"沉簿领","d":"","s":"《昭明文选》卷二十九、三国魏·刘公干（桢）《杂诗》","q":[["且宽沉簿领，应赖酒如渑。","耿湋 早春宴高陵滑少府"]]},{"n":"刘公干","d":"","s":"《三国志》卷二十一《魏书·王粲传》附《刘桢传》","q":[["高谈闵仲叔，逸气刘公干。","储光羲 贻刘高士别"],["故人多病尽归去，唯有刘桢不得眠。","戴叔伦 行营送马侍御"]]},{"n":"刘桢病","d":"","s":"《三国志》卷二十一《魏书·王粲传》","q":[["刘桢元抱病，虞寄数辞官。","李商隐 楚泽"],["因恨刘桢病，空园卧见秋。","李端 卧病寄苗员外"]]},{"n":"刘桢平视","d":"","s":"《三国志》卷二十一《魏书·王粲传》附《刘桢传》","q":[["甄后出拜，刘桢平视。","李瀚 蒙求"],["甄后出拜，刘桢平视。","李瀚 蒙求"]]},{"n":"刘桢有气","d":"","s":"《昭明文选》卷三十南朝宋·谢灵运《拟魏太子邺中集诗八首·刘桢·序》","q":[["刘桢徒有气，管辂独无年。","张九龄 眉州康司马挽歌词"]]},{"n":"西垣","d":"","s":"《昭明文选》诗丙·第二十三卷·赠答·刘桢·〈赠徐干〉","q":[["西垣草诏罢，南宫忆上才。","韦应物 和张舍人夜直中书寄吏部刘员外"]]},{"n":"应刘","d":"","s":"《昭明文选》卷四十二、三国魏·魏文帝（曹丕）《与朝歌令吴质书》","q":[["崔嵬长河北，尚见应刘墓。","孟云卿 邺城怀古"],["还瞻魏太子，宾客减应刘。","杜甫 重题"]]},{"n":"漳滨卧","d":"","s":"《昭明文选》卷二十三、三国魏·刘公干（桢）《赠五官中郎将四首》其二","q":[["已叹漳滨卧，何言驻隙难。","司空曙 哭王注"],["自叹眠漳久，双林动所思。","吴融 寄尚颜师"]]}],"109":[{"n":"商傅","d":"","s":"《史记》卷三〈殷本纪〉","q":[]},{"n":"傅说版筑","d":"","s":"《孟子注疏》卷十二下〈告子章句下〉","q":[["傅氏筑已卑，磻溪钓何激。","韩愈 和裴仆射假山十一韵"],["傅岩既纡郁，首山亦嵯峨。操筑无昔老，采薇有遗歌。","薛稷 秋日还京陕西十里作"]]},{"n":"济巨川","d":"济巨川：喻指宰相。唐沈＃期《哭苏眉州崔司业二公》：“崔昔挥宸翰，苏尝济巨川。”","s":"《尚书·商书·说命上》","q":[["适会傅岩人，虚舟济川时。","独孤及 送陈兼应辟兼寄高适贾至"],["宇宙既焜耀，崇德济巨川。","储光羲 奉别长史庾公太守徐公应召"]]},{"n":"调味","d":"和羹：借指梅花。徐贵《梅花》：“结实和羹知有日，肯随羌笛落天涯？”《尚书·商书·说命下》王曰：‘来汝说…著作酒，若作和羹，尔唯盐梅。”又喻指宰相。唐刘禹锡《和汴州令狐相公到镇改月偶书所怀》：“受赈新梁苑，和羹旧傅严。”","s":"《尚书》卷十〈商书·说命下〉","q":[["龙衮期重补，梅羹伫再和。","令狐楚 将赴洛下旅次汉南献上相公二十兄言怀八韵"],["此日临风飘羽卫，他年嘉约指盐梅。","元稹 赠毛仙翁"]]},{"n":"傅野","d":"梦高宗：指受到帝王的赏识。唐姚合《赠终南山傅山人》：“悲君还姓傅，独不梦高宗。”","s":"《史记》卷三〈殷本纪〉","q":[["戎衣一挂清天下，傅野非无济世才。","韩偓 疏雨"],["在野傅岩君不梦，乘轩卫懿鹤何功。","郑启 严塘经乱书事"]]},{"n":"骑箕尾","d":"","s":"《庄子集释》卷三上〈内篇·大宗师〉","q":[]},{"n":"作砺","d":"","s":"《尚书·商书·说命上》","q":[["终随金砺用，不学玉山颓。","白居易 奉和思黯相公以李苏州所寄太湖石奇状绝伦因题二十韵见示兼呈梦得"],["自然须作砺，不必恨临戎。","罗隐 投宣武郑尚书二十韵"]]},{"n":"刻象求","d":"","s":"《帝王世纪》","q":[["好入天子梦，刻像来尔求。","杜牧 洛中送冀处士东游"]]},{"n":"作霖雨","d":"","s":"《尚书·商书·说命上》","q":[["寰中不用忧天旱，霖雨看看属傅岩。","周朴 喜贺拔先辈衡阳除正字"],["眼看白笔为霖雨，肯使红鳞便曝腮。","周朴 客州赁居寄萧郎中"]]},{"n":"曲蘖","d":"","s":"《尚书·商书·说命下》","q":[["为君天下酒，曲糵将用时。","岑参 尹相公京兆府中棠树降甘露诗"]]}],"110":[{"n":"陈寔碑","d":"","s":"《后汉书》卷六十二《陈寔传》","q":[["既卧黔娄衾，空立陈寔碑。","皮日休 七爱诗元鲁山"]]},{"n":"陈寔奖元方","d":"","s":"《世说新语》中卷下《夙惠》","q":[["王浑知武子，陈寔奖元方。","杨巨源 上刘侍中"]]},{"n":"陈寔是好儿","d":"","s":"《后汉书》卷六十二《陈寔传》","q":[["许询本爱交禅侣，陈寔由来是好儿。","杨巨源 题贾巡官林亭"]]},{"n":"陈寔遗盗","d":"","s":"《后汉书》卷六十二《陈寔传》","q":[["黄向访主，陈寔遗盗。","李瀚 蒙求"]]},{"n":"陈太邱","d":"","s":"《后汉书》卷六十二《陈寔传》","q":[["仲举登宰辅，太丘荣缙绅。","储光羲 敬酬陈掾亲家翁秋夜有赠"],["姚公美政谁与俦，不减昔时陈太丘。","杜甫 陪王侍御同登东山最高顶宴姚通泉晚携酒泛江"]]},{"n":"谌纪","d":"","s":"《后汉书》卷六十二〈荀韩钟陈列传·陈寔列传〉","q":[]},{"n":"聚德星","d":"","s":"《世说新语笺疏》上卷上〈德行〉","q":[["从今别君后，长忆德星看。","刘禹锡 送太常萧博士弃官归养赴东都"],["以吾一日长，念尔聚星稀。","孟浩然 送洗然弟进士举"]]},{"n":"太邱道","d":"","s":"《后汉书》卷六十八〈郭符许列传·许劭〉","q":[["终惭太丘道，不为小生私。","李端 下第上薛侍郎"]]},{"n":"荀陈","d":"","s":"《后汉书》卷六十二〈荀韩钟陈列传·荀淑〉","q":[["颍郡水东流，荀陈兄弟游。","宋之问 送许州宋司马赴任"],["耿贾官勋大，荀陈地望清。","李商隐 五言述德抒情诗一首四十韵献上杜七兄仆射相公"]]},{"n":"颍川集","d":"","s":"《太平御览》卷三八四","q":[["今宵颍川曲，谁识聚贤人。","李峤 星"],["方知颍川集，别有太丘门。","董思恭 咏星"]]}],"111":[{"n":"阿堵物","d":"阿堵：指钱。宋陆游《岁暮贫甚戏书》：“阿堵无知不受呼，忍贫闭户亦良图。”","s":"《世说新语》中卷下《规箴》","q":[["冶长空得罪，夷甫岂言钱。","刘长卿 罪所留系寄张十四"],["若无一堵物，不啻冷如霜。","寒山 诗三百三首"]]},{"n":"神州陆沉","d":"","s":"《世说新语笺疏》下卷下〈轻诋〉","q":[]},{"n":"识胡儿","d":"","s":"《晋书》卷一百四〈石勒载记上〉","q":[["锢党岂能留汉鼎，清谈空解识胡儿。","杜牧 故洛阳城有感"]]},{"n":"持麈尾","d":"","s":"《世说新语》下卷上《容止》","q":[["闲言挥麈柄，清步掩蜗庐。","杨巨源 郊居秋日酬奚赞府见寄"],["应笑王戎成俗物，遥持麈尾独徘徊。","韦应物 假中枉卢二十二亦称卧疾兼讶李二久不访问以诗答书因亦戏李二"]]},{"n":"将无同","d":"三语掾：代称幕府官员。唐元稹《答姨兄胡灵之见寄五十韵》：“官曹三语掾，国器万寻帧。”又借指椽史之官。唐柳宗元《同刘二十八院长述旧言怀感时书事奉寄遵州张员外使君五十二韵之作用其韵增至八十通赠二君子》：“谁采中原寂，徒巾下泽…","s":"《世说新语笺疏》上卷下〈文学〉","q":[["可怜三语掾，长作九泉灰。","刘商 杂言同豆卢郎中郭南七里桥哀悼姚仓曹"],["更闻台阁求三语，遥想风流第一人。","王维 同崔傅答贤弟"]]},{"n":"悬河口","d":"悬河：指说话滔滔不绝。宋陆游《闻王嘉叟讣报有作》：“‘笼灯踏雪夜相过，剧论悬河骇邻里。”","s":"《晋书》卷八十七〈郭象列传〉","q":[["安能以此上论列，愿借辨口如悬河。","韩愈 石鼓歌"]]},{"n":"宁馨","d":"","s":"《晋书》卷四十三《王戎传》附《王衍传》","q":[["为问中华学道者，几人雄猛得宁馨。","刘禹锡 赠日本僧智藏"]]},{"n":"王衍钟情","d":"","s":"《世说新语》下卷上《伤逝》","q":[["方同王衍钟情切，犹念商瞿有庆迟。","李群玉 哭小女痴儿"]]},{"n":"王夷甫","d":"","s":"《晋书》卷四十三〈王戎列传·（从弟）王衍〉","q":[]},{"n":"瑶树","d":"","s":"《世说新语笺疏》中卷下〈赏誉〉","q":[["瑶树忽倾沧海里，醉乡翻在夜台中。","李群玉 哭郴州王使君"]]}],"112":[{"n":"赤眉","d":"","s":"《汉书》卷九十九下《王莽传下》","q":[["赤眉犹世乱，青眼只途穷。","杜甫 巫峡敝庐奉赠侍御四舅别之澧朗"],["眉画犹思赤，巾裁未厌黄。","韦庄 和郑拾遗秋日感事一百韵"]]},{"n":"错刀","d":"","s":"《汉书》卷二十四下《食货志下》","q":[["虚为错刀留远客，枉缘书札损文鳞。","李商隐 题二首后重有戏赠任秀才"],["闻道松醪贱，何须吝错刀。","韩愈 潭州泊船呈诸公"]]},{"n":"盗移","d":"","s":"《后汉书》卷一下《光武帝纪下》","q":[["盗移未改命，历在终履端。","张九龄 奉和圣制幸晋阳宫"]]},{"n":"天年竟夭","d":"龚胜耻事新：喻忠贞不事二主。唐颜真卿《咏陶渊明》：“张良思报韩，龚胜耻事新。”","s":"《汉书》卷七十二《龚胜亡》","q":[["龚胜不屈，孙宝自劾。","李瀚 蒙求"],["楚国一老人，来嗟龚胜亡。","李白 自溧水道哭王炎三首之一"]]},{"n":"国玺危皇后","d":"","s":"《汉书》卷九十八〈元后列传〉","q":[["御衣空惜侍中血，国玺几危皇后身。","韩偓 八月六日作四首"]]},{"n":"昆阳举","d":"","s":"《汉书》卷九十九下《王莽传下》","q":[["庶同昆阳举，再睹汉仪新。","李白 赠张相镐二首"],["千载昆阳好功业，与君门下作恩威。","罗隐 经故洛阳城"]]},{"n":"莽卓","d":"","s":"《汉书》卷九十九上〈王莽列传〉","q":[["不羞莽卓黄金印，却笑羲皇白接䍦。","韩偓 余卧疾深村闻一二郎官令称继使闽越笑余迂古潜于异乡闻之因成此篇"]]},{"n":"子云阁","d":"扬雄投阁：喻无故受牵连而获罪，走投无路。宋陆游《丰年行》：“书生识字亦聊尔，莫作扬雄老投阁。”","s":"《汉书》卷八十七下〈扬雄列传下〉","q":[["东望安仁省，西临子云阁。","上官仪 酬薛舍人万年宫晚景寓直怀友"],["投阁嗤扬子，飞书代鲁连。","张继 酬李书记校书越城秋夜见赠"]]},{"n":"王莽谦恭","d":"王莽谦恭：喻以伪善骗取信任。唐白居易《放言五首》之三：“周公恐惧流言日，王莽谦恭未篡时。”","s":"《汉书》卷九十九上《王莽传上》","q":[["周公恐惧流言后，王莽谦恭未篡时。","白居易 放言五首"]]},{"n":"玉灭瘢","d":"","s":"《汉书》卷九十九上〈王莽列传上〉","q":[]}],"113":[{"n":"子猷竹","d":"此君：咏竹。唐杜牧《题刘秀才新竹》：“不是山阴客，何人爱此君。”","s":"《世说新语笺疏》下卷上〈简傲〉","q":[["虽非宋玉诛茅至，且学王家种竹来。","吴融 岐阳蒙相国借宅因抒怀投献"],["皇王自有增封日，修竹徒劳号此君。","徐夤 松"]]},{"n":"白袷玉郎","d":"","s":"《世说新语》下卷下《轻诋》","q":[["彩线结茸背复叠，白袷玉郎寄桃叶。","李贺 染丝上春机"]]},{"n":"辟疆园","d":"","s":"《世说新语》下卷上《简傲》","q":[["树异桓宣武，园非顾辟疆。","唐彦谦 红叶"],["柳深陶令宅，竹暗辟疆园。","李白 留别龚处士"]]},{"n":"山阴道","d":"访戴：喻指访友或行事洒脱。唐李白《酬坊州王司马与间正字对雪见赠》：“访戴昔未偶，寻嵇此相得。”","s":"《世说新语笺疏》下卷上〈任诞〉","q":[["兴掩寻安道，词胜命仲宣。","刘禹锡 奉和中书崔舍人八月十五日夜玩月二十韵"],["兴比乘舟访，恩怀倒屣亲。","司空曙 送高胜重谒曹王"]]},{"n":"不记马","d":"","s":"《世说新语笺疏》下卷上〈简傲〉","q":[["吾孙骑曹不骑马，业学尸乡多养鸡。","杜甫 寄从孙崇简"]]},{"n":"似马曹","d":"","s":"《世说新语笺疏》下卷上〈简傲〉","q":[]},{"n":"西山爽气","d":"拄笏看山：指朝廷官宦有隐士情怀。宋朱松《春晚书怀》：“脱巾漉酒从人笑，拄笏看山颇自奇。”","s":"《世说新语笺疏》下卷上〈简傲〉","q":[["若见西山爽，应知黄绮心。","王维 送李太守赴上洛"]]},{"n":"旧青毡","d":"青毡：喻先祖遗物，或喻旧业。唐卢纶《寄郑七纲》：“他日吴公如记问，愿将黄绶比青毡。”","s":"《晋书》卷八十〈王羲之列传·（徽之子）王献之〉","q":[["来时虽恨失青毡，自见芭蕉几十篇。","司空图 狂题十八首"],["卜羡君平杖，偷存子敬毡。","杜甫 秋日夔府咏怀奉寄郑监李宾客一百韵"]]},{"n":"子敬琴","d":"人琴两亡：指悼念亲友。唐陈子昂《同宋参军之问梦赵六赠卢陈二子之作》：“人琴遂两亡，白云失处所。”","s":"《世说新语笺疏》下卷上〈伤逝〉","q":[["相如只谢病，子敬忽云亡。","张九龄 故徐州刺史赠吏部侍郎苏公挽歌词三首"],["徒闻子敬遗琴在，不见相如驷马归。","戴叔伦 吊畅当"]]},{"n":"子猷","d":"","s":"《晋书》卷八十〈王羲之列传·（子）王徽之〉","q":[["未遭伶伦听，非安子猷宠。","元稹 寺院新竹"],["家贫惟好月，空愧子猷过。","刘长卿 月下呈章秀才"]]}],"114":[{"n":"明珠暗投","d":"","s":"《史记》卷八十三《邹阳列传》","q":[["似璧悲三献，疑珠怯再投。","张子容 璧池望秋月"],["远客谢主人，明珠难暗投。","李白 留别贾至舍人二首"]]},{"n":"白头新","d":"","s":"《史记》卷八十三〈鲁仲连邹阳列传·邹阳〉","q":[["尧舜至今万万岁，数子将为倾盖间。","李贺 相劝酒"],["可怜宾客尽倾盖，何处老翁来赋诗。","杜甫 七月一日题终明府水楼二首之二"]]},{"n":"邹枚","d":"","s":"《史记》卷一百一十七〈司马相如列传〉","q":[["邹枚入梁苑，逸少在山阴。","刘长卿 寄会稽公徐侍郎"],["文学引邹枚，歌钟陈卫霍。","张说 药园宴武辂沙将军赋得洛字"]]},{"n":"曳长裾","d":"曳裾：指阿附权贵。唐李白《行路难》：“弹剑作歌奏苦声，曳裾王门不称情。”","s":"《汉书》卷五十一〈贾邹枚路传·邹阳〉","q":[["匣有青萍筒有书，何门不可曳长裾。","吕温 道州酬送何山人之容州"],["会作王门曳裾客，为余前谢鲍参军。","朱长文 送李司直归浙东幕兼寄鲍将军（一作朱湾诗）"]]},{"n":"梁园赋","d":"延枚：指延集宾客。唐李商隐《忆雪》：“预约延枚酒，虚乘访戴船。”；授简：指奉命吟诗作赋。唐杜甫《又作此奉卫王》：“白头授简焉能赋，愧似相如为大夫。”","s":"《西京杂记》卷二","q":[["孙室临书幌，梁园泛酒杯。","令狐楚 省中直夜对雪寄李师素侍郎"],["有客怀兔园，吟诗绕城内。","曹邺 贺雪寄本府尚书"]]},{"n":"桀犬吠尧","d":"","s":"《汉书》卷五十一《邹阳传》","q":[["美舜歌徒作，欺尧犬正狞。","吴融 和严谏议萧山庙十韵"],["桀犬尚吠尧，匈奴笑千秋。","李白 经乱离后天恩流夜郎忆回游书怀赠江夏韦太守良宰"]]},{"n":"酒赋","d":"","s":"《西京杂记》卷四","q":[["拙被林泉滞，生逢《酒赋》欺。","杜甫 夔府书怀四十韵"]]},{"n":"邹书","d":"","s":"《史记》卷八十三〈鲁仲连邹阳列传·邹阳〉","q":[["梁王虽好事，不察狱中书。","崔国辅 送韩十四被鲁王推递往济南府"],["楚筵辞醴日，梁狱上书辰。","杜甫 寄李十二白二十韵"]]},{"n":"先容","d":"","s":"《史记》卷八十三《邹阳列传》","q":[["弱岁游玄圃，先容幸弃瑕。","柳宗元 同刘二十八院长（禹锡）述旧言怀感时书事奉寄澧州张员外使君（署）五十二韵之作因其韵增至八十通赠二君子（刘禹锡初与公同为盐察御史。故称院长）"]]},{"n":"鹗表","d":"鹗荐：指荐贤。宋苏轼《次韵王定国谢韩子华过饮》：“亲嫌妨鹗荐，相对发微泚。”","s":"《后汉书》卷八十下〈文苑列传下·祢衡〉","q":[["慈明八龙，祢衡一鹗。","李瀚 蒙求"],["修持清苦振佳声，众鸟那知一鹗情。","方干 寄于少监"]]}],"115":[{"n":"万斛愁","d":"","s":"《周书》卷四十一〈庾信列传〉","q":[["伤心庾开府，老作北朝臣。","司空曙 金陵怀古"],["若比江南更牢落，子山词赋莫兴哀。","吴融 彭门用兵后经汴路三首"]]},{"n":"王庾","d":"","s":"《北史·艺术传下·姚最》","q":[]},{"n":"鲍庾","d":"","s":"北宋·郭祥正《送马东玉朝散还朝》","q":[]},{"n":"收庾信","d":"","s":"《周书》卷四十一《庾信传》","q":[["共传收庾信，不比得陈琳。","杜甫 奉赠王中允"]]},{"n":"小庾","d":"","s":"《北史》卷八十三〈文苑列传·庾信〉","q":[["文体此时看又别，吾知小庾甚风流。","韩翃 送故人赴江陵寻庾牧"]]},{"n":"徐庾","d":"","s":"《北史》卷八十三〈文苑列传·庾信〉","q":[["尘埃徐庾词，金玉曹刘名。","孟郊 赠苏州韦郎中使君"],["南朝徐庾流，洛下忆同游。","罗隐 商于驿与于蕴玉话别"]]},{"n":"由旬","d":"","s":"北周·庾信《庾子山集》卷三《奉和法筳应诏》","q":[["南方宝界几由旬，八部同瞻一佛身。","广宣 贺幸普济寺应制"]]},{"n":"庾园","d":"","s":"北周·庾信《庾子山集》卷一《小园赋》","q":[["却寻庾信小园中，闲对数竿心自足。","张南史 竹"],["露寒潘省夜，木落庾园秋。","武元衡 闻相公三兄小园置宴以元衡寓直因寄上兼呈中书三兄"]]},{"n":"庾薛","d":"","s":"《北史》卷八十三《文苑传·庾信传》","q":[["北朝荣庾薛，西汉盛严徐。","常衮 晚秋集贤院即事寄徐薛二侍郎"]]},{"n":"庾公","d":"","s":"《周书》卷四十一《庾信传》","q":[["三川难可见，应惜庾公才。","岑参 故河南尹歧国公赠工部尚书苏公挽歌二首之二"],["玄成美价存，子山旧业传。","杜甫 赠李十五丈别"]]}],"116":[{"n":"长杨射熊罴","d":"","s":"《汉书》卷九〈元帝纪〉","q":[["长杨射熊罴，武帐弄哑咿。","杜牧 杜秋娘诗"]]},{"n":"毛延寿","d":"","s":"《西京杂记》卷二","q":[["丹青能令丑者妍，无盐翻在深宫里。自古妒娥眉，胡沙埋皓齿。","李白 于阗采花"],["相如死后无词客，延寿亡来绝画工。","杜牧 奉陵宫人"]]},{"n":"当熊","d":"","s":"《汉书》卷九十七下《外戚传下·孝元冯昭仪传》","q":[["水至亦不去，熊来尚可当。","李白 秦女卷衣"],["辞辇复当熊，倾心奉六宫。","卢纶 天长久词（三首。附宫中乐二首。一作天长词。一作天长地久词。）"]]},{"n":"马上琵琶","d":"","s":"《昭明文选》卷二十七〈诗戊·乐府上·王明君词并序〉","q":[]},{"n":"伏青蒲","d":"伏蒲：咏忠臣直谏。唐许浑《闻边将刘皋无辜受戮》：“却赖汉庭多烈士，至今犹自伏蒲论。”","s":"《汉书》卷八十二〈王商史丹傅喜列传·史丹〉","q":[["宵衣旰食明天子，日伏青蒲不为言。","杜牧 闻开江相国宋下世二首"],["斯时伏青蒲，延争守御床。","杜甫 壮游"]]},{"n":"贡禹怀书","d":"","s":"《汉书》卷七十二《贡禹传》","q":[["贡禹怀书日，张衡作赋辰。","李峤 田"]]},{"n":"汉元","d":"","s":"《汉书》卷九《元帝纪》","q":[["自有汉元争翊戴，不劳商皓定敧倾。","殷文圭（宋时避讳。改殷为汤。） 观贺皇太子册命"]]},{"n":"丸鼓","d":"","s":"《汉书》卷八十二《史丹传》","q":[["徒嗟日沈湎，丸鼓骛奇音。","柳宗元 感遇二首"]]},{"n":"头角折","d":"","s":"《汉书》卷六十七《朱云传》","q":[["我虽在金台，头角长垂折。","杜牧 池州送孟迟先辈"]]},{"n":"萧傅","d":"","s":"《汉书》卷七十八《萧望之传》","q":[["谢公诗更老，萧傅道方尊。","杨巨源 和郑少师相公题慈恩寺禅院"]]}],"117":[{"n":"刘家异同","d":"","s":"《汉书》卷三十六《楚王元传》附《刘歆传》","q":[["闻道将雏向墨池，刘家还有异同词。","柳宗元 重赠二首"]]},{"n":"刘讼石中书","d":"","s":"《汉书》卷三十六《楚元王传》附《刘向传》","q":[["可怜刘校尉，曾讼石中书。","杜牧 李给事中敏二首"]]},{"n":"刘子政","d":"","s":"《汉书》卷三十六《楚元王传》附《刘向传》","q":[["阁上掩书刘向去，门前修刺孔融来。","刘禹锡 同乐天送河南冯尹学士"],["若问旧人刘子政，如今头白在商于。","刘禹锡 送分司陈郎中祗召直史馆重修三圣实录"]]},{"n":"刘中垒","d":"","s":"《汉书》卷三十六《楚元王传》附《刘向传》","q":[["宗室刘中垒，文场谢客儿。","独孤及 送李宾客荆南迎亲"]]},{"n":"向歆传业","d":"","s":"《汉书》卷三十六〈楚元王列传·刘向～〉928～","q":[]},{"n":"向歆父子","d":"","s":"《汉书》卷三十六〈楚元王列传·刘向～〉928～","q":[]},{"n":"向隅","d":"向隅：喻指哀伤或抑郁。唐温庭筠《病中书怀呈友人》：“逸足皆先路，穷郊独向隅。”","s":"汉·刘向《说苑》卷五《贵德》","q":[["惟应深夜月，独伴向隅人。","于武陵 长信宫二首"],["闻君败绩无归计，气激星辰坐向隅。","唐彦谦 奉使岐下闻唐弘夫行军为贼所擒伤而有作"]]},{"n":"歆向","d":"","s":"《文中子·天地》","q":[]},{"n":"子政","d":"","s":"《汉书》卷三十六〈楚元王列传·刘向～〉928～","q":[]}],"118":[{"n":"陈蕃榻","d":"徐孺榻：指礼贤重才，或指礼遇宾客。唐孟浩然《荆门上张丞相》：“坐登徐孺榻，濒接李膺杯。”","s":"《后汉书》卷五十三〈周黄徐姜申屠列传·徐稚〉","q":[["解榻招徐稚，登楼引仲宣。","元稹 献荥阳公诗五十韵"],["何武劾腐儒，陈蕃礼高士。","刘禹锡 送湘阳熊判官孺登府罢归钟陵因寄呈江西裴中丞二十三兄"]]},{"n":"扫一室","d":"扫一室：指闲居生活，或指志向远大。宋苏轼《送张安道赴南都留台》：“归来扫一室，虚白以自怡。”","s":"《后汉书》卷六十六〈陈王列传·陈蕃〉","q":[]},{"n":"陈仲举","d":"","s":"《后汉书》卷六十六〈陈王列传·陈蕃〉","q":[]},{"n":"窦武忠谋","d":"","s":"《后汉书》卷六十九《窦武传》","q":[["李膺勾党即罹患，窦武忠谋又未行。","吴融 风雨吟"]]},{"n":"何劳扫一室","d":"","s":"《后汉书》卷六十六《陈蕃传》","q":[["丈夫清万里，谁能扫一室。","刘希夷 从军行"],["一室何劳扫，三章自不冤。","杜牧 奉送中丞姊夫俦自大理卿出镇江西叙事书怀因成十二韵"]]},{"n":"三君","d":"","s":"《后汉书》卷六十七〈党锢列传〉","q":[]},{"n":"题舆","d":"","s":"《太平御览》卷二六三","q":[["辍史空三署，题舆佐一方。","张谔 送李著作倅杭州"],["名参汉望苑，职述景题舆。","杜甫 寄李十四员外布十二韵"]]},{"n":"膺蕃","d":"","s":"《世说新语笺疏》上卷上〈德行〉～","q":[]},{"n":"仲举","d":"","s":"《后汉书》卷六十六《陈蕃传》","q":[["仲举登宰辅，太丘荣缙绅。","储光羲 敬酬陈掾亲家翁秋夜有赠"],["茂先实王佐，仲举信时英。","裴耀卿 敬酬张九龄当涂界留赠之作"]]}],"119":[{"n":"悬剑","d":"挂剑：表示追念亡友。宋黄庭坚《李浸州挽词》：“虽云挂剑来坟上，亦恐藏书在壁中。”","s":"《史记》卷三十一〈吴太伯世家〉","q":[["曾被桂树枝，寒光射林薮。","元稹 说剑"],["碑传门客建，剑是故人留。","崔堤 秦州薛都督挽词"]]},{"n":"歌唐虞","d":"","s":"《春秋左传·襄公二十九年》","q":[["陶唐歌遗民，后汉更列帝。","杜甫 送樊二十三侍御赴汉中判官"],["微臣徒窃抃，岂足歌唐虞。","权德舆 奉和圣制重阳日中外同欢以诗言志因示百僚"]]},{"n":"号三匝","d":"","s":"《礼记·檀弓下》","q":[["绕坟不暇号三匝，设祭惟闻饭一盘。","韩愈 去岁自刑部侍郎以罪贬潮州刺史乘驿赴任（一作之官）其后家亦遣逐小女道死殡之层峰驿旁（一作之）山下蒙恩还朝（一作今）过其墓留题驿梁"]]},{"n":"延陵季子","d":"","s":"《史记》卷三十一〈吴太伯世家〉","q":[["季子生前别，羊昙醉后悲。","司空曙 哭苗员外呈张参军"],["延陵称贵邑，季子有高踪。","李频 送延陵韦少府"]]},{"n":"季札辨","d":"季札听歌：指欣赏乐舞。唐韩翊《宴吴王宅》：“听歌吴季札，纵饮汉中山。”","s":"《春秋左传·襄公二十九年》","q":[["惉滞难令季札辨，迟回但恐文侯卧。","元稹 立部伎"],["听歌吴季札，纵饮汉中山。","韩翃 宴吴王宅"]]},{"n":"季子高风","d":"","s":"《春秋左传正义》卷三十二〈襄公·传十四年〉","q":[]},{"n":"季子邑","d":"","s":"《史记》卷三十一〈吴太伯世家〉","q":[["清风季子邑，想见下车时。","刘长卿 送李挚赴延陵令"]]},{"n":"君子墓","d":"","s":"《礼记·檀弓下》","q":[["延陵今葬子，空使鲁人观。","司空曙 哭王注"],["有吴君子墓，返葬故山遥。","窦牟 故秘监丹阳郡公延陵包公挽歌"]]},{"n":"赠缟","d":"","s":"《春秋左传·襄公二十九年》","q":[["既闻留缟带，讵肯掷蓍簪。","韦庄 同旧韵"],["缔交君赠缟，投分我忘筌。","骆宾王 夏日游德州赠高四"]]}],"120":[{"n":"高歌商颂","d":"","s":"《庄子集释》卷九下〈杂篇·让王〉","q":[["高歌足自快，商颂有遗音。","柳宗元 贡衰"],["风松韵里忘形坐，霜月光中共影行。","齐己 叙怀寄高推官"]]},{"n":"家贫别亲","d":"","s":"《韩诗外传》卷七","q":[["君行别老亲，此去苦家贫。","杜甫 送孟十二仓曹赴东京选"]]},{"n":"梁山曲","d":"","s":"旧题汉·蔡邕《琴操》卷下《梁山操》","q":[["白雪梁山曲，寒风易水歌。","骆宾王 夏日游德州赠高四"]]},{"n":"三省","d":"","s":"《论语注疏·学而》","q":[["一叨尉京甸，三省惭黎元。","钱起 初黄绶赴蓝田县作"],["揆拙迷三省，劳生昧两忘。","骆宾王 在江南赠宋五之问"]]},{"n":"宿草","d":"","s":"《礼记·檀弓上》","q":[["旧交封宿草，衰鬓重生刍。","李绅 趋翰苑遭诬构四十六韵"],["鸰原荒宿草，凤沼接亨衢。","杜甫 赠韦左丞丈"]]},{"n":"堂堂张","d":"","s":"《论语·子张》","q":[["谔谔宁惭直，堂堂不谢张。","韦庄 和郑拾遗秋日感事一百韵"]]},{"n":"细人姑息","d":"","s":"《礼记注疏》卷六〈檀弓上〉","q":[["细人尚姑息，吾子色愈谨。","杜甫 赠郑十八贲"]]},{"n":"晏子赠行","d":"","s":"《晏子春秋》卷五《内篇杂上》","q":[["相国齐晏子，赠行不及言。","李白 郑鲁郡刘长史迁弘农长史"]]},{"n":"易篑","d":"","s":"《礼记·檀弓上》","q":[["遗音和蜀魄，易箦对巴猿。","李商隐 哭遂州萧侍郎二十四韵"]]}],"121":[{"n":"白袍","d":"","s":"《南史》卷六十一《陈庆之传》","q":[["忆昔范增碎玉斗，未使吴兵著白袍。","杜甫 久雨期王将军不至"]]},{"n":"白铜鞮","d":"","s":"《隋书》卷十三《音乐志上》","q":[["春风慎行李，莫上白铜鞮。","朱庆余 送陈摽"]]},{"n":"磨楯鼻","d":"","s":"《北史》卷八十三〈文苑列传·荀济〉","q":[["郡公楯鼻好磨墨，走马为君飞羽书。","韩翃 寄哥舒仆射"]]},{"n":"金瓯","d":"","s":"《梁书》卷五十六〈侯景列传〉","q":[["兵围梁殿金瓯破，火发陈宫玉树摧。","司空图 南北史感遇十首"],["玉井已乾龙不起，金瓯虽破虎曾争。","罗隐 台城"]]},{"n":"同泰寺","d":"","s":"《南史》卷七《梁本纪·武帝纪下》","q":[["何须同泰寺，然后始为奴。","李群玉 龙安寺佳人阿最歌八首"]]},{"n":"下殿趋","d":"","s":"《北史》卷五《魏本纪·孝武帝纪》","q":[["有甚当车泣，因劳下殿趋。","李商隐 有感二首"]]},{"n":"萧家菖蒲花","d":"","s":"《梁书》卷七《太祖张皇后传》","q":[["风彩出萧家，本是菖蒲花。","李贺 梁公子"]]},{"n":"萧寺","d":"","s":"《梁书》卷五十《文学传下·任孝恭传》","q":[["萧寺春风正落花，淹留数宿惠休家。","刘沧 晚春宿僧院"],["萧寺楼台对夕阴，淡烟疏磬散空林。","刘沧 秋日山寺怀友人"]]},{"n":"萧郎","d":"","s":"《梁书》卷一〈武帝本纪上〉","q":[]}],"122":[{"n":"铩翮","d":"","s":"《昭明文选》卷二十一南朝宋·颜延年（延之）《五君?五首·嵇中散》","q":[["鸾凤有铩翮，先儒曾抱麟。","杜甫 敬寄族弟唐十八使君"],["振此铩翮，扇之腾翻。","裴潾 前相国赞皇公早葺平泉山居暂还憩旋起赴诏命作镇浙右辄抒怀赋四言诗十四首奉寄之十三"]]},{"n":"光禄","d":"","s":"《宋书》卷七十三《颜延之传》","q":[["可但步兵偏爱酒，也知光禄最能诗。","严武 巴岭答杜二见忆"]]},{"n":"五君咏","d":"","s":"《宋书》卷七十三〈颜延之列传〉","q":[["时吟五君咏，再举七子风。","孟郊 上包祭酒"],["高吟五君咏，疑对九华峰。","聂夷中 题贾氏林泉"]]},{"n":"延年作","d":"","s":"《宋书》卷七十三《颜延之传》","q":[["延年如有作，应不用山王。","李德裕 仆射相公偶话于故集贤张学士厅写得德裕与仆射旧唱和诗其时和者五人惟仆射与德裕皆列高位凄然怀旧辄献此诗"]]},{"n":"颜范","d":"","s":"《昭明文选》卷二十五卷南朝宋·谢灵运《还旧园作见颜范二中书》","q":[["明日中书见颜范，始应通籍入金门。","李群玉 送于少监自广州还紫逻"],["此时颜范贵，十步旧连行。","杨凝 和直禁省"]]},{"n":"颜公付酒钱","d":"","s":"《宋书》卷九十三《隐逸传·陶潜传》","q":[["颜公二十万，尽付酒家钱。","李白 赠宣城宇文太守兼呈崔侍御"]]},{"n":"颜谢","d":"","s":"《宋书》卷七十三《颜延之传》","q":[["颜谢徵文并，钟裴直事同。","司空曙 奉和常舍人晚秋集贤院即事寄徐薛二侍郎"],["世业大小礼，近通颜谢诗。","戴叔伦 抚州对事后送外生宋垓归饶州觐侍呈上姊夫"]]},{"n":"一麾出守","d":"","s":"《昭明文选》卷二十一南朝宋·颜延年（延之）《五君咏五首·阮始平》","q":[["莫笑一麾东下计，满江秋浪碧参差。","杜牧 即事"],["欲把一麾江海去，乐游原上望昭陵。","杜牧 将赴吴兴登乐游原一绝"]]},{"n":"颜鲍","d":"","s":"《宋书》卷五十一《宗室传·刘义庆传》附《鲍照传》","q":[["不复见颜鲍，系舟卧荆巫。","杜甫 遣怀"]]}],"123":[{"n":"龚黄","d":"","s":"《汉书》卷八十九《循吏传序》","q":[["共蹑华胥梦，龚黄安足寻。","张说 奉和圣制赐诸州刺史应制以题坐右"],["晋楚忙忙起战尘，龚黄门外有高人。","徐夤 依韵赠南方处士五首之五"]]},{"n":"黄颍川","d":"","s":"《汉书》卷八十九《循吏传·黄霸传》","q":[["黄霸宁淹留，苍生望腾鶱。","岑参 潼关镇国军句覆使院早春寄王同州"],["黄霸官犹屈，苍生望已愆。","岑参 西河太守杜公挽歌四首之一"]]},{"n":"黄霸玺书增","d":"","s":"《汉书》卷八十九《循吏传序》","q":[["潘生骖阁远，黄霸玺书增。","杜甫 寄刘峡州伯华使君四十韵"]]},{"n":"张高盖","d":"","s":"《汉书》卷八十九〈循吏列传·黄霸〉","q":[["莫羡黄公盖，须乘彦伯舟。","岑参 送襄州任别驾"]]},{"n":"攫肉","d":"","s":"《汉书》卷八十九《循吏传·黄霸传》","q":[["无乃饥啼走道旁，贪鲜攫肉人所伤。","柳宗元 跂乌词"]]},{"n":"让田","d":"","s":"《史记》卷二十《建元以来侯者年表》","q":[["威惩治粟尉，恩洽让田人。","卢纶 寄赠库部王郎中（时充折｛★｝使）"]]},{"n":"下凤皇","d":"","s":"《汉书》卷八十九〈循吏列传·黄霸〉","q":[["川路风烟接，俱宜下凤皇。","杜甫 江亭王阆州筵钱萧遂州"]]},{"n":"颍川政","d":"","s":"《汉书》卷八十九《循吏传·黄霸传》","q":[["徵黄看即及，莫叹滞江城。","李汉儒 和绵州于中丞登越王楼作"],["已向为霖报消息，颍川徵诏是前期。","李群玉 送崔使君萧山祷雨甘泽遽降"]]},{"n":"治最","d":"","s":"《汉书》卷八十九〈循吏列传·黄霸〉","q":[]}],"124":[{"n":"班马香","d":"","s":"杜牧《冬至日寄小侄阿宜诗》","q":[]},{"n":"班马","d":"","s":"《晋书》卷八十二《陈寿等传论》","q":[["高摘屈宋艳，浓薰班马香。","杜牧 冬至日寄小侄阿宜诗"],["绮园难贮林栖意，班马须持笔削权。","黄滔 遇罗员外衮"]]},{"n":"班扬","d":"","s":"《昭明文选》卷六十南朝宋·王僧达《祭颜光禄文》","q":[["班扬名甚盛，嵇阮逸相须。","杜甫 哭台州郑司户苏少监"],["斯文崔魏徒，以我似班扬。","杜甫 壮游"]]},{"n":"班氏业前书","d":"","s":"《后汉书》卷四十上《班彪传》附《班固传》","q":[["韦门旌旧德，班氏业前书。","宋之问 故赵王属赠黄门侍郎上官公挽词"]]},{"n":"风云","d":"","s":"《汉书》卷一百上〈叙列传上〉","q":[["分随烟霞老，岂有风云求。","李群玉 洞庭驿楼雪夜宴集奉赠前湘州张员外"],["汉朝卿相尽风云，司马题桥众又闻。","汪遵 升仙桥"]]},{"n":"下笔不休","d":"","s":"《昭明文选》卷五十二、三国魏·魏文帝（曹丕）《典论论文》","q":[["文轻傅武仲，酒逼盖宽饶。","刘禹锡 酬杨八庶子喜韩吴兴与余同迁见赠"],["学富赡清词，下笔不能休。","岑参 冀州客舍酒酣贻王绮寄题南楼"]]},{"n":"赋两都","d":"","s":"《后汉书》卷四十上《班彪传》附《班固传》","q":[["始觉石楠咏，价倾赋两都。","孟郊 和宣州钱判官使院厅前石楠树"]]},{"n":"迁固","d":"","s":"《南齐书》卷五十二《文学传·崔慰祖传》","q":[["入掌迁固笔，出参枚马词。","崔湜 景龙二年余自门下平章事削阶授江州员外司马寻拜襄州刺史春日赴襄阳途中言志"]]},{"n":"优游慕陆","d":"","s":"《昭明文选》卷四十五东汉·班孟坚（固）《答宾戏》","q":[["优游应慕陆，止足定师张。","皎然 因游支硎寺寄邢端公"]]}],"125":[{"n":"旧青毡","d":"青毡：喻先祖遗物，或喻旧业。唐卢纶《寄郑七纲》：“他日吴公如记问，愿将黄绶比青毡。”","s":"《晋书》卷八十〈王羲之列传·（徽之子）王献之〉","q":[["来时虽恨失青毡，自见芭蕉几十篇。","司空图 狂题十八首"],["卜羡君平杖，偷存子敬毡。","杜甫 秋日夔府咏怀奉寄郑监李宾客一百韵"]]},{"n":"渡江曲","d":"","s":"《艺文类聚》卷四十三〈乐部三·歌〉","q":[]},{"n":"二王","d":"","s":"北齐·颜之推《颜氏家训》卷七《杂艺》","q":[["书札二王争巧拙，篇章七子避风流。","罗隐 寄酬邺王罗令公五首"]]},{"n":"人那得知","d":"人那得知：喻父子书法皆工妙。唐柳宗元《重赠二首》之一：“如今试遣隈墙问，已道世人那得知。”","s":"《世说新语》中卷下《品藻》","q":[["如今试遣隈墙问，已道世人那得知。","柳宗元 重赠二首"]]},{"n":"桃叶","d":"","s":"《乐府诗集》卷四十五《桃叶歌三首》","q":[["俗侣唱桃叶，隐士鸣桂琴。","孟郊 答昼上人止谗作"],["竹枝游女曲，桃叶渡江词。","张登 上巳泛舟得迟字"]]},{"n":"王郎穿屐","d":"","s":"《世说新语笺疏》下卷上〈简傲〉","q":[]},{"n":"王子敬","d":"","s":"《晋书》卷八十〈王羲之列传·（徽之子）王献之〉","q":[["神清王子敬，气逐马相如。","张南史 早春书事奉寄中书李舍人"]]},{"n":"谢安问献之","d":"","s":"《晋书》卷八十《王羲之传》附《王献之传》","q":[["忆昔谢安问献之，时人虽见那得知。","权德舆 马秀才草书歌"]]},{"n":"谢女解围","d":"","s":"《晋书》卷九十六《列女传·王凝之妻谢氏传》","q":[["齐后破坏，谢女解围。","李瀚 蒙求"]]}],"126":[{"n":"干将","d":"","s":"《吴越春秋》卷四〈阖闾内传·阖闾元年〉","q":[["我闻音响异，疑是干将偶。","元稹 说剑"],["吴溪漫淬干将剑，却是猿声断客肠。","张祜 题弋阳馆"]]},{"n":"阖闾邦","d":"","s":"《史记》卷三十一〈吴太伯世家〉","q":[]},{"n":"阖闾墓","d":"","s":"《吴地记》","q":[]},{"n":"巨阙","d":"","s":"《荀子·性恶》","q":[["笔下铦磨巨阙锋，胸中静滟西江水。","僧鸾 赠李粲秀才"]]},{"n":"倾吴市","d":"","s":"《吴越春秋》卷四〈阖闾内传·阖闾三年〉","q":[["宛转能倾吴国市，裴回巧拂汉皇坛。","武三思 仙鹤篇"]]},{"n":"水晶宫","d":"","s":"《述异记》卷上","q":[["苑外江头坐不归，水精春殿转霏微。","杜甫 曲江对酒"]]},{"n":"要离","d":"","s":"《吴越春秋》卷四〈阖闾内传·阖闾二年〉","q":[]},{"n":"湛卢","d":"","s":"《越绝书》卷十一《越绝外传·记宝剑》","q":[["朝士兼戎服，君王按湛卢。","杜甫 大历三年春白帝城放船出瞿塘峡久居夔府将适江陵漂泊有诗凡四十韵"]]},{"n":"湛卢飞","d":"","s":"《吴越春秋》卷四《阖闾内传》","q":[["行叹鸱夷没，遽惜湛卢飞。","骆宾王 夕次旧吴"]]}],"127":[{"n":"邹枚","d":"","s":"《史记》卷一百一十七〈司马相如列传〉","q":[["邹枚入梁苑，逸少在山阴。","刘长卿 寄会稽公徐侍郎"],["文学引邹枚，歌钟陈卫霍。","张说 药园宴武辂沙将军赋得洛字"]]},{"n":"梁园赋","d":"延枚：指延集宾客。唐李商隐《忆雪》：“预约延枚酒，虚乘访戴船。”；授简：指奉命吟诗作赋。唐杜甫《又作此奉卫王》：“白头授简焉能赋，愧似相如为大夫。”","s":"《西京杂记》卷二","q":[["孙室临书幌，梁园泛酒杯。","令狐楚 省中直夜对雪寄李师素侍郎"],["有客怀兔园，吟诗绕城内。","曹邺 贺雪寄本府尚书"]]},{"n":"枚叟","d":"","s":"《汉书》卷五十一〈贾邹枚路传·枚乘列传〉","q":[["伍生传或谬，枚叟说难穷。","宋昱 樟亭观涛"],["湖清霜镜晓，涛白雪山来。八月枚乘笔，三吴张翰杯。","李白 送友人寻越中山水"]]},{"n":"枚皋扈仙跸","d":"","s":"《汉书》卷五十一〈贾邹枚路传·枚乘·（子）枚皋～〉2366～","q":[["目断枚皋何处在，阑干十二忆登临。","吴融 八月十五夜禁直寄同僚"],["待得枚皋相见日，自应妆镜笑蹉跎。","杜牧 见刘秀才与池洲妓别"]]},{"n":"枚马","d":"","s":"《文心雕龙》卷二〈诠赋〉","q":[["入掌迁固笔，出参枚马词。","崔湜 景龙二年余自门下平章事削阶授江州员外司马寻拜襄州刺史春日赴襄阳途中言志"],["徐陈尝并作，枚马亦同时。","张说 酬崔光禄冬日述怀赠答"]]},{"n":"枚叔愈疾","d":"","s":"《昭明文选》卷三十四汉·枚叔（乘）《七发》","q":[["愈疾同枚叔，销忧比仲宣。","赵冬羲 奉酬燕公见归田赋垂赠之作"]]},{"n":"枚藻","d":"","s":"《汉书》卷五十一《枚乘传》","q":[["枚藻清词律，邹谈耀辩锋。","李峤 夏晚九成宫呈同僚"]]},{"n":"王枚","d":"","s":"《汉书》卷六十四〈严朱吾丘主父徐严终王贾列传·王褒〉","q":[["王枚俱得从，浅浅愧飞毫。","李适 奉和圣制九日侍宴应制得高字"],["谬忝王枚列，多惭雨露恩。","武平一 奉和幸新丰温泉宫应制"]]},{"n":"微缕悬千钧","d":"","s":"《汉书》卷五十一《枚乘传》","q":[["高堂委金玉，微缕悬千钧。","陈子昂 感遇诗三十八首之二十四"]]}],"128":[{"n":"从毛薛","d":"","s":"《史记》卷七十七〈魏公子列传〉","q":[["邯郸能屈节，访博从毛薛。","李白 博平郑太守自庐山千里相寻入江夏北市门见访却之武陵立马赠别"]]},{"n":"朱公子","d":"","s":"《史记》卷七十七《魏公子列传》","q":[["救赵挥金槌，邯郸先震惊。","李白 侠客行"],["救赵复存魏，英威天下闻。","李白 博平郑太守自庐山千里相寻入江夏北市门见访却之武陵立马赠别"]]},{"n":"妇人醇酒","d":"","s":"《史记》卷七十七〈魏公子列传〉","q":[]},{"n":"侯生遭骂","d":"","s":"《史记》卷七十七〈魏公子列传〉","q":[["冶长信非罪，侯生或遭骂。","韩愈 县斋有怀"]]},{"n":"买丝绣平原","d":"","s":"《史记》卷七十六〈平原君虞卿列传·平原君〉","q":[["买丝绣作平原君，有酒惟浇赵州土。","李贺 浩歌"]]},{"n":"三千客","d":"三千客：指贵客盈门。宋范成大《次韵甄云卿晚登浮丘亭》：“宾筵旧压三千客，燕榭新高十二城。”","s":"《史记》卷七十七〈魏公子列传〉","q":[["食恩三千士，一旦为豺狼。","孟郊 汴州离乱后忆韩愈李翱"],["若无三千客，谁道信陵君。","李白 博平郑太守自庐山千里相寻入江夏北市门见访却之武陵立马赠别"]]},{"n":"四佳公子","d":"","s":"《汉书》卷九十二〈游侠列传〉","q":[]},{"n":"信陵君","d":"","s":"《史记》卷七十七《魏公子列传》","q":[["忽乃异群萃，高歌信陵门。信陵好宾客，清夜开华轩。","储光羲 舟中别武金坛"],["日入信陵宾馆静，赠君闲步月明中。","刘商 赠严四草履"]]},{"n":"魏王卧内藏兵符","d":"","s":"《史记》卷七十七《魏公子列传》","q":[["魏王卧内藏兵符，子西掩袂真无辜。","柳宗元 古东门行"]]}],"129":[{"n":"八公山","d":"八公山：指战争失利之地。唐李白《送张遥之寿阳幕府》；“苻坚百万众，遥阻八公山。”","s":"《晋书》卷一一四《苻坚载记下》","q":[["遥知用兵处，多在八公山。","刘长卿 奉陪使君西庭送淮西魏判官"],["苻坚百万众，遥阻八公山。","李白 送张遥之寿阳幕府"]]},{"n":"风声鹤唳","d":"风声鹤唳：指因兵败而惊惧。清黄景仁《寿阳》：“地经白马青丝后，山在风声鹤唳中。”","s":"《晋书》卷七十九〈谢安列传·（奕子）谢玄〉","q":[]},{"n":"童子是苍蝇","d":"","s":"《晋书》卷一一三《苻坚载记》","q":[["议赦蝇栖笔，邀歌蚁泛醪。","刘禹 浙西李大夫述梦四十韵并浙东元相公酬和斐然继声"],["共望汉朝多沛泽，苍蝇早晚得先知。","司空曙 酬崔峒见寄"]]},{"n":"曹苻气势","d":"","s":"《资治通鉴》卷六十五〈汉纪五十七·孝献皇帝庚·建安十三年〉","q":[]},{"n":"凤臆","d":"","s":"《晋书》卷一一三《苻坚载记上》","q":[["凤臆龙鬐未易识，侧身注目长风生。","杜甫 李鄠县丈人胡马行"]]},{"n":"苻坚","d":"","s":"《晋书》卷一一三、四《苻坚载记上、下》","q":[["小儒轻董卓，有识笑苻坚。","杜甫 寄岳州贾司马六丈巴州严八使君两阁老五十韵"]]},{"n":"苻坚棰","d":"投鞭填江：喻兵众势大。唐李白《登金陵冶城西北谢安墩》：“投鞭可填江，一扫何足论。”","s":"《晋书》卷一百一十四〈苻坚载记下〉","q":[["投鞭可填江，一扫不足论。","李白 登金陵冶城西北谢安墩"],["魏帝缝囊真戏剧，苻坚投箠更荒唐。","杜牧 西江怀古"]]},{"n":"鹤唳","d":"","s":"《晋书》卷七十九《谢安传》附《谢玄传》","q":[["残兵疑鹤唳，空垒辩乌声。","刘禹锡 赠澧州高大夫司马霞寓"]]},{"n":"扣马陈","d":"","s":"《晋书》卷一一三《苻坚载记上》","q":[["袖中谏猎书，扣马久上陈。","杜甫 八哀诗（并序）赠太子太师汝阳郡王琎"]]}],"130":[{"n":"百神迎","d":"","s":"《春秋左传·哀公七年》","q":[["祝尧三老至，会禹百神迎。","苗晋卿 奉和圣制早登太行山中言志"]]},{"n":"扈苗征","d":"","s":"《尚书·夏书·甘誓》","q":[["安得封域内，长有扈苗征。","杜牧 感怀诗一首"]]},{"n":"九畴","d":"","s":"《尚书》卷十二〈周书·洪范〉","q":[["不停两鸟鸣，大法失九畴。","韩愈 双鸟诗"]]},{"n":"九鼎","d":"","s":"《史记》卷十二〈孝武本纪〉","q":[["鳌冠三山安海浪，龙盘九鼎镇皇都。","司空图 淮西"],["天地尘昏九鼎危，大貂曾出武侯师。","吴融 敷水有丐者云是马侍中诸孙悯而有赠"]]},{"n":"平水土","d":"","s":"《尚书·虞书·舜典》","q":[["大禹平水土，吾人得其宗。","吕温 登少陵原望秦中诸川太原王至德妙用（一本无用字）有水术因用感叹"],["用为羲和天为成，用平水土地为厚。","杜甫 可叹"]]},{"n":"舜禹让旒","d":"","s":"《史记》卷一《五帝本纪·舜本纪》","q":[["伊皋争负鼎，舜禹让垂旒。","徐夤 依御史温飞卿华清宫二十二韵"]]},{"n":"唐尧咨禹","d":"","s":"《尚书》卷三〈虞书·舜典〉","q":[]},{"n":"涂山会","d":"","s":"《春秋左传·哀公七年》","q":[["涂山已见首诸侯，麟阁终当画元老。","权德舆 奉和张仆射朝天行"],["百灵侍轩后，万国会涂山。","魏徵 奉和正日临朝应诏"]]},{"n":"鸟耘","d":"","s":"东汉·王充《论衡》卷四《书虚》","q":[["万方同象鸟，举恸满秋尘。","李商隐 昭肃皇帝挽歌辞三首之三"]]}],"131":[{"n":"送君南浦","d":"","s":"《昭明文选》卷十六〈赋辛·哀伤·别赋〉","q":[["悔作望南浦，望中生远愁。","于武陵 远水"],["东城草虽绿，南浦柳无枝。","储嗣宗 赠别"]]},{"n":"碧云句","d":"","s":"《昭明文选》卷三十一〈诗庚·杂拟下·杂体诗三十首·休上人别怨〉","q":[["诗誇碧云句，道證青莲心。","孟郊 送清远上人归楚山旧寺"],["不见休上人，空伤碧云思。","李群玉 怀初公"]]},{"n":"五色笔","d":"才尽：喻因年老而才思退减。唐杜甫《送顾八分文学适洪吉州》：“才尽伤形体，病渴污官位。”；江淹梦：指文采不凡。唐方干《再题路支使南亭》：“睡时分得江淹梦，五色毫端弄逸才。”","s":"《南史》卷五十九〈江淹列传〉","q":[["锦窠不是寻常锦，兼向丘迟夺得来。","司空图 少仪"],["都缘有意重熏裛，更洒江毫上玉堂。","吴融 薛舍人见徵恩赐香并二十八字同寄"]]},{"n":"江鲍","d":"","s":"南朝梁·钟嵘《诗品》卷中","q":[["览君荆山作，江鲍堪动色。","李白 经乱离后天恩流夜郎忆旧游书怀赠江夏韦太守良宰"],["流传江鲍体，相顾免无儿。","杜甫 赠毕四（曜）"]]},{"n":"江淹赋别","d":"","s":"《昭明文选》卷十六南朝梁·江文通（淹）《别赋》","q":[["欲知肠断相思处，役尽江淹别后魂。","赵光远 题妓莱儿壁一作题北里妓人壁"],["江生魂黯黯，泉客泪涔涔。","李商隐 自桂林奉使江陵途中感怀寄献尚书"]]},{"n":"江淹恨","d":"","s":"《昭明文选》卷十六南朝梁·江文通（淹）《恨赋》","q":[["王粲销忧日，江淹起恨年。","李峤 原（杂咏诗百二十首。全唐诗所载缺文颇多。今照此邦所传古文补书之。已附此。旧缺膴膴二字。下莓作苔）"]]},{"n":"江淹拟诗","d":"","s":"南朝梁·钟嵘《诗品》卷中","q":[["为向东州故人道，江淹已拟惠休诗。","李益 送贾校书东归寄振上人（一作振上人院喜见贾弇兼酬别）"]]},{"n":"排冥筌","d":"","s":"《昭明文选》卷三十一南朝梁·江文通（淹）《杂体诗三十首·许徵君自序》","q":[["何当共携手，相与排冥筌。","李白 赠饶阳张司户燧"]]},{"n":"孺人稚子","d":"","s":"《昭明文选》卷十六南朝梁·江文通（淹）《恨赋》","q":[["已呼孺人戛鸣瑟，更遣稚子传清杯。","韩愈 感春五首之一"]]}],"132":[{"n":"章台路","d":"章台走马：指风流潇洒。唐李白《流夜郎赠辛判官》：“夫子红颜我少年，章台走马著金鞭。”","s":"《汉书》卷七十六〈赵尹韩张两王列传·张敞〉","q":[["骑别章台晚，舟行洛水春。","储光羲 秦中送人觐省"],["京兆归何处，章台空暮尘。","刘禹锡 再伤庞尹"]]},{"n":"京兆画","d":"","s":"《汉书》卷七十六〈赵尹韩张两王列传·张敞〉","q":[["青楼邻里妇，终年画长眉。自倚对良匹，笑妾空罗帏。","于濆 古别离"],["买笑楼前花已谢，画眉窗下月空残。","刘损 愤惋诗三首"]]},{"n":"画远山","d":"","s":"《汉书》卷七十六〈赵尹韩张两王列传·张敞〉","q":[]},{"n":"理剧推张","d":"","s":"《汉书》卷七十六〈赵尹韩张两王列传·张敞〉","q":[["训刑方命吕，理剧复推张。","柳宗元 弘农公以硕德伟材屈于诬枉左官三岁复为大僚天监昭明人心感悦宗元窜伏湘浦拜贺末由谨献五十韵以毕微志"]]},{"n":"五日京兆","d":"五日尹：指为官时日短。宋陆游《闻勾龙司户会客山亭送酒肴及橄榄并简诸同僚》：“但恨五日尹，阻造三语椽。”","s":"《汉书》卷七十六〈赵尹韩张两王列传·张敞〉","q":[["翻同五日尹，遽见一星亡。","卢照邻 哭金部韦郎中"]]},{"n":"张京兆","d":"","s":"《汉书》卷七十六《张敞传》","q":[["内史称张敞，苍生借寇恂。","元稹 代曲江老人百韵"],["处剧张京兆，通经戴侍中。","李商隐 今月二日不自量度辄以诗一首四十韵干渎尊严伏蒙仁恩俯赐披览奖逾其实"]]},{"n":"张王","d":"","s":"《汉书》卷七十六〈赵尹韩张两王列传〉","q":[]},{"n":"赵张","d":"","s":"《汉书》卷七十六《赵尹韩张两王传》","q":[["预传籍籍新京尹，青史无劳数赵张。","杜甫 章梓州桔亭钱成都窦少尹"],["独安巡狩日，曾掩赵张名。","卢纶 雪谤后书事上皇甫大夫"]]}],"133":[{"n":"负荆","d":"负荆：指向朋友请罪、道歉。唐李白《自广平乘醉走马六十里至邯郸登城楼览古书怀》：“两虎不可斗，廉公终负荆。”指认错赔礼。晋卢湛《览古》：“屈节邯郸中，俯首忍回轩、廉公何为者，负荆谢厥愆。”","s":"《史记》卷八十一《廉颇蔺相如列传》","q":[["凶丑将除蔓，奸豪已负荆。","刘长卿 至德三年春正月时谬蒙差摄海盐令闻王师收二京因书事寄上浙西节度李侍郎中丞行营五十韵"],["两虎不可斗，廉公终负荆。","李白 自广平乘醉走马六十里至邯郸登城楼览古书怀"]]},{"n":"怀赵","d":"","s":"《史记》卷八十一《廉颇蔺相如列传》","q":[["顾土虽怀赵，知天讵畏匡。","柳宗元 弘农公以硕德伟才屈于诬枉左官三岁复为大僚天监昭明人心感悦宗元窜伏湘浦拜贺末由谨献诗五十韵以毕微志"]]},{"n":"廉李","d":"","s":"《史记》卷八十一〈廉颇蔺相如列传〉","q":[]},{"n":"廉蔺","d":"廉蔺：喻指将相忠心为国而结下深厚友谊。唐李白《醉后赠从甥高镇》：“时清不及英豪人，三尺儿童重廉蔺。”","s":"《后汉书》卷七十《孔融传》","q":[["时清不及英豪人，三尺童儿重廉蔺。","李白 醉后赠从甥高镇"],["廉蔺若未死，孙吴知暗同。","高适 李云南征蛮诗"]]},{"n":"廉颇","d":"廉颇：指老将。唐张说《南中送北使》之二；“廉颇诚未老，孙叔巨无谋。”清顾炎武《郝将军今为医客于吴之卜津桥言及旧事感而有赠》：“人楚廉颇犹未老，过秦扁鹊更能工。”","s":"《史记》卷八十一《廉颇蔺相如列传》","q":[["谁道廉颇老，犹能报远雠。","李端 赠故将军"],["昔观文苑传，岂述廉蔺绩。","杜甫 八哀诗赠司空王公思礼"]]},{"n":"三遗矢","d":"三遗矢：喻年老体弱。清赵翼《吴门晤范洽园编修》：“何当老态三遗矢，还附名流一瓣香。”；强饭廉颇：喻老当益壮者。宋陆游《亲旧见过多见贺强健戏作此篇》：“据鞍马援虽堪笑，强饭廉颇亦未非。”","s":"《史记》卷八十一〈廉颇蔺相如列传〉","q":[["似鸮占贾谊，上马试廉颇。","刘长卿 奉寄婺州李使君舍人"]]},{"n":"两虎斗","d":"","s":"《史记》卷八十一《廉颇蔺相如列传》","q":[["赵倚两虎斗，晋为六卿分。","李白 古风之五十三"]]},{"n":"刎颈交","d":"","s":"《史记》卷八十一〈廉颇蔺相如列传〉","q":[]}],"134":[{"n":"八百里","d":"","s":"《世说新语笺疏》下卷下〈汰侈〉","q":[]},{"n":"比玉","d":"","s":"《世说新语笺疏》下卷上〈容止〉","q":[["尝值偷琴处，亲闻比玉时。","司空曙 哭苗员外呈张参军"]]},{"n":"马埒","d":"铺钱埒：指生活豪侈。唐宗楚客《安乐公主移入新宅待宴应制》：“马向铺钱埒，箫闻弄玉台。”","s":"《世说新语笺疏》下卷下〈汰侈〉","q":[["玉环腾远创，金埒荷殊荣。","上官婉儿 游长安公主流杯池二十五首"],["马埒蓬蒿藏狡兔，凤楼烟雨啸愁鸱。","刘禹锡 题于家公主旧宅"]]},{"n":"千里莼","d":"","s":"《世说新语笺疏》上卷上〈言语〉","q":[["若逢广坐问羊酪，从此知名在一言。","刘禹锡 送周鲁儒赴举诗并引"],["江左重诗篇，陆生名久传。凤城来已熟，羊酪不嫌膻。","刘禹锡 送陆侍御归淮南使府五韵（用年字）"]]},{"n":"马癖","d":"","s":"《晋书》卷四十二〈王浑列传·（子）王济〉","q":[["邓公马癖人共知，初得花骢大宛种。","杜甫 骢马行"],["难逢王济知音癖，欲就燕昭买骏名。","韩琮 咏马"]]},{"n":"王济尚味","d":"","s":"《世说新语》下卷下《汰侈》","q":[["王济本尚味，石崇方斗奢。","刘禹锡 崔元受少府自贬所还遗山姜花以诗答之"]]},{"n":"卫玠","d":"卫玠：用于称美外甥。唐李端《酬丘拱外甥览余旧文见寄》：“舅乏郗鉴爱，君如卫玠贤。”","s":"《世说新语笺疏》下卷上〈容止〉","q":[["花当西施面，泉胜卫玠清。","元稹 独游"],["舅乏郤鉴爱，君如卫玠贤。","李端 酬丘拱外甥览余旧文见寄"]]},{"n":"武子","d":"","s":"《晋书》卷四十二〈王浑列传·（子）王济〉","q":[["王浑知武子，陈寔奖元方。","杨巨源 上刘侍中"]]}],"135":[{"n":"除道","d":"","s":"《汉书》卷六十四上《朱买臣传》","q":[["蒸鱼闻匕首，除道哂要章。","杜甫 壮游"]]},{"n":"负樵","d":"买臣负薪：喻寒士遭厄，或喻世态炎凉。唐白居易《读史》之五：“买臣负薪日，妻亦弃如遗。”；买臣负薪：喻大器晚成。清吴伟业《过朱买臣墓》：“行年五十功名晚，何似空山长负薪。”","s":"《汉书》卷六十四上《朱买臣传》","q":[["宁武子，朱买臣，扣角行歌背负薪。","李白 笑歌行（以下二首。苏轼云是伪作。）"],["买臣负薪日，妻亦弃如遗。","白居易 读史五首"]]},{"n":"会稽章","d":"","s":"《汉书》卷六十四上《朱买臣传》","q":[["疏受杜门期脱屣，买臣归邸忽乘轺。","李绅 初秋忽奉诏除浙东观察使检校右貂"],["家临浙水傍，岸对买臣乡。","李频 及第后归"]]},{"n":"买臣","d":"","s":"《汉书》卷六十四上《朱买臣传》","q":[["沈生隐侯胤，朱子买臣孙。","孟浩然 夜登孔伯昭南楼时沈太清朱升在座"],["终岁逍遥仁术内，无名甘老买臣乡。","方干 越中言事二首之二"]]},{"n":"买臣之年","d":"","s":"《汉书》卷六十四上《朱买臣传》","q":[["四十九仍入，年非朱买臣。","骆宾王 咏怀古意上裴侍郎"]]},{"n":"随计吏","d":"","s":"《汉书》卷六十四上《朱买臣传》","q":[["又须随计吏，鸡鹤迥然分。","李咸用 宿隐者居"]]},{"n":"愚妇轻买臣","d":"","s":"《汉书》卷六十四上《朱买臣传》","q":[["郗氏诚难负，朱家自愧贫。","刘长卿 见秦系离婚后出山居作"],["会稽愚妇轻买臣，余亦辞家西入秦。","李白 南陵别儿童入京"]]},{"n":"朱氏衣","d":"","s":"《汉书》卷六十四《朱买臣传》","q":[["一轴郢人歌处雪，两重朱氏著来衣。","黄滔 翁文尧员外拥册礼之归一路有诗名昼锦集先将寄示因书五十六字"]]}],"136":[{"n":"知鱼乐","d":"观鱼：咏山水之乐。唐孟浩然《寻梅道士》：“重以观鱼乐，因之鼓枻歌。”","s":"《庄子集释》卷六下〈外篇·秋水〉","q":[["南华在濠上，谁辩魏王瓠。","储光羲 贻王侍御出台掾丹阳"],["但乐濠梁鱼，岂怨钟山鹄。","吴融 绵竹山西四十韵"]]},{"n":"郢匠","d":"郢匠：指技艺高超的人，或喻大毛笔。唐骆宾王《夏日游德州赠高四》：“成风郢匠斫，流水伯牙弦。”","s":"《庄子集释》卷八中〈杂篇·徐无鬼〉","q":[["郢人斤斫无痕迹，仙人衣裳弃刀尺。","刘禹锡 翰林白二十二学士见寄诗一百篇因以答贶"],["脱略磻溪钓，操持郢匠斤。","杜甫 奉赠鲜于京兆二十韵"]]},{"n":"散樗","d":"散樗：用以自谦、，或指不愿为世俗做事。唐杜甫《送郑十八虔贬台州司户》：“郑公樗散鬓成丝，酒后常称老画师。”","s":"《庄子集释》卷一上〈内篇·逍遥游〉","q":[["安知幽涧侧，独与散樗丛。","周存 禁中春松"],["散材无所用，老向琐闱眠。","姚合 送狄尚书镇太原"]]},{"n":"五车书","d":"五车书：喻指读书多，学问深。唐王维《戏赠张五弟湮三首》之二：“张弟五车书，读书仍隐居。”","s":"《庄子集释》卷十下〈杂篇·天下〉","q":[["男儿一片气，何必五车书。","孟浩然 送告八从军"],["世人如要问生涯，满架堆床是五车。","方干 题悬溜岩隐者居"]]},{"n":"鼓庄盆","d":"","s":"《庄子》外篇·卷六下《至乐》","q":[["小于潘岳头先白，学取庄周泪莫多。","元稹 六年春遣怀八首"],["相逢且问昭州事，曾鼓庄盆对逝川。","薛逢 送韩绛归淮南寄韩绰先辈"]]},{"n":"惠施","d":"","s":"《庄子》杂篇·卷十下《天下》","q":[["惠施不肯干万乘，卜式未必穷一经。","李白 悲歌行"]]},{"n":"剑头微吷","d":"","s":"《庄子》杂篇·卷八下《则阳》","q":[["晋人目二子，其犹吹一吷。","韩愈 读皇甫湜公安园池诗书其后二首"]]},{"n":"蓬心","d":"","s":"《庄子》内篇·卷一上《逍遥游》","q":[["鴳翼尝披隼，蓬心类倚麻。","柳宗元 同刘二十八院长述旧言怀感时书事奉寄澧州张员外使君五十二韵之作因其韵增至八十通赠二君子"]]}],"137":[{"n":"沈碑","d":"碑沉汉水：咏世事变迁，或喻建立功业。唐温庭筠《中书令裴公挽歌词》：“铭勒燕山暮，碑沉汉水春。”","s":"《晋书》卷三十四《杜预传》","q":[["极浦沉碑会，秋花落帽筵。","杜牧 往年随故府吴兴公夜泊芜湖口今赴官西去再宿芜湖感旧伤怀因成十六韵"],["遥仰沉碑会，鸳鸯玉佩敲。","杜牧 送牛相出镇襄州"]]},{"n":"传癖","d":"左传癖：喻指勤奋读书，钻研学问。宋陆游《夜坐》：“辛苦空成《左传》癖，逍遥常愧大慈仙。”","s":"《裴子语林》","q":[["杜预春秋癖，扬雄著述精。","元稹 哭吕衡州六首"],["晓达兵家流，饱闻春秋癖。","杜甫 八哀诗赠司空王公思礼"]]},{"n":"杜当阳","d":"","s":"《晋书》卷三十四《杜预传》","q":[["果持文武术，还继杜当阳。","孙逖 送赵大夫护边"],["朝瞻孔北海，时用杜荆州。","高适 奉酬睢阳李太守"]]},{"n":"杜将军","d":"","s":"《晋书》卷三十四《杜预传》","q":[["莫被此心生晚计，镇南人忆杜将军。","杨巨源 赠李傅"]]},{"n":"杜武库","d":"","s":"《晋书》卷三十四〈杜预列传〉","q":[["释子弥天秀，将军武库才。","孟浩然 与张折冲游耆阇寺"],["谁知杜武库，只见谢宣城。","李商隐 五言述德抒情诗一首四十韵献上杜七兄仆射相公"]]},{"n":"杜预建桥","d":"","s":"《晋书》卷三十四《杜预传》","q":[["杨仆移关，杜预建桥。","李瀚 蒙求"]]},{"n":"捷报孙歆头","d":"","s":"《晋书》卷三十四《杜预传》","q":[["军令未闻诛马谡，捷书惟是报孙歆。","李商隐 隋师东"]]},{"n":"元凯","d":"","s":"《晋书》卷三十四〈杜预列传〉","q":[["从夫元凯贵，训子孟轲贤。","岑参 西河郡太原守张夫人挽歌"],["子牟怀魏阙，元凯滞襄城。","崔湜 襄城即事"]]}],"138":[{"n":"青玉案","d":"四愁：咏愁思。唐孟郊《百忧》：“智士日千虑，愚夫唯四愁。”","s":"《昭明文选》卷二十九〈诗己·杂诗上·四愁诗四首〉","q":[["愧无青玉案，缄佩永不泯。","刘复 出三城留别幕中三判官"],["年方伯玉早，恨比四愁多。","刘禹锡 答柳子厚"]]},{"n":"词学张平子","d":"","s":"《后汉书》卷五十九《张衡传》","q":[["茂先惭博物，平子谢文章。","李隆基 送张说巡边"],["词学张平子，风仪褚彦回。","王湾 哭补阙亡友綦毋学士"]]},{"n":"翠帽","d":"","s":"《昭明文选》卷二东汉·张平子（衡）《西京赋》","q":[["已建玄戈收相土，应回翠帽过离宫。","杜牧 洛阳"]]},{"n":"金虎","d":"","s":"《昭明文选》卷三〈赋乙·京都中·东京赋〉","q":[["金虎知难动，毛厘亦耻言。","杜牧 昔事文皇帝三十二韵"],["金虎挻灾不复论，搆成狂猘犯车尘。","韩偓 八月六日作四首"]]},{"n":"平子定情","d":"","s":"《昭明文选》卷二十九东汉·张平子（衡）《四愁诗》","q":[["平子定情词丽绝，诗人匪石誓分明。","赵嘏 代人赠别"]]},{"n":"平子赋","d":"平子赋：喻精美文章，或咏归隐及哀愁。唐皇甫冉《馆陶李丞旧居》：“词藻世传平子赋，园林人比郑公乡。”","s":"《昭明文选》卷十五东汉·张平子（衡）《归田赋》","q":[["欲随平子去，犹未献甘泉。","孟浩然 题长安主人壁"],["贡禹怀书日，张衡作赋辰。","李峤 田"]]},{"n":"平子游都","d":"","s":"《后汉书》卷五十九《张衡传》","q":[["不游都邑称平子，只向江东作步兵。","李群玉 寄张祜（祜亦未面。频寄声相闻）"],["平子游都久，知君坐见嗤。","皇甫冉 寄刘八山中"]]},{"n":"双玉盘","d":"","s":"《昭明文选》卷二十九〈诗己·杂诗上·四愁诗四首〉","q":[["明日开铃阁，新诗双玉盘。","耿湋 和王怀州观西营秋射"],["闻有关河信，欲寄双玉盘。","贾至 寓言二首"]]}],"139":[{"n":"大王风","d":"","s":"《昭明文选》卷十三〈赋庚·物色·风赋〉","q":[["依依宜织江雨空，雨中六月兰台风。","李贺 罗浮山父（一作人）与葛篇"],["雄风卷昏雾，干戈满楼船。","于濆 南越谣"]]},{"n":"楚对凡亡","d":"","s":"《庄子集释》卷七下〈外篇·田子方〉","q":[]},{"n":"斩鲸","d":"","s":"《春秋左传·宣公十二年》","q":[["三千里外布干戈，果得鲸鲵入网罗。","朱冲和 遗临平监吏"],["一挥氛沴静，再举鲸鲵灭。","李世民 经跛薛举战地"]]},{"n":"七德","d":"","s":"《春秋左传·宣公十二年》","q":[["戢武耀七德，升文辉九功。","李世民 执契静三边"]]},{"n":"三休","d":"","s":"汉·贾谊《新书》卷七《退让》","q":[["危径几万转，数里将三休。","王维 自大散以往深林密竹磴道盘曲四五十里至黄牛岭见黄花川"],["龙骖驻六马，飞阁上三休。","虞世南 奉和至寿春应令"]]},{"n":"射兕云梦","d":"","s":"《战国策》卷十四〈楚策一·江乙说于安陵君〉","q":[["霓旌翠羽盖，射兕云梦林。","陈子昂 感遇诗三十八首之二十八"]]},{"n":"一舆一臣台","d":"","s":"《春秋左传正义》卷四十四〈昭公·传七年〉","q":[]},{"n":"夷陵火","d":"","s":"《史记》卷七十三《白起列传》","q":[["莫救夷陵火，无复秦庭哭。","李百药 郢城怀古"]]}],"140":[{"n":"吕虔刀","d":"","s":"《晋书》卷三十三〈王祥列传·（弟）王览〉","q":[["望有经纶钓，虔收宰相刀。","元稹 哭吕衡州六首"],["不愧宝刀赠，维怀琼树枝。","刘长卿 别陈留诸官"]]},{"n":"冰鲤","d":"","s":"《三国志》卷十八《魏书·吕虔传》","q":[["故友仍同里，常僚每合堂。渊龙过许劭，冰鲤吊王祥。","柳宗元 弘农公以硕德伟材屈于诬枉（弘农公杨凭也。为御史李夷简所弹）左官三岁复为大僚天监昭明人心感悦宗元窜伏湘浦拜贺末由谨献诗五十韵以毕微志"]]},{"n":"海沂咏","d":"","s":"《晋书》卷三十三《王祥传》","q":[["还将海沂咏，籍甚汉公卿。","皇甫冉 送荣别驾赴华州"],["衣催莲女织，颂听海人词。","钱起 送任先生任唐山丞"]]},{"n":"入幕雀","d":"","s":"《晋书》卷三十三《王祥传》","q":[["衔书表周瑞，入幕应王祥。","李峤 雀"]]},{"n":"王览友弟","d":"","s":"《晋书》卷三十三《王祥传》附《王览传》","q":[["江革忠孝，王览友弟。","李瀚 蒙求"]]},{"n":"王祥","d":"","s":"《晋书》卷三十三〈王祥列传〉","q":[["王祥因就宦，莱子不违亲。","司空曙 送鄂州张别驾襄阳觐省"],["谢朓中书直，王祥别乘归。","李端 送别驾赴晋陵即舍人叔之兄"]]},{"n":"王祥守奈","d":"","s":"《晋书》卷三十三〈王祥列传〉","q":[["王祥守奈，蔡顺分椹。","李瀚 蒙求"]]},{"n":"休徵选","d":"","s":"《晋书》卷三十三《王祥传》","q":[["国为休徵选，舆因仲举题。","卢藏用 饯许州宋司马赴任"]]}],"141":[{"n":"薄淮阳","d":"卧理：喻指官吏治理有方或声望高，能做到无为而治。唐张说《送崔二长史日知赴潞州》：“东山怀卧理，南省怅悲翁。”","s":"《史记》卷一百二十〈汲郑列传〉","q":[["淮阳多病偶求欢，客袖侵霜与烛盘。","杜牧 初冬夜饮"],["谁知病太守，犹得作茶仙。","杜牧 春日茶山病不饮酒因呈宾客"]]},{"n":"长孺","d":"","s":"《汉书》卷五十〈张冯汲郑列传·汲黯〉","q":[["梁公世不容，长孺心亦褊。","张九龄 临泛东湖"],["朝推长孺直，野慕隐之清。","张说 岳州赠广平公宋大夫"]]},{"n":"后来居上","d":"积薪：指官吏年高资深反位居人下。唐元稹《代曲江老人百韵》：“尚齿惇耆艾，搜材拔积薪。”","s":"《史记》卷一百二十〈汲郑列传〉","q":[["且嫌游昼短，莫问积薪长。","杜牧 春日言怀寄虢州李常侍十韵"],["左掖期连茹，南宫愧积薪。","权德舆 酬崔舍人阁老冬至日宿直省中奉简两掖阁老并见示"]]},{"n":"汲黯开仓","d":"","s":"《史记》卷一百二十〈汲郑列传〉","q":[["汲黯开仓，冯驩折券。","李瀚 蒙求"]]},{"n":"汲黯直","d":"","s":"《史记》卷一二○《汲黯列传》","q":[["只缘汲黯好直言，遂使安仁却为掾。","任华 寄杜拾遗"],["汲黯言当直，陈平智本奇。","崔融 哭蒋詹事俨"]]},{"n":"汲黯寝谋","d":"","s":"《史记》卷一二○《汲黯列传》","q":[["寝谋惭汲黯，秉羽贵孙敖。","李德裕 寒食日三殿侍宴奉进诗一首"]]},{"n":"匡汲俄宠辱","d":"","s":"《汉书》卷八十一《匡衡传》","q":[["匡汲俄宠辱，卫霍竟哀荣。","杜甫 八哀诗（并序）赠左仆射郑国公严公武"]]},{"n":"益戆","d":"","s":"《汉书》卷五十《汲黯传》","q":[["益戆由来未觉贤，终须南去吊湘川。","杜牧 商山富水驿"]]}],"142":[{"n":"伴张翰泛洛阳船","d":"","s":"《世说新语笺疏》下卷上〈任诞〉","q":[]},{"n":"人生适意","d":"忆鲈鱼：咏思乡之情、归隐之志。唐杜甫《洗兵马》：“东走无复忆鲈鱼，南飞觉有安巢鸟。”","s":"《世说新语笺疏》中卷上〈识鉴〉","q":[["扁舟恋南越，岂独为鲈鱼。","储嗣宗 得越中书"],["木叶萧萧动归思，西风画角汉东城。","刘沧 雨后游南门寺"]]},{"n":"身后名","d":"季鹰杯：喻为人旷达。唐高适《酬裴员外以诗代书》：“辛酸陈候诔，叹息季鹰杯’”","s":"《世说新语笺疏》下卷上〈任诞〉","q":[["八月枚乘笔，三吴张翰杯。","李白 送友人寻越中山水"],["莫思身外无穷事，且尽生前有限杯。","杜甫 绝句漫兴九首之四（冷斋诗话。漫兴当作漫与。言即景率意之作也。苏轼、黄庭坚、杨廷秀袭用之。俱押入语韵。姜尧章蟋蟀词与段复之词亦然。元以前未有读作兴字者。迨杨廉夫始作漫兴七首。妄"]]},{"n":"抚琴","d":"","s":"《世说新语》下卷上《伤逝》","q":[["抚琴犹可绝，况此故无弦。","李益 闻亡友王七嘉禾寺得素琴"],["援琴一流涕，旧馆几沾巾。","陈子昂 同旻上人伤寿安傅少府"]]},{"n":"江东步兵","d":"","s":"《世说新语》下卷上《任诞》","q":[["不游都邑称平子，只向江东作步兵。","李群玉 寄张祜（祜亦未面。频寄声相闻）"]]},{"n":"张翰扁舟","d":"","s":"《世说新语》下卷上《任诞》","q":[["扁舟不独如张翰，白帽还应似管宁。","杜甫 严中丞枉驾见过"]]},{"n":"张翰黄花句","d":"","s":"《昭明文选》卷二十九晋·张季鹰（翰）《杂诗》","q":[["张翰黄花句，风流五百年。","李白 金陵送张十一再游东吴"]]},{"n":"舟中琴","d":"","s":"《世说新语》下卷上《任诞》","q":[["为乐凡几许，听取舟中琴。","骆宾王 称心寺"]]}],"143":[{"n":"安陵谁辨削砺功","d":"","s":"《史记》卷一○一《袁盎列传》","q":[["袁丝徒伏剑，长孺欲成灰。","李德裕 清冷池怀古"],["安陵谁辨削砺功，韩国讵明深井里。","柳宗元 古东门行"]]},{"n":"梁园赋","d":"延枚：指延集宾客。唐李商隐《忆雪》：“预约延枚酒，虚乘访戴船。”；授简：指奉命吟诗作赋。唐杜甫《又作此奉卫王》：“白头授简焉能赋，愧似相如为大夫。”","s":"《西京杂记》卷二","q":[["孙室临书幌，梁园泛酒杯。","令狐楚 省中直夜对雪寄李师素侍郎"],["有客怀兔园，吟诗绕城内。","曹邺 贺雪寄本府尚书"]]},{"n":"梁王","d":"","s":"《史记》卷五十八《梁孝王世家》","q":[["梁国深文雅，淮王爱道仙。","张说 惠文太子挽歌二首之二"],["君不见梁王池上月，昔照梁王樽酒中。梁王已去明月在，黄鹂愁醉啼春风。","李白 携妓登梁不栖霞山孟氏桃园中"]]},{"n":"梁王驷马","d":"","s":"《艺文类聚》卷五十六","q":[["都尉仙凫远，梁王驷马来。","李峤 诗"],["叶令双凫至，梁王驷马来。","李元操 和从叔禄愔元日早朝"]]},{"n":"梁王苑","d":"","s":"《史记》卷五十八〈梁孝王世家〉","q":[["知君梁苑去，日见白华新。","储光羲 秦中送人觐省"],["梁园多绿柳，楚岸尽枫林。","储光羲 临江亭五咏"]]},{"n":"牛祸","d":"","s":"《汉书》卷四十七《文三王传·梁孝王传》","q":[["牛祸衅将发，羊孙谋始回。","李德裕 清冷池怀古"],["赵伦鹠怪，梁孝牛祸。","李瀚 蒙求"]]},{"n":"雁池","d":"","s":"《西京杂记》卷二","q":[["终思一酩酊，净扫雁池头。","杜甫 送题寄上汉中王三首之二"]]},{"n":"羊孙谋","d":"","s":"《史记》卷五十八《梁孝王世家》","q":[["牛祸衅将发，羊孙谋始回。","李德裕 清冷池怀古"]]}],"144":[{"n":"舌存","d":"仪舌：喻指安身进取之本，或指能言善辩。唐元稹《献荣阳公诗五十韵》：“仪舌忻犹在，舒帷誓不褰。”；疑璧：指不白之冤。唐骆宾王《幽絷书情简知己》：“绝缣非易辨，疑璧果难裁。”","s":"《史记》卷七十《张仪列传》","q":[["一行万里纤尘静，可要张仪更入秦。","司空图 寄王赞学"],["毛义持书去，张仪韫璧行。","李峤 檄"]]},{"n":"门阑苏生","d":"","s":"《史记》卷四十《楚世家》","q":[["门阑苏生在，勇锐白起强。","杜甫 入衡州"]]},{"n":"六里","d":"","s":"《史记》卷七十〈张仪列传〉","q":[["楚人曾此限封疆，不见清阴六里长。","罗隐 武牢关"],["割地张仪诈，谋身绮季长。","李商隐 商于"]]},{"n":"上党天下脊","d":"","s":"《史记》卷七十〈张仪列传〉","q":[]},{"n":"苏张","d":"","s":"《史记》卷六十九〈苏秦列传〉","q":[]},{"n":"苏张舌","d":"","s":"《史记》卷六十九《苏秦列传》","q":[["却假苏张舌，高誇周宋镡。","杜甫 风疾舟中伏枕书怀三十六韵奉呈湖南亲友"],["非故败他却成此，苏张终作多言鬼。","武元衡 行路难"]]},{"n":"万乘相","d":"","s":"《汉书》卷六十五〈东方朔列传〉","q":[["誓耕十亩田，不取万乘相。","韩愈 岳阳楼别窦司直"]]},{"n":"纵横","d":"","s":"汉·扬雄《法言》卷十一《渊骞》","q":[["二贤纵横器，久滞徒劳职。","刘长卿 对雨赠济阴马少府考城蒋少府兼献成武五兄南华二兄"],["纵横济时意，跌宕过人迹。","刘长卿 送元八游汝南"]]}],"145":[{"n":"悲丝","d":"","s":"《墨子》卷一〈所染〉","q":[["素丝易染髭难染，墨翟当年合泣髭。","刘驾 白髭"],["主人雕盘盘素丝，寒女眷眷墨子悲。","司空曙 长林令卫象饧丝结歌"]]},{"n":"避朝歌","d":"","s":"《汉书》卷五十一《邹阳传》","q":[["回车避朝歌，掩口去盗泉。","李白 赠宣城宇文太守兼呈崔侍"]]},{"n":"黔突","d":"","s":"《昭明文选》卷四十五〈对问设论辞序上·设论·答宾戏〉","q":[["早须归天阶，不得安孔席。","岑参 西蜀旅舍春叹寄朝中故人呈狄评事"],["贤有不黔突，圣有不暖席。","杜甫 发同谷县"]]},{"n":"带萦垒","d":"","s":"《后汉书》卷五十九《张衡传》","q":[["渐见长围云欲合，可怜穷垒带犹萦。","杜牧 东兵长句十韵"]]},{"n":"孔墨","d":"","s":"《韩非子》卷十九〈显学〉","q":[["不能师孔墨，何事问长沮。","王维 赠东岳焦鍊师"]]},{"n":"墨翟耻论兵","d":"","s":"《墨子》卷五《非攻上》","q":[["庄周空说剑，墨翟耻论兵。","李白 秋夜独坐怀故山"]]},{"n":"墨翟问","d":"","s":"《墨子》卷十二《贵义》","q":[["非同墨翟问，空滞杀龙川。","陈子昂 赠严仓曹乞推命录"]]},{"n":"墨子回车","d":"","s":"《新序·节士第七》","q":[]}],"146":[{"n":"卜商","d":"子夏索居：指寂寥独居。唐杜甫《上韦左相二十韵》：“长卿多病久，子夏索居频。”","s":"《礼记·檀弓上》","q":[["清秋将落帽，子夏正离群。","张贲 贲中间有吴门旅泊之什蒙鲁望垂和更作一章以伸酬谢"],["人间搦管穷苍颉，地上修文待卜商。","徐夤 伤前翰林杨左丞"]]},{"n":"富贵未知天","d":"","s":"《论语·颜渊》","q":[["栖遑长委命，富贵未知天。","陈子昂 赠严仓曹乞推命录"],["死生元有命，富贵本由天。此是古人语，吾今非谬传。","寒山 诗三百三首两百二十三"]]},{"n":"起予","d":"","s":"《史记》卷六十七〈仲尼弟子列传〉","q":[["努力输肝胆，休烦独起予。","杜甫 秋日荆南送石首薛明府辞满告别奉寄薛尚书颂德叙怀斐然之作三十韵"],["起予幸斑白，因是托子孙。","杜甫 贻华阳柳少府"]]},{"n":"吾过矣","d":"","s":"《礼记注疏》卷七〈檀弓〉","q":[]},{"n":"西河风味","d":"","s":"《史记》卷六十七《仲尼弟子列传》","q":[["南纪改波澜，西河共风味。","杜甫 题衡山县文宣王庙新学堂呈陆宰"]]},{"n":"西河遇","d":"","s":"《史记》卷六十七《仲尼弟子列传》","q":[["东门忧不入，西河遇亦深。","顾况 大茅岭东新居忆亡子从真"]]},{"n":"小人儒","d":"","s":"《论语·雍也》","q":[["名参君子场，行为小人儒。","孟郊 旅次湘沅有怀灵均"]]},{"n":"游夏","d":"","s":"《后汉书》卷三十下《郎顗传》","q":[["侧听弦歌宰，文书游夏徒。","孟浩然 同卢明府早秋宴张郎中海亭"],["天然生知姿，学立游夏上。","杜甫 八哀诗故著作郎贬台州司户荥阳郑公虔"]]}],"147":[{"n":"长倩赠","d":"","s":"《西京杂记》卷五","q":[["孙弘期射策，长倩赠生刍。","郑孺华 赋得生刍一束"]]},{"n":"开东阁","d":"","s":"《汉书》卷五十八〈公孙弘卜式儿宽列传·公孙弘〉","q":[["大君锡车马，时复过平津。","储光羲 敬酬陈掾亲家翁秋夜有赠"],["出入平津邸，自言娇且艳。","储光羲 洛阳道五首献吕四郎中"]]},{"n":"公孙策","d":"","s":"《汉书》卷五十八〈公孙弘卜式儿宽列传·公孙弘〉","q":[["孺子才虽远，公孙策未行。","于结 赋得生当一束"]]},{"n":"公孙弘牧猪","d":"","s":"《史记》卷一百一十二〈平津侯主父列传〉","q":[["尝学公孙弘，策杖牧群猪。","王绩 薛记室收过庄见寻率题古意以赠"]]},{"n":"后来居上","d":"积薪：指官吏年高资深反位居人下。唐元稹《代曲江老人百韵》：“尚齿惇耆艾，搜材拔积薪。”","s":"《史记》卷一百二十〈汲郑列传〉","q":[["且嫌游昼短，莫问积薪长。","杜牧 春日言怀寄虢州李常侍十韵"],["左掖期连茹，南宫愧积薪。","权德舆 酬崔舍人阁老冬至日宿直省中奉简两掖阁老并见示"]]},{"n":"三儒","d":"","s":"《汉书》卷八十九〈循吏列传〉","q":[]},{"n":"三陟平津","d":"","s":"《史记》卷一百一十二〈平津侯主父列传〉","q":[["再取连城璧，三陟平津侯。","陈子昂 答洛阳主人"]]},{"n":"孙被","d":"孙被：指官员生活俭朴。唐李峤《布》：“孙被登三相，刘衣阐四方。”","s":"《汉书》卷五十八《公孙弘传》","q":[["孙被登三相，刘衣阐四方。","李峤 布"]]}],"148":[{"n":"连城璧","d":"","s":"《史记》卷八十一〈廉颇蔺相如列传〉","q":[["连城犹隐石，唯有卞和知。","刘商 殷秀才求诗"],["璧从全赵去，鹏自北溟抟。","刘长卿 瓜洲驿奉钱张侍御公拜膳部郎中却复宪台充贺兰大夫留后使之岭南时侍御先在淮南幕府"]]},{"n":"负荆","d":"负荆：指向朋友请罪、道歉。唐李白《自广平乘醉走马六十里至邯郸登城楼览古书怀》：“两虎不可斗，廉公终负荆。”指认错赔礼。晋卢湛《览古》：“屈节邯郸中，俯首忍回轩、廉公何为者，负荆谢厥愆。”","s":"《史记》卷八十一《廉颇蔺相如列传》","q":[["凶丑将除蔓，奸豪已负荆。","刘长卿 至德三年春正月时谬蒙差摄海盐令闻王师收二京因书事寄上浙西节度李侍郎中丞行营五十韵"],["两虎不可斗，廉公终负荆。","李白 自广平乘醉走马六十里至邯郸登城楼览古书怀"]]},{"n":"廉蔺","d":"廉蔺：喻指将相忠心为国而结下深厚友谊。唐李白《醉后赠从甥高镇》：“时清不及英豪人，三尺儿童重廉蔺。”","s":"《后汉书》卷七十《孔融传》","q":[["时清不及英豪人，三尺童儿重廉蔺。","李白 醉后赠从甥高镇"],["廉蔺若未死，孙吴知暗同。","高适 李云南征蛮诗"]]},{"n":"两虎斗","d":"","s":"《史记》卷八十一《廉颇蔺相如列传》","q":[["赵倚两虎斗，晋为六卿分。","李白 古风之五十三"]]},{"n":"慕蔺","d":"","s":"《史记》卷一一七《司马相如列传》","q":[["慕蔺岂曩古，攀嵇是当年。","李白 赠饶阳张司户燧"],["长卿慕蔺久，子猷意已深。","魏万 金陵酬李翰林谪仙子"]]},{"n":"相如缶","d":"","s":"《史记》卷八十一〈廉颇蔺相如列传〉","q":[["高唱荆卿歌，乱击相如缶。","元稹 说剑"]]},{"n":"相如怀抱","d":"","s":"《史记》卷八十一〈廉颇蔺相如列传〉","q":[]},{"n":"相如折秦","d":"","s":"《史记》卷八十一〈廉颇蔺相如列传〉","q":[["相如章华巅，猛气折秦嬴。","李白 自广平乘醉走马六十里至邯郸登城楼览古书怀"]]}],"149":[{"n":"辩折田巴","d":"","s":"《太平御览》卷四六四","q":[["辩折田巴生，心齐鲁连子。","李白 送王屋山人魏万还王屋"]]},{"n":"鲁连子","d":"蹈海：指不畏强敌，宁死不屈。唐李白《送岑徵君归鸣皋山》：“蹈海宁受赏，还山非问津。”","s":"《战国策》卷二十〈赵策·秦围赵之邯郸〉","q":[["莫学仲连逃海上，田单空愧取聊城。","刘长卿 送卢侍御赴河北"],["谁云秦军众，摧却鲁连舌。","李白 别鲁颂"]]},{"n":"鲁连书","d":"鲁连箭：喻指不战而屈人之兵。唐李白《江夏寄汉阳辅录事》：“‘君草陈琳檄，我书鲁连箭。”","s":"《史记》卷八十三〈鲁仲连邹阳列传·邹阳〉","q":[["秋深为尔持圆扇，莫忘鲁连飞一箭。","刘商 赋得赋雉歌送杨协律表弟赴婚期"],["莫学仲连逃海上，田单空愧取聊城。","刘长卿 送卢侍御赴河北"]]},{"n":"鲁仲连","d":"","s":"《史记》卷八十三《鲁仲连列传》","q":[["纵为鲁连子，山路有柴扉。","刘慎虚 越中问海客"],["鲁连功可让，千载一相挥。","刘长卿 同诸公袁郎中宴筵喜加章服"]]},{"n":"谈笑谢金","d":"","s":"《史记》卷八十三〈鲁仲连邹阳列传·鲁仲连〉","q":[["鲁连卖谈笑，岂是顾千金。","李白 留别王司马嵩"],["鲁连逃千金，圭组岂可酬。","李白 赠崔郎中宗之"]]},{"n":"千里驹","d":"","s":"《楚辞补注》卷六〈卜居〉","q":[]},{"n":"谈笑解围","d":"","s":"《战国策》卷二十〈赵策·秦围赵之邯郸〉","q":[["闻道王师犹转战，谁能谈笑解重围。","皇甫冉 同温丹徒登万岁楼"]]},{"n":"天下士","d":"","s":"《史记》卷八十三〈鲁仲连邹阳列传·鲁仲连〉","q":[]}],"150":[{"n":"馆娃宫","d":"","s":"《吴越春秋》卷九〈勾践阴谋外传·勾践十二年〉","q":[["分明石潭里，宜照浣纱人。","张子容 春江花月夜二首之一"],["别有浣纱吴女郎，行尽绿潭潭转幽。","李白 和卢侍御通塘曲"]]},{"n":"夫差","d":"","s":"《史记》卷三十一《吴太伯世家》","q":[["树隔夫差苑，溪连句践城。","张祜 题苏州楞伽寺"],["夫差旧国久破碎，红燕自归花自开。","殷尧藩 馆娃宫"]]},{"n":"姑苏台","d":"","s":"《史记》卷三十一〈吴太伯世家〉","q":[["城堪迷下蔡，台合上姑苏。","吴融 即席十韵"]]},{"n":"黄池会","d":"","s":"《春秋左传·哀公十三年》","q":[["黄池高会事未终，沧海横流人荡覆。","刘长卿 登吴古城歌"],["黄池通霸迹，赤壁畅戎威。","骆宾王 夕次旧吴"]]},{"n":"吴王醉处","d":"","s":"《全唐诗》卷一百六十二〈乌栖曲〉","q":[]},{"n":"十年生聚","d":"","s":"《春秋左传正义》卷五十七〈哀公·传元年〉","q":[]},{"n":"水犀军","d":"","s":"《国语·越语上》","q":[["谢朓诗中佳丽地，夫差传里水犀军。","杜牧 润州二首"]]},{"n":"伍员忠谏","d":"","s":"《史记》卷六十六《伍子胥列传》","q":[["伍员结舌长嘘嚱，忠谏无因到君耳。","刘商 姑苏怀古送秀才下第归江南"],["当年国门外，谁识伍员忠。","杜牧 吴宫词二首"]]}],"151":[{"n":"抱朴子","d":"","s":"《晋书》卷七十二〈葛洪列传〉","q":[]},{"n":"丹砂井","d":"丹砂井：喻水质醇美，或喻地灵人杰。唐王维《林园即事寄舍弟统》：“徒思赤笔书，讵有丹砂井？”","s":"《抱朴子》卷十一〈内篇·仙药〉","q":[["徒思赤笔书，讵有丹砂井。","王维 林园即事寄舍弟紞"]]},{"n":"反复字","d":"","s":"《抱朴子》卷五十〈外篇·自叙〉","q":[["莫惊反掌字，当取葛洪规。","李峤 纸"]]},{"n":"葛仙翁","d":"","s":"《晋书》卷七十二《葛洪传》","q":[["勿惮山深与地僻，罗浮尚有葛仙翁。","元结 说洄溪招退者"],["存亡去住一壶中，兄事安期弟葛洪。","崔郾 赠毛仙翁"]]},{"n":"葛洪丹井","d":"","s":"《晋书》卷七十二〈葛洪列传〉","q":[]},{"n":"勾漏令","d":"","s":"《晋书》卷七十二《葛洪传》","q":[["永嘉多北至，句漏且南征。","杜甫 奉送二十三舅录事之摄郴州"],["远惭句漏令，不得问丹砂。","杜甫 为农"]]},{"n":"愧葛洪","d":"","s":"《全唐诗》卷二百二十四〈赠李白〉","q":[]},{"n":"肘后方","d":"肘后方：喻指医方地喻指仙道。唐韦庄《王道者》：“五云遥指海中央，金鼎曾传肘后方。”","s":"《晋书》卷七十二《葛洪传》","q":[["壶中药物梯霞诀，肘后方书缩地功。","令狐楚 赠毛仙翁"],["枕中经妙谁传与，肘后方新自写将。","周渭 赠龙兴观主吴崇岳"]]}],"152":[{"n":"臂纱","d":"","s":"《晋书》卷三十一《后妃传上·胡贵嫔传》","q":[["十年一梦归人世，绛缕犹封系臂纱。","杜牧 出宫人二首"],["红儿若向当时见，系臂先封第一纱。","罗虬 比红儿诗"]]},{"n":"痴叔","d":"","s":"《世说新语笺疏》中卷下〈赏誉〉","q":[["王湛床头见周易，长康传里好丹青。","李颀 同张员外諲酬答之作"],["痴叔去时还读易，仲容多兴索衔杯。","杜牧 使回枉唐州崔司马书兼寄四韵因和"]]},{"n":"池上杯","d":"","s":"《续齐谐记》","q":[["未展山阳会，空留池上杯。","李峤 酬（一作和）杜五弟晴朝独坐见赠"],["流觞想兰亭，捧剑传金人。","李适 三日书怀因示百僚"]]},{"n":"揽须","d":"桓伊筝：咏抚筝，或指心情悲愤。宋陆游《夜闻湖中渔歌》：“悲伤似击渐离筑，忠愤如抚桓伊筝。”","s":"《晋书》卷八十一〈桓宣列传·（族子）桓伊〉","q":[["谢傅何由接，桓伊定不凡。","刘禹锡 和汴州令狐相公到镇改月偶书所怀"]]},{"n":"焚裘","d":"","s":"《初学记》卷九","q":[["汉文宜惜露台费，晋武须焚前殿裘。","沈佺期 七夕曝衣篇"],["河宗来献宝，天子命焚裘。","沈佺期 和崔正谏登秋日早朝"]]},{"n":"晋武轻后事","d":"","s":"《晋书》卷三《世祖武帝纪》","q":[["晋武轻后事，惠皇终已昏。","高适 登百丈峰二首"]]},{"n":"师昭","d":"","s":"《三国志》卷四《魏书·三少帝纪》","q":[["袁董非徒尔，师昭岂偶然！","韩偓 感事三十四韵（丁卯已后）"]]},{"n":"羊车过","d":"","s":"《晋书》卷三十一〈后妃上·胡贵嫔〉","q":[["春风鸾镜愁中影，明月羊车梦里声。","戴叔伦 宫词"],["羊车讵畏青门闭，兔月今宵照后庭。","杨师道 阙题"]]}],"153":[{"n":"失匕箸","d":"","s":"《三国志》卷三十二〈蜀书·先主备传〉","q":[["四夷闻风失匕箸，天子受贺登高楼。","刘禹锡 平蔡州三首"],["杯酒英雄君与操，文章微婉我知丘。","白居易 哭刘尚书梦得二首"]]},{"n":"本初朔饮","d":"","s":"《岁时习俗资料汇编·新增月日纪古》卷之六上〈六月卷上·伏日〉","q":[]},{"n":"孔璋客绍","d":"","s":"《三国志》卷二十一〈魏书·王粲传·徐干陈琳阮瑀应玚刘桢〉","q":[]},{"n":"轻董卓","d":"","s":"《后汉书》卷七十四上《袁绍传》","q":[["小儒轻董卓，有识笑苻坚。","杜甫 寄岳州贾司马六丈巴州严八使君两阁老五十韵"]]},{"n":"乌巢空幕","d":"","s":"《三国志》卷一〈魏书·武帝纪〉","q":[]},{"n":"袁董","d":"","s":"《后汉书》卷七十四上《袁绍传》","q":[["袁董非徒尔，师昭岂偶然。","韩偓 感事三十四韵"]]},{"n":"袁绍杯","d":"","s":"《后汉书》卷三十五《郑玄传》","q":[["篱边老却陶潜菊，江上徒逢袁绍杯。","杜甫 秋尽"]]},{"n":"袁校尉","d":"","s":"《后汉书》卷七十四上《袁绍传》","q":[["散卒半随袁校尉，寡妻休问辟司徒。","唐彦谦 奉使岐下闻唐弘夫行军为贼所擒伤而有作"]]}],"154":[{"n":"晁错","d":"","s":"《汉书》卷四十九〈爰盎晁错列传·晁错〉","q":[["不得同晁错，吁嗟后郤诜。","杜甫 奉赠鲜于京兆二十韵"]]},{"n":"晁董","d":"","s":"《旧唐书》卷一百九十下〈文苑列传下·刘蕡〉","q":[]},{"n":"晁氏忠作祸","d":"","s":"《汉书》卷四十九〈爰盎晁错列传·晁错〉","q":[["晁氏有恩忠作祸，贾生无罪直为灾。","杜牧 闻开江相国宋下世二首"]]},{"n":"七国三边","d":"","s":"《史记》卷十一〈孝景本纪〉","q":[["七国三边未到忧，十三身袭富平侯。","李商隐 富平少侯"]]},{"n":"清光","d":"","s":"《汉书》卷四十九〈爰盎晁错列传·晁错〉","q":[]},{"n":"衣冠就东市","d":"","s":"《汉书》卷四十九《晁错传》","q":[["旋见衣冠就东市，忽遗弓剑不西巡。","杜牧 河湟"]]},{"n":"诛错为名","d":"","s":"《汉书》卷四十九《晁错传》","q":[["食参将可待，诛错辄为名。","刘长卿 至德三年春正月时谬蒙差摄海盐令闻王师收二京因书寄上浙西节度李侍郎中丞行营五十韵"],["又从斩晁错，诸侯益强盛。","白居易 赠友五首"]]},{"n":"囊不智","d":"","s":"《史记》卷七十一《樗里子列传》","q":[["曷月还朝天，及时开智囊。","独孤及 送相里郎中赴江西"],["解空囊不智，灭景谷何愚。","羊士谔 郡斋读经"]]}],"155":[{"n":"白云巘","d":"","s":"《太平广记》卷二○二","q":[["犹及九峰春，归吟白云巘。","李骘 自惠山至吴下寄酬南徐从事"],["无何一名系，引出白云间。","杜荀鹤 怀庐岳书斋"]]},{"n":"挂冠神武","d":"","s":"《南史》卷七十六〈隐逸列传下·〉","q":[]},{"n":"陶隐居","d":"陶隐居：喻雅逸情趣。唐高适《送虞城刘明府谒魏郡苗太守》：“今日逢明圣，吾为陶隐居。”","s":"《梁书》卷五十一〈处士列传·陶弘景〉","q":[["陶仙谩学长生术，暑往寒来更寂寥。","张又新 青嶂山"],["可爱剡溪僧，独寻陶景舍。","戴叔伦 新年第二夜答处上人宿玉芝观见寄"]]},{"n":"山中宰相","d":"山中宰相：指处士议政。唐徐寅《岚似屏风》：“山中宰相陶弘景，谷口耕夫郑子真。”","s":"《南史》卷七十六〈隐逸列传下·陶弘景〉","q":[["山中宰相陶弘景，谷口耕夫郑子真。","徐夤 岚似屏风"],["旨趣陶山相，诗篇沈隐侯。","郑谷 蔡处士"]]},{"n":"华阳真逸铭","d":"","s":"《欧阳修全集·集古录跋尾》卷十〈瘗鹤铭〉","q":[]},{"n":"句曲仙诀","d":"","s":"《南史》卷七十六《隐逸传下·陶弘景传》","q":[["句曲闻仙诀，临川得佛经。","李商隐 酬令狐郎中见寄"]]},{"n":"陶景恋松","d":"","s":"《梁书》卷五十一〈处士列传·陶弘景〉","q":[["陶景恋深松桧影，留侯抛却帝王师。","徐夤 忆旧山"]]},{"n":"陶贞白","d":"","s":"《南史》卷七十六《隐逸传下·陶弘景传》","q":[["若逢茅氏传消息，贞白先生不久归。","储嗣宗 和茅山高拾遗忆山中杂题五首之巢鹤"],["采药陶贞白，寻山许远游。","李群玉 送房处士閒游"]]}],"156":[{"n":"传都赋","d":"","s":"《世说新语》下卷下《文学》","q":[["满地传都赋，倾朝看药船。","王维 哭祖六自虚（时年十八）"]]},{"n":"纸价高","d":"洛阳纸贵：喻作品风行一时。唐宋之问《范阳王挽词二首》之一：“洛阳今纸贵，犹写太冲词。”","s":"《晋书》卷九十二〈文苑列传·左思〉","q":[["洛阳纸价因兄贵，蜀地红笺为弟贫。","何兆 赠兄"],["四方虽纸贵，谁怕费钱刀。","姚合 和郑相演杨尚书蜀中唱和诗"]]},{"n":"涧底松","d":"","s":"《昭明文选》卷二十一〈诗乙·咏史·咏史八首〉","q":[["风霜落满千林木，不近青青涧底松。","徐夤 寄华山司空侍郎二首之一"],["自得天然状，非同涧底生。","许棠 和薛侍御题兴善寺松"]]},{"n":"镊白","d":"","s":"《南史》卷五〈齐本纪下·废帝郁林王〉","q":[["谁道从军乐，年来镊白须。","姚合 从军乐二首之二"],["镜弄白髭须，如何作老夫。","杜牧 遣兴"]]},{"n":"掞天才","d":"","s":"《昭明文选》卷四晋·左太冲（思）《蜀都赋》","q":[["凌云羽翮掞天才，扬历中枢与外台。","刘禹锡 和令狐相公初归京国赋诗言怀"],["不是郢中清唱发，谁当丞相掞天才。","刘禹锡 江陵严司空见示与成都武相公唱和因命同作"]]},{"n":"左记室","d":"","s":"《晋书》卷九十二《左思传》","q":[["中有左记室，逢人眼光明。","曹邺 送进士李殷下第游汾河"]]},{"n":"左家娇女","d":"","s":"《玉台新咏》卷二晋·左思《娇女诗》","q":[["嵇氏幼男犹可悯，左家娇女岂能忘。","李商隐 王十二兄与畏之员外相访见招小饮时予以悼亡日近不去因寄"]]},{"n":"左太冲","d":"","s":"《晋书》卷九十二《文苑传·左思传》","q":[["左思裁赋日，王充作论年。","李峤 砚"],["妙迹蔡侯施，芳名左伯驰。","李峤 纸"]]}],"157":[{"n":"华阴葬","d":"","s":"《后汉书》卷五十四〈杨震列传·杨震〉","q":[]},{"n":"关西夫子","d":"","s":"《后汉书》卷五十四《杨震传》","q":[["赠言杨伯起，非复是关西。","李行言 秋晚度废关"]]},{"n":"鸟哭杨震","d":"","s":"《后汉书》卷五十四《杨震传》","q":[["有鸟哭杨震，无儿悲邓攸。","元稹 阳城驿"]]},{"n":"四世三公","d":"","s":"《后汉书》卷五十四《杨震传》附《杨彪传》","q":[["四代三公族，清风播人天。","李白 送杨燕之东鲁"],["汉家名臣杨德祖，四代五公享茅土。","李颀 行路难"]]},{"n":"四知金","d":"","s":"《后汉书》卷五十四《杨震传》","q":[["杨震东来是宦游，政成登此自消忧。","方干 登新城县楼赠蔡明府"],["方同杨伯起，独有四知名。","李峤 金"]]},{"n":"杨伯起哀荣","d":"","s":"《后汉书》卷五十四《杨震传》","q":[["谁知杨伯起，今日重哀荣。","宋之问 范阳王挽词二首之二"]]},{"n":"杨氏子孙","d":"","s":"《后汉书》卷五十四《杨震传》","q":[["每叹陆家兄弟少，更怜杨氏子孙贫。","鲍防 送薛补阙入朝"]]},{"n":"鳣庭","d":"","s":"《后汉书》卷五十四《杨震传》","q":[["共悬龟印衔新绶，同忆鳣庭访旧居。","李德裕 奉送相公十八丈镇扬州"]]}],"158":[{"n":"北山文","d":"","s":"《昭明文选》卷四十三南朝齐·孔德璋（稚圭）《北山移文》","q":[["会有圭组恋，遂贻山林嘲。","柳宗元 游朝阳岩遂登西亭二十韵"],["今日病身惭小隐，欲将泉石勒移文。","曹唐 三年冬大礼五首之五"]]},{"n":"赤米白盐","d":"","s":"《南齐书》卷四十一〈周颙列传〉","q":[]},{"n":"周妻何肉","d":"何肉周妻：指修行中有所难舍。明袁宏道《赠虞德园兄弟》：“台宗贤教谁能识，何肉周妻到底疑。”","s":"《南齐书》卷四十一〈周颙列传〉","q":[]},{"n":"书从外氏学","d":"","s":"《南史》卷三十四〈周朗列传·（族孙）周颙〉","q":[["书从外氏学，竹自晋时栽。","卢纶 送从侄滁州觐省"]]},{"n":"鹤怨周颙","d":"","s":"《昭明文选》卷四十三〈书下·北山移文〉","q":[["稚圭蛙鸣，彦伦鹤怨。","李瀚 蒙求"],["鱼惭张翰辞东府，鹤怨周颙负北山。","罗隐 寄右省王谏议"]]},{"n":"张南周北","d":"","s":"《南史》卷三十九〈刘勉列传·（刘悛弟）刘绘〉","q":[]},{"n":"周颙","d":"","s":"《南史》卷三十四〈周朗列传·（族孙）周颙〉","q":[["庾信哀虽久，何颙好不忘。","杜甫 上兜率寺"],["久为野客寻幽惯，细学何颙免兴孤。","杜甫 岳麓山道林二寺行"]]}],"159":[{"n":"范叔寒","d":"范叔袍：指贫困时所受帮助。清赵翼《前守韦缘事罢官诗以送别》之二：“民犹争诵廉公裤、我敢相矜范叔袍。”","s":"《史记》卷七十九〈范雎蔡泽列传·范雎〉","q":[["夜寒销腊酒，霜冷重绨袍。","戎昱 冬夜宴梁十三厅"],["他日见张禄，绨袍怀旧恩。","李白 送鲁郡刘长史迁弘农长史"]]},{"n":"范雎","d":"","s":"《史记》卷七十九〈范雎蔡泽列传·范雎〉","q":[["望宋怜思女，游梁念客卿。","李绅 到宣武三十韵"],["韦贤初相汉，范叔已归秦。","杜甫 上韦左相二十韵"]]},{"n":"邯郸虱","d":"","s":"《韩非子》卷九《内储说上》","q":[["不料邯郸虱，俄成即墨牛。","温庭筠 过华清宫二十二韵"]]},{"n":"魏齐首","d":"","s":"《史记》卷七十九《范雎列传》","q":[["安知魏齐首，见断箦中尸。","杜牧 杜秋娘诗"]]},{"n":"须贾擢发","d":"","s":"《史记》卷七十九〈范雎蔡泽列传·范雎〉","q":[["廉颇负荆，须贾擢发。","李瀚 蒙求"]]},{"n":"箦中尸","d":"","s":"《史记》卷七十九《范雎列传》","q":[["安知魏齐首，见断箦中尸。","杜牧 杜秋娘诗"]]},{"n":"张禄相秦","d":"","s":"《史记》卷七十九《范雎列传》","q":[["穰侯休忌关东客，张禄先生竟相秦。","徐夤 龙蛰二首"]]}],"160":[{"n":"仁风动","d":"仁风动：喻地方官有善政。唐独孤及《送马郑州》：“当使仁风动，遥听舆颂喧。”","s":"《世说新语笺疏》上卷上〈言语〉","q":[["江湖经战阵，草木待仁风。","畅当 奉送杜中丞赴洪州"],["扬风非赠扇，易俗是张琴。","李隆基 赐崔日知往潞州"]]},{"n":"谢将军","d":"","s":"《世说新语笺疏》上卷下〈文学〉","q":[["吟尽长江一江月，更无人似谢将军。","吴融 松江晚泊"],["早闻牛渚咏，今见鹡鸰心。","孟浩然 送袁十岭南寻弟"]]},{"n":"倚马雄才","d":"","s":"《世说新语笺疏》上卷下〈文学〉","q":[]},{"n":"临汝袁郎","d":"","s":"《晋书·袁宏传》","q":[["临汝袁郎得相见，闲云引到东阳县。","刘言史 葛巾歌"]]},{"n":"袁舫","d":"","s":"《世说新语笺疏》上卷下〈文学〉","q":[]},{"n":"袁宏泛舟","d":"","s":"《晋书》卷九十二〈文苑列传·袁宏〉","q":[]},{"n":"袁宏憔悴","d":"","s":"《晋书》卷九十二《文苑传·袁宏传》","q":[["独有袁宏正憔悴，一樽惆怅落花时。","温庭筠 寄岳州李外郎远"]]}],"161":[{"n":"老尽力","d":"","s":"汉·韩婴《韩诗外传》","q":[["主人念老马，廨署容秋萤。","杜甫 桥陵诗三十韵因呈县内诸官"],["尘中老尽力，岁晚病伤心。","杜甫 病马"]]},{"n":"礼干木","d":"","s":"《吕氏春秋》卷二十一《开春论·期贤》","q":[["战国方须礼干木，康时何必重侯嬴。","费冠卿 酬范中丞见"]]},{"n":"田方简傲","d":"","s":"《史记》卷四十四《魏世家》","q":[["陆逵豪爽，田方简傲。","李瀚 蒙求"]]},{"n":"田子方","d":"","s":"汉·韩婴《韩诗外传》卷八第三十三章","q":[["愿逢田子方，恻然为我悲。","李白 天马歌"]]},{"n":"魏侯重","d":"","s":"《战国策》卷四《秦策二》","q":[["但蒙魏侯重，不受谤书诬。","陈子昂 答韩使同在边"]]},{"n":"洗箱箧","d":"","s":"《史记》卷七十一〈樗里子甘茂列传·甘茂〉","q":[["直笔在史臣，将来洗箱箧。","杜甫 八哀诗故司徒李公光弼"]]},{"n":"翟璜直言","d":"","s":"《新序·杂事一》","q":[["董宣强项，翟璜直言。","李瀚 蒙求"]]}],"162":[{"n":"泥中婢","d":"","s":"《世说新语笺疏》上卷下〈文学〉","q":[]},{"n":"郑公乡","d":"","s":"《后汉书》卷三十五〈张曹郑列传·曹褒〉","q":[["愧非郑公里，归扫蒙笼室。","丘丹 奉酬幸使君送归山之作"],["登科旧乡里，当为改嘉名。","姚合 送李秀才赴举"]]},{"n":"乞郑玄","d":"","s":"《世说新语笺疏》上卷下〈文学〉","q":[["未拟生裴秀，如何乞郑玄。","郑还古 赠柳氏妓"]]},{"n":"巳年得梦","d":"","s":"《后汉书》卷三十五《郑玄传》","q":[["巳年人得梦，庚日鸟为灾。","郑愔 哭郎著作"]]},{"n":"吾道东","d":"","s":"《后汉书》卷三十五《郑玄传》","q":[["斯人脱身来，岂非吾道东。","杜甫 赠苏四徯"],["吾道将东矣，秋风更飒然。","钱起 寇中送张司马归洛"]]},{"n":"袁绍杯","d":"","s":"《后汉书》卷三十五《郑玄传》","q":[["篱边老却陶潜菊，江上徒逢袁绍杯。","杜甫 秋尽"]]},{"n":"康成","d":"","s":"《后汉书》卷三十五〈张曹郑列传·郑玄〉～","q":[["诗礼康成学，文章贾谊才。","郑愔 哭郎著作"],["山简愧兼诸郡命，郑玄惭秉六经权。","黄滔 奉和翁文尧员外文秀光贤昼锦之什"]]}],"163":[{"n":"掇蜂","d":"伯奇掇蜂：指受人诬陷，父子反目。唐李端《杂歌》：“伯奇掇蜂贤父逐，曾参杀人慈母疑。”；掇蜂：喻离间父子。唐白居易《新乐府·天可度》“劝君掇蜂君莫掇，使君父子成豺狼。”","s":"《世说新语笺疏》上卷上〈言语〉","q":[["拾尘掇蜂，疑圣猜贤。","李白 雪谗诗赠友人"],["伯奇掇蜂贤父逐，曾参杀人慈母疑。","李端 杂歌"]]},{"n":"薄伐","d":"","s":"《诗经·小雅·六月》","q":[["还同周薄伐，不取汉和亲。","刘方平 郑陇右严判官"]]},{"n":"吉甫清风","d":"","s":"《毛诗正义》卷十八之三〈大雅·荡之什·烝民〉","q":[]},{"n":"吉甫颂","d":"","s":"《诗经·大雅·嵩高·序》","q":[["还闻吉甫颂，不共郢歌俦。","张九龄 和姚令公从幸温汤喜雪"],["山公启事罢，山公启事罢。","张九龄 奉和吏部崔尚书"]]},{"n":"江汉美宣王","d":"","s":"《诗经·大雅·江汉·序》","q":[["吉甫裁诗歌盛业，一篇江汉美宣王。","杜牧 奉和白相公圣德和平致兹休运岁终功就合咏盛明呈上三相公长句四韵"]]},{"n":"文武吉甫","d":"","s":"《诗经·小雅·六月》","q":[["东方连帅南阳公，文武吉甫如古风。","权德舆 送张仆射朝见毕归镇"]]},{"n":"岳降","d":"","s":"《毛诗正义》卷十八之三〈大雅·荡之什·崧高〉","q":[["虽遇河清圣，惭非岳降贤。","韩偓 感事三十四韵"]]}],"164":[{"n":"管乐","d":"","s":"《三国志》卷三十五《蜀书·诸葛亮传》","q":[["自顾躬耕者，才非管乐俦。","孟浩然 与黄侍御北津泛舟"],["夫子今管乐，英才冠三军。","李白 赠何七判官昌浩"]]},{"n":"剧辛乐毅","d":"","s":"《战国策》卷二十九《燕策一》","q":[["拥彗折节无嫌猜，剧章乐毅感恩分。","李白 行路难三首之二"]]},{"n":"乐毅不归","d":"","s":"《史记》卷八十《乐毅列传》","q":[["去年大将军，忽负乐生谤。","张谓 同孙构免官后登蓟楼"],["乐毅傥再生，于今亦奔亡。","李白 经乱离后天恩流夜郎忆旧游书怀赠江夏韦太守良宰"]]},{"n":"乐毅","d":"乐毅：喻良将，或喻良将遭谗。唐李白《经乱离后天恩流夜郎忆旧游书怀赠江夏韦太守良宰》：“乐毅怕再生，于今亦奔亡。”","s":"《史记》卷八十〈乐毅列传〉","q":[]},{"n":"乐毅书","d":"","s":"《史记》卷八十《乐毅列传》","q":[["载感贾生恸，复闻乐毅书。","杜甫 别张十三建封"]]},{"n":"乐毅贤","d":"","s":"《史记》卷八十《乐毅列传》","q":[["无人不重乐毅贤，何敌能当鲁连啸。","钱起 送傅管记赴蜀军"]]},{"n":"尊乐毅","d":"","s":"《战国策》卷二十九《燕策一》","q":[["燕王尊乐毅，分国愿同欢。","陈子昂 感遇诗三十八首之十六"]]}],"165":[{"n":"邓禹","d":"","s":"《后汉书》卷十六〈邓寇列传·邓禹〉","q":[]},{"n":"邓禹分麾","d":"","s":"《后汉书》卷十六《邓禹传》","q":[["赵尧宁易印，邓禹即分麾。","苏颋 践赵尚书摄御史大夫赴朔方军"]]},{"n":"邓禹笑人","d":"","s":"《南齐书》卷四十七〈王融列传〉","q":[]},{"n":"耿邓","d":"","s":"《后汉书》卷十六《邓禹传》","q":[["孰与关张并，功临耿邓亲。","杜甫 谒先主庙"]]},{"n":"寇邓勋","d":"","s":"《后汉书》卷二十二《中兴二十八将传论》","q":[["吾慕寇邓勋，济时信良哉。","杜甫 述古三首之三"]]},{"n":"禹弇宫武","d":"","s":"《后汉书》卷十六〈邓寇列传·邓禹〉","q":[]},{"n":"台图","d":"云台画象：指表彰功臣。唐杜甫《寄董卿嘉荣十韵》：“云台画形象，皆为扫氛妖。”","s":"《东观汉记》卷二《显宗孝明皇帝纪》","q":[["清溪一路照羸身，不似云台画像人。","司空图 商山二首"],["几人欲话云台峻，独我方探禹穴深。","吴融 秋日感事"]]}],"166":[{"n":"后庭花","d":"","s":"《陈书》卷七〈皇后列传〉","q":[["商女不知亡国恨，隔江犹唱后庭花。","杜牧 泊秦淮"],["万户千门成野草，只缘一曲后庭花。","刘禹锡 金陵五题并序台城"]]},{"n":"陈后主","d":"","s":"《南史》卷十《陈后主本纪》","q":[["雕戈动地来，误杀陈后主。","欧阳询 道失"]]},{"n":"荒宫馀辱井","d":"","s":"《南史》卷十〈陈本纪下·后主〉","q":[]},{"n":"结绮阁","d":"","s":"《南史》卷十二〈后妃列传下·后主沈皇后·后主张贵妃〉","q":[["不下结绮阁，空迷江令语。","欧阳询 道失"],["日晖青琐殿，霞生结绮楼。","虞世南 凌晨早朝"]]},{"n":"胭脂井","d":"","s":"《韵语阳秋》卷五","q":[]},{"n":"龙沉景阳井","d":"","s":"《陈书》卷六《后主本纪》","q":[["天子龙沉景阳井，谁歌玉树后庭花。","李白 金陵歌送别范宣"]]},{"n":"十客","d":"","s":"《南史》卷十〈陈本纪下·后主〉","q":[]}],"167":[{"n":"绕指柔","d":"","s":"《昭明文选》卷二十五〈诗丁·赠答三·重赠卢谌〉","q":[["谁念刘越石，化为绕指柔。","李白 留别贾舍人至二首"],["干有千寻竦，精闻百炼钢。","柳宗元 弘农公以硕德伟材屈于诬枉左官三岁复为大僚天监昭明人心感悦宗元窜伏湘浦拜贺末由谨献诗五十韵以毕微志"]]},{"n":"刘琨啸","d":"","s":"《晋书》卷六十二〈刘琨列传〉","q":[["月傍关山几处明，胡骑中宵堪北走。","杜甫 吹笛"],["刘琨坐啸风清塞，谢朓题诗月满楼。","武元衡 酬严司空荆南（一作州）见寄"]]},{"n":"二十四友","d":"","s":"《晋书》卷六十二〈刘琨列传〉","q":[["珍重昔年金谷友，共来泉际话幽魂。","李玖 四丈夫同赋"],["嗣世衰微谁肯忧，二十四友日日空追游。","韦应物 金谷园歌"]]},{"n":"闻鸡起舞","d":"闻鸡起舞：指少年立志。清蒲松龄《夜坐悲歌》：“半夜闻鸡欲起舞，把酒问天天不语。”","s":"《晋书》卷六十二〈祖逖列传〉","q":[["楚客早闻歌凤德，刘琨休更舞鸡声。","吴融 萧县道中"],["刘琨与祖逖，起舞鸡鸣晨。虽有匡济心，终为乐祸人。","李白 避地司空原言怀"]]},{"n":"刘越石","d":"","s":"《晋书》卷六十二《刘琨传》","q":[["新从刘太尉，结束向并州。","司空曙 送王使君赴太原拜节度副使"],["君即刘越石，雄豪冠当时。","李白 宣城送刘副使入秦"]]},{"n":"刘琨听鸡","d":"","s":"《晋书》卷六十二〈祖逖列传〉","q":[]},{"n":"卢谌幄内璆","d":"","s":"《昭明文选》卷二十五晋·刘越石（琨）《重赠卢谌一首》","q":[["王俭花为府，卢谌幄内璆。","张登 冬至夜郡斋宴别前华阴卢主簿并序"]]}],"168":[{"n":"茂陵女","d":"白头吟：喻心境哀伤幽怨。唐骆宾王《在狱咏蝉》；“那堪玄鬓影，来对白头吟。”","s":"旧题晋·葛洪《西京杂记》卷三","q":[["一朝将聘茂陵女，文君因赠白头吟。","李白 白头吟"],["分明似写文君恨，万怨千愁弦上声。","李益 奉和武相公春晓闻莺"]]},{"n":"玉芙蓉","d":"远山眉：喻女子貌美。唐杜牧《少年行》：“豪持出塞节，笑别远山眉。”","s":"《西京杂记》卷二","q":[["豪持出塞节，笑别远山眉。","杜牧 少年行"],["江畔秋光蟾阁镜，槛前山翠茂陵眉。","杜牧 题桐叶"]]},{"n":"风流地","d":"","s":"《史记》卷一百一十七〈司马相如列传〉","q":[["临江起珠楼，不卖文君酒。","于濆 宫怨"],["不恨归日迟，莫向临邛去。","孟郊 古别离"]]},{"n":"卓女","d":"文君酒：咏酒或情爱。唐李百药《少年行》：“始酌文君酒，新吹弄玉萧。”；贳酒成都：咏人性情豪放，不惜以珍宝换取豪饮。唐骆宾王《艳情代郭氏赠卢照邻》：“掷果河阳君有分，贳酒成都妾亦然。”","s":"《汉书》卷五十七上〈司马相如列传〉","q":[["楼下当垆称卓女，楼头伴客名莫愁。","元稹 西凉伎"],["莱子真为少，相如未免穷。","孟郊 赠转运陆中丞"]]},{"n":"求凰曲","d":"凤客：指风流才子。唐卢全《卓女怨》：“迷魂随凤客，娇思人琴心。”；求凰：喻男子求佳侣。金元好问《王子文琴斋》：“天上秋风月底霜，求凰一曲鬓丝长。”咏男女之情。唐岑参《糙陕县王主簿赴襄阳成亲》：“求凰应不远，去马剩须鞭。”","s":"《史记》卷一一七《司马相如列传》","q":[["求凤应不远，去马剩须鞭。","岑参 送陕县王主簿赴襄阳成亲"],["君不见相如绿绮琴，一抚一拍凤凰音。","张纮 行路难"]]},{"n":"鹔鹴换酒","d":"","s":"《西京杂记》卷二","q":[["谢尚自能鸲鹆舞，相如免脱鹔鹴裘。","李白 对雪醉后赠王历阳"],["鹔鹴换美酒，舞衣罢雕龙。","李白 怨歌行"]]},{"n":"夜失身","d":"","s":"《史记》卷一百一十七〈司马相如列传〉","q":[["一颦一笑千金重，肯似成都夜失身。","权德舆 杂兴五首"]]}],"169":[{"n":"成康","d":"成康：周成王 与 周康王 的并称。史称其时天下安宁，刑措不用，故用以称至治之世。","s":"《诗·周颂·执竞》","q":[]},{"n":"定鼎","d":"","s":"《春秋左传·宣公三年》","q":[["州当定鼎处，人去偃戈年。","李频 送姚郜先辈赴汝州辟"],["秦后徒闻乐，周王耻卜年。","王维 奉和圣制庆玄元皇帝玉像之作应制"]]},{"n":"问周鼎","d":"","s":"《春秋左传正义》卷二十一〈宣公·传三年〉","q":[["沈吟问鼎语，但见东波流。","李群玉 登章华楼"],["长怀问鼎气，夙负拔山雄。","李隆基 巡省途次上党旧宫赋（并序）"]]},{"n":"桐圭","d":"","s":"《吕氏春秋·览部》卷十八〈审应览·重言〉","q":[["纫佩兰凋径，舒圭叶剪桐。","李世民 过旧宅二首之二"],["盘石圭多剪，凶门毂少推。","杜甫 秋日荆南述怀三十韵"]]},{"n":"分陜","d":"","s":"《春秋公羊传注疏》卷三〈隐公·隐公五年〉","q":[]},{"n":"君陈","d":"","s":"《尚书·周书·君陈》","q":[["天眷君陈旧在东，归朝人看大司空。","杨巨源 薛司空自青州归朝"]]},{"n":"康侯马","d":"","s":"《周易》卷四《晋卦》","q":[["青丝玉勒康侯马，孟水金堤滑伯城。","韩翃 送康洗马归滑州"]]}],"170":[{"n":"燕颔","d":"投笔：指弃文就武。唐魏征《述怀》：“中原初逐鹿，投笔事戎轩。”","s":"《后汉书》卷四十七〈班梁列传·班超〉","q":[["班笔行看掷，黄陂莫漫澄。","元稹 纪怀赠李六户曹崔二十功曹五十韵"],["赴敌甘负戈，论兵勇投笔。","刘长卿 吴中闻潼关失守因奉寄淮南萧判官"]]},{"n":"班定远","d":"封侯万里：指因有边功而封侯。宋陆游《累日文符沓至怅然有感》：“封侯万里独心在，糊口四方何事无。”","s":"《后汉书》卷四十七〈班梁列传·班超〉","q":[["自逐定远侯，亦著短后衣。","岑参 北庭西郊候封大夫受降回军献上"],["和戎因赏魏，定远莫辞班。","张说 送郑大夫唯忠从公主入蕃"]]},{"n":"笔耕","d":"","s":"《艺文类聚》卷五十八","q":[["男儿须聘用，莫信笔堪耕。","卢纶 送李校书赴东川幕"]]},{"n":"甘英穷西海","d":"","s":"《后汉书》卷八十八《西域传》","q":[["甘英穷西海，四万到洛阳。","杜牧 郡斋独酌（黄州作）"]]},{"n":"生入关","d":"","s":"《后汉书》卷四十七《班超传》","q":[["可怜班定远，生入玉门关。","令狐楚 从军词五首"],["愿得此身长报国，何须生入玉门关。","戴叔伦 塞上曲二首"]]},{"n":"虎穴得子","d":"","s":"《后汉书》卷四十七《班超传》","q":[["虎穴得子人皆惊，行尽三湘不逢敌。","刘禹锡 观棋歌送儇师西游"]]},{"n":"佣书","d":"","s":"《后汉书》卷四十七《班超传》","q":[["庸书酬万债，竹坞问樊村。","杜牧 奉送中丞姊夫俦自大理卿出镇江西叙书怀因成十二韵"],["赊酒不辞病，佣书非为贫。","杜牧 宣城赠肖兵曹"]]}],"171":[{"n":"百口累","d":"","s":"《晋书》卷六十九《周顗传》","q":[["知同百口累，曷日办抽簪。","独孤及 得李滁州书以玉潭庄见托因书春思以诗代答"]]},{"n":"伯仁觞","d":"","s":"《世说新语笺疏》下卷上〈任诞〉","q":[]},{"n":"印如斗","d":"","s":"《世说新语笺疏》下卷下〈尤悔〉","q":[["色阻金印大，兴含沧浪清。","杜甫 同元使君舂陵行"],["匈奴破尽人看归，金印酬功如斗大。","韩翃 送孙泼赴云中"]]},{"n":"腹中空洞","d":"","s":"《世说新语笺疏》下卷下〈排调〉","q":[]},{"n":"择虱","d":"","s":"《晋书》卷八十三〈顾和列传〉","q":[["悔逐迁莺伴，谁观择虱时。","李商隐 咏怀寄秘阁旧僚二十六韵"]]},{"n":"周侯山嶷","d":"","s":"《世说新语》中卷下《赏誉》","q":[["周侯山嶷，会稽霞举。","李瀚 蒙求"]]},{"n":"周顗才醒","d":"","s":"《世说新语笺疏》下卷上〈任诞〉","q":[["未曾周顗醉，转觉季之恭。","李商隐 今月二日不自量度辄以诗一首四十韵干渎尊严伏蒙仁恩俯赐披览奖逾其实"],["王戎似电休推病，周顗才醒众却惊。","羊昭业 皮袭美见留小宴次韵"]]}],"172":[{"n":"江令","d":"","s":"《陈书》卷二十七《江总传》","q":[["已随江令誇琼树，又入卢家妒玉堂。","李商隐 对雪二首"],["前身应是梁江总，名总还曾字总持。","李商隐 赠司勋杜十三员外"]]},{"n":"江令恨别","d":"","s":"《陈书》卷二十七〈江总列传〉","q":[]},{"n":"江令锦袍","d":"","s":"《艺文类聚》卷六十七","q":[["管宁纱帽净，江令锦袍鲜。","杜甫 秋日夔府咏怀奉寄郑监李宾客一百韵（郑审官秘书少监。时谪贬江陵。李之芳留吐蕃归。拜礼部尚书。改太子宾客。）"]]},{"n":"江总","d":"","s":"《陈书》卷二十七《江总传》","q":[["莫看江总老，犹被赏时鱼。","杜甫 复愁十二首"],["久钦江总文才妙，自叹虞翻骨相屯。","韩愈 韶州留别张端公使君（时宪宗元和十四年十月）"]]},{"n":"江总还家尚黑头","d":"","s":"《陈书》卷二十七《江总传》","q":[["远愧梁江总，还家尚黑头。","杜甫 晚行口号"]]},{"n":"江总外家养","d":"","s":"《陈书》卷二十七《江总传》","q":[["江总外家养，谢安乘兴长。","杜甫 入衡州"]]},{"n":"十客","d":"","s":"《南史》卷十〈陈本纪下·后主〉","q":[]}],"173":[{"n":"武安君","d":"","s":"《史记》卷七十三〈白起王剪列传·白起〉","q":[["卫青谩作大将军，白起真成一竖子。","李白 述德兼陈情上哥舒大夫"],["西羌延国讨，白起佐军威。","李白 送白利从金吾董将军西征"]]},{"n":"坑降","d":"长平苦：喻指战争惨败。唐李益《从军夜次六胡北饮马磨剑石为祝殇辞》：“毕昴不见胡天阴，东征曾吊长平苦、”","s":"《史记》卷四十三〈赵世家〉","q":[["岂令冤气积，千古在长平。","刘长卿 按覆后归睦州赠苗侍御"],["感念殽尸露，咨嗟赵卒坑。","李商隐 五言述德抒情诗一首四十韵献上杜七兄仆射相公"]]},{"n":"韩白","d":"","s":"《梁书》卷一《武帝纪上》","q":[["伊夔事业扶千载，韩白机谋冠九州。","罗隐 钱尚父生日"]]},{"n":"锐头儿","d":"","s":"晋·孔衍《春秋后语·赵语》","q":[["锐头将军来何迟，令我心中苦不足。","杜甫 久雨期王将军不至"],["长陵锐头儿，出猎待明发。","杜甫 遣兴五首之二"]]},{"n":"山西将","d":"","s":"《汉书》卷六十九〈赵充国辛庆忌列传〉","q":[]},{"n":"太白食昴","d":"","s":"《汉书》卷五十一《邹阳传》","q":[["太白夜食昴，长虹日中贯。","李白 南奔书怀"]]},{"n":"夷陵火","d":"","s":"《史记》卷七十三《白起列传》","q":[["莫救夷陵火，无复秦庭哭。","李百药 郢城怀古"]]}],"174":[{"n":"李将军","d":"","s":"《史记》卷一○九《李将军列传》","q":[["汉代李将军，微功合可咍。","岑参 使交河郡郡在火山脚其地苦热无雨雪献封大夫"],["夜宴李将军，欲望心相许。","曹邺 东武吟"]]},{"n":"六骡西走","d":"","s":"《史记》卷一百一十一〈卫将军骠骑列传〉","q":[]},{"n":"平阳骑","d":"","s":"《汉书》卷五十五《卫青霍去病传》","q":[["骑出平阳里，筵开卫尉家。","周思钧 晦日宴高氏林亭"],["结束平阳骑，明朝入建章。","王维 奉和杨驸马六郎秋夜即事"]]},{"n":"蒲泥","d":"","s":"《史记》卷一一一《卫将军骠骑列传》","q":[["行当收汉垒，直可取蒲泥。","李益 送常曾侍御使西蕃寄题西川"]]},{"n":"任安义","d":"","s":"《史记》卷一一一《卫将军骠骑列传》","q":[["终始任安义，荒芜孟母邻。","杜甫 奉赠萧二十使君"],["劝君今日后，结客结任安。主人宾客去，独住在门阑。","白居易 和答诗十首（并序）之和雉媒"]]},{"n":"卫霍","d":"","s":"《史记》卷一一一《卫将军骠骑列传》","q":[["卫霍待富贵，岂能无乾坤。","于濆 寒下曲"],["赤肉痛金疮，他人成卫霍。","于濆 边游录成卒言"]]},{"n":"卫幕","d":"","s":"《汉书》卷五十四〈李广苏建列传·李广〉","q":[["卫幕衔恩重，潘舆送喜频。","杜甫 奉贺阳城郡王太夫人恩命加邓国太夫人"],["卫青开幕府，杨仆将楼船。","杜甫 广州段功曹到得杨五长史谭书功曹却归聊寄此诗"]]}],"175":[{"n":"充国大田","d":"","s":"《汉书》卷六十九《赵充国传》","q":[["亚夫高垒静，充国大田秋。","羊士谔 送张郎中副使自南省赴凤翔府幕"]]},{"n":"充国画麟阁","d":"","s":"《汉书》卷六十九《赵充国传》","q":[["明年麟阁上，充国画于斯。","苏颋 饯赵尚书摄御史大夫赴朔方军"]]},{"n":"充国自赞","d":"","s":"《汉书》卷六十九《赵充国传》","q":[["枚皋诣阙，充国自赞。","李瀚 蒙求"]]},{"n":"麒麟阁","d":"","s":"《汉书》卷五十四〈李广苏建列传·苏武〉","q":[["若非载笔登麟阁，定是吹箫伴凤台。","于季子 早春洛阳答杜审言"],["新登麒麟阁，适脱獬豸冠。","岑参 送张秘书充刘相公通汴河判官便赴江外觐省"]]},{"n":"留屯奏","d":"","s":"《汉书》卷六十九〈赵充国辛庆忌列传·赵充国〉","q":[]},{"n":"如刻画","d":"","s":"《汉书》卷六十九《赵充国传》","q":[["唯有老身如刻画，犹期圣主解衣看。","李端 题故将军庄"]]},{"n":"山西将","d":"","s":"《汉书》卷六十九〈赵充国辛庆忌列传〉","q":[]}],"176":[{"n":"七宝鞭","d":"七宝鞭：喻以智谋脱身。唐温庭筠《奉天西佛寺》：“宗臣欲舞千钧剑，追骑犹观七宝鞭。”","s":"《晋书》卷六《明帝纪》","q":[["君王指点新丰树，几不亲留七宝鞭。","唐彦谦 骊山道中"],["宗臣欲舞千钧剑，追骑犹观七宝鞭。","温庭筠 奉天西佛寺"]]},{"n":"长安日","d":"","s":"《世说新语》中卷下《夙惠》","q":[["长安远于日，山川云间之。","元稹 江陵三梦"],["长安在何处，遥指夕阳边。","刘长卿 清明后登城眺望"]]},{"n":"典午","d":"","s":"《三国志》卷四十二《蜀书·谯周传》","q":[["长惭典午非材职。得就闲官即至公。","韩愈 晋公破贼回重拜台司以诗示幕中宾客愈奉和"]]},{"n":"君自了","d":"","s":"《晋书》卷四十三〈山涛列传〉","q":[]},{"n":"日边","d":"日下：喻指帝都。唐戎里《秋日感怀》：“日下未驰千里足，天涯徒泛五湖舟。”","s":"《世说新语笺疏》中卷下〈夙惠〉","q":[["桐上知音日下身，道光谁不仰清尘。","刘威 赠欧阳秀才"],["汉恩天外洽，周颂日边称。","司空曙 送翰林张学士岭南勒圣碑"]]},{"n":"师昭","d":"","s":"《三国志》卷四《魏书·三少帝纪》","q":[["袁董非徒尔，师昭岂偶然！","韩偓 感事三十四韵（丁卯已后）"]]},{"n":"云台仗","d":"","s":"《三国志》卷四《魏书·高贵乡公纪》","q":[["寂寞云台仗，飘飖沙塞旌。","杜甫 八哀诗赠左仆射郑国公严公武"],["无复云台仗，虚修水战船。","杜甫 寄岳州贾司马六丈巴州严八使君两阁老五十韵"]]}],"177":[{"n":"碧野鸡","d":"陈仓雉：咏雉。南朝陈张正见《雉子斑》：“陈仓雉未飞，敛翮依芳甸。”","s":"《史记》卷二十八〈封禅书〉","q":[]},{"n":"凤凰台","d":"乘鸾：喻求得佳偶，或谓女子升仙。唐李群玉《玉真观》：“高情帝王慕乘驾，绀发初簪玉叶冠。”唐赵嘏《代人赠别》：“会须携手乘鸾去，萧史楼台在王京。”；凤箫：泛指箫，或喻箫声优美。宋苏轼《与述古自有美堂乘月夜归》：“鱼钥未收清…","s":"《列仙传》卷上《萧史》","q":[["萧郎不顾凤楼人，云涩回车泪脸新。","上元夫人 留别"],["弄玉有夫皆得道，刘纲兼室尽登仙。","上元夫人 再赠"]]},{"n":"木已拱","d":"","s":"《春秋左传正义》卷十七〈僖公·传三十二年〉","q":[["金粟堆南木已拱，瞿唐石城草萧瑟。","杜甫 观公孙大娘弟子舞剑器行"]]},{"n":"秦后闻乐","d":"","s":"《昭明文选》卷二东汉·张平子（衡）《西京赋》","q":[["秦后徒闻乐，周王耻卜年。","王维 奉和圣制庆玄元皇帝玉像之作应制"]]},{"n":"天帝醉","d":"","s":"《昭明文选》卷二东汉·张平子（衡）《西京赋》","q":[["咄咄安可言，时醉而未醒。","陈子昂 感遇诗三十八首"]]},{"n":"箫台","d":"","s":"《昭明文选》卷二十八〈诗戊·乐府下·乐府八首·升天行〉","q":[]},{"n":"妖梦","d":"","s":"《春秋左传正义》卷十四〈僖公·传十五年〉","q":[]}],"178":[{"n":"不竞南风","d":"南风多死声：喻指在战争中显示出失败征兆。北周庾信《拟咏怀二十七首》之十一：“楚歌饶恨曲，南风多死声。”","s":"《春秋左传正义》卷三十八〈襄公·传十八年〉","q":[["楚歌饶恨曲，南风多死声。","庾信 拟咏怀二十七首之十一"],["南风昔不竞，豪圣思经纶。","李白 避地司空原言怀"]]},{"n":"绛老","d":"","s":"《春秋左传正义》卷四十〈襄公·传三十年〉","q":[]},{"n":"鹤舞","d":"","s":"《韩非子》卷三《十过》","q":[["鹤舞月将下，乌啼霜正繁。","李端 送从兄赴洪州别驾兄善琴"],["琴乌曲怨愤，庭鹤舞摧颓。","杜甫 秋日荆南述怀三十韵"]]},{"n":"晋君听琴","d":"","s":"《韩非子》卷三〈十过〉","q":[["折杨皇华合流俗，晋君听琴枉清角。","李白 答王十二寒夜独酌有怀"]]},{"n":"师旷","d":"","s":"《国语·晋语八》","q":[["三尺焦桐七条线，子期师旷两沈沈。","李山甫 赠弹琴李处士"],["还希师旷怀，见我心不轻。","贯休 上裴大夫二首"]]},{"n":"云动风飞","d":"","s":"《韩非子》卷三《十过》","q":[["不见秋云动，悲风稍稍飞。","杜甫 秋笛"]]},{"n":"子野","d":"","s":"《孟子》卷七《离娄上》","q":[["离娄岂不明，子野岂不聪。","孟郊 失意归吴因寄东台刘复侍御"],["子野真遗却，浮浅藏渊深。","孟郊 答昼上人止谗作"]]}],"179":[{"n":"陈蕃榻","d":"徐孺榻：指礼贤重才，或指礼遇宾客。唐孟浩然《荆门上张丞相》：“坐登徐孺榻，濒接李膺杯。”","s":"《后汉书》卷五十三〈周黄徐姜申屠列传·徐稚〉","q":[["解榻招徐稚，登楼引仲宣。","元稹 献荥阳公诗五十韵"],["何武劾腐儒，陈蕃礼高士。","刘禹锡 送湘阳熊判官孺登府罢归钟陵因寄呈江西裴中丞二十三兄"]]},{"n":"人如玉","d":"","s":"《毛诗正义》卷十一之一〈小雅·鸿雁之什·白驹〉","q":[["旧交封宿草，衰鬓重生刍。","李绅 趋翰苑遭诬搆四十六韵"],["停觞一摇笔，聊寄生刍吟。","李群玉 将离澧浦置酒野屿奉怀沈正字昆弟三人联登高第"]]},{"n":"孺子风流","d":"","s":"《后汉书》卷五十三〈周黄徐姜申屠列传·徐稚〉","q":[]},{"n":"孺子贫","d":"","s":"《后汉书》卷五十三《徐稚传》","q":[["孺子才虽远，公孙策未行。","于结 赋得生刍一束"],["未及冯公老，何惊孺子贫。","陈子昂 酬李参军崇嗣旅馆见赠"]]},{"n":"孺子宅","d":"","s":"《水经注疏》卷三十九〈赣水〉","q":[]},{"n":"徐孺子","d":"","s":"《后汉书》卷五十三《徐稚传》","q":[["见知嘱徐孺，赏句类陶渊。","孟郊 寄陕府邓给事"],["南郡迎徐子，临川谒谢公。","张继 送窦十九判官使江南"]]},{"n":"一绳何系","d":"","s":"《后汉书》卷五十三《徐稚传》","q":[["一绳将何系，忧醉不能持。","陈子昂 感遇诗三十八首"]]}],"180":[{"n":"北府牢之勇","d":"","s":"《晋书》卷八十四〈刘牢之列传〉","q":[]},{"n":"屐齿折","d":"喜折屐：指欣喜。宋苏轼《与叶淳老侯敦夫张秉道同相视新河秉道有诗次韵二首》之一：“怜君嗜好更迂阔，得我新诗喜折屐。”","s":"《世说新语笺疏》中卷上〈雅量〉","q":[["对棋陪谢傅，把剑觅徐君。","杜甫 别房太尉墓（在阆州）"]]},{"n":"玉树枝","d":"","s":"《世说新语》上卷上《言语》","q":[["谢庭瞻不远，潘省会于斯。","杜甫 同豆卢峰知字韵"],["子弟先卒伍，芝兰叠玙璠。","杜甫 览柏中允（一作丞）兼子侄数人除官制词因述父子兄弟四美载歌丝纶"]]},{"n":"谢玄文","d":"","s":"《晋书》卷七十九《谢安传》附《谢玄传》","q":[["名逃郤诜策，兴发谢玄文。","钱起 送李秀才落第游荆楚"]]},{"n":"谢掾","d":"","s":"《晋书》卷六十五《王导传》附《王珣传》","q":[["隋邸旧僚推谢掾，汉廷高议得相如。","罗隐 淮南送工部卢员外赴阙"]]},{"n":"幼度","d":"","s":"《晋书》卷七十九〈谢安列传·（奕子）谢玄〉","q":[]},{"n":"紫囊","d":"紫罗囊：喻指香囊，或喻精美之物。唐杜甫《又示宗武》：“试吟青玉案，莫羡紫罗囊。”","s":"《晋书》卷七十九《谢安传》附《谢玄传》","q":[["试吟青玉案，莫羡紫罗囊。","杜甫 又示宗武"],["归时每爱怀朱橘，戏处常闻佩紫囊。","卢纶 酬赵少尹戏示诸侄元阳等因以见赠"]]}],"181":[{"n":"数仞墙","d":"夫子墙：指道德学问高深莫测。唐钱起《寻司助李郎中不遇》：“重花不隔陈善榻，修竹能深夫子墙。”","s":"《论语注疏·子张》","q":[["夫子墙还峻，酂侯宅过谦。","姚合 和座主相公西亭秋日即事"],["丘墙高莫比，萧宅僻还清。","姚合 和裴令公新成绿野堂即事"]]},{"n":"端木辞金","d":"","s":"《史记》卷六十七《仲尼弟子列传》","q":[["端木辞金，钟离委珠。","李瀚 蒙求"]]},{"n":"瑚琏才","d":"","s":"《论语·公冶长》","q":[["郑公瑚琏器，华岳金天晶。","杜甫 八哀诗赠左仆射郑国公严公武"],["嶷嶷瑚琏器，阴阴桃李蹊。","杜甫 水宿遣兴奉呈群公"]]},{"n":"环堵","d":"","s":"《庄子集释》卷九下〈杂篇·让王〉","q":[]},{"n":"民受其赐","d":"","s":"《论语·先宪》","q":[["道州民，民到于今受其赐。","白居易 新乐府（并序）之道州民之美（一有贤字）臣遇明主也"]]},{"n":"吾安放","d":"","s":"《礼记·檀弓上》","q":[["百年见存殁，牢落吾安放。","杜甫 八哀诗故著作郎贬台州司户荥阳郑公虔"]]},{"n":"子贡言辞","d":"","s":"《史记》卷六十七〈仲尼弟子列传〉","q":[]}],"182":[{"n":"阿童","d":"","s":"《晋书》卷三十四《羊祜传》","q":[["人间无阿童，犹唱水中龙。","李贺 王浚墓下作"]]},{"n":"刀州","d":"三刀梦：指升官。唐李德裕《题剑门》：“想是三刀梦，森然在眼然。”","s":"《晋书》卷四十二〈王浚列传〉","q":[["解下佩刀无所惜，新闻天子付三刀。","姚合 裴大夫见过"],["东川横剑阁，南斗近刀州。","姚合 送任畹及第归蜀中觐亲"]]},{"n":"千寻铁锁","d":"","s":"《晋书》卷四十二〈王浚列传〉","q":[["千寻铁锁沈江底，一片降幡出石头。","刘禹锡 西塞山怀古"]]},{"n":"王浚爱旌旗","d":"","s":"《晋书》卷四十二〈王浚列传〉","q":[["王浚爱旌旗，梁竦劳州县。","杨巨源 题赵孟庄"]]},{"n":"王浚筏","d":"","s":"《晋书》卷四十二《王浚传》","q":[["横锁已沉王浚筏，投鞭难阻谢玄兵。","殷尧藩 送白舍人渡江"]]},{"n":"与浑不协","d":"","s":"《晋书》卷四十二《王浚传》","q":[["与浑虽不协，归皓实为雄。","张九龄 奉和圣制过王浚墓"]]}],"183":[{"n":"大小乔","d":"","s":"《三国志》卷五十四〈吴书·周瑜传〉","q":[["西京才子旁看取，何似乔家那窈娘。","杜牧 偶呈郑先辈"],["周郎若见红儿貌，料得无心念小乔。","罗虬 比红儿诗"]]},{"n":"道南宅","d":"","s":"《三国志》卷五十四《吴书·周瑜传》","q":[["但苦山北寒，谁知道南宅。","李白 赠友人三首之三"]]},{"n":"分宅","d":"","s":"《昭明文选》卷五十五南朝梁·刘孝标（峻）《广绝交论》","q":[["分宅脱骖间，感激怀未济。","杜甫 八哀诗赠秘书监江夏李公邕"]]},{"n":"功曹非复萧何","d":"","s":"《三国志》卷五十七《吴书·虞翻传》","q":[["勋业终（一作真）归马伏波，功曹非（一作无）复汉萧何。","杜甫 奉寄别马巴州（原注。时甫除京兆功曹。在东川。）"]]},{"n":"孙策","d":"","s":"《三国志》卷四十六《吴书·孙破虏讨逆传》","q":[["十万梅鋗空寸土，三分孙策竟荒丘。","罗隐 吴门晚泊寄句曲道友"]]},{"n":"月入怀中","d":"","s":"《搜神记》卷十","q":[]}],"184":[{"n":"汪汪万顷","d":"","s":"《世说新语笺疏》上卷上〈德行〉","q":[]},{"n":"黄宪万顷","d":"","s":"《后汉书》卷五十三《黄宪传》","q":[["王允千里，黄宪万顷。","李瀚 蒙求"]]},{"n":"林宗重黄生","d":"","s":"《后汉书》卷五十三《黄宪传》","q":[["知人想林宗，直道惭史鱼。","高适 苦雨寄房四昆季"],["宣父敬项橐，林宗重黄生。","魏万 金陵酬李翰林谪仙子"]]},{"n":"牛医儿","d":"","s":"《后汉书》卷五十三〈周黄徐姜申屠列传·黄宪〉","q":[]},{"n":"黄叔度","d":"","s":"《后汉书》卷五十三〈周黄徐姜申屠列传·黄宪〉","q":[["最笑近来黄叔度，自投名刺占陂湖。","元稹 重酬乐天"],["季鹰久疏旷，叔度早畴昔。","刘长卿 九日岳阳待黄遂张涣"]]},{"n":"叔度千顷","d":"叔度千顷：指人心胸宽广。宋黄庭坚《汴岸置酒赠黄十七》：“初平群羊置莫问，叔度千顷醉即休。”","s":"《后汉书》卷五十三〈周黄徐姜申屠列传·黄宪〉","q":[["初平群羊置莫问，叔度千顷醉即休。","黄庭坚 汴岸置酒赠黄十七"]]}],"185":[{"n":"北海归文","d":"","s":"《孟子注疏》卷七下〈离娄章句上〉","q":[]},{"n":"夷齐","d":"夷齐：喻指有气节，不接受敌人施舍。唐李白《梁园吟》：“持盐把酒但饮之，莫学夷齐事高洁。”","s":"《史记》卷六十一〈伯夷列传〉","q":[["苟非夷齐心，岂得无战争。","于濆 古征战"],["采薇易为山，何必登首阳。","于濆 感怀"]]},{"n":"巢夷","d":"","s":"东汉·王符《潜夫论》卷八《交际》","q":[["山水能成癖，巢夷拟独亲。","独孤及 答李滁州忆玉潭新居见寄"],["诸君推管乐，之子慕巢夷。","陈子昂 同宋参军之间梦赵六赠卢除二子之作"]]},{"n":"二老","d":"","s":"《孟子注疏》卷七下〈离娄章句上〉","q":[["与子成二老，来往亦风流。","杜甫 寄赞上人"]]},{"n":"麋鹿群","d":"","s":"南朝梁·梁元帝萧绎《金楼子·兴王》","q":[["世人只向簪裾老，芳草空馀麋鹿闲。","令狐楚 赋山"],["烟霄惭暮齿，麋鹿愧初心。","吴融 和杨侍郎"]]},{"n":"天下大老","d":"","s":"《孟子注疏》卷七上〈离娄章句上〉","q":[]}],"186":[{"n":"白头王建在","d":"","s":"《全唐诗》卷三百八十六〈赠王建〉","q":[]},{"n":"抖擞尘埃","d":"","s":"《全唐诗》卷三百八十〈夏日谒智远禅师〉","q":[]},{"n":"郊岛","d":"","s":"《苏轼文集》卷六三〈祭柳子玉文〉","q":[["元轻白俗，郊寒岛瘦。嘹然一吟，众作卑陋。","苏轼 祭柳子玉文"]]},{"n":"诗穷孟郊","d":"","s":"《新唐书》卷一百七十六〈韩愈列传·孟郊〉","q":[]},{"n":"拾柴东野","d":"","s":"《全唐诗》卷三百八十〈忽不贫喜卢仝书船归洛〉","q":[]},{"n":"月娥","d":"","s":"《全唐诗》卷三百七十六〈看花五首〉","q":[]}],"187":[{"n":"宠过韦","d":"","s":"《汉书》卷七十三〈韦贤列传〉","q":[["韦贤初相汉，范叔已归秦。","杜甫 上韦左相二十韵"],["将门高胜霍，相子宠过韦。","钱起 陪南省诸公宴殿中李监宅"]]},{"n":"满籯金","d":"","s":"《汉书》卷七十三〈韦贤列传·韦贤〉","q":[["世事徒三窟，儿童且一经。","唐彦谦 梅亭"],["遗子后黄金，作歌先紫芝。","张九龄 骊山下逍遥公旧居游集"]]},{"n":"扶阳","d":"","s":"《汉书》卷七十三《韦贤传》","q":[["记事还同楚倚相，传经远自汉扶阳。","权德舆 送韦行军员外赴河阳"],["宾筵徵稷嗣，家法自扶阳。","权德舆 韦宾客宅与诸博士宴集"]]},{"n":"汉相韦贤","d":"","s":"《汉书》卷七十三〈韦贤列传·韦贤〉","q":[]},{"n":"韦平","d":"","s":"《汉书》卷七十三〈韦贤列传·韦贤〉","q":[]},{"n":"韦相积德","d":"","s":"《汉书》卷七十三《韦贤传》","q":[["莫埋丞相印，留着付玄成。","岑参 故仆射裴公挽歌三首"],["积德韦丞相，通神张子房。","崔泰之 同光禄弟冬日述怀"]]}],"188":[{"n":"刘惔倾酿","d":"","s":"《世说新语》中卷下《赏誉》","q":[["刘惔倾酿，孝伯痛饮。","李瀚 蒙求"]]},{"n":"刘尹","d":"","s":"《世说新语》上卷上《德行》","q":[["传书报刘尹，何事忆陶家。","李端 和张尹忆东篱菊"]]},{"n":"孝廉船","d":"","s":"《世说新语》下卷下《文学》","q":[["将过夫子宅，前问孝廉船。","李端 送耿拾遗湋使江南括图书"],["兴残虚白室，迹断孝廉船。","杜甫 哭韦大夫之晋"]]},{"n":"倾家酿","d":"","s":"《世说新语笺疏》中卷下〈赏誉〉","q":[]},{"n":"叔宝清","d":"","s":"《晋书》卷三十六〈卫瓘列传·（孙）卫玠、（恒族弟）卫展〉","q":[["羸将卫玠比，冷共邺侯同。","李端 长安感事呈卢纶"],["我亦休文瘦，君能叔宝清。","陆龟蒙 奉酬袭美早春病中书事"]]},{"n":"哭真长","d":"","s":"《晋书》卷七十五《刘惔传》","q":[["任被褚裒泉下笑，重将北面哭真长。","唐彦谦 闻李渎司勋下世"],["日疑怀叔度，夜似忆真长。","杜审言 赠崔融二十韵"]]}],"189":[{"n":"闭门种菜","d":"","s":"《三国志》卷三十二〈蜀书·先主备传〉","q":[]},{"n":"单刀会","d":"","s":"《三国志》卷五十四〈吴书·鲁肃传〉","q":[]},{"n":"刮骨","d":"","s":"《三国志》卷三十六〈蜀书·关羽传〉","q":[["报雠只是闻尝胆，饮酒不曾妨刮骨。","王维 燕支行"]]},{"n":"关羽","d":"","s":"《三国志》卷三十六《蜀书·关羽传》","q":[["湘西不得归关羽，河内犹宜借寇恂。","杜甫 奉寄章十侍御"]]},{"n":"关张","d":"","s":"《南史》卷六十七《萧摩诃传》","q":[["汉将小卫霍，蜀将凌关张。","岑参 东归留题太常徐卿草堂"]]},{"n":"云长勇","d":"","s":"《三国志》卷三十六《蜀书·关羽传》","q":[["矫矫云长勇，恂恂郤縠风。","杜牧 题永崇西平王宅太尉愬院六韵"]]}],"190":[{"n":"未赦虞翻","d":"","s":"《三国志》卷五十七〈吴书·虞翻传〉","q":[]},{"n":"青蝇吊","d":"青蝇吊：用以悼亡。清王士禛《望剑州怀乔文衣》：“太息青蝇吊，交州几岁还？”","s":"《艺文类聚》卷四十〈礼部下·吊〉","q":[]},{"n":"功曹非复萧何","d":"","s":"《三国志》卷五十七《吴书·虞翻传》","q":[["勋业终（一作真）归马伏波，功曹非（一作无）复汉萧何。","杜甫 奉寄别马巴州（原注。时甫除京兆功曹。在东川。）"]]},{"n":"虞翻骨相屯","d":"","s":"《三国志》卷五十七《吴书·虞翻传》","q":[["地远虞翻老，秋深宋玉悲。","李白 赠易秀才"],["世议排张挚，时情弃仲翔。","柳宗元 弘农公以硕德伟材屈于诬枉左官三岁复为大僚天监昭明人心感悦宗元窜伏湘浦拜贺末由谨献诗五十韵以毕微志"]]},{"n":"青蝇悲虞氏","d":"","s":"《三国志》卷五十七〈吴书·虞翻传〉","q":[["青蝇岂独悲虞氏，黄犬应闻笑李斯。","李德裕 到恶溪夜归泊芦岛"]]},{"n":"虞童","d":"","s":"《三国志》卷五十七《吴书·虞翻传》","q":[["贾傅辞宁切，虞童发未䰉。","柳宗元 酬韶州裴曹长使君寄道州吕八大使因以见示二十韵一首"]]}],"191":[{"n":"孤山梅","d":"","s":"《宋人轶事汇编》卷七〈林逋常秩陈恬〉","q":[]},{"n":"暗香疏影","d":"","s":"《宋诗钞·和靖诗钞》","q":[]},{"n":"飞鹤传书","d":"","s":"《宋人轶事汇编》卷七〈林逋常秩陈恬〉","q":[]},{"n":"孤山处士","d":"","s":"《宋史》卷四百五十七〈隐逸列传上·林逋〉","q":[]},{"n":"梅鹤","d":"","s":"《归田录》卷二","q":[]},{"n":"西湖处士","d":"","s":"《归田录》卷二","q":[]}],"192":[{"n":"桓僖","d":"","s":"《春秋左传·哀公三年》","q":[]},{"n":"鲁公黄发颂","d":"","s":"《毛诗正义》卷二十之二〈鲁颂·駉之什·閟宫〉","q":[]},{"n":"鲁侯昌","d":"","s":"《诗经·鲁颂·閟宫》","q":[["雅歌张仲德，颂祝鲁侯昌。","柳宗元 弘农公以硕德伟材屈于诬枉左官三岁复为大僚天监昭明人心感悦宗元窜伏湘浦拜贺末由谨献诗五十韵以毕微志"]]},{"n":"鲁侯难老","d":"","s":"《毛诗正义》卷二十之一〈鲁颂·駉之什·泮水〉","q":[]},{"n":"鲁侯燕喜","d":"","s":"《毛诗正义》卷二十之二〈鲁颂·駉之什·閟宫〉","q":[]},{"n":"寿而臧","d":"","s":"《毛诗正义》卷二十之二〈鲁颂·駉之什·閟宫〉","q":[]}],"193":[{"n":"大手笔","d":"椽笔：喻名家作品或写作才能极高。宋苏轼《三月廿三恭闻皇太后升遐》之一：“月落风悲天雨泣，谁将椽笔写光尘？”","s":"《晋书》卷六十五〈王导列传·王珣〉","q":[["古者世称大手笔，此事不系于职司。","李商隐 韩碑"],["世掌纶言传大笔，官分鸿序压霜台。","李群玉 送唐侍御福建省兄"]]},{"n":"郗超","d":"","s":"《世说新语笺疏》下卷上〈宠礼〉","q":[["明日郗超会，应思下客同。","司空曙 酬郑十四望驿不得同宿见赠因寄张参军"],["王粲名虽重，郗超髯未长。","李端 送从叔赴洪州"]]},{"n":"令公喜","d":"","s":"《世说新语笺疏》下卷上〈宠礼〉","q":[]},{"n":"黑头公","d":"","s":"《世说新语笺疏》中卷上〈识鉴〉","q":[["到彼的知宣室语，几时徵拜黑头公。","罗隐 淮南送节度卢端公将命之汴州端公常为汴州相公从事"],["削玉风姿官水土，黑头公自古来难。","韩偓 和王舍人抚州饮席赠韦司空"]]},{"n":"禁脔","d":"","s":"《世说新语》下卷下《排调》","q":[["君为禁脔婿，争看玉人游。","李颀 赠别张兵曹"],["禁脔去东床，趋庭赴北堂。","杜甫 送大理封主薄五郎亲事不合却赴通州主薄前阆州贤子余与主薄平章郑氏女子垂欲纳郑氏伯父京书至女子已许他族亲事遂停"]]},{"n":"头方黑","d":"","s":"《世说新语笺疏》中卷上〈识鉴〉","q":[]}],"194":[{"n":"啖螯讥尔雅","d":"","s":"《世说新语》下卷下《纰漏》","q":[["啖螯讥尔雅，卖饼诉公羊。","唐彦谦 送樊琯司业归朝"]]},{"n":"谢将军","d":"","s":"《世说新语笺疏》上卷下〈文学〉","q":[["吟尽长江一江月，更无人似谢将军。","吴融 松江晚泊"],["早闻牛渚咏，今见鹡鸰心。","孟浩然 送袁十岭南寻弟"]]},{"n":"鸲鹆舞","d":"","s":"《晋书》卷七十九《谢尚传》","q":[["兴酣鸲鹆舞，言洽凤皇翔。","杜审言 赠崔融二十韵"],["且请同观舞鸲鹆，何须竟哂食槟榔。","卢纶 酬赵少尹戏示诸侄元阳等因以见赠"]]},{"n":"仁祖弹弦","d":"","s":"《世说新语笺疏》下卷上〈容止〉","q":[["弹弦本自称仁祖，吹管由来许季长。","司马逸客 雅琴篇"]]},{"n":"小安丰","d":"","s":"《晋书》卷四十三〈王戎列传〉","q":[]},{"n":"袁舫","d":"","s":"《世说新语笺疏》上卷下〈文学〉","q":[]}],"195":[{"n":"北斗","d":"","s":"《后汉书》卷六十三《李固传》","q":[["北斗司喉舌，东方领搢绅。","杜甫 上韦左相二十韵（见素。天宝元年。改侍中为左相。中书令为右相。十五载。见素从明皇幸蜀。至巴西。诏兼左相。封豳国公。）"],["南荆双戟痕犹在，北斗孤魂望已深。","灵一 哭卫尚书"]]},{"n":"胡广惭","d":"","s":"《后汉书》卷六十三〈李杜列传·李固〉","q":[["孔光尊董贤，胡广惭李固。","李华 杂诗六首"]]},{"n":"李杜齐名","d":"","s":"《后汉书》卷六十三《李固杜乔传·赞》","q":[["李杜齐名真忝窃，朔云寒菊倍离忧。","杜甫 长沙送李十一"]]},{"n":"李固冤","d":"","s":"《后汉书》卷六十三《李固杜乔传》","q":[["李固有冤藏蠹简，邓攸无子续清风。","李玖 四丈夫同赋之一"]]},{"n":"衣衾藏李固","d":"","s":"《后汉书》卷六十三《李固传》","q":[["虽有衣衾藏李固，终无表疏雪王章。","李玖 四丈夫同赋"]]},{"n":"义夫","d":"","s":"《后汉书》卷六十三《杜乔传》","q":[["义夫留感激，公子播英名。","李绅 到宣武三十韵"]]}],"196":[{"n":"谢雪","d":"","s":"《世说新语》上卷上《言语》","q":[["谢庭风韵婕妤才，天纵斯文去不回。","窦常 过宋氏五女旧居"],["谢家争拟絮，越岭误惊梅。","令狐楚 省中直夜对雪寄李师素侍郎"]]},{"n":"凝之","d":"","s":"《世说新语笺疏》上卷上〈言语〉","q":[]},{"n":"天壤王郎","d":"","s":"《世说新语笺疏》下卷上〈贤媛〉","q":[]},{"n":"谢娘解围","d":"","s":"《晋书》卷九十六〈列女列传·王凝之妻谢氏〉","q":[]},{"n":"谢女","d":"谢女：咏才女。唐刘禹锡《柳絮》：“索回谢女题诗笔，点缀陶公漉酒巾。”","s":"《世说新语笺疏》上卷上〈言语〉","q":[["萧郎独宿落花夜，谢女不归明月春。","刘沧 代友人悼姬"],["好是照身宜谢女，嫦娥飞向玉宫来。","姚合 咏镜"]]},{"n":"谢女解围","d":"","s":"《晋书》卷九十六《列女传·王凝之妻谢氏传》","q":[["齐后破坏，谢女解围。","李瀚 蒙求"]]}],"197":[{"n":"马帐","d":"绛帐：喻授业师长或授课处所。唐卢纶《上巳日陪齐相公花楼宴》：“札卑瞻绎帐，恩侠厕华缨。”","s":"《后汉书》卷六十上〈马融列传上〉","q":[["心轻马融帐，谋夺子房帷。","元稹 酬翰林白学士代书一百韵"],["保宁帝业青萍在，投弃儒书绛帐空。","方干 王将军"]]},{"n":"马融笛","d":"","s":"《后汉书》卷六十上〈马融列传上〉","q":[["弹弦本自称仁祖，吹管由来许季长。","司马逸客 雅琴篇"],["虚无马融笛，怅望龙骧茔。","杜甫 八哀诗赠左仆射郑国公严公武"]]},{"n":"邻笛唤将乡思动","d":"","s":"《昭明文选》卷十八〈赋壬·音乐下·长笛赋〉","q":[]},{"n":"马南郡","d":"","s":"《后汉书》卷六十上〈马融列传上〉","q":[["尝闻马南郡，门下有康成。","刘长卿 送郑说之歙州谒薛侍郎"],["马融方直校，阅检复持铅。","李端 酬前驾部员外郎苗发"]]},{"n":"马融奢","d":"马融奢：指生活奢侈。唐柳宗元《同刘二十八院长述旧言怀感时书事奉寄澧州张员外使君五十二韵之作因其韵增至八十通赠二君子》：“肯随胡质矫，方恶马融奢。”","s":"《后汉书》卷六十上《马融传》","q":[["肯随胡质矫，方恶马融奢。","柳宗元 同刘二十八院长述旧言怀感时书事奉寄澧州张员外使君五十二韵之作因其韵增至八十通赠二君子"]]},{"n":"吾道东","d":"","s":"《后汉书》卷三十五《郑玄传》","q":[["斯人脱身来，岂非吾道东。","杜甫 赠苏四徯"],["吾道将东矣，秋风更飒然。","钱起 寇中送张司马归洛"]]}],"198":[{"n":"山阳笛","d":"山阳笛：喻悼念、怀念故友。唐司空曙《残老百哗歌同王员外耿拾遗吉中罕李端游慈思各赋一物》：“金谷筝中传不似，山阳笛里写难成。”","s":"《昭明文选》卷十六、三国魏·向子期（秀）《思旧赋·序》","q":[["旧时闻笛泪，今夜重沾衣。","司空曙 冬夜耿拾遗王秀才就宿因伤故人"],["金谷筝中传不似，山阳笛里写难成。","司空曙 残莺百啭歌同王员外耿拾遗吉中孚李端游慈恩各赋一物"]]},{"n":"嵇向","d":"","s":"《晋书》卷四十九《向秀传》","q":[["嵇向林庐接，携手行将归。","钱起 客舍赠郑贲"]]},{"n":"竹林七贤","d":"七贤：喻指文人放荡不羁，或指独立于世俗之外，或喻朋友的交情深厚。唐卢纶《秋夜同畅当宿潭上西亭》：“圆月出山头，七贤林下游。”","s":"《三国志》卷二十一〈魏书·王粲传·嵇康〉","q":[["东篱摘芳菊，想见竹林游。","储光羲 仲夏饯魏四河北觐叔"],["超超青云器，婉婉竹林会。","储光羲 奉和韦判官献侍郎叔除河东采访使"]]},{"n":"攀嵇","d":"","s":"《昭明文选》卷二十一南朝宋·颜延年（延之）《五君咏五首·向常侍》","q":[["正遂攀稽愿，翻追访戴欢。","吴融 和诸学士秋夕禁直偶雪"],["沿牒相逢楚水湄，竹林文酒此攀嵇。","胡宿 赵宗道归辇下"]]},{"n":"向秀园","d":"","s":"《晋书》卷四十九《向秀传》","q":[["暮雨扬雄宅，秋风向秀园。","李郢 园居"]]},{"n":"向子期","d":"","s":"《晋书》卷四十九《向秀传》","q":[["逸气刘公干，玄言向子期。","高适 奉酬睢阳路太守见赠（一作贻）之作"],["旧里若为归去好，子期凋谢吕安亡。","韦庄 思归"]]}],"199":[{"n":"随御史轩","d":"","s":"《后汉书》卷三十三上〈郑弘列传〉","q":[]},{"n":"白鹿","d":"","s":"《艺文类聚》卷九十五","q":[["竹马数小儿，拜迎白鹿前。","李白 赠宣城宇文太守兼呈崔侍御"]]},{"n":"车至鹿驯","d":"","s":"《谢承后汉书》卷二〈郑弘传〉","q":[["郡移棠转茂，车至鹿还驯。","钱起 送王使君移镇淮南"]]},{"n":"郑风","d":"","s":"《后汉书》卷三十三《郑弘传》","q":[["每得樵风便，往来殊不难。","丘为 泛若耶溪"],["花县弹琴暇，樵风载酒时。","刘长卿 陪王明府泛舟"]]},{"n":"沈钱","d":"","s":"《古今注》卷下《草木》","q":[["常怪投钱饮，事与贤达疏。","韦应物 至西峰兰若受田妇馈"],["款交欣散玉，洽友悦沈钱。","骆宾王 咏云酒"]]},{"n":"随车","d":"","s":"《后汉书》卷三十三上〈郑弘列传〉","q":[["风变市儿惊偃草，雨晴郊薮谬随车。","李绅 拜三川守"],["惠风仍偃草，灵雨会随车。","柳宗元 韦使君黄溪祈雨见召从行至祠下口号"]]}],"200":[{"n":"俸钱散","d":"","s":"《后汉书》卷八十上〈文苑列传·黄香〉","q":[["俸钱时散士子尽，府库不为骄豪虚。","杜甫 惜别行送刘仆射判官"]]},{"n":"黄郎子","d":"","s":"《后汉书》卷八十上〈文苑列传·黄香〉","q":[]},{"n":"天下无双","d":"江夏黄童：指才华出众者。唐罗隐《送姚安之赴任秋浦》：“江夏黄童徒逞辩，广都庞令恐非才。”","s":"《东观汉记》卷十七〈黄香传〉","q":[["呜呼江夏姿，竟掩宣尼袂。","杜甫 八哀诗（并序）赠秘书监江夏李公邕"],["江夏黄童徒逞辩，广都庞令恐非才。","罗隐 送姚安之赴任秋浦"]]},{"n":"黄香","d":"","s":"《后汉书》卷八十上《文苑传·黄香传》","q":[["澹澹沧海气，结成黄香才。","孟郊 送黄构擢第后归江南"],["网今开傅燮，书旧识黄香。","杜牧 除官归京睦州两霁"]]},{"n":"扇枕","d":"","s":"《太平御览》卷七百七〈服用部九·枕〉","q":[["北堂倚门望君忆，东归扇枕后秋色。","岑参 送韩巽入都觐省便赴举"],["天从扇枕愿，人遂倚门情。","张说 岳州别姚司马诏之制许归侍"]]},{"n":"文强阅书","d":"","s":"《后汉书》卷八十上《文苑传·黄香传》","q":[["少孺嘉能赋，文强阅赐书。","寇坦 同张少府和厍狄员外夏晚初霁南省寓直时兼充节度判官之作"]]}],"201":[{"n":"馆娃宫","d":"","s":"《吴越春秋》卷九〈勾践阴谋外传·勾践十二年〉","q":[["分明石潭里，宜照浣纱人。","张子容 春江花月夜二首之一"],["别有浣纱吴女郎，行尽绿潭潭转幽。","李白 和卢侍御通塘曲"]]},{"n":"捧心颦","d":"丑女效颦：指丑陋而强学美好之人。唐李白《古风五十九首》之三十五：“丑女来效颦，还家惊四邻。”；捧心：喻指仿效弄巧成拙，或喻美女病态。唐”柳宗元《重赠二首》之二：“世世悠悠不识真，姜芽尽是捧心人。’”","s":"《庄子集释》卷五下〈外篇·天运〉","q":[["翻惭效颦者，却笑从人迟。","于濆 拟古意"],["丑女来效颦，还家惊四邻。","李白 古风之三十五"]]},{"n":"浓抹淡妆","d":"","s":"《苏轼诗集》卷九〈饮湖上初晴后雨二首〉","q":[]},{"n":"嫫母","d":"","s":"《荀子·赋篇》","q":[["我愿燕赵姝，化为嫫母姿。","于濆 苦辛吟"],["嫫母西施共此身，可怜老少隔千春。","吕岩 题广陵妓屏二首之一"]]},{"n":"西子扁舟","d":"","s":"《吴地记》","q":[]},{"n":"苧罗山","d":"","s":"《吴越春秋》卷九〈勾践阴谋外传·勾践十二年〉","q":[["此去若逢花柳月，栖禅莫向苧萝山。","施肩吾 送僧游越"]]}],"202":[{"n":"抚琴","d":"","s":"《世说新语》下卷上《伤逝》","q":[["抚琴犹可绝，况此故无弦。","李益 闻亡友王七嘉禾寺得素琴"],["援琴一流涕，旧馆几沾巾。","陈子昂 同旻上人伤寿安傅少府"]]},{"n":"麾扇渡","d":"","s":"《晋书》卷六十八《顾荣传》","q":[["长呼结浮云，埋没顾荣扇。","李白 江夏寄汉阳辅录事"]]},{"n":"顾荣锡炙","d":"","s":"《晋书》卷六十八《顾荣传》","q":[["顾荣锡炙，田文比饭。","李瀚 蒙求"]]},{"n":"顾彦先","d":"","s":"《昭明文选》卷二十四〈诗丙·赠答二·赠尚书郎顾彦先二首〉","q":[["御史王元贶，郎官顾彦先。","韩翃 送蒋员外端公归淮南"]]},{"n":"麒麟","d":"","s":"《晋书》卷八十三《顾和传》","q":[["衡岳三麒麟，各振黄钟音。","李群玉 将离澧浦置酒野屿奉怀沈正字昆弟三人联登高第"]]},{"n":"三俊","d":"","s":"《晋书》卷六十八〈顾荣列传〉","q":[]}],"203":[{"n":"垂帷","d":"下帷：喻指专心读书。唐李白《行行且游猎篇》：“儒生不及游侠人，白首下帷复何益。”","s":"《汉书》卷五十六《董仲舒传》","q":[["且逍遥，还酩酊。仲舒漫不窥园井。","刘言史 放萤怨"],["对景嗟移晷，窥园讵改阴。","孟简 惜分阴"]]},{"n":"晁董","d":"","s":"《旧唐书》卷一百九十下〈文苑列传下·刘蕡〉","q":[]},{"n":"天人三策","d":"","s":"《汉书》卷五十六〈董仲舒列传〉","q":[]},{"n":"改瑟","d":"","s":"《汉书》卷五十六《董仲舒传》","q":[["垂衣深共理，改瑟其咸若。","张九龄 奉和圣制送十道采访使及朝集使"]]},{"n":"三儒","d":"","s":"《汉书》卷八十九〈循吏列传〉","q":[]},{"n":"仲舒对策","d":"","s":"《汉书》卷五十六《董仲舒传》","q":[["贾谊上书曾伏阙，仲舒陈策欲匡时。","牟融 寄永平友人"],["述圣鲁宣父，通经汉仲舒。","钱起 奉和中书常舍人晚秋集贤院即事寄徐薛二侍御"]]}],"204":[{"n":"不因热","d":"","s":"《东观汉记》卷十八〈梁鸿传〉","q":[["潘岳本自闲，梁鸿不因热。","骆宾王 夏日游德州赠高四"]]},{"n":"齐眉案","d":"","s":"《后汉书》卷八十三〈逸民列传·梁鸿〉","q":[]},{"n":"齐眉","d":"齐眉：指夫妻间互敬互爱。唐李绅《趋翰苑遭诬拘四十六韵》：‘俯首安赢业，齐眉慰病夫。”","s":"《后汉书》卷八十三〈逸民列传·梁鸿〉","q":[["我非东床人，令姊忝齐眉。","李白 窜夜郎于乌江留别宗十六璟"],["俯首安羸业，齐眉慰病夫。","李绅 趋翰苑遭诬搆四十六韵"]]},{"n":"梁鸿","d":"鸿舂：指生活清贫。唐贾岛《送令狐绹相公》：“鸿舂乖汉爵，祯病卧漳滨。”","s":"《后汉书》卷八十三〈逸民列传·梁鸿〉","q":[["伯鸾游太学，中夜一相望。","储光羲 洛中贻朝校书衡朝即日本人也"],["元淑命不达，伯鸾吟可叹。","储光羲 贻刘高士别"]]},{"n":"五噫出京","d":"","s":"《后汉书》卷八十三《逸民传·梁鸿传》","q":[["儿戏不足道，五噫出西京。","李白 经乱离后天恩流夜郎忆旧游书怀赠江夏韦太守良宰"]]},{"n":"洗粉黛","d":"","s":"《高士传》卷下《梁鸿列传》","q":[["客来洗粉黛，日暮拾流萤。","杜甫 奉酬薛十二丈判官见赠"]]}],"205":[{"n":"严终","d":"","s":"高适《奉寄平原颜太守》","q":[]},{"n":"请长缨","d":"请长缨：指立志报国，降服强敌。唐白居易《元和十二年淮寇未平》：“愚计忽思飞短檄，狂心便欲请长缨。”","s":"《汉书》卷六十四下〈严朱吾丘主父徐严终王贾列传下·王褒〉","q":[["请缨期系虏，枕草誓捐躯。","元稹 哭吕衡州六首之三"],["何劳短兵接，自有长缨缚。","刘长卿 奉和李大夫同吕评事太行苦热行兼寄院中诸公仍呈王员外"]]},{"n":"入关意气","d":"","s":"《汉书》卷六十四下〈严朱吾丘主父徐严终王贾列传下·终军〉","q":[]},{"n":"弃繻生","d":"","s":"《汉书》卷六十四下《严朱吾丘主父徐严终王贾列传·终军》","q":[["弃繻当日路，应竞看终军。","姚鹄 送刘耕归舒州"],["遥知出关后，更有一终军。","岑参 送薛播擢第归河东"]]},{"n":"横草","d":"","s":"《汉书》卷六十四下《终军传》","q":[["微诚慕横草，琐力摧撞筵。","韩愈 答张彻"],["不量横草力，虚慕入云踪。","韩琮 秋晚信州推院亲友或责无书即事寄答"]]},{"n":"终贾","d":"","s":"《旧唐书》卷七十四〈马周列传〉","q":[]}],"206":[{"n":"八裴","d":"","s":"《世说新语》中卷下《品藻》","q":[["兄弟真二陆，声名连八裴。","高适 酬裴员外以诗代书"]]},{"n":"玉山行","d":"玉人：喻指男子美貌。唐卢纶《酬金部王郎中省中春日见寄》：“鹤侣正疑芳景引，玉人那为簿书沉。”","s":"《世说新语笺疏》下卷上〈容止〉","q":[["共惜不成金谷妓，虚令看杀玉车人。","王翰 观蛮童为伎之作"],["拂墙花影动，疑是玉人来。","崔莺莺 答张生（一作明月三五夜）"]]},{"n":"寒眸激电","d":"","s":"《世说新语笺疏》下卷上〈容止〉","q":[]},{"n":"矛戟","d":"","s":"《世说新语》中卷下《赏誉》","q":[["见说往年在翰林，胸中矛戟何森森。","任华 寄李白"],["复进出矛戟，昭然开鼎彝。","杜甫 赠崔十三评事公辅"]]},{"n":"裴楷清通","d":"","s":"《世说新语》中卷下《赏誉》","q":[["王戎简要，裴楷清通。","李瀚 蒙求"],["裴楷能清通，山涛急推荐。","殷寅 铨试后徵山别业寄源侍御"]]},{"n":"裴王","d":"","s":"《艺文类聚》卷四十八","q":[["裴王持藻镜，姚宋斡陶钧。","元稹 代曲江老人百韵"]]}],"207":[{"n":"不列三后","d":"","s":"《后汉书》卷五十四《杨赐传》","q":[["早知大理官，不列三后俦。","韩愈 赴江陵途中寄赠王二十补阙李十一拾遗李二十六员外翰林三学士"]]},{"n":"皋陶夔契","d":"","s":"《尚书》卷三〈虞书·舜典〉","q":[]},{"n":"皋陶","d":"","s":"《尚书》卷三〈虞书·舜典〉","q":[["皇皇轩辕君，赞赞皋陶谟。","储光羲 观范阳递俘"],["既非皋陶吏，空食沉狱魂。","孟郊 峡哀"]]},{"n":"皋夔","d":"","s":"《尚书·虞书·舜典》","q":[["鸳鹭皆回席，皋夔亦慕膻。","韩偓 感事三十四韵"],["昨者州前搥大鼓，嗣皇继圣登夔皋。","韩愈 八月十五夜赠张功曹"]]},{"n":"万机","d":"","s":"《尚书·虞书·皋陶谟》","q":[["时此万机暇，适与佳节并。","李适 重阳日赐宴曲江亭赋六韵诗用清字"]]},{"n":"伊皋","d":"","s":"《汉书》卷四十《张陈王周传赞》","q":[["方将袭伊皋，永以崇夏殷。","储光羲 敬酬陈掾亲家翁秋夜有赠"],["伊皋争负鼎，舜禹让垂旒。","徐夤 依御史一本无御史二字温飞卿华清宫二十二韵"]]}],"208":[{"n":"池塘草","d":"梦惠连：指创作诗文有神来之笔。唐李白《书情寄从弟邢州长史昭》：“昨梦见惠连，朝吟谢公诗。”","s":"《全上古三代秦汉三国六朝文·全梁文》卷五十五〈钟嵘·诗品中〉","q":[["惯识江南春早处，长惊蓟北梦回时。谢家园里成吟久，只欠池塘一句诗。","吴融 莺"],["随梦入池塘，无心在金谷。","唐彦谦 春草"]]},{"n":"惠连","d":"","s":"《南史》卷十九《谢方明传》附《谢惠连传》","q":[["惠连仍有作，知得从兄酬。","司空曙 送魏季羔游长沙觐兄"],["辅嗣外生还解易，惠连群从总能诗。","李嘉祐 与从弟正字从兄兵曹宴集林园"]]},{"n":"愧惠连","d":"","s":"《昭明文选》卷十三南朝宋·谢惠连《雪赋》","q":[["念物希周穆，含毫愧惠连。","李咸用 雪十二韵"],["惠连发清兴，袁安念高卧。","高适 苦雪四首之二"]]},{"n":"济江篇","d":"","s":"《昭明文选》卷二十五南朝宋·谢灵运《酬从弟惠连》","q":[["济江篇已出，书府俸犹贫。","耿湋 送郭正字归郢上"],["归来莫忘此，兼示济江篇。","高适 秦中送李九赴城"]]},{"n":"谢法曹","d":"","s":"《宋书》卷五十三《谢方明传》附《谢惠连传》","q":[["狂歌好爱陶彭泽，佳句唯称谢法曹。","韩翃 和高平朱参军思归作"]]},{"n":"谢家兄弟","d":"","s":"《宋书》卷五十三《谢方明传》附《谢惠连传》","q":[["友朋汉相府，兄弟谢家诗。","耿湋 春日书情寄元校书伯和相国元子"],["人日春风绽早梅，谢家兄弟看花来。","鲍防 人日陪宣州范中丞传正与范侍御传真宴东峰亭"]]}],"209":[{"n":"苏黄","d":"","s":"《宋史·文苑传六·黄庭坚》","q":[]},{"n":"黄陈","d":"","s":"《和张功父梅诗》","q":[]},{"n":"笔势回万牛","d":"","s":"《山谷内集诗注》卷六〈以团茶洮州绿石砚赠无咎文潜〉","q":[]},{"n":"江南断肠句","d":"","s":"《宋诗钞·山谷诗钞》","q":[]},{"n":"山谷品题","d":"","s":"《宋诗钞·山谷诗钞》","q":[]},{"n":"光风霁月","d":"","s":"《全宋诗》卷一千一十六〈濂溪诗序〉","q":[]}],"210":[{"n":"蔡地兵威","d":"","s":"《新唐书》卷一百七十三〈裴度列传〉","q":[]},{"n":"悬瓠","d":"","s":"《旧唐书》卷一百三十三〈李晟列传·李愬〉","q":[]},{"n":"晋公已生","d":"","s":"《太平广记》卷一百三十八〈徵应四·裴度〉","q":[]},{"n":"柳雅","d":"","s":"《全唐文》卷五百七十一〈柳宗元三·献平淮夷雅表〉","q":[]},{"n":"绿野堂","d":"","s":"《旧唐书》卷一百七十〈裴度列传〉","q":[]},{"n":"平淮裴度","d":"","s":"《旧唐书》卷一百七十〈裴度列传〉","q":[]}],"211":[{"n":"愈头风","d":"陈琳檄：咏军府中有才能的文人。唐李白《江夏寄汉阳辅录事》：“君草陈琳檄，我书鲁连箭。”","s":"《三国志》卷二十一《魏书·王粲传》附《陈琳传》","q":[["孔璋旧檄家家有，叔度新歌处处听。","刘禹锡 令狐相公自天平移镇太原以诗申贺相公昔为并州从事"],["孔璋才素健，早晚檄书成。","刘长卿 行营酬吕侍御时尚书问罪襄阳军次汉东境上侍御以州邻寇贼复有水火迫于征税诗以见谕"]]},{"n":"建安诸子","d":"","s":"《昭明文选》卷五十二〈论二·典论论文〉","q":[]},{"n":"孔璋客绍","d":"","s":"《三国志》卷二十一〈魏书·王粲传·徐干陈琳阮瑀应玚刘桢〉","q":[]},{"n":"青萍","d":"","s":"《昭明文选》卷四十〈弹事笺奏记·笺·答东阿王笺〉","q":[["归耕地肺绝尘喧，匣里青萍未报恩。","储嗣宗 和顾非熊先生题茅山处士闲居"],["保宁帝业青萍在，投弃儒书绛帐空。","方干 王将军"]]},{"n":"徐陈","d":"","s":"《三国志》卷二十一〈魏书·王粲〉","q":[["清秋忽高兴，震藻若有神。曜曜趋宫廷，洸洸迈徐陈。","储光羲 敬酬陈掾亲家翁秋夜有赠"],["徐陈尝并作，枚马亦同时。夫君迈前侣，观国骋奇姿。","张说 酬崔光禄冬日述怀赠答"]]},{"n":"游睢","d":"","s":"《昭明文选》卷四十一、三国魏·陈孔璋（琳）《为曹洪与魏文帝书》","q":[["衣冠迷适越，藻绘忆游睢。","杜甫 夔府书怀四十韵"]]}],"212":[{"n":"八鸾锵","d":"","s":"《毛诗正义》卷十八之三〈大雅·荡之什·烝民〉","q":[]},{"n":"吉甫颂","d":"","s":"《诗经·大雅·嵩高·序》","q":[["还闻吉甫颂，不共郢歌俦。","张九龄 和姚令公从幸温汤喜雪"],["山公启事罢，山公启事罢。","张九龄 奉和吏部崔尚书"]]},{"n":"江汉美宣王","d":"","s":"《诗经·大雅·江汉·序》","q":[["吉甫裁诗歌盛业，一篇江汉美宣王。","杜牧 奉和白相公圣德和平致兹休运岁终功就合咏盛明呈上三相公长句四韵"]]},{"n":"木铎","d":"","s":"《周礼注疏》卷三〈天官冢宰·小宰〉","q":[["首路回竹符，分镳扬木铎。","张九龄 奉和圣制送十道采访使及朝集使"]]},{"n":"木鸡","d":"木鸡：喻呆笨发愣，或指修养极高。唐张枯《送韦正字[木片]贯赴制举》：“木鸡方备德，金马正求贤。”","s":"《庄子集释》卷七上〈外篇·达生〉","q":[]},{"n":"休道太原师","d":"","s":"《国语》卷一《周语上》","q":[["汉武惭夸朔方地，周宣休道太原师。","杜牧 今皇帝陛下一诏徵兵不日功集河湟诸郡次第归降臣获睹圣功辄献歌咏"]]}],"213":[{"n":"燃脐","d":"董卓脐：指恶人遭报应。唐刘禹锡《城西行》：“守吏能燃董卓脐，饥乌来觇桓玄目。”","s":"《后汉书》卷七十二〈董卓列传〉","q":[]},{"n":"然脐","d":"","s":"《后汉书》卷七十二《董卓传》","q":[["岂思鳞作簟，仍计腹为灯。","李商隐 洞庭鱼"],["屡断呼韩颈，曾然董卓脐。","李贺 送秦光禄北征"]]},{"n":"莽卓","d":"","s":"《汉书》卷九十九上〈王莽列传〉","q":[["不羞莽卓黄金印，却笑羲皇白接䍦。","韩偓 余卧疾深村闻一二郎官令称继使闽越笑余迂古潜于异乡闻之因成此篇"]]},{"n":"轻董卓","d":"","s":"《后汉书》卷七十四上《袁绍传》","q":[["小儒轻董卓，有识笑苻坚。","杜甫 寄岳州贾司马六丈巴州严八使君两阁老五十韵"]]},{"n":"袁董","d":"","s":"《后汉书》卷七十四上《袁绍传》","q":[["袁董非徒尔，师昭岂偶然。","韩偓 感事三十四韵"]]},{"n":"仲颖残忍","d":"","s":"《三国志》卷六《魏书·董卓传》","q":[["仲颖恣残忍，废兴良在躬。","卢照邻 咏史四首"]]}],"214":[{"n":"蔡姬","d":"","s":"《后汉书》卷八十四〈列女列传·董祀妻〉","q":[]},{"n":"蔡琰","d":"","s":"《后汉书》卷八十四〈列女传·董祀妻〉","q":[["文姬留此曲，千载一知音。","刘长卿 鄂渚听杜别驾弹胡琴"],["二妃烟尘外，凄凉转战归。胡笳悲蔡琰，汉使泣明妃。","李敬方 太和公主还宫"]]},{"n":"蔡琰胡笳","d":"","s":"《后汉书》卷八十四〈列女列传·董祀妻〉","q":[]},{"n":"蔡琰辨琴","d":"","s":"《艺文类聚》卷四十四","q":[["梁鸿五噫，蔡琰辨琴。","李瀚 蒙求"]]},{"n":"蔡琰请曹公","d":"","s":"《后汉书》卷八十四《列女传·董祀妻传》","q":[["多君同蔡琰，流泪请曹公。","李白 在浔阳非所寄内"]]},{"n":"断弦问文姬","d":"","s":"《艺文类聚》卷四十四〈乐部四·琴〉","q":[]}],"215":[{"n":"问奇字","d":"玄文覆酱：喻著作高深，无人能懂，或喻毫无价值。唐陆龟蒙《记事诗》：“骏骨正牵盐，玄文终覆瓿。”；问奇字：指从师受业或向人请教。唐韩愈《题张十八所居》：“端来问奇字，为我讲声行。”","s":"《汉书》卷八十七下《扬雄传下》","q":[["拟受太玄今不遇，可怜遗恨似侯芭。","皮日休 屣步访鲁望不遇"],["莫问盐车骏，谁看酱瓿玄。","陆龟蒙 袭美见题郊居十首因次韵酬之以伸荣谢"]]},{"n":"刘家异同","d":"","s":"《汉书》卷三十六《楚王元传》附《刘歆传》","q":[["闻道将雏向墨池，刘家还有异同词。","柳宗元 重赠二首"]]},{"n":"刘歆师儒","d":"","s":"《汉书》卷三十六《楚元王传》附《刘向传》","q":[["石建每闻宗谨孝，刘歆不敢衒师儒。","卢纶 送崔邠拾遗"]]},{"n":"向歆传业","d":"","s":"《汉书》卷三十六〈楚元王列传·刘向～〉928～","q":[]},{"n":"向歆父子","d":"","s":"《汉书》卷三十六〈楚元王列传·刘向～〉928～","q":[]},{"n":"歆向","d":"","s":"《文中子·天地》","q":[]}],"216":[{"n":"羲皇上","d":"羲皇人：指生活清闲自适。唐李白《戏赠郑溧阳》：“清风北窗下，自谓羲皇人。”","s":"《全上古三代秦汉三国六朝文·全晋文》卷一百十一〈陶潜·与子俨等书〉","q":[["腹中无一物，高话羲皇年。","储光羲 同王十三维偶然作十首之三"],["竹庭瓶水新，深称北窗人。","周贺 赠皎然上人（一本无皎字）"]]},{"n":"羲舒","d":"","s":"《楚辞补注》卷一〈离骚经·王逸序〉","q":[]},{"n":"羲车","d":"羲驭：指日或时光。唐许敬宗《奉和入潼关》：“羲驭循黄道，星陈引翠旗。”","s":"《楚辞补注》卷一〈离骚经·王逸序〉","q":[["蹉跎陶唐人，鞭挞日月久。","杜甫 上水遣怀"],["羲和驱日月，疾急不可恃。","韩愈 秋怀诗十一首之一"]]},{"n":"羲和","d":"","s":"《楚辞》卷一《离骚》","q":[["烟岛抟鹏亸双翅，羲和赫怒强总辔。","僧鸾 苦热行"],["羲和舒灵晖，倏忽西极通。","储光羲 登秦岭作时陷贼归国"]]},{"n":"羲娥","d":"","s":"《楚辞补注》卷一〈离骚经·王逸序〉","q":[]},{"n":"羲和湎淫","d":"","s":"《史记》卷二《夏本纪》","q":[["昔在羲和，湎浮不修。","顾况 上古之什补亡训传十三章燕于巢"]]}],"217":[{"n":"盘中钓","d":"","s":"《后汉书》卷八十二下《方术传·左慈传》","q":[["玉管时来凤，铜盘即钓鱼。","王维 赠东岳焦炼师"],["卖鲊市中何许人，钓鱼坐上谁家子。","韩翃 赠别华阴道士"]]},{"n":"割酒","d":"","s":"晋·葛洪《神仙传》卷五《左慈》","q":[["初平起石，左慈掷杯。","李瀚 蒙求"],["饮人聊割酒，送客乍分风。","王维 赠焦道士"]]},{"n":"入羊中","d":"","s":"《后汉书》卷八十二下〈方术列传·左慈〉","q":[["出游居鹤上，避祸入羊中。","李端 雪夜寻太白道士"]]},{"n":"元放掷杯","d":"","s":"《太平广记》卷十一〈神仙十一·左慈〉","q":[]},{"n":"左慈","d":"","s":"晋·葛洪《神仙传》卷五《左慈》","q":[["新传左慈诀，曾与右军鹅。","卢纶 寻贾尊师"]]},{"n":"左慈危","d":"","s":"《后汉书》卷八十二下〈方术列传下·左慈〉","q":[]}],"218":[{"n":"玄都观","d":"","s":"《本事诗·事感》","q":[["紫陌红尘拂面来，无人不道看花回。玄都观里桃千树，尽是刘郎去后栽。","刘禹锡 元和十一年自朗州召至京戏赠看花诸君子"],["百亩庭中半是苔，桃花净尽菜花开。种桃道士归何处，前度刘郎今又来。","刘禹锡 再游玄都观"]]},{"n":"断肠刺史","d":"","s":"《太平广记》卷一百七十七〈器量二·李绅〉","q":[]},{"n":"高山白早","d":"","s":"《全唐诗》卷三百六十〈苏州白舍人寄新诗有叹早白无儿之句因以赠之〉","q":[]},{"n":"梦得身捷","d":"","s":"《全唐诗》卷三百五十四〈抛球乐词〉","q":[]},{"n":"梦得文章","d":"","s":"《旧唐书》卷一百六十〈刘禹锡列传〉","q":[]},{"n":"梦得武陵","d":"","s":"《旧唐书》卷一百六十〈刘禹锡列传〉","q":[]}],"219":[{"n":"欧苏","d":"","s":"金王若虚《送吕鹏举赴举序》","q":[]},{"n":"六一词高","d":"","s":"《直斋书录解题》卷二十一〈歌词类〉","q":[]},{"n":"六一泉","d":"","s":"《苏轼文集》卷十九〈六一泉铭〉","q":[]},{"n":"六一先生","d":"","s":"《欧阳修全集·居士集》卷四十四〈六一居士传〉","q":[]},{"n":"心从天外归","d":"","s":"《青琐高议》卷九〈诗渊清格〉","q":[]},{"n":"醉翁吟","d":"","s":"《渑水燕谈录》卷七〈歌咏〉","q":[]}],"220":[{"n":"安车","d":"","s":"《后汉书》卷八十三《逸民传·严光传》","q":[["安车未至柴关外，片玉已藏坟土新。","李咸用 悼范摅处士"],["想就安车召，宁期负矢还。","李商隐 灵仙阁晚眺寄郓州韦评事"]]},{"n":"君房痴","d":"","s":"《后汉书》卷八十三〈逸民列传·严光〉","q":[]},{"n":"七里滩","d":"严陵钓：咏隐士。唐李白《独酌清溪江石上寄权昭夷》：“永愿坐此石，长垂严陵钓。”","s":"《后汉书》卷八十三〈逸民列传·严光〉","q":[["知君济世有长策，莫问沧浪隐钓矶。","刘沧 赠颛琐山人"],["栖迟惯得沧浪思，云阁还应梦钓矶。","刘沧 题王校书山斋"]]},{"n":"严子","d":"","s":"《后汉书》卷八十三〈逸民列传·严光〉","q":[["严陵七里滩，携手同所适。","刘长卿 京口怀洛阳旧居兼寄广陵二三知己"],["门前七里濑，早晚子陵过。","刘长卿 对酒寄严维"]]},{"n":"客星","d":"","s":"《艺文类聚》卷一〈天部上·星〉","q":[["偶作客星侵帝座，却应虚薄是严光。","司空图 狂题十八首"],["醉头倒向芦花里，却笑无端犯客星。","崔道融 钓鱼"]]},{"n":"狂奴故态","d":"狂奴：喻傲世之隐者。唐皮日休《钓矾》：“狂奴卧此多，所以踏帝腹。”；狂奴故态：指人行为狂傲。唐陆龟蒙《严光钓台》：“不是狂奴为故态，仲华争得黑头公。”","s":"《后汉书》卷八十三〈逸民列传·严光〉","q":[]}],"221":[{"n":"钧天乐","d":"钧天：喻指美乐。唐李世民《春日玄武门宴群臣》：“娱宾歌湛露，广乐奏钧天。”；钧天梦：咏梦境。宋杨亿《直夜》：“负郭春耕废，钧天晓梦长。”","s":"《史记》卷四十三〈赵世家〉","q":[["传闻帝乐奏钧天，傥冀微躬备五弦。","司马逸客 雅琴篇"],["献图开益地，张乐奏钧天。","张说 奉和圣制暇日与兄弟同游兴庆宫作应制"]]},{"n":"腹背毛","d":"","s":"《说苑》卷八《尊贤》","q":[["他时讵有盐梅味，今日犹疑腹背毛。","李咸用 赠友弟"]]},{"n":"邯郸鸠","d":"","s":"《列子·说符》","q":[["齐王不忍觳觫牛，简子亦放邯郸鸠。二子得意犹念此，况我万里为孤囚。","柳宗元 放鹧鸪词"]]},{"n":"茧丝堡障","d":"","s":"《国语》卷十五〈晋语九·赵简子以晋阳为保鄣〉","q":[]},{"n":"鸣玉宴","d":"","s":"《国语》卷十八《楚语下》","q":[["今日见银牌，今夜鸣玉宴。","李贺 河阳歌"]]},{"n":"射熊","d":"","s":"《史记》卷四十三〈赵世家〉","q":[["射熊今梦帝，秤象问何人。","王维 恭懿太子挽歌五首之三"]]}],"222":[{"n":"曹参次位","d":"","s":"《史记》卷五十三〈萧相国世家〉","q":[]},{"n":"曹参酒","d":"曹参酒：指丞相或官吏无为而治。唐李商隐《五百述德抒情诗一百四十韵》：“后饮曹参酒，先和傅说羹。”","s":"《史记》卷五十四《曹相国世家》","q":[["后饮曹参酒，先和傅说羹。","李商隐 五首述德抒情诗一首四十韵献上杜七兄仆射相公"],["西伯最怜耕让畔，曹参空爱酒盈樽。","贯休 大蜀皇帝潜龙日述圣德诗五首之五"]]},{"n":"曹参趣装","d":"","s":"《史记》卷五十四《曹相国世家》","q":[["于公高门，曹参趣装。","李瀚 蒙求"]]},{"n":"魏勃","d":"","s":"《史记》卷五十二《齐悼惠王世家》","q":[["心期玉帐亲台位，魏勃因君说姓名。","杨巨源 送陈判官罢举赴江外"]]},{"n":"萧曹","d":"","s":"《汉书》卷三十九《萧何曹参传》","q":[["宠荣连雨露，先后比萧曹。","姚合 和郑相演杨尚书蜀中唱和诗"],["萧曹曾作沛中吏，攀龙附凤当有时。","李白 猛虎行"]]}],"223":[{"n":"济巨川","d":"济巨川：喻指宰相。唐沈＃期《哭苏眉州崔司业二公》：“崔昔挥宸翰，苏尝济巨川。”","s":"《尚书·商书·说命上》","q":[["适会傅岩人，虚舟济川时。","独孤及 送陈兼应辟兼寄高适贾至"],["宇宙既焜耀，崇德济巨川。","储光羲 奉别长史庾公太守徐公应召"]]},{"n":"调味","d":"和羹：借指梅花。徐贵《梅花》：“结实和羹知有日，肯随羌笛落天涯？”《尚书·商书·说命下》王曰：‘来汝说…著作酒，若作和羹，尔唯盐梅。”又喻指宰相。唐刘禹锡《和汴州令狐相公到镇改月偶书所怀》：“受赈新梁苑，和羹旧傅严。”","s":"《尚书》卷十〈商书·说命下〉","q":[["龙衮期重补，梅羹伫再和。","令狐楚 将赴洛下旅次汉南献上相公二十兄言怀八韵"],["此日临风飘羽卫，他年嘉约指盐梅。","元稹 赠毛仙翁"]]},{"n":"作霖雨","d":"","s":"《尚书·商书·说命上》","q":[["寰中不用忧天旱，霖雨看看属傅岩。","周朴 喜贺拔先辈衡阳除正字"],["眼看白笔为霖雨，肯使红鳞便曝腮。","周朴 客州赁居寄萧郎中"]]},{"n":"曲蘖","d":"","s":"《尚书·商书·说命下》","q":[["为君天下酒，曲糵将用时。","岑参 尹相公京兆府中棠树降甘露诗"]]},{"n":"为霖雨","d":"","s":"《尚书》卷十〈商书·说命上〉","q":[]}],"224":[{"n":"苏门啸","d":"","s":"《三国志》卷二十一〈魏书·王粲传·阮籍〉","q":[["尝希苏门啸，讵厌巴树猿。","元稹 酬独孤二十六送归通州"],["风泉有清音，何必苏门啸。","孟浩然 题终南翠微寺空上人房"]]},{"n":"孙登长啸","d":"孙登长啸：咏啸傲。唐王维《偶然作六首》之三：“孙登长啸台，松竹有遗处。”","s":"《三国志》卷二十一《魏书·王粲传》附《嵇康传》","q":[["诗客爱时景，道人话升腾。笑这各有趣，悠哉古孙登。","元稹 刘氏馆集隐客归和子元及之子蒙晦之"],["处世苟无闷，佯狂道非弘。无言被人觉，予亦笑孙登。","元稹 秋堂夕"]]},{"n":"嵇康寡识","d":"","s":"《三国志》卷二十一《魏书·王粲传》附《嵇康传》","q":[["嵇康殊寡识，张翰独知终。","王昌龄 赵十四兄见访"]]},{"n":"愧孙登","d":"","s":"《世说新语》下卷上《栖逸》","q":[["淮王门有客，终不愧孙登。","杜甫 赠特进汝阳王二十韵"]]},{"n":"一弦","d":"","s":"《晋书》卷九十四〈隐逸列传·孙登〉","q":[["不如从四皓，丘中鸣一弦。","骆宾王 秋日山行简梁大官"]]}],"225":[{"n":"咄咄书空","d":"咄咄怪事：指惊奇或忧疑。宋苏轼《杜介熙熙堂》：“咄咄何曾书怪事，熙熙长觉似春台。”","s":"《晋书》卷七十七〈殷浩列传〉","q":[["自悲咄咄感，变作烦恼翁。","孟郊 劝善吟"],["书空翘足卧，避险侧身行。","方干 山中寄吴磻十韵"]]},{"n":"庾楼","d":"庾公楼：指风流儒雅之场所。唐卢纶《送申居正字往湖南迎亲……》：“坦腹定逢潘令罪，上楼应伴庚公闲。”","s":"《世说新语笺疏》下卷上〈容止〉","q":[["遥想高楼上，唯君对庾公。","司空曙 龙池寺望月寄韦使君阎别驾"],["庾公明月吟连曙，谢守青山看入秋。","吴融 离霅溪感事献郑员外"]]},{"n":"江逌爇鸡","d":"","s":"《晋书》卷八十三《江逌传》","q":[["田单火牛，江逌爇鸡。","李瀚 蒙求"]]},{"n":"殷浩","d":"","s":"《晋书》卷七十七〈殷浩列传〉","q":[["望月逢殷浩，缘江送范云。","李端 送雍郢州"],["已作相如投赋计，还凭殷浩寄书回。","杜牧 江上逢友人"]]},{"n":"庾征西","d":"","s":"《晋书》卷七十三《庾亮传》","q":[["不遇庾征西，云谁展怀抱。","萧颖士 仰答韦司业垂访五首之三"]]}],"226":[{"n":"槐府","d":"","s":"《周礼注疏》卷三十五〈秋官司寇·朝士〉","q":[]},{"n":"王氏三槐","d":"","s":"《周礼注疏》卷三十五〈秋官司寇·朝士〉","q":[]},{"n":"三槐堂","d":"","s":"《苏轼文集》卷十九〈三槐堂铭〉","q":[]},{"n":"王文正","d":"","s":"《五朝名臣言行录》卷二〈丞相王文正公（旦）〉","q":[]},{"n":"曾旦","d":"","s":"《宾退录》卷三","q":[]}],"227":[{"n":"偷光","d":"借壁光：咏勤学。清钱谦益《虫诗十二首·灯蛾》：“未许因人热，那能借壁光。”","s":"《西京杂记》卷二","q":[["惜日看圭短，偷光恨壁坚。","元稹 献荥阳公诗五十韵"],["览卷试穿邻舍壁，明灯何惜借馀光。","岑参 秋夕读书幽兴献兵部李侍郎"]]},{"n":"解颐","d":"","s":"《汉书》卷八十一《匡衡传》","q":[["讼息但长啸，宾来或解颐。","李白 赠徐安宜"],["讨论实解颐，操割纷应手。","杜甫 奉赠李八丈判官"]]},{"n":"匡鼎","d":"","s":"《汉书》卷八十一《匡衡传》","q":[["恳谏留匡鼎，诸儒引服虔。","杜甫 秋日夔府咏怀奉寄郑监李宾客一百韵（郑审官秘书少监。时谪贬江陵。李之芳留吐蕃归。拜礼部尚书。改太子宾客。）"]]},{"n":"匡衡抗疏","d":"","s":"《汉书》卷八十一《匡衡传》","q":[["贾谊昔流恸，匡衡常引经。","杜甫 同元使君舂陵行（有序）"],["匡衡抗疏功名薄，刘向传经心事违。","杜甫 秋兴八首"]]},{"n":"匡汲俄宠辱","d":"","s":"《汉书》卷八十一《匡衡传》","q":[["匡汲俄宠辱，卫霍竟哀荣。","杜甫 八哀诗（并序）赠左仆射郑国公严公武"]]}],"228":[{"n":"满身香","d":"荀令香：喻奇异香味，或喻人风仪高雅。唐白居易《奉和裴令公新成午桥庄绿野堂即事》：“花妒谢家妓，兰偷荀令香。”；荀炉：喻指香炉。宋李维《霜月》：“荀炉残更换，湘瑟罢仍调。”","s":"《艺文类聚》卷七十","q":[["香闻荀令宅，艳入孝王家。","刘禹锡 和令狐相公郡斋对紫薇花"],["荀令园林好，山公游赏频。","刘禹锡 酬令狐相公亲仁郭家花下即事见寄"]]},{"n":"文若","d":"","s":"《后汉书》卷七十〈荀彧列传〉","q":[["文若为全德，留侯是重名。","李嘉祐 故燕国相公挽歌二首"]]},{"n":"荀令","d":"","s":"《三国志》卷十〈魏书·荀彧传〉","q":[["荀令歌钟北里亭，翠娥红粉敞云屏。","杨巨源 观妓人入道二首"],["荀令昔居此，故巢留越禽。","武元衡 四川使宅有韦令公时孔雀存焉暇日与诸公同玩座中兼故府宾妓兴嗟久之因赋此诗用广其义"]]},{"n":"荀香","d":"","s":"《艺文类聚》卷七十〈服饰部下·香炉〉","q":[]},{"n":"荀氏风流","d":"","s":"《三国志》卷十《魏书·荀彧传》","q":[["勋业耿家盛，风流荀氏均。","李端 送路司谏侍从叔赴洪州"],["荀氏风流远，胡家清白齐。","皇甫冉 送李万州赴饶州觐省"]]}],"229":[{"n":"报爰丝","d":"","s":"《史记》卷一○一《袁盎列传》","q":[["莫道精灵无伯有，寻闻任侠报爰丝。","吴融 偶题"]]},{"n":"六飞","d":"","s":"《汉书》卷四十九〈爰盎晁错列传·爰盎〉","q":[["钟鼓旌旗引六飞，玉皇初著画龙衣。","司马扎 观郊礼"],["六飞南幸芙蓉苑，十里飘香入夹城。","杜牧 长安杂题长句六首"]]},{"n":"日饮亡何","d":"日饮无何：指每日饮酒，不问正事。宋苏轼《赵既见和复次韵答之》：“寒酸可笑分一斗，日饮无何足袁盎。”","s":"《汉书》卷四十九〈爰盎晁错列传·爰盎〉","q":[]},{"n":"袁盎却座","d":"","s":"《史记》卷一○一《袁盎列传》","q":[["袁盎却座，卫瓘抚床。","李瀚 蒙求"]]},{"n":"袁丝揽辔","d":"","s":"《史记》卷一○一《袁盎列传》","q":[["辔待袁丝揽，书期蜀客操。","李德裕 述梦四十韵"]]}],"230":[{"n":"参卿","d":"","s":"《晋书》卷五十六《孙楚传》","q":[["参卿休坐幄，荡子不还乡。","杜甫 冬晚送长孙渐舍人归州"],["何补参卿事，欢娱到薄躬。","杜甫 陪郑公秋晚北池临眺"]]},{"n":"枕流漱石","d":"漱石：咏隐居生活。宋苏轼《次韵孙巨源寄涟水李盛二著作》之二：“漱石先生难可意，啮毡校尉久无明。”","s":"《世说新语笺疏》下卷下〈排调〉","q":[]},{"n":"零雨","d":"","s":"《昭明文选》卷二十晋·孙子荆（楚）《征西官属送于陟阳候作诗》","q":[["骊山浮云散，灞岸零雨夕。","刘舟 送萧颍士赴东府得适字"],["断烟伤别望，零雨送离杯。","徐坚 钱许州宋司马赴任"]]},{"n":"孙楚","d":"","s":"《晋书》卷五十六〈孙楚列传〉","q":[["陆机初入洛，孙楚又游吴。","储嗣宗 早春怀薛公裕"],["入幕知孙楚，披襟得郑侨。","杜甫 奉赠卢五丈参谋"]]},{"n":"子荆","d":"","s":"《晋书》卷五十六〈孙楚列传〉","q":[["记室得何逊，韬钤延子荆。","杜甫 八哀诗赠左仆射郑国公严公武"],["孙子荆家思有馀，元戎曾荐入公车。","皮日休 孙发百篇将游天台请诗赠行因以送之"]]}],"231":[{"n":"报束长生","d":"","s":"《晋书》卷五十一《束皙传》","q":[["祗怪闾阎喧鼓吹，邑人同报束长生。","李商隐 所居永乐县久旱县宰祈祷得雨因赋诗"]]},{"n":"补亡","d":"","s":"《昭明文选》卷十九晋·束广微（皙）《补亡诗六首》","q":[["那知冥寞客，不有补亡篇。","孟郊 李少府厅吊李元宾遗字"],["笔下成释憾，卷中同补亡。","白居易 洛中偶作"]]},{"n":"采兰","d":"","s":"《昭明文选》卷十九续〈诗甲·补亡·补亡诗六首〉","q":[["如何飘梗处，又到采兰时。","李端 下第上薛侍郎"],["采兰花萼聚，就日雁行联。","钱起 李四劝为尉氏尉李七勉为开封尉"]]},{"n":"池上杯","d":"","s":"《续齐谐记》","q":[["未展山阳会，空留池上杯。","李峤 酬（一作和）杜五弟晴朝独坐见赠"],["流觞想兰亭，捧剑传金人。","李适 三日书怀因示百僚"]]},{"n":"飞觞临水","d":"","s":"《昭明文选》卷二十〈诗甲·公宴·应诏宴曲水作诗〉","q":[]}],"232":[{"n":"无长物","d":"","s":"《世说新语笺疏》上卷上〈德行〉","q":[["此外无长物，于我有若亡。","白居易 寄张十八"],["但恐人间为长物，不如林下作遗民。","白居易 狂吟七言十四韵"]]},{"n":"鹤氅","d":"","s":"《世说新语》下卷上《企羡》","q":[["披缁学佛应无分，鹤氅谈空亦不妨。","徐夤 山寺寓居"],["肯羡鱼须美，长誇鹤氅轻。","李昭象 赴举出山留寄山居郑参军"]]},{"n":"浇肠","d":"浇块磊：指借酒消愁。金元好问《送钦叔内翰并寄刘达卿郎中白文举编修五首》之三：“我有一樽酒，浇君块磊胸。”","s":"《世说新语笺疏》下卷上〈任诞〉","q":[["数杯浇肠虽暂醉，皎皎万虑醒还新。","韩愈 感春四首"]]},{"n":"王恭柳","d":"王恭柳：指人物品貌出众。唐李商隐《行至金中驿寄兴元渤海尚书》：“诸生个个王恭柳，从事人人庚杲莲。”","s":"《晋书》卷八十四《王恭传》","q":[["三五月明临阚泽，百千人众看王恭。","徐夤 尚书荣拜恩命夤疾中辄课恶诗二首以申攀赞"],["诸生个个王恭柳，从事人人庾杲莲。","李商隐 行至金牛驿寄兴元渤海尚书"]]},{"n":"孝伯痛饮","d":"","s":"《世说新语》下卷上《任诞》","q":[["刘惔倾酿，孝伯痛饮。","李瀚 蒙求"]]}],"233":[{"n":"食无鱼","d":"冯谖有鱼：指贤士怀才未遇，或反指受器重。宋苏轼《次韵周开祖长官见寄》：“犀首正缘无事饮，冯援应为有鱼留。”","s":"《战国策》卷十一〈齐四·齐人有冯谖者〉","q":[["不知弹铗客，何处感新恩。","于武陵 过侯王故第"],["此来多愧食鱼心，东阁将辞强一吟。","刘沧 入关留别主人"]]},{"n":"营三窟","d":"兔藏三窟：喻指谋求避祸之道。唐杜甫《见王监兵马使说近山有白黑二鹰赋诗二首》之一：“鹏碍九天须却避，兔藏三窟莫深忧。”","s":"《战国策》卷十一〈齐四·齐人有冯谖者〉","q":[["世事徒三窟，儿童且一经。","唐彦谦 梅亭"],["孟尝习狡兔，三窟赖冯谖。","李白 送薛九被谗去鲁"]]},{"n":"狡穴","d":"","s":"《战国策》卷十一〈齐策四·齐人有冯谖者〉","q":[]},{"n":"蒯缑客","d":"","s":"《史记》卷七十五〈孟尝君列传〉","q":[]},{"n":"市义","d":"市义：喻有雄才远见，或喻收买民心。唐刘禹锡《许给事见示哭工部刘尚书诗因命同作》。“总戎宽得众，市义贵能贫。”","s":"《战国策》卷十一《齐策四》","q":[["总戎宽得众，市义贵能贫。","刘禹锡 许给事见示哭工部刘尚书诗因命同作（从叔望山河间）"],["谁能买仁义，令子无寒饥。","姚合 送张宗原"]]}],"234":[{"n":"曹卿礼公子","d":"","s":"《春秋左传·僖公二十三年》","q":[["曹卿礼公子，楚媪馈王孙。","张说 南中别王陵成崇"]]},{"n":"绵上隐","d":"","s":"《春秋左传·僖公二十四年》","q":[["欲追绵上隐，况近子平村。","李德裕 近于伊川卜山居将命者画图而至欣然有感聊赋此诗兼寄上浙东元相公大夫使求青田胎化鹤"]]},{"n":"赏从","d":"","s":"《春秋左传·僖公二十四年》","q":[["世祖修高庙，文公赏从臣。","杜甫 寄张二十山人彪三十韵"],["赏从频峨冕，殊私再直庐。","杜甫 秋日荆南送石首薛明府辞满告别奉寄薛尚书颂德叙怀斐然之作三十韵"]]},{"n":"一国三公","d":"","s":"《春秋左传正义》卷十二〈僖公·传五年〉","q":[["一国实三公，万人欲为鱼。","杜甫 草堂"]]},{"n":"子犯有言","d":"","s":"《春秋左传·僖公二十四年》","q":[["子犯亦有言，臣犹自知之。","韩愈 除官赴阙至江州寄鄂岳李大夫"]]}],"235":[{"n":"惭儿子","d":"","s":"《后汉书》卷八十四〈列女列传·王霸妻〉","q":[]},{"n":"滹沱凝合","d":"","s":"《后汉书》卷二十〈铫期王霸祭遵列传·王霸〉","q":[]},{"n":"王霸冰合","d":"","s":"《后汉书》卷二十〈铫期王霸祭遵列传·王霸〉","q":[["广利泉涌，王霸冰合。","李瀚 蒙求"]]},{"n":"王霸重朝章","d":"","s":"《后汉书》卷八十三〈逸民列传·王霸〉","q":[["韩康虽复在人间，王霸终思隐岩窦。","李颀 答高三十五留别便呈于十一"],["管宁存祭礼，王霸重朝章。","王绩 赠李征君大寿"]]},{"n":"王霸揶揄","d":"","s":"《后汉书》卷二十〈铫期王霸祭遵列传·王霸〉","q":[["镏惔虚访觅，王霸竟揶揄。","温庭筠 病中书怀呈友人"]]}],"236":[{"n":"苍舒","d":"","s":"《春秋左传·文公十八年》","q":[["苍舒留帝宠，子晋有仙才。","王维 恭懿太子挽歌五首之四"]]},{"n":"长剑匣中鸣","d":"","s":"《太平御览》卷三百四十四〈兵部七十五·剑下〉","q":[["讵怜冲斗气，犹向匣中鸣。","骆宾王 和李明府"],["边马枥上惊，雄剑匣中鸣。","李益 夜发军中"]]},{"n":"六英","d":"","s":"《淮南子》卷十一〈齐俗训〉","q":[["早忝登三署，曾闻奏六英。","刘禹锡 历阳书事七十韵"]]},{"n":"顼冥收威","d":"","s":"《礼记注疏》卷十七〈月令〉","q":[["电光䃸磹赪目䁔，顼冥收威避玄根。","韩愈 陆军山火和皇甫湜用其韵"]]},{"n":"颛顼","d":"","s":"《礼记·月令》","q":[["颛顼时初谢，句芒令复陈。","张濯 迎春东郊"],["羲和流德泽，颛顼愧倚薄。","杜甫 西阁曝日"]]}],"237":[{"n":"防梭","d":"","s":"《世说新语》中卷下《赏誉》","q":[["防梭齿虽在，乞帽鬓惭斑。","段成式 和周繇见嘲"],["谢鲲吟未废，张硕梦堪思。","韩偓 春闷偶成十二韵"]]},{"n":"娇送飞梭","d":"","s":"《世说新语笺疏》中卷下〈赏誉〉","q":[]},{"n":"一丘一壑","d":"","s":"《世说新语笺疏》中卷下〈品藻〉","q":[]},{"n":"幼舆高志","d":"","s":"《晋书》卷四十九〈谢鲲列传〉","q":[]},{"n":"元规端委，幼舆邱壑","d":"","s":"《世说新语笺疏》中卷下〈品藻〉","q":[]}],"238":[{"n":"燕霜","d":"燕霜：指冤狱。唐李白《送张秀才谒高中丞》：“我无燕霜感，玉石俱烧焚。”","s":"《后汉书》卷五十七〈杜栾刘李刘谢列传·刘瑜〉","q":[["燕臣昔恸哭，五月飞秋霜。","李白 古风"],["我无燕霜感，玉石俱烧焚。","李白 送张秀才谒高中丞"]]},{"n":"邹律","d":"","s":"《全上古三代秦汉三国六朝文·全汉文》卷三十八〈刘向·别录〉","q":[]},{"n":"谈天口","d":"","s":"《史记》卷七十四〈孟子荀卿列传〉","q":[["枚藻清词律，邹谈耀辩锋。","李峤 夏晚九成宫呈同僚"],["谈天信浩荡，说剑纷纵横。","李白 赠韦秘书子春二首之一"]]},{"n":"邹氏律","d":"","s":"《列子》卷五《汤问》","q":[["邹家不用偏吹律，到底荣枯也自均。","李山甫 秋"],["寒谷谩劳邹氏律，长天独遇宋都风。","杨知至 覆落后呈同年"]]},{"n":"邹子说九瀛","d":"","s":"《史记》卷七十四《孟子列传》附《邹衍传》","q":[["邹子何寥廓，漫说九瀛垂。","陈子昂 蓟丘览古赠卢居士藏用七首邹衍"]]}],"239":[{"n":"贺家湖","d":"","s":"《新唐书》卷一百九十六〈隐逸列传·贺知章〉","q":[]},{"n":"风流贺季真","d":"","s":"《全唐诗》卷一百八十二〈对酒忆贺监二首〉","q":[]},{"n":"贺老门前湖水","d":"","s":"《全唐诗》卷一百一十二〈回乡偶书二首〉","q":[]},{"n":"谪仙人","d":"","s":"《全唐诗》卷一百八十二〈对酒忆贺监二首〉","q":[]},{"n":"四明狂客","d":"","s":"《旧唐书》卷一百九十中〈文苑列传中·贺知章〉","q":[]}],"240":[{"n":"印如斗","d":"","s":"《世说新语笺疏》下卷下〈尤悔〉","q":[["色阻金印大，兴含沧浪清。","杜甫 同元使君舂陵行"],["匈奴破尽人看归，金印酬功如斗大。","韩翃 送孙泼赴云中"]]},{"n":"击唾壶","d":"缺唾壶：指击节咏叹，或喻壮怀激烈。宋苏轼《次韵刘景文见寄》：“莫因老骥思千里，醉后哀歌缺唾壶。”","s":"《世说新语笺疏》中卷下〈豪爽〉","q":[["烈士击玉壶，壮心惜暮年。","李白 玉壶吟"],["犹酌甘泉歌，歌长击樽破。","杜甫 屏迹三首之三"]]},{"n":"石崇香枣","d":"","s":"《太平御览》卷九六五","q":[["长筹未必输孙皓，香枣何劳问石崇。","李商隐 药转"]]},{"n":"王敦倾室","d":"","s":"《晋书》卷九十八《王敦传》","q":[["王敦倾室，纪瞻出妓。","李瀚 蒙求"]]},{"n":"正始遗音","d":"","s":"《世说新语笺疏》中卷下〈赏誉〉","q":[]}],"241":[{"n":"祖生鞭","d":"祖生鞭：指争先立功，多用作劝勉之词。唐李白《赠宣城宇文太守兼呈崔侍御》：“多逢剿绝儿，先着祖生鞭。”","s":"《世说新语》中卷下《赏誉》","q":[["戴冯遥避席，祖逖后施鞭。","元稹 献荥阳公诗五十韵"],["蹇步徒相望，先鞭不可亲。","司空曙 送柳震归蜀"]]},{"n":"过江誓水","d":"","s":"《晋书》卷六十二《祖逖传》","q":[["感遇明主恩，颇高祖逖言。过江誓流水，志在清中原。","李白 南奔书怀（一作自丹阳南奔道中作。此诗萧士赟云是伪作。"]]},{"n":"闻鸡起舞","d":"闻鸡起舞：指少年立志。清蒲松龄《夜坐悲歌》：“半夜闻鸡欲起舞，把酒问天天不语。”","s":"《晋书》卷六十二〈祖逖列传〉","q":[["楚客早闻歌凤德，刘琨休更舞鸡声。","吴融 萧县道中"],["刘琨与祖逖，起舞鸡鸣晨。虽有匡济心，终为乐祸人。","李白 避地司空原言怀"]]},{"n":"刘琨听鸡","d":"","s":"《晋书》卷六十二〈祖逖列传〉","q":[]},{"n":"士稚","d":"","s":"《晋书》卷六十二〈祖逖列传〉","q":[]}],"242":[{"n":"杯蛇","d":"樽中弩：喻无端多疑，自相惊扰。唐杜甫《风疾舟中伏枕书怀三十六韵》：“疑惑樽中弩，淹留冠上簪。”","s":"《晋书》卷四十三〈乐广列传〉","q":[["送客屡闻帘外鹊，销愁已辨酒中蛇。","包佶 答窦拾遗卧病见寄"],["撒枕销行蚁，移杯失画蛇。","李端 酬秘书元丞郊园卧疾见寄"]]},{"n":"冰翁","d":"","s":"《世说新语笺疏》上卷上〈言语〉","q":[]},{"n":"披云雾","d":"乐广披云：喻人风神朗澈，或借用指云开天晴。唐张聿《圆灵水镜》：“乐广披云日，山涛卷雾年。”","s":"《世说新语笺疏》中卷下〈赏誉〉","q":[["乐广披云日，山涛卷雾年。","张聿 圆灵水镜"],["披云自有镜，从此照仙台。","张谔 赠吏部孙员外济"]]},{"n":"乐广","d":"","s":"《晋书》卷四十三〈乐广列传〉","q":[["晋臣多乐广，汉主识冯唐。","武元衡 酬陆员外歙州许员外郢州二使君"],["方谢公超步，终从彦辅游。","苏味道 咏雾"]]},{"n":"彦辅怜卫叔","d":"","s":"《晋书》卷三十六《卫瓘传》附《卫玠传》","q":[["秦家重萧史，彦辅怜卫叔。","白居易 和梦游春一百韵"]]}],"243":[{"n":"神仙侣","d":"仙侣同舟：喻指知己，或指沽名人的光。唐杜甫《秋兴》之八：“佳人拾翠春相问，仙侣同舟晚更移。”","s":"《后汉书》卷六十八《郭太传》","q":[["山宜姑射貌，江泛李膺舟。","于瑰 和绵州于中丞登越王楼作二首之一"],["物外须仙侣，人间要使君。","姚合 寄绛州李使君"]]},{"n":"人如玉","d":"","s":"《毛诗正义》卷十一之一〈小雅·鸿雁之什·白驹〉","q":[["旧交封宿草，衰鬓重生刍。","李绅 趋翰苑遭诬搆四十六韵"],["停觞一摇笔，聊寄生刍吟。","李群玉 将离澧浦置酒野屿奉怀沈正字昆弟三人联登高第"]]},{"n":"折角巾","d":"","s":"《后汉书》卷六十八〈郭符许列传·郭太〉","q":[["唯有角巾沾雨至，手持残菊向西招。","李益 九月十日雨中过张伯佳期柳镇未至以诗招之"],["方领蕙带折角巾，杜若已老兰苕春。","李贺 南园"]]},{"n":"郭泰碑铭","d":"郭泰碑铭：称颂人生前品行。唐罗隐《围城偶作》：“自从郭泰碑铭后，只见黄金不见人。”","s":"《后汉书》卷六十八〈郭符许列传·郭太〉","q":[["会葬知元伯，看碑识蔡邕。","张说 李工部挽歌三首"],["自从郭泰碑铭后，只见黄金不见文。","罗隐 圉城偶作"]]},{"n":"题殄瘁诗","d":"","s":"《后汉书》卷六十八《郭太传》","q":[["何处躬耕者，犹题殄瘁诗。","杜牧 和野人殷潜之题筹笔驿十四韵"]]}],"244":[{"n":"灯花喜","d":"","s":"旧题晋·葛洪《西京杂记》卷三","q":[["灯花何太喜，酒绿正相亲。","杜甫 独酌成诗"]]},{"n":"樊哙排闼","d":"","s":"《史记》卷九十五《樊哙列传》","q":[["樊哙排闼，辛毗引裾。","李瀚 蒙求"]]},{"n":"樊哙市井","d":"","s":"《史记》卷九十五《樊哙列传》","q":[["屠狗兴贩缯，突起定倾危。","李商隐 井泥四十韵"],["樊哙市井徒，萧何刀笔吏。一朝时运会，千古传名谥。","李密 淮阳感怀"]]},{"n":"鸿门","d":"","s":"《史记》卷七《项羽本纪》","q":[["佐汉解鸿门，生唐为后身。","李白 赠张相镐二首之一"]]},{"n":"屠沽乞食为僚宰","d":"","s":"《史记》卷九十五〈樊郦滕灌列传·樊哙〉","q":[]}],"245":[{"n":"一鸣惊人","d":"冲天翼：喻指贤士待时而动。唐贯休《遇叶进土》：“自愧龙钟人，见此冲天翼、”","s":"《韩非子》卷七〈喻老〉","q":[["遇此枝叶覆，夙举冀冲天。","李岑 东峰亭各赋一物得栖烟鸟"],["子既屈一鸣，余固宜三刖。","杜牧 池州送孟迟先辈"]]},{"n":"淳于炙毂","d":"","s":"《史记》卷七十四《孟子荀卿列传》","q":[["淳于炙毂，彦国吐屑。","李瀚 蒙求"]]},{"n":"鹄已去","d":"","s":"《史记》卷一二六《滑稽列传》","q":[["水上鹄已去，亭中鸟又鸣。词因使楚重，名为救齐成。","柳宗元 善谑驿和刘梦得酹淳于先生"]]},{"n":"华堂烛暗送客","d":"","s":"《史记》卷一百二十六〈滑稽列传〉","q":[]},{"n":"伯乐顾","d":"伯乐顾：喻指受名家赏识而出名。唐张九龄《南还以诗代书赠京师旧僚》：“上惭伯乐顾，中负叔牙知。”","s":"《战国策》卷三十〈燕二·苏代为燕说齐〉","q":[["一顾恩深荷道安，独垂双泪下层峦。","刘沧 龙门留别道友"],["一顾生鸿羽，再言将鹤翩。","孟郊 寄陕府邓给事"]]}],"246":[{"n":"贡禹冠","d":"贡公喜：庆贺他人做官。唐杜甫《奉赠韦左丞丈二十二韵》：“窃效贡公喜，难甘原宪贫。”","s":"《汉书》卷七十二《王贡两龚鲍传》","q":[["感激遂弹冠，安能守固穷。","孟浩然 书怀贻京邑同好"],["别有弹冠士，希君无见遗。","岑参 过梁州奉赠张尚书大夫公"]]},{"n":"辞王吉","d":"","s":"《汉书》卷七十二《王吉传》","q":[["忽辞王吉去，为是秋胡死。","戴叔伦 去归怨"]]},{"n":"王吉","d":"","s":"《太平御览》卷九二○","q":[["惊鸣雕辇侧，王吉自相知。","杨师道 应诏咏巢鸟"]]},{"n":"王吉归乡","d":"","s":"《汉书》卷七十二〈王贡两龚鲍列传·王吉〉","q":[["王吉归乡里，甘心长闭关。","李华 杂诗六首"]]},{"n":"王阳囊衣","d":"","s":"《汉书》卷七十二《王吉传》","q":[["王阳囊衣，马援薏苡。","李瀚 蒙求"]]}],"247":[{"n":"菊水","d":"","s":"《后汉书》卷四十四〈邓张徐张胡列传·胡广〉","q":[]},{"n":"胡广","d":"","s":"《后汉书》卷四十四《胡广传》","q":[["宠赠追胡广，亲临比贺循。","苏颋 赠司徒豆卢府君挽词"]]},{"n":"胡广惭","d":"","s":"《后汉书》卷六十三〈李杜列传·李固〉","q":[["孔光尊董贤，胡广惭李固。","李华 杂诗六首"]]},{"n":"胡广补阙","d":"","s":"《后汉书》卷四十四《胡广传》","q":[["胡广补阙，袁安倚赖。","李瀚 蒙求"]]},{"n":"万事不理","d":"","s":"《后汉书》卷四十四〈邓张徐张胡列传·胡广〉","q":[]}],"248":[{"n":"许都讲","d":"","s":"《世说新语》上卷上《言语》","q":[["寄谢山阴许都讲，昨来频得远公书。","李端 忆友怀野寺旧居"],["空忝许询辈，难酬支遁词。","杜甫 巳上人茅斋"]]},{"n":"许询胜具","d":"","s":"《世说新语》下卷上《栖逸》","q":[["翟汤隐操，许询胜具。","李瀚 蒙求"]]},{"n":"许掾","d":"","s":"《世说新语》中卷下《品藻》","q":[["心似蒙庄游物外，官惭许掾在人间。","杨发 秋晴独立南亭"]]},{"n":"玄度","d":"","s":"《世说新语》上卷上《言语》","q":[["不见支公与玄度，相思拥膝坐长吟。","刘长卿 秋夜有怀高三十五兼呈空上人（一作皇甫冉诗）"],["能令许玄度，吟卧不知还。","孟浩然 宿立公房"]]},{"n":"宗许","d":"","s":"《宋书》卷九十三〈隐逸列传·宗炳〉","q":[["为我谢宗许，尘中难久留。","耿湋 寻觉公因寄李二端司空十四曙"]]}],"249":[{"n":"博望侯","d":"","s":"《史记》卷一一一《卫将军骠骑列传》","q":[["用时应不称娲皇，将去也堪随博望。","吴融 太湖石歌"],["从来思博望，许国不谋身。","张说 将赴朔方军应制"]]},{"n":"河源","d":"","s":"《史记》卷一百二十三〈大宛列传〉","q":[["寻河愁地尽，过碛觉天低。","岑参 碛西头送李判官入京"],["临海旧来闻骠骑，寻河本自有中郎。","崔融 从军行"]]},{"n":"一片石","d":"","s":"《太平御览》卷八〈天部八·汉〉","q":[]},{"n":"凿空","d":"","s":"《汉书》卷六十一《张骞传》","q":[["十月繁霜下，征人远凿空。","徐彦伯 胡无人行"],["宁如凿空使，远致石榴花。","王翰 奉和圣制送张尚书巡边"]]},{"n":"张骞泛槎","d":"","s":"《太平御览》卷五十一〈地部十六·石上〉2～","q":[["乘槎断消息，无处觅张骞。","杜甫 有感五首"]]}],"250":[{"n":"龚渤海","d":"","s":"《汉书》卷八十九《循吏传·龚遂传》","q":[["戎即昆山序，车同渤海单。","张九龄 送赵都护赴安西"],["求理由来许便宜，汉朝龚遂不为疵。","戴叔伦 抚州被推昭雪答陆太祝三首之一"]]},{"n":"卖剑买牛","d":"佩犊：喻弃官务农。宋苏轼《张作诗送砚反剑乃和其诗卒以剑归之》：“斩蛟刺虎老无力，带牛佩犊吏所诃。”；卖剑买牛：喻重本务农。宋苏轼《常润道中有怀钱塘五首》之五：“卖剑买牛吾欲老，杀鸡为黍子来无？”","s":"《汉书》卷八十九〈循吏列传·龚遂传〉","q":[]},{"n":"革潢池风俗","d":"","s":"《尚书》卷十四〈周书·康诰〉","q":[]},{"n":"龚黄","d":"","s":"《汉书》卷八十九《循吏传序》","q":[["共蹑华胥梦，龚黄安足寻。","张说 奉和圣制赐诸州刺史应制以题坐右"],["晋楚忙忙起战尘，龚黄门外有高人。","徐夤 依韵赠南方处士五首之五"]]},{"n":"潢池","d":"","s":"《汉书》卷八十九《循吏传·龚遂传》","q":[["每想潢池寇，犹稽赤族惩。","元稹 纪怀赠李六户曹崔二十功曹五十韵"]]}],"251":[{"n":"小儿杨德祖","d":"","s":"《后汉书》卷八十下〈文苑列传下·祢衡〉","q":[["十五事文翰，大儿轻孔融。","李端 长安感事呈卢纶"]]},{"n":"绝妙辞","d":"色丝文：称赞文章文辞华美。唐赵嘏《题曹娥庙》：“文字在碑碑已堕，波涛辜负色丝文。”","s":"《世说新语笺疏》中卷下〈捷悟〉","q":[["碑缺曹娥宅，林荒逸少居。","刘长卿 无锡东郭送友人游越"],["越鸟闻花里，曹娥想镜中。","刘长卿 送崔处士先适越"]]},{"n":"德祖家珍","d":"","s":"《世说新语笺疏》上卷上〈言语〉","q":[]},{"n":"鸡肋弃","d":"","s":"《三国志》卷一〈魏书·武帝纪〉","q":[["鸡肋曹公忿，猪肝仲叔惭。","罗隐 寄洪正师"]]},{"n":"杨修","d":"","s":"《后汉书》卷五十四《杨震传》附《杨修传》","q":[["范丐非童子，杨修岂小儿。","李端 送单少府赴扶风"]]}],"252":[{"n":"凤凰池","d":"凤池：凤凰池是禁苑中池沼，借指中书省或宰相。唐张说《崔司业挽歌二首》之二：“凤池伤旧草，麟史泣遗编。”","s":"唐·杜佑《通典》卷二十一《职官三》","q":[["看著凤池相继入，都堂那肯滞关营。","丘上卿 和主司王起"],["交朋接武居仙院，幕客追风入凤池。","刘禹锡 和仆射牛相公以离阙庭七年班行亲故亡殁十无一人再睹龙颜喜庆虽极感叹风烛能不怆然因成四韵并示集贤中书二相公所和"]]},{"n":"和峤专车","d":"","s":"《晋书》卷四十五《和峤传》","q":[["管宁割席，和峤专车。","李瀚 蒙求"]]},{"n":"荀家","d":"","s":"《晋书》卷三十九〈荀勖列传〉","q":[["贯珠一夜奏累累，尽是荀家旧教词。","吴融三 闻歌"]]},{"n":"荀秘监","d":"","s":"《晋书》卷三十九《荀勖传》","q":[["官秩旧参荀秘监，樽罍今伴霍嫖姚。","罗隐 寄渭北徐从事"]]},{"n":"荀勖定汲书","d":"","s":"《晋书》卷三十九《荀勖传》","q":[["汲书荀勖定，汉史蔡邕专。","卢纶 和常舍人晚秋集贤院即事十二韵寄赠江南徐薛二侍郎"]]}],"253":[{"n":"问君平","d":"成都卜：指雅逸生活，或指占卜。唐杜甫《游子》：“厌就成都卜，休为吏部眠。”","s":"《汉书》卷七十二〈王贡两龚鲍列传〉","q":[["君平帘下徒相问，长伴吹箫别有人。","刘君锡 和严给事闻唐昌观玉蕊花下有游仙二绝"],["众说君平死，真师易义全。","姚合 送任尊师归蜀觐亲"]]},{"n":"一片石","d":"","s":"《太平御览》卷八〈天部八·汉〉","q":[]},{"n":"李强","d":"","s":"《汉书》卷七十二《王贡两龚鲍传序》","q":[["处士同杨郑，邦君谢李疆。","崔善为 答王无功冬夜载酒乡馆"]]},{"n":"严郑","d":"","s":"《昭明文选》卷二十三、三国魏·嵇叔夜（康）《幽愤诗》","q":[["劳生愧严郑，外物慕张邴。","杜甫 渼陂西南台"]]},{"n":"张骞泛槎","d":"","s":"《太平御览》卷五十一〈地部十六·石上〉2～","q":[["乘槎断消息，无处觅张骞。","杜甫 有感五首"]]}],"254":[{"n":"高阳徒","d":"高阳酒徒：喻指狂放而好饮酒者。唐罗隐《曲江春感》：“高阳酒徒半雕落，终南山色空崔鬼。”","s":"《史记》卷九十七〈郦生陆贾列传·郦生〉","q":[["短衣宁倦重修谒，谁识高阳旧酒徒。","李咸用 和友人喜相遇十首之六"],["君不见高阳酒徒起草中，长揖山东隆准公。","李白 梁甫吟"]]},{"n":"齐烹","d":"","s":"《史记》卷九十七《郦生陆贾列传》","q":[["不是不同明主意，懒将唇舌与齐烹。","李咸用 依韵修睦上人山居十首"],["就烹感汉使，握节悲阳秋。","李德裕 东郡怀古二首之阳给事"]]},{"n":"郦生长揖","d":"","s":"《史记》卷九十七〈郦生陆贾列传·郦生〉","q":[["伊籍一拜，郦生长揖。","李瀚 蒙求"]]},{"n":"齐横降","d":"","s":"《史记》卷九十四《田儋列传》附《田横传》","q":[["势侔高阳翁，坐约齐横降。","韩愈 病中赠张十八"]]},{"n":"齐说客","d":"","s":"《史记》卷九十七《郦生列传》","q":[["圭窦三千士，云梯七十城。耻非齐说客，只似鲁诸生。","杜甫 奉送郭中丞兼太仆卿充陇右节度使三十韵"]]}],"255":[{"n":"锻铁","d":"","s":"《世说新语笺疏》下卷上〈简傲〉","q":[["中散山阳锻，愚公野谷村。","杜甫 赠比部萧郎中十兄"],["才淑随厮养，名贤隐锻炉。","杜甫 过南岳入洞庭湖"]]},{"n":"龙性讵能驯","d":"","s":"《昭明文选》卷二十一南朝宋·颜延年（延之）《五君咏五首·嵇中散》","q":[["凤歌空有问，龙性讵能驯。","陈子昂 酬李参军崇嗣旅馆见赠"]]},{"n":"矛戟","d":"","s":"《世说新语》中卷下《赏誉》","q":[["见说往年在翰林，胸中矛戟何森森。","任华 寄李白"],["复进出矛戟，昭然开鼎彝。","杜甫 赠崔十三评事公辅"]]},{"n":"王戎简要","d":"","s":"《三国志》卷二十三〈魏书·裴潜传〉","q":[["王戎简要，裴楷清通。","李瀚 蒙求"]]},{"n":"五字迁","d":"","s":"《三国志》卷二十八《魏书·钟会传》","q":[["一经推旧德，五字擢英才。","沈佺期 和韦舍人早朝"],["史为三坟博，郎因五字迁。","沈东美 奉和苑舍人宿直晓玩新池寄南省友"]]}],"256":[{"n":"麒麟阁","d":"","s":"《汉书》卷五十四〈李广苏建列传·苏武〉","q":[["若非载笔登麟阁，定是吹箫伴凤台。","于季子 早春洛阳答杜审言"],["新登麒麟阁，适脱獬豸冠。","岑参 送张秘书充刘相公通汴河判官便赴江外觐省"]]},{"n":"河间礼乐","d":"","s":"《汉书》卷五十三〈景十三王列传·河间献王刘德〉","q":[["子建文笔壮，河间经术存。","杜甫 别李义"],["枚乘文章老，河间礼乐存。","杜甫 奉汉中王手札"]]},{"n":"间平襟度","d":"","s":"《汉书》卷五十三〈景十三王列传·河间献王刘德〉","q":[]},{"n":"千里驹","d":"","s":"《楚辞补注》卷六〈卜居〉","q":[]},{"n":"三雍奏乐","d":"","s":"《汉书》卷五十三〈景十三王列传·河间献王刘德〉","q":[]}],"257":[{"n":"买山钱","d":"","s":"《世说新语》下卷下《排调》","q":[["沃洲能共隐，不用道林钱。","刘长卿 初到碧涧招明契上人"],["支遁初求道，深公笑买山。","孟浩然 宿立公房"]]},{"n":"巢父","d":"","s":"东汉·王符《潜夫论》卷八《交际》","q":[["巢父精灵归大夜，客儿才调振遗风。","方干 哭江西陈陶处士"],["水深严子钓，松挂巢父衣。","卢象 家叔徵君东溪草堂二首之二"]]},{"n":"巢由","d":"","s":"《遵生八笺·尘外遐举笺·历代高隐姓氏·巢父》","q":[["如知巢与许，千载迹犹新。","于武陵 寻山"],["巢由薄天下，俗士营一官。","唐彦谦 六月十三日上陈微博士"]]},{"n":"箕山颍水","d":"洗耳：指隐士清高脱俗。唐李白《送裴十八图南归嵩山》之二“归时莫洗耳，为我洗其心。”","s":"《庄子集释》卷一上〈内篇·逍遥游〉","q":[["箕山有高节，湘水有清源。","陈子昂 感遇诗三十八首之三十一"],["心到物自闲，何劳远箕颍。","元稹 表夏十首之二"]]},{"n":"一巢悬木末","d":"","s":"《高士传》卷上","q":[["回望一巢悬木末，独寻危石坐岩中。","刘沧 赠天台隐者"]]}],"258":[{"n":"妃子将军瞋","d":"","s":"《新唐书》卷二百二〈文艺列传中·李白〉","q":[]},{"n":"力士脱靴","d":"力士脱靴：指狂傲不羁、蔑视权贵。唐贯休《古意》：“一朝力士脱靴后，玉上青蝇生一个。”","s":"《新唐书》卷二百二〈文艺列传中·李白〉","q":[]},{"n":"谪仙人","d":"","s":"《全唐诗》卷一百八十二〈对酒忆贺监二首〉","q":[]},{"n":"御手调羹","d":"","s":"《新唐书》卷二百二〈文艺列传中·李白〉","q":[]},{"n":"杨妃袜","d":"","s":"《记事珠》","q":[]}],"259":[{"n":"辕下驹","d":"","s":"《史记》卷一百七〈魏其武安侯列传〉","q":[["赠尔秦人策，莫鞭辕下驹。","杜甫 别苏傒"],["出尘皆野鹤，历块匪辕驹。","杜甫 大历三年春白帝城放船出瞿塘峡久居夔府将适江陵漂泊有诗凡四十韵"]]},{"n":"田窦","d":"","s":"《史记》卷一○七《魏其武安侯列传》","q":[["田窦相倾夺，宾客互盈亏。","李白 古风之五十九"],["田窦方贵幸，赵李新相知。","郑愔 少年行"]]},{"n":"田窦醉","d":"","s":"《史记》卷一○七《魏其武安侯列传》","q":[["田窦长留醉，苏辛曲护岐。","杜牧 少年行"]]},{"n":"田鼢豪华","d":"","s":"《汉书》卷五十二《田纷传》","q":[["陈遵重交结，田鼢擅豪华。","虞世南 门有车马客"]]},{"n":"颍川使酒","d":"","s":"《史记》卷一○七《魏其武安侯列传》","q":[["誓令疏勒出飞泉，不似颍川空使酒。","王维 老将行"]]}],"260":[{"n":"囊中锥","d":"","s":"《史记》卷七十六〈平原君虞卿列传·平原君〉","q":[["叶怯穿杨箭，囊藏透颖锥。","元稹 酬翰林白学士代书一百韵"],["颖微囊未出，寒甚谷难吹。","刘禹锡 罢郡归洛阳寄友人"]]},{"n":"龙骧虎步","d":"","s":"《三国志》卷二十一〈魏书·王粲传·徐干陈琳阮瑀应玚刘桢〉","q":[]},{"n":"毛遂堕井","d":"","s":"旧题汉·葛洪《西京杂记》卷六","q":[["野人未必非毛遂，太守还须是孟尝。","张祜 江上旅泊呈杜员外"],["毛遂不堕井，曾参宁杀人。","李白 系浔阳上崔相涣三首"]]},{"n":"三寸舌","d":"三寸舌：指能言善辩、能以言语胜人。唐于渍《南越谣》：“三寸陆贾舌，万里汉山川。”","s":"《史记》卷七十六〈平原君虞卿列传·平原君〉","q":[["三寸陆贾舌，万里汉山川。","于濆 南越谣"]]},{"n":"因人成事","d":"","s":"《史记》卷七十六〈平原君虞卿列传·平原君〉","q":[]}],"261":[{"n":"胜隔绀纱尘幔","d":"","s":"《青箱杂记》卷六","q":[]},{"n":"无地起楼台","d":"","s":"《国老谈苑》卷二","q":[]},{"n":"莱公骰","d":"","s":"《宋人轶事汇编》卷五〈寇准〉","q":[]},{"n":"莱公扶景德","d":"","s":"《邵氏闻见录》卷一","q":[]},{"n":"柘枝犹在","d":"","s":"《梦溪笔谈》卷五〈校證·乐律一〉","q":[]}],"262":[{"n":"虎皮付伊川","d":"","s":"《二程语录》卷十七〈传闻杂记〉","q":[]},{"n":"剑阁铭","d":"剑阁铭：咏蜀地。清钱谦益《绣斧西巡歌为徐季良先生作》之一：“胡床襆被萧然去，片石留为剑阁铭。”","s":"《昭明文选》卷五十六晋·张孟阳（载）《剑阁铭》","q":[["江绕武侯筹笔地，雨昏张载勒铭山。","唐彦谦 兴元沈氏庄"],["胡床襆被萧然去，片石留为剑阁铭。”","钱谦益 绣斧西巡歌为徐季良先生作之一"]]},{"n":"孟阳掷瓦","d":"","s":"《晋书》卷五十五〈潘岳列传〉","q":[["孟阳掷瓦，贾氏如皋。","李瀚 蒙求"]]},{"n":"三张","d":"","s":"《晋书》卷五十五〈张载列传·（协弟）张亢〉","q":[["只有三张最惆怅，下山回马尚迟迟。","杜牧 送薛邽二首"],["地推八米源流盛，才笑三张事业贫。","罗隐 送卢端公归台卢校书之夏县"]]},{"n":"双南金","d":"","s":"《诗经·鲁颂·泮水》","q":[["寄之二君子，希见双南金。","元稹 春晚寄杨十二兼呈赵八"],["无复双金报，空馀挂剑悲。","刘禹锡 西州李尚书知愚与元武昌有旧远示二篇吟之泫然因以继和二首"]]}],"263":[{"n":"嵇绍血","d":"","s":"《晋书》卷八十九〈忠义列传·嵇绍〉","q":[]},{"n":"野鹤姿","d":"嵇鹤：喻指人才出众。唐李商隐《病中闻河东公乐营置酒口占寄上》：“嵇鹤元无对，荀龙不在夸。”","s":"《世说新语笺疏》下卷上〈容止〉","q":[["嵇鹤元无对，荀龙不在誇。","李商隐 病中闻河东公乐营置酒口占寄上"],["野鹤终踉跄，威凤徒参差。","王维 送高适弟耽归临淮作"]]},{"n":"山嵇","d":"","s":"《晋书》卷四十三〈山涛列传〉","q":[["范云堪晚友，嵇绍自不孤。","杜甫 别张十三建封"],["张老存家事，嵇康有故人。","杜甫 奉赠萧二十使君"]]},{"n":"侍中血","d":"","s":"《晋书》卷八十九《忠义传·嵇绍传》","q":[["御衣空惜侍中血，国玺几危皇后身。","韩偓 八月六日作四首"],["溅血惭嵇绍，迟行笑褚渊。","韩偓 感事三十四韵"]]},{"n":"嵇延祖","d":"","s":"《晋书》卷八十九《忠义传·嵇绍传》","q":[["人间只有嵇延祖，最望山公启事来。","李商隐 赠宇文中丞"],["山公访嵇绍，赵武见韩侯。","李端 送诸暨裴少府"]]}],"264":[{"n":"老辽东","d":"辽东帽：指清高，有操守；或喻隐居不仕。宋文天祥《正气歌》：“或为辽东帽，清操厉冰雪。”","s":"《三国志》卷十一〈魏书·管宁传〉","q":[]},{"n":"华歆","d":"","s":"《三国志》卷十三〈魏书·华歆传〉","q":[["往还谁是龙头人，公主遣秉鱼须笏。","李贺 酒罢张大彻索赠诗（时张初效潞幕）"],["班资冠鸡舌，人品压龙头。","罗隐 寄礼部郑员外"]]},{"n":"割席管宁","d":"","s":"《裴子语林》","q":[]},{"n":"管宁榻","d":"管宁床：咏勤学，或指行事端正。清叶燮《叠韵答学山侄》：“漂泊未归元亮宅，支离合老管宁床。”","s":"《高士传》卷下","q":[["管宁穿亦坐，徐孺去常悬。","李德裕 思山居一十首忆葛藤木禅床"],["扁舟不独如张翰，白帽还应似管宁。","杜甫 严中丞枉驾见过"]]},{"n":"管宁祭礼","d":"","s":"《三国志》卷十一《魏书·管宁传》","q":[["管宁存祭礼，王霸重朝章。","王绩 赠李徵君大寿"]]}],"265":[{"n":"堕马妆","d":"","s":"《后汉书》卷三十四〈梁统列传·（玄孙）梁冀〉","q":[["西施捧心，孙寿折腰。","李瀚 蒙求"],["折步教人学，偷香与客熏。","李端 妾薄命"]]},{"n":"将军西第","d":"","s":"《后汉书》卷三十四〈梁统列传·（玄孙）梁冀〉","q":[["无数将军西第成，早作丞相东山起。","杜甫 暮秋枉裴道州手札率尔遣兴寄近呈苏涣侍御"]]},{"n":"李固冤","d":"","s":"《后汉书》卷六十三《李固杜乔传》","q":[["李固有冤藏蠹简，邓攸无子续清风。","李玖 四丈夫同赋之一"]]},{"n":"梁冀","d":"","s":"《后汉书》卷三十四《梁统传》附《梁冀传》","q":[["窦融一家三尚主，梁翼频封万户侯。","蔡孚 打球篇"]]},{"n":"梁冀跋扈","d":"","s":"《后汉书》卷三十四《梁统传》附《梁冀传》","q":[["跋扈以成梁冀在，简书难问杜乔归。","罗隐 经洛阳故城"]]}],"266":[{"n":"咏白蘋","d":"","s":"《先秦汉魏晋南北朝诗·梁诗》卷八〈柳恽·江南曲〉","q":[]},{"n":"柳家汀洲","d":"","s":"《玉台新咏》卷五〈江南曲〉","q":[["柳家汀洲孟冬月，云寒水清荻花发。","朱长文 吴兴送梁补阙归朝赋得荻花"]]},{"n":"柳吴兴","d":"","s":"《梁书》卷二十一《柳恽传》","q":[["应谓焦桐堪采斫，不知谁是柳吴兴。","张又新 吹台山"],["罗含黄菊宅，柳恽白蘋汀。","李商隐 寄太原卢司空三十韵"]]},{"n":"柳恽旧国","d":"","s":"《南史》卷三十八〈柳元景列传·柳恽〉","q":[]},{"n":"文畅","d":"","s":"《梁书》卷二十一《柳恽传》","q":[["逸荡子山匹，经奇文畅俦。","皎然 读张曲江集"]]}],"267":[{"n":"舟中敌国","d":"","s":"《史记》卷六十五〈孙子吴起列传·吴起〉","q":[["羌胡毂下一朝起，敌国舟中非所拟。","柳宗元 古东门行"]]},{"n":"母殁不临","d":"","s":"《史记》卷六十五《吴起列传》","q":[["昔有吴起者，母殁丧不临。嗟哉斯徒辈，其心不如禽。","白居易 慈乌夜啼"]]},{"n":"吮疮","d":"","s":"《史记》卷六十五《吴起列传》","q":[["谁为吮疮者，此事今人薄。","刘长卿 从军行六首之六"]]},{"n":"孙吴","d":"","s":"《史记》卷一一一《卫将军骠骑列传》","q":[["口里虽谭周孔文，怀中不舍孙吴略。","李渤 喜弟淑再至为长歌"],["潘陆应同调，孙吴亦异时。","杜甫 暮春江陵送马大卿公恩命追赴阙下"]]},{"n":"吴起","d":"","s":"《史记》卷六十五《吴起列传》","q":[["贪名笑吴起，说国叹苏秦。","唐彦谦 客中感怀"],["非唯吴起与穰苴，今古推排尽不如。","方干 贼退后赠刘将军"]]}],"268":[{"n":"壁经","d":"","s":"《汉书》卷三十〈艺文志〉","q":[["箫奏秦台里，书开鲁壁中。","宋之问 宴安乐公主宅得空字"],["孔壁采遗篆，周韦考绝编。","崔日知 冬日述怀奉呈韦祭酒张左丞兰台名贤"]]},{"n":"雉过","d":"","s":"《后汉书》卷二十五〈卓鲁魏刘列传·鲁恭〉","q":[["都忘醉后逢廉度，不省归时见鲁恭。","于鹄 醉后寄山中友人"],["老人骖驭往，童子狎雏嬉。","张说 送乔安邑备"]]},{"n":"鲁恭文字","d":"","s":"《史记》卷五十九《五宗世家》","q":[["彩云萧史驻，文字鲁恭留。","杜甫 玉台观"]]},{"n":"囊不智","d":"","s":"《史记》卷七十一《樗里子列传》","q":[["曷月还朝天，及时开智囊。","独孤及 送相里郎中赴江西"],["解空囊不智，灭景谷何愚。","羊士谔 郡斋读经"]]},{"n":"卓鲁","d":"","s":"《昭明文选》卷四十三南朝齐·孔德璋（稚圭）《北山移文》","q":[["惭无卓鲁术，解印谢黔黎。","李嘉祐 南浦渡口"],["伯舅吏淮泗，卓鲁方喟然。","王维 奉送六舅归陆浑"]]}],"269":[{"n":"掷地","d":"掷地篇：喻文辞优美。唐羊士谔《郡中玩月寄江南李少府尹虞部孟员外》：“兹夕披云望，还吟掷地篇。”","s":"《世说新语笺疏》上卷下〈文学〉","q":[["赋成先掷地，词高直掞天。","崔日知 冬日述怀呈韦祭酒张左丞兰台名贤"],["欲啸迁乔侣，先飞掷地文。","李峤 和杜侍御太清台宿直旦有怀"]]},{"n":"龙津","d":"","s":"《晋书》卷五十六《孙绰传》","q":[["鸿羽不低飞，龙津徒自险。","钱起 送李四擢第归觐省"],["一与清风上芸阁，再期秋雨过龙津。","鲍溶 寄张十七校书李仁行秀才"]]},{"n":"遂初","d":"","s":"《晋书》卷五十六《孙楚传》附《孙绰传》","q":[["云埋野艇吟归去，草没山田赋遂初。","罗隐 新安投所知"]]},{"n":"孙绰才冠","d":"","s":"《晋书》卷五十六《孙楚传》附《孙绰传》","q":[["贺循儒宗，孙绰才冠。","李瀚 蒙求"]]},{"n":"谢安雅量","d":"","s":"《世说新语笺疏》中卷上〈雅量〉","q":[]}],"270":[{"n":"社中人","d":"","s":"《大正新脩大藏经》卷二十六〈净土立教志·莲社七祖·法师慧远〉2～","q":[["使君匡岳近，终作社中人。","周贺 投江州张郎中"],["闻结西方社，尚书待远公。","姚合 送澄江上人赴兴元郑尚书招"]]},{"n":"宗居士","d":"","s":"《宋书》卷九十三《隐逸传·宗炳传》","q":[]},{"n":"宗雷","d":"","s":"《宋书》卷九十三〈隐逸列传·宗炳〉","q":[["诗人识何谢，居士别宗雷。","李端 得山中道友书寄苗钱二员外"],["独有宗雷贱，过君著敝袍。","李端 题郑少府林园"]]},{"n":"宗许","d":"","s":"《宋书》卷九十三〈隐逸列传·宗炳〉","q":[["为我谢宗许，尘中难久留。","耿湋 寻觉公因寄李二端司空十四曙"]]},{"n":"卧游图","d":"卧游图：指称赏画。宋陆游《小阁纳凉》：“莫遣良工更摹写，此诗端是卧游图。”","s":"《宋书·宗炳传》","q":[["莫遣良工更摹写，此诗端是卧游图。","陆游 小阁纳凉"]]}],"271":[{"n":"荀龙","d":"","s":"《后汉书》卷六十二〈荀韩钟陈列传·荀淑〉","q":[["雄推三虎贾，群擢八龙荀。","元稹 代曲江老人百韵"],["荀氏八龙唯欠一，桓山四凤已过三。","包何 相里使君第七男生日"]]},{"n":"高阳里","d":"","s":"《后汉书》卷六十二〈荀韩钟陈列传·荀淑〉","q":[["相门才子高阳族，学省清资五品官。","刘禹锡 送国子令狐传士赴兴元觐省"],["晨兴涉清洛，访子高阳宅。","韦应物 李博士弟以余罢官居同德精舍共有伊陆名山之期久而未去枉诗见问中云宋生昔登览未云那能顾蓬荜直寄鄙怀聊以为答"]]},{"n":"荀陈","d":"","s":"《后汉书》卷六十二〈荀韩钟陈列传·荀淑〉","q":[["颍郡水东流，荀陈兄弟游。","宋之问 送许州宋司马赴任"],["耿贾官勋大，荀陈地望清。","李商隐 五言述德抒情诗一首四十韵献上杜七兄仆射相公"]]},{"n":"荀家头龙","d":"","s":"《后汉书》卷六十二〈荀韩钟陈列传·荀淑〉","q":[["贾氏许频趋季虎，荀家因敢谒头龙。","黄滔 投翰长赵侍郎"]]},{"n":"荀氏风流","d":"","s":"《三国志》卷十《魏书·荀彧传》","q":[["勋业耿家盛，风流荀氏均。","李端 送路司谏侍从叔赴洪州"],["荀氏风流远，胡家清白齐。","皇甫冉 送李万州赴饶州觐省"]]}],"272":[{"n":"欧苏","d":"","s":"金王若虚《送吕鹏举赴举序》","q":[]},{"n":"河东乞巧文","d":"","s":"《全唐文》卷五百八十三〈柳宗元十五·乞巧文〉2～","q":[]},{"n":"柳柳州","d":"","s":"《全唐诗》卷三百五十二〈种柳戏题〉","q":[]},{"n":"柳雅","d":"","s":"《全唐文》卷五百七十一〈柳宗元三·献平淮夷雅表〉","q":[]},{"n":"子厚南宫","d":"","s":"《全唐文》卷五百六十三〈韩愈十七·柳子厚墓志铭〉2～","q":[]}],"273":[{"n":"白兔公","d":"","s":"晋·葛洪《抱朴子·内篇·极言》","q":[["旧事仙人白兔公，掉头归去又乘风。","韩翃 送齐山人归长白山"]]},{"n":"篯铿年","d":"","s":"《论语注疏·述而》","q":[]},{"n":"彭殇","d":"","s":"《庄子》内篇·卷一下《齐物论》","q":[["细算人生事，彭殇共一筹。","杜牧 不饮赠酒"],["人生落其内，何者为彭殇。","杜牧 郡斋独酌"]]},{"n":"彭聃","d":"","s":"《楚辞》卷三《天问》","q":[["颜回徒恨少成古，彭祖何曾老至今。","刘威 感寓"],["王母桃花千遍红，彭祖巫咸几回死。","李贺 浩歌"]]},{"n":"彭祖寿","d":"","s":"《楚辞补注》卷三〈天问〉","q":[]}],"274":[{"n":"八凯","d":"","s":"《史记》卷一〈五帝本纪·帝舜〉","q":[["谢太傅须同八凯，姚梁公可并三台。","贯休 蜀王入大慈寺听讲"],["人知八凯须当国，猿到三声不用愁。","贯休 送薛侍郎贬峡州司马"]]},{"n":"八元","d":"","s":"《春秋左传·文公十八年》","q":[["早入八元数，尝承三接恩。","刘禹锡 和浙西李大夫伊川卜居"]]},{"n":"八族","d":"","s":"《史记》卷一《五帝本纪·舜本纪》","q":[["八族未来谁北拱，四凶犹在莫南巡。","罗隐 湘妃庙"]]},{"n":"阏伯","d":"","s":"《春秋左传·昭公元年》","q":[["阏伯去已久，高丘临道旁。人皆有兄弟，尔独为参商。","高适 宋中十首之十"]]},{"n":"十六族","d":"","s":"《史记》卷一《武帝本纪》","q":[["岂唯十六族，今古称其贤。","权德舆 酬穆七侍郎早登使院西楼感怀"]]}],"275":[{"n":"妲末","d":"","s":"《汉语大词典》","q":[]},{"n":"褒妲","d":"","s":"《国语》卷七《晋语一》","q":[["中自诛褒妲，周汉获再兴。","杜甫 北征"]]},{"n":"妲己","d":"","s":"《史记》卷三〈殷本纪〉","q":[["妲己灭纣，褒女惑周。","李白 雪谗诗赠友人"]]},{"n":"商倾妲己","d":"","s":"《史记》卷三〈殷本纪〉","q":[]},{"n":"铜柱","d":"","s":"汉·刘向《列女传》卷七《孽嬖传·殷纣妲己》","q":[["玉床逾皓洁，铜柱方歊焮。","徐彦伯 比干墓"]]}],"276":[{"n":"班女","d":"","s":"《汉书》卷九十七下《外戚传下·孝成班婕妤传》","q":[["班姬入后宫，飞燕舞东风。青娥中夜起，长叹月明里。","刘驾 皎皎词"],["班姬此夕愁无限，河汉三更看斗牛。","崔颢 七夕"]]},{"n":"怨秋风","d":"班女怨：指妇女因失宠而哀怨。唐窦牟《元日喜闻大礼寄上翰林四学士中书六舍人二十韵》：“忽思班女怨，遥听越人吟。”","s":"《昭明文选》卷二十七〈诗戊·乐府上·怨歌行〉","q":[["一从悲画扇，几度泣前鱼。","于武陵 长信宫二首"],["羞同班女高秋扇，欲照明王乙夜书。","刘庭琦 奉和圣制瑞雪篇"]]},{"n":"避辇","d":"","s":"《汉书》卷九十七下〈外戚列传下·孝成班婕妤〉","q":[]},{"n":"同辇","d":"辞辇：称颂后妃有德守礼。唐卢纶《天长久词》：“辞辇复当熊，倾心奉六宫。”","s":"《汉书》卷九十七下《外戚传下·孝成班婕妤传》","q":[["本无辞辇意，岂见入空宫。","李贺 感讽六首之五"],["辞辇复当熊，倾心奉六宫。","卢纶 天长久词"]]},{"n":"昭阳人妒","d":"","s":"《汉书》卷九十七下〈外戚列传下·孝成班倢?〉","q":[]}],"277":[{"n":"减灶","d":"","s":"《史记》卷六十五《孙子列传》附《孙膑传》","q":[["运筹初减灶，调鼎未和羹。","刘长卿 至德三年春正月时谬蒙差摄海盐令闻王师收二京因书事寄上浙西节度李侍郎中丞行营五十韵"],["沉沙无故迹，减灶有残痕。","李世民 经破薛举战地"]]},{"n":"庞涓怯孙膑","d":"","s":"《史记》卷六十五〈孙子吴起列传·孙子〉","q":[["回军与角逐，斫树收穷庞。","韩愈 病中赠张十八"],["尔来但欲保封疆，莫学庞涓怯孙膑。","韩愈 赠崔立之评事"]]},{"n":"上驷","d":"","s":"《史记》卷六十五《孙子列传》","q":[["岁老岂能充上驷，力微当自慎前程。","韩愈 入关咏马"]]},{"n":"孙膑伏兵","d":"","s":"《史记》卷六十五〈孙子吴起列传·孙子〉","q":[]},{"n":"万灶","d":"","s":"《史记》卷六十五〈孙子吴起列传·孙子〉","q":[]}],"278":[{"n":"白莲社","d":"","s":"《大正新脩大藏经》卷四十九〈史传部一〉","q":[]},{"n":"东林","d":"","s":"晋·佚名《莲社高贤传·慧远法师》","q":[["东林期隐吏，日月为虚盈。","皎然 春夜期裴都曹济集心上人院不至"],["北阙会抛红駊騀，东林社忆白氛氲。","齐己 答崔校书"]]},{"n":"二林","d":"","s":"《大正新脩大藏经》卷五十〈史传部三〉3～","q":[["下马二林寺，翛然进轻策。","白居易 春游二林寺"]]},{"n":"社中人","d":"","s":"《大正新脩大藏经》卷二十六〈净土立教志·莲社七祖·法师慧远〉2～","q":[["使君匡岳近，终作社中人。","周贺 投江州张郎中"],["闻结西方社，尚书待远公。","姚合 送澄江上人赴兴元郑尚书招"]]},{"n":"杖出泉","d":"","s":"南朝梁·释慧皎《高僧传》卷六《晋庐山释慧远》","q":[["到处花为雨，行时杖出泉。","钱起 送赟法师往上都"]]}],"279":[{"n":"孔颜","d":"","s":"《昭明文选》卷二十八〈诗戊·乐府下·乐府十七首·日出东南隅行〉","q":[]},{"n":"孔颜遗旨","d":"","s":"《论语注疏·季氏》","q":[]},{"n":"练光乱马","d":"","s":"东汉·王充《论衡》卷四《书虚》","q":[["练光摇乱马，剑气上连牛。","骆宾王 久客临海有怀"]]},{"n":"颜冉","d":"","s":"《论语·先进》","q":[["颜冉德无邻，分忧浙水滨。","贯休 上杭州令狐使君"]]},{"n":"铸颜","d":"","s":"《法言·学行》","q":[["宁同鲁司寇，惟铸一颜回。","李商隐 喜舍弟羲叟及第上礼部魏公"],["斗间紫气龙埋狱，天上洪炉帝铸颜。","杜牧 道一大尹存之庭美二学士简于圣明自致霄汉皆与舍弟昔年还往牧支离穷悴窃于一麾书美歌诗兼自言志因成长句四韵呈上三君子"]]}],"280":[{"n":"丝竹后堂","d":"","s":"《汉书》卷八十一〈匡张孔马列传·张禹〉","q":[["复此开悬榻，宁唯入后堂。","杜审言 赠崔融二十韵"]]},{"n":"安昌列后堂","d":"","s":"《汉书》卷八十一〈匡张孔马列传·张禹〉","q":[]},{"n":"攀槛","d":"","s":"《汉书》卷六十七〈杨胡朱梅云列传·朱云〉","q":[["致君期折槛，举职在埋轮。","崔涂 寄舅"],["共美持衡日，皆言折槛时。","李嘉祐 故燕国相公挽歌二首之二"]]},{"n":"萧咸","d":"","s":"《汉书》卷七十八《萧望之传》附《萧育传》","q":[["若转弘农守，萧咸事不如。","卢纶 送抚州周使君"]]},{"n":"张禹","d":"","s":"《后汉书》卷四十四《张禹传》","q":[["汉相见王陵，扬州事张禹。","韩翃 送万巨"]]}],"281":[{"n":"千金诺","d":"","s":"《史记》卷一百〈季布栾布列传·季布〉","q":[["一饭意专堪便死，千金诺在转难酬。","吴融 离霅溪感事献郑员外"],["千金未必能移性，一诺从来许杀身。","戎昱 上湖南崔中丞"]]},{"n":"广柳","d":"","s":"《史记》卷一○○《季布列传》","q":[["顽童逃广柳，羸马卧平芜。","温庭筠 病中书怀呈友人"]]},{"n":"汉求季布","d":"","s":"《史记》卷一○○《季布列传》","q":[["汉求季布鲁朱家，楚逐伍胥去章华。","李白 江上赠窦长史"]]},{"n":"季布折公卿","d":"","s":"《史记》卷一○○《季布列传》","q":[["鲁连善谈笑，季布折公卿。","李白 献从叔当涂宰阳冰"]]},{"n":"髡钳","d":"","s":"《史记》卷一○○《季布列传》","q":[["髡钳为台隶，灌园变姓名。","卢照邻 咏史四首之一"]]}],"282":[{"n":"白俗","d":"","s":"《苏轼文集》卷六三〈祭柳子玉文〉","q":[]},{"n":"微之","d":"","s":"《旧唐书》卷一百六十六〈元稹列传〉","q":[]},{"n":"我白君元，各自为长庆","d":"","s":"《全唐文》卷六百五十三〈元稹七·白氏长庆集序〉","q":[]},{"n":"压倒元白","d":"","s":"《太平广记》卷一百七十八〈贡举一·宴集〉","q":[]},{"n":"元白","d":"","s":"《全唐文》卷七百六十五〈唐诗类选后序〉","q":[]}],"283":[{"n":"白马负经","d":"","s":"北魏·杨衒之《洛阳伽蓝记》卷四","q":[["遥知汉地未有经，手牵白马绕天行。","刘言史 送婆罗门归本国"],["金人来梦里，白马出城中。","沈佺期 奉和圣制同皇太子游慈恩封应制"]]},{"n":"馆陶恩","d":"","s":"《后汉书》卷十下《皇后纪》附《皇女》","q":[["早加于氏对，偏占馆陶恩。","窦常 凉国惠康公主挽歌"]]},{"n":"金人梦","d":"","s":"《后汉书》卷八十八《西域传·天竺传》","q":[["金人来梦里，白马出城中。","沈佺期 奉和圣制同皇太子游慈恩寺应制"]]},{"n":"镜奁换","d":"","s":"《后汉书》卷十上《皇后纪·光烈阴皇后纪》","q":[["镜奁换粉黛，翠羽犹葱胧。","杜甫 往在"],["只有朝陵日，妆奁一暂开。","韩愈 大行皇太后挽歌词三首"]]},{"n":"撞郎","d":"","s":"《后汉书》卷四十一《钟离意传》","q":[["徒令永平帝，千载罢撞郎。","卢照邻 哭金部韦郎中"]]}],"284":[{"n":"安兄杀嵇","d":"","s":"《三国志》卷二十一《魏书·王粲传》附《嵇康传》","q":[["吕安兄不道，都市杀嵇康。","白居易 杂感"]]},{"n":"题凡鸟","d":"凡鸟：喻庸才。唐张九龄《杂诗》之二：“凡鸟已相噪，凤凰安得知。”","s":"《世说新语笺疏》下卷上〈简傲〉","q":[["凡鸟已相噪，凤皇安得知。","张九龄 杂诗五首"],["谒客唯题凤，偷儿欲觇毡。","李端 晚春过夏侯校书值其沉醉戏赠"]]},{"n":"山阳笛","d":"山阳笛：喻悼念、怀念故友。唐司空曙《残老百哗歌同王员外耿拾遗吉中罕李端游慈思各赋一物》：“金谷筝中传不似，山阳笛里写难成。”","s":"《昭明文选》卷十六、三国魏·向子期（秀）《思旧赋·序》","q":[["旧时闻笛泪，今夜重沾衣。","司空曙 冬夜耿拾遗王秀才就宿因伤故人"],["金谷筝中传不似，山阳笛里写难成。","司空曙 残莺百啭歌同王员外耿拾遗吉中孚李端游慈恩各赋一物"]]},{"n":"千里驾","d":"寻嵇：喻对朋友的思念。唐李白《酬坊州工司马与间正字对雪见赠》“访戴昔未偶，寻嵇此相得。”","s":"《世说新语笺疏》下卷上〈简傲〉","q":[["今朝忽枉嵇生驾，倒屣开门遥解颜。","崔兴宗 酬王维卢象见过林亭"],["同人千里驾，邻国五马车。","房琯 题汉州西湖"]]},{"n":"向秀园","d":"","s":"《晋书》卷四十九《向秀传》","q":[["暮雨扬雄宅，秋风向秀园。","李郢 园居"]]}],"285":[{"n":"伯乐相马","d":"","s":"《庄子》外篇·卷四中《马蹄》","q":[["自知毛骨还应异，更请孙阳仔细看。","平曾 絷白马诗上薛仆射"],["上惭伯乐顾，中负叔牙知。","张九龄 南还以诗代书赠京师"]]},{"n":"服盐车","d":"盐车：喻指人才处于困境。唐李白《天马歌》：“盐车上峻阪，倒行逆施长日晚。”","s":"《战国策》卷十七〈楚策四·汗明见春申君〉","q":[["盐车淹素志，长坂入青云。","唐彦谦 留别四首"],["嘶风重诉牵盐耻，伯乐何妨转眼看。","李咸用 投知"]]},{"n":"良乐","d":"","s":"《汉书》卷一○○上《叙传上》","q":[["良乐知骐骥，张雷验镆铘。","贾岛 寄令狐绹相公"]]},{"n":"伯乐顾","d":"伯乐顾：喻指受名家赏识而出名。唐张九龄《南还以诗代书赠京师旧僚》：“上惭伯乐顾，中负叔牙知。”","s":"《战国策》卷三十〈燕二·苏代为燕说齐〉","q":[["一顾恩深荷道安，独垂双泪下层峦。","刘沧 龙门留别道友"],["一顾生鸿羽，再言将鹤翩。","孟郊 寄陕府邓给事"]]}],"286":[{"n":"乌鹊桥","d":"七夕：咏七夕，或喻指夫妇聚会。唐杜甫《牵牛织女》：“万古永相望，七夕谁见同。”","s":"《史记》卷二十七〈天官书〉","q":[["乌鹊桥成上界通，千秋灵会此宵同。","刘威 七夕"],["鹊桥初就咽银河，今夜仙郎自姓和。","和凝 杨柳枝"]]},{"n":"盈盈一水","d":"","s":"《昭明文选》卷二十九〈诗己·杂诗上·古诗十九首〉","q":[["云归巫峡音容断，路隔星河去住难。","刘损 愤惋诗三首之三"],["银河正清浅，霓节过来无。","吴融 即席十韵"]]},{"n":"织女襄","d":"","s":"《毛诗正义·小雅·谷风·大东》","q":[["谁知此日凭轩处，一笔工夫胜七襄。","吴融 和座主尚书登布善寺楼"],["腾身跨汗漫，不著织女襄。","韩愈 调张籍"]]},{"n":"乞天孙巧","d":"","s":"《荆楚岁时记》第一部〈宝颜堂秘笈本〉","q":[["万人惟待乘鸾出，乞巧齐登明月楼。","陆畅 云安公主出降杂咏催妆二首"]]}],"287":[{"n":"吴宫教战","d":"","s":"《史记》卷六十五〈孙子吴起列传·孙子〉","q":[]},{"n":"孙吴","d":"","s":"《史记》卷一一一《卫将军骠骑列传》","q":[["口里虽谭周孔文，怀中不舍孙吴略。","李渤 喜弟淑再至为长歌"],["潘陆应同调，孙吴亦异时。","杜甫 暮春江陵送马大卿公恩命追赴阙下"]]},{"n":"孙武","d":"","s":"《史记》卷六十五《孙子列传》","q":[["袁公论剑术，孙子叙兵篇。","崔日知 冬日述怀奉呈韦祭酒张左丞兰台名贤"],["孙武倾心与万夫，削平妖孽在斯须。","方干 狂寇后上刘尚书"]]},{"n":"孙武杀美人","d":"","s":"《史记》卷六十五《孙子列传》","q":[["任伊孙武心如铁，不办军前杀此人。","罗虬 比红儿诗之四十"]]}],"288":[{"n":"并州快剪刀","d":"","s":"《全唐诗》卷二百一十九〈戏题画山水图歌【戏题王宰画山水图歌】〉【案：宰。蜀人。善","q":[]},{"n":"关心药裹","d":"","s":"《全唐诗》卷二百三十三〈酬郭十五受判官〉","q":[]},{"n":"旗亭画壁","d":"","s":"《岁时习俗资料汇编·月令粹编》卷十五〈冬总〉","q":[]},{"n":"携高李","d":"","s":"《全唐诗》卷二百二十二〈昔游〉","q":[]}],"289":[{"n":"鼎迁","d":"","s":"《春秋左传·桓公二年》","q":[["高居迁鼎邑，遥傅好书王。","柳宗元 弘农公以硕德伟材屈于诬枉（弘农公杨凭也。为御史李夷简所弹）左官三岁复为大僚天监昭明人心感悦宗元窜伏湘浦拜贺末由谨献诗五十韵以毕微志"],["水斗宫初毁，风变鼎将迁。","陆敬 游隋故都"]]},{"n":"来苏","d":"","s":"《尚书·商书·仲虺之诰》","q":[["肆觐遵时豫，顺动悦来苏。","虞世南 奉和幸江都应诏"],["来苏伫圣德，濡足乃乘乾。","陆敬 游隋故都"]]},{"n":"汤征","d":"","s":"《孟子》卷二《梁惠王下》","q":[["汤征随北怨，舜咏起南风。","袁朗 赋饮马长城窟"]]},{"n":"务光让天下","d":"","s":"《庄子》杂篇·卷九下《让王》","q":[["善卷让天子，务光亦逃名。","李白 雉子斑（一作设辟邪伎鼓吹雉子斑曲辞）"],["务光让天下，商贾竞刀锥。","陈子昂 感遇诗三十八首之十"]]}],"290":[{"n":"伯有精灵","d":"","s":"《春秋左传·昭公七年》","q":[["莫道精灵无伯有，寻闻任侠报爰丝。","吴融 偶题"]]},{"n":"吾无为善","d":"","s":"《春秋左传·昭公十三年》","q":[["为善吾无矣，知音子绝焉。","王维 哭祖六自虚"]]},{"n":"郑侨","d":"","s":"《春秋左传正义》卷三十九〈襄公·传二十九年〉","q":[["入幕知孙楚，披襟得郑侨。","杜甫 奉赠卢五丈参谋"]]},{"n":"子产","d":"","s":"《史记》卷四十二〈郑世家〉","q":[["文翁旧学校，子产昔田畴。","李夷简 西亭暇日书怀十二韵献上相公"]]}],"291":[{"n":"东都外","d":"","s":"《汉书》卷七十一《东都外》","q":[["何必东都外，此处可抽簪。","孔德绍 南隐游泉山行经太华，纷吾世网暇灵岳展幽寻寥廊风尘远杳冥川谷深山昏五里雾日落二华阴疏峰起莲叶危塞隐桃林何必东都外此处可抽簪夜宿荒村绵绵夕漏深客痕转伤心抚弦无人听对歌时独斟故乡"],["海上旧山无的信，东门归路不堪行。","戴叔伦 送车参军江陵（一作送韦参军一作释清江诗）"]]},{"n":"疏还","d":"二疏：喻叔侄并贤，又咏功成身退。唐权德舆《奉送韦起居老舅百日假满归嵩阳旧居》：“四皓本违难，二疏犹待年。”","s":"《汉书》卷七十一〈隽疏于薛平彭列传·疏广（兄子）疏受〉","q":[["唯有汉二疏，应觉还家晚。","刘驾 读史"],["尚平方毕娶，疏广念归期。","李德裕 思山居一十首忆种菰时"]]},{"n":"挥金","d":"","s":"《汉书》卷七十一〈隽疏于薛平彭列传·疏广〉","q":[["故老空悬剑，邻交日散金。","张说 和魏仆射还乡"],["不散东海金，何争西飞匿。","李白 君子有所思行"]]},{"n":"疏受","d":"","s":"《汉书》卷七十一《疏广传》","q":[["疏受杜门期脱屣，买臣归邸忽乘轺。","李绅 初秋忽奉诏除浙东观察使检校右貂"]]}],"292":[{"n":"夺锦袍","d":"","s":"《隋唐嘉话》下","q":[]},{"n":"造物小儿","d":"","s":"《新唐书》卷二百一〈文艺列传上·杜审言〉","q":[]},{"n":"沈宋","d":"","s":"唐·杜甫《秋日夔府咏怀奉寄郑监李宾客一百韵》","q":[]},{"n":"锦袍夺去","d":"","s":"《隋唐嘉话》下","q":[]}],"293":[{"n":"耿邓","d":"","s":"《后汉书》卷十六《邓禹传》","q":[["孰与关张并，功临耿邓亲。","杜甫 谒先主庙"]]},{"n":"耿贾","d":"","s":"《后汉书》卷二十二〈朱景王杜马刘傅坚马列传〉","q":[["耿贾官勋大，荀陈地望清。","李商隐 五言述德抒情诗一首四十韵献上杜七兄仆射相公"],["耿贾扶王室，萧曹拱御筵。","杜甫 秋曰夔府咏怀奉寄郑监李宾客一百韵"]]},{"n":"耿弇","d":"","s":"《后汉书》卷十九《耿弇传》","q":[["先揖耿弇声寂寂，今看黄霸事摐摐。","杜牧 寄唐州李玭尚书"]]},{"n":"禹弇宫武","d":"","s":"《后汉书》卷十六〈邓寇列传·邓禹〉","q":[]}],"294":[{"n":"持螯手","d":"","s":"《艺文类聚》卷四十八〈职官部四·吏部郎〉","q":[["金罍几醉乌程酒，鹤舫閒吟把蟹螯。","羊士谔 忆江南旧游二首之二"]]},{"n":"卧瓮","d":"吏部眠：咏嗜酒或醉态。唐杜甫《游子》：“厌就成都卜，休为吏部眠。”","s":"《晋中兴书》卷七〈陈留阮录〉","q":[["偷归瓮间卧，逢个楚狂来。","戴叔伦 答崔载华"],["毕卓醉狂潘氏少，倾来掷去恰相宜。","方干 袁明府以家酝寄余余以山梅答赠非唯四韵兼亦双关"]]},{"n":"瓮头吏部","d":"","s":"《晋中兴书》卷七〈陈留阮录〉","q":[]},{"n":"蟹螯","d":"","s":"《晋书》卷四十九《毕卓传》","q":[["蟹螯即金液，糟丘是蓬莱。","李白 月下独酌四首之四"],["左手持蟹螯，右手执丹经。","李颀 赠张旭"]]}],"295":[{"n":"夺锦袍","d":"","s":"《隋唐嘉话》下","q":[]},{"n":"凤阁","d":"","s":"《旧唐书》卷四十二〈职官志一·序言〉","q":[]},{"n":"六郎","d":"","s":"《大唐新语》卷九〈谀佞〉","q":[]},{"n":"武媚宫中","d":"","s":"《新唐书》卷七十六〈后妃列传上·高宗王皇后〉","q":[]}],"296":[{"n":"卫娘","d":"","s":"《史记》卷四十九《外戚世家》","q":[["瑶房侍寝世莫知，金屋更衣人不见。","崔颢 郸邯宫人怨"],["子夫前入侍，飞燕复当时。","武平一 妾薄命"]]},{"n":"平阳","d":"","s":"《史记》卷一一一《卫将军骠骑列传》","q":[["虚然异风出，髣髴宿平阳。","丁仙芝 剡溪西馆闻笛"],["平阳旧池馆，寂寞使人愁。","丁仙芝 长宁公主旧山池"]]},{"n":"平阳拊背","d":"","s":"《史记》卷四十九《外戚世家》","q":[["平阳拊背穿驰道，铜雀分香下璧门。","杜牧 出宫人二首"]]},{"n":"平阳骑","d":"","s":"《汉书》卷五十五《卫青霍去病传》","q":[["骑出平阳里，筵开卫尉家。","周思钧 晦日宴高氏林亭"],["结束平阳骑，明朝入建章。","王维 奉和杨驸马六郎秋夜即事"]]}],"297":[{"n":"牛衣卧","d":"卧牛衣：咏贫士生活凄凉。唐皮日休《鲁望读襄阳耆旧传见赠次韵》：“甘穷卧牛衣，受辱对狗窦。”","s":"《汉书》卷七十六〈赵尹韩张两王列传·王章〉","q":[["牛衣独自眠，谁哀仲卿泣。","刘禹锡 谪居悼往二首"],["无灯假贫女，有泪沾牛衾。","李群玉 将离澧浦置酒野屿奉怀沈正字昆弟三人联登高第"]]},{"n":"三王尹京","d":"","s":"《汉书》卷七十二《王吉传》附《王骏传》","q":[["三王尹京，二鲍纠慝。","李瀚 蒙求"]]},{"n":"王章泣恨","d":"","s":"《汉书》卷七十六《王章传》","q":[["光逸偷眠稳，王章泣恨长。","李峤 被"]]},{"n":"无表雪王章","d":"","s":"《汉书》卷七十六〈赵尹韩张两王列传·王章〉","q":[["虽有衣衾藏李固，终无表疏雪王章。","李玖 四丈夫同赋"]]}],"298":[{"n":"丙吉问牛","d":"","s":"《汉书》卷七十四〈魏相丙吉列传·丙吉〉","q":[["凤巢方得地，牛喘最关心。","包佶 奉和柳相公中书言怀"],["倚马才高犹爱艺，问牛心在肯容私。","卢延让 逢友人赴阙"]]},{"n":"丙魏","d":"","s":"《汉书》卷七十四《魏相丙吉传》","q":[["运偶唐虞盛，情同丙魏深。","裴度 奉酬中书相公至日圆丘摄事合于中书后阁宿斋移止于集贤院叙怀见寄之作"]]},{"n":"吐茵","d":"污车茵：喻指醉后失误或替人掩盖过失。唐王维《故太子太师徐公挽歌四首》之三：“从今虚醉饱，无复污车茵。”","s":"《汉书》卷七十四〈魏相丙吉列传·丙吉〉","q":[["自笑吐茵还酩酊，日斜空从绛衣回。","李郢 奉陪裴相公重阳日游安乐池亭"],["莫辞倒载吟归去，看欲东山又吐茵。","段成式 和徐商贺卢员外赐绯（一作和徐相公贺襄阳徐副使加章服）"]]},{"n":"麒麟阁","d":"","s":"《汉书》卷五十四〈李广苏建列传·苏武〉","q":[["若非载笔登麟阁，定是吹箫伴凤台。","于季子 早春洛阳答杜审言"],["新登麒麟阁，适脱獬豸冠。","岑参 送张秘书充刘相公通汴河判官便赴江外觐省"]]}],"299":[{"n":"鲧死羽","d":"","s":"《尚书·虞书·舜典》","q":[["膺图受禅登明堂，共流幽州鲧死羽。","韩愈 永贞行"]]},{"n":"梼杌","d":"","s":"《春秋左传·文公十八年》","q":[["梼杌宽之久，防风戮不行。","李商隐 送千牛李将军赴阙五十韵"]]},{"n":"羽窟幽黄能","d":"","s":"《春秋左传·昭公七年》","q":[["近者三奸悉破碎，羽窟无底幽黄能。","韩愈 忆昨行和张十一"]]},{"n":"拙鲧","d":"","s":"《山海经·海内经》","q":[["黄河弄濆薄，梗涩连拙鲧。","韩愈 嘲鼾睡二首"]]}],"300":[{"n":"攀槛","d":"","s":"《汉书》卷六十七〈杨胡朱梅云列传·朱云〉","q":[["致君期折槛，举职在埋轮。","崔涂 寄舅"],["共美持衡日，皆言折槛时。","李嘉祐 故燕国相公挽歌二首之二"]]},{"n":"断佞臣","d":"","s":"《汉书》卷六十七《朱云传》","q":[["尝闻断马剑，每壮朱云贤。","李华 咏史十一首之一"],["安得上方断马剑，斩取朱门公子头。","王翰 飞燕篇"]]},{"n":"五鹿岳岳","d":"","s":"《汉书》卷六十七《朱云传》","q":[["五鹿归来惊岳岳，孤鸿飞去入冥冥。","陆希声 山居即事二首"]]},{"n":"朱阿游","d":"","s":"《汉书》卷六十七《朱云传》","q":[["昔有平陵男，姓朱名阿游。","卢照邻 咏史四首"]]}],"301":[{"n":"仇览栖鹰","d":"","s":"《后汉书》卷七十六《循吏传·仇览传》","q":[["庞统展骥，仇览栖鹰。","李瀚 蒙求"]]},{"n":"仇梅","d":"","s":"《后汉书》卷七十六《循吏传·仇览传》","q":[["不是仇梅至，何人问百忧。","耿湋 下邽客舍喜叔孙主簿郑少府见过"]]},{"n":"仇香印","d":"","s":"《后汉书》卷七十六〈循吏列传·仇览〉","q":[["南陵暂掌仇香印，北阙终行贾谊书。","贾岛 送友人之南陵"]]},{"n":"栖棘","d":"枳棘栖凤：咏县吏，多有大才小用之售民唐刘长卿《送沈少府之任淮南》：“俗君滞南楚，积棘徒栖风。”","s":"《后汉书》卷七十六〈循吏列传·仇览〉","q":[["惜君滞南楚，枳棘徒栖凤。","刘长卿 送沈少府之任淮南"],["枳棘君尚栖，匏瓜吾岂系。","孟浩然 将适天台留别临安李主簿"]]}],"302":[{"n":"一囊钱","d":"","s":"《后汉书》卷八十下《文苑传·赵壹传》","q":[["赵壹囊初乏，何曾箸欲收。","李峤 钱"],["初辞五斗米，唯奉一囊钱。","韩翃 家兄自山南罢归献诗叙事"]]},{"n":"穷鸟客","d":"","s":"《后汉书》卷八十下《文苑传·赵壹传》","q":[["汉阳穷鸟客，梁甫卧龙才。","骆宾王 幽絷书情通简知己"]]},{"n":"元淑命不达","d":"","s":"《后汉书》卷八十下〈文苑列传·赵壹〉","q":[["元淑命不达，伯鸾吟可叹。","储光羲 贻刘高士别"],["作赋同元淑，能诗匪仲宣。","高适 信安王幕府诗"]]},{"n":"赵壹赋命薄","d":"","s":"《后汉书》卷八十下《文苑传·赵壹传》","q":[["赵壹赋命薄，陈思多世忧。","李群玉 将之京国赠薛员外"],["赵壹赋命薄，马卿家业贫。","李贺 出城别张又新酬李汉"]]}],"303":[{"n":"盗道","d":"","s":"《庄子》外篇·卷四中《胠箧》","q":[["图霸未能知盗道，饰非唯欲害仁人。","韩偓 八月六日作四首之二"]]},{"n":"盗蹠","d":"","s":"《庄子集释》卷九下〈杂篇·盗蹠〉","q":[["叔孙谗易得，盗蹠暴难当。","李商隐 赠送前刘五经映三十四韵"]]},{"n":"尧与蹠","d":"","s":"《孟子》卷六《滕文公下》","q":[["世无洗耳翁，谁知尧与蹠。","李白 古风之二十四"]]},{"n":"蹠行仁义孔丘非","d":"","s":"《庄子集释》卷四中〈外篇·胠箧〉","q":[]}],"304":[{"n":"坠驴","d":"","s":"《宋人轶事汇编》卷五〈陈抟种放魏野杨朴穆修郭忠恕江直木〉","q":[]},{"n":"陈抟","d":"","s":"《旧五代史》卷一百一十六〈周书·世宗本纪·显德三年〉","q":[]},{"n":"希夷睡","d":"","s":"《宋史》卷四百五十七〈隐逸列传上·陈抟〉","q":[]},{"n":"薇垣小星韩王普","d":"","s":"《续湘山野录》","q":[]}],"305":[{"n":"一鸣惊人","d":"冲天翼：喻指贤士待时而动。唐贯休《遇叶进土》：“自愧龙钟人，见此冲天翼、”","s":"《韩非子》卷七〈喻老〉","q":[["遇此枝叶覆，夙举冀冲天。","李岑 东峰亭各赋一物得栖烟鸟"],["子既屈一鸣，余固宜三刖。","杜牧 池州送孟迟先辈"]]},{"n":"绝缨","d":"","s":"《韩诗外传》卷七","q":[["罗衣半醉春夜寒，绝缨解带一为欢。","李颀 绝缨歌"]]},{"n":"蒙锦绣","d":"","s":"《史记》卷一二六《滑稽列传》","q":[["驽骀蒙锦绣，尘土浴潺湲。","杜牧 往年随故府吴兴公夜泊芜湖口今赴官西去再宿芜湖感旧伤怀因成十六韵"]]},{"n":"螳螂捕蝉","d":"雀伺螳螂：喻只瞻前而不顾后，或喻侵犯。五代前蜀韦庄《和郑拾遗秋日感事一百韵》：“人心惊獬豸，雀意伺螳螂。”","s":"《韩诗外传》卷十第二十一章","q":[["人心惊獬豸，雀意伺螳螂。","韦庄 和郑拾遗秋日感事一百韵"],["隐榆非谏楚，噪柳异悲潘。","骆宾王 秋晨同淄川毛司马秋九咏秋蝉"]]}],"306":[{"n":"宁家宅","d":"宅相：称美外甥。唐李白《赠别从甥高五》：“能成吾宅相，不减魏阳元。”","s":"《晋书》卷四十一《魏舒传》","q":[["思君宁家宅，久接竹林期。","司空曙 哭苗员外呈张参军（苗公即参军舅氏）"],["能成吾宅相，不减魏阳元。","李白 赠别从甥高五"]]},{"n":"襆被","d":"","s":"《晋书》卷四十一《魏舒传》","q":[["到来恒襆被，随例且含香。","岑参 省中即事"]]},{"n":"画筹","d":"","s":"《晋书》卷四十一《魏舒传》","q":[["今日竞飞杨叶箭，魏舒休作画筹人。","唐彦谦 试夜题省郎柱"],["载笔念无能，捧筹惭所画。","杜牧 偶游石盎僧舍"]]},{"n":"魏舒","d":"","s":"《晋书》卷四十一《魏舒传》","q":[["魏舒堂堂，周舍鄂鄂。","李瀚 蒙求"],["魏舒终有泪，还识宁家衣。","卢纶 送从舅成都丞广归蜀"]]}],"307":[{"n":"郊岛","d":"","s":"《苏轼文集》卷六三〈祭柳子玉文〉","q":[["元轻白俗，郊寒岛瘦。嘹然一吟，众作卑陋。","苏轼 祭柳子玉文"]]},{"n":"月下敲门","d":"","s":"《鉴戒录》卷八〈贾忤旨〉","q":[]},{"n":"推敲","d":"推敲：指作诗文时反复斟酌字句，或指对事情反复考虑。宋楼钥《蒋慈溪鹗挽词》：“推敲诗益炼，骈俪语尤工。”","s":"《鉴戒录》卷八〈贾忤旨〉","q":[]},{"n":"文魔贾岛","d":"","s":"《新唐书》卷一百七十六〈韩愈列传·贾岛〉","q":[]}],"308":[{"n":"德如闵骞","d":"","s":"《论语注疏·先进》","q":[]},{"n":"闵损衣单","d":"","s":"《太平御览》卷四一三","q":[["王褒柏惨，闵损衣单。","李瀚 蒙求"]]},{"n":"十哲","d":"","s":"《旧唐书》卷二十四〈礼仪志四〉","q":[]},{"n":"颜闵","d":"","s":"《论语·先进》","q":[["儒风久沦弊，颜闵寿不长。","刘商 哭韩淮端公兼上崔中丞"],["羁离交屈宋，牢落值颜闵。","杜甫 赠郑十八贲"]]}],"309":[{"n":"开三径","d":"三径：指家园，或喻归隐。唐孟浩然《秦中感秋寄远上人》：“一丘常欲卧，三径苦无资。”","s":"《昭明文选》卷四十五〈对问设论辞序上·辞·归去来〉","q":[["入门堪笑复堪怜，三径苔荒一钓船。","伍唐圭 寒食日献郡守"],["关山云尽九秋月，门柳叶凋三径霜。","刘沧 秋日夜怀"]]},{"n":"卜邻羊仲求仲","d":"","s":"《昭明文选》卷三十〈诗己·杂诗下·田南树园激流植援〉","q":[]},{"n":"蒋径","d":"","s":"《太平御览》卷四百九〈人事部五十·交友四〉2～","q":[]},{"n":"蒋元卿","d":"","s":"《汉书》卷七十二《王贡两龚鲍传》","q":[["不复由莱径，无由见蒋生。","封孟绅 赋得行不由径"],["尚子不可见，蒋生难再逢。","岑参 自潘陵尖还少室居止秋夕凭眺"]]}],"310":[{"n":"白虎议","d":"","s":"《后汉书》卷三《章帝纪》","q":[["议高通白虎，谏切伏青蒲。","白居易 东南行一百韵寄通州元九侍御澧州李十一舍人果州崔二十二使君开州韦大员外庾三十二补阙杜十四拾遗李二十助教员外窦七校书（元稹集和此诗注内本题末尚有兼投吊席八舍人七字）"]]},{"n":"侧席","d":"","s":"《后汉书》卷三〈肃宗孝章帝纪〉","q":[["见说圣君能仄席，不知谁是请长缨。","崔涂 己亥岁感事"],["顺风求至道，侧席问遗贤。","钱起 温泉宫礼见"]]},{"n":"管埋舜祠","d":"","s":"《风俗通义》卷六《声音》","q":[["唯留一管人间吹，无德不能得此管，此管沈埋虞舜祠。","李贺 苦篁调啸引"]]},{"n":"题剑","d":"","s":"《东观汉记》卷二〈肃宗孝章皇帝纪〉","q":[["空馀济南剑，天子署高名。","崔融 户部尚书崔公挽歌"],["汉章题楚剑，郑武袭缁衣。","沈佺期 和户部岑尚书参迹枢揆"]]}],"311":[{"n":"易水寒","d":"燕丹客：喻勇士。唐骆宾王《送郑少府人辽共赋快客运从戎》：“不学燕丹客，空歌易水寒。”","s":"《史记》卷八十六〈刺客列传·荆轲〉","q":[["须知易水歌，至死无悔吝。","李咸用 猛虎行"],["击筑饮美酒，剑歌易水湄。","李白 少年行二首"]]},{"n":"贯日","d":"","s":"《战国策》卷二十五〈魏策四·秦王使人谓安陵君〉","q":[]},{"n":"聂政姊","d":"","s":"《战国策》卷二十七〈韩策二〉","q":[["何惭聂政姊，万古共惊嗟。","李白 秦女休行"]]},{"n":"入韩剑客","d":"","s":"《战国策》卷二十七〈韩策二〉","q":[["入韩非剑客，过赵受钳奴。","李商隐 哭虔州杨侍郎"]]}],"312":[{"n":"金汤","d":"","s":"《汉书》卷四十五〈蒯伍江息夫列传·蒯通〉","q":[["金汤既失险，玉石乃同焚。","孔绍安 别徐永元秀才"],["尧行道德终无敌，秦把金汤可自由。","李山甫 上元怀古二首"]]},{"n":"蒯通言","d":"","s":"《史记》卷九十二〈淮阴侯列传〉","q":[]},{"n":"中原逐鹿","d":"","s":"《史记》卷九十二〈淮阴侯列传·蒯通〉","q":[["中原逐鹿罢，高祖郁龙骧。","吴少微 过汉故城"],["既迷秦帝鹿，难问贾生雕。","唐彦谦 咸通中始闻褚河南归葬阳翟是岁上平徐方大肆庆赏又诏八品锡其裔孙追叙风概因成二十韵"]]},{"n":"乞火","d":"乞火：指为人排解纠纷。唐杜牧《酬张枯处士见寄长句四韵》：“荐衡昔日知文举，乞火无人作蒯通。”","s":"《汉书》卷四十五《蒯通传》","q":[["自愧扫门士，谁为乞火人。","杜牧 寄崔钧"],["荐衡昔日知文举，乞火无人作蒯通。","杜牧 酬张祐处士见寄长句四韵"]]}],"313":[{"n":"两谢","d":"","s":"《宋书》卷五十六〈谢瞻列传〉","q":[]},{"n":"谢中书","d":"","s":"《宋书》卷五十六《谢瞻传》","q":[["载笔已齐周右史，论诗更事谢中书。","韩翃 访王起居不遇留赠"]]},{"n":"宣远","d":"","s":"《宋书》卷五十六〈谢瞻列传〉","q":[["他日新诗应见报，还如宣远在安城。","韩翃 送中兄典邵州"]]},{"n":"遵渚来鸿","d":"","s":"《诗经·豳风·九罭》","q":[["栖枝犹绕鹊，遵渚未来鸿。","骆宾王 月夜有怀简诸同病"]]}],"314":[{"n":"汉武眼穿","d":"","s":"《汉书》卷九十七上《外戚传·孝武李夫人传》","q":[["亚水依岩半倾侧，笼云隐雾多愁绝。绿珠语尽身欲投，汉武眼穿神渐灭。","元稹 山枇杷"],["纵有迎仙术，终悲隔绛纱。","窦叔向 贞懿皇后挽歌三首之二"]]},{"n":"李夫人","d":"","s":"《汉书》卷九十七上《外戚传上·孝武李夫人传》","q":[["秾艳三千临粉镜，独悲掩面李夫人。","司空图 力疾山下吴村看杏花十九首之十"],["屏上楼台陈后主，镜中金翠李夫人。","温庭筠 和道溪君别业"]]},{"n":"李延年","d":"","s":"《汉书》卷九十三《佞幸传·李延年传》","q":[["若逢汉武帝，还是李延年。","梁锽 戏赠歌者"],["延年女弟双凤入，罗敷使君千骑归。","骆宾王 帝京篇"]]},{"n":"赵李经过","d":"","s":"《昭明文选》卷二十三〈诗丙·咏怀·咏怀诗十七首〉","q":[["城中相识尽繁华，日夜经过赵李家。","王维 洛阳女儿行"],["田窦方贵幸，赵李新相知。","郑愔 少年行"]]}],"315":[{"n":"市骏","d":"","s":"《战国策》卷二十九〈燕策一·燕昭王收破燕后即位〉","q":[["骏骨黄金买，英髦绛帐延。","元稹 献荥阳公诗五十韵（并启）"],["燕昭不是空怜马，支遁何妨亦爱鹰。","司空图 退栖"]]},{"n":"黄金台","d":"黄金台：指招贤之所。唐李白《南奔书怀》：“侍笔黄金台，传觞青玉案。”","s":"《战国策》卷二十九〈燕策一·燕昭王收破燕后即位〉","q":[["此去黄金台上客，相思应羡雁南归。","刘沧 送友人罢举赴蓟门从事"],["若使解言天下事，燕台今筑几千金。","司空图 喜山鹊初归三首之二"]]},{"n":"燕馆","d":"","s":"《战国策》卷二十九《燕策一》","q":[["只惭燕馆盛，宁觉阮途穷。","吴融 赴阙次留献荆南成相公三十韵"]]},{"n":"尊乐毅","d":"","s":"《战国策》卷二十九《燕策一》","q":[["燕王尊乐毅，分国愿同欢。","陈子昂 感遇诗三十八首之十六"]]}],"316":[{"n":"投杖","d":"龙竹：喻得道成仙，或指竹杖。唐王绩《游仙四首》之四：“鸭桃闻已种，龙竹未经骑。”","s":"《太平广记》卷十二〈神仙十二·壶公〉","q":[["浅忆觞堪泛，深思杖可投。","吴融 御沟十六韵"],["叶县凫共去，葛陂龙暂还。","岑参 寻少室张山人闻与偃师周明府同入都"]]},{"n":"长房萸","d":"","s":"《续齐谐记》","q":[["长房萸早熟，彭泽菊初收。","李显 九月九日幸临渭亭登高得秋字"]]},{"n":"费长房","d":"","s":"《后汉书》卷八十二下《方术传·费长房传》","q":[["思量费子真仙子，不作头陀山下尘。","来鹄 鄂渚清明日与乡友登头陀山"],["长房自贵解飞翻，五色云中独闭门。看却桑田欲成海，不知还往几人存。","曹唐 小游仙诗九十八首"]]},{"n":"缩地","d":"长房术：咏仙术，亦指赶路心情急切而倍道兼行。唐岑参《安西馆中思长安》：“遥凭长房术，为缩地山东。”","s":"《神仙传》卷五《壶公传》","q":[["壶中药物梯霞诀，肘后方书缩地功。","令狐楚 赠毛仙翁"],["同受新年不同赏，无由缩地欲如何。","元稹 和乐天早春见寄"]]}],"317":[{"n":"歌钟重锡","d":"","s":"《春秋左传·襄公十一年》","q":[["和戎因赏魏，定远莫辞班。","张说 送郑大夫惟忠从公主入蕃"],["歌钟期重锡，拜手落花春。","杜审言 送高郎中北使"]]},{"n":"戮仆","d":"","s":"《春秋左传·襄公三年》","q":[["放纵是谁之过欤，效尤戮仆愧前史。","韩愈 寄卢仝"]]},{"n":"魏绛","d":"","s":"《春秋左传·襄公四年》","q":[["卫青师自老，魏绛赏何功。","戎昱 泾州观元戎出师"],["魏绛言堪采，陈汤事偶成。","杜牧 夏州崔常侍自少常亚列出领摩幢十韵"]]},{"n":"五利功","d":"","s":"《春秋左传正义》卷二十九〈襄公·传四年〉","q":[["百年徒有伊川叹，五利宁无魏绛功。","吴融 金桥感事"],["青史书归日，翻轻五利功。","权德舆 送张曹长工部大夫奉使西番"]]}],"318":[{"n":"捕风系影","d":"","s":"《汉书》卷二十五下《郊祀志下》","q":[["捕风兼系影，信矣不须争。","贯休 贻世"]]},{"n":"谷永笔札","d":"","s":"《汉书》卷九十二《游侠传·楼护传》","q":[["谷永笔札，顾恺丹青。","李瀚 蒙求"]]},{"n":"谷永才","d":"","s":"《汉书》卷八十五《谷永杜邺传》","q":[["才非谷永传，无意谒王侯。","武元衡 夏日对雨寄朱放拾遗"]]},{"n":"谷永言事","d":"","s":"《汉书》卷八十五《谷永传》","q":[["谷水直言身不顾，郤诜高第转名香。","韩翃 别氾水县尉"],["谷永独言事，匡衡多引经。","高适 奉酬北海李太守丈人夏日平阴亭"]]}],"319":[{"n":"成羽翼","d":"","s":"《史记》卷五十五〈留侯世家〉","q":[]},{"n":"舂市徒","d":"","s":"《汉书》卷九十七上《外戚传上·高祖吕皇后传》","q":[["戚姬髡剪入舂市，万古共悲辛。","李白 中山孺子妾歌"],["昔称夭桃子，今为舂市徒。","陈子昂 感遇诗三十八首之十五"]]},{"n":"护汉储","d":"","s":"《汉书》卷四十《张良传》","q":[["汉宫成羽翼，伊水弄参差。","储光羲 河中望鸟滩作贻吕四郎中"],["卒能匡惠帝，岂不赖留侯。","张说 赠崔公"]]},{"n":"左袒","d":"","s":"《汉书》卷三《高后纪》","q":[["南军不袒左边袖，四老安刘是灭刘。","杜牧 题商山四皓庙一绝"],["烈烈张汉阳，左袒清诸武。","皇甫澈 赋四相诗（并序）赋四相诗（并序）赋四相诗（并序）中书令钟绍京赋四相诗（并序）赋四相诗（并序）礼部尚书门下侍平章事李山见赋四相诗（并序），赋四相诗（并序）门下侍郎平章事王缙"]]}],"320":[{"n":"粉郎","d":"何郎：称赞青年男子貌美，或指情郎或驸马。唐李贺《同沈驸马赋得御沟水》：“幸因流浪处，暂得见何郎。”","s":"《世说新语笺疏》下卷上〈容止〉","q":[["汤饼赐都尉，寒冰颁上才。","刘禹锡 翠微寺有感"],["何郎独在无恩泽，不似当初傅粉时。","刘禹锡 题于家公主旧宅"]]},{"n":"玉树连","d":"","s":"《世说新语》下卷上《容止》","q":[["共济已惊依玉树，随流还许醉金觞。","刘威 晚春陪王员外东塘游宴"],["小小豫章甲，纤纤玉树姿。","孟郊 子庆诗"]]},{"n":"金狄移","d":"","s":"《三辅黄图》卷三〈建章宫·神明台〉","q":[["金狄移灞岸，铜盘向洛阳。","王绩 过汉故城"]]},{"n":"双璧蒹葭","d":"","s":"《世说新语笺疏》下卷上〈容止〉","q":[]}],"321":[{"n":"枚皋谈笑","d":"","s":"《汉书》卷五十一〈贾邹枚路传·枚乘·（子）枚皋～〉2367～","q":[]},{"n":"枚皋扈仙跸","d":"","s":"《汉书》卷五十一〈贾邹枚路传·枚乘·（子）枚皋～〉2366～","q":[["目断枚皋何处在，阑干十二忆登临。","吴融 八月十五夜禁直寄同僚"],["待得枚皋相见日，自应妆镜笑蹉跎。","杜牧 见刘秀才与池洲妓别"]]},{"n":"枚皋文敏","d":"","s":"《汉书》卷五十一〈贾邹枚路传·枚乘·（子）枚皋～〉2366～","q":[]},{"n":"少孺能赋","d":"","s":"《汉书》卷五十一《枚乘传》附《枚皋传》","q":[["少孺嘉能赋，文强阅赐书。","寇坦 同张少府和厍狄员外夏晚初霁南省寓直时兼充节度判官之作"]]}],"322":[{"n":"田横客","d":"","s":"《史记》卷九十四《田儋列传》","q":[["纵使将军能伏剑，何人岛上哭田横。","李涉 哭田布"],["李陵初诗，田横感歌。","李瀚 蒙求"]]},{"n":"齐横降","d":"","s":"《史记》卷九十四《田儋列传》附《田横传》","q":[["势侔高阳翁，坐约齐横降。","韩愈 病中赠张十八"]]},{"n":"田横岛","d":"","s":"《史记》卷九十四《田儋列传》附《田横传》","q":[["苏武天山上，田横海岛边。","李白 奔亡道中五首之一"],["已闻陈胜心降汉，谁为田横国号齐。","韦庄 赠云阳裴明府"]]},{"n":"五百人","d":"","s":"《史记》卷九十四《田儋列传》附《田横传》","q":[["海上五百人，同日死田横。","李白 于五松山赠南陵常赞府"],["三千客里宁无义，五百人中必有恩。","许浑 闻边将刘皋无辜受戮"]]}],"323":[{"n":"酷似","d":"","s":"《晋书》卷八十五《何无忌传》","q":[["辕门拜首儒衣弊，貌似牢之岂不怜。","刘长卿 送秦侍御外甥张篆之福州谒鲍大夫秦侍御与大夫有旧"],["徐庶高交友，刘牢出外甥。","杜甫 奉送二十三舅录事（崔伟）之摄郴州"]]},{"n":"田舍翁","d":"","s":"《宋书》卷三《武帝纪下》","q":[["奈何田舍翁，受此厚贶情。","杜甫 太子张舍人遗织成褥段"]]},{"n":"外甥似舅","d":"","s":"《晋书》卷八十五〈何无忌列传〉","q":[]},{"n":"戏马会","d":"","s":"《昭明文选》卷二十南朝宋·谢宣远（瞻）《九日从宋公戏马台集送孔令》","q":[["方知戏马会，永谢登龙宾。","孟郊 南阳公请东樱桃亭子春宴"]]}],"324":[{"n":"高闾","d":"","s":"《汉书》卷七十一〈隽疏于薛平彭列传·于定国〉","q":[["于公必有高门庆，谢守何烦晓镜悲。","刘禹锡 苏州白舍人寄新诗有叹早白无儿之句因以赠之"]]},{"n":"定国精明","d":"","s":"《汉书》卷七十一〈隽疏于薛平彭列传·于定国〉","q":[["精明如定国，孤峻似陈蕃。","杜牧 奉送中丞姊夫俦自大理卿出镇江西叙事书怀因成十二韵"]]},{"n":"于家决狱","d":"","s":"《汉书》卷七十一〈隽疏于薛平彭列传·于定国〉","q":[["直氏偷金枉，于家决狱明。","刘长卿 按覆后归睦州赠苗侍御"]]},{"n":"于张","d":"","s":"《昭明文选》卷五十六〈箴铭诔上·诔上·杨荆州诔〉","q":[["于张惩不滥，陈郭宪无倾。","虞世南 赋得慎罚"]]}],"325":[{"n":"八凯","d":"","s":"《史记》卷一〈五帝本纪·帝舜〉","q":[["谢太傅须同八凯，姚梁公可并三台。","贯休 蜀王入大慈寺听讲"],["人知八凯须当国，猿到三声不用愁。","贯休 送薛侍郎贬峡州司马"]]},{"n":"八族","d":"","s":"《史记》卷一《五帝本纪·舜本纪》","q":[["八族未来谁北拱，四凶犹在莫南巡。","罗隐 湘妃庙"]]},{"n":"高阳多夔龙","d":"","s":"《春秋左传·文公十八年》","q":[["高阳多夔龙，荆山积玙璠。","王维 同卢拾遗过韦给事东山别业二十韵给事首春休沐维已陪游及乎是行亦预闻命会无车马不果斯诺"]]},{"n":"十六族","d":"","s":"《史记》卷一《武帝本纪》","q":[["岂唯十六族，今古称其贤。","权德舆 酬穆七侍郎早登使院西楼感怀"]]}],"326":[{"n":"操刀割","d":"","s":"《春秋左传·襄公三十一年》","q":[["未得操割效，忽复寒暑移。","张九龄 在郡秋怀二首之一"],["操刀尝愿割，持斧竟称雄。","张九龄 酬赵二侍御使西军赠两省旧僚之作"]]},{"n":"如旧识","d":"","s":"《春秋左传·襄公二十九年》","q":[["同宿李翱家，一言如旧识。","白居易 伤唐衢二首之一"]]},{"n":"赠缟","d":"","s":"《春秋左传·襄公二十九年》","q":[["既闻留缟带，讵肯掷蓍簪。","韦庄 同旧韵"],["缔交君赠缟，投分我忘筌。","骆宾王 夏日游德州赠高四"]]},{"n":"制锦","d":"","s":"《春秋左传正义》卷四十〈襄公·传三十一年〉","q":[["制锦不择地，操刀良在兹。","李白 赠徐安宜"]]}],"327":[{"n":"访莘","d":"","s":"《孟子》卷九下《万章上》","q":[["迹岩劳傅想，窥野访莘情。","李世民 春日登陕州城楼俯眺原野回丹碧缀烟霞密翠班红芳菲花柳即目川岫聊以命篇"]]},{"n":"开三面","d":"祝网：称颂仁政。唐杜甫《秋日荆南述怀》：“垂旒资穆穆，祝网但恢恢。”","s":"《吕氏春秋·纪部》卷十〈孟冬纪·异用〉","q":[["网已袪三面，歌因守四方。","常衮 奉和圣制麟德殿燕百僚应制"],["罗网开三面，闾阎问百年。","张嘉贞 奉和早登太行山中言志应制"]]},{"n":"三危露","d":"","s":"《吕氏春秋·览部》卷十四〈孝行览·本〉","q":[]},{"n":"徯帝情","d":"","s":"《尚书·商书·仲虺之诰》","q":[["凤辇幸秦久，周人徯帝情。","钱起 送蒋尚书居守东都"]]}],"328":[{"n":"郗超","d":"","s":"《世说新语笺疏》下卷上〈宠礼〉","q":[["明日郗超会，应思下客同。","司空曙 酬郑十四望驿不得同宿见赠因寄张参军"],["王粲名虽重，郗超髯未长。","李端 送从叔赴洪州"]]},{"n":"令公喜","d":"","s":"《世说新语笺疏》下卷上〈宠礼〉","q":[]},{"n":"入幕","d":"","s":"《晋书》卷六十七〈郗鉴列传·（郗愔子）郗超〉","q":[]},{"n":"郗嘉宾","d":"","s":"《晋书》卷六十七〈郗鉴列传·（郗愔子）郗超〉","q":[]}],"329":[{"n":"房魏","d":"","s":"《旧唐书》卷七十一〈魏徵列传〉","q":[["呜呼房魏不复见，秦王学士时难羡。","杜甫 折槛行"]]},{"n":"魏徵妩媚","d":"","s":"《新唐书》卷九十七〈魏徵列传〉","q":[]},{"n":"魏徵直言","d":"","s":"《新唐书》卷九十七〈魏徵列传〉","q":[]},{"n":"一言回天力","d":"","s":"《新唐书》卷一百三〈张玄素列传〉","q":[]}],"330":[{"n":"玉川奴","d":"","s":"《全唐诗》卷三百四十〈寄卢仝〉【案：宪宗元六年河南令时作。】","q":[]},{"n":"琢玉郎","d":"","s":"《全唐诗》卷三百八十八〈与马异结交〉","q":[]},{"n":"清风生两腋","d":"","s":"《全唐诗》卷三百八十八〈走笔谢孟谏议寄新茶〉","q":[]},{"n":"玉川","d":"","s":"《新唐书》卷一百七十六〈韩愈列传·卢仝〉","q":[]}],"331":[{"n":"抱膝吟","d":"","s":"《三国志》卷三十五《蜀书·诸葛亮传》","q":[["羁栖摧剪平生志，抱膝时为梁甫吟。","李群玉 长沙紫极宫雨夜愁坐"],["维舟倚前浦，长啸一含情。","杜甫 公安县怀古"]]},{"n":"孔明有知音","d":"","s":"《三国志》卷三十五〈蜀书·诸葛亮传〉","q":[["嵇康不得死，孔明有知音。","杜甫 遣兴五首之一（黄鹤本以陶潜、贺公、孟浩然三首入庞德公一首后。）"],["子房仙去孔明死，更有何人解指踪。","费冠卿 閒居即事"]]},{"n":"孔明故事","d":"","s":"《三国志》卷三十五〈蜀书·诸葛亮传〉","q":[["孔明多故事，安石竟崇班。","杜甫 承闻故房相公灵榇自阆州启殡归葬东都有作二首之一"]]},{"n":"七擒","d":"七擒略：指运用智计使人彻底折服。唐李白《书怀赠南陵常赞府》：“将无七擒略，鲁女惜园葵。”","s":"《三国志》卷三十五〈蜀书·诸葛亮传〉","q":[["将无七擒略，鲁女惜园葵。","李白 书怀赠南陵常赞府"],["三捷岂云尔，七擒良信然。","苏晋 奉和圣制送张说巡边"]]}],"332":[{"n":"长岑长","d":"","s":"《后汉书》卷五十二《崔骃传》","q":[["惆怅长岑长，寂寞梁王傅。","储光羲 贻王侍御出台掾丹阳"]]},{"n":"崔亭伯","d":"","s":"《后汉书》卷五十二《崔骃传》","q":[["忽枉崔骃什，兼流韦孟词。","张说 酬崔光禄冬日述怀赠答"],["故交竟谁在，独有崔亭伯。","李白 宣州九日闻崔四侍御与宇文太守游敬亭余时登向山不同此赏醉后寄崔侍御二首之一"]]},{"n":"渡辽水","d":"","s":"《后汉书》卷五十二〈崔骃列传·崔骃〉","q":[["始知亭伯去，还是拙谋身。","崔湜 至桃林塞作"],["屈原憔悴滞江潭，亭伯流离放辽海。","李白 单父东楼秋夜送族弟沈之秦"]]},{"n":"亭伯雄词","d":"","s":"《后汉书》卷五十二〈崔骃列传·崔骃〉","q":[["酷似仰牢之，雄词挹亭伯。","权德舆 奉和崔评事寄外甥刘同州并呈杜宾客许给事王侍郎昆弟杨少尹李侍御并见寄之作"]]}],"333":[{"n":"长岑长","d":"","s":"《后汉书》卷五十二《崔骃传》","q":[["惆怅长岑长，寂寞梁王傅。","储光羲 贻王侍御出台掾丹阳"]]},{"n":"窦宪","d":"","s":"《后汉书》卷二十三《窦融传》附《窦宪传》","q":[["遂别鲁诸生，来从窦车骑。","李益 来从窦车骑行"],["步兵校尉辞公府，车骑将军忆本朝。","罗隐 得宣州窦尚书书因投寄二首之二"]]},{"n":"勒燕然","d":"勒燕然：咏边塞立功。唐姚合《送任响评事赴沂海》：“孟坚勒燕然，岂独在汉朝？”","s":"《张璠后汉纪·和帝纪·永元二年》","q":[["燕然山上云，半是离乡魂。","于濆 塞下曲"],["空留一片石，万古在燕山。","刘长卿 平蕃三首之三"]]},{"n":"渡辽水","d":"","s":"《后汉书》卷五十二〈崔骃列传·崔骃〉","q":[["始知亭伯去，还是拙谋身。","崔湜 至桃林塞作"],["屈原憔悴滞江潭，亭伯流离放辽海。","李白 单父东楼秋夜送族弟沈之秦"]]}],"334":[{"n":"二郎作相","d":"","s":"《邵氏闻见录》卷六","q":[]},{"n":"槐府","d":"","s":"《周礼注疏》卷三十五〈秋官司寇·朝士〉","q":[]},{"n":"王氏三槐","d":"","s":"《周礼注疏》卷三十五〈秋官司寇·朝士〉","q":[]},{"n":"三槐堂","d":"","s":"《苏轼文集》卷十九〈三槐堂铭〉","q":[]}],"335":[{"n":"贰师","d":"","s":"《汉书》卷六十一〈张骞李广利列传·李广利〉","q":[["来参八骏列，不假贰师功。","周存 西戎献马"],["天子预开麟阁待，祗今谁数贰师功。","岑参 献封大夫破播仙歌六章"]]},{"n":"轮台归汉","d":"","s":"《汉书》卷六十一《李广利传》","q":[["尝读西域传，汉家得轮台。","岑参 登北庭北楼呈幕中诸公"]]},{"n":"闭玉门","d":"","s":"《史记》卷一二三《大宛列传》","q":[["塞下长驱汗血马，云中恒闭玉门关。","李昂 从军行"],["闻道玉门犹被遮，应将性命逐轻车。","李颀 古从军行"]]},{"n":"征大宛","d":"","s":"《汉书》卷九十六上《西域传上》","q":[["今日歌天马，非关征大宛。","储光羲 和张太祝冬祭马步"]]}],"336":[{"n":"老汉滨","d":"","s":"《后汉书》卷六十二《荀淑传》附《荀爽传》","q":[["近更婴衰疾，空思老汉滨。","李端 送友入关（一本题上有代从兄衡四字）"]]},{"n":"无双誉","d":"","s":"《后汉书》卷六十二〈荀淑列传·（子）荀爽〉","q":[["家擅无双誉，朝居第一功。","李商隐 今月二日不自量度辄以诗一首四十韵干渎尊严伏蒙仁恩俯赐披览奖逾其实"]]},{"n":"荀家头龙","d":"","s":"《后汉书》卷六十二〈荀韩钟陈列传·荀淑〉","q":[["贾氏许频趋季虎，荀家因敢谒头龙。","黄滔 投翰长赵侍郎"]]},{"n":"荀爽","d":"","s":"《后汉书》卷六十二〈荀淑列传·（子）荀爽〉","q":[["韦玄方继相，荀爽复齐名。","张九龄 故徐州刺史赠吏部侍郎苏君挽歌词三首"]]}],"337":[{"n":"二十五老","d":"","s":"《说苑》卷八〈尊贤〉","q":[["虽无二十五老者，且有一翁钱少阳。","李白 赠潘侍御论钱少阳"]]},{"n":"焚山林","d":"","s":"《庄子集释》卷九下〈杂篇·盗蹠〉","q":[]},{"n":"介推","d":"介推：咏雅逸或寒食。唐顾况《拟古三首》之三：“浮生果何慕，老去羡介推。”；子推：代指寒食。唐孟云卿《寒食》：“贫居往往无烟火，不独明朝为子推。”","s":"《后汉书》卷六十一〈左周黄列传·周举〉","q":[["累重虽然容食椹，力微无计报焚林。","吴仁璧 投谢钱武肃"],["贫居往往无烟火，不独明朝为子推。","孟云卿 寒食"]]},{"n":"绵上隐","d":"","s":"《春秋左传·僖公二十四年》","q":[["欲追绵上隐，况近子平村。","李德裕 近于伊川卜山居将命者画图而至欣然有感聊赋此诗兼寄上浙东元相公大夫使求青田胎化鹤"]]}],"338":[{"n":"耳馀","d":"","s":"《汉书》卷三十二〈张耳陈馀列传·陈馀〉","q":[]},{"n":"随厮养","d":"","s":"《史记》卷八十九《张耳陈馀列传》","q":[["才淑随厮养，名贤隐锻炉。","杜甫 过南岳入洞庭湖"]]},{"n":"斩成安","d":"","s":"《史记》卷九十二〈淮阴侯列传〉","q":[["今朝拜韩信，计日斩成安。","王涯 从军词三首"]]},{"n":"张陈","d":"","s":"《史记》卷八十九《张耳陈馀列传》","q":[["松篁贞管鲍，桃李艳张陈。","李咸用 论交"],["张陈竟火灭，萧朱亦星离。","李白 古风"]]}],"339":[{"n":"九龄风度","d":"","s":"《旧唐书》卷九十九〈张九龄列传〉","q":[]},{"n":"九龄疏谏","d":"","s":"《旧唐书》卷九十九〈张九龄列传〉","q":[]},{"n":"张九龄贬荆州","d":"","s":"《新唐书》卷一百二十六〈张九龄列传〉","q":[]},{"n":"张子寿","d":"","s":"《旧唐书》卷九十九〈张九龄列传〉","q":[]}],"340":[{"n":"落帽风","d":"孟嘉帽：喻气度非凡，潇洒倜傥。唐独孤及《九月九日李苏州东楼宴》：“风前孟嘉帽，月下庾公楼。”；龙山：喻欢宴。唐末湾《重阳日陪韦卿宴》：“何必龙山好，南亭赏不睽。”","s":"《全上古三代秦汉三国六朝文·全晋文》卷一百十二〈陶潜·晋故征西大将军长史孟府君传","q":[["贵重近臣光绮席，笑怜从事落乌纱。","令孤楚 奉和严石空重阳日同崔常侍崔郎及诸公登龙山落帽台佳宴"],["登楼王粲望，落帽孟嘉情。","元稹 答姨兄胡灵之见寄五十韵"]]},{"n":"酒中趣","d":"","s":"《晋书》卷九十八《桓温传》附《孟嘉传》","q":[["但得酒中趣，勿为醒者传。","李白 月下独酌四首之二"]]},{"n":"可能无势，我驾驭卿","d":"","s":"《全上古三代秦汉三国六朝文·全晋文》卷一百十二〈陶潜·晋故征西大将军长史孟府君传","q":[]},{"n":"孟参军","d":"孟参军：指极有风仪之人。唐严维《九日陪崔郎中北山宾》：“府中官最小，唯有孟参军”","s":"《全上古三代秦汉三国六朝文·全晋文》卷一百十二〈陶潜·晋故征西大将军长史孟府君传","q":[["昨日已尝村酒熟，一杯思与孟嘉倾。","张南史 春日道中寄孟侍御"],["妙曲逢卢女，高才得孟嘉。","张子嘉 除夜乐城逢孟浩然"]]}],"341":[{"n":"安世","d":"","s":"《汉书》卷五十九《张汤传》附《张安世传》","q":[["累相承安世，深筹协子房。","徐坚 奉和圣制送张说巡边"]]},{"n":"安世三箧","d":"","s":"《汉书》卷五十九《张汤传》附《张安世传》","q":[["应奉五行，安世三箧。","李瀚 蒙求"],["汉使收三箧，周诗采百篇。","李端 送耿拾遗湋使江南括图书"]]},{"n":"麒麟阁","d":"","s":"《汉书》卷五十四〈李广苏建列传·苏武〉","q":[["若非载笔登麟阁，定是吹箫伴凤台。","于季子 早春洛阳答杜审言"],["新登麒麟阁，适脱獬豸冠。","岑参 送张秘书充刘相公通汴河判官便赴江外觐省"]]},{"n":"金张","d":"七叶贵：喻世代显贵。唐王昌龄《留别岑参兄弟》：“貂蝉七叶贵，鸿鸽万里游。”","s":"《昭明文选》卷二十一〈诗乙·咏史·咏史八首〉","q":[["貂蝉七叶贵，鸿鹄万里游。","王昌龄 留别岑参兄弟"],["芳草落花无限，金张许史相随。","丘丹 忆长安四月"]]}],"342":[{"n":"倒戟","d":"","s":"《春秋左传正义》卷二十一〈宣公·传二年〉","q":[["一饭意专堪便死，千金诺在转难酬。","吴融 离霅溪感事献郑员外"],["嗟嗟邓大夫，士卒终倒戟。","杜甫 八哀诗赠司空王公思礼"]]},{"n":"董狐笔","d":"董狐直笔：咏史官秉笔直书，刚正不阿。宋黄庭坚《王彦祖惠其祖黄州制草书其后》：“董狐常直笔，汲黯少居中。”","s":"《春秋左传正义》卷二十一〈宣公·传二年〉","q":[["惟我之有颂兮，奚斯跃而董狐蹶。","来鹄 圣政纪颂"],["祸首燧人氏，厉阶董狐笔。","杜甫 写怀二首之二"]]},{"n":"翳桑顾求","d":"","s":"《春秋左传·宣公二年》","q":[["野悲扬目称嗟食，林极翳桑顾所求。","李绅 却到浙西"]]},{"n":"赵孤存","d":"","s":"《史记》卷四十五〈韩世家〉","q":[]}],"343":[{"n":"补衮","d":"","s":"《诗经·大雅·烝民》","q":[["龙衮期重补，梅羹伫再和。","令孤楚 将赴洛下旅次汉南献上相公二十兄言怀八韵"],["昔年叨补衮，边地亦埋轮。","孙逖 送李补阙摄御史充河西节度判官"]]},{"n":"喉舌","d":"","s":"《诗经·大雅·烝民》","q":[["樵苏封葬地，喉舌罢朝天。","杜甫 哭李尚书"]]},{"n":"生申","d":"","s":"《毛诗正义》卷十八之三〈大雅·荡之什·烝民〉","q":[]},{"n":"山甫","d":"","s":"《诗经·大雅·烝民》","q":[["山甫归应疾，留侯功复成。","张九龄 奉和圣制送尚书燕国公赴朔方"]]}],"344":[{"n":"华歆","d":"","s":"《三国志》卷十三〈魏书·华歆传〉","q":[["往还谁是龙头人，公主遣秉鱼须笏。","李贺 酒罢张大彻索赠诗（时张初效潞幕）"],["班资冠鸡舌，人品压龙头。","罗隐 寄礼部郑员外"]]},{"n":"割席管宁","d":"","s":"《裴子语林》","q":[]},{"n":"管宁榻","d":"管宁床：咏勤学，或指行事端正。清叶燮《叠韵答学山侄》：“漂泊未归元亮宅，支离合老管宁床。”","s":"《高士传》卷下","q":[["管宁穿亦坐，徐孺去常悬。","李德裕 思山居一十首忆葛藤木禅床"],["扁舟不独如张翰，白帽还应似管宁。","杜甫 严中丞枉驾见过"]]},{"n":"华歆忤旨","d":"","s":"《三国志》卷十三《魏书·华歆传》","q":[["华歆忤旨，陈群蹙容。","李瀚 蒙求"]]}],"345":[{"n":"九原","d":"九原：指墓地。南朝宋鲍照《松柏篇》：“永离九原亲，长与三辰隔。”唐杜甫《哭长孙侍御》：“惟余旧台柏，萧瑟九原中。”","s":"《礼记注疏》卷十〈檀弓〉","q":[["唯馀旧台柏，萧瑟九原中。","杜甫 哭长孙侍御"],["三亩空留悬磬室，九原犹寄若堂封。","柳宗元 同刘二十八哭吕衡州兼寄江陵李元二侍御"]]},{"n":"九原唤起","d":"","s":"《国语》卷十四〈晋语八·赵文子称贤随武子〉","q":[]},{"n":"九原可作","d":"九原可作：喻死者再生。唐杜牧《长安杂题长句六首》之四：“九原可作吾谁与，师友琅玡邴曼容。”","s":"《国语》卷十四〈晋语八·赵文子称贤随武子〉","q":[["九原可作吾谁与，师友琅玡邴曼容。","杜牧 长安杂题长句六首"],["九原自此无因见，反复遗踪泪万行。","罗隐 箧中得故王郎中书"]]},{"n":"赵武见韩侯","d":"","s":"《春秋左传正义》卷二十六〈成公·传八年〉","q":[["山公访嵇绍，赵武见韩侯。","李端 送诸暨裴少府"]]}],"346":[{"n":"九原可作","d":"九原可作：喻死者再生。唐杜牧《长安杂题长句六首》之四：“九原可作吾谁与，师友琅玡邴曼容。”","s":"《国语》卷十四〈晋语八·赵文子称贤随武子〉","q":[["九原可作吾谁与，师友琅玡邴曼容。","杜牧 长安杂题长句六首"],["九原自此无因见，反复遗踪泪万行。","罗隐 箧中得故王郎中书"]]},{"n":"举仇","d":"","s":"《春秋左传·襄公二十一年》","q":[["举仇且不弃，何必论亲疏。夫子觉者也，其能遗我乎。","萧颍士 仰答韦司业垂访五首"]]},{"n":"十世宥","d":"","s":"《春秋左传·襄公二十一年》","q":[["苗裔当蒙十世宥，岂谓贻厥无基阯。","韩愈 寄卢仝"]]},{"n":"叔向婴拘","d":"","s":"《春秋左传正义》卷三十四〈襄公·传二十一年〉","q":[["岂知晋叔向，无罪婴囚拘。","萧颖士 仰答韦司业垂访五首"]]}],"347":[{"n":"买山钱","d":"","s":"《世说新语》下卷下《排调》","q":[["沃洲能共隐，不用道林钱。","刘长卿 初到碧涧招明契上人"],["支遁初求道，深公笑买山。","孟浩然 宿立公房"]]},{"n":"放鹤","d":"放鹤：咏鹤僧人。唐卢纶《题念济寺晕上人院》：“放鹤临山阁，降龙步石桥。”","s":"《世说新语笺疏》上卷上〈言语〉","q":[["道林曾放雪翎飞，应悔庭除闭羽衣。","李谷 和皮日休悼鹤"],["引泉通绝涧，放鹤入孤云。","权德舆 送映师归本寺"]]},{"n":"手谈","d":"","s":"《世说新语笺疏》下卷上〈巧蓺〉","q":[]},{"n":"沃洲","d":"","s":"《高僧传》卷四《竺道潜传》","q":[["沃洲能共隐，不用道林钱。","刘长卿 初到碧涧招明契上人"],["方同沃洲去，不似武陵迷。","刘长卿 寄灵一上人初还云门"]]}],"348":[{"n":"安道","d":"","s":"《晋书》卷九十四《隐逸传·戴逵传》","q":[["情会招车胤，闲行觅戴逵。","元稹 酬翰林白学士代书一百韵"],["自此辞张邵，何由见戴逵。","刘长卿 哭张员外继"]]},{"n":"山阴道","d":"访戴：喻指访友或行事洒脱。唐李白《酬坊州王司马与间正字对雪见赠》：“访戴昔未偶，寻嵇此相得。”","s":"《世说新语笺疏》下卷上〈任诞〉","q":[["兴掩寻安道，词胜命仲宣。","刘禹锡 奉和中书崔舍人八月十五日夜玩月二十韵"],["兴比乘舟访，恩怀倒屣亲。","司空曙 送高胜重谒曹王"]]},{"n":"江南处士星","d":"","s":"《晋书》卷九十四〈隐逸列传·谢敷〉","q":[]},{"n":"戴逵破琴","d":"","s":"《晋书》卷九十四《隐逸传·戴逵传》","q":[["戴逵破琴，谢敷应星。","李瀚 蒙求"]]}],"349":[{"n":"富民侯","d":"","s":"《汉书》卷六十六《车千秋传》","q":[["岘首风烟看未足，便应重拜富民侯。","刘禹锡 奉和裴侍中将赴汉南留别座上诸公"],["兹亭有殊致，经始富人侯。","李夷简 西亭暇日书怀十二韵献上相公"]]},{"n":"九迁","d":"","s":"汉·焦延寿《易林》卷三《履·节》","q":[["邻里才三徙，云霄已九迁。","温庭筠 感旧陈情五十韵献淮南李仆射"]]},{"n":"匈奴笑千秋","d":"","s":"《汉书》卷六十六《车千秋传》","q":[["桀犬尚吠尧，匈奴笑千秋。","李白 经乱离后天恩流夜郎忆旧游书怀赠江夏韦太守良宰"],["三事或可羞，匈奴哂千秋。","李白 酬谈少府"]]},{"n":"一言悟主","d":"","s":"《汉书》卷六十六《车千秋传》","q":[["悟主一言那可学，从军五首竟徒为。","窦牟 秋夕闲居对雨赠别卢七侍御坦"]]}],"350":[{"n":"蔡泽丑","d":"","s":"《史记》卷七十九《蔡泽列传》","q":[["君不见蔡泽嵌枯诡怪之形状，大言直取秦丞相。","李白 鞠歌行"],["苏秦憔悴人多厌，蔡泽栖迟世看丑。","高适 九日酬颜少府"]]},{"n":"蔡泽无媒","d":"","s":"《史记》卷七十九《蔡泽列传》","q":[["长卿未遇杨朱泣，蔡泽无媒原宪贫。","卢纶 冬日登城楼有怀因赠程腾"]]},{"n":"功成者去","d":"","s":"《战国策》卷五〈秦策三·蔡泽见逐于赵〉","q":[]},{"n":"跃马年","d":"跃马年：指做官。唐王维《赠从弟司库员外球》：“徒闻跃马年，苦无出人智。”","s":"《史记》卷七十九《蔡泽列传》","q":[["少年跃马同心使，免得诗中道跨驴。","贾岛 送友人之南陵"],["愿奉唐生诀，将知跃马年。","陈子昂 赠严仓曹乞推命录"]]}],"351":[{"n":"富韩文范","d":"","s":"《三朝名臣言行录》卷一〈韩琦〉","q":[]},{"n":"韩范","d":"","s":"《续资治通鉴长编》卷一百二十七〈起仁宗康定元年四月尽是年六月〉","q":[]},{"n":"胸中兵甲","d":"","s":"《世说新语笺疏》下卷上〈容止〉","q":[]},{"n":"忧君范老","d":"","s":"《范文正公集》卷七〈岳阳楼记〉","q":[]}],"352":[{"n":"富韩文范","d":"","s":"《三朝名臣言行录》卷一〈韩琦〉","q":[]},{"n":"宽夫彦国","d":"","s":"《邵氏闻见录》卷十","q":[]},{"n":"洛英","d":"","s":"《邵氏闻见录》卷十","q":[]},{"n":"文富","d":"","s":"《归田录》卷一","q":[]}],"353":[{"n":"五色笔","d":"才尽：喻因年老而才思退减。唐杜甫《送顾八分文学适洪吉州》：“才尽伤形体，病渴污官位。”；江淹梦：指文采不凡。唐方干《再题路支使南亭》：“睡时分得江淹梦，五色毫端弄逸才。”","s":"《南史》卷五十九〈江淹列传〉","q":[["锦窠不是寻常锦，兼向丘迟夺得来。","司空图 少仪"],["都缘有意重熏裛，更洒江毫上玉堂。","吴融 薛舍人见徵恩赐香并二十八字同寄"]]},{"n":"鼎鱼","d":"","s":"《昭明文选》卷四十三南朝梁·丘希范（迟）《与陈伯之书》","q":[["鱼游沸鼎知无日，鸟覆危巢岂待风。","李商隐 行次昭应县道上送户部李郎中充昭义攻讨"],["鼎鱼犹假息，穴蚁欲何逃。","杜甫 喜闻将军已临贼境二十韵"]]},{"n":"邱迟","d":"","s":"《梁书》卷四十九《丘迟传》","q":[["丘迟本才子，始冠即周旋。","李端 酬丘拱外甥览余旧文见寄"],["未把彩毫还郭璞，乞留残锦与丘迟。","李群玉 寄长沙许侍御"]]},{"n":"邱迟花木","d":"","s":"《昭明文选》卷四十三南朝梁·丘希范（迟）《与陈伯之书》","q":[["江山清谢朓，花木媚丘迟。","张子容 赠司勋萧郎中"]]}],"354":[{"n":"八十思乡","d":"","s":"《汉书》卷七十二〈王贡两龚鲍列传·贡禹〉","q":[]},{"n":"贡禹冠","d":"贡公喜：庆贺他人做官。唐杜甫《奉赠韦左丞丈二十二韵》：“窃效贡公喜，难甘原宪贫。”","s":"《汉书》卷七十二《王贡两龚鲍传》","q":[["感激遂弹冠，安能守固穷。","孟浩然 书怀贻京邑同好"],["别有弹冠士，希君无见遗。","岑参 过梁州奉赠张尚书大夫公"]]},{"n":"贡禹","d":"","s":"《汉书》卷七十二《贡禹传》","q":[["更送乘轺归上国，应怜贡禹未成名。","卢纶 冬夜赠别友人"]]},{"n":"贡禹怀书","d":"","s":"《汉书》卷七十二《贡禹传》","q":[["贡禹怀书日，张衡作赋辰。","李峤 田"]]}],"355":[{"n":"八千石","d":"","s":"《史记》卷一百三〈万石张叔列传·万石君〉","q":[]},{"n":"石奋","d":"","s":"《史记》卷一○三《万石君列传》","q":[["慎微参石奋，决密与张汤。","白居易 渭村退居寄礼部崔侍郎翰林钱舍人诗一百韵"]]},{"n":"石建宗瑾孝","d":"","s":"《汉书》卷四十六《石奋传》","q":[["石建每闻宗谨孝，刘歆不敢衒师儒。","卢纶 送崔邠拾遗"]]},{"n":"万石君","d":"","s":"《史记》卷一百三〈万石张叔列传·万石君〉","q":[["敢道万石君，轻于一丝缕。","皮日休 游毛公坛"]]}],"356":[{"n":"陈惊坐","d":"","s":"《汉书》卷九十二《游侠传·陈遵传》","q":[["坐非陈子惊，门还魏公扫。","孟浩然 襄阳公宅饮"],["剧谈推曼倩，惊坐揖陈遵。","骆宾王 春日离长安客中言怀"]]},{"n":"陈遵尺牍","d":"","s":"《汉书》卷九十二《游侠传·陈遵传》","q":[["聪明过管辂，尺牍倒陈遵。","杜甫 上韦左相二十韵"]]},{"n":"孟公","d":"","s":"《汉书》卷九十二〈游侠列传·陈遵〉","q":[]},{"n":"陈孟公","d":"孟公辖：后遂以“孟公投辖”为喜酒好客之典。唐元稹《酬窦校书二十韵》：“潜投孟公辖，狂乞莫愁钱。”","s":"《汉书》卷九十二〈游侠列传·陈遵〉","q":[["既狎忘筌友，方淹投辖车。","周彦晖 晦日宴高氏林亭"],["既欣投辖赏，暂缓望乡情。","岑文本 冬日宴于庶子宅各赋一字得平"]]}],"357":[{"n":"王生结袜","d":"","s":"《史记》卷一百二〈张释之冯唐列传·张释之〉","q":[["公车未结王生袜，客路虚弹贡禹冠。","薛逢 上吏部崔相公"],["何人更结王生袜，此客虚弹贡氏冠。","许浑 灞上逢元九处士东归"]]},{"n":"一抔土","d":"","s":"《汉书》卷五十《张释之传》","q":[["秦为三月火，汉乃一抔土。","权德舆 早夏青龙寺致斋凭眺感物因书十四韵"],["可怜贞质无今古，可叹隋陵一抔土。","卢纶 栖岩寺隋文帝马脑盏歌"]]},{"n":"倚瑟高歌","d":"","s":"《史记》卷一○二《张释之列传》","q":[["一言出口堪生死，高歌倚瑟扬清悲。","鲍溶 倚瑟行"]]},{"n":"于张","d":"","s":"《昭明文选》卷五十六〈箴铭诔上·诔上·杨荆州诔〉","q":[["于张惩不滥，陈郭宪无倾。","虞世南 赋得慎罚"]]}],"358":[{"n":"安期枣","d":"安期枣：咏仙道，或称美瓜果。唐元稹《和乐天赠吴丹》：“冥搜方朔桃，结念安期枣。”","s":"《史记》卷二十八〈封禅书〉","q":[["亲见安期公，食枣大如瓜。","李白 寄王屋山人孟大融"],["神与枣兮如瓜，虎卖杏兮收谷。","王维 送友人归山歌二首"]]},{"n":"青骡","d":"","s":"《太平御览》卷九百一〈兽部十三·骡〉","q":[["汗血到王家，随鸾撼玉珂。少君骑海上，人见是青骡。","李贺 马诗二十三首"],["尚忆青骡去，宁知白马来。","王维 哭褚司马"]]},{"n":"少君","d":"","s":"《汉书》卷二十五上〈郊祀志上〉","q":[["少君引我升玉坛，礼空遥请真仙官。","刘禹锡 八月十五日夜桃源玩月"],["微月空山曙，春祠谒少君。","李益 同萧炼师宿太乙庙"]]},{"n":"识齐鼎","d":"","s":"《史记》卷十二《孝武本纪》","q":[["遥识齐侯鼎，新过王母庐。","王维 赠东岳焦炼师"]]}],"359":[{"n":"乌头白","d":"乌头白：喻处境困难，或喻不可能之事。唐白居易《江州赴忠州至江陵已来舟中示舍弟五十韵》：“乌头因感白，鱼尾为劳赪。”","s":"《论衡校释》卷五〈感虚第十九〉","q":[["秦中已久乌头白，却是君王未备知。","李商隐 人欲"],["青云马生角，黄州使持节。","杜牧 池州送孟迟先辈"]]},{"n":"批龙麟","d":"","s":"《战国策》卷三十一〈燕策三·燕太子丹质于秦亡归〉","q":[]},{"n":"天雨粟","d":"","s":"《史记》卷八十六〈刺客列传〉","q":[]},{"n":"燕太子","d":"","s":"《史记》卷三十四《燕召公世家》","q":[["经过燕太子，结托并州儿。","李白 少年行二首之一"]]}],"360":[{"n":"凌波步","d":"洛川神：咏神仙或美女。唐孟浩然《和张二自稷县还途中遇雪》：“歌疑郢中客，态比洛川神。”","s":"《昭明文选》卷十九〈赋癸·情·洛神赋〉","q":[["未减行雨荆台下，自比凌波洛浦游。","上官仪 题画障"],["还似洛妃乘雾去，碧天无际水空流。","冷朝阳 送红线"]]},{"n":"寄明珰","d":"","s":"《昭明文选》卷十九〈赋癸·情·洛神赋〉","q":[]},{"n":"宓妃留枕","d":"","s":"《昭明文选》卷十九、三国魏·曹子建（植）《洛神赋》","q":[["贾氏窥帘韩掾少，宓妃留枕魏王才。","李商隐 无题四首"]]},{"n":"宓妃腰","d":"","s":"《昭明文选》卷十九、三国魏·曹子建（植）《洛神赋》并《序》","q":[["宓妃腰细才胜露，赵后身轻欲倚风。","李商隐 蜂"]]}],"361":[{"n":"白马小儿","d":"青丝白马：指叛乱军马。唐杜甫《洗兵马》：“青丝白马谁家子，粗豪且逐风尘起。”","s":"《隋书》卷二十二《五行志上》","q":[["白马小儿谁家子，泰清之岁来关囚。","李白 金陵歌送别范宣"],["妖氛拥白马，元帅待雕戈。","杜甫 观兵"]]},{"n":"侯景九锡","d":"","s":"《梁书》卷五十六《侯景传》","q":[["董贤三公谁复惜，侯景九锡行可叹。","韩愈 永贞行"]]},{"n":"侯景未擒","d":"","s":"《南史》卷八十《贼臣传·侯景传》","q":[["公孙仍恃险，侯景未生擒。","杜甫 风疾舟中伏枕书怀三十六韵奉呈湖南亲友"]]},{"n":"坐御床","d":"","s":"《梁书》卷五十六《侯景传》","q":[["犬戎直来坐御床，百官跣足随天王。","杜甫 忆昔二首"]]}],"362":[{"n":"齐三士","d":"三士桃：喻指用计杀人。唐卢象《追凉历下古城西北隅此地有清泉乔木》：“闲荫七贤地，醉餐三士桃。”","s":"《晏子春秋》卷二《内篇·谏下》","q":[["二桃杀三士，讵假剑如霜。","李白 惧谗"],["世人见我轻鸿毛，力排南山三壮士，齐相杀之费二桃。","李白 梁甫吟"]]},{"n":"季孟","d":"","s":"《论语注疏·微子》","q":[]},{"n":"齐景驷千","d":"","s":"《论语·季氏》","q":[["齐景驷千，何曾食万。","李瀚 蒙求"]]},{"n":"晏子裘","d":"晏裘：指生活节俭。唐杜牧《冬至日遇京使发寄舍弟》：“旅馆夜忧姜被冷，暮江寒觉晏裘轻。”","s":"《晏子春秋》卷六《内篇杂下》","q":[["旅馆夜忧姜被冷，暮江寒觉晏裘轻。","杜牧 冬至日遇京使发寄舍弟"],["高德闻郑履，俭居称晏裘。","武元衡 酬李十一尚书西亭暇日书怀见寄十二韵之作"]]}],"363":[{"n":"龙性讵能驯","d":"","s":"《昭明文选》卷二十一南朝宋·颜延年（延之）《五君咏五首·嵇中散》","q":[["凤歌空有问，龙性讵能驯。","陈子昂 酬李参军崇嗣旅馆见赠"]]},{"n":"攀嵇","d":"","s":"《昭明文选》卷二十一南朝宋·颜延年（延之）《五君咏五首·向常侍》","q":[["正遂攀稽愿，翻追访戴欢。","吴融 和诸学士秋夕禁直偶雪"],["沿牒相逢楚水湄，竹林文酒此攀嵇。","胡宿 赵宗道归辇下"]]},{"n":"青云器","d":"","s":"《昭明文选》卷二十一〈诗乙·咏史·五君咏五首·阮始平〉","q":[["仲容青云，叔夜玉山。","李瀚 蒙求"],["白社陶元亮，青云阮仲容。","李端 奉和秘书元丞杪秋忆终南旧居"]]},{"n":"颜光禄","d":"","s":"《诗品》卷中《宋光禄大夫颜延之》","q":[["五言宁谢颜光禄，百岁须齐卫武公。","杜牧 寄宣州郑谏议"]]}],"364":[{"n":"待月西厢下","d":"","s":"《太平广记》卷四百八十八〈杂传记五·莺莺传〉","q":[]},{"n":"红娘","d":"","s":"《太平广记》卷四百八十八〈杂传记五·莺莺传〉","q":[]},{"n":"怜取眼前人","d":"","s":"《太平广记》卷四百八十八〈杂传记五·莺莺传〉","q":[]},{"n":"张生","d":"","s":"《汉书》卷八十八《儒林传·伏生传》附《张生》","q":[["青春事贺监，黄卷问张生。","韩翃 送夏侯校书归上都"]]}],"365":[{"n":"白玉楼","d":"","s":"《全唐文》卷七百八十〈李商隐十·李贺小传〉","q":[]},{"n":"水剪双眸","d":"","s":"《全唐诗》卷三百九十〈唐儿歌〉【案：杜豳公之子。】","q":[]},{"n":"古锦囊","d":"","s":"《全唐文》卷七百八十〈李商隐十·李贺小传〉","q":[]},{"n":"贺白文章","d":"","s":"《全唐诗》卷二百二十四〈春日忆李白〉","q":[]}],"366":[{"n":"去卫灵公，遭桓司马","d":"","s":"《孟子注疏》卷九下〈万章章句上〉","q":[]},{"n":"石椁文","d":"","s":"《庄子》杂篇·卷八下《则阳》","q":[["未厌金陵气，先开石椁文。","骆宾王 帝京篇"]]},{"n":"卫谤","d":"","s":"《史记》卷四十七《孔子世家》","q":[["终当灭卫谤，不受鲁人讥。","李白 书怀赠南陵常赞府"]]},{"n":"炀灶","d":"","s":"《韩非子》卷九《内储说上》","q":[["探汤汲阴井，炀灶开重扉。","柳宗元 夏日苦热登西楼"]]}],"367":[{"n":"传庾翼","d":"","s":"《晋书》卷八十《王羲之传》","q":[["逸翰应藏法，高词肯浪吟。数须传庾翼，莫独与卢谌。","李商隐 自桂林奉使江陵途中感怀寄献尚书"],["忆昔鄱阳寺中见一碣，逋翁词兮逋翁扎。庾翼未服王右军，李白不知谁拟杀。","贯休 读顾况歌行"]]},{"n":"束高阁","d":"","s":"《世说新语》中卷下《豪爽》","q":[["又岂忧文臣尽遭束高阁，文教从今日萧索。","吴融 风雨吟"],["春秋三传束高阁，独抱遗经究终始。","韩愈 寄卢仝"]]},{"n":"家鸡野鹜","d":"","s":"晋·何法盛《晋中兴书》卷七","q":[["闻道近来诸子弟，临池寻已厌家鸡。","柳宗元 殷贤戏批书后寄刘连州并示孟崙二童（自注。家有右军书。每纸背庾翼题云。王会稽六纸。二月三十日）"]]},{"n":"稚恭乘骑","d":"","s":"《世说新语》中卷上《雅量》","q":[["梳洗凭张敞，乘骑笑稚恭。","李商隐 垂柳"]]}],"368":[{"n":"蚌鹬心","d":"","s":"《战国策》卷三十〈燕策二·赵且伐燕〉","q":[["蚌鹬徒喧竞，笙歌罢献酬。","李咸用 和殷衙推春霖即事"],["波浑未辨鱼龙迹，雾暗宁知蚌鹬心。","许浑 新兴道中"]]},{"n":"木偶人","d":"","s":"《战国策》卷十《齐策三》","q":[["且求容立锥头地，免似漂流木偶人。","白居易 卜居"]]},{"n":"伯乐顾","d":"伯乐顾：喻指受名家赏识而出名。唐张九龄《南还以诗代书赠京师旧僚》：“上惭伯乐顾，中负叔牙知。”","s":"《战国策》卷三十〈燕二·苏代为燕说齐〉","q":[["一顾恩深荷道安，独垂双泪下层峦。","刘沧 龙门留别道友"],["一顾生鸿羽，再言将鹤翩。","孟郊 寄陕府邓给事"]]},{"n":"挹馀烈","d":"","s":"《史记》卷七十一〈樗里子甘茂列传·甘茂〉","q":[["行矣各勉旃，吾当挹馀烈。","高适 宋中别李八"]]}],"369":[{"n":"王尊叱驭","d":"九折回轩：借喻不再奔波于仕途。唐李商隐《明禅师院酬从兄见寄》：“斯游悦为胜，九折幸回轩”；九折途：喻指路途艰险。宋陆游《东窗》：“九折危途寸步艰，至今回首尚心寒。”","s":"《汉书》卷七十六〈赵尹韩张两王列传·王尊〉","q":[["晨严九折度，暮戒六军行。","张九龄 奉和圣制早登太行山率尔言志"],["撕游傥为胜，九折幸回轩。","李商隐 明禅师院酬从兄见寄"]]},{"n":"布鼓","d":"","s":"《汉书》卷七十六《王尊传》","q":[["词人羞布鼓，远客献貂襜。","刘禹锡 和汴州令狐相公到镇改月偶书所怀（二十二韵）"]]},{"n":"三王尹京","d":"","s":"《汉书》卷七十二《王吉传》附《王骏传》","q":[["三王尹京，二鲍纠慝。","李瀚 蒙求"]]},{"n":"张王","d":"","s":"《汉书》卷七十六〈赵尹韩张两王列传〉","q":[]}],"370":[{"n":"细柳营","d":"如儿戏：指军纪松散、衰败之师、唐杜牧《感怀诗一首》：“凶门爪牙辈，穰穰如儿戏。”；细柳营：咏治军有方、军容整肃。唐王维《观猎》：“忽过新丰市，还归细柳营。”","s":"《史记》卷五十七《绛侯周勃世家》","q":[["柳营无事诣莲宫，步步犹疑是梦中。","令狐楚 游义兴寺寄上李逢吉相公"],["回来看觅莺飞处，即是将军细柳营。","刘商 行营送人"]]},{"n":"天上将","d":"","s":"《汉书》卷四十〈张陈王周列传·周勃·（子）周亚夫〉","q":[["忽闻天上将，关塞重横行。","陈子昂 和陆明府赠将军重出塞"]]},{"n":"条侯","d":"","s":"《史记》卷五十七《绛侯周勃世家》","q":[["细柳肃军令，条侯信殊伦。","权德舆 细柳驿"]]},{"n":"亚夫得剧孟","d":"","s":"《史记》卷一○六《吴王濞列传》","q":[["亚夫未见顾，剧孟阻先行。","李白 闻李太尉大举秦兵百万出征东南懦夫请缨冀申一割之用半道病还留别金陵崔侍御十九韵"],["亚夫得剧孟，敌国空无人。","李白 赠张相镐二首之一（时逃难在宿松山作。萧士赟云，此下八首非白作。）"]]}],"371":[{"n":"三户亡秦","d":"","s":"《史记》卷七〈项羽本纪〉","q":[["孤城尽日空花落，三户无人自鸟啼。","刘长卿 使次安陆寄友人"],["家楚依三户，辞州选一钱。","司空曙 送严使君游山"]]},{"n":"范增","d":"","s":"《史记》卷七〈项羽本纪〉","q":[]},{"n":"鸿门","d":"","s":"《史记》卷七《项羽本纪》","q":[["佐汉解鸿门，生唐为后身。","李白 赠张相镐二首之一"]]},{"n":"碎玉斗","d":"","s":"《史记》卷七《项羽本纪》","q":[["忆昔范增碎玉斗，未使吴兵著白袍。","杜甫 久雨期王将军不至"]]}],"372":[{"n":"两部蛙","d":"两部蛙：咏环境清悠。唐戴复古《豫章巨浸呈陈幼度提干》：“自成鼓吹喧朝夕，输与东湖两部蛙。”","s":"《南史》卷四十九〈孔圭列传〉","q":[]},{"n":"北山文","d":"","s":"《昭明文选》卷四十三南朝齐·孔德璋（稚圭）《北山移文》","q":[["会有圭组恋，遂贻山林嘲。","柳宗元 游朝阳岩遂登西亭二十韵"],["今日病身惭小隐，欲将泉石勒移文。","曹唐 三年冬大礼五首之五"]]},{"n":"德璋","d":"","s":"《南齐书》卷四十八《孔稚圭传》","q":[["何言张掾傲，每重德璋亲。","卢纶 过司空曙村居"]]},{"n":"稚圭","d":"","s":"《南齐书》卷四十八《孔稚圭传》","q":[["稚圭伦鉴未精通，只把蛙声鼓吹同。","吴融 蛙声"],["莫怪闻时倍惆怅，稚圭蓬荜在山阴。","吴融 西京道中闻蛙"]]}],"373":[{"n":"哭秦庭","d":"秦庭哭：指为国解难。唐李百药《郢城怀古》：“莫救夷陵火，无复秦庭哭。”","s":"《春秋左传正义》卷五十四〈定公·传四年〉","q":[["包胥心独许，连夜哭秦兵。千乘徒虚尔，一夫安可轻。","元稹 楚歌十首"],["包胥非救楚，随会反留秦。","张说 过庾信宅"]]},{"n":"长蛇","d":"","s":"《春秋左传·定公四年》","q":[["长蛇稽天讨，上将方北伐。","独孤及 奉和李大夫同吕评事太行苦热行兼寄院中诸公"],["皇运偶中变，长蛇食中土。","独孤及 季冬自嵩山赴洛道中作"]]},{"n":"封豕","d":"","s":"《春秋左传·定公四年》","q":[["荡蔡擒封豕，平齐斩巨鳌。","白居易 寄献北都留守裴令公"]]},{"n":"申包胥恨","d":"","s":"《史记》卷六十六〈伍子胥列传〉","q":[]}],"374":[{"n":"湘夫人","d":"江娥啼竹：咏忧伤之情，或咏竹。唐李贺《李凭箜篌引》：“江娥啼竹素女愁，李凭中国弹箜篌。”","s":"《艺文类聚》卷八十九〈木部下·竹〉","q":[["愁如湘灵哭湘浦，咽咽哀音隔云雾。九嶷深翠转巍峨，仙骨寒消不知处。","僧鸾 赠李粲秀才"],["河汉夜阑孤雁度，潇湘水阔二妃愁。","刘沧 江楼月夜闻笛"]]},{"n":"舜弦","d":"","s":"《史记》卷二十四〈乐书〉","q":[["应是南风曲，声声不合今。","于武陵 匣中琴"],["湛露羞依草，南风耻带熏。","令狐楚 青云干吕"]]},{"n":"尧禅舜","d":"","s":"《史记》卷一《五帝本纪·尧本纪》","q":[["古来尧禅舜，何必罪驩兜。","沈佺期 从驩州廨宅移住山间水亭赠苏使君"]]},{"n":"尧舜","d":"","s":"《礼记·大学》","q":[["尧舜传天下，同心致太平。","张说 东都酺宴四首"],["尧舜之事不足惊，自余嚣嚣直可轻。","李白 怀仙歌"]]}],"375":[{"n":"花外小车","d":"","s":"《邵氏闻见录》卷十八","q":[]},{"n":"康节","d":"","s":"《邵氏闻见录》卷十八","q":[]},{"n":"弄巧成拙","d":"","s":"《伊川击壤集》卷二十〈首尾吟〉","q":[]},{"n":"邵雍","d":"","s":"《康节先生墓志铭》","q":[]}],"376":[{"n":"带经锄","d":"","s":"《汉书》卷五十八〈公孙弘卜式儿宽传·儿宽〉","q":[["常林带经，高凤漂麦。","李瀚 蒙求"],["日长农有暇，悔不带经来。","钱起 南溪春耕"]]},{"n":"耽书","d":"","s":"《晋书》卷五十一〈皇甫谧列传〉","q":[["服药颜犹驻，耽书癖已成。","郎士元 送韦逸人归钟山"]]},{"n":"皇甫谧","d":"","s":"《昭明文选》卷四十五〈对问设论辞序上·序上·三都赋序〉","q":[["玄宴难瘳痹，临邛但发痟。","唐彦谦 汉代"],["秋光何处堪消日，玄宴先生满架书。","李涉 秋日过员太祝林园"]]},{"n":"著书玄晏","d":"","s":"《晋书》卷五十一〈皇甫谧列传〉","q":[]}],"377":[{"n":"阿娇","d":"","s":"《史记》卷四十九《外戚世家》","q":[["母兄怜爱无俦侣，五岁名为阿娇女。","崔显 邯郸宫人怨"],["阿娇生汉宫，西施住南国。","曹邺 四怨三愁五情诗十二首其二情"]]},{"n":"长门赋","d":"千金赋：喻作品极有价值。金元好问《白屋》：“长门谁买千金赋，祖道虚传五鬼文。”；长门泣：喻失宠后的凄怨心情。南朝梁何逊《扬州法曹梅花盛开》：“朝洒长门泣，夕驻临邛杯。”","s":"《昭明文选》卷十六汉·司马长卿（相如）《长门赋·序》","q":[["长门谁买千金赋，祖道虚传五鬼文。","元好问 白屋"],["虽然不似王孙女，解爱临邛卖赋郎。","崔珏 有赠"]]},{"n":"长门","d":"","s":"《昭明文选》卷十六〈赋辛·哀伤·长门赋〉","q":[["今日在长门，从来不如丑。","于濆 宫怨"],["谁能赋得长门事，不惜千金奉酒杯。","吴融 上阳宫词"]]},{"n":"陈皇后","d":"","s":"《汉书》卷九十七上《外戚传·孝武陈皇后传》","q":[["君王纵有情，不奈陈皇后。","于濆 宫怨"]]}],"378":[{"n":"报琼瑶","d":"","s":"《毛诗正义》卷三之三〈国风·卫风·木瓜〉","q":[["贫薄诗家无好物，反投桃李报琼琚。","白居易 岁暮枉衢州张使君书并诗因以长句报之"],["木瓜诚有报，玉楮论无实。","张九龄 叙怀二首"]]},{"n":"武公入相","d":"","s":"《毛诗正义》卷三之二（续）〈国风·卫风·淇奥〉","q":[]},{"n":"卫武","d":"","s":"《国语·楚语上》","q":[["五言宁谢颜光禄，百岁须齐卫武公。","杜牧 寄宣州郑谏议"],["愿公如卫武，百岁尚康强。","杜牧 春日言怀寄虢州李常侍十韵"]]},{"n":"武公百岁","d":"","s":"《国语》卷十七〈楚语上·左史倚相儆申公子亹〉","q":[]}],"379":[{"n":"螳螂捕蝉","d":"雀伺螳螂：喻只瞻前而不顾后，或喻侵犯。五代前蜀韦庄《和郑拾遗秋日感事一百韵》：“人心惊獬豸，雀意伺螳螂。”","s":"《韩诗外传》卷十第二十一章","q":[["人心惊獬豸，雀意伺螳螂。","韦庄 和郑拾遗秋日感事一百韵"],["隐榆非谏楚，噪柳异悲潘。","骆宾王 秋晨同淄川毛司马秋九咏秋蝉"]]},{"n":"叔敖阴德","d":"","s":"汉·贾谊《新书》卷六《春秋》","q":[["欲学叔敖瘗，其如多似麻。","元稹 巴蛇三首"],["柳下直道，叔敖阴德。","李瀚 蒙求"]]},{"n":"孙敖秉羽","d":"","s":"《庄子》杂篇·卷八中《徐无鬼》","q":[["寝谋惭汲黯，秉羽贵孙敖。","李德裕 寒食日三殿侍宴奉进诗一首"]]},{"n":"孙叔无谋","d":"","s":"《春秋左传·宣公十二年》","q":[["廉颇诚未老，孙叔宜无谋。","张说 南中送北使二首之二"]]}],"380":[{"n":"富韩文范","d":"","s":"《三朝名臣言行录》卷一〈韩琦〉","q":[]},{"n":"宽夫彦国","d":"","s":"《邵氏闻见录》卷十","q":[]},{"n":"文富","d":"","s":"《归田录》卷一","q":[]}],"381":[{"n":"理窟","d":"","s":"《世说新语笺疏》上卷下〈文学〉","q":[["只应移理窟，泉下对真长。","罗隐 哭张博士太常"]]},{"n":"孝廉船","d":"","s":"《世说新语》下卷下《文学》","q":[["将过夫子宅，前问孝廉船。","李端 送耿拾遗湋使江南括图书"],["兴残虚白室，迹断孝廉船。","杜甫 哭韦大夫之晋"]]},{"n":"张冯","d":"","s":"《晋书》卷七十五《张凭传》","q":[["张冯本名士，蔡廓是佳儿。","司空曙 送王使君小子孝廉登科归省"]]}],"382":[{"n":"问唐举","d":"","s":"《史记》卷七十九〈蔡泽列传〉","q":[]},{"n":"唐举","d":"","s":"《荀子·非相篇》","q":[["懒从唐生决，羞访季主卜。","李白 寻阳紫极宫感秋作"],["燕客期跃马，唐生安敢讥。","李白 送蔡山人"]]},{"n":"跃马年","d":"跃马年：指做官。唐王维《赠从弟司库员外球》：“徒闻跃马年，苦无出人智。”","s":"《史记》卷七十九《蔡泽列传》","q":[["少年跃马同心使，免得诗中道跨驴。","贾岛 送友人之南陵"],["愿奉唐生诀，将知跃马年。","陈子昂 赠严仓曹乞推命录"]]}],"383":[{"n":"阚泽","d":"","s":"《三国志》卷五十三《吴书·阚泽传》","q":[["三五月明临阚泽，百千人众看王恭。","徐夤 尚书荣拜恩命夤疾中辄课恶诗二首以申攀赞之二"],["未酬阚泽佣书债，犹欠君平卖卜钱。","韦庄 癸丑年下第献新先辈"]]},{"n":"梦月","d":"","s":"《太平御览》卷三九八","q":[["占星非聚德，梦月讵悬名。","骆宾王 在江南赠宋五之问"]]},{"n":"佣书","d":"","s":"《后汉书》卷四十七《班超传》","q":[["庸书酬万债，竹坞问樊村。","杜牧 奉送中丞姊夫俦自大理卿出镇江西叙书怀因成十二韵"],["赊酒不辞病，佣书非为贫。","杜牧 宣城赠肖兵曹"]]}],"384":[{"n":"胜公荣","d":"","s":"《世说新语笺疏》下卷上〈简傲〉","q":[]},{"n":"公荣","d":"","s":"《世说新语笺疏》下卷上〈简傲〉","q":[]},{"n":"刘公荣","d":"","s":"《世说新语》下卷上《简傲》","q":[["已恨流莺欺谢客，更将浮蚁与刘郎。","温庭筠 李羽处士寄新酝走笔戏酬"]]}],"385":[{"n":"解金貂","d":"金貂换：文人狂放不羁，或喻喜好饮酒。唐温庭筠《寄卢生》：“他年犹拟金貂换，寄语黄公旧酒垆。”","s":"《晋书》卷四十九〈阮籍列传·（瞻弟）阮孚〉","q":[["脱貂贳桂醑，射雁与山厨。","王维 过崔驸马山池"],["不识金貂重，偏惜玉山颓。","骆宾王 畴昔篇"]]},{"n":"几两屐","d":"阮家屐：喻指特别爱好。唐王维《谒培上人》：“床下阮家屐，窗前筇竹杖。”","s":"《世说新语》中卷上《雅量》","q":[["床下阮家屐，窗前筇竹杖。","王维 谒璇上人"]]},{"n":"阮囊","d":"","s":"《韵府群玉·阳韵》","q":[["囊空恐羞涩，留得一钱看。","杜甫 空囊"]]}],"386":[{"n":"惠帝闻蟆","d":"","s":"《晋书》卷四《孝惠帝纪》","q":[["刘玄刮席，惠帝闻蟆。","李瀚 蒙求"],["晋武轻后事，惠皇终已昏。","高适 登百丈峰二首之二"]]},{"n":"卫瓘抚床","d":"","s":"《晋书》卷三十六《卫瓘传》","q":[["袁盎却座，卫瓘抚床。","李瀚 蒙求"]]},{"n":"蒸鸡","d":"","s":"《晋书》卷四《孝惠帝纪》","q":[["蒸鸡殊减膳，屑曲异和羹。","李商隐 送千牛李将军赴阙五十韵"]]}],"387":[{"n":"董贤","d":"","s":"《汉书》卷九十三《佞幸传·董贤传》","q":[["向使逢着汉帝怜，董贤气咽不能语。","岑参 醉后戏与赵歌儿"],["董贤三公谁复惜，侯景九锡行可叹。","韩愈 永贞行"]]},{"n":"董贤女弟","d":"","s":"《汉书》卷九十三《佞幸传·董贤传》","q":[["董贤女弟在椒风，窈窕繁华贵后宫。","崔国辅 白纻辞二首之二"]]},{"n":"孔光尊董贤","d":"","s":"《汉书》卷九十三《佞幸传·董贤传》","q":[["孔光尊董贤，胡广惭李固。","李华 杂诗六首"]]}],"388":[{"n":"射斗牛","d":"丰城气：喻有声誉。才华。唐杨炯《和刘长庄答十九兄》：“宝剑丰城气、明珠魏国珍。”；丰城龙剑：指宝剑，或喻出类拔革之人及华美宝贵之物。金元好问《赠答平阳仇舜臣》：“沧海骊珠能几见，丰城龙剑不终藏。”","s":"《晋书》卷三十六〈张华列传〉","q":[["负户愁读书，剑光忿冲斗。","储光羲 狱中贻姚张薛李郑柳诸公"],["牛斗之气，蓄于昆溪。","元希声 赠皇甫侍御赴都八首"]]},{"n":"干将","d":"","s":"《吴越春秋》卷四〈阖闾内传·阖闾元年〉","q":[["我闻音响异，疑是干将偶。","元稹 说剑"],["吴溪漫淬干将剑，却是猿声断客肠。","张祜 题弋阳馆"]]},{"n":"镆铘","d":"","s":"《吴越春秋》卷四《阖闾内传》","q":[["镆铘无人淬，两刃幽壤铁。","元稹 谕宝二首之二"],["戎装佩镆铘，走马逐轻车。","周繇 送边上从事"]]}],"389":[{"n":"负子渡河","d":"","s":"《谢承后汉书》卷五〈儒林传·刘昆〉","q":[]},{"n":"刘昆","d":"","s":"《后汉书》卷七十九上《儒林传·刘昆传》","q":[["渡河何所适，终是怯刘琨（昆）。","斑寅 与宁茵赋诗（大中年。秀才宁茵寓南山庄。夜有人。一称桃林斑特处士。一称南山斑寅将军。来访。谈论赋诗而别。及视其迹。乃知牛与虎也）"]]},{"n":"刘昆反火","d":"","s":"《后汉书》卷七十九上《儒林传·刘昆传》","q":[["孟尝还珠，刘昆反火。","李瀚 蒙求"]]}],"390":[{"n":"陈胜","d":"","s":"《史记》卷四十八《陈涉世家》","q":[["已闻陈胜心降汉，谁为田横国号齐。","韦庄 赠云阳裴明府"]]},{"n":"丛祠一炬","d":"","s":"《史记》卷四十八《陈涉世家》","q":[["丛祠一炬照秦川，雨散云飞二十年。","吴融 丛祠"]]},{"n":"罾鱼","d":"","s":"《史记》卷四十八〈陈涉世家〉","q":[]}],"391":[{"n":"牵裾","d":"牵裾：指忠臣苦谏。唐杜甫《建都十二韵》：“牵裾恨不死，漏网辱殊恩。”","s":"《三国志》卷二十五《魏书·辛毗传》","q":[["牵裾恨不死，漏网荷殊恩。","杜甫 建都十二韵"],["不才同补衮，奉诏许牵裾。","杜甫 赠李八秘书别三十韵"]]},{"n":"孙刘辈使我不为公","d":"","s":"《三国志》卷二十五〈魏书·辛毗传〉","q":[]},{"n":"辛毗引裾","d":"","s":"《三国志》卷二十五《魏书·辛毗传》","q":[["樊哙排闼，辛毗引裾。","李瀚 蒙求"]]}],"392":[{"n":"才术褚先生","d":"","s":"《南史》卷七十五《隐逸传上·褚伯玉传》","q":[["光阴蓟子训，才术褚先生。","高适 赠别褚山人"]]},{"n":"褚伯玉","d":"","s":"《南齐书》卷五十四《高逸传·褚伯玉传》","q":[["还同褚伯玉，入馆忝州人。","丘丹 奉酬韦苏州使君"]]},{"n":"故要","d":"","s":"《南齐书》卷五十四《高逸传·褚伯玉传》","q":[["问子能来宿，今疑索故要。","杜甫 西阁三度期大昌严明府同宿不到"]]}],"393":[{"n":"白日开","d":"","s":"《西京杂记》卷四","q":[["白日铭安在，清风颂独留。","李乂 哭仆射鄂公杨再思"],["鸟来伤贾傅，马立葬滕公。","李端 张左丞挽歌二首"]]},{"n":"滕公宅","d":"","s":"《史记》卷九十五《夏侯婴列传》","q":[["地闭滕公宅，山荒谢客庐。","李端 哭张南史因寄南史侄叔宗"]]},{"n":"夏侯婴","d":"","s":"《史记》卷九十五〈樊郦滕灌列传·夏侯婴〉","q":[["宫省旧推皇甫谧，寺曹今得夏侯婴。","罗隐 裴庶子除太仆卿因贺"]]}],"394":[{"n":"不下堂","d":"宓子弹琴：咏官吏善于管理。唐杜甫《七月一日题终明府水楼二首》之二：“宓子弹琴邑宰日，终军弃繻英妙时。”；宓子贱：喻指县官。唐李白《赠阎丘宿松》：“何衔宓子贱，不减陶渊明。”","s":"《吕氏春秋》卷二十一〈开春论·察贤〉","q":[["有我衰鸟郎，新邑长鸣琴。","储光羲 述韦昭应画犀牛"],["音容想在眼，暂若升琴堂。","刘长卿 出丰县界寄韩明府"]]},{"n":"二十四老翁","d":"","s":"《孔子家语》卷三《辨政》","q":[["宾从何逶迤，二十四老翁。","高适 观李九少府翥树宓子贱神祠碑"]]},{"n":"助夜渔","d":"","s":"《水经注》卷二十五《泗水》","q":[["今日蓝溪水，无人不夜鱼。","钱起 送李明府去官"]]}],"395":[{"n":"督邮才弱冠","d":"","s":"《后汉书》卷四十三《朱晖传》附《朱穆传》","q":[["借问督邮才弱冠，府中年少不如君。","皇甫冉 送李录事赴饶州"]]},{"n":"奉书朱穆","d":"","s":"《后汉书》卷四十三〈朱晖朱穆列传·孙穆〉","q":[]},{"n":"朱公叔","d":"","s":"《后汉书》卷四十三《朱晖传》附《朱穆传》","q":[["我心不畏朱公叔，君意须防刘孝标。","马异 答卢仝结交诗"]]}],"396":[{"n":"灰死","d":"灰死：形容失意的心情。唐白居易《送兄弟回雪夜》：“灰死如我心，雪白如我发。”","s":"《史记》卷一百八〈韩长孺列传〉","q":[["坠履忘情后，寒灰更湿时。","刘言史 江陵客舍留别樊尚书"],["谁知大炉火，还有不然灰。","刘长川 将赴东都上李相公"]]},{"n":"长孺国器","d":"","s":"《汉书》卷五十二《韩安国传》","q":[["季圭士首，长孺国器。","李瀚 蒙求"]]},{"n":"长孺欲成灰","d":"","s":"《汉书》卷五十二《韩安国传》","q":[["袁丝徒伏剑，长孺欲成灰。","李德裕 清冷池怀古"]]}],"397":[{"n":"宝瑟僵","d":"","s":"《汉书》卷六十八〈霍光金日磾列传·金日磾〉","q":[]},{"n":"金张","d":"七叶贵：喻世代显贵。唐王昌龄《留别岑参兄弟》：“貂蝉七叶贵，鸿鸽万里游。”","s":"《昭明文选》卷二十一〈诗乙·咏史·咏史八首〉","q":[["貂蝉七叶贵，鸿鹄万里游。","王昌龄 留别岑参兄弟"],["芳草落花无限，金张许史相随。","丘丹 忆长安四月"]]},{"n":"两绶","d":"","s":"《汉书》卷六十八《金日磾传》","q":[["两绶藏不见，落花何处期。","杜牧 少年行"]]}],"398":[{"n":"董贤","d":"","s":"《汉书》卷九十三《佞幸传·董贤传》","q":[["向使逢着汉帝怜，董贤气咽不能语。","岑参 醉后戏与赵歌儿"],["董贤三公谁复惜，侯景九锡行可叹。","韩愈 永贞行"]]},{"n":"董贤女弟","d":"","s":"《汉书》卷九十三《佞幸传·董贤传》","q":[["董贤女弟在椒风，窈窕繁华贵后宫。","崔国辅 白纻辞二首之二"]]},{"n":"葡萄宫","d":"","s":"《汉书》卷九十四下《匈奴传下》","q":[["京师皆骑汗血马，回纥喂肉葡萄宫。","杜甫 洗兵马"]]}],"399":[{"n":"庾尚书","d":"","s":"《梁书》卷四十九《文学传上·庾于陵传》附《庾肩吾传》","q":[["闻寻周触士，知伴庾尚书。","杨巨源 郊居秋日酬奚赞府见寄"],["当从庚中庶，诗客更何人。","耿湋 春日游慈恩寺寄畅当"]]},{"n":"小庾","d":"","s":"《北史》卷八十三〈文苑列传·庾信〉","q":[["文体此时看又别，吾知小庾甚风流。","韩翃 送故人赴江陵寻庾牧"]]},{"n":"徐庾","d":"","s":"《北史》卷八十三〈文苑列传·庾信〉","q":[["尘埃徐庾词，金玉曹刘名。","孟郊 赠苏州韦郎中使君"],["南朝徐庾流，洛下忆同游。","罗隐 商于驿与于蕴玉话别"]]}],"400":[{"n":"卫娘","d":"","s":"《史记》卷四十九《外戚世家》","q":[["瑶房侍寝世莫知，金屋更衣人不见。","崔颢 郸邯宫人怨"],["子夫前入侍，飞燕复当时。","武平一 妾薄命"]]},{"n":"平阳","d":"","s":"《史记》卷一一一《卫将军骠骑列传》","q":[["虚然异风出，髣髴宿平阳。","丁仙芝 剡溪西馆闻笛"],["平阳旧池馆，寂寞使人愁。","丁仙芝 长宁公主旧山池"]]},{"n":"平阳拊背","d":"","s":"《史记》卷四十九《外戚世家》","q":[["平阳拊背穿驰道，铜雀分香下璧门。","杜牧 出宫人二首"]]}],"401":[{"n":"晋宣狼顾","d":"","s":"《晋书》卷一《宣帝纪》","q":[["晋宣狼顾，汉祖龙颜。","李瀚 蒙求"]]},{"n":"恋栈","d":"","s":"《三国志》卷九〈魏书·曹真传·何晏邓飏丁谧毕轨李胜桓范〉","q":[]},{"n":"一曹三马","d":"","s":"《晋书》卷一〈高祖宣帝纪〉","q":[]}],"402":[{"n":"孟邻","d":"","s":"汉·刘向《列女传》卷一《母仪·邹孟轲母传》","q":[["偏知汉水广，应与孟家邻。","刘慎虚 寄江滔求孟六遗文"],["韦生堪继相，孟子愿依邻。","孟郊 题韦承总吴王故城下幽居"]]},{"n":"大被","d":"","s":"《三国志》卷四十八〈吴书·三嗣主·孙皓传〉","q":[["时宜裂大袂，剑客车盘茵。","李贺 出城别张又新酬李汉"],["仍闻广练被，更有远儒过。","卢纶 宴赵氏昆季书院因与会文并率尔投赠"]]},{"n":"陶孟母贤","d":"","s":"《晋书》卷六十六〈陶侃列传〉","q":[]}],"403":[{"n":"王子乔","d":"王乔鹤：喻洒脱不凡之人，或指鹤。唐杜甫《观李固请司马弟山水图三首》之二：“范蠡舟扁小，王乔鹤不群。”；王子乔：喻指仙人。《古诗十九首》之十五：“仙人王子乔，难可与等期。”","s":"旧题汉·刘向《列仙传》卷上《王子乔》","q":[["年年望灵鹤，常在此山头。","于鹄 寄续尊师"],["安得如子晋，与之游太清。","储光羲 同王十三维偶然作十首"]]},{"n":"松乔","d":"","s":"《搜神记》卷一～","q":[["自有园公紫芝侣，仍追少傅赤松游。","刘禹锡 自左冯归洛下酬乐天兼呈裴令公"],["向夕便思青琐拜，近年寻伴赤松游。","姚合 使两浙赠罗隐"]]},{"n":"上宾","d":"","s":"《逸周书》卷九〈太子晋〉","q":[["后学方成市，吾师又上宾。","李德裕 尊师是桃源黄先生传法弟子常见尊师称先师灵迹今重赋此诗兼寄题黄先生旧馆"],["暂欲系船韶石下，上宾虞舜整冠裾。","韩愈 从潮州量移袁州张韶州端公以诗相贺因酬之"]]}],"404":[{"n":"驭气","d":"","s":"《庄子》内篇·卷一上《逍遥游》","q":[["泠然御风客，与道自浮沉。","储嗣宗 送道士"],["云是淮王宅，风为列子车。","刘禹锡 同乐天和微之深春二十首（同用家花车斜四韵）"]]},{"n":"列子居郑圃","d":"","s":"《列子·天瑞》","q":[["列子居郑圃，不将众庶分。","李白 赠张公洲革处士"]]},{"n":"子列","d":"","s":"《庄子集释》卷三下〈内篇·应帝王〉","q":[["子列光殊价，明时忍自高。","杜牧 寄李播评事"]]}],"405":[{"n":"吾道穷","d":"悲麟：指感叹生不逢时。唐李商隐《失题》：“斯文虚梦鸟，吾道欲悲麟。”；麟笔：指著作。宋陆游《小轩》：“麟笔残功成水品，蛇图余思入棋枰。”","s":"《春秋公羊传注疏》卷二十八〈哀公十四年〉","q":[["获麟书诸册，豢龙醢为臡。","元稹 青云驿"],["别号行鸣雁，遗编感获麟。","唐彦谦 吊方于处士二首"]]},{"n":"好龙","d":"叶公：喻徒有所好之人。唐齐己《谢惠卜人见惠二龙障子以短歌酬之》：“恐是叶公好假龙，及见真龙却惊怕。”；叶公好尚：喻只是表面上爱好某事物。唐郑谷《兵部卢郎中光济借示诗集以四韵谢之》：“叶公好尚浑疏阔，忽见真龙几丧明。”","s":"《新序》卷五〈杂事〉","q":[["多愧书传鹤，深惭纸画龙。","徐灵府 言志献浙东廉访辞召"],["因君访遗迹，此日见真龙。","戴叔伦 同赋龙沙墅"]]},{"n":"鸡不如鹤","d":"","s":"《韩诗外传》卷二第二十三章","q":[["远物皆重近皆轻，鸡虽有德不如鹤。","鲍防 杂感"]]}],"406":[{"n":"食子","d":"","s":"《韩非子》卷七〈说林上〉","q":[["乐羊为魏将，食子殉军功。","陈子昂 感遇诗三十八首"]]},{"n":"魏侯重","d":"","s":"《战国策》卷四《秦策二》","q":[["但蒙魏侯重，不受谤书诬。","陈子昂 答韩使同在边"]]},{"n":"洗箱箧","d":"","s":"《史记》卷七十一〈樗里子甘茂列传·甘茂〉","q":[["直笔在史臣，将来洗箱箧。","杜甫 八哀诗故司徒李公光弼"]]}],"407":[{"n":"贪泉水","d":"贪泉：喻为人节操高尚，光明正大。唐张枯《寄迁客》：“瘴海须求药，贪泉莫举瓢。”","s":"《世说新语笺疏》上卷上〈德行〉","q":[["番禺静无事，空咏饮泉诗。","刘长卿 送韦赞善使岭南"],["瘴海须求药，贪泉莫举瓢。","张祜 寄迁客"]]},{"n":"隐之感邻","d":"","s":"《晋书》卷九十《良吏传·吴隐之传》","q":[["隐之感邻，王修辍社。","李瀚 蒙求"]]},{"n":"坐无毡","d":"","s":"《晋书》卷九十《良吏传·吴隐之传》","q":[["才名四十年，坐客寒无毡。","杜甫 戏简艽广文虔兼呈苏司业源明"]]}],"408":[{"n":"射日弓","d":"九日落：喻为民除害，或喻勇猛。唐杜甫《观公孙大娘弟子舞剑器行》：“[火霍]如羿射九日落，矫如群帝骖龙翔。”","s":"《楚辞补注》卷三〈天问〉","q":[["安得羿善射，一箭落旄头。","李白 经乱离后天恩流夜郎忆旧游书怀赠江夏韦太守良宰"],["羿昔落九乌，天人清且安。","李白 古朗月行"]]},{"n":"五弟训禽荒","d":"","s":"《尚书·夏书·五子之歌》","q":[["尝闻夏太康，五弟训禽荒。","魏知古 从猎渭川献诗"]]},{"n":"凿齿","d":"","s":"《淮南子》卷八《本经训》","q":[["奔鲸夹黄河，凿齿屯洛阳。","李白 北上行"]]}],"409":[{"n":"夷门抱关","d":"","s":"《史记》卷七十七〈魏公子列传〉","q":[["东道听游子，夷门歌主人。","于武陵 送酂县董明府之任"],["侯嬴不得从，心逐信陵君。","刘商 送庐州贾使君拜命"]]},{"n":"朱公子","d":"","s":"《史记》卷七十七《魏公子列传》","q":[["救赵挥金槌，邯郸先震惊。","李白 侠客行"],["救赵复存魏，英威天下闻。","李白 博平郑太守自庐山千里相寻入江夏北市门见访却之武陵立马赠别"]]},{"n":"侯生遭骂","d":"","s":"《史记》卷七十七〈魏公子列传〉","q":[["冶长信非罪，侯生或遭骂。","韩愈 县斋有怀"]]}],"410":[{"n":"捕虏","d":"","s":"《后汉书》卷二十二《马武传》","q":[["居然双捕虏，自是一嫖姚。","杜甫 寄董卿嘉荣十韵"]]},{"n":"马武","d":"","s":"《后汉书》卷二十二〈朱景王杜马刘傅坚马列传·马武〉","q":[]},{"n":"马武弹剑","d":"","s":"《后汉书》卷十八《吴盖陈臧列传》","q":[["雄如马武皆弹剑，少似终军亦请缨。","杜牧 东兵长句十韵"]]}],"411":[{"n":"史鱼黜殡","d":"","s":"汉·韩婴《韩诗外传》卷七·第二十一章","q":[["史鱼黜殡，子囊城郢。","李瀚 蒙求"]]},{"n":"史鱼直","d":"","s":"《论语·卫灵公》","q":[["知人想林宗，直道惭史鱼。","高适 苦雨寄房四（一作休）昆季"]]},{"n":"心似矢","d":"","s":"《论语·卫灵公》","q":[["秉心犹似矢，搔首忽如蓬。","李端 长安感事呈卢纶"]]}],"412":[{"n":"情伤荀倩","d":"","s":"《世说新语笺疏》下卷下〈惑溺〉","q":[]},{"n":"荀粲惑溺","d":"","s":"《三国志》卷十〈魏书·荀彧传〉","q":[["王述忿狷，荀粲惑溺。","李瀚 蒙求"],["情若何，荀奉倩。","李贺 后园凿井歌"]]},{"n":"荀倩","d":"荀奉倩：指夫妻恩爱，或用以悼亡。唐李贺《后国凿井歌》：“情若何？荀奉倩。”","s":"《三国志》卷十〈魏书·荀彧传〉","q":[]}],"413":[{"n":"连城璧","d":"","s":"《史记》卷八十一〈廉颇蔺相如列传〉","q":[["连城犹隐石，唯有卞和知。","刘商 殷秀才求诗"],["璧从全赵去，鹏自北溟抟。","刘长卿 瓜洲驿奉钱张侍御公拜膳部郎中却复宪台充贺兰大夫留后使之岭南时侍御先在淮南幕府"]]},{"n":"十日饮","d":"十日欢：指朋友相见而饮酒尽欢。唐李白《寻鲁城北范居士失道落苍耳中见范置酒摘苍耳作》：“近作十曰欢，远为千载期。”","s":"《史记》卷七十九〈范雎蔡泽列传·范雎列传〉","q":[["愿学平原十日饮，此时不忍歌骊驹。","韩翃 赠兖州孟都督"]]},{"n":"武关盟","d":"","s":"《史记》卷八十四〈屈原贾生列传·屈原〉","q":[]}],"414":[{"n":"麒麟阁","d":"","s":"《汉书》卷五十四〈李广苏建列传·苏武〉","q":[["若非载笔登麟阁，定是吹箫伴凤台。","于季子 早春洛阳答杜审言"],["新登麒麟阁，适脱獬豸冠。","岑参 送张秘书充刘相公通汴河判官便赴江外觐省"]]},{"n":"弘恭陷萧望","d":"","s":"《汉书》卷七十八《萧望之传》","q":[["弘恭陷萧望，赵高谋李斯。阴德既必报，阴祸岂虚施。","白居易 读史五首之四"]]},{"n":"下走","d":"","s":"《汉书》卷七十八〈萧望之列传·萧望之〉","q":[]}],"415":[{"n":"东马严徐","d":"","s":"《汉书》卷六十四上〈严朱吾丘主父徐严终王贾列传上·严助〉","q":[]},{"n":"更生","d":"","s":"《史记》卷一百一十二〈平津侯主父列传〉","q":[]},{"n":"严徐","d":"","s":"《史记》卷一一二《平津侯主父列传》","q":[["北朝荣庾薛，西汉盛严徐。","常衮 晚秋集贤院即事寄徐薛二侍郎"]]}],"416":[{"n":"麒麟阁","d":"","s":"《汉书》卷五十四〈李广苏建列传·苏武〉","q":[["若非载笔登麟阁，定是吹箫伴凤台。","于季子 早春洛阳答杜审言"],["新登麒麟阁，适脱獬豸冠。","岑参 送张秘书充刘相公通汴河判官便赴江外觐省"]]},{"n":"莲勺困","d":"","s":"《汉书》卷八《宣帝纪》","q":[["皇孙犹曾莲勺困，卫庄见贬伤其足。","杜甫 赤霄行"]]},{"n":"五单于争立","d":"","s":"《汉书》卷九十四下〈匈奴列传下〉","q":[]}],"417":[{"n":"龙忌","d":"","s":"《后汉书》卷六十一〈左周黄列传·周举〉","q":[]},{"n":"一战霸","d":"","s":"《春秋左传·僖公二十七年》","q":[["虽免十上劳，何能一战霸。","韩愈 县斋有怀"]]},{"n":"重耳在楚","d":"","s":"《春秋左传正义》卷十五〈僖公·传二十三年〉","q":[]}],"418":[{"n":"七宝鞭","d":"七宝鞭：喻以智谋脱身。唐温庭筠《奉天西佛寺》：“宗臣欲舞千钧剑，追骑犹观七宝鞭。”","s":"《晋书》卷六《明帝纪》","q":[["君王指点新丰树，几不亲留七宝鞭。","唐彦谦 骊山道中"],["宗臣欲舞千钧剑，追骑犹观七宝鞭。","温庭筠 奉天西佛寺"]]},{"n":"一丘一壑","d":"","s":"《世说新语笺疏》中卷下〈品藻〉","q":[]},{"n":"元规端委，幼舆邱壑","d":"","s":"《世说新语笺疏》中卷下〈品藻〉","q":[]}],"419":[{"n":"皋陶夔契","d":"","s":"《尚书》卷三〈虞书·舜典〉","q":[]},{"n":"夔龙","d":"","s":"《尚书·虞书·舜典》","q":[["圣哲承休运，伊夔列上台。","丁仙芝 越棠贡白雉（一作孙昌胤诗）"],["并进夔龙位，仍齐龟鹤年。","刘禹锡 奉和淮南李相公早秋即事寄成都武相公"]]},{"n":"皋夔","d":"","s":"《尚书·虞书·舜典》","q":[["鸳鹭皆回席，皋夔亦慕膻。","韩偓 感事三十四韵"],["昨者州前搥大鼓，嗣皇继圣登夔皋。","韩愈 八月十五夜赠张功曹"]]}],"420":[{"n":"一枝春","d":"陇头梅：咏对朋友的思念之情，亦咏梅花。唐宋之问《题大庾岭北驿》：“明朝望乡处，应见陇头梅。”","s":"《太平御览》卷九百七十〈果部七·梅〉","q":[["绣衣屡许携家酝，皂盖能忘折野梅。","杜甫 王十七侍御抡许携酒至草堂奉寄此诗便请邀高三十五使君同到"],["欲为万里赠，杳杳山水隔。","柳宗元 早梅"]]},{"n":"范宣城","d":"","s":"《宋书》卷六十九《范晔传》","q":[["千人插羽迎，知是范宣城。","韩翃 送郢州郎使君"]]},{"n":"范晔顾儿","d":"","s":"《宋书》卷六十九〈范晔孔熙先列传〉","q":[["范晔顾其儿，李斯忆黄犬。","杜甫 八哀诗故秘书少监武功苏公源明"]]}],"421":[{"n":"韦平","d":"","s":"《汉书》卷七十三〈韦贤列传·韦贤〉","q":[]},{"n":"韦相积德","d":"","s":"《汉书》卷七十三《韦贤传》","q":[["莫埋丞相印，留着付玄成。","岑参 故仆射裴公挽歌三首"],["积德韦丞相，通神张子房。","崔泰之 同光禄弟冬日述怀"]]},{"n":"玄成","d":"","s":"《汉书》卷七十三《韦贤传》附《韦贤成传》","q":[["玄成知必大，宁是泛沧浪。","严维 送李秘书往儋州"],["玄成世业紫真官，文似相如貌胜潘。","崔峒 送韦八少府判官归东京"]]}],"422":[{"n":"拂衣","d":"","s":"《后汉书》卷五十四〈杨震列传·（曾孙）杨彪〉","q":[["肯学求名者，经年未拂衣。","李端 送丘丹归江东"],["吏情更觉沧洲远，老大悲伤未拂衣。","杜甫 曲江对酒"]]},{"n":"舐犊","d":"","s":"《后汉书》卷五十四《杨震传》附《杨彪传》","q":[["疲牛舐犊心犹切，阴鹤鸣雏力已衰。","罗隐 感别元帅尚父"]]},{"n":"四世三公","d":"","s":"《后汉书》卷五十四《杨震传》附《杨彪传》","q":[["四代三公族，清风播人天。","李白 送杨燕之东鲁"],["汉家名臣杨德祖，四代五公享茅土。","李颀 行路难"]]}],"423":[{"n":"齐眉","d":"齐眉：指夫妻间互敬互爱。唐李绅《趋翰苑遭诬拘四十六韵》：‘俯首安赢业，齐眉慰病夫。”","s":"《后汉书》卷八十三〈逸民列传·梁鸿〉","q":[["我非东床人，令姊忝齐眉。","李白 窜夜郎于乌江留别宗十六璟"],["俯首安羸业，齐眉慰病夫。","李绅 趋翰苑遭诬搆四十六韵"]]},{"n":"梁鸿","d":"鸿舂：指生活清贫。唐贾岛《送令狐绹相公》：“鸿舂乖汉爵，祯病卧漳滨。”","s":"《后汉书》卷八十三〈逸民列传·梁鸿〉","q":[["伯鸾游太学，中夜一相望。","储光羲 洛中贻朝校书衡朝即日本人也"],["元淑命不达，伯鸾吟可叹。","储光羲 贻刘高士别"]]},{"n":"洗粉黛","d":"","s":"《高士传》卷下《梁鸿列传》","q":[["客来洗粉黛，日暮拾流萤。","杜甫 奉酬薛十二丈判官见赠"]]}],"424":[{"n":"举仇","d":"","s":"《春秋左传·襄公二十一年》","q":[["举仇且不弃，何必论亲疏。夫子觉者也，其能遗我乎。","萧颍士 仰答韦司业垂访五首"]]},{"n":"十世宥","d":"","s":"《春秋左传·襄公二十一年》","q":[["苗裔当蒙十世宥，岂谓贻厥无基阯。","韩愈 寄卢仝"]]},{"n":"叔向婴拘","d":"","s":"《春秋左传正义》卷三十四〈襄公·传二十一年〉","q":[["岂知晋叔向，无罪婴囚拘。","萧颖士 仰答韦司业垂访五首"]]}],"425":[{"n":"百万呼卢","d":"","s":"《宋书》卷一〈武帝本纪〉","q":[["君莫笑刘毅从来布衣愿，家无儋石输百万。","杜甫 今夕行（原注。自齐赵西归至咸阳作。）"],["有时六博快壮心，绕床三匝呼一掷。","李白 猛虎行"]]},{"n":"刘毅答诏","d":"","s":"《晋书》卷四十五《刘毅传》","q":[["郭钦上书见大计，刘毅答诏惊群臣。","杜甫 暮秋枉裴道州手札率尔遣兴寄近（一作递）呈苏涣侍御"]]},{"n":"庾悦吝子鹅","d":"","s":"《晋书》卷五十二《庾悦传》","q":[["孔融不要留残脍，庾悦无端吝子鹅。","陆龟蒙 蔬食"]]}],"426":[{"n":"齐眉案","d":"","s":"《后汉书》卷八十三〈逸民列传·梁鸿〉","q":[]},{"n":"要离","d":"","s":"《吴越春秋》卷四〈阖闾内传·阖闾二年〉","q":[]},{"n":"要离杀庆忌","d":"","s":"东汉·赵晔《吴越春秋》卷四《阖闾内传》","q":[["要离杀庆忌，壮夫所素轻。妻子亦何辜，焚之买虚声。","李白 东海有勇妇"],["乃是要离客，西来欲报恩。","李白 赠武十七谔"]]}],"427":[{"n":"杜乔","d":"","s":"《后汉书》卷六十三《杜乔传》","q":[["跋扈以成梁冀在，简书难问杜乔归。","罗隐 经故洛阳城"]]},{"n":"李杜齐名","d":"","s":"《后汉书》卷六十三《李固杜乔传·赞》","q":[["李杜齐名真忝窃，朔云寒菊倍离忧。","杜甫 长沙送李十一"]]},{"n":"义夫","d":"","s":"《后汉书》卷六十三《杜乔传》","q":[["义夫留感激，公子播英名。","李绅 到宣武三十韵"]]}],"428":[{"n":"蛾眉螓首","d":"","s":"《诗经·卫风·硕人》","q":[["蛾眉一没空留怨，青冢月明啼夜乌。","刘沧 边思"],["东邻女新嫁，照镜弄蛾眉。","司马札 蚕女"]]},{"n":"瓠犀","d":"","s":"《毛诗正义》卷三之二（续）〈国风·卫风·硕人〉","q":[["一顾授横波，千金呈瓠犀。","权德舆 杂诗五首之三"],["新妆对镜知无比，微笑时时出瓠犀。","权德舆 杂诗五首之四"]]},{"n":"庄姜恨","d":"","s":"《诗经·邶风·燕燕·序》","q":[["整羽庄姜恨，回身汉后轻。","李山甫 燕"]]}],"429":[{"n":"愧卢前","d":"","s":"《旧唐书》卷一百九十上〈文苑列传上·杨炯〉","q":[]},{"n":"王勃","d":"","s":"《旧唐书》卷一百九十上〈文苑列传上·王勃〉","q":[]},{"n":"王杨","d":"","s":"《新唐书》卷二百一〈文艺列传上·序言〉","q":[]}],"430":[{"n":"恩波凤池","d":"","s":"《全唐诗》卷二百三十五〈早朝大明宫呈两省僚友〉","q":[]},{"n":"凝碧池","d":"","s":"《明皇杂录》","q":[["秋槐叶落空宫里，凝碧池头奏管弦。","王维 菩提寺禁裴迪来相看说逆贼等凝碧池上作音乐供奉人等举声便一时泪下私成口号诵示裴迪"]]},{"n":"摩诘丹青","d":"","s":"《新唐书》卷二百二〈文艺列传中·王维〉","q":[]}],"431":[{"n":"卓长官","d":"","s":"《后汉书》卷二十五〈卓鲁魏刘列传·卓茂〉","q":[["至今闾里逢灾沴，犹祝当时卓长官。","汪遵 密县"]]},{"n":"卓侯","d":"","s":"《后汉书》卷二十五〈卓鲁魏刘列传·卓茂〉","q":[["何当世祖从人望，早以公台命卓侯。","姚合 使两浙赠罗隐"]]},{"n":"卓鲁","d":"","s":"《昭明文选》卷四十三南朝齐·孔德璋（稚圭）《北山移文》","q":[["惭无卓鲁术，解印谢黔黎。","李嘉祐 南浦渡口"],["伯舅吏淮泗，卓鲁方喟然。","王维 奉送六舅归陆浑"]]}],"432":[{"n":"儿女探井臼","d":"","s":"《后汉书》卷二十八下《冯衍传》","q":[["儿女相悲探井臼，前功岂在他人后。","韩翃 送别郑明府"]]},{"n":"穷冯衍","d":"","s":"《后汉书》卷二十八下〈冯衍列传下·冯衍〉","q":[]},{"n":"冯衍归里","d":"","s":"《后汉书》卷二十八上《冯衍传》","q":[["冯衍归里，张昭塞门。","李瀚 蒙求"]]}],"433":[{"n":"细侯风韵","d":"","s":"《后汉书》卷三十一〈郭杜孔张廉王苏羊贾陆列传·郭伋〉","q":[["马嘶芳草自淹留，别馆何人属细侯。","羊士谔 游郭驸马大安山池"],["细侯风韵兼前事，不止为舟也作霖。","薛涛 和郭员外题万里桥"]]},{"n":"郭细侯","d":"","s":"《后汉书》卷三十一〈郭杜孔张廉王苏羊贾陆列传·郭伋〉","q":[["翩翩羽骑双旌后，上客亲随郭细侯。","司空曙 送卢彻之太原谒马尚书"],["上客刘公干，元戎郭细侯。","韩翃 送刘侍御赴令公行营"]]},{"n":"竹马待","d":"","s":"《后汉书》卷三十一《郭伋传》","q":[["人咏甘棠茂，童谣竹马群。","刘商 送庐州贾使君拜命"],["诗叟未相识，竹儿争见君。","孟郊 寄洛州李大夫"]]}],"434":[{"n":"李蔡为人在下中","d":"","s":"《史记》卷一百九〈李将军列传〉","q":[]},{"n":"李轻车","d":"","s":"《史记》卷一百一十一〈卫卫将军骠骑列传〉","q":[["翩翩新结束，去逐李轻车。","刘长卿 送南特进赴归行营"],["曾逐李轻车，西征出太蒙。","岑参 北庭贻宗学士道别"]]},{"n":"山西将","d":"","s":"《汉书》卷六十九〈赵充国辛庆忌列传〉","q":[]}],"435":[{"n":"方寸","d":"方寸：喻心。唐白居易《秋居书怀》：“尽日方寸中，澹然无所欲。”","s":"《三国志》卷三十五〈蜀书·诸葛亮传〉","q":[["字字烂嚼醍醐味，醍醐之味珍且美。不在唇，不在齿，只在劳生方寸里。","修雅 闻诵法华经歌"],["方寸终朝似火然，为求白日上青天。","刘得仁 省试日上崔侍郎四首"]]},{"n":"卧南阳","d":"南阳卧：指有才之士隐居家中。唐韩偓《寄隐者》：“渭滨晦迹南阳卧，若比吾徒更寂寥。”","s":"《三国志》卷三十五《蜀书·诸葛亮传》","q":[["一吟梁甫曲，知是卧龙才。","刘禹锡 和杨侍郎初至郴州纪事书情题郡斋八韵"],["早识卧龙应有分，不妨从此蹑丹梯。","刘禹锡 洛中送杨处厚入关便游蜀"]]},{"n":"徐庶","d":"","s":"《三国志》卷三十五〈蜀书·诸葛亮传〉","q":[["今代徐元直，高风自可亲。","唐彦谦 宿赵𡸯别业"],["徐庶高交友，刘牢出外甥。","杜甫 奉送二十三舅录事之摄郴州"]]}],"436":[{"n":"常何","d":"","s":"《新唐书》卷九十八〈马周列传〉","q":[]},{"n":"鸢肩火色","d":"","s":"《旧唐书》卷七十四〈马周列传〉","q":[]},{"n":"御史除周","d":"","s":"《旧唐书》卷七十四〈马周列传〉","q":[]}],"437":[{"n":"耳馀","d":"","s":"《汉书》卷三十二〈张耳陈馀列传·陈馀〉","q":[]},{"n":"随厮养","d":"","s":"《史记》卷八十九《张耳陈馀列传》","q":[["才淑随厮养，名贤隐锻炉。","杜甫 过南岳入洞庭湖"]]},{"n":"张陈","d":"","s":"《史记》卷八十九《张耳陈馀列传》","q":[["松篁贞管鲍，桃李艳张陈。","李咸用 论交"],["张陈竟火灭，萧朱亦星离。","李白 古风"]]}],"438":[{"n":"范彦龙","d":"","s":"《梁书》卷十三〈范云列传〉","q":[["为谢同僚老博士，范云来岁即公卿。","刘禹锡 寄杨八拾遗"],["望月逢殷浩，缘江送范云。","李端 送雍郢州"]]},{"n":"何范","d":"","s":"《梁书》卷四十九《文学传上·何逊传》","q":[["不妨何范尽诗家，未解当年重物华。","李商隐 漫成三首之一"],["沈范早知何水部，曹刘不待薛郎中。","杜甫 解闷十二首"]]},{"n":"沈范","d":"","s":"唐杜甫《解闷》诗之四","q":[]}],"439":[{"n":"卖饼","d":"卖饼：指因避难而隐姓埋名。清钱谦益《欲别东楼去四首》之三：“卖饼经寒食，吹萧过落花。”","s":"《后汉书》卷六十四《赵岐传》","q":[["宣城酒家保，北海卖饼师。","吴伟业 又咏古之六"],["卖饼经寒食，吹萧过落花。","钱谦益 欲别东楼去四首之三"]]},{"n":"忆孙宾","d":"","s":"《后汉书》卷六十四《赵岐传》","q":[["青云傥可致，北海忆孙宾。","陈子昂 酬李参军崇嗣旅馆见赠"]]},{"n":"赵岐忙","d":"","s":"《后汉书》卷六十四《赵岐传》","q":[["清论不知庄叟达，死交空欢赵岐忙。","罗隐 经故友所居"]]}],"440":[{"n":"青龙白虎车","d":"","s":"《神仙传》卷八《沈羲》","q":[["举手何所待，青龙白虎车。","李白 早望海霞边"]]},{"n":"沈羲","d":"","s":"《神仙传》卷七《沈义》","q":[["玉版徵书洞里看，沈羲新拜侍郎官。","司空图 贺翰林侍郎二首"],["玉诏新除沈侍郎，便分茅土镇东方。","曹唐 小游仙诗"]]},{"n":"玉书征","d":"","s":"晋·葛洪《神仙传》卷八","q":[["愿与金庭会，将待玉书徵。","陈子昂 题李三书斋（崇嗣）"]]}],"441":[{"n":"兰陵令","d":"","s":"《史记》卷七十四〈孟子荀卿列传〉","q":[]},{"n":"驱鸡","d":"","s":"东汉·荀况《申鉴》卷一《政体》","q":[["戴豸却驱鸡，东南上句溪。","许棠 送王侍御赴宣城"],["遁迹驱鸡吏，冥心失马翁。","许浑 泛溪"]]},{"n":"四海一家","d":"","s":"《荀子·议兵篇》","q":[]}],"442":[{"n":"廊庙器","d":"","s":"《三国志》卷三十八《蜀书·许靖传》","q":[["廊庙之具裴施州，宿昔一逢无此流。","杜甫 寄裴施州"],["上无皋陶伯益廊庙材，的不能匡君辅国活生民。","白居易 雪中晏起偶咏所怀兼呈张常侍韦庶子皇甫郎中"]]},{"n":"依马磨","d":"","s":"《三国志》卷三十八〈蜀书·许靖传〉","q":[]},{"n":"许靖","d":"","s":"《三国志》卷三十八《蜀书·许靖传》","q":[["许靖犹羁宦，安仁复悼亡。","李商隐 属疾"],["葛洪及许靖，避世常此路。","杜甫 咏怀二首之二"]]}],"443":[{"n":"芙蓉幕","d":"莲幕：美称官署的幕府、幕僚。唐李商隐《自桂林奉使江陵途中感怀寄献尚书》：“下客依莲幕，明公念竹林。”","s":"《南史》卷四十九〈庾杲之列传〉","q":[["弊貂不称芙蓉幕，衰朽仍惭玳瑁簪。","吴仁璧 投谢钱武肃"],["亦知莲府客，夜坐喜同师。","姚合 送无可上人游边"]]},{"n":"无鲑菜","d":"","s":"《南齐书》卷三十四〈庾杲之列传〉","q":[["自愧无鲑菜，空烦卸马鞍。","杜甫 王竟携酒高亦同过共用寒字"]]},{"n":"庾郎","d":"","s":"《南齐书》卷三十四《庾杲之传》","q":[["庾郎盘马地，却怕有春泥。","唐彦谦 春雨"],["庾郎年最少，青草妒春袍。","李商隐 春游"]]}],"444":[{"n":"聱叟","d":"","s":"《新唐书》卷一百四十三〈元结列传〉","q":[]},{"n":"元郎太漫","d":"","s":"《全唐文》卷三百八十一〈元结二·自释书〉","q":[]},{"n":"中兴碑","d":"","s":"《全唐文》卷三百八十〈元结·大唐中兴颂〉","q":[]}],"445":[{"n":"湘夫人","d":"江娥啼竹：咏忧伤之情，或咏竹。唐李贺《李凭箜篌引》：“江娥啼竹素女愁，李凭中国弹箜篌。”","s":"《艺文类聚》卷八十九〈木部下·竹〉","q":[["愁如湘灵哭湘浦，咽咽哀音隔云雾。九嶷深翠转巍峨，仙骨寒消不知处。","僧鸾 赠李粲秀才"],["河汉夜阑孤雁度，潇湘水阔二妃愁。","刘沧 江楼月夜闻笛"]]},{"n":"湘灵鼓瑟","d":"","s":"《楚辞补注》卷五〈远游〉","q":[["鼓宜尧女瑟，荡必蔡姬舟。","吴融 御沟十六韵"],["遥知月落酒醒处，五十弦从波上来。","吴融 送荆南从事之岳州"]]},{"n":"朱宫姊妹","d":"","s":"《楚辞补注》卷二〈九歌·河伯〉","q":[]}],"446":[{"n":"索靖","d":"","s":"《晋书》卷三十六《卫瓘传》","q":[["劝君火急添功用，趁取当时二妙声。","柳宗元 叠后"],["银钩屈曲索靖，题桥司马相如。","范尧佐 书"]]},{"n":"铜驼荆棘","d":"泣铜驼：指对国家人民遭劫难感到悲伤。唐李商隐《曲江》：“死忆华亭闻鹤嗅，老忆王室泣铜驼。”","s":"《晋书》卷六十〈索靖列传〉","q":[["死忆华亭闻唳鹤，老忧王室泣铜驼。天荒地变心虽折，若比伤春意未多。","李商隐 曲江"]]},{"n":"银钩","d":"","s":"《晋书》卷六十《索靖传》","q":[["旧迹依然已十秋，雪山当面照银钩。","杜牧 三川驿伏览座主舍人留题"],["霜雪回光避锦袖，龙蛇动箧蟠银钩。","杜甫 寄裴施州"]]}],"447":[{"n":"翻覆手","d":"","s":"《史记》卷九十七〈郦生陆贾列传·陆贾〉","q":[["翻手作云覆手雨，纷纷轻薄何须数。","杜甫 贫交行"]]},{"n":"陆贾装","d":"陆贾分金：指官吏退休后安排家业，分发钱财。唐骆宾王《帝京篇》：“陆贾分金将宴喜，陈遵投辖正留宾。”","s":"《汉书》卷四十三〈郦陆朱刘叔孙列传·陆贾〉","q":[["我有延陵剑，君无陆贾金。","李白 送曲十少府"],["行李千金赠，衣冠八尺身。","杜甫 奉寄李十五秘书二首"]]},{"n":"千金橐","d":"","s":"《史记》卷九十七〈郦生陆贾列传·陆贾〉","q":[]}],"448":[{"n":"羲皇上","d":"羲皇人：指生活清闲自适。唐李白《戏赠郑溧阳》：“清风北窗下，自谓羲皇人。”","s":"《全上古三代秦汉三国六朝文·全晋文》卷一百十一〈陶潜·与子俨等书〉","q":[["腹中无一物，高话羲皇年。","储光羲 同王十三维偶然作十首之三"],["竹庭瓶水新，深称北窗人。","周贺 赠皎然上人（一本无皎字）"]]},{"n":"伏羲初制","d":"","s":"《太平御览》卷五七六","q":[["伏羲初制法，素女昔传名。","李峤 瑟"]]},{"n":"太昊","d":"","s":"《吕氏春秋·纪部》卷一〈孟春纪·孟春〉～","q":[["太昊弛维纲，畏避但守谦。","韩愈 苦寒"]]}],"449":[{"n":"茅氏","d":"","s":"《史记》卷六《秦始皇本纪》","q":[["若逢茅氏传消息，贞白先生不久归。","储嗣宗 和茅山高拾遗忆山中杂题五首巢鹤"],["须存彭寿千年在，终见茅公九转成。","罗邺 献池州庾员外"]]},{"n":"茅山道士","d":"","s":"《太平广记》卷十三〈神仙十三·茅君〉","q":[["久向三茅穷艺术，仍传五柳旧琴书。","李群玉 送陶少府赴选"],["仙山如有分，必拟访三茅。","郑谷 池上"]]},{"n":"三茅兄弟","d":"","s":"《太平御览》卷六百六十一〈道部三·真人下〉2～","q":[]}],"450":[{"n":"披云雾","d":"乐广披云：喻人风神朗澈，或借用指云开天晴。唐张聿《圆灵水镜》：“乐广披云日，山涛卷雾年。”","s":"《世说新语笺疏》中卷下〈赏誉〉","q":[["乐广披云日，山涛卷雾年。","张聿 圆灵水镜"],["披云自有镜，从此照仙台。","张谔 赠吏部孙员外济"]]},{"n":"卫瓘","d":"","s":"《晋书》卷三十六《卫瓘传》","q":[["黄庭留卫瓘，绿树养韩冯。","李贺 恼公"]]},{"n":"卫瓘抚床","d":"","s":"《晋书》卷三十六《卫瓘传》","q":[["袁盎却座，卫瓘抚床。","李瀚 蒙求"]]}],"451":[{"n":"绝妙辞","d":"色丝文：称赞文章文辞华美。唐赵嘏《题曹娥庙》：“文字在碑碑已堕，波涛辜负色丝文。”","s":"《世说新语笺疏》中卷下〈捷悟〉","q":[["碑缺曹娥宅，林荒逸少居。","刘长卿 无锡东郭送友人游越"],["越鸟闻花里，曹娥想镜中。","刘长卿 送崔处士先适越"]]},{"n":"曹娥泣江","d":"","s":"《后汉书》卷八十四〈列女列传·孝女曹娥〉","q":[]},{"n":"葬鱼娘子","d":"","s":"《太平御览》卷三十一〈时序部十六·五月五日〉2～","q":[]}],"452":[{"n":"安期生","d":"","s":"晋·葛洪《抱朴子·内篇·极言》","q":[["携琴侍叔夜，负局访安期。","上官婉儿 游长宁公主流杯池二十五首之十五"],["西峰望紫云，知处安期生。","于鹄 宿西山修下元斋咏"]]},{"n":"安期枣","d":"安期枣：咏仙道，或称美瓜果。唐元稹《和乐天赠吴丹》：“冥搜方朔桃，结念安期枣。”","s":"《史记》卷二十八〈封禅书〉","q":[["亲见安期公，食枣大如瓜。","李白 寄王屋山人孟大融"],["神与枣兮如瓜，虎卖杏兮收谷。","王维 送友人归山歌二首"]]},{"n":"寻安期","d":"","s":"旧题晋·嵇含《南方草木状》卷上","q":[["惟有安期舄，留之沧海隅。","李白 赠张相镐二首之二"],["安期始遗舄，千古谢荣耀。投迹庶可齐，沧浪有孤棹。","王昌龄 观江淮名胜图"]]}],"453":[{"n":"拜井","d":"","s":"《艺文类聚》第九卷〈水部下·泉〉","q":[["誓令疏勒出飞泉，不似颍川空使酒。","王维 老将行"],["耿恭拜出井底水，广利刺开山上泉。","顾云 天威行"]]},{"n":"将军佩","d":"","s":"《东观汉记》卷十〈耿恭传〉","q":[["讵要方士符，何假将军盖。","杜甫 信行远修水筒"]]},{"n":"全疏勒","d":"","s":"《后汉书》卷十九《耿弇传》附《耿恭传》","q":[["节比全疏勒，功当雪会稽。","皇甫冉 和袁郎中破贼后经剡中山水"]]}],"454":[{"n":"逸书","d":"","s":"《史记》卷一百二十一〈儒林列传〉","q":[["儒中年最老，独有济南生。","司空曙 送王先生归南山"],["羞作济南生，九十诵古文。","李白 赠何七判官昌浩"]]},{"n":"伏生九十传书","d":"","s":"《史记》卷一百二十一〈儒林列传〉","q":[]},{"n":"老伏虔","d":"","s":"《汉书》卷八十八《伏生传》","q":[["弟子贫原宪，诸生老伏虔。","杜甫 寄岳州贾司马六丈巴州严八使君两阁老五十韵"]]}],"455":[{"n":"孟尝搀一日","d":"","s":"《史记》卷七十五〈孟尝君列传〉","q":[]},{"n":"田文好客","d":"","s":"《史记》卷七十五〈孟尝君列传〉","q":[]},{"n":"原尝春陵","d":"","s":"《史记》卷七十六〈平原君虞卿列传·平原君〉","q":[["原尝春陵六国时，开心写意君所知。堂中各有三千士，明日报恩知是谁。","李白 扶风豪士歌"]]}],"456":[{"n":"缝掖贵","d":"缝掖贵：指礼待儒生贤士。唐高适《同李太守北池泛舟宴高平郑太守》：“乃知缝掖贵，今日对诸侯。”","s":"《后汉书》卷四十九〈王充王符仲长统列传·王符〉","q":[["邹阳长裾，王符逢（缝）掖。","李瀚 蒙求"],["乃知缝掖贵，今日对诸侯。","高适 同李太守北池泛舟宴高平郑太守"]]},{"n":"潜夫论","d":"","s":"《后汉书》卷四十九《王符传》","q":[["鹿袖青藜鼠耳巾，潜夫岂解拜朝臣。","刘言史 山中喜崔补阙见寻"],["一片白葛巾，潜夫自能结。","刘言史 葛巾歌"]]},{"n":"三贤","d":"","s":"《全唐文》卷五百五十七〈韩愈十一·后汉三贤赞三首〉","q":[]}],"457":[{"n":"阿奴碌碌","d":"","s":"《世说新语笺疏》中卷上〈识鉴〉","q":[]},{"n":"才短","d":"","s":"《世说新语笺疏》中卷上〈识鉴〉","q":[["才短难自力，惧终莫洗湔。","韩愈 示爽"]]},{"n":"周嵩狼抗","d":"","s":"《世说新语》中卷上《识鉴》","q":[["周嵩狼抗，梁冀跋扈。","李瀚 蒙求"]]}],"458":[{"n":"孔雀东飞","d":"","s":"《玉台新咏》卷一《古诗为焦仲卿妻作·序》","q":[["孔雀东飞何处栖，庐江小吏仲卿妻。","李白 庐江主人妇"]]},{"n":"庐江小吏","d":"","s":"《玉台新咏》卷一《古诗为焦仲卿妻作·序》","q":[["卢江小吏朱斑轮，柳缕吐芽香玉春。悠悠楚水流如马，恨紫愁红满平野。","温庭筠 懊恼曲"]]},{"n":"庐江吏妇","d":"","s":"《玉台新咏》卷一《古诗为焦仲卿妻作·序》","q":[["庐江小吏妇，非关织作迟。","乔知之 定情篇"]]}],"459":[{"n":"膝上王文度","d":"","s":"《晋书》卷七十五〈王湛列传·（王承子）王述〉","q":[]},{"n":"人言我不如公","d":"","s":"《世说新语笺疏》中卷上〈方正〉","q":[]},{"n":"王述忿狷","d":"","s":"《世说新语》下卷下《忿娟》","q":[["王述忿狷，荀粲惑溺。","李瀚 蒙求"]]}],"460":[{"n":"鸢肩火色","d":"","s":"《旧唐书》卷七十四〈马周列传〉","q":[]},{"n":"御史除周","d":"","s":"《旧唐书》卷七十四〈马周列传〉","q":[]},{"n":"倦客新丰","d":"","s":"《新唐书》卷九十八〈马周列传〉","q":[]}],"461":[{"n":"穷愁著书","d":"","s":"《史记》卷七十六〈平原君虞卿列传·虞卿〉","q":[["谁遣虞卿裁道帔，轻绡一匹染朝霞。","李贺 南园十三首之十二"],["若逢金马门前客，为说虞卿久著书。","段成式 送穆郎中赴阙"]]},{"n":"魏齐首","d":"","s":"《史记》卷七十九《范雎列传》","q":[["安知魏齐首，见断箦中尸。","杜牧 杜秋娘诗"]]},{"n":"箦中尸","d":"","s":"《史记》卷七十九《范雎列传》","q":[["安知魏齐首，见断箦中尸。","杜牧 杜秋娘诗"]]}],"462":[{"n":"褒妲","d":"","s":"《国语》卷七《晋语一》","q":[["中自诛褒妲，周汉获再兴。","杜甫 北征"]]},{"n":"褒女","d":"","s":"《国语》卷七〈晋语一·史苏论献公伐骊戎胜而不吉〉","q":[["褒姒冢前烽火起，不知泉下破颜无。","唐彦谦 登兴元城观烽火"],["未免被他褒女笑，只教天子暂蒙尘。","李商隐 华清宫"]]},{"n":"褒姒笑","d":"","s":"《毛诗正义》卷十二之一〈小雅·节南山之什·正月〉","q":[]}],"463":[{"n":"辕下驹","d":"","s":"《史记》卷一百七〈魏其武安侯列传〉","q":[["赠尔秦人策，莫鞭辕下驹。","杜甫 别苏傒"],["出尘皆野鹤，历块匪辕驹。","杜甫 大历三年春白帝城放船出瞿塘峡久居夔府将适江陵漂泊有诗凡四十韵"]]},{"n":"田窦","d":"","s":"《史记》卷一○七《魏其武安侯列传》","q":[["田窦相倾夺，宾客互盈亏。","李白 古风之五十九"],["田窦方贵幸，赵李新相知。","郑愔 少年行"]]},{"n":"田窦醉","d":"","s":"《史记》卷一○七《魏其武安侯列传》","q":[["田窦长留醉，苏辛曲护岐。","杜牧 少年行"]]}],"464":[{"n":"悬瓠","d":"","s":"《旧唐书》卷一百三十三〈李晟列传·李愬〉","q":[]},{"n":"临淮李","d":"","s":"《旧唐书》卷一百三十三〈李晟列传·李愬〉","q":[]},{"n":"平淮裴度","d":"","s":"《旧唐书》卷一百七十〈裴度列传〉","q":[]}],"465":[{"n":"一丸泥","d":"一丸封：喻指勇士守险。宋王安石《西帅》：“一丸岂虑封函谷，千骑无由饮渭桥。”","s":"《后汉书》卷十三〈隗嚣公孙述列传·隗嚣〉","q":[["未见泥函谷，俄惊火建章。","唐彦谦 送樊琯司业归朝"],["不将千里隔，何用一丸泥。","张说 奉和圣制潼关口号应制"]]},{"n":"伏波米","d":"聚米：指军事上分析地形。明陈瑚《李映碧廷尉遗地图》：“人关无复萧丞相，聚米空思马伏波。”","s":"《后汉书》卷二十四〈马援列传·马援〉","q":[["运筹知决胜，聚米似论边。","韦应物 酬豆卢仓曹题库壁见示"]]},{"n":"隗嚣","d":"","s":"《后汉书》卷十三《隗嚣传》","q":[["几时睿算歼张角，何处愚人戴隗嚣。","罗隐 中元甲子以辛丑驾幸蜀四首之二"],["难问开元向前事，依稀犹认隗嚣宫。","许棠 成纪书事二首之二"]]}],"466":[{"n":"投梭","d":"投杼：指流言可畏。唐李白《系寻阳上崔相涣三首》之二：“虚言误公子，投杼惑慈亲。”；谗言三及：喻受谗言诬陷。唐李白《答三十二寒夜独酌有怀》：“曾参岂是杀人者，谗言三及慈母惊。”","s":"《战国策》卷四〈秦策·秦武王谓甘茂〉","q":[["曾参岂是杀人者，谗言三及慈母惊。","李白 答王十二寒夜独酌有怀"],["毛遂不堕井，曾参宁杀人。虚言误公子，投杼惑慈亲。","李白 系寻阳上崔相涣三首之二"]]},{"n":"曾参","d":"","s":"《论语·学而》","q":[["唯修曾子行，不著老莱衣。","姚合 送王龟处士"],["既有曾参行，仍兼君子儒。","崔璐 览皮先辈盛制因作十韵以寄用伸款仰"]]},{"n":"颜曾","d":"","s":"词典","q":[]}],"467":[{"n":"闭门高卧","d":"","s":"《后汉书》卷四十五〈袁张韩周列传·袁安〉","q":[["雪霁凝光入座寒，天明犹自卧袁安。","吴仁璧 春雪"],["玉尘销欲尽，穷巷起袁安。","姚康 礼部试早春残雪"]]},{"n":"袁安","d":"","s":"《后汉书》卷四十五《袁安传》","q":[["谁怜高卧处，岁暮叹袁安。","何频瑜 墙阴残雪"],["不知轩屏侧，岁晚对袁安。","刘长卿 同郭参谋咏崔仆射淮南节度使厅前竹"]]},{"n":"袁安坠睫","d":"","s":"《后汉书》卷四十五《袁安传》","q":[["袁安坠睫寻忧汉，贾谊濡毫但过秦。","韩偓 八月六日作四首"]]}],"468":[{"n":"粉郎","d":"何郎：称赞青年男子貌美，或指情郎或驸马。唐李贺《同沈驸马赋得御沟水》：“幸因流浪处，暂得见何郎。”","s":"《世说新语笺疏》下卷上〈容止〉","q":[["汤饼赐都尉，寒冰颁上才。","刘禹锡 翠微寺有感"],["何郎独在无恩泽，不似当初傅粉时。","刘禹锡 题于家公主旧宅"]]},{"n":"何平叔","d":"","s":"《三国志》卷九《魏书·曹爽传》附《何晏传》","q":[["寄语何平叔，无为轻老生。","刘禹锡 寓兴二首之一"],["戚里旧知何驸马，诗家今得鲍参军。","杨巨源 酬于驸马二首之一"]]},{"n":"何晏神伏","d":"","s":"《世说新语》上卷下《文学》","q":[["何晏神伏，郭奕心醉。","李瀚 蒙求"]]}],"469":[{"n":"醉为乡","d":"","s":"《新唐书》卷一百九十六〈隐逸列传·王绩〉","q":[]},{"n":"焦革","d":"","s":"《新唐书》卷一百九十六〈隐逸列传·王绩〉","q":[]},{"n":"三升官酒","d":"","s":"《新唐书》卷一百九十六〈隐逸列传·王绩〉","q":[]}],"470":[{"n":"祭遵","d":"","s":"《后汉书》卷二十《祭遵传》","q":[["人思崔琰议，朝掩祭遵公。","张九龄 和姚令公哭李尚书乂"]]},{"n":"祭遵布被","d":"","s":"《后汉书》卷二十《祭遵传》","q":[["孔伋缊袍，祭遵布被。","李瀚 蒙求"]]},{"n":"投壶","d":"","s":"《后汉书》卷二十《祭遵传》","q":[["杖钺褰帷瞻具美，投壶散帙有馀清。","杜甫 江陵节度阳城郡王新楼成王请严侍御判官赋七字句同作"]]}],"471":[{"n":"沉豪牛","d":"","s":"《穆天子传》卷一《披图视典章》","q":[["鲛人献微绡，曾祝沈豪牛。","杜甫 奉同郭给事汤东灵湫作"]]},{"n":"旷原","d":"","s":"《穆天子传》卷三《旷原大猎章》","q":[["阆风入辙迹，旷原延冥搜。","杜甫 奉同郭给事汤东灵湫作"]]},{"n":"献宝","d":"","s":"《穆天子传》卷一","q":[["欲问支机石，如临献宝宫。","杜甫 天池"],["自从献宝朝河宗，无复射蛟江水中。","杜甫 韦讽录事宅观曹将军画马图"]]}],"472":[{"n":"焚稿","d":"","s":"《晋书》卷三十四《羊祜传》","q":[["藏弓身已退，焚稿事难闻。","刘长卿 秋日夏口涉汉阳献李相公"],["对客默焚稿，何人知谏书。","杨巨源 和卢谏议朝回书情即事寄两省阁老兼呈二起居谏院诸院长"]]},{"n":"王谢风流","d":"乌衣巷：喻王公贵族的居处，或咏王公贵族之往事。唐刘禹锡《乌衣巷》：“朱雀桥边野草花，乌衣巷口夕阳斜。”","s":"《世说新语笺疏》中卷上〈雅量〉","q":[["朱雀桥边野草花，乌衣巷口夕阳斜。","刘禹锡 金陵五题"],["旧时王谢堂前燕，飞入寻常百姓家。","刘禹锡 金陵五题乌衣巷"]]},{"n":"堂前燕","d":"","s":"《全唐诗》卷三百六十五〈金陵五题五首〉","q":[]}],"473":[{"n":"郭文游山","d":"","s":"《晋书》卷九十四《隐逸传·郭文传》","q":[["郭文游山，袁宏泊渚。","李瀚 蒙求"]]},{"n":"不畏虎","d":"不畏虎：咏高人隐士。宋苏轼《南溪之南竹林中……故名之曰避世堂》：“高人不畏虎，避世已无心。”","s":"《晋书》卷九十四《隐逸传·郭文传》","q":[["更议居远村，避喧甘猛虎。","杜甫 贻阮隐居（昉）"]]},{"n":"鹿裘","d":"","s":"晋·皇甫谧《高士传》卷上","q":[["空山三十年，鹿裘挂窗睡。","杜牧 送沈处士赴苏州李中丞招以诗赠行"],["带月乘渔艇，迎寒绽鹿裘。","秦系 山中崔大夫大书相问"]]}],"474":[{"n":"蓬莱清浅","d":"桑田：喻世事变迁极快、极大。或谓时间久远。唐王绩《游仙四首》之一：“自悲生死促。无暇待桑田。”","s":"《神仙传》卷七〈麻姑〉～","q":[["独往不可群，沧海成桑田。","储光羲 献八舅东归"],["已见松柏摧为薪，更闻桑田变成海。","刘希夷 代悲白头翁"]]},{"n":"麻姑","d":"","s":"晋·葛洪《神仙传》卷七《麻姑》","q":[["欲共麻姑住，仙城半在空。","徐凝 武夷山仙城"],["曾于方外见麻姑，闻说君山自古无。","方干 题君山"]]},{"n":"麻姑爪","d":"","s":"晋·葛洪《神仙传》卷二《王远》","q":[["直遣麻姑与搔背，可能留命待桑田。","李商隐 海上"],["明星玉女备洒扫，麻姑搔背指爪轻。","李白 西岳云台歌送丹丘子"]]}],"475":[{"n":"半面妆","d":"徐妃半面妆：喻仅及一半，未得全貌。唐李商隐《南朝》：“休夸此地分天下，只得徐妃半面妆。”","s":"《南史》卷十二〈后妃列传第下·元帝徐妃〉","q":[["夫君每尚风流事，应为徐妃致此栽。","司马都 和陆鲁望白菊"],["休誇此地分天下，只得徐妃半面妆。","李商隐 南朝"]]},{"n":"长袖留宾","d":"","s":"《艺文类聚》卷八十","q":[["长袖平阳曲，新声子夜歌。从来惯留客，兹夕为谁多。","孟浩然 崔明府宅夜观妓"],["城南无夜月，长袖莫留宾。","钱起 江陵晦日陪诸官泛舟"]]},{"n":"收庾信","d":"","s":"《周书》卷四十一《庾信传》","q":[["共传收庾信，不比得陈琳。","杜甫 奉赠王中允"]]}],"476":[{"n":"放麑","d":"","s":"《韩非子》卷七〈说林上〉","q":[]},{"n":"放麑翁","d":"放麑翁：喻选用仁人。唐陈子昂《感遇诗三十八首》之四：““吾闻山中相，乃属放麑翁。”（此句误将鲁大夫孟孙误为中山相）","s":"《韩非子》卷七〈说林上〉","q":[["我欲拣其养，放麛者是谁。","孟郊 子庆诗"],["吾闻中山相，乃属放麑翁。","陈子昂 感遇诗三十八首"]]},{"n":"孟孙问孝","d":"","s":"《论语注疏·为政》","q":[["孟孙唯问孝，莱子复辞官。","皇甫冉 刘侍御朝命停官归侍"]]}],"477":[{"n":"藏拙","d":"","s":"唐·刘鋉《隋唐嘉话》","q":[["纵无显效亦藏拙，若有所成甘守株。","罗隐 自贻"]]},{"n":"天上麒麟","d":"","s":"《陈书》卷二十六〈徐陵列传〉","q":[["黄祖不怜鹦鹉客，志公偏赏麒麟儿。","李山甫 赴举别所知"],["天上麒麟时一下，人间不独有徐陵。","杜牧 赠李秀才"]]},{"n":"徐庾","d":"","s":"《北史》卷八十三〈文苑列传·庾信〉","q":[["尘埃徐庾词，金玉曹刘名。","孟郊 赠苏州韦郎中使君"],["南朝徐庾流，洛下忆同游。","罗隐 商于驿与于蕴玉话别"]]}],"478":[{"n":"犀烛","d":"","s":"《晋书》卷六十七《温峤传》","q":[["黑皮年少学采珠，手把生犀照咸水。","施肩吾 岛夷行"],["犀烛江行见鬼神，木人登席呈歌舞。","李端 杂歌"]]},{"n":"玉镜台","d":"","s":"《世说新语笺疏》下卷下〈假谲〉","q":[["君不见温家玉镜台，提携抱握九重来。","张纮 行路难"],["羊权须得金条脱，温峤终虚玉镜台。","李商隐 中元作"]]},{"n":"江左管夷吾","d":"","s":"《世说新语笺疏》上卷上〈言语〉","q":[]}],"479":[{"n":"一斗之胆","d":"胆大姜伯约：喻有胆量、勇猛。唐韩捆《送刘将军》：“胆大欲期姜伯约，功多不让李轻车。”","s":"《三国志》卷四十四〈蜀书·姜维传〉","q":[["一斗之胆撑脏腑，如磥之筋碍臂骨。","施肩吾 壮士行"],["胆大欲期姜伯约，功多不让李轻车。","韩翃 送刘将军"]]},{"n":"姜维","d":"","s":"《三国志》卷四十四〈蜀书·姜维传〉","q":[]},{"n":"骆谷姜维","d":"","s":"《三国志》卷四十四〈蜀书·姜维传〉","q":[]}],"480":[{"n":"下泽车","d":"款段：喻指普通的生活或侮悟之情。唐李白《江南赠韦南陵冰》：“昔骑天子大宛马，今乘款段诸侯门。”","s":"《东观汉记校注》卷十二〈马援传〉","q":[["有时鞭款段，尽日醉儚僜。","元稹 纪怀赠李六户曹崔二十功曹五十韵"],["谁采中原菽，徒巾下泽车。","柳宗元 同刘二十八院长述旧言怀感时书事奉寄澧州张员外使君五十二韵之作因其韵增至八十通赠二君子"]]},{"n":"马少游","d":"","s":"《后汉书》卷二十四《马援传》","q":[["一以功名累，翻思马少游。","刘禹锡 经伏波神祠"]]},{"n":"求赢馀","d":"","s":"《后汉书》卷二十四《马援传》","q":[["岂必求赢馀，所要石与甔。","韩愈 秋怀诗十一首之七"]]}],"481":[{"n":"桀纣","d":"桀纣：夏桀与商纣的合称。二人皆因无道，为商汤与周武王所灭。后用以为残暴之君的代称。；辛癸：商纣 、 夏桀 的并称。 商纣 名 帝辛 ， 夏桀 名 履癸 ，两人均为有名的暴君。","s":"《孟子·离娄上》","q":[]},{"n":"裂缯","d":"","s":"《太平御览》卷一三五","q":[["自从命向红儿去，不欲留心在裂缯。","罗虬 比红儿诗之二十四"]]},{"n":"瑶台","d":"","s":"《淮南子》卷八《本经训》","q":[["黄屋非尧意，瑶台安可论。","陈子昂 感遇诗三十八首之十九"],["瑶台倾巧笑，玉杯殒双蛾。","陈子昂 感遇诗三十八首之十二"]]}],"482":[{"n":"庞涓怯孙膑","d":"","s":"《史记》卷六十五〈孙子吴起列传·孙子〉","q":[["回军与角逐，斫树收穷庞。","韩愈 病中赠张十八"],["尔来但欲保封疆，莫学庞涓怯孙膑。","韩愈 赠崔立之评事"]]},{"n":"辱庞涓","d":"","s":"《史记》卷六十五〈孙子吴起列传·孙子〉","q":[]},{"n":"孙膑伏兵","d":"","s":"《史记》卷六十五〈孙子吴起列传·孙子〉","q":[]}],"483":[{"n":"闭门著书","d":"","s":"《后汉书》卷四十九〈王充王符仲长统列传·王充〉","q":[["左思裁赋日，王充作论年。","李峤 砚"],["闭户著书多岁月，种松皆老作龙鳞。","王维 春日与裴迪过新昌里访吕逸人不遇"]]},{"n":"三贤","d":"","s":"《全唐文》卷五百五十七〈韩愈十一·后汉三贤赞三首〉","q":[]},{"n":"王充阅市","d":"","s":"《后汉书》卷四十九〈王充王符仲长统列传·王充〉","q":[["王充阅市，董生下帷。","李瀚 蒙求"]]}],"484":[{"n":"韩彭","d":"","s":"《昭明文选》卷四十一汉·李少卿（陵）《答苏武书》","q":[["战败仍树勋，韩彭但空老。","刘长卿 从军六首之五"],["苍生属伊吕，明主仗韩彭。","刘长卿 至德三年春正月时谬蒙差摄海盐令闻王师收二京因书事寄上浙节度李侍郎中丞行营五十韵"]]},{"n":"彭黥菹醢","d":"","s":"《昭明文选》卷四十一汉·李少卿（陵）《答苏武书》","q":[["乍如彭与黥，呼冤受菹醢。","韩愈 嘲鼾睡二首之一"]]},{"n":"信越","d":"","s":"《史记》卷七《项羽本纪》","q":[["爪牙驱信越，腹心谋张陈。","王圭 咏汉高祖"],["信越功名高似狗，裴王气力大于牛。","罗隐 关亭春望"]]}],"485":[{"n":"胡威","d":"","s":"《三国志》卷二十七《魏书·胡质传》","q":[["双溪泊船处，候吏拜胡威。","权德舆 送卢评事婺州省觐"],["荀氏风流远，胡家清白齐。","皇甫冉 送李万州赴饶州觐省"]]},{"n":"问绢","d":"","s":"《三国志》卷二十七《魏书·胡广传》","q":[["采兰度汉水，问绢过荆州。","岑参 送陶铣弃举荆南觐省"],["君怀一匹胡威绢，争拭酬恩泪得乾。","李商隐 送郑大台文南觐"]]},{"n":"胡质矫","d":"","s":"《三国志》卷二十七〈魏书·胡质传〉","q":[["肯随胡质矫，方恶马融奢。","柳宗元 同刘二十八院长述旧言怀感时书事奉寄澧州张员外使君五十二韵之作因其韵赠至八十通赠二君子"]]}],"486":[{"n":"胡威","d":"","s":"《三国志》卷二十七《魏书·胡质传》","q":[["双溪泊船处，候吏拜胡威。","权德舆 送卢评事婺州省觐"],["荀氏风流远，胡家清白齐。","皇甫冉 送李万州赴饶州觐省"]]},{"n":"问绢","d":"","s":"《三国志》卷二十七《魏书·胡广传》","q":[["采兰度汉水，问绢过荆州。","岑参 送陶铣弃举荆南觐省"],["君怀一匹胡威绢，争拭酬恩泪得乾。","李商隐 送郑大台文南觐"]]},{"n":"清白传家","d":"","s":"《三国志》卷二十七〈魏书·胡质传〉","q":[]}],"487":[{"n":"辽东豕","d":"","s":"《东观汉记》卷十五〈朱浮传〉","q":[["辽东惭白豕，楚客羞山鸡。","李白 赠范金卿二首之一"]]},{"n":"渔阳结怨","d":"","s":"《后汉书》卷三十三《朱浮传》","q":[["比讶渔阳结怨恨，元听舜日旧箫韶。","杜甫 夔州歌十绝句"]]},{"n":"中风走","d":"","s":"《后汉书》卷三十三〈朱冯虞郑周列传·朱浮〉","q":[["穷迫挫曩怀，常如中风走。","杜甫 上水遣怀"]]}],"488":[{"n":"商君阡陌","d":"","s":"《史记》卷六十八《商君列传》","q":[["汉帝宫将苑，商君陌与阡。","张九龄 奉和吏部崔尚书雨后大明朝堂望南山"]]},{"n":"商鞅徙木","d":"","s":"《史记》卷六十八〈商君列传〉","q":[]},{"n":"商羊舞","d":"","s":"《孔子家语》卷三〈辩政〉","q":[["百足虽捷捷，商羊亦翘翘。","元稹 酬刘猛见送"],["自是湘州石燕飞，那关齐地商羊舞。","李端 荆门歌送兄赴夔州"]]}],"489":[{"n":"雷居士","d":"","s":"《宋书》卷九十三《隐逸传·雷次宗传》","q":[["我与雷居士，平生事远公。","李端 同司空文明过坚上人故院"],["为报故人雷处士，尘心终日自劳生。","耿湋 宿万固寺因寄严补阙"]]},{"n":"雷远","d":"","s":"《宋书》卷九十三《隐逸传·雷次宗传》","q":[["既得庐霍趣，乃高雷远情。","皎然 杼山禅居寄赠东溪吴处士冯一首"]]},{"n":"宗雷","d":"","s":"《宋书》卷九十三〈隐逸列传·宗炳〉","q":[["诗人识何谢，居士别宗雷。","李端 得山中道友书寄苗钱二员外"],["独有宗雷贱，过君著敝袍。","李端 题郑少府林园"]]}],"490":[{"n":"绿杨两家春","d":"","s":"《南史》卷四十八《陆慧晓传》","q":[["明月好同三径夜，绿杨宜作两家春。","白居易 欲与元八卜邻先有是赠"]]},{"n":"张南周北","d":"","s":"《南史》卷三十九〈刘勉列传·（刘悛弟）刘绘〉","q":[]},{"n":"张掾","d":"","s":"《南齐书》卷四十八《孔稚圭传》","q":[["何言张掾傲，每重德璋亲。","卢纶 过司空曙村居"]]}],"491":[{"n":"开三径","d":"三径：指家园，或喻归隐。唐孟浩然《秦中感秋寄远上人》：“一丘常欲卧，三径苦无资。”","s":"《昭明文选》卷四十五〈对问设论辞序上·辞·归去来〉","q":[["入门堪笑复堪怜，三径苔荒一钓船。","伍唐圭 寒食日献郡守"],["关山云尽九秋月，门柳叶凋三径霜。","刘沧 秋日夜怀"]]},{"n":"卜邻羊仲求仲","d":"","s":"《昭明文选》卷三十〈诗己·杂诗下·田南树园激流植援〉","q":[]},{"n":"蒋径","d":"","s":"《太平御览》卷四百九〈人事部五十·交友四〉2～","q":[]}],"492":[{"n":"筑中置铅","d":"","s":"《史记》卷八十六〈刺客列传·荆轲〉","q":[["燕南壮士吴门豪，筑中置铅鱼隐刀。","李白 结袜子"]]},{"n":"燕市悲歌","d":"冲冠：喻指愤怒。唐卢照邻《咏史四首》之四：“直发上冲冠，壮气横三气。”","s":"《史记》卷八十六〈刺客列传·荆轲〉","q":[["高唱荆卿歌，乱击相如缶。","元稹 说剑"],["燕市悲歌又送君，目随征雁过寒云。","李涉 送魏简能东游二首之二"]]},{"n":"渐离矐","d":"","s":"《史记》卷八十六《刺客列传》","q":[["斯须到绝顶，似愈渐离矐。","皮日休 初夏游楞伽精舍"]]}],"493":[{"n":"陵母伏剑","d":"","s":"《汉书》卷四十〈张陈王周传·王陵〉","q":[["陵母伏剑，轲亲断机。","李瀚 蒙求"]]},{"n":"三尺水","d":"王陵戆：喻人耿直不阿。唐许浑《维舟秦淮过温州李给事宅》：“代有王陵戆，时无勒尚谗。”","s":"《史记》卷八〈高祖本纪〉","q":[["直似王陵戆，非如宁武愚。","张九龄 豋荆州城楼"],["王陵固似戆，郭最遂非雄。","李端 长安感事呈卢纶"]]},{"n":"王陵","d":"","s":"《汉书》卷四十〈张陈王周传·王陵〉","q":[]}],"494":[{"n":"上蔡门","d":"黄犬悲：指为官受害而追悔莫及。宋苏轼《雨中过舒教授》：“飞鸢悔前笑，黄犬悲晚悟。”","s":"《史记》卷八十七〈李斯列传〉","q":[["赤龙已赴东方暗，黄犬徒怀上蔡悲。","储嗣宗 长安怀古"],["青蝇岂独悲虞氏，黄犬应闻笑李斯。","李德裕 到恶溪夜泊芦岛"]]},{"n":"指鹿为马","d":"指鹿：喻指诬陷或颠倒是非。唐李绅《趋翰苑遭诬构四十六韵》：“诳天犹指鹿，依社尚凭狐。”","s":"《史记》卷六〈秦始皇本纪〉","q":[["汉祖竟为龙，赵高徒指鹿。","于濆 秦原览古"],["上下一相蒙，马鹿遂颠倒。","古之奇 秦人谣"]]},{"n":"赵高谋李斯","d":"","s":"《史记》卷八十七〈李斯列传〉","q":[["弘恭陷萧望，赵高谋李斯。","白居易 读史五首"]]}],"495":[{"n":"赤兔","d":"","s":"《后汉书》卷七十五《吕布传》","q":[["吕将军，骑赤兔。","李贺 吕将军歌"],["赤兔无人用，当须吕布骑。","李贺 马诗二十三首之八"]]},{"n":"然脐","d":"","s":"《后汉书》卷七十二《董卓传》","q":[["岂思鳞作簟，仍计腹为灯。","李商隐 洞庭鱼"],["屡断呼韩颈，曾然董卓脐。","李贺 送秦光禄北征"]]},{"n":"吕布遭围下邳","d":"","s":"《后汉书》卷七十五〈刘焉袁术吕布列传·吕布〉","q":[]}],"496":[{"n":"杨朱泣","d":"亡羊路：喻指世事复杂。唐姚系《京西遇旧识兼送往陇西》：“相逢与相失，共是亡羊路。”；杨朱泣：指因误入歧途而感伤。唐杜甫《早发射洪县南途中作》：“茫然阮籍途，更洒杨朱泣。”","s":"《淮南子》卷十七〈说林训〉","q":[["相逢与相失，共是亡羊路。","姚系 京西遇旧识兼送往陇西"],["来岁公田多种黍，莫教黄菊笑杨朱。","刘商 重阳日寄上饶李明府"]]},{"n":"杨朱","d":"","s":"《孟子》卷十三《尽心上》","q":[["终当赋归去，那更学杨朱。","李绅 趋翰苑遭诬构四十六韵"]]},{"n":"杨朱哭","d":"","s":"《太平御览》卷四八七","q":[["杨朱来此哭，桑扈返于真。","王维 过沈居士山居哭之"]]}],"497":[{"n":"少皞","d":"","s":"《礼记注疏》卷十六〈月令〉","q":[["少皞开宫行帝业，无刃金风剪红叶。","李咸用 送人"],["羲和鞭白日，少昊行清秋。","杜甫 同诸公登慈恩寺塔"]]},{"n":"少昊墟","d":"","s":"《元和郡县图志》卷十〈河南道·衮州〉","q":[["遗墟当少昊，悬象逼奎娄。","高适 东平旅游奉赠薛太守二十四韵"],["前临少昊墟，始觉东蒙长。","高适 鲁郡途中遇徐十八录事"]]},{"n":"少皞墟","d":"","s":"《春秋左传正义》卷四十八〈昭公·传十七年〉","q":[]}],"498":[{"n":"楚倚相","d":"","s":"《春秋左传·宣公二年》","q":[["天生良史笔，浪迹擅文藻。","姚发 送萧颖士赴东府得草字"],["记事还同楚倚相，传经远自汉扶阳。","权德舆 送韦行军员外赴河阳"]]},{"n":"董狐笔","d":"董狐直笔：咏史官秉笔直书，刚正不阿。宋黄庭坚《王彦祖惠其祖黄州制草书其后》：“董狐常直笔，汲黯少居中。”","s":"《春秋左传正义》卷二十一〈宣公·传二年〉","q":[["惟我之有颂兮，奚斯跃而董狐蹶。","来鹄 圣政纪颂"],["祸首燧人氏，厉阶董狐笔。","杜甫 写怀二首之二"]]},{"n":"南史笔","d":"","s":"《春秋左传正义》卷三十六〈襄公·传二十五年〉","q":[]}],"499":[{"n":"归皓","d":"","s":"《晋书》卷四十二《王浚传》","q":[["与浑虽不协，归皓实为雄。","张九龄 奉和圣制过王浚墓"]]},{"n":"黄旗","d":"","s":"《汉书》卷四十八《吴书·孙皓传》","q":[["空糊赪坏真何益，欲举黄旗竟未成。","李商隐 览古"]]},{"n":"武昌鱼","d":"","s":"《三国志》卷六十一〈吴书·陆凯传〉","q":[["得餐武昌鱼，不顾浔阳田。","独孤及 下弋阳江舟中代书寄裴侍御"],["鱼听建业歌声过，水看瞿塘雪影来。","罗隐 游江夏口"]]}],"500":[{"n":"论巧拙","d":"","s":"《昭明文选》卷十六晋·潘安仁（岳）《闲居赋·序》","q":[["休指宦游论巧拙，只将愚直祷神祇。","杜牧 题桐叶"]]},{"n":"马安四至","d":"","s":"《史记》卷一二○《汲郑列传》","q":[["马安四至，应璩三入。","李瀚 蒙求"],["应笑马安虚巧宦，四回迁转始为卿。","罗隐 裴庶子除太仆卿因贺"]]},{"n":"四至九卿","d":"","s":"《汉书》卷五十〈张冯汲郑列传·汲黯〉","q":[]}],"501":[{"n":"市骏","d":"","s":"《战国策》卷二十九〈燕策一·燕昭王收破燕后即位〉","q":[["骏骨黄金买，英髦绛帐延。","元稹 献荥阳公诗五十韵（并启）"],["燕昭不是空怜马，支遁何妨亦爱鹰。","司空图 退栖"]]},{"n":"黄金台","d":"黄金台：指招贤之所。唐李白《南奔书怀》：“侍笔黄金台，传觞青玉案。”","s":"《战国策》卷二十九〈燕策一·燕昭王收破燕后即位〉","q":[["此去黄金台上客，相思应羡雁南归。","刘沧 送友人罢举赴蓟门从事"],["若使解言天下事，燕台今筑几千金。","司空图 喜山鹊初归三首之二"]]},{"n":"千里马","d":"","s":"《战国策》卷二十九〈燕策一·燕昭王收破燕后即位〉","q":[["常说使君千里马，至今龙迹尚堪攀。","文鉴 题马迹山"]]}],"502":[{"n":"扁鹊","d":"","s":"《史记》卷一○五《扁鹊列传》","q":[["韩康灵药不复求，扁鹊医方曾莫睹。","李嘉祜 夜闻江南人家赛神因题即事"]]},{"n":"扁鹊起虢","d":"","s":"《史记》卷一百五〈扁鹊仓公列传·扁鹊〉","q":[["董奉活燮，扁鹊起虢。","李瀚 蒙求"]]},{"n":"见垣一壁","d":"","s":"《史记》卷一百五〈扁鹊仓公列传·扁鹊〉","q":[]}],"503":[{"n":"五羖","d":"五羖赎：咏求贤。唐李商隐《自桂林奉使江陵途中感怀寄献尚书》：“长怀五羖赎，终著九州箴。”","s":"《孟子注疏》卷九下〈万章章句上〉","q":[["长怀五羖赎，终著九州箴。","李商隐 自桂林奉使江陵途中感怀寄献尚书"],["陶朱与五羖，名播天壤间。","李白 南都行"]]},{"n":"薰获","d":"","s":"《春秋左传·僖公四年》","q":[["今我及数子，固无莸与薰。","韩愈 醉赠张秘书"],["因疾鼻又塞，渐能等薰莸。","韩韩 赴江陵途中寄赠王二十补阙李十一拾遗李二十六员外翰林三学士"]]},{"n":"一国三公","d":"","s":"《春秋左传正义》卷十二〈僖公·传五年〉","q":[["一国实三公，万人欲为鱼。","杜甫 草堂"]]}],"504":[{"n":"随何","d":"","s":"《史记》卷九十一〈黥布列传〉","q":[["天下尚未宁，健儿胜腐儒。","杜甫 草堂"]]},{"n":"随何辩","d":"","s":"《汉书》卷三十四〈韩彭英卢吴列传·黥布〉","q":[]},{"n":"折随何","d":"","s":"《汉书》卷三十四〈韩彭英卢吴列传·黥布〉","q":[]}],"505":[{"n":"周瑜破曹","d":"","s":"《三国志》卷四十七〈吴书·吴主权〉","q":[["赤壁争雄如梦里，且须歌舞宽离忧。","李白 江夏赠韦南陵冰"],["烈火张天照云海，周瑜于此破曹公。","李白 赤壁歌送别"]]},{"n":"赤壁楼船","d":"","s":"《三国志》卷四十七〈吴书·吴主权传〉","q":[]},{"n":"周醪","d":"","s":"《三国志》卷五十四《吴书·周瑜传》","q":[["周醪忽同醉，牙弦乃共挥。","许敬宗 冬日宴于庶子宅各赋一字得归"]]}],"506":[{"n":"登车泣贵嫔","d":"","s":"《晋书》卷七《成帝纪》","q":[["夺马悲公主，登车泣贵嫔。","杜甫 伤春五首之四"]]},{"n":"杜后生齿","d":"","s":"《晋书》卷三十二《后妃传下·成恭杜皇后传》","q":[["杜后生齿，灵王出髭。","李瀚 蒙求"]]},{"n":"庾舅","d":"","s":"《晋书》卷七十三《庾亮传》","q":[["庾舅已能窥帝室，王都还是预人家。","罗隐 建康"]]}],"507":[{"n":"白龙鱼服","d":"鱼服困：指落难，或运气不佳而遇到灾祸。清赵翼《淮阴钓台》：“与哙伍怜鱼服困，假齐王伏狗烹灾。”","s":"《艺文类聚》卷九十六〈鳞介部上·龙〉","q":[]},{"n":"渔人犯白龙","d":"","s":"汉·刘向《说苑》卷九《正谏》","q":[["白龙改常服，偶被豫且制。","李白 枯鱼过河泣"],["且贪原兽轻黄屋，宁畏渔人犯白龙。","钱起 汉武出猎"]]},{"n":"刳肠","d":"","s":"《庄子集释》卷九上〈杂篇·外物〉","q":[["有志酬毛宝，无心畏豫且。","李群玉 龟"],["龟灵未免刳肠患，马失应无折足忧。","白居易 放言五首"]]}],"508":[{"n":"辽东豕","d":"","s":"《东观汉记》卷十五〈朱浮传〉","q":[["辽东惭白豕，楚客羞山鸡。","李白 赠范金卿二首之一"]]},{"n":"渔阳突骑","d":"","s":"《后汉书》卷十八《吴汉传》","q":[["渔阳突骑犹精锐，赫赫雍王都节制。","杜甫 渔阳"]]},{"n":"中风走","d":"","s":"《后汉书》卷三十三〈朱冯虞郑周列传·朱浮〉","q":[["穷迫挫曩怀，常如中风走。","杜甫 上水遣怀"]]}],"509":[{"n":"一鸣惊人","d":"冲天翼：喻指贤士待时而动。唐贯休《遇叶进土》：“自愧龙钟人，见此冲天翼、”","s":"《韩非子》卷七〈喻老〉","q":[["遇此枝叶覆，夙举冀冲天。","李岑 东峰亭各赋一物得栖烟鸟"],["子既屈一鸣，余固宜三刖。","杜牧 池州送孟迟先辈"]]},{"n":"留髡送客","d":"","s":"《史记》卷一百二十六〈滑稽列传〉","q":[]},{"n":"驺忌鼓琴","d":"","s":"《史记》卷四十六〈田敬仲完世家〉","q":[["远师驺忌鼓鸣琴，去和南风惬舜心。","柳宗元 李西川荐琴石"]]}],"510":[{"n":"捷报孙歆头","d":"","s":"《晋书》卷三十四《杜预传》","q":[["军令未闻诛马谡，捷书惟是报孙歆。","李商隐 隋师东"]]},{"n":"龙骧茔","d":"","s":"《晋书》卷四十二《王浚传》","q":[["虚无马融笛，怅望龙骧茔。","杜甫 八哀诗并序赠左仆射郑国公严公武"],["墓待龙骧诏，台迎獬豸威。","杜甫 送卢十四弟侍御护韦尚书（之晋）灵榇归上都二十韵"]]},{"n":"龙骧下蜀","d":"","s":"《晋书》卷四十二《王浚传》","q":[["我见楼船壮心目，颇似龙骧下三蜀。","李白 司马将军歌以代陇上健儿陈安"],["君看帝子浮江日，何似龙骧出峡来。","李白 永王东巡歌十一首之八"]]}],"511":[{"n":"北府牢之勇","d":"","s":"《晋书》卷八十四〈刘牢之列传〉","q":[]},{"n":"酷似","d":"","s":"《晋书》卷八十五《何无忌传》","q":[["辕门拜首儒衣弊，貌似牢之岂不怜。","刘长卿 送秦侍御外甥张篆之福州谒鲍大夫秦侍御与大夫有旧"],["徐庶高交友，刘牢出外甥。","杜甫 奉送二十三舅录事（崔伟）之摄郴州"]]},{"n":"外甥似舅","d":"","s":"《晋书》卷八十五〈何无忌列传〉","q":[]}],"512":[{"n":"旦暮身","d":"","s":"《史记》卷三十九《晋世家》","q":[["七十三翁旦暮身，誓开险路作通津。","白居易 开龙门八节石滩诗二首之二"]]},{"n":"骊姬","d":"","s":"《国语》卷七〈晋语一·史苏论献公伐骊戎胜而不吉〉","q":[["侧闻骊姬事，申生不自保。暂山商山云，朅来趋洒扫。","李华 咏史十一首之五"]]},{"n":"小臣毙","d":"","s":"《春秋左传正义》卷十二〈僖公·传四年〉","q":[["终悲洛阳狱，事近小臣敝。","杜甫 八哀诗赠秘书监江夏李公邕"]]}],"513":[{"n":"月旦评","d":"许氏评：指对人或作品进行评价。唐李商隐《送千牛李将军赴阙五十韵》：“幸藉梁园赋，叨蒙许氏评。”","s":"《后汉书》卷六十八〈郭符许列传·许劭〉","q":[["幸藉梁园赋，叨蒙许氏评。","李商隐 送千牛李将军赴阙五十韵"],["笑言成月旦，风韵挹天真。","权德舆 哭刘四尚书"]]},{"n":"平舆","d":"","s":"《后汉书》卷六十八《许劭传》","q":[["伯仲尽时贤，平舆与颍川。","权德舆 奉和馆张阁老以许陈二阁长爱弟俱为尚书郎伯仲同时列在南北省会于左掖因而有咏"],["月旦继平舆，风流仕石渠。","权德舆 送许著作分司东都"]]},{"n":"太邱道","d":"","s":"《后汉书》卷六十八〈郭符许列传·许劭〉","q":[["终惭太丘道，不为小生私。","李端 下第上薛侍郎"]]}],"514":[{"n":"张许","d":"","s":"《旧唐书》卷一百八十七下〈忠义列传下·许远〉","q":[]},{"n":"记书若张巡","d":"","s":"《新唐书》卷一百九十二〈忠义列传中·张巡〉","q":[]},{"n":"嚼齿","d":"","s":"《旧唐书》卷一百八十七下〈忠义列传下·张巡〉","q":[]}],"515":[{"n":"毛延寿","d":"","s":"《西京杂记》卷二","q":[["丹青能令丑者妍，无盐翻在深宫里。自古妒娥眉，胡沙埋皓齿。","李白 于阗采花"],["相如死后无词客，延寿亡来绝画工。","杜牧 奉陵宫人"]]},{"n":"马上琵琶","d":"","s":"《昭明文选》卷二十七〈诗戊·乐府上·王明君词并序〉","q":[]},{"n":"昭君出塞","d":"","s":"《汉书》卷九〈元帝纪〉","q":[["去国汉妃还似玉，亡家石氏岂无金。","罗邺 落第书怀寄友人"]]}],"516":[{"n":"贺循儒宗","d":"","s":"《晋书》卷六十八〈贺循列传〉","q":[["贺循儒宗，孙绰才冠。","李瀚 蒙求"]]},{"n":"亲临贺循","d":"","s":"《晋书》卷六十八〈贺循列传〉","q":[["宠赠追胡广，亲临比贺循。","苏颋 赠司徒豆卢府君挽词"]]},{"n":"舟中琴","d":"","s":"《世说新语》下卷上《任诞》","q":[["为乐凡几许，听取舟中琴。","骆宾王 称心寺"]]}],"517":[{"n":"萧朱","d":"","s":"《汉书》卷七十八〈萧望之列传·萧育〉","q":[["张陈竟火灭，萧朱亦星离。","李白 古风之五十九"],["名声逼扬马，交分过萧朱。","白居易 东南行一百韵寄通州元九待御澧州李十一舍人果州崔二十二使君"]]},{"n":"萧车","d":"","s":"《汉书》卷七十八《萧望之传》附《萧育传》","q":[["萧车安不定，蜀使下何之。","杜甫 夔府书怀四十韵"]]},{"n":"萧次君去官频","d":"","s":"《汉书》卷七十八《萧望之传》附《萧育传》","q":[["杜陵萧次君，迁少去官频。","杜牧 自贻"]]}],"518":[{"n":"白马公孙","d":"","s":"《史记》卷七十六《平原君列传》","q":[["白马公孙何处去，青牛老人更不还。","岑参 函谷关歌送刘评事使关西"],["白马高谭去，青牛真气来。","王勃 散关晨度"]]},{"n":"邯郸步","d":"邯郸步：指学习方法不当，不仅未学到新技能，反而失去了原有技能。宋欧阳修《镇阳读书》：“有类邯郸步，两失皆茫茫。”","s":"《庄子集释》卷六下〈外篇·秋水〉","q":[["邯郸笑匍匐，燕蒯受揶揄。","元稹 酬乐天东南行诗一百韵"],["寿陵失本步，笑杀邯郸人。","李白 古风之三十五"]]},{"n":"专云壑","d":"","s":"《庄子集释》卷六下〈外篇·秋水〉","q":[]}],"519":[{"n":"生申","d":"","s":"《毛诗正义》卷十八之三〈大雅·荡之什·烝民〉","q":[]},{"n":"申甫","d":"","s":"《诗经·大雅·嵩高》","q":[["命代生申甫，承家翊禹汤。","杨巨源 上刘侍中"],["周王致理称申甫，今日贤臣见明主。","权德舆 奉和张仆射朝天行"]]},{"n":"岳降","d":"","s":"《毛诗正义》卷十八之三〈大雅·荡之什·崧高〉","q":[["虽遇河清圣，惭非岳降贤。","韩偓 感事三十四韵"]]}],"520":[{"n":"楚江萍","d":"楚昭萍：喻吉祥之物，或喻珍贵果品。宋刘筠《樱桃》：“楚昭萍已破，韩嫣弹争投。”","s":"《孔子家语》卷二〈致思〉","q":[["荣华贵少壮，岂食楚江萍。","杜甫 奉酬薛十二丈判官见赠"],["暖老须燕玉，充饥忆楚萍。","杜甫 独坐二首之一"]]},{"n":"渐台水死","d":"","s":"《列女传》卷四〈贞顺传·楚昭贞姜〉","q":[["水至亦不去，熊来尚可当。","李白 秦女卷衣"],["千年名姓香氛氲，渐台水死何伤闻。","鲍溶 辞辇行"]]},{"n":"坠履","d":"","s":"《新书》卷七《谕诚》","q":[["他日陶甄寻坠履，沧洲何处觅渔翁。","韩偓 余自刑部员外郎为时权所挤值盘石出镇藩屏朝选宾佐以余充职掌记郁郁不乐因成长句寄所知"]]}],"521":[{"n":"周妻何肉","d":"何肉周妻：指修行中有所难舍。明袁宏道《赠虞德园兄弟》：“台宗贤教谁能识，何肉周妻到底疑。”","s":"《南齐书》卷四十一〈周颙列传〉","q":[]},{"n":"何胤三遗红","d":"","s":"《南史》卷三十《何尚之传》附《何胤传》","q":[["严光一唾垂緌紫，何胤三遗大带红。","韩偓 此翁"]]},{"n":"含瓦砾","d":"","s":"《南史》卷三十《何尚之传》附《何胤传》","q":[["如含瓦砾竟何功，痴黠相兼似得中。","韩偓 味道"]]}],"522":[{"n":"何充爱禅","d":"","s":"《晋书》卷七十七《何充传》","q":[["仲虺专为诰，何充雅爱禅。","贯休 和韦相公见示閒卧"]]},{"n":"讥何","d":"","s":"《晋书》卷七十七〈何充列传〉","q":[]},{"n":"刘惔倾酿","d":"","s":"《世说新语》中卷下《赏誉》","q":[["刘惔倾酿，孝伯痛饮。","李瀚 蒙求"]]}],"523":[{"n":"仇梅","d":"","s":"《后汉书》卷七十六《循吏传·仇览传》","q":[["不是仇梅至，何人问百忧。","耿湋 下邽客舍喜叔孙主簿郑少府见过"]]},{"n":"梅市","d":"","s":"《汉书》卷六十七《梅福传》","q":[["近水方同梅市隐，曝衣多笑阮家贫。","司空曙 闲园即事寄陈公"],["梅市门何处，兰亭水向流。","郎士元 送李遂之越"]]},{"n":"神仙中人","d":"","s":"《汉书》卷六十七〈杨胡朱梅云传·梅福〉","q":[["棘寺初衔命，梅仙已误身。","刘长卿 西庭夜燕喜评事兄拜会"],["李膺门客为闲客，梅福官衔改旧衔。","周朴 喜贺拔先辈衡阳除正字"]]}],"524":[{"n":"郎潜","d":"白发郎潜：指年老而怀才不遇。宋苏轼《次天字韵答岑岩起》：“莫叹郎潜生白发，圣朝求旧鄙鸢肩。”","s":"《昭明文选》卷十五〈赋辛·志中·思玄赋〉","q":[["遭逢好交日，黜落至公时。","李昌符 下第后蒙侍郎示意指于新先辈宣恩感谢"],["汉家尚壮今则老，发短心长知奈何。","李端 赠康洽"]]},{"n":"梁王驷马","d":"","s":"《艺文类聚》卷五十六","q":[["都尉仙凫远，梁王驷马来。","李峤 诗"],["叶令双凫至，梁王驷马来。","李元操 和从叔禄愔元日早朝"]]},{"n":"文景","d":"","s":"《汉书》卷五〈景帝纪〉","q":[]}],"525":[{"n":"素车白马","d":"灵胥：指河神。来陆游《乙丑夏秋之交小舟早夜往来湖中戏成绝句》：“千年未息灵胥怒，卷地潮声到枕边。”","s":"《吴越春秋》卷五〈夫差内传·十三年〉","q":[["行叹鸱夷没，遽惜湛卢飞。","骆宾王 夕次旧吴"],["但褫千人魄，那知伍相心。","姚合 杭州观潮"]]},{"n":"藏弓","d":"","s":"《史记》卷四十一〈越王句践世家〉","q":[["藏弓身已退，焚稿事难闻。","刘长卿 秋日夏口涉汉阳献李相公"],["弓藏狡兔尽，慷慨念心伤。","王圭 咏淮阴侯"]]},{"n":"种蠡","d":"","s":"《史记》卷四十一〈越王句践世家〉","q":[]}],"526":[{"n":"汉主思李牧","d":"","s":"《史记》卷一○二《冯唐列传》","q":[["汉主岂劳思李牧，赵王犹是用廉颇。","雍陶 罢还边将"]]},{"n":"李牧","d":"","s":"《史记》卷八十一《廉颇蔺相如列传》附《李牧列传》","q":[["李牧今不在，边人饲豺虎。","李白 古风之十四"],["李牧制儋蓝，遗风岂寂寥。","高适 睢阳酬别畅大判官"]]},{"n":"廉李","d":"","s":"《史记》卷八十一〈廉颇蔺相如列传〉","q":[]}],"527":[{"n":"汉昭登位","d":"","s":"《汉书》卷七《昭帝纪》","q":[["汉昭登位少，周代卜年长。","姚合 敬宗皇帝挽词三首"]]},{"n":"太液黄鹄","d":"","s":"旧题汉·葛洪《西京杂记》","q":[["太液始同黄鹤下，仙乡已驾白云归。","姚鹄 送贺知章入道"],["赓歌太液翻黄鹄，从猎陈仓获碧鸡。","李商隐 寄令狐学士"]]},{"n":"燕客书诈","d":"","s":"《汉书》卷六十八《霍光传》","q":[["燕客书方诈，尧门信未孚，","李绅 趋翰苑遭诬构四十六韵"]]}],"528":[{"n":"珠履三千","d":"珠履：喻幕僚生活奢华。唐刘言史《苦妇词》：“兰裙间珠履，食五处花筵。”；珠履客：喻指幕僚。唐杜牧《送王侍御赴夏日座主幕》：“君为珠履三千客，我是青衿七十徒。”","s":"《史记》卷七十八〈春申君列传〉","q":[["宾客无多少，出入皆珠履。","储光羲 同王十三维偶然作十首"],["好客交珠履，华筵舞玉颜。","刘禹锡 奉和裴令公新成绿野堂即书"]]},{"n":"春申刎首","d":"","s":"《史记》卷七十八《春申君列传》","q":[["春申一何愚，刎首为李园。","李白 送薛九被谗去鲁"]]},{"n":"三千客","d":"三千客：指贵客盈门。宋范成大《次韵甄云卿晚登浮丘亭》：“宾筵旧压三千客，燕榭新高十二城。”","s":"《史记》卷七十七〈魏公子列传〉","q":[["食恩三千士，一旦为豺狼。","孟郊 汴州离乱后忆韩愈李翱"],["若无三千客，谁道信陵君。","李白 博平郑太守自庐山千里相寻入江夏北市门见访却之武陵立马赠别"]]}],"529":[{"n":"西州路","d":"","s":"《晋书》卷七十九《谢安传》","q":[["季子生前别，羊昙醉后悲。","司空曙 哭苗员外呈张参军"],["满筵旧府笙歌在，独有羊昙最泪流。","杨巨源 酬卢员外"]]},{"n":"围棋赌墅","d":"赌墅：喻临危不惧的大将风度，或指舅甥关系。唐孙元晏《晋·谢公赌墅》：“自从乞与羊昙后，赌墅功成更有谁？”","s":"《晋书》卷七十九《谢安传》","q":[["曾经庾亮三秋月，下尽羊昙两路棋。","李郢 上裴晋公"],["谢公尝乞墅，宁氏终相宅。","权德舆 奉和崔评事寄外甥刘同"]]},{"n":"谢傅舅甥贤","d":"","s":"《晋书》卷七十九《谢安传》","q":[["东武杨公姻娅重，西州谢傅舅甥贤。","武元衡 送李秀才赴滑州诣大夫舅"]]}],"530":[{"n":"崇侯","d":"","s":"《史记》卷三《殷本纪》","q":[["崇侯入辅严陵退，堪忆啼猿万仞峰。","徐夤 西寨寓居之二"]]},{"n":"妲己","d":"","s":"《史记》卷三〈殷本纪〉","q":[["妲己灭纣，褒女惑周。","李白 雪谗诗赠友人"]]},{"n":"商受斮涉","d":"","s":"《尚书·周书·秦誓下》","q":[["南风掷孕，商受斮涉。","李瀚 蒙求"]]}],"531":[{"n":"山西将","d":"","s":"《汉书》卷六十九〈赵充国辛庆忌列传〉","q":[]},{"n":"世将道家禁","d":"","s":"《后汉书》卷十九〈耿弇列传·耿弇〉","q":[]},{"n":"王剪在频阳","d":"","s":"《史记》卷七十三〈白起王剪列传·王剪〉","q":[["知爱鲁连归海上，肯令王剪在频阳。","杨巨源 赠张将军"]]}],"532":[{"n":"借寇恂","d":"借寇恂：称颂官吏政绩卓著，受百姓拥戴。唐杜甫《奉寄章十侍御》：“湘西不得归关羽，河内犹宜借寇恂。”","s":"《后汉书》卷十六〈邓寇列传·寇恂〉","q":[["内史称张敞，苍生借寇恂。","元稹 代曲江老人百韵"],["杭人遮道路，垂泣浙江前。","姚合 送裴大夫赴亳州"]]},{"n":"寇邓勋","d":"","s":"《后汉书》卷二十二《中兴二十八将传论》","q":[["吾慕寇邓勋，济时信良哉。","杜甫 述古三首之三"]]},{"n":"萧寇","d":"","s":"《后汉书》卷十六〈邓寇列传·寇恂〉","q":[]}],"533":[{"n":"彭黥菹醢","d":"","s":"《昭明文选》卷四十一汉·李少卿（陵）《答苏武书》","q":[["乍如彭与黥，呼冤受菹醢。","韩愈 嘲鼾睡二首之一"]]},{"n":"黥布开关","d":"","s":"《史记》卷九十一《黥布列传》","q":[["黥布开关，张良烧栈。","李瀚 蒙求"]]},{"n":"黥阵","d":"","s":"《史记》卷九十一《黥布列传》","q":[["秦台破心胆，黥阵惊毛发。","杜牧 池州送孟迟先辈"],["鲸阵人人慑，秋星历历分。","杜牧 赠张祜"]]}],"534":[{"n":"灵光赋","d":"","s":"《谢承后汉书》卷五〈文苑传·王逸〉","q":[]},{"n":"颂灵光","d":"","s":"《后汉书》卷八十上《文苑传·王逸传》","q":[["正平赋鹦鹉，文考颂灵光。二子古不吊，夫君今何伤。","权德舆 从事淮南府过亡友杨校书旧厅感念愀然"]]},{"n":"延寿","d":"","s":"《后汉书》卷八十上《文苑传·王逸传》附《王延寿传》","q":[["诗名比元长，赋体凌延寿。","皎然 答裴集阳伯明二贤各垂赠二十韵今以一章用酬两作"]]}],"535":[{"n":"绿珠楼","d":"","s":"《晋书》卷三十三〈石苞列传·（子）石乔·（子）石崇〉","q":[["四者俱不闻，空传堕楼客。","于濆 金谷感怀"],["亚水依岩半倾侧，笼云隐雾多愁绝。绿珠语尽身欲投，汉武眼穿神渐灭。","元稹 山枇杷"]]},{"n":"明珠买妾","d":"","s":"《太平御览》卷一百八十九〈居处部十七·井〉","q":[]},{"n":"一斛明珠换绿珠","d":"","s":"《苌楚斋随笔·续笔》卷九〈杨贵妃等生广西〉","q":[]}],"536":[{"n":"灌夫","d":"","s":"《史记》卷一○七《魏其武安侯列传》","q":[["意气由来排灌夫，专权判不容萧相。","卢照邻 长安古意"],["颍川豪横客，咸阳轻薄儿。","郑愔 少年行"]]},{"n":"一钱不直","d":"一钱不直：喻对人或事物的蔑视。宋黄庭坚《次韵任道食荔支有感三首》之一：“一钱不直程卫尉，万事称好司马公。”；灌夫骂：喻为人刚直，或指漫骂同座之人。清王以慜《复答冬丈聊广其意》：“有耳休矜巢父洗，有口休从灌夫骂。”","s":"《汉书》卷五十二〈窦田灌韩传·灌夫〉","q":[]},{"n":"颍川使酒","d":"","s":"《史记》卷一○七《魏其武安侯列传》","q":[["誓令疏勒出飞泉，不似颍川空使酒。","王维 老将行"]]}],"537":[{"n":"侠客专诸","d":"","s":"《史记》卷八十六〈刺客列传·专诸〉","q":[]},{"n":"鱼隐刀","d":"","s":"《史记》卷八十六〈刺客列传·专诸〉","q":[["燕南壮士吴门豪，筑中置铅鱼隐刀。","李白 结袜子"]]},{"n":"专诸","d":"","s":"《史记》卷八十六〈刺客列传·专诸〉","q":[["且将换酒与君醉，醉归托宿吴专诸。","李白 醉后赠从甥高镇"]]}],"538":[{"n":"建安诸子","d":"","s":"《昭明文选》卷五十二〈论二·典论论文〉","q":[]},{"n":"徐陈","d":"","s":"《三国志》卷二十一〈魏书·王粲〉","q":[["清秋忽高兴，震藻若有神。曜曜趋宫廷，洸洸迈徐陈。","储光羲 敬酬陈掾亲家翁秋夜有赠"],["徐陈尝并作，枚马亦同时。夫君迈前侣，观国骋奇姿。","张说 酬崔光禄冬日述怀赠答"]]},{"n":"应徐","d":"","s":"《三国志》卷二十一《魏书·王粲传》","q":[["菲才叨侍从，连藻愧应徐。","张说 扈从幸韦嗣立山庄应制"],["岂惟高卫霍，曾是接应徐。","杜甫 秋日荆南送石首薛明府辞满告别奉寄薛尚书颂德叙怀斐然之作三十韵"]]}],"539":[{"n":"恭显","d":"","s":"《汉书》卷三十六〈楚元王列传·刘向〉","q":[["恭显诚甘罪，韦平亦恃权。","韩偓 感事三十四韵"]]},{"n":"弘恭陷萧望","d":"","s":"《汉书》卷七十八《萧望之传》","q":[["弘恭陷萧望，赵高谋李斯。阴德既必报，阴祸岂虚施。","白居易 读史五首之四"]]},{"n":"刘讼石中书","d":"","s":"《汉书》卷三十六《楚元王传》附《刘向传》","q":[["可怜刘校尉，曾讼石中书。","杜牧 李给事中敏二首"]]}],"540":[{"n":"人如玉","d":"","s":"《毛诗正义》卷十一之一〈小雅·鸿雁之什·白驹〉","q":[["旧交封宿草，衰鬓重生刍。","李绅 趋翰苑遭诬搆四十六韵"],["停觞一摇笔，聊寄生刍吟。","李群玉 将离澧浦置酒野屿奉怀沈正字昆弟三人联登高第"]]},{"n":"黄宪万顷","d":"","s":"《后汉书》卷五十三《黄宪传》","q":[["王允千里，黄宪万顷。","李瀚 蒙求"]]},{"n":"林宗重黄生","d":"","s":"《后汉书》卷五十三《黄宪传》","q":[["知人想林宗，直道惭史鱼。","高适 苦雨寄房四昆季"],["宣父敬项橐，林宗重黄生。","魏万 金陵酬李翰林谪仙子"]]}],"541":[{"n":"良乐","d":"","s":"《汉书》卷一○○上《叙传上》","q":[["良乐知骐骥，张雷验镆铘。","贾岛 寄令狐绹相公"]]},{"n":"良造","d":"","s":"《淮南子》卷六《览冥训》","q":[["四十八监选龙媒，时贡天庭付良造。","元稹 阴山道"]]},{"n":"王良","d":"","s":"《春秋左传·哀公二年》","q":[["车无轮扁斲，辔无王良把。虽有万骏来，谁是敢骑者。","元稹 八骏图诗"],["王良若许相抬策，千里追风也不难。","曹唐 病马五首呈郑校书章三吴十五先辈"]]}],"542":[{"n":"伯道无儿","d":"邓家无子：指没有子嗣。唐白居易《老来生计》：“陶令有田唯种黍，邓家无子不留金。”","s":"《晋书》卷九十〈良吏列传·邓攸〉","q":[["往年鬓已同潘岳，垂老年教作邓攸。","元稹 哭子十首"],["有鸟哭杨震，无儿悲邓攸。","元稹 阳城驿"]]},{"n":"紞如五鼓","d":"","s":"《晋书》卷九十〈良吏列传·邓攸〉","q":[["梁国歌来晚，徐方怨不留。","高适 奉酬睢阳李太守"]]},{"n":"饮水","d":"","s":"《晋书》卷九十《良吏传·邓攸传》","q":[["人皆知饮水，公辈不偷金。","杜甫 赠裴南部闻袁判官自来欲有按问"],["折腰非吾事，饮水非吾贫。","韦应物 任洛阳丞请告一首"]]}],"543":[{"n":"建安诸子","d":"","s":"《昭明文选》卷五十二〈论二·典论论文〉","q":[]},{"n":"应刘","d":"","s":"《昭明文选》卷四十二、三国魏·魏文帝（曹丕）《与朝歌令吴质书》","q":[["崔嵬长河北，尚见应刘墓。","孟云卿 邺城怀古"],["还瞻魏太子，宾客减应刘。","杜甫 重题"]]},{"n":"应徐","d":"","s":"《三国志》卷二十一《魏书·王粲传》","q":[["菲才叨侍从，连藻愧应徐。","张说 扈从幸韦嗣立山庄应制"],["岂惟高卫霍，曾是接应徐。","杜甫 秋日荆南送石首薛明府辞满告别奉寄薛尚书颂德叙怀斐然之作三十韵"]]}],"544":[{"n":"锦帆天子","d":"","s":"《开河记》","q":[["锦帆天子狂魂魄，应过扬州看月明。","罗隐 中元夜泊淮口"]]},{"n":"雷塘","d":"","s":"《隋书》卷四《炀帝纪下》","q":[["年年只有晴风便，遥为雷塘送雪花。","李山甫 隋堤柳"],["炀帝雷塘土，迷藏有旧楼。","杜牧 扬州三首之一"]]},{"n":"萧娥","d":"","s":"《隋书》卷三十六〈后妃列传·炀帝萧皇后〉～","q":[]}],"545":[{"n":"诗书元帅","d":"","s":"《春秋左传正义》卷十六〈僖公·传二十七年〉","q":[]},{"n":"郤縠","d":"","s":"《国语》卷十〈晋语四·文公任贤与赵衰举贤〉","q":[["郤縠诗书将，衔恩赴梓州。","姚合 送杨尚书赴东川"],["虽同郤縠举，郤縠不封侯。","李频 送薛能赴镇徐方"]]},{"n":"中军","d":"","s":"《春秋左传正义》卷十六〈僖公·传二十七年〉","q":[["中军待上客，令肃事有恒。","杜甫 陪章留后惠义寺饯嘉州崔都督赴州"]]}],"546":[{"n":"骨清","d":"","s":"晋·干宝《搜神记》卷五","q":[["骨清年少眼如冰，凤羽参差五色层。","杜牧 赠李秀才"]]},{"n":"蒋侯麾","d":"","s":"《搜神记》卷五","q":[]},{"n":"秣陵尉","d":"","s":"《搜神记》卷五","q":[["上书一见平津侯，剑笏斜齐秣陵尉。","韩翃 赠别上无主簿张著"]]}],"547":[{"n":"迟行笑褚渊","d":"","s":"《南齐书》卷二十三《褚渊传》","q":[["溅血惭嵇绍，迟行笑褚渊。","韩偓 感事三十四韵"]]},{"n":"褚渊落水","d":"","s":"《南史》卷十九〈谢灵运列传·谢超宗〉","q":[["王俭坠车，褚渊落水。","李瀚 蒙求"]]},{"n":"人笑褚渊","d":"","s":"《南齐书》卷五十五〈孝义列传·乐颐·（弟）乐预〉","q":[]}],"548":[{"n":"苟富贵","d":"","s":"《史记》卷四十八〈陈涉世家〉","q":[]},{"n":"鸿鹄志","d":"","s":"《史记》卷四十八〈陈涉世家〉","q":[["云鸿别有回翔便，应笑啁啾燕雀卑。","方干 赠赵崇侍御"],["未成鸿鹄姿，遽顿骅骝趾。","权德舆 哭李晦群崔季文二处士"]]},{"n":"鸣狐","d":"","s":"《史记》卷四十八〈陈涉世家〉","q":[]}],"549":[{"n":"怀王迹穷","d":"","s":"《史记》卷八十四《屈原列传》","q":[["碧溪留我武关东，一笑怀王迹自穷。","杜牧 题武关"]]},{"n":"靳尚","d":"","s":"《史记》卷八十四《屈原列传》","q":[["欲慰灵均恨，先烧靳尚祠。","徐凝 浙西李尚书奏毁淫昏庙"]]},{"n":"门阑苏生","d":"","s":"《史记》卷四十《楚世家》","q":[["门阑苏生在，勇锐白起强。","杜甫 入衡州"]]}],"550":[{"n":"尺布堪逢，斗粟堪舂","d":"","s":"《史记》卷一百一十八〈淮南衡山列传〉","q":[]},{"n":"一斗粟","d":"","s":"《史记》卷一百一十八〈淮南衡山列传〉","q":[["尺布之谣，塞耳不能听。","李白 上留田行"],["汉谣一斗粟，不与淮南舂。","李白 箜篌谣"]]},{"n":"袖金锤","d":"","s":"《史记》卷一百一十八〈淮南衡山列传〉","q":[["猎敲白玉镫，怒袖紫金锤。","杜牧 少年行"]]}],"551":[{"n":"吴下阿蒙","d":"刮目：指另眼看待，用新眼光看人。宋苏舜钦《送李冀州》：“众人刮目看能事，著鞭无为懦生羞。\"；吴阿蒙：指人平庸。清顾汾《长至斋宿四译馆署次江补斋太常壁间韵》之四：“壮怀漫说庾开府，老眼依然吴阿蒙。”","s":"《三国志》卷五十四〈吴书·吕蒙传〉","q":[["众人刮目看能事，著鞭无为儒生羞。","苏舜钦 送李冀州"],["壮怀漫说庾开府，老眼依然吴阿蒙。","顾汾 长至斋宿四译馆署次江补斋太常壁间韵之四"]]},{"n":"吕蒙营","d":"","s":"《三国志》卷五十四《吴书·吕蒙传》","q":[["野旷吕蒙营，江深刘备城。","杜甫 公安县怀古"]]},{"n":"识吕蒙","d":"","s":"《三国志》卷四十七《吴书·吴主传》","q":[["军事留孙楚，行间识吕蒙。","杜甫 投赠哥舒开府二十韵"]]}],"552":[{"n":"云中魏尚","d":"","s":"《史记》卷一百二〈张释之冯唐列传·冯唐〉","q":[["莫嫌旧日云中守，犹堪一战取功勋。","王维 老将行"]]},{"n":"汉主思李牧","d":"","s":"《史记》卷一○二《冯唐列传》","q":[["汉主岂劳思李牧，赵王犹是用廉颇。","雍陶 罢还边将"]]},{"n":"冯唐","d":"冯唐已老：喻指命运不济，或喻年岁已大但仍没有作为。唐杜甫《寄岑嘉州》：“谢眺每篇堪讽诵，冯唐已老听吹嘘。”","s":"《史记》卷一百二〈张释之冯唐列传·冯唐〉","q":[["贡喜音容间，冯招病疾缠。","杜甫 哭韦大夫之晋"],["为郎非白头，作牧授沧洲。","李频 送侯郎中任新定二首"]]}],"553":[{"n":"天年竟夭","d":"龚胜耻事新：喻忠贞不事二主。唐颜真卿《咏陶渊明》：“张良思报韩，龚胜耻事新。”","s":"《汉书》卷七十二《龚胜亡》","q":[["龚胜不屈，孙宝自劾。","李瀚 蒙求"],["楚国一老人，来嗟龚胜亡。","李白 自溧水道哭王炎三首之一"]]},{"n":"两龚","d":"","s":"《法言义疏》卷九〈问神〉","q":[]},{"n":"以手推松曰去","d":"","s":"《汉书》卷七十二〈王贡两龚鲍列传·龚胜、龚舍〉","q":[]}],"554":[{"n":"高山流水","d":"高山流水：指对音乐精通或知心好友。唐牟融《写意二首》之一：“高山流水琴三弄，明月清风酒一樽。”","s":"《吕氏春秋》卷十四《孝行览·本味》","q":[["预弹山水调，终拟从钟期。","上官婉儿 游长宁公主流杯池二十五首"],["潘岳闲居赋，钟期流水琴。","储光羲 同张侍御鼎和京兆萧兵曹华岁晚南园"]]},{"n":"知音","d":"","s":"《昭明文选》卷四十二、三国魏·魏文帝（曹丕）《与朝歌令吴质书》","q":[["知音方见誉，浮宦久相关。","刘威 冬日送友人西归"],["桐上知音日下身，道光谁不仰清尘。","刘威 赠欧阳秀才"]]},{"n":"钟子期","d":"","s":"《吕氏春秋·纪部》卷九〈季秋纪·精通〉","q":[]}],"555":[{"n":"登车揽辔","d":"","s":"《后汉书》卷六十七〈党锢列传·范滂〉","q":[]},{"n":"范功曹","d":"","s":"《后汉书》卷六十七〈党锢列传·范滂〉","q":[["使者应须访廉吏，府中惟有范功曹。","严维 送崔峒使往睦州兼寄薛司户"]]},{"n":"清裁","d":"","s":"《后汉书》卷六十七《党锢传·范滂传》","q":[["十载违清裁，幽怀未一论。","杜牧 夜泊桐庐先寄苏台卢郎中"],["无计披清裁，唯持祝寿觞。","杜牧 春日言怀寄虢州李常侍十韵"]]}],"556":[{"n":"高山流水","d":"高山流水：指对音乐精通或知心好友。唐牟融《写意二首》之一：“高山流水琴三弄，明月清风酒一樽。”","s":"《吕氏春秋》卷十四《孝行览·本味》","q":[["预弹山水调，终拟从钟期。","上官婉儿 游长宁公主流杯池二十五首"],["潘岳闲居赋，钟期流水琴。","储光羲 同张侍御鼎和京兆萧兵曹华岁晚南园"]]},{"n":"成连入海","d":"海上琴：咏音乐。清张问陶《辛未除夕柬景朴斋司马时已请病将归》：“一年花雪互追寻，同鼓成连海上琴。”","s":"《昭明文选》卷十八嵇叔夜（康）《琴赋》","q":[["伯牙海上感沧溟，何似今朝风雨思。","吴融 风雨吟"],["成连入海移人情，岂是本来无嗜欲？","李咸用 水仙操"]]},{"n":"知音","d":"","s":"《昭明文选》卷四十二、三国魏·魏文帝（曹丕）《与朝歌令吴质书》","q":[["知音方见誉，浮宦久相关。","刘威 冬日送友人西归"],["桐上知音日下身，道光谁不仰清尘。","刘威 赠欧阳秀才"]]}],"557":[{"n":"申白","d":"","s":"《汉书》卷三十六〈楚元王列传·楚元王刘交〉","q":[]},{"n":"申公","d":"","s":"《史记》卷一二一《儒林列传·申公传》","q":[["肯谢申公辈，治诗事汉文。","皎然 同明府章送沈秀才还石门山读书"]]},{"n":"申公告老","d":"","s":"《史记》卷一百二十一〈儒林列传〉","q":[]}],"558":[{"n":"摩挲铜狄","d":"","s":"《后汉书》卷八十二下〈方术列传下·蓟子训〉","q":[]},{"n":"蓟训历家","d":"","s":"《神仙传》卷五《蓟子训》","q":[["壶公谪天，蓟训历家。","李瀚 蒙求"]]},{"n":"蓟子","d":"","s":"《后汉书》卷八十二下《方术传·蓟子训传》","q":[["谬惭知蓟子，真怯笑扬雄。","杜甫 奉寄河南韦尹丈人"],["家家迎蓟子，处处识壶公。","杜甫 寄司马山人十二韵"]]}],"559":[{"n":"张芝","d":"","s":"《后汉书》卷六十五《张奂传》","q":[["君到亦应闲不得，主人草圣复诗仙。","姚合 和王郎中题华州李中丞厅"],["王逸少、张伯英，古来几许浪得名。","李白 草书歌行"]]},{"n":"临池学书","d":"临池：咏练习书法。宋苏轼《石苍舒醉墨堂》：“不须临池更苦学，完取绢素充衾调。”","s":"《后汉书》卷六十五〈皇甫张段列传·张奂〉","q":[["几年出家通宿命，一朝却忆临池圣。","朱逵 怀素上人草书歌"],["别有张芝学，书池幸见临。","李峤 墨"]]},{"n":"练先书","d":"","s":"晋·卫恒《四体书势》","q":[["有练实先书，临池真尽墨。","杜甫 殿中杨监见示张旭草书图"]]}],"560":[{"n":"蚩尤","d":"","s":"《史记》卷一《五帝本纪·黄帝本纪》","q":[["蚩尤终戮辱，胡羯漫猖狂。","杜甫 寄彭州高三十五使君适虢州岑二十七长史参三十韵"],["蚩尤塞寒空，蹴蹋崖谷滑。","杜甫 自京赴奉先县咏怀五百字"]]},{"n":"黄帝战蚩尤","d":"","s":"《山海经·大荒北经》","q":[["云缠风束乱敲磕，黄帝未胜蚩尤强。","杜牧 大雨行"]]},{"n":"涿鹿","d":"","s":"《史记》卷一《五帝本纪·黄帝本纪》","q":[["熊罴驱涿鹿，犀象走昆阳。","韦庄 和郑拾遗秋日感事一百韵"]]}],"561":[{"n":"牧羊儿","d":"金华牧羊儿：指得道成仙，或喻有点石成金之神奇魔力。唐李白《古风》之十七：“金华牧羊儿，乃是紫烟客。”","s":"《太平广记》卷七〈神仙七·黄初平〉","q":[["仙人拥石去，童子驭车来。","李峤 羊"],["金华牧羊儿，乃是紫烟客。","李白 古风"]]},{"n":"松乔","d":"","s":"《搜神记》卷一～","q":[["自有园公紫芝侣，仍追少傅赤松游。","刘禹锡 自左冯归洛下酬乐天兼呈裴令公"],["向夕便思青琐拜，近年寻伴赤松游。","姚合 使两浙赠罗隐"]]},{"n":"金华赤松子","d":"","s":"北魏·郦道元《水经注》卷四十《渐江水》","q":[["松子栖金华，安期入蓬海。此人古之仙，羽化竟何在。","李白 对酒行"],["落帆金华岸，赤松若可招。","李白 送王屋山人魏万还王屋"]]}],"562":[{"n":"褚渊落水","d":"","s":"《南史》卷十九〈谢灵运列传·谢超宗〉","q":[["王俭坠车，褚渊落水。","李瀚 蒙求"]]},{"n":"芙蓉幕","d":"莲幕：美称官署的幕府、幕僚。唐李商隐《自桂林奉使江陵途中感怀寄献尚书》：“下客依莲幕，明公念竹林。”","s":"《南史》卷四十九〈庾杲之列传〉","q":[["弊貂不称芙蓉幕，衰朽仍惭玳瑁簪。","吴仁璧 投谢钱武肃"],["亦知莲府客，夜坐喜同师。","姚合 送无可上人游边"]]},{"n":"萧郎","d":"","s":"《梁书》卷一〈武帝本纪上〉","q":[]}],"563":[{"n":"秦医","d":"","s":"《春秋左传正义》卷二十六〈成公·传十年〉","q":[["炯炯一心在，沉沉二竖婴。","杜甫 八哀诗赠左仆射郑国公严公武"],["雕琢只应劳郢匠，膏肓终恐误秦医。","罗隐 投所思"]]},{"n":"十世宥","d":"","s":"《春秋左传·襄公二十一年》","q":[["苗裔当蒙十世宥，岂谓贻厥无基阯。","韩愈 寄卢仝"]]},{"n":"玉波如渑","d":"","s":"《春秋左传正义》卷四十五〈昭公·传十二年〉","q":[]}]}};
